local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["npc:dendrite-starblaze"] = {n="德迪利特·星焰",s="德迪利特·星焰是一位居住在月光林地神圣的永夜港村庄的暗夜精灵德鲁伊。他效力于塞纳里奥议会，是暗夜精灵和牛头人德鲁伊学徒重要的导师与向导。通过他，修行者们被召唤到圣林，以掌握诸如净化毒素和与自然形态沟通等必要仪式。",h="德迪利特·星焰是一位居住在月光林地神圣的永夜港村庄的暗夜精灵德鲁伊。他效力于塞纳里奥议会，是暗夜精灵和牛头人德鲁伊学徒重要的导师与向导。通过他，修行者们被召唤到圣林，以掌握诸如净化毒素和与自然形态沟通等必要仪式。",kw={"水栖形态","塞纳里奥议会","治疗疾病","德迪利特·星焰","德鲁伊","新的课程","月光林地","暗夜精灵","永夜港"},ang={["class:Druid"]="德迪利特·星焰是你第一次传送至月光林地时的主要向导之一，他会教导你治疗疾病并追求水栖形态。",["race:NightElf"]="德迪利特守护着卡多雷自然之道的传统仪式，并在永夜港欢迎卡多雷新兵加入塞纳里奥教团。",["race:Tauren"]="对于从莫高雷来到月光林地的舒哈鲁德鲁伊来说，德迪利特就是活生生的证明，证明塞纳里奥议会的纽带超越了部落与联盟之间的争端。"},sec={{t="圣所中的向导",b="德迪利特·星焰身处永夜港，代表了塞纳里奥议会中立且永恒的精神。当德鲁伊新手学会调整灵魂以使用“传送：月光林地”时，德迪利特是他们到达后最早迎接他们的人之一。他架起了古代卡多雷传统与新兴牛头人道路之间的桥梁，将所有响应自然召唤的人视为圣所枝叶下的亲族。"},{t="自然的试炼",b="德迪利特的主要职责包括引导德鲁伊学徒深入了解自然的奥秘。他指导新手完成理解毒药与瘟疫所需的试炼，派遣他们去检查受污染的水域并寻找草药治疗方法。他还监督那些引导德鲁伊进行水下试炼的步骤，在授予他们与水栖形态沟通的能力之前，测试他们在水下的耐心与耐力。"}},faq={{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位位于月光林地永夜港的暗夜精灵德鲁伊，也是塞纳里奥议会的导师。他引导成长中的德鲁伊完成重要的职业试炼和训练。",al={"德迪利特·星焰","德迪利特是谁","星焰 月光林地"}},{q="为什么暗夜精灵会训练部落的牛头人？",a="塞纳里奥议会独立于联盟和部落的政治派系之外。在月光林地，暗夜精灵和牛头人遵循古老的兄弟誓言共同研习德鲁伊之道，将尘世的纷争留在山口之外。",al={"为什么德迪利特训练部落","德迪利特 牛头人德鲁伊","跨阵营德鲁伊导师"}},{q="德迪利特·星焰提供哪些任务？",a="德迪利特负责监督几个基础的德鲁伊职业试炼。这些任务包括掌握毒液与疾病治疗，以及通往水栖形态所需沟通能力的试炼。",al={"德迪利特 任务","星焰 任务列表"}},{q="在哪里可以找到德迪利特·星焰？",a="他位于永夜港，该定居点坐落在月光林地的月神湖北岸。",al={"德迪利特 位置","星焰在哪里","德迪利特·星焰 地图"}},{q="年轻的德鲁伊如何第一次见到德迪利特？",a="德鲁伊新手在训练达到十级左右时，会从种族训练师那里学会“传送：月光林地”法术。施放此法术会将他们直接传送到月光林地，德迪利特会在那里等待他们的到来。",al={"如何找到德迪利特","传送至月光林地 任务"}},{q="非德鲁伊冒险者能与他互动吗？",a="非德鲁伊玩家可以访问永夜港并与德迪利特交谈，但他不会为塞纳里奥议会的德鲁伊传统之外的人提供训练、试炼或任务。",al={"非德鲁伊 德迪利特","战士能和星焰说话吗"}}},fx={["3038adca"]={q="德迪利特·星焰想要什么？",a="德迪利特引导初出茅庐的德鲁伊踏上自然与平衡之路。他通过向荒野之灵致敬的试炼——例如与巨熊之灵沟通，以及掌握毒素与水之力——确保所有学徒，无论出身如何，都能学会塞纳里奥议会的职责与古老修行。",al={"德迪利特·星焰的目标","德迪利特想要什么","德迪利特·星焰的动机"}},ef589fff={q="德迪利特·星焰为何在月光林地？",a="月光林地是神圣的中立之地，塞纳里奥议会在此避开尘世的阵营纷争，举行集会。德迪利特驻守永夜港，担任新晋德鲁伊的导师，教授他们成长所必需的基础知识并主持试炼。",al={"德迪利特为何在这里","德迪利特·星焰在月光林地的位置","德迪利特为何在永夜港"}},["7aee8496"]={q="德迪利特·星焰与谁有关联？",a="德迪利特是塞纳里奥议会的使者和导师。他与暗夜精灵和牛头人出身的德鲁伊密切合作，听从荒野之灵的召唤和塞纳留斯的教诲，而非达纳苏斯或部落的政治旗帜。",al={"德迪利特·星焰的阵营","德迪利特·星焰与塞纳里奥议会","德迪利特效忠谁"}}},fp="18,368,27.425.0,18.422.0,26.175.0,40.246.0,42.189.0,38.107.0,54.202.0,44.165.0"}
P.entries["npc:deputy-feldon"] = {n="菲尔顿副队长",s="菲尔顿副队长是赤脊山卫队的一员，驻扎在湖畔镇大桥南侧。他负责守卫通往湖畔镇的主要道路，时刻警惕着逼近城镇周边区域的凶猛豺狼人族群。",h="菲尔顿副队长是赤脊山卫队的一员，驻扎在湖畔镇大桥南侧。他负责守卫通往湖畔镇的主要道路，时刻警惕着逼近城镇周边区域的凶猛豺狼人族群。",kw={"大桥","菲尔顿副队长","菲尔顿","豺狼人","卫兵","湖畔镇","赤脊山"},ang={["faction:Alliance"]="菲尔顿体现了暴风城外围领地那种绝望的处境，当地的卫兵必须恳求路过的勇士协助维持国王的和平。"},sec={{t="紧张的守卫",b="菲尔顿副队长守卫在湖畔镇大桥南端的入口处，他代表了那些人手不足、正努力维持基本贸易和交通路线畅通的城镇卫队。在北方黑石兽人的步步紧逼与南部丘陵横行的豺狼人族群夹击下，像菲尔顿这样的卫兵已经竭尽全力。由于擅离职守会危及城镇的防线，他只能依靠路过的冒险者来清除侵入道路的豺狼人，以免湖畔镇彻底与外界隔绝。"}},faq={{q="菲尔顿副队长是谁？",a="菲尔顿副队长是湖畔镇卫队的一名军官，驻扎在连接城镇与赤脊山南部主要道路的大桥南侧。",al={"菲尔顿","谁是菲尔顿","菲尔顿副队长的职责"}},{q="为什么菲尔顿副队长担心豺狼人？",a="在通往艾尔文森林的道路沿线已经发现了豺狼人的营地。菲尔顿担心它们正准备侵入人类的家园，那样的话，湖畔镇将不再是唯一处于围困之中的城镇，而卫队目前根本无力应对这些威胁。",al={"为什么有豺狼人","菲尔顿与豺狼人问题","侵入的豺狼人"}},{q="为什么菲尔顿不亲自对付豺狼人？",a="湖畔镇卫队严重人手不足，同时面临着兽人和豺狼人的威胁。菲尔顿不能擅离大桥的哨位，否则城镇入口将失去防守。",al={"为什么菲尔顿不战斗","菲尔顿的职责"}},{q="在哪里可以找到菲尔顿副队长？",a="他站在湖畔镇大桥南侧的道路上值勤，监视着通往城镇的南部入口。",al={"菲尔顿的位置","菲尔顿在哪里"}}},fx={["1b9b43bf"]={q="菲尔顿副队长属于哪一方？",a="菲尔顿副队长是忠于联盟的执法官，在湖畔镇守卫和所罗门镇长的管辖下守卫赤脊山。他致力于保护王国的居民，并确保通往镇子的道路免受逼近的威胁。",al={"菲尔顿副队长的阵营","菲尔顿效忠谁","菲尔顿副队长属于联盟吗"}},dc2592f9={q="菲尔顿副队长为何驻守在桥附近？",a="菲尔顿副队长驻守在湖畔镇桥梁以南，监视南面的入口。豺狼人部族逼近镇子，威胁日益严重，他因此巡查道路，确保交通畅通，并招募有能力的旅人遏制入侵，以免桥梁也遭到围困。",al={"菲尔顿为何在这里","菲尔顿副队长为何在此处","菲尔顿在这里做什么"}},["5e39d198"]={q="菲尔顿副队长与谁有关联？",a="菲尔顿听命于所罗门镇长和负责守卫湖畔镇的地方维稳部队。在暴风城没有派来大批援军的情况下，他是守卫赤脊山的稀少地方警卫之一。",al={"菲尔顿副队长的关系","菲尔顿向谁汇报","菲尔顿副队长是治安官吗"}}},fp="13,254,15.511.0,21.159.0,42.254.0,48.202.0,33.125.0"}
P.entries["npc:deputy-rainer"] = {n="瑞尼尔副队长",s="瑞尼尔副队长是一名驻扎在艾尔文森林西界西泉要塞外的暴风城军队军官。他的任务是守住防线，抵御不断侵入的豺狼人部族以及从西部荒野流窜过来的强盗。当正规军队的增援未能抵达时，他负责协调当地的防御工作。",h="瑞尼尔副队长是一名驻扎在艾尔文森林西界西泉要塞外的暴风城军队军官。他的任务是守住防线，抵御不断侵入的豺狼人部族以及从西部荒野流窜过来的强盗。当正规军队的增援未能抵达时，他负责协调当地的防御工作。",kw={"瑞尼尔副队长","艾尔文森林","格里安·斯托曼","霍格","治安官杜汉","河爪","西泉要塞","西部荒野"},ang={["faction:Alliance"]="瑞尼尔副队长代表了暴风城军事触角的边缘地带，让联盟的英雄们直观地了解到当地的要塞在没有正规皇家支援的情况下，必须如何适应才能生存下去。"},sec={{t="守卫西界",b="西泉要塞是艾尔文森林最西端的堡垒，位于通往西部荒野的边界道路旁。由于暴风城的政治瘫痪，导致主力部队被部署在海外或深陷于官僚主义之中，像西泉要塞这样的边境哨所严重缺乏人手。瑞尼尔副队长站在塔外，组织要塞所能集结的一点微薄防御力量。由于当地道路不断受到好战的河爪豺狼人和流窜盗贼的威胁，瑞尼尔被迫依靠过往的旅人和雇佣冒险者，而非王国的正规军团来保障森林小道的安全。"},{t="通往西部荒野之路",b="除了应对河爪部族的直接威胁并警告旅人提防臭名昭著的豺狼人首领霍格外，瑞尼尔还是与河对岸那片多灾多难的土地之间的重要联络枢纽。他深知困扰艾尔文森林边界的混乱起源于西部的法外农田，因此他指引有能力的志愿者越过边界进入西部荒野，并将他们引向格里安·斯托曼和苦苦挣扎的人民民兵团。"}},faq={{q="瑞尼尔副队长是谁？",a="瑞尼尔副队长是一名驻扎在艾尔文森林西缘西泉要塞的暴风城军队军官。他负责监管当地的道路安全，并雇佣冒险者来对抗周边的威胁。",al={"瑞尼尔 艾尔文","瑞尼尔是谁","西泉要塞军官"}},{q="为什么西泉要塞人手不足？",a="暴风城军队的大部分兵力被部署在其他地方，而首都的政治混乱使得正规增援部队无法到达偏远地区。因此，闪金镇的治安官杜汉必须依靠独立的冒险者来协助瑞尼尔。",al={"为什么西泉要塞没有守卫","为什么要塞陷入困境","西泉要塞需要帮助"}},{q="瑞尼尔试图应对哪些威胁？",a="瑞尼尔的主要工作重点是遏制盘踞在要塞南面森林里的河爪豺狼人部族、流窜的盗贼，以及在边境线上掠夺旅人的臭名昭著的豺狼人首领霍格。",al={"西泉要塞附近有什么敌人","河爪豺狼人 西泉要塞","西泉要塞豺狼人"}},{q="在清理了豺狼人之后，瑞尼尔会将冒险者派往何处？",a="一旦要塞附近的豺狼人威胁被压制，瑞尼尔就会指引经验丰富的冒险者越过西界进入西部荒野，去协助哨兵岭的格里安·斯托曼和人民民兵团。",al={"找过瑞尼尔后去哪","瑞尼尔 任务 西部荒野","西泉要塞之后"}}},fp="13,204,26.474.0,20.348.0,21.179.0,38.229.0,41.178.0,61.194.0"}
P.entries["npc:devrak"] = {n="迪弗拉克",s="迪弗拉克是一位兽人驭风者训练师，驻扎在贫瘠之地的十字路口。作为卡利姆多中部主要的空中枢纽，他负责监管部落的飞龙网络，运送物资和信使，往返于杜隆塔尔、莫高雷和边境哨所之间。他还确保关键的后勤物资（如野味和处理过的兽皮）能够顺利运抵部落的各个主城。",h="迪弗拉克是一位兽人驭风者训练师，驻扎在贫瘠之地的十字路口。作为卡利姆多中部主要的空中枢纽，他负责监管部落的飞龙网络，运送物资和信使，往返于杜隆塔尔、莫高雷和边境哨所之间。他还确保关键的后勤物资（如野味和处理过的兽皮）能够...",kw={"贫瘠之地","十字路口","迪弗拉克","飞行管理员","奥格瑞玛","雷霆崖","驭风者","飞龙"},ang={["faction:Horde"]="对于任何在卡利姆多游历的部落冒险者来说，迪弗拉克都是不可或缺的盟友，他是连接兽人、巨魔和牛头人领地的中心枢纽。",["race:Orc"]="迪弗拉克驻扎在贫瘠之地干燥的中心地带，展示了兽人与卡利姆多驭风者合作的才能，通过与这些凶猛的野兽建立联系，确保了部落的空中统治力。"},sec={{t="十字路口栖枝守护者",b="迪弗拉克位于卡利姆多主要贸易路线的交汇处，他照料着让部落在广袤大地间保持联络的飞龙。十字路口暴露在灼热的阳光下，极易受到野猪人、半人马以及联盟斥候的袭击，因此快速的空中运输至关重要。迪弗拉克既要应对经验丰富的旅行者，也要接待缺乏经验的信使，为骑手们配备训练有素的驭风者，以便他们跨越草原，抵达莫高雷的山巅或杜隆塔尔的石质峡谷。"},{t="大酋长与各族首领的物资",b="除了运送旅客，迪弗拉克在边境后勤中也发挥着至关重要的作用。贫瘠之地的猎人们收获了大量的肉类和毛皮，迪弗拉克帮助将这些物资直接运送到奥格瑞玛的灶火和雷霆崖的制皮匠手中。通过向大陆各地的飞行管理员介绍初出茅庐的信使，他巩固了这条为部落腹地提供补给的空中生命线。"},{t="致命的栖枝",b="处于争议边境地区的飞行管理员绝不能毫无自卫能力。迪弗拉克绝不仅仅是一个简单的野兽饲养员；当十字路口遭到袭击时，他会召唤狂暴的飞龙，用剧毒的毒刺和利爪撕碎敌对的入侵者，这让他的栖枝成为了任何胆敢攻击该定居点的人眼中的危险目标。"}},faq={{q="迪弗拉克在十字路口扮演什么角色？",a="迪弗拉克是驻扎在贫瘠之地十字路口的部落飞行管理员。他负责照料哨所的驭风者，提供前往卡利姆多各地定居点的航线，并协调信使、士兵和重要贸易物资的运输。",al={"迪弗拉克是谁","迪弗拉克做什么","迪弗拉克的工作","十字路口飞行管理员"}},{q="迪弗拉克能带我去哪里？",a="从他在十字路口的栖枝出发，迪弗拉克连接着奥格瑞玛和雷霆崖等主要主城，以及灰谷、石爪山脉、尘泥沼泽、千针石林和南部边境的边境哨所，前提是你必须先与那些飞行管理员交谈过。",al={"迪弗拉克的航线","我能从十字路口飞往哪里","十字路口飞行路线"}},{q="迪弗拉克提供什么任务？",a="迪弗拉克协助处理一些信使任务，教会年轻的部落冒险者如何使用飞行网络，包括将新鲜肉类送往奥格瑞玛的Gryshka，并将成捆的兽皮送到雷霆崖。",al={"迪弗拉克的任务","十字路口飞行任务"}},{q="如果十字路口遭到袭击，迪弗拉克如何自卫？",a="迪弗拉克受到他栖枝的守卫。如果遭到联盟突袭者或敌对野兽的攻击，他可以召唤凶猛的狂暴飞龙协助他战斗，用尖牙利爪将攻击者驱逐。",al={"迪弗拉克会战斗吗","击杀迪弗拉克","迪弗拉克的防御"}},{q="为什么在十字路口设置飞行管理员如此重要？",a="贫瘠之地是卡利姆多中部的连接脊梁。由于十字路口连接着杜隆塔尔、莫高雷、灰谷和石爪山脉，迪弗拉克的栖枝使得部落能够快速重新部署兵力并协调物资，而无需依赖长达数日的步行旅程。",al={"为什么十字路口飞行管理员很重要","十字路口的地理重要性"}},{q="迪弗拉克照料什么生物？",a="迪弗拉克管理驭风者，也被称为飞龙。这些原产于卡利姆多山峰和台地的龙类带翼掠食者，被部落驯服，成为跨越崎岖地形的可靠飞行坐骑。",al={"迪弗拉克有什么坐骑","十字路口坐骑"}}},fx={a0427f27={q="迪弗拉克属于哪一方？",a="迪弗拉克是部落的骄傲成员。他驻守在卡利姆多腹地的十字路口，奉酋长之命维持兽人和牛头人领地之间重要的空中补给航线畅通，在贫瘠之地及更远地区运送信使、补给和战士。",al={"迪弗拉克属于部落吗","迪弗拉克的阵营","迪弗拉克效忠谁"}},bd507e24={q="迪弗拉克想要什么？",a="迪弗拉克专注于维持部落在卡利姆多中部的重要补给线。他依靠旅人将鞣制兽皮和腌肉等必需品运往奥格瑞玛和雷霆崖等主要主城，确保聚居地的双足飞龙骑手随时待命，并为战争提供充足支援。",al={"迪弗拉克的目标是什么","迪弗拉克的目的","迪弗拉克需要什么"}}},fp="6,381,31.508.0,43.382.0,14.350.0,40.258.0,24.282.0,30.189.0,61.189.0,60.262.0,34.211.0"}
P.entries["npc:dextren-ward"] = {n="迪克斯特·瓦德",s="迪克斯特·瓦德是一名臭名昭著的罪犯和掘墓者，被关押在暴风城监狱内。在被捕之前，他通过挖掘暮色森林乌鸦岭墓地的尸体并将其交给死灵法师Morbent Fel来牟取暴利。现在，他身陷监狱血腥暴乱之中，而夜色镇议会仍对他下达了死刑判决。",h="迪克斯特·瓦德是一名臭名昭著的罪犯和掘墓者，被关押在暴风城监狱内。在被捕之前，他通过挖掘暮色森林乌鸦岭墓地的尸体并将其交给死灵法师Morbent...",kw={"议员米尔斯迪普","犯罪与惩罚","迪克斯特·瓦德","暮色森林","掘墓者","morbent fel","乌鸦岭墓地","暴风城","监狱"},ang={["class:Paladin"]="瓦德与死灵法师勾结提供新鲜尸体的行为，是对圣光的神圣性以及逝者安宁的令人憎恶的亵渎。",["class:Priest"]="对乌鸦岭神圣墓地的亵渎，使得对瓦德的审判成为道德和精神偿还的必然要求。",["faction:Alliance"]="对于协助夜色镇的联盟勇士来说，终结迪克斯特·瓦德是为那些受到亵渎的暮色森林家庭伸张正义的一种行为，也是收复暴乱监狱的一项重要任务。"},sec={{t="暮色森林的盗墓行径",b="在被锁链困于暴风城街道之下前，迪克斯特·瓦德在暮色森林那迷雾笼罩的树林中进行着一场阴森而又赚取暴利的买卖。乌鸦岭墓地本已是一个充满悲伤和日益恐怖的地方，但瓦德却将这片墓地视为他的私人采石场。瓦德不仅搜寻死者留下的饰品和传家宝，他还从事尸体交易，挖掘新鲜的坟墓来供应当地的黑暗信徒。"},{t="死灵法师的走卒",b="瓦德的主要顾客是Morbent Fel，这位死灵法师的黑暗仪式困扰着暮色森林，并壮大了亡灵的队伍。通过向Fel提供尸体，瓦德积极地助长了笼罩夜色镇的恐怖氛围。尽管最终被暴风城的当局抓获并拖入监狱，但他的罪行引起了夜色镇人民的不共戴天之仇，导致议员米尔斯迪普要求以瓦德的手作为伸张正义的证明。"},{t="监狱中的混乱",b="当监狱内爆发全面叛乱时，瓦德并非被盟友所救，而是从牢房中被释放，并加入了封锁的地下城内的混乱之中。他全副武装且凶残无比，占据了监狱的一角，并利用恐怖手段驱赶闯入者，这使他成为联盟军队在恢复秩序时力求消灭的优先目标之一。"}},faq={{q="迪克斯特·瓦德是谁？",a="迪克斯特·瓦德是一名被关押在暴风城监狱中的臭名昭著的罪犯。他是一名人类精英囚犯，负责在暮色森林中劫掠死者，以供奉黑暗仪式。",al={"迪克斯特·瓦德是谁","迪克斯特·瓦德背景故事","监狱迪克斯特"}},{q="为什么迪克斯特·瓦德会被关在监狱里？",a="瓦德因在暮色森林的乌鸦岭墓地盗墓而被捕入狱。他不仅窃取财物，还挖掘新鲜尸体直接卖给死灵法师Morbent Fel。",al={"他为什么被捕","迪克斯特·瓦德的罪行","迪克斯特做了什么"}},{q="谁想要迪克斯特·瓦德死？",a="夜色镇的议员米尔斯迪普想要瓦德死。米尔斯迪普寻求为亵渎暮色森林的坟墓进行报复，并要求得到瓦德被切下的手作为他死亡的证明。",al={"谁想要迪克斯特死","迪克斯特·瓦德赏金","犯罪与惩罚任务发布者"}},{q="瓦德与Morbent Fel有什么关系？",a="瓦德充当了Morbent Fel的尸体供应商。通过挖掘乌鸦岭墓地新埋葬的死者，瓦德为Fel的死灵实验和亡灵制造提供了所需的原材料。",al={"与morbent fel的联系","迪克斯特·瓦德与morbent fel","谁购买了尸体"}},{q="在哪里可以找到迪克斯特·瓦德？",a="他位于暴风城监狱内，这是位于暴风城运河中的高度安全监狱。在监狱持续的叛乱期间，他潜伏在其中一个囚禁区域内。",al={"迪克斯特·瓦德位置","迪克斯特·瓦德在哪里","在哪里找到迪克斯特"}},{q="为什么任务需要迪克斯特的手？",a="议员米尔斯迪普明确要求得到瓦德冰冷、死亡的手，作为无可辩驳的实物证据，证明这个盗墓贼再也不能挖掘暮色森林的坟墓或通过死灵术牟利。",al={"为什么要切断他的手","迪克斯特·瓦德的手","迪克斯特死亡证明"}}},fx={["87b921a6"]={q="迪克斯特·瓦德站在哪一边？",a="瓦德只顾自己，尽管他曾与祸害暮色森林的黑暗势力有所勾结。他并未像迪菲亚潜行者那样为某个有组织的派系效力，而是以罪犯的身份伺机牟利，与亡灵法师莫本特·费尔达成肮脏交易，将乌鸦岭墓地新挖出的尸体供给对方。",al={"迪克斯特·瓦德的派系","迪克斯特·瓦德为谁效力","迪克斯特·瓦德是迪菲亚成员吗"}},["371c7358"]={q="为什么迪克斯特·瓦德令人畏惧？",a="除了盗墓这门令人毛骨悚然的营生，瓦德还以能让面对他的人心生恐慌而闻名。在监狱狭窄而暴力的走廊里，他制造超自然恐惧的本领使他格外致命：逃跑的斗士很快就会撞上其他暴乱囚犯的刀刃。",al={"迪克斯特·瓦德为何危险","迪克斯特·瓦德令人畏惧","迪克斯特·瓦德危险在哪里"}}},fp="12,354,25.431.0,23.452.0,21.368.0,20.169.0,36.190.0,28.175.0,41.206.0,32.182.0,42.186.0"}
P.entries["npc:dirania-silvershine"] = {n="迪兰妮亚·月光",s="迪兰妮亚·月光是一位居住在泰达希尔幽影谷的暗夜精灵。她忠诚而敏锐，守护着这片宁静的林地，每当同伴埃沃隆因鲁莽的行为陷入困境时，她都会照看他。",h="迪兰妮亚·月光是一位居住在泰达希尔幽影谷的暗夜精灵。她忠诚而敏锐，守护着这片宁静的林地，每当同伴埃沃隆因鲁莽的行为陷入困境时，她都会照看他。",kw={"解药","迪兰妮亚","埃沃隆","幽影谷","月光","泰达希尔","网木"},ang={["race:NightElf"]="对于步入幽影谷的年轻暗夜精灵来说，迪兰妮亚是一个早期的提醒，让他们意识到友谊的羁绊，以及即便在世界之树最新的避难所中也依然潜伏着的危险。"},sec={{t="幽影谷的守望者",b="迪兰妮亚站在幽影谷宁静的树冠下，这是一片与世隔绝的山谷，年轻的暗夜精灵们在此开始他们为卡利姆多和联盟服务的历程。当许多人关注着兽穴和圣地中广泛的精神职责时，迪兰妮亚却时刻挂念着她身边的人，警惕着即便在泰达希尔中心地带也会暗中滋生的危险。"},{t="朋友的危机",b="迪兰妮亚目前最关心的是她的同伴埃沃隆。埃沃隆在面对游荡在山谷中的有毒林地生物时总是过于急躁和粗心，常常惹上麻烦。当他不幸被当地的网木蜘蛛咬伤中毒时，迪兰妮亚便主动寻求援手，收集材料并准备解药，以免毒素造成永久性的伤害。"}},faq={{q="迪兰妮亚·月光是谁？",a="迪兰妮亚·月光是一位出现在泰达希尔幽影谷的暗夜精灵。她是一位任务发放者，主要关心在她的朋友埃沃隆招惹了当地有毒野生生物后对他进行营救和治疗。",al={"迪兰妮亚","迪兰妮亚是谁","迪兰妮亚·月光背景故事"}},{q="我在哪里可以找到迪兰妮亚·月光？",a="迪兰妮亚位于幽影谷内，这是泰达希尔内的新手山谷，距离奥达希尔附近的主干道不远。",al={"迪兰妮亚位置","迪兰妮亚在哪里","寻找迪兰妮亚·月光"}},{q="迪兰妮亚和埃沃隆是什么关系？",a="迪兰妮亚和埃沃隆是亲密的朋友。迪兰妮亚是两人中更明智、更警觉的一位，每当埃沃隆因愚蠢行径而遭受当地动物的毒咬时，她都会挺身而出，安排制作解药。",al={"迪兰妮亚和埃沃隆有关吗","埃沃隆和迪兰妮亚","迪兰妮亚的朋友"}},{q="迪兰妮亚提供什么任务？",a="她提供以帮助其同伴为中心的相关任务，最著名的是“患难之交”和“埃沃隆的解药”，要求冒险者搜集材料来调制解救埃沃隆所中蜘蛛毒的药物。",al={"迪兰妮亚的任务","迪兰妮亚·月光的任务","埃沃隆任务"}},{q="为什么迪兰妮亚会担心幽影谷里的蜘蛛？",a="栖息在幽影谷树冠间的网木蜘蛛带有剧毒。虽然经验丰富的哨兵可以对付它们，但像埃沃隆这样的精灵新手往往低估了危险，并面临被咬伤导致中毒的风险。",al={"幽影谷蜘蛛","为什么泰达希尔有蜘蛛","网木危险"}},{q="迪兰妮亚属于任何正式的组织或派系吗？",a="迪兰妮亚是一位居住在泰达希尔平静生活的联盟暗夜精灵。她并未被描述为 The Sisterhood of Elune 或塞纳里奥议会的活跃成员，而是一位关心同胞的平民。",al={"迪兰妮亚所属阵营","迪兰妮亚是德鲁伊吗","迪兰妮亚是哨兵吗"}}},fx={f156932e={q="迪兰妮亚·月光想要什么？",a="迪兰妮亚急切地想为好友埃沃隆寻求帮助。他前往幽影谷后遭到当地的网木蜘蛛严重毒伤，已经无法行动。她需要有人尽快在林间空地各处收集所需材料，配制解毒剂，救他一命。",al={"迪兰妮亚·月光的目标","迪兰妮亚需要什么","迪兰妮亚·月光想要什么"}},e30a1bf8={q="迪兰妮亚·月光为什么在这里？",a="迪兰妮亚住在幽影谷，与其他暗夜精灵一同栖居在奥达希尔遮蔽的枝干间。好友埃沃隆在附近中了蜘蛛毒后，她便焦急地留守此地，等待有能力的旅人前来相助。",al={"迪兰妮亚为何在幽影谷","迪兰妮亚·月光在此的原因","迪兰妮亚为何在这里"}}},fp="19,222,23.348.0,16.388.0,27.209.0,37.119.0,42.211.0,31.194.0,51.221.0,51.217.0"}
P.entries["npc:dirge-quikcleave"] = {n="迪尔格·奎克里弗",s="迪尔格·奎克里弗是一位地精烹饪大师和商人，在加基森旅店中坐镇。他以极富创意的菜肴闻名艾泽拉斯，并指导那些寻求掌握工匠级烹饪的资深厨师。",h="迪尔格·奎克里弗是一位地精烹饪大师和商人，在加基森旅店中坐镇。他以极富创意的菜肴闻名艾泽拉斯，并指导那些寻求掌握工匠级烹饪的资深厨师。",kw={"工匠级烹饪","蚌肉大餐","烹饪训练师","迪尔格·奎克里弗","加基森","地精厨师","塔纳利斯"},ang={["profession:Cooking"]="迪尔格·奎克里弗是雄心勃勃的厨师们的首选工匠导师，在授予他们大师地位之前，会用他招牌的蚌肉大餐食谱来测试他们的技能。",["race:Orc"]="奥格瑞玛的训练师会直接指引有抱负的部落美食家前往塔纳利斯沙漠，去寻求迪尔格的烹饪指导。"},sec={{t="剁肉刀大师",b="迪尔格·奎克里弗居住在尘土飞扬的沙漠前哨站加基森，为穿过塔纳利斯沙地的干渴旅人提供饮品和肉食。尽管是在边境酒馆里经营，他仍自称是艾泽拉斯最伟大的在世烹饪艺术家。世界各地的城市烹饪训练师在学生学完基础课程后，都会将最优秀的学生指引到迪尔格那里。他的烹饪造诣以需要极其罕见的食材而闻名——从制作蚌肉大餐所需的巨型蚌肉和蛋，到遥远海岸的奇异野兽。"},{t="奇异风味与隐秘交易",b="在他那美食家的虚张声势之下，迪尔格保留着沙漠中任何地精所特有的商业头脑。他与卡利姆多各地的古怪人物保持着联系，并对危险的烹饪冒险有着敏锐的眼光。那些愿意获取凶猛野兽肉块的人，比如菲拉斯的恐怖之岛上原生的怪物奇美拉，会发现迪尔格能配制出足以支撑勇士在危险旅途中生存的丰盛食谱——前提是他们不要对他的私人交易问得太多。"}},faq={{q="迪尔格·奎克里弗是谁？",a="迪尔格·奎克里弗是一位地精烹饪大师兼供应商，位于塔纳利斯加基森的旅店中。他是艾泽拉斯最出色的烹饪从业者之一，教导有抱负的厨师如何将手艺磨练至工匠大师水平。",al={"迪尔格·奎克里弗背景故事","迪尔格是谁","加基森厨师"}},{q="在哪里可以找到迪尔格·奎克里弗？",a="他位于塔纳利斯北部沙丘中，热砂港的繁荣城镇加基森的酒馆内。",al={"迪尔格位置","迪尔格·奎克里弗在哪里","迪尔格旅店"}},{q="为什么烹饪训练师会把冒险者送去见他？",a="主城的烹饪训练师只能将学徒的技能提升到一定程度。一旦厨师达到专家级门槛，训练师就会通过任务“去加基森吧！”将他们送到加基森找迪尔格，以证明自己的实力并解锁工匠级烹饪。",al={"为什么要拜访迪尔格","工匠级烹饪任务","去加基森吧"}},{q="迪尔格以哪些菜肴而闻名？",a="迪尔格因他的蚌肉大餐而闻名，这是一种由巨型蚌肉和蛋制成的美味煎蛋卷，此外还有丰盛的狼排和他那强劲的迪尔格的超美味奇美拉肉片。",al={"迪尔格食谱","蚌肉大餐","迪尔格烹饪什么"}}},fx={["882c7cf6"]={q="迪尔格·奎克里弗站在哪一边？",a="迪尔格·奎克里弗完全保持中立，在热砂港位于沙漠中的前哨加基森经营。他和大多数贸易财团的地精一样，只为出价合适的人效力，乐于分享自己的烹饪技艺，也向联盟和部落的顾客售卖食物。",al={"迪尔格·奎克里弗的派系","迪尔格属于部落还是联盟","迪尔格·奎克里弗为谁效力"}},["6a938a01"]={q="迪尔格·奎克里弗想要什么？",a="迪尔格对极致而奇异的烹饪满怀热情。他寻觅稀有而特别的肉类，以及来自世界危险角落的新鲜食材，用来制作他闻名遐迩的蛤蜊杂烩和奇美拉肉排等佳肴，随时准备将大胆的采集成果化作烹饪杰作。",al={"迪尔格·奎克里弗的目标","迪尔格·奎克里弗需要什么","迪尔格为何想要食材"}},["97163837"]={q="迪尔格·奎克里弗为什么在加基森？",a="在加基森繁忙的旅店经营，让迪尔格身处勇敢的探险者、猎杀怪物的人和沙漠旅客往来的重要路口。这里为这位地精厨师带来源源不断的顾客，他们需要丰盛的补给，也有大胆的厨师前来学习他的独门技艺。",al={"迪尔格为何在加基森","迪尔格·奎克里弗为何在塔纳利斯","迪尔格为何在这里"}},["60da7b2e"]={q="迪尔格·奎克里弗与谁有联系？",a="迪尔格在加基森的热砂港地精中安家，为各行各业的旅人和沙漠行者服务。他也与纳瑞安这类古怪人物保持联系；需要制作别致的上等菜肴时，纳瑞安知道该找谁。",al={"迪尔格·奎克里弗的熟人","迪尔格认识谁","迪尔格的人脉"}}},fp="16,214,21.555.0,31.506.0,24.244.0,36.115.0,48.245.0,32.177.0"}
P.entries["npc:doan-karhan"] = {n="杜安·卡汉",s="杜安·卡汉是一位居住在南贫瘠之地的人类学者和黑魔法修行者。他一生致力于研究燃烧军团的恶魔神器，特别是神秘的索兰鲁克宝珠。",h="杜安·卡汉是一位居住在南贫瘠之地的人类学者和黑魔法修行者。他一生致力于研究燃烧军团的恶魔神器，特别是神秘的索兰鲁克宝珠。",kw={"贫瘠之地","杜安·卡汉","索兰鲁克宝珠","扎尔甘宝珠","术士"},ang={["class:Warlock"]="杜安·卡汉对于经验丰富的术士来说是宝贵的资源，他掌握着发现、修复和驾驭传奇恶魔宝珠所需的奥术知识。",["faction:Alliance"]="尽管是人类，但杜安在远离暴风城或塞拉摩的地方活动，比起大联盟的种种约束，他更偏爱在卡利姆多的中心地带过着孤独的流亡生活。"},sec={{t="贫瘠之地的隐士",b="杜安·卡汉隐居在南贫瘠之地荒野大草原上一个僻静的营地里，远离联盟的文明堡垒。他之所以退隐荒野，并非是为了寻求普通的独处，而是为了不受干扰地研究危险的恶魔遗物。杜安掌握着关于强大的邪能容器的深奥知识，他拥有一枚扎尔甘宝珠，并对传说中的索兰鲁克宝珠痴迷不已。术士在钻研神器制作和黑暗仪式时，常会向他寻求指引。"}},faq={{q="杜安·卡汉在哪里？",a="杜安·卡汉的营地位于南贫瘠之地，隐藏在陶拉祖营地和大路以东的区域。他独自居住在一片容易被忽略的小空地上。",al={"杜安·卡汉位置","杜安·卡汉在哪里","杜安·卡汉 南贫瘠之地"}},{q="为什么会有人类独自住在贫瘠之地？",a="杜安·卡汉选择在充满敌意的荒野中流亡，是为了研究燃烧军团的魔法遗物。这种对恶魔宝珠的黑暗研究在联盟的文明领地内是被禁止或受到严厉审查的。",al={"他为什么在这里","为什么贫瘠之地会有人类","杜安·卡汉背景故事"}},{q="什么是索兰鲁克宝珠？",a="索兰鲁克宝珠是一件古老而强大的军团遗物，蕴含着黑暗力量。杜安·卡汉在了解其构造以及类似的扎尔甘宝珠方面拥有渊博的知识，并指导那些试图重铸它的术士。",al={"索兰鲁克宝珠","什么是索兰鲁克宝珠"}}},fp="11,236,25.487.0,29.160.0,43.214.0,29.224.0"}
P.entries["npc:doctor-gregory-victor"] = {n="格里高利·维克托医生",s="格里高利·维克托医生是一位驻扎在阿拉希高地部落据点落锤镇的被遗忘者外科医生。作为部落首屈一指的创伤医师，他负责评估那些寻求掌握高级分诊技术和战场急救术的候补医护人员。他那冷酷、冷静的高效率使身处激烈地区冲突的前线战士们得以保全性命。",h="格里高利·维克托医生是一位驻扎在阿拉希高地部落据点落锤镇的被遗忘者外科医生。作为部落首屈一指的创伤医师，他负责评估那些寻求掌握高级分诊技术和战场急救术的候补医护人员。他那冷酷、冷静的高效率使身处激烈地区冲突的前线战士们得...",kw={"阿拉希高地","格里高利·维克托医生","急救","格里高利·维克托","落锤镇","部落创伤","外科医生","分诊"},ang={["faction:Horde"]="维克托医生在部落最危险的据点之一提供了至关重要的战地医疗服务，确保阿拉希前线的战士们能恢复战斗状态。",["race:Undead"]="与皇家药剂师协会的有毒混合剂不同，维克托医生展示了被遗忘者对传统的凡人解剖学和修复外科手术的精通。"},sec={{t="落锤镇的外科医生",b="虽然许多人对被遗忘者的药剂师持怀疑态度，但格里高利·维克托医生通过实用的战场外科手术，而非受污染的炼金术为部落服务。他驻扎在竞争激烈的阿拉希高地深处的落锤镇，为那些被辛迪加匪徒、巨石食人魔和联盟军队重创的士兵进行手术。他的岗位同时也是部落战地医护人员的主要试炼场，要求其在巨大压力下保持冷酷的高效率，并优先处理危重病人。"}},faq={{q="格里高利·维克托医生是谁？",a="格里高利·维克托医生是一位驻扎在阿拉希高地落锤镇的被遗忘者医师。他是部落的首席创伤外科医生，负责监督分诊工作并指导高级战地医护人员。",al={"维克托医生","格里高利·维克托","格里高利·维克托是谁"}},{q="我在哪里可以找到格里高利·维克托医生？",a="他位于阿拉希高地东北部的落锤镇要塞内。",al={"格里高利·维克托位置","维克托在哪里","维克托医生在哪"}},{q="他在部落中扮演什么角色？",a="维克托医生通过严格的考核来测试有潜力的战地医护人员的分诊能力，教导他们如何稳定濒死者的伤情，并为前线战斗制作高级布绷带。",al={"格里高利·维克托做什么","格里高利·维克托急救","部落创伤医生"}},{q="他的联盟对应人物是谁？",a="古斯塔夫·范沃森医生，驻扎在尘泥沼泽的塞拉摩岛，负责联盟的高级创伤和分诊训练。",al={"维克托医生的联盟对应者","联盟分诊医生"}}},fx={d46fa605={q="格里高利·维克托医生站在哪一边？",a="格里高利·维克托医生忠于部落和被遗忘者。他驻扎在阿拉希高地的落锤镇，是一位经验丰富的外科医生，负责救治本阵营的伤员，并向愿意学习的人传授先进的战地急救知识。",al={"格里高利·维克托医生属于什么阵营","维克托医生是部落成员吗","维克托医生的效忠对象"}},["5e053b25"]={q="格里高利·维克托医生想要什么？",a="维克托医生致力于战地医疗和外科手术。他需要能够在高压环境下处理伤员分诊的战地医护人员，并通过考核有志成为治疗者的人，确保他们能合理安排治疗顺序，在战争混乱中挽救生命。",al={"维克托医生想要什么","格里高利·维克托医生的目标","维克托在做什么"}},["3e1305a9"]={q="格里高利·维克托医生为什么在这里？",a="维克托医生驻扎在落锤镇，支援部落在争夺激烈的阿拉希高地的前线。联盟的袭击和当地威胁不断涌现，因此需要一位经验丰富的创伤外科医生来保障士兵的性命。",al={"格里高利·维克托为何在这里","维克托医生为何在落锤镇","维克托在此的原因"}}},fp="21,369,21.487.0,29.225.0,39.93.0,37.191.0,32.136.0"}
P.entries["npc:doctor-gustaf-vanhowzen"] = {n="古斯塔夫·范沃森医生",s="古斯塔夫·范沃森医生是塞拉摩岛联盟创伤中心的外科医生兼首席医师。他驻扎在塞拉摩堡垒内，负责培训岛上的治疗者，并对希望掌握最高级战场分诊和绷带技术的医护人员进行考核。",h="古斯塔夫·范沃森医生是塞拉摩岛联盟创伤中心的外科医生兼首席医师。他驻扎在塞拉摩堡垒内，负责培训岛上的治疗者，并对希望掌握最高级战场分诊和绷带技术的医护人员进行考核。",kw={"联盟创伤","专家级急救","急救","塞拉摩堡垒","古斯塔夫·范沃森","塞拉摩","分诊","范沃森"},ang={["faction:Alliance"]="每一位渴望掌握战场外科手术的联盟医护人员都必须前往塞拉摩，在范沃森医生的注视下证明他们的分诊技能。"},sec={{t="塞拉摩首席医师",b="古斯塔夫·范沃森医生位于塞拉摩岛塞拉摩堡垒的底层，负责监管吉安娜·普罗德摩尔部队的医疗护理工作，并训练前哨站的前线治疗者。面对尘泥沼泽恶劣的环境，范沃森坚持严苛的战场能力标准，亲自对经验丰富的医护人员进行紧张的分诊测试，以确保他们能在巨大的压力下优先处理致命伤。"}},faq={{q="在哪里可以找到古斯塔夫·范沃森医生？",a="范沃森医生驻扎在尘泥沼泽塞拉摩岛上的主堡垒——塞拉摩堡垒的底层。",al={"范沃森位置","古斯塔夫·范沃森在哪里","古斯塔夫·范沃森地点"}},{q="范沃森在联盟中担任什么职务？",a="他是联盟创伤中心的首席医师，也是塞拉摩的主要外科医生。除了监管驻军的医疗室外，他还担任资深联盟战场医护人员的专家级急救训练师。",al={"范沃森做什么","范沃森职责","范沃森医生是谁"}},{q="范沃森医生能教玩家什么？",a="他提供专家级急救分诊考核，使熟练的医护人员能够提高技能上限，并指导合格的从业者制作高级绷带，例如重丝纹布绷带和符文布绷带。",al={"我能从范沃森那里学到什么","范沃森训练","范沃森的急救"}},{q="部落有与范沃森医生对应的训练师吗？",a="有的。部落对应的创伤专家是格里高利·维克托医生，他在阿拉希高地的落锤镇训练战场医护人员并进行分诊考试。",al={"部落分诊训练师","部落范沃森对应人物","部落急救大师是谁"}}},fx={["5f514c39"]={q="古斯塔夫·范沃森医生是谁？",a="古斯塔夫·范沃森医生是联盟创伤医疗队的首席医师，也是驻扎在塞拉摩岛的创伤外科专家。他以精湛的战场医疗技术闻名于整个联盟，负责监督塞拉摩治疗者的训练，并向战地医护人员传授先进的分诊技巧。",al={"范沃森是谁","古斯塔夫·范沃森","古斯塔夫·范沃森医生是谁"}},d768860b={q="古斯塔夫·范沃森医生站在哪一边？",a="范沃森医生坚定地效忠联盟。他领导着名为联盟创伤医疗队的医疗队伍，在吉安娜·普罗德摩尔的麾下效力，通过严格的战地医疗保障士兵和前线冒险者的生命。",al={"范沃森的阵营","范沃森是联盟成员吗","古斯塔夫·范沃森医生效忠谁"}},c346cbcd={q="古斯塔夫·范沃森医生想要什么？",a="范沃森医生希望联盟军队始终保持最高水平的创伤救治标准。在战场上，犹豫就会丧命，因此他要考核并指导有能力的战地医护人员掌握分诊方法，以便在极端压力下处理严重的战斗伤患。",al={"范沃森想要什么","范沃森的动机","范沃森医生的目标"}},["12e0bbc2"]={q="古斯塔夫·范沃森医生为什么在这里？",a="范沃森医生驻扎在塞拉摩岛的塞拉摩堡垒，负责照料这座军事要塞的伤员，并训练当地驻军的治疗者。他在此考核途经卡利姆多、精通急救的创伤医疗候选人。",al={"范沃森为何在塞拉摩","范沃森医生为何在这里","范沃森在哪里工作"}},["9903e76f"]={q="古斯塔夫·范沃森医生与谁有联系？",a="范沃森医生为塞拉摩岛的联盟驻军效力，听命于吉安娜·普罗德摩尔在此地的军队。他直接与联盟军医协调，并指挥联盟创伤医疗部门。",al={"范沃森的关系","范沃森为谁效力","古斯塔夫·范沃森医生的关系"}}},fp="23,268,28.425.0,43.136.0,48.222.0,41.216.0,54.167.0"}
P.entries["npc:donova-snowden"] = {n="多诺瓦·雪山",s="多诺瓦·雪山是一位无畏的矮人研究员，她在冬泉谷冰火温泉附近的温泉水畔扎营。尽管环境极度寒冷且野生动物充满敌意，她仍坚持研究该地区奇特的地热活动，并时刻监控着日益腐化的冬泉熊怪。",h="多诺瓦·雪山是一位无畏的矮人研究员，她在冬泉谷冰火温泉附近的温泉水畔扎营。尽管环境极度寒冷且野生动物充满敌意，她仍坚持研究该地区奇特的地热活动，并时刻监控着日益腐化的冬泉熊怪。",kw={"多诺瓦·雪山","火酒","冰火温泉","熊怪","研究员","冬泉","冬泉谷"},ang={["faction:Horde"]="尽管有着矮人的血统，但多诺瓦愿意忽略阵营立场，招募有能力的侦察兵来对抗冬泉谷的野生猛兽和腐化的熊怪。",["race:Dwarf"]="发现一位矮人同胞独自在冰封的山峰上冒险，让人感到一种亲切感，这展现了矮人那种远离卡兹莫丹、渴望实地考察与探索的坚韧精神。"},sec={{t="雪地里的独行研究员",b="大多数旅行者都留在永望镇的安全区，但多诺瓦·雪山选择在冰火温泉附近的严寒荒野中露营。她每天都在调查从永久冻土层中冒出的奇特地热异常现象，以及那些侵蚀着冬泉谷本土生物的黑暗影响。她务实且坚定，常招募路过的联盟和部落冒险者收集样本，并协助遏制当地的威胁。"},{t="调查冬泉熊怪",b="多诺瓦的大部分精力都集中在冬泉熊怪身上，它们的行为已经恶化，变得反复无常且极具攻击性。通过调查诸如冬泉火酒这类强效混合剂，以及在各个部落间流传的诡异有毒物质，她试图找出导致它们突然陷入疯狂的根源。她的实地考察使她成为了所有希望了解在北方群山中蔓延的腐化现象的人的关键联络人。"}},faq={{q="我在哪里可以找到多诺瓦·雪山？",a="多诺瓦·雪山就在冬泉谷冰火温泉主路西南方的一处小温泉旁扎营。",al={"多诺瓦·雪山位置","多诺瓦在哪里","多诺瓦·雪山地图"}},{q="多诺瓦为什么要在这种严寒的天气里待在这里？",a="她正在对冬泉谷异常的温泉进行环境研究，并调查感染了当地冬泉熊怪部落的腐化现象。",al={"多诺瓦为什么在冬泉谷","多诺瓦·雪山目的"}},{q="多诺瓦会与部落玩家合作吗？",a="是的。尽管她是矮人，但多诺瓦以独立研究员的身份行事，并向联盟和部落的冒险者提供任务。",al={"多诺瓦只属于联盟吗","部落可以和多诺瓦对话吗","多诺瓦·雪山阵营"}},{q="多诺瓦在调查关于冬泉熊怪的什么内容？",a="她正在研究导致冬泉部落陷入疯狂的神秘腐化现象，特别是在调查诸如冬泉火酒这类奇怪的混合剂，以及从它们的奔跑者身上发现的恶臭有毒物质。",al={"多诺瓦熊怪任务","冬泉火酒研究"}}},fp="14,292,29.469.0,28.457.1,32.130.0,44.159.0,36.128.0,63.214.0"}
P.entries["npc:donyal-tovald"] = {n="丹亚·托瓦尔德",s="丹亚·托瓦尔德是一位服务于暴风城内Royal Library的人类管家。在年轻的安度因·乌瑞恩国王发起的一项倡议下，他负责照看王国书籍，并致力于向广大公众分发历史文献的副本。",h="丹亚·托瓦尔德是一位服务于暴风城内Royal Library的人类管家。在年轻的安度因·乌瑞恩国王发起的一项倡议下，他负责照看王国书籍，并致力于向广大公众分发历史文献的副本。",kw={"安度因·乌瑞恩国王","书籍","丹亚·托瓦尔德","历史","图书管理员","royal library","stormwind keep"},ang={["class:Mage"]="造访暴风城的法师可能会欣赏托瓦尔德在保存书面知识方面的奉献精神，即使这些文本主要是历史而非奥术资料。",["race:Human"]="对于暴风城的人类来说，托瓦尔德代表了在第一次战争和首都重建之后，重建并保存其文化和书面历史的一种努力。"},sec={{t="暴风城历史的管家",b="丹亚·托瓦尔德位于暴风城内Royal Library侧翼的静谧壁龛中，照看着王国浩如烟海的历史记载、卷轴和学术典籍。虽然图书馆主要服务于贵族和王室，但年轻的安度因·乌瑞恩国王发起了一项倡议，旨在让普通公民也能更容易地获取知识。托瓦尔德负责这些文本的保存和抄写工作，以确保联盟的教训和丰功伟绩不会在王国动荡的政治局势中被遗忘。"}},faq={{q="丹亚·托瓦尔德是谁？",a="丹亚·托瓦尔德是一位驻守在暴风城Royal Library的人类图书管理员。他负责维护王国的档案馆，并管理着一项由安度因·乌瑞恩国王支持的倡议，旨在向公众分发历史书籍的副本。",al={"托瓦尔德是谁","皇家图书管理员","丹亚·托瓦尔德背景故事"}},{q="在哪里可以找到丹亚·托瓦尔德？",a="他位于暴风城东侧的Royal Library侧翼内，周围环绕着书架和历史卷轴。",al={"丹亚·托瓦尔德位置","托瓦尔德在哪里","如何找到托瓦尔德"}},{q="他为什么要把书发给公民？",a="年轻的安度因·乌瑞恩国王赞助了一个王室项目，旨在教育公众并分享知识。丹亚·托瓦尔德作为管家，负责监督这些王室手稿的复制和分发工作。",al={"安度因书籍倡议","暴风城图书馆项目","他为什么发放书籍"}},{q="他隶属于贵族议会还是圣职人员？",a="托瓦尔德直接在王权下工作，担任暴风城内王室档案馆的保管人，专注于历史和学术文本，而非教会或政治教条。",al={"托瓦尔德是圣光教会的吗","托瓦尔德所属阵营"}}},fp="13,188,30.433.0,21.200.0,31.133.0,40.159.0,56.181.0"}
P.entries["npc:doomsayer-wiserunner"] = {n="先知奥萨迪·智慧行者",s="这位受人尊敬的牛头人长者就是先知奥萨迪·智慧行者，他一直在莫高雷连绵起伏的丘陵中忠诚地服务着他的人民。他在血蹄村西北部山丘的一个洞穴中，为那些进行传统成人礼、迈向精神成熟的年轻牛头人勇士提供帮助。",h="这位受人尊敬的牛头人长者就是先知奥萨迪·智慧行者，他一直在莫高雷连绵起伏的丘陵中忠诚地服务着他的人民。他在血蹄村西北部山丘的一个洞穴中，为那些进行传统成人礼、迈向精神成熟的年轻牛头人勇士提供帮助。",kw={"纳拉其营地","末日预言者奥萨迪·智慧行者","莫高雷","幻象仪式","智慧仪式","先知奥萨迪·智慧行者","牛头人长者"},ang={["class:Shaman"]="萨满祭司会将奥萨迪·智慧行者视为古老传统的守护者，因为他能理解编织在大地与天空之间的讯息。",["race:Tauren"]="对于那些走出红云台地的年轻舒哈鲁来说，先知奥萨迪·智慧行者是他们通往精神成熟的祖先旅程中必不可少的导师。"},sec={{t="神圣之路的向导",b="先知奥萨迪·智慧行者作为舒哈鲁的一位长者和神秘主义者，屹立在莫高雷柔和的悬崖之中。当年轻的牛头人完成了最初的力量与幻象试炼后，他们便会前往那里，在祖先仪式期间寻求他的建议。他解读大地母亲的幻象，并指引年轻人如何尊崇他们的祖先，用他那稳健的智慧，将分散的游牧部落凝聚成一个统一的整体。"}},faq={{q="谁是先知奥萨迪·智慧行者？",a="先知奥萨迪·智慧行者是一位备受尊崇的牛头人长者，在莫高雷的各个部落中享有很高的声望。他的职责是引导年轻的初学者完成神圣的大地母亲仪式。",al={"谁是奥萨迪·智慧行者","先知奥萨迪·智慧行者","奥萨迪·智慧行者牛头人长者"}},{q="他在莫高雷扮演什么角色？",a="先知奥萨迪·智慧行者是年轻牛头人的精神导师。在勇士们开始早期的幻象任务后，他会接见他们以完成传统的智慧仪式，测试他们是否有能力为部落和大地母亲服务。",al={"奥萨迪·智慧行者做什么","先知奥萨迪·智慧行者的目的","奥萨迪·智慧行者的职责"}},{q="先知奥萨迪·智慧行者在哪里？",a="他位于血蹄村西北部山丘的一个洞穴中，那里正是幻象仪式指引牛头人青年前往的地方。从那里，他会将他们送往雷霆崖东部的赤色石，去寻找祖先的灵魂。",al={"奥萨迪·智慧行者在哪里","先知奥萨迪·智慧行者位置","奥萨迪·智慧行者坐标"}}},fx={fbd19081={q="先知奥萨迪·智慧行者想做什么？",a="他希望引导年轻的牛头人经历神圣的灵性成长阶段。他主持智慧试炼等仪式，确保新一代尊崇先祖的指引，并在灵魂面前证明自己的价值。",al={"先知奥萨迪·智慧行者的目标","智慧行者想做什么","先知奥萨迪·智慧行者的动机"}},bf3ce735={q="先知奥萨迪·智慧行者为什么在这里？",a="他居住在莫高雷起伏的丘陵间，担任灵性导师。牛头人青年踏上神圣的成年礼仪式时，他会等候他们，考验他们的洞察力，并将先祖的智慧赐予完成朝圣之旅的人。",al={"先知奥萨迪·智慧行者为什么在莫高雷","先知奥萨迪·智慧行者为何在此","智慧行者为什么在这里"}},f44673b7={q="先知奥萨迪·智慧行者站在哪一边？",a="他忠于牛头人部族和部落。先知奥萨迪·智慧行者驻扎在莫高雷，引导年轻的牛头人完成神圣的先祖试炼，维护族人古老的灵性传统，并尊崇大地母亲的智慧。",al={"先知奥萨迪·智慧行者的阵营","智慧行者站在哪一边","先知奥萨迪·智慧行者是部落成员吗"}}},fp="15,293,26.422.0,23.168.0,34.235.0,35.217.0"}
P.entries["npc:doras"] = {n="多拉斯",s="多拉斯是奥格瑞玛部落的首要风骑士训练师，栖身在俯瞰力量谷的木制高塔上。他负责监管首都的双足飞龙，并派遣信使、斥候和旅行者前往卡利姆多的各个角落。",h="多拉斯是奥格瑞玛部落的首要风骑士训练师，栖身在俯瞰力量谷的木制高塔上。他负责监管首都的双足飞龙，并派遣信使、斥候和旅行者前往卡利姆多的各个角落。",kw={"多拉斯","飞行管理员","奥格瑞玛","valley of strength","风骑士训练师","双足飞龙"},ang={["faction:Horde"]="对于任何部落冒险者来说，多拉斯提供了离开首都的主要空中通道，使他们能够迅速前往卡利姆多各地的盟友定居点。"},sec={{t="天空之路的大师",b="多拉斯栖身在力量谷上方的木制平台上，照料着被称为风骑士或双足飞龙的有翼掠食者。自从部落定居杜隆塔尔以来，这些狡猾、生有革质双翼的野兽就成了部落在卡利姆多进行通讯和交通的中流砥柱。多拉斯负责它们的照料工作，为骑手分配休息好的坐骑，并确保重要的信息和增援部队能够送达偏远的前哨站，如十字路口、雷霆崖，以及位于灰谷或尘泥沼泽深处的定居点。"}},faq={{q="我在哪里可以找到多拉斯？",a="多拉斯驻扎在奥格瑞玛直接俯瞰力量谷的飞行塔顶端。旅行者可以通过城市入口附近中央木制结构上的蜿蜒坡道抵达他的栖息处。",al={"多拉斯位置","奥格瑞玛飞行管理员在哪里","奥格瑞玛双足飞龙管理员"}},{q="多拉斯训练什么生物？",a="多拉斯管理着风骑士，通常也被称为双足飞龙。这些聪明的、带有毒性的有翼掠食者原产于卡利姆多的干旱岩架和稀树草原，它们被部落所驯服，成为跨越遥远距离时可靠的飞行坐骑。",al={"奥格瑞玛坐骑","多拉斯驯养什么飞行生物","什么是风骑士"}},{q="多拉斯能把旅行者送到哪里？",a="从他位于奥格瑞玛的栖息处出发，多拉斯将旅行者与卡利姆多中部和北部的各个部落前哨站连接起来，包括贫瘠之地的十字路口、莫高雷的雷霆崖，以及灰谷及更远地区的军事营地。",al={"多拉斯飞行路线","我能从奥格瑞玛飞往哪里","奥格瑞玛飞行航线"}}},fx={["65cae112"]={q="多拉斯是谁？",a="多拉斯是奥格瑞玛的部落首席双足飞龙管理员。他驻守在城市高处，照料首都的双足飞龙，并协调信使、士兵和冒险者往返卡利姆多各地的空中交通。",al={"多拉斯是谁","多拉斯的身份","奥格瑞玛的多拉斯"}},fb843279={q="多拉斯效忠哪一方？",a="多拉斯效忠部落，直接听命于奥格瑞玛的大酋长萨尔。他确保只有值得信赖的部落盟友才能使用城市的空中交通网络。",al={"多拉斯的阵营","多拉斯是部落成员吗","多拉斯效忠谁"}},["54873cb0"]={q="多拉斯为什么在这里？",a="作为部落首都的飞行管理员，多拉斯负责管理部落双足飞龙网络的中心枢纽。他驻守奥格瑞玛，为大酋长的驻地与杜隆塔尔、贫瘠之地及更远地区的前哨站提供重要的交通联系。",al={"多拉斯为什么在奥格瑞玛","多拉斯的职责","多拉斯在此的职责"}},f6504325={q="多拉斯想做什么？",a="多拉斯专注于照料他的双足飞龙，并维持卡利姆多各地可靠的信使和旅行路线。他希望无论部落的利益在哪里受到挑战，都能迅速传递消息并调动援军。",al={"多拉斯想做什么","多拉斯的动机","多拉斯的目标"}}},fp="5,225,20.498.0,23.213.0,32.246.0,31.232.0"}
P.entries["npc:doren"] = {n="Doren",s="多伦上尉指挥着位于荆棘谷北部的反抗军营地。多伦曾是库尔森上校手下的一名军官，在长官和其他远征队员陷入疯狂后，他领导了一场哗变。现在，他指挥着一支游击抵抗力量，决心查明这场灾难的根源并除掉库尔森。",h="多伦上尉指挥着位于荆棘谷北部的反抗军营地。多伦曾是库尔森上校手下的一名军官，在长官和其他远征队员陷入疯狂后，他领导了一场哗变。现在，他指挥着一支游击抵抗力量，决心查明这场灾难的根源并除掉库尔森。",kw={"赫洛德","库尔森上校","doren","库尔森","库尔森的营地","多伦上尉","反抗军营地","荆棘谷","索尔森"},ang={["faction:Alliance"]="对于联盟士兵来说，多伦代表了暴风城丛林远征的悲剧后果，他提供了一个纠正库尔森的错误并恢复荒野边境秩序的机会。",["race:Human"]="人类旅行者会认出多伦的军事纪律，这提醒着人们，远离暴风城王国执行孤立的任务会对人的心智和士气造成怎样的影响。"},sec={{t="丛林哗变",b="多伦上尉最初是在暴风城的旗帜下，听从库尔森上校的指挥来到荆棘谷的。这次远征本意是在这片荒蛮的南部丛林中建立一个立足点，但随着库尔森和他的核心圈子陷入一种古怪、暴力的疯狂之中，情况很快恶化了。由于拒绝放弃理智和荣誉，多伦和一小队忠诚的士兵脱离了部队。他们向北逃去，并在路边建立了反抗军营地，选择了反叛而不是沦为疯子的奴仆。"},{t="揭开真相",b="从他们危险的前哨站出发，多伦指挥着针对库尔森的营地的行动。他维持着与中立方（包括藏宝海湾里的地精联络人，比如克拉兹克）的补给线，以确保他那日益减少的部队有吃有喝，武器充足。除了单纯的生存，多伦还在寻找答案：他派遣像列兵索尔森这样的间谍深入敌后，试图找出是什么诅咒了上校，并根除像赫洛德这样的叛徒和通敌者。最终，多伦认为要挽救远征队仅存的荣誉，唯一的办法就是亲手终结库尔森。"}},faq={{q="多伦上尉是谁？",a="多伦上尉是荆棘谷北部反抗军营地的领袖。他曾是暴风城远征军中库尔森上校的副手。在库尔森发疯后，多伦领导了一支拒绝追随他的士兵，并脱离了部队。",al={"多伦是谁","多伦背景故事","反抗军营地领袖"}},{q="为什么多伦被视为反叛者？",a="多伦和他的部队对他们的指挥官库尔森上校发动了哗变。由于库尔森是远征队官方任命的负责人，脱离队伍并对他拿起武器，在技术上使得多伦和他的追随者成了反叛者，尽管他们反叛是为了保持理智并反抗库尔森的暴政。",al={"为什么叫反抗军营地","多伦为何反叛","库尔森哗变"}},{q="是什么导致库尔森上校发疯的？",a="导致库尔森及其核心圈子陷入疯狂的具体源头仍然是一个谜，而多伦正在积极寻求解决。多伦利用侦察兵和渗透者来查明究竟是什么在丛林深处腐化了他的前指挥官。",al={"库尔森为何发疯","库尔森的疯狂"}},{q="多伦是如何维持反抗军营地的补给的？",a="由于断绝了来自暴风城的官方支援，多伦依赖隐秘的补给运输和与第三方的贸易安排。值得注意的是，他与南部海盗避风港藏宝海湾的地精商人（例如克拉兹克）协调，以保证他的部队得到装备。",al={"反抗军营地补给","多伦的补给"}},{q="赫洛德是谁，他与多伦有什么关系？",a="赫洛德是库尔森部队中的一个相关人物。多伦怀疑赫洛德参与了调查，导致多伦的卧底特工列兵索尔森在潜入库尔森的营地时被识破了真实身份。",al={"赫洛德","赫洛德反抗军营地"}},{q="多伦是否听命于暴风城？",a="多伦仍然忠于联盟的理想，但由于他在战场上背离了指挥官，他现在自主行动。他欢迎联盟的冒险者协助清理这场灾难性的远征。",al={"多伦与联盟","多伦对暴风城的效忠"}}},fp="5,319,22.497.0,20.558.1,24.242.0,32.324.0,30.242.0,44.251.0,56.210.0,31.223.0"}
P.entries["npc:dorn-plainstalker"] = {n="多恩·平原行者",s="多恩·平原行者是一位隐居的牛头人长者，居住在俯瞰千针石林峡谷的老屋。他担任传统成年仪式的监考官，挑战部落的冒险者，以证明他们的品格与坚韧。通过信仰、耐力、力量和传说这几项考验，他将检验旅者是否有资格成为大地母亲及其族人的忠诚仆从。",h="多恩·平原行者是一位隐居的牛头人长者，居住在俯瞰千针石林峡谷的老屋。他担任传统成年仪式的监考官，挑战部落的冒险者，以证明他们的品格与坚韧。通过信仰、耐力、力量和传说这几项考验，他将检验旅者是否有资格成为大地母亲及其族人的...",kw={"多恩·平原行者","乱风岗","牛头人试炼","耐力试炼","信仰试炼","传说试炼","力量试炼","千针石林","老屋"},ang={["faction:Horde"]="多恩欢迎所有愿意接受他考验的部落勇士，确保各种族的战士、猎人和萨满祭司都能在卡利姆多崎岖的荒野中证明自己的实力。",["race:Tauren"]="对于在千针石林漫游的牛头人来说，多恩代表了游牧祖先传统的延续，以及那些考验一个人与大地母亲之间平衡的各种精神仪式。"},sec={{t="高崖隐士",b="多恩·平原行者隐居在老屋高处峡谷脊背上的一个浅洞中，远离乱风岗的喧嚣。想要抵达他那座山间避难所，需要沿着俯瞰下方高耸台地的陡峭北崖蜿蜒前行。在这个安静的制高点，多恩坚守着古老的习俗，并指引那些在荒凉的南贫瘠之地寻求指引的人们。"},{t="四项考验",b="多恩·平原行者指导朝圣者完成一系列严苛的测试，旨在衡量牛头人勇士的核心美德：信仰、耐力、力量和传说。这些考验不仅仅是单纯的体能锻炼，更迫使求道者直面恐惧、盲目跳入未知、在狡猾的荒野掠食者面前坚持到底，并在领取最终试炼之前思考卡利姆多的神圣历史。"}},faq={{q="多恩·平原行者是谁？",a="多恩·平原行者是一位牛头人隐士和长者，居住在千针石林高处一个僻静的崖边避难所——老屋。他为有志成为部落勇士的人们主持传统的成年仪式。",al={"多恩是谁","多恩背景故事","多恩·平原行者"}},{q="我可以在哪里找到多恩·平原行者？",a="他位于老屋的一个洞穴中。从乱风岗出发，向北前往峡谷边缘的高耸峭壁，然后沿山脊向东走，直到你发现一条通往他山间圣地的坡道。",al={"多恩在哪里","如何找到多恩·平原行者","老屋位置"}},{q="多恩主持的考验有哪些？",a="多恩监管着四项神圣测试：信仰试炼、耐力试炼、力量试炼和传说试炼。完成这些测试可以证明旅者的勇气、身体意志、战斗技巧以及对传统的尊重。",al={"多恩·平原行者的任务","信仰试炼","千针石林的成人仪式"}},{q="什么是信仰试炼？",a="信仰试炼要求朝圣者从令人眩晕的悬崖木板跳入下方的深渊，以展示绝对的信任并克服原始的恐惧。",al={"千针石林的信仰之跃","多恩的信仰试炼"}},{q="为什么多恩独自住在洞穴里？",a="多恩恪守牛头人的苦修精神传统。通过独自居住在老屋的高处，远离乱风岗的日常贸易与防御，他为寻求者保持了一个宁静的沉思与试炼之所。",al={"为什么多恩要离群索居","多恩·平原行者的背景"}},{q="多恩隶属于乱风岗吗？",a="虽然他居住在乱风岗之外，但多恩是部落和牛头人部族的一名忠诚成员，他会帮助那些漫步在风蚀峡谷中的勇敢旅者。",al={"乱风岗长者","多恩属于部落吗"}}},fx={["4250a0db"]={q="多恩·平原行者效忠哪一方？",a="多恩·平原行者效忠部落和他的牛头人同胞。他欢迎部落旅者前往老屋，接受考验以证明自己的能力，并引导他们完成传统仪式，确保他们具备为部族和整个部落效力所需的力量、信仰与智慧。",al={"多恩是部落成员吗","多恩·平原行者的阵营","多恩效忠谁"}},a0eea52d={q="多恩·平原行者想做什么？",a="多恩·平原行者想考验那些穿越千针石林的勇士的品格、耐力与精神。通过主持信仰、耐力、力量和知识试炼，他希望让合格的冒险者为世界的严酷挑战做好准备，并确保他们尊崇大地的传统。",al={"多恩的目标","多恩想做什么","多恩·平原行者的职责"}}},fp="17,395,25.386.0,15.401.0,25.212.0,35.215.0,37.210.0,26.152.0,35.237.0,38.171.0"}
P.entries["npc:drum-fel"] = {n="杜拉姆法尔",s="杜拉姆法尔是一位驻扎在阿拉希高地部落哨站落锤镇的兽人指挥官。他与妻子科林一起，指挥军事力量保护这个避难所，抵御不断侵袭的巨魔、食人魔以及人类残余势力。他的战略推进对于部落在阿拉希开辟持久的立足点至关重要。",h="杜拉姆法尔是一位驻扎在阿拉希高地部落哨站落锤镇的兽人指挥官。他与妻子科林一起，指挥军事力量保护这个避难所，抵御不断侵袭的巨魔、食人魔以及人类残余势力。他的战略推进对于部落在阿拉希开辟持久的立足点至关重要。",kw={"阿拉希高地","石拳","杜拉姆法尔","落锤镇","科林法尔","奥卡拉","枯木"},ang={["faction:Horde"]="对于在东部王国推进的部落战士来说，杜拉姆法尔是一位主要的军事协调员，负责保障幽暗城与南部领地之间脆弱的生命线安全。",["race:Orc"]="杜拉姆法尔体现了在东部王国重建兽人生活所需的务实军事勇气，坚守在曾经设立收容所的土地上。"},sec={{t="落锤镇典狱官",b="杜拉姆法尔坐镇于防守严密的落锤镇，统筹部落在阿拉希的防御与领土扩张。在敌对势力的包围中，他协调针对枯木森林巨魔以及占据博德戈尔和石拳大厅的石拳食人魔氏族的军事打击。杜拉姆深知，落锤镇不能仅仅依靠孤立而生存，它必须瓦解邻近势力的力量才能繁荣发展。为此，他经常派遣经验丰富的勇士深入敌后，在这些威胁对部落营地发动袭击之前就将其消灭。"},{t="激流堡的威胁",b="杜拉姆法尔的战役延伸到了激流堡的废墟，石拳食人魔在那里的人类王国遗迹中建立了防御工事。多年前，杜拉姆击败了食人魔蛮兵奥卡拉，结下了不解之仇。杜拉姆并不知道，奥卡拉正潜伏在激流堡中伺机复仇。为了保护丈夫免遭这场宿怨引发的伏击，他的妻子科林默默采取行动掩盖奥卡拉的存在，并借助外来冒险者的力量在杜拉姆亲自冲锋前解决掉这个威胁。"}},faq={{q="杜拉姆法尔是谁？",a="杜拉姆法尔是一位位于阿拉希高地落锤镇的兽人领袖。他负责协调该据点针对地区内敌对势力的军事行动。",al={"杜拉姆法尔","杜拉姆法尔是谁","落锤镇 杜拉姆"}},{q="杜拉姆法尔在哪里？",a="他位于阿拉希高地东北部的落锤镇部落定居点内，就在通往辛特兰的主干道东侧。",al={"杜拉姆法尔位置","杜拉姆法尔在哪里","寻找杜拉姆法尔"}},{q="科林法尔是谁？",a="科林法尔是杜拉姆的妻子。她也住在落锤镇。",al={"科林法尔","杜拉姆法尔的妻子"}},{q="食人魔奥卡拉为什么要杀死杜拉姆法尔？",a="多年前，杜拉姆法尔在战斗中击败了奥卡拉。深感耻辱的食人魔如今潜伏在激流堡的废墟中，密谋向这位兽人指挥官复仇。",al={"奥卡拉的宿怨","为什么奥卡拉恨杜拉姆法尔","奥卡拉 杜拉姆法尔"}},{q="杜拉姆法尔的目标是什么？",a="杜拉姆法尔指挥打击博德戈尔、石拳大厅和激流堡的石拳食人魔，以及附近的枯木巨魔部落。",al={"杜拉姆法尔的任务","杜拉姆法尔的敌人","杜拉姆法尔在与谁战斗"}}},fx={["51d7fbcd"]={q="杜拉姆法尔效忠哪一方？",a="杜拉姆法尔是部落中坚毅的领袖。他驻守在落锤镇，指挥军事行动，确保部落在阿拉希高地的安全与主导地位。",al={"杜拉姆法尔的阵营","杜拉姆法尔效忠谁","杜拉姆法尔是部落成员吗"}},["828c27d6"]={q="杜拉姆法尔想做什么？",a="杜拉姆法尔希望落锤镇能在敌对的领土上生存并发展。为了保护这座定居点，他下令对威胁该地区的敌对势力发起果断的攻势，包括石拳食人魔、枯木巨魔，以及盘踞在激流堡废墟中的敌人。",al={"杜拉姆法尔的目标","杜拉姆法尔需要什么","杜拉姆法尔的动机"}},def003ab={q="杜拉姆法尔为什么在落锤镇？",a="杜拉姆法尔从落锤镇统筹军事行动，守护部落在阿拉希高地的据点。他以这座堡垒为依托，协调族人抵御周边威胁，防止定居点遭到毁灭。",al={"杜拉姆法尔为什么在这里","阿拉希的杜拉姆法尔","杜拉姆法尔在阿拉希的职责"}}},fp="8,316,20.585.0,24.525.1,16.161.0,28.161.0,17.57.0,46.169.0,34.155.0"}
P.entries["npc:drusilla-la-salle"] = {n="杜希拉·拉萨雷",s="杜希拉·拉萨雷是一名人类术士训练师，位于北郡修道院外阴暗的墓地中。她在北郡圣教的边缘地带活动，教导初出茅庐的施法者们关于召唤和暗影的黑暗技艺。当禁忌的知识从修道院的墙内流出时，她会毫不犹豫地利用机会主义和黑暗魔法将其据为己有。",h="杜希拉·拉萨雷是一名人类术士训练师，位于北郡修道院外阴暗的墓地中。她在北郡圣教的边缘地带活动，教导初出茅庐的施法者们关于召唤和暗影的黑暗技艺。当禁忌的知识从修道院的墙内流出时，她会毫不犹豫地利用机会主义和黑暗魔法将其据为...",kw={"修道院","杜希拉·拉萨雷","墓地","北郡","虚空灵能","被盗魔典","术士训练师"},ang={["class:Priest"]="站在北郡神圣大厅之外，杜希拉代表了你职业的黑暗面，她在圣洁的墓地旁从事暗影和恶魔契约的勾当。",["class:Warlock"]="杜希拉是你黑暗技艺的启蒙导师，引导你掌握诅咒和邪能召唤的实战技巧，同时教导你如何在众目睽睽之下隐藏你的野心。"},sec={{t="圣地之影",b="当圣骑士和牧师在北郡修道院的彩色玻璃下修行时，杜希拉·拉萨雷却待在墓地的墓碑之间。在暴风城王国，练习恶魔学和邪能魔法是极大的禁忌，这迫使术士们只能生活在主流社会的边缘。杜希拉为收到受污染信件的术士新手提供初步指导，教导他们如何掌控暗影力量，同时避免招致修道院当局的直接愤怒。"},{t="虚空灵能",b="北郡修道院的图书馆侧厅秘密收藏了几本危险的禁忌之书，其中包括《虚空灵能》。杜希拉早就觊觎这份手稿，但如果一个术士在戒备森严的档案馆徘徊，会立刻引起怀疑。当一名背叛的学徒逃离修道院加入迪菲亚潜行者，并带走了那本著作时，她的机会来了。杜希拉利用这次失窃，派遣她的学徒去追捕那个The Turncoat，并假借收回修道院财产的名义，将那本魔典拿到手。"}},faq={{q="为什么术士被允许待在北郡修道院附近？",a="术士深受圣光教会和暴风城领导层的极度不信任。杜希拉·拉萨雷待在修道院主体建筑之外，隐居在附近的墓地里，在那里进行教学，远离在内部学习的虔诚牧师和教士。",al={"杜希拉为什么在修道院","修道院里的术士","她为什么在墓地"}},{q="杜希拉试图获取什么书？",a="她在寻找一本名为《虚空灵能》的魔典。它最初被锁在北郡修道院图书馆侧厅的一个受保护区域内，在一名迪菲亚叛徒偷走它之前，术士们根本无法接触到它。",al={"她想要什么书","虚空灵能之书","被盗魔典任务之书"}},{q="谁从图书馆偷走了那本书？",a="一名在北郡修道院学习的学徒违背了他的誓言，与迪菲亚潜行者结盟，掠夺了那本魔典，然后逃往北郡山谷的一个营地。",al={"谁拿走了魔典","迪菲亚窃书者","谁偷走了虚空灵能"}},{q="她对人类术士新手扮演什么角色？",a="杜希拉是人类术士的启蒙训练师，她接收发给新人的受污染信件，并教导他们基础的诅咒和召唤仆从的方法。",al={"北郡人类术士训练师","谁在北郡训练术士"}}},fp="17,251,22.404.0,18.431.1,47.192.0,39.189.0,36.154.0,47.147.0"}
P.entries["npc:duke-hydraxis"] = {n="海达克西斯公爵",s="海达克西斯公爵是一位高贵的水元素，他在艾萨拉海岸外一座偏远且饱受海浪冲击的小岛上统领着海达希亚水元素。他效忠于猎潮者耐普图隆，并召集凡人冒险者对抗他古老的元素宿敌，特别是炎魔拉格纳罗斯。",h="海达克西斯公爵是一位高贵的水元素，他在艾萨拉海岸外一座偏远且饱受海浪冲击的小岛上统领着海达希亚水元素。他效忠于猎潮者耐普图隆，并召集凡人冒险者对抗他古老的元素宿敌，特别是炎魔拉格纳罗斯。",kw={"艾萨拉","海达克西斯公爵","海达希亚水元素","海达克西斯","熔火之心","耐普图隆","拉格纳罗斯","水元素"},ang={["class:Shaman"]="对于那些直接与原始元素沟通的萨满祭司来说，见到像海达克西斯公爵这样地位的元素，可以让他们难得地洞察耐普图隆的古老等级制度，以及元素位面之间永恒的敌对关系。"},sec={{t="水元素之主",b="海达克西斯公爵伫立在艾萨拉拉文凯斯雕像东北方的一块孤立岩石上，他是海达希亚水元素的主要使者。虽然大多数被束缚在艾泽拉斯的元素都充满了敌意且混乱无序，但海达克西斯的行事却深谋远虑。作为猎潮者耐普图隆的忠诚臣属，他认为水是原始力量中最纯净、最本质的力量。他冷眼审视着艾泽拉斯各地日益增长的动荡，寻找能够改变元素战争天平的勇士。"},{t="对抗火焰的战争",b="海达克西斯的核心战役目标是炎魔拉格纳罗斯的炽热大军。他将火元素的入侵视为世界的灾祸，必须将其熄灭。在给予信任或提供挑战拉格纳罗斯在熔火之心的火焰堡垒所需的工具之前，海达克西斯公爵要求凡人通过在各大陆击杀敌对元素来证明自己的力量、韧性和忠诚。那些证明了自身价值的人将获得海洋的祝福，以及扑灭守护炎魔领地的圣火所需的手段。"}},faq={{q="海达克西斯公爵在哪里？",a="海达克西斯公爵位于艾萨拉东海岸外一座与世隔绝的小岛上，就在拉文凯斯雕像的正东北方。",al={"海达克西斯在哪里","海达克西斯公爵位置","寻找海达克西斯公爵","海达克西斯地图位置"}},{q="海达克西斯公爵效忠于谁？",a="他领导着海达希亚水元素，并侍奉元素水之王，猎潮者耐普图隆。",al={"海达克西斯效忠于谁","海达克西斯阵营","耐普图隆的仆从"}},{q="为什么海达克西斯公爵对凡人勇士感兴趣？",a="他寻求可靠的凡人盟友来对抗敌对的元素派系，尤其是潜伏在黑石山中的拉格纳罗斯的火元素势力。",al={"海达克西斯为何需要凡人","海达克西斯的意图","海达克西斯的目的"}},{q="海达克西斯公爵与熔火之心有什么联系？",a="海达克西斯公爵指引勇士去破坏炎魔拉格纳罗斯的计划，并提供扑灭守护熔火之心的符文和首领所需的元素辅助手段。",al={"海达克西斯与熔火之心","海达克西斯与拉格纳罗斯","熔火之心海达克西斯"}}},fp="13,287,22.506.0,20.552.0,33.133.0,34.99.0,52.158.0,54.169.0"}
P.entries["npc:durnan-furcutter"] = {n="德南·弗卡特",s="德南·弗卡特是一位在寒脊山谷的安威玛尔工作的矮人裁缝和皮革商人。他在安威玛尔内工作，为刚受训的矮人和侏儒冒险者提供适合抵御严寒山风的轻便服装。",h="德南·弗卡特是一位在寒脊山谷的安威玛尔工作的矮人裁缝和皮革商人。他在安威玛尔内工作，为刚受训的矮人和侏儒冒险者提供适合抵御严寒山风的轻便服装。",kw={"安威玛尔","布甲商人","寒脊山谷","丹莫罗","德南·弗卡特","皮甲商人","烫嘴的晨酿"},ang={["profession:Tailoring"]="对于初出茅庐的裁缝来说，像德南这样的商人提供了基础的服装，在高级布甲出现之前，正是这些衣物让侦察兵和学徒们能在雪道中存活下来。",["race:Dwarf"]="德南体现了寒脊山谷矮人生活的务实一面：结实的工艺、对热饮的喜爱，以及在雪地里友好的交谈。"},sec={{t="严寒中的暖意",b="安威玛尔是年轻矮人和流亡侏儒的第一个试炼场，并非每一位战士踏上征程时都身披重甲。德南·弗卡特为那些需要轻便、柔韧的衣物以保持敏捷，同时又不至于在丹莫罗的凛冽寒风中冻僵的侦察兵、潜行者和施法者提供服务。他就位于安威玛尔的炉火旁，出售日常裁缝制品和缝制皮革，并声称他的货品是整个山谷中最棒的。"},{t="手中的酒杯",b="和驻扎在积雪山麓的任何真正的矮人一样，德南对烈酒的喜爱几乎不亚于对诚实交易的追求。他会向诺里斯·激流订购热气腾腾的烫嘴的晨酿——这位商人在寒脊山谷四处兜售这种滚烫的佳酿——以抵御刺骨的寒风。在山谷中奔波的冒险者经常需要赶在酒变凉之前，将一杯热饮送到他那双期待的手中，然后再把空杯带回给诺里斯。"}},faq={{q="德南·弗卡特是谁？",a="德南·弗卡特是一位驻扎在寒脊山谷安威玛尔的矮人护甲商人。他向在丹莫罗开始冒险旅程的新手冒险者出售基础的布甲和皮甲装备。",al={"德南","弗卡特","德南·弗卡特是谁"}},{q="我在哪里可以找到德南·弗卡特？",a="他位于寒脊山谷中开凿在山腰上的定居点——安威玛尔内部，靠近训练师和当地的商人。",al={"德南位置","德南在哪里","安威玛尔布甲商人"}},{q="德南卖什么？",a="他提供各式各样的入门级布甲和皮甲，专供那些依赖敏捷或施法，而非重型锁甲的职业使用。",al={"德南的商品","德南卖什么"}},{q="为什么他会参与烫嘴的晨酿的配送？",a="德南在寒脊山谷的凛冽寒风中长时间工作，为了保持清醒和温暖，他会向在山谷中兜售此酒的诺里斯·激流订购热腾腾的烫嘴的晨酿。",al={"德南啤酒任务","烫嘴的晨酿 德南","德南饮品"}}},fx={d97cf4a2={q="德南·弗卡特效忠哪一方？",a="德南坚定地支持铁炉堡和联盟。他驻扎在安威玛尔，为在寒脊山谷踏上旅程的年轻矮人和侏儒新兵提供装备。",al={"德南的阵营","德南·弗卡特与联盟","德南效忠谁"}},afaf309b={q="德南·弗卡特想做什么？",a="德南首先想经营自己的生意，还夸口说他卖的布衣和皮衣是山谷这一带最好的。除此之外，为了抵御寒脊山谷刺骨的严寒，他也从不拒绝来一杯热气腾腾的灼热麦酒。",al={"德南想做什么","德南·弗卡特的目标","德南的职责"}},["9750ade9"]={q="德南·弗卡特为什么在安威玛尔？",a="安威玛尔是寒脊山谷新手的训练场和集会中心。德南留在这里，为新晋冒险者提供必需的衣物和基础护甲，让他们能在踏入白雪皑皑的荒野前做好准备。",al={"德南为什么在这里","德南为什么在寒脊山谷","德南在此的原因"}}},fp="16,261,25.456.0,13.439.0,24.190.0,34.146.0,22.152.0,53.171.0"}
P.entries["npc:duthorian-rall"] = {n="达索瑞恩·拉尔",s="达索瑞恩·拉尔是驻扎在暴风城光明大教堂内的一位受人尊敬的人类白银之手骑士。作为联盟中最具影响力的圣骑士之一，他负责监督新晋圣光战士的训练与精神试炼。他指引招募者们立下慈善、英勇与奉献的庄严誓言，以保卫艾泽拉斯免受天灾军团及潜伏的内部威胁侵害。",h="达索瑞恩·拉尔是驻扎在暴风城光明大教堂内的一位受人尊敬的人类白银之手骑士。作为联盟中最具影响力的圣骑士之一，他负责监督新晋圣光战士的训练与精神试炼。他指引招募者们立下慈善、英勇与奉献的庄严誓言，以保卫艾泽拉斯免受天灾军团...",kw={"cathedral of light","达芙妮·斯迪威尔","达索瑞恩·拉尔","乔丹·斯迪威尔","圣骑士训练师","白银之手","暴风城","生命符记","神圣之书","勇气之书"},ang={["class:Paladin"]="达索瑞恩·拉尔是你身在暴风城时的主要精神导师之一，他通过基础试炼来考验你的慈悲与英勇，这些试炼将解锁复活、神圣感知以及你的战马等力量。",["faction:Alliance"]="作为白银之手内部的一位有影响力的领袖，达索瑞恩确保联盟的捍卫者保持道德正直，并有能力保卫王国免受强盗与亡灵的威胁。",["race:Human"]="达索瑞恩扎根于暴风城的光明大教堂，代表着人类信仰与社会核心中持久的奉献精神与骑士纪律。"},sec={{t="白银之手的支柱",b="达索瑞恩·拉尔站在光明大教堂的拱顶耳堂内，代表着白银之手骑士团的悠久传统。由于王国正处于内部动荡之中，且瓦里安·乌瑞恩国王下落不明，达索瑞恩肩负起为新进成员灌输公正纪律的重要职责。包括闪金镇的威尔海姆修士和铁炉堡的布兰度尔·铁锤在内的外地受人尊敬的圣骑士们，都会将有前途的招募者引荐到他的麾下，开始他们的神圣试炼。"},{t="慈悲与生命的试炼",b="达索瑞恩教导说，没有道德基础的武力是空洞的。通过《神圣之书》，他考验圣骑士的同理心，要求他们在暴风城各地行使仁慈与无私的义举，然后才向他们传授更深奥的奥秘。他的试炼最终会通过英雄哨岗附近的生命符记来考验候选人，派遣他们去救助受伤的盟友，并教会他们引导圣光的神奇力量，使倒下的战友起死回生。"},{t="英勇的代价",b="除了精神上的沉思，达索瑞恩还要求在面对危险时展现出坚定的勇气。在他的英勇试炼中，他告诫立誓者，他们的誓言可能需要以生命为代价。他通过将新进成员送入危险地带——例如在西部荒野保护达芙妮·斯迪威尔免受迪菲亚叛徒的伤害——来考验这种决心，随后引导他们前往铁炉堡外的大师级铁匠乔丹·斯迪威尔处，并授予他们与其地位相符的神圣战马。"}},faq={{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是一位杰出的白银之手骑士，居住在暴风城的光明大教堂内。他担任新晋圣骑士的导师与精神指引，代表圣光教会考验他们的奉献精神与勇气。",al={"达索瑞恩·拉尔背景故事","达索瑞恩是谁","大教堂圣骑士达索瑞恩"}},{q="在哪里可以找到达索瑞恩·拉尔？",a="你可以在位于暴风城Cathedral Square中心的光明大教堂东侧翼找到他。",al={"达索瑞恩·拉尔在哪里","达索瑞恩·拉尔位置","如何找到达索瑞恩"}},{q="他与《神圣之书》有什么联系？",a="达索瑞恩为圣骑士提供《神圣之书》，并指导他们完成谦逊、慈悲与救援的试炼。完成他的试炼证明了一名新进成员有资格掌握圣光的复活力量。",al={"神圣之书与达索瑞恩","救赎任务与达索瑞恩","生命符记任务"}},{q="为什么达索瑞恩要把圣骑士送到西部荒野？",a="在《勇气之书》的试炼期间，达索瑞恩派遣圣骑士前往西部荒野的农场，保护达芙妮·斯迪威尔免受迪菲亚强盗的袭击，以此展现他们为保卫无辜者而牺牲的意愿。",al={"达芙妮·斯迪威尔任务","勇气之书与西部荒野","西部荒野圣骑士任务"}},{q="达索瑞恩会给予通过试炼的圣骑士什么奖励？",a="成功的圣骑士在他的指导下获得了关键的神圣能力，包括神圣的复活天赋、感知亡灵的能力、诸如暴风壁垒之类的防护装备，以及最终他们召唤的战马。",al={"达索瑞恩任务奖励","从达索瑞恩处获得什么"}},{q="谁最初指引冒险者去找达索瑞恩？",a="立誓者通常由圣骑士训练师指引，其中包括闪金镇的威尔海姆修士和铁炉堡的布兰度尔·铁锤。",al={"谁指引你去找达索瑞恩","达索瑞恩引导任务"}}},fp="14,364,27.415.0,29.446.0,18.376.1,22.224.0,34.125.0,47.211.0,45.210.0,66.240.0,45.134.0"}
P.entries["npc:ebru"] = {n="厄布鲁",s="厄布鲁是一位暗夜精灵德鲁伊，在哀嚎洞穴上方的峭壁中避难。作为纳拉雷克斯少数几位未受腐蚀的门徒之一，她只能无助地看着大师恢复贫瘠之地的梦想沦为一场噩梦。从她的栖身处，她招募勇于进入地底深处的旅行者，去清除由梦魇滋生的变异恐怖生物。",h="厄布鲁是一位暗夜精灵德鲁伊，在哀嚎洞穴上方的峭壁中避难。作为纳拉雷克斯少数几位未受腐蚀的门徒之一，她只能无助地看着大师恢复贫瘠之地的梦想沦为一场噩梦。从她的栖身处，她招募勇于进入地底深处的旅行者，去清除由梦魇滋生的变异恐...",kw={"贫瘠之地","塞纳里奥议会","变异","德鲁伊","厄布鲁","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊来说，遇见厄布鲁是一个鲜明的提醒，告诫他们行走在翡翠梦境中所固有的可怕危险，以及失去控制带来的灾难性代价。",["race:NightElf"]="厄布鲁代表了在卡利姆多干旱中心深处运作的一小群孤立的暗夜精灵，远离灰谷和泰达希尔的古老树冠。"},sec={{t="高处的守望者",b="当纳拉雷克斯的大多数追随者屈服于在洞穴中蔓延的翡翠腐蚀时，厄布鲁设法逃脱了梦魇的魔爪。她在俯瞰哀嚎洞穴入口的洞穴头骨构造内扎营，守望着下方的入口。她知道纳拉雷克斯的高尚计划——利用地下泉水将干旱的贫瘠之地转变为茂密的林地——已经出了严重的问题，她拼命地引导愿意冒险的探险者去消灭威胁要淹没周围平原的各种变异野兽。"},{t="腐蚀的代价",b="梦魇不仅扭曲了洞穴的生态系统，还扭曲了厄布鲁的同门，将他们变成了狂热的尖牙德鲁伊。失去了同伴，面对教团的毁灭，厄布鲁专注于遏制腐蚀。"}},faq={{q="厄布鲁是谁？",a="厄布鲁是一位暗夜精灵德鲁伊，也是纳拉雷克斯未受腐蚀的门徒。她居住在哀嚎洞穴入口上方高处的一个洞穴中，守望着这里，并协调各方努力以阻止腐蚀蔓延到贫瘠之地。",al={"厄布鲁是谁","厄布鲁背景故事","关于厄布鲁"}},{q="为什么厄布鲁会在哀嚎洞穴上方？",a="当纳拉雷克斯的仪式陷入翡翠梦魇并导致她的同门变成敌对的狂热分子时，她向上逃去。她在洞穴入口上方峭壁的栖身处让她可以在监视洞穴的同时，免受内部野性恐怖生物的伤害。",al={"厄布鲁在哪里","为什么厄布鲁在这里","厄布鲁洞穴位置"}},{q="纳拉雷克斯和他的其他门徒发生了什么事？",a="纳拉雷克斯进入深度冥想以引出地下泉水，但他的心智被困在了翡翠梦魇之中。随之而来的腐蚀扭曲了洞穴的动植物，并使他的大多数门徒发疯，将他们变成了尖牙德鲁伊。",al={"门徒们发生了什么","纳拉雷克斯的命运","尖牙德鲁伊的起源"}},{q="厄布鲁要求旅行者做什么？",a="厄布鲁敦促冒险者深入哀嚎洞穴，清除变异野兽，并反击那些从她大师受折磨的梦境中诞生的突变怪物。",al={"厄布鲁任务","清除变异","净化洞穴"}}},fx={["5ace5551"]={q="厄布鲁效忠于哪一方？",a="厄布鲁为塞纳里奥议会效力，并忠于她的导师——德鲁伊纳拉雷克斯。许多同伴都遭到侵入洞穴的梦魇侵蚀，而她没有变得敌对，也未屈服于腐化。她虽是暗夜精灵，却愿意接纳任何有能力深入洞穴净化绿洲、拯救师父的旅人，无论其属于联盟还是部落。",al={"厄布鲁所属阵营","厄布鲁属于联盟还是部落","厄布鲁为谁效力"}}},fp="4,367,25.552.0,23.238.1,12.237.0,46.256.0,49.263.0,35.188.0"}
P.entries["npc:edwin-vancleef"] = {n="艾德温·范克里夫",s="艾德温·范克里夫曾是石匠工会才华横溢的工会会长，他在第二次战争后负责重建暴风城。在遭到贵族议会的克扣工钱后，他领导了一场暴力的工人起义，并组建了亡命徒组织：迪菲亚潜行者。他盘踞在西部荒野的死亡矿井深处，向他曾经协助重建的王国寻求复仇。",h="艾德温·范克里夫曾是石匠工会才华横溢的工会会长，他在第二次战争后负责重建暴风城。在遭到贵族议会的克扣工钱后，他领导了一场暴力的工人起义，并组建了亡命徒组织：迪菲亚潜行者。他盘踞在西部荒野的死亡矿井深处，向他曾经协助重建的...",kw={"兄弟会","死亡矿井","迪菲亚","月溪镇","石匠","暴风城","范克里夫","西部荒野"},ang={["class:Rogue"]="范克里夫由军情七处首领Mathias Shaw亲自训练，这使他成为艾泽拉斯最出色的潜行者之一，将正规的工会领导能力与精英刺杀技巧融为一体。",["faction:Alliance"]="联盟指挥官认为范克里夫是威胁人类南部领土的首要内部安全隐患，他不仅让西部荒野陷入瘫痪，还威胁到艾尔文森林的边境。",["race:Human"]="对于暴风城的人类来说，范克里夫体现了王国战后复兴的悲剧：一位忠诚的英雄，因生计被剥夺而沦为了王国最致命的叛乱分子。"},sec={{t="王国的建筑师",b="第一次战争的浩劫过后，艾德温·范克里夫被选中领导石匠工会，承担起重建暴风城的艰巨任务。作为一名无与伦比的工匠和理想主义者，范克里夫指导了这座都城宏伟城墙和高耸大教堂的建造。除了精通建筑学之外，范克里夫还是一名极为致命的特工；他曾受童年好友Mathias Shaw的教导，习得潜行、诡计和剑术。"},{t="暴乱与兄弟会",b="当多年的劳作结束时，贵族议会因军事行动而背负了巨额债务，并拒绝支付石匠工会承诺的报酬。愤怒的范克里夫要求赔偿，却遭到贵族们正式解散了工会。范克里夫领导了一场暴乱，带着石匠们离开了城市；在混乱中，他的副手也是最信任的助手巴基尔·斯瑞德被俘，并被关进了监狱。在西部荒野，范克里夫将流亡的工人和被驱逐的社会边缘人集结在迪菲亚潜行者的旗帜之下。"},{t="阴影中的报复",b="趁着王室对农村地区的疏忽，迪菲亚潜行者赶走了西部荒野的农民，占据了那里丰富的金矿。在月溪镇的死亡矿井深处，范克里夫监督着一艘巨型战舰的建造，准备对暴风城发动武装袭击。虽然贵族议会将这些窃贼视为乌合之众，但范克里夫却与河爪豺狼人、海盗以及各路恶棍结盟，将一个心怀怨恨的工会变成了一支意图摧毁君主制的军队。"}},faq={{q="艾德温·范克里夫是谁？",a="他是迪菲亚潜行者的幕后主使，也是石匠工会的前任会长。他是一位大师级的建筑师，曾在第一次战争中部落摧毁暴风城后，负责重建这座城市。",al={"范克里夫是谁","艾德温·范克里夫背景故事","范克里夫的身份"}},{q="为什么石匠工会要反抗暴风城？",a="暴风城重建完成后，贵族议会因王国背负巨额债务而拒绝支付石匠工会约定的工资。当范克里夫和工人们进行抗议时，贵族们解散了工会，从而在街头引发了暴力骚乱。",al={"为什么迪菲亚要反叛","石匠为什么暴乱","迪菲亚暴乱原因"}},{q="艾德温·范克里夫藏在哪里？",a="他盘踞在西部荒野的死亡矿井最深处的圣所，指挥着迪菲亚潜行者，据传通往那里的入口位于安静的月溪镇。",al={"范克里夫在哪","范克里夫位置","死亡矿井首领位置"}},{q="他和Mathias Shaw有什么关系？",a="Mathias Shaw是艾德温的童年好友。Shaw亲自教导范克里夫潜行、窃盗和战斗的艺术，最初他曾希望范克里夫能加入王室情报机构军情七处。",al={"范克里夫和shaw","范克里夫和shaw有关联吗","mathias shaw的朋友"}},{q="巴基尔·斯瑞德在暴乱中发生了什么？",a="在暴乱期间，范克里夫的副手也是他最信任的助手巴基尔·斯瑞德被俘并被关押在监狱中。在等待审判和审讯的过程中，斯瑞德在监狱里几乎被人遗忘，而范克里夫则带着石匠工会离开了城市。",al={"巴基尔·斯瑞德是谁","范克里夫的副手","巴基尔·斯瑞德暴乱"}},{q="他在死亡矿井里建造什么？",a="传言称迪菲亚潜行者招募了聪明的地精，在死亡矿井底部建造某种可怕的东西，但具体是什么尚不清楚。",al={"死亡矿井战舰","死亡矿井里有什么","范克里夫的战舰"}}},fx={["7e824b42"]={q="艾德温·范克里夫效忠于哪一方？",a="艾德温·范克里夫只效忠于迪菲亚潜行者——这个由前石匠工会的流亡者组成、由他创立的叛乱组织。他反对贵族议会和暴风城王室，认为整个王国都背弃了他的工匠。他不效忠联盟或部落，而是作为一名亡命策划者，执意发动自己的复仇之战。",al={"艾德温·范克里夫的效忠对象","艾德温·范克里夫为谁而战","范克里夫属于联盟还是部落"}},["01cc4ddf"]={q="艾德温·范克里夫想要什么？",a="范克里夫寻求向暴风城王国彻底复仇。他耗费多年重建首都，腐败的贵族议会却拒绝付款，夺走石匠工会赖以谋生的生计；此后他发誓要让整个王国为背叛付出代价。他企图突破城市防御、击溃贵族，并通过武装叛乱和公开破坏，为遭到流放的工匠复仇。",al={"范克里夫的目标","艾德温·范克里夫的目标是什么","范克里夫为何攻击暴风城"}},["5f8574b7"]={q="艾德温·范克里夫为何令人畏惧？",a="暴风城将范克里夫视为威胁其安全的最大祸患之一，因为他兼具高超的建筑知识和致命的盗贼本领。他设计过保护首都的防御工事，因此熟知王国防线的每一处弱点。他麾下有庞大而凶狠的犯罪网络，且在死亡矿井中筑有重重防御；凭借充足的火力、人手和狡诈，他足以令年幼国王的王国屈服。",al={"范克里夫为何出名","艾德温·范克里夫为何令人畏惧","艾德温·范克里夫的威胁"}}},fp="14,354,24.458.0,28.565.0,28.516.1,22.202.0,49.258.0,31.164.1,39.205.0,46.243.0,37.169.1"}
P.entries["npc:einar-stonegrip"] = {n="埃纳尔·石钳",s="埃纳尔·石钳是一名驻扎在湿地主要十字路口的矮人猎手。为了避免与他分居的妻子在米奈希尔港见面而引发尴尬的重逢，他只能依靠路过的冒险者将鳄鱼皮运送到镇上。",h="埃纳尔·石钳是一名驻扎在湿地主要十字路口的矮人猎手。为了避免与他分居的妻子在米奈希尔港见面而引发尴尬的重逢，他只能依靠路过的冒险者将鳄鱼皮运送到镇上。",kw={"鳄鱼","埃纳尔·石钳","詹姆斯·哈洛兰","米奈希尔港","塞达","皮革","猎手","湿地"},ang={["faction:Alliance"]="往返于铁炉堡和米奈希尔港的旅行者经常会经过埃纳尔的路边哨所，这为联盟补给线上的传递工作提供了便利。",["race:Dwarf"]="埃纳尔反映了矮人登山者普遍具有的坚韧和自立精神，尽管婚姻问题迫使他不得不睡在潮湿的沼泽地里，而不是温暖的酒馆中。"},sec={{t="十字路口的猎手",b="埃纳尔·石钳驻扎在连接丹奥加兹、丹莫德和米奈希尔港的中央路口，靠在湿地的泥沼中冒险来谋生。他狩猎当地的鳄鱼以获取坚韧的皮革，供给海岸边的制皮师和商人们。虽然他有着能从泥潭中徒手制服爬行动物的强悍体魄，但却被家庭纠纷压得喘不过气来。由于与妻子塞达闹翻，关系极其紧张，埃纳尔宁愿一直待在外面，雇佣旅行者将捆扎好的皮货送到他的商业伙伴詹姆斯·哈洛兰手中，也不愿亲自踏入米奈希尔港半步。"}},faq={{q="埃纳尔·石钳是谁？",a="埃纳尔·石钳是一名矮人剥皮师兼猎手，驻扎在湿地的十字路口。他以采集鳄鱼皮并在米奈希尔港出售为生。",al={"埃纳尔是谁","埃纳尔·石钳背景故事","湿地 矮人 十字路口"}},{q="为什么埃纳尔不亲自把货物送到米奈希尔港？",a="埃纳尔与住在米奈希尔港的妻子塞达关系极度恶劣。为了避免面对她的怒火，他宁愿留在沼泽地里，花钱雇佣路过的信使来运送他的贸易货物。",al={"为什么埃纳尔不去镇上","埃纳尔·石钳的妻子","为什么要雇佣冒险者"}},{q="埃纳尔在米奈希尔港与谁共事？",a="埃纳尔为詹姆斯·哈洛兰收集鳄鱼皮，后者是米奈希尔港的一名商人，负责皮革制品的销售和分销。",al={"埃纳尔的商业伙伴","谁购买埃纳尔的皮革","与詹姆斯·哈洛兰的关系"}}},fx={["2e6b6b46"]={q="埃纳尔·石钳效忠于哪一方？",a="埃纳尔忠于铁炉堡和联盟。他驻扎在湿地的十字路口附近，与其他山地巡逻员并肩行动，并为米奈希尔港的聚落提供贸易货物。",al={"埃纳尔·石钳所属阵营","埃纳尔·石钳为谁效力","埃纳尔属于联盟还是部落"}},["61290d18"]={q="埃纳尔·石钳想要什么？",a="埃纳尔想继续向米奈希尔港的詹姆斯·哈洛兰供应鳄鱼皮，又不必亲自前往。他急于找到路过的旅人，替他送去货物包裹，这样他就能拖延面对妻子塞达的时间。",al={"埃纳尔想要什么","埃纳尔·石钳的目标","埃纳尔·石钳的任务动机"}}},fp="15,245,27.596.0,23.165.0,57.206.0,44.147.0"}
P.entries["npc:eitrigg"] = {n="伊崔格",s="伊崔格是一位经验丰富的战士，曾参加过第一次和第二次战争，目前在奥格瑞玛担任大酋长萨尔备受尊敬的顾问。他曾是黑石氏族的战士，后来对旧部落的恶魔行径感到失望，并开始了流亡生活，直到与一位人类圣骑士之间产生了非凡的友谊，彻底改变了他的命运。如今，他协助引导新部落重回荣誉与萨满教义的道路。",h="伊崔格是一位经验丰富的战士，曾参加过第一次和第二次战争，目前在奥格瑞玛担任大酋长萨尔备受尊敬的顾问。他曾是黑石氏族的战士，后来对旧部落的恶魔行径感到失望，并开始了流亡生活，直到与一位人类圣骑士之间产生了非凡的友谊，彻底改...",kw={"黑石氏族","血与荣耀","伊崔格","grommash hold","壁炉谷","orgrim doomhammer","奥格瑞玛","斯坦索姆","萨尔","提里奥·弗丁"},ang={["class:Paladin"]="伊崔格和提里奥·弗丁的故事在圣骑士中广为流传，被视为职责与正义荣誉之间终极考验的典范。",["class:Warrior"]="伊崔格代表着在数十年的悲剧岁月中得以留存的尚武荣誉，他凭借纯粹的力量和不屈的纪律在两场战争中幸存了下来。",["faction:Horde"]="伊崔格是部落活着的集体记忆，他站在萨尔身边，以确保恶魔腐化时代的错误永不重演。",["race:Orc"]="对于杜隆塔尔的兽人来说，伊崔格是一位受人尊敬的长者，他的黑石氏族出身证明了任何兽人都能拥抱荣誉并救赎他们民族的遗产。"},sec={{t="旧部落的老兵",b="伊崔格出生于德拉诺的黑石氏族，曾为部落参加了第一次和第二次战争。惨烈的战斗和部落在第二次战争中的最终战败，迫使他直面自己的族人已经堕落到何种地步——那是嗜血和恶魔腐蚀的深渊。对部落的现状感到厌恶，伊崔格离开了四散的残部，选择了自我流放，只求在洛丹伦的荒野中寻找宁静。"},{t="血与荣耀",b="在荒野中流亡多年后，伊崔格在壁炉谷附近一座废弃的哨塔里避难时，被人类圣骑士提里奥·弗丁发现。他们最初的冲突导致遗迹倒塌，但伊崔格没有终结昏迷的人类，而是将他从瓦砾中救出。提里奥被这种纯粹的尚武荣誉所感动，发誓要与这位隐士保持友谊，并拒绝泄露他的藏身之处。当当地的联盟当局最终抓获伊崔格并判处他在斯坦索姆绞刑时，提里奥放弃了自己的骑士头衔、领地和自由，发起了一场营救这位兽人的突袭。这段传奇的羁绊向两位战士证明，荣誉超越了他们种族之间刻骨铭心的仇恨。"},{t="大酋长的顾问",b="在提里奥试图在斯坦索姆营救伊崔格的绝望过程中，萨尔率领新组建的部落突袭了城市，并将这位年迈的战士救出。与萨尔的会面让伊崔格相信，兽人已经摆脱了恶魔的腐蚀，并重新发现了他们古老的萨满传统。伊崔格随萨尔跨越无尽之海回到卡利姆多，在奥格瑞玛的智慧谷担任了一个受人尊敬的职位。他现在站在Grommash Hold内，担任年轻大酋长的顾问，协助评估新兵，并传授他来之不易的智慧，以确保新部落永远不会重蹈过去的覆辙。"}},faq={{q="伊崔格是谁？",a="伊崔格是一位年长的黑石氏族兽人战士，曾参加过第一次和第二次战争。如今，他居住在奥格瑞玛的Grommash Hold，担任大酋长萨尔值得信赖的参谋和顾问。",al={"伊崔格是谁","伊崔格背景故事","萨尔身边的兽人"}},{q="为什么伊崔格把一个人类视为兄弟？",a="在洛丹伦流亡期间，伊崔格在一场导致石塔坍塌的决斗中救了圣骑士提里奥·弗丁的性命。作为回报，提里奥保守了伊崔格的藏身地点，后来还在斯坦索姆为了阻止伊崔格被处决而与自己的人民战斗，为此失去了爵位和领地。在相互认可的荣誉约束下，伊崔格视提里奥为兄弟。",al={"伊崔格和提里奥","伊崔格的人类朋友","血与荣耀"}},{q="伊崔格属于哪个氏族？",a="伊崔格属于黑石氏族。他经历过旧时代的战争，但在目睹了引导部落的恶魔腐蚀后，他抛弃了部落腐化的残部。",al={"伊崔格氏族","伊崔格是黑石氏族吗"}},{q="伊崔格为什么要离开旧部落？",a="在第二次战争中部落战败后，伊崔格看到他的族人因嗜血和恶魔腐蚀而丧失了荣誉。他厌恶地离开了，与其为一个腐败的战争机器效力，不如寻找一个安静的地方等待终结。",al={"为什么伊崔格要离开","伊崔格流亡"}},{q="伊崔格是如何来到奥格瑞玛的？",a="当联盟军队抓获伊崔格并准备在斯坦索姆处决他时，萨尔率领部队突袭了城市并将他解救出来。在看到萨尔对荣誉的承诺和对萨满教义的重新发掘后，伊崔格选择跟随年轻的大酋长前往卡利姆多。",al={"伊崔格如何遇见萨尔","伊崔格营救"}},{q="伊崔格现在在奥格瑞玛担任什么角色？",a="伊崔格直接在Grommash Hold为萨尔提供建议，并协助测试和评估向新部落宣誓效忠的新兵。",al={"伊崔格任务","伊崔格做什么"}}},fx={["53b3cb4d"]={q="伊崔格效忠于哪一方？",a="伊崔格全心效忠于萨尔的新部落。他曾为旧日嗜血的部落而战，但看清其恶魔远征背后的腐化后便离开了它。如今，他在Grommash Hold辅佐并守护萨尔，忠心耿耿；他相信这种新的萨满愿景能为兽人带来荣誉与救赎。",al={"伊崔格所属阵营","伊崔格为谁效力","伊崔格是否忠于萨尔"}},f3c80f4d={q="伊崔格想要什么？",a="伊崔格希望兽人能以荣誉引领自身，而不是重蹈过去的黑暗覆辙。他目睹了暗影议会的欺诈，也曾流亡在外，如今将余生奉献给辅佐大酋长萨尔，并培养一代守纪、有原则的部落战士来守护家园。",al={"伊崔格的目标是什么","伊崔格的动机","伊崔格的愿望是什么"}},["46467f44"]={q="伊崔格为何闻名？",a="在老兵之中，伊崔格以黑石兽人战士的身份闻名，曾历经第一次和第二次战争。他幸存下来、在斯坦索姆从行刑中被戏剧性地救出，并与人类圣骑士提里奥·弗丁结下深厚的荣誉之谊，这些经历让他名留传说。",al={"伊崔格为何广为人知","伊崔格因何成名","伊崔格的战争经历"}}},fp="7,388,26.445.0,15.714.0,25.608.0,15.190.0,46.363.0,33.177.0,36.219.0,36.259.0,51.139.0"}
P.entries["npc:elanaria"] = {n="艾兰娜瑞",s="艾兰娜瑞是一位暗夜精灵战士导师和协调员，驻扎在达纳苏斯的战士区。她指导整个卡利姆多的后起之秀，通过对抗萨特沃拉斯·邪蹄等危险威胁以及埃鲁拉之影等灵魂实体来磨练他们的战斗技艺。她的指导为在暗夜精灵首都打磨战斗技巧的联盟士兵们架起了一座关键的桥梁。",h="艾兰娜瑞是一位暗夜精灵战士导师和协调员，驻扎在达纳苏斯的战士区。她指导整个卡利姆多的后起之秀，通过对抗萨特沃拉斯·邪蹄等危险威胁以及埃鲁拉之影等灵魂实体来磨练他们的战斗技艺。她的指导为在暗夜精灵首都打磨战斗技巧的联盟士兵...",kw={"达纳苏斯","艾兰娜瑞","埃鲁拉之影","铁匠马希尔","泰达希尔","沃拉斯·邪蹄","战士任务","战士区"},ang={["class:Warrior"]="艾兰娜瑞是战士区的一位重要联络人，她会分配等级适宜的武道试炼，这些试炼会奖励坚固的装备并提升战术战斗技巧。",["faction:Alliance"]="从泰达希尔的首都出发，艾兰娜瑞帮助维持军事战备，并武装那些保卫卡利姆多北部联盟利益的士兵们。",["race:NightElf"]="代表着达纳苏斯的武道传统，艾兰娜瑞致力于清除卡多雷祖先领地上的萨特和不安的阴影等腐化实体。"},sec={{t="战士区的哨兵",b="艾兰娜瑞自豪地站在达纳苏斯树冠内的战士区，担任武道冠军的导师和联络人。在暗夜精灵正式加入大联盟的时代，她的职责不仅是指导当地的哨兵，还要为各种背景的战士做好准备，以应对这片土地所面临的严酷挑战。"},{t="钢铁与精神的试炼",b="艾兰娜瑞从不轻易夸奖他人；她要求纪律、韧性和被证实的实力。她指派经验丰富的冒险者去击败蹂躏泰达希尔和黑海岸的强大敌人，包括腐化的萨特沃拉斯·邪蹄和麻烦的灵魂如埃鲁拉之影。她还与铁匠马希尔等熟练的工匠保持联络，以确保值得信赖的战士们拥有合适的武装来投入战争。"}},faq={{q="艾兰娜瑞是谁？",a="艾兰娜瑞是一位位于达纳苏斯战士区的暗夜精灵。她担任武道任务发布者，指派新晋战士在卡利姆多北部进行战斗试炼。",al={"艾兰娜瑞 达纳苏斯","艾兰娜瑞是谁","艾兰娜瑞 npc"}},{q="我在哪里可以找到艾兰娜瑞？",a="她位于战士区，这是达纳苏斯北部的一处高地区域，专门用于城市的军事训练和防御。",al={"艾兰娜瑞 位置","艾兰娜瑞在哪里","艾兰娜瑞 地点"}},{q="艾兰娜瑞提供什么任务？",a="艾兰娜瑞是中级战士进阶的关键人物，提供诸如猎杀萨特沃拉斯·邪蹄、对抗埃鲁拉之影以及与铁匠马希尔等当地护甲师协作等任务。",al={"艾兰娜瑞 任务","艾兰娜瑞的任务","艾兰娜瑞 战士任务"}},{q="为什么艾兰娜瑞要派遣战士去对付沃拉斯·邪蹄？",a="沃拉斯·邪蹄是一个危险的萨特，他的恶魔腐化威胁着北方的荒野。艾兰娜瑞指派有能力的战士去击杀他，既是为了守护森林，也是为了证明他们在战场上的英勇。",al={"艾兰娜瑞 沃拉斯","沃拉斯·邪蹄任务","为什么要杀沃拉斯·邪蹄"}},{q="铁匠马希尔是谁？",a="铁匠马希尔是驻扎在达纳苏斯的一位护甲大师。艾兰娜瑞将战士们引荐给马希尔，以便他们能制造或获得适合前线战斗的专业武装装备。",al={"马希尔联系人","铁匠马希尔 战士","艾兰娜瑞和马希尔"}},{q="艾兰娜瑞会与非暗夜精灵互动吗？",a="会。作为联盟的一员，艾兰娜瑞协助所有前来战士区寻求指导和专业训练的符合条件的联盟战士。",al={"人类可以和艾兰娜瑞对话吗","联盟战士 艾兰娜瑞"}}},fx={de8f39db={q="艾兰娜瑞效忠于哪一方？",a="艾兰娜瑞坚定地支持达纳苏斯的暗夜精灵及更广泛的联盟。她居住在首都的战士区，指引并派遣有能力的战士保卫他们的土地，抵御迫近的威胁。",al={"艾兰娜瑞所属阵营","艾兰娜瑞为谁效力","艾兰娜瑞的效忠对象"}},d7c0e558={q="艾兰娜瑞想要什么？",a="艾兰娜瑞寻求愿意守护卡利姆多、肃清腐化邪恶的老练战士。她派遣勇士消灭危险敌人，包括萨特沃卢斯·邪蹄；她也会将有潜力的新兵引荐给铁匠马希尔等技艺精湛的工匠，确保他们做好战斗准备。",al={"艾兰娜瑞需要什么","艾兰娜瑞的职责","艾兰娜瑞的动机"}},["16a563e6"]={q="艾兰娜瑞为何在达纳苏斯？",a="艾兰娜瑞驻守达纳苏斯的战士区，担任暗夜精灵首都战士们的导师和协调者。从这个军事据点，她可以轻松评估来访冒险者的实力，并派遣他们前往最需要其刀剑之处。",al={"艾兰娜瑞为何在这里","艾兰娜瑞为何在战士区","艾兰娜瑞所在位置的原因"}}},fp="8,400,25.365.0,25.410.0,16.181.0,26.148.0,32.219.0,56.207.0,21.184.0,44.156.0"}
P.entries["npc:elder-bloodhoof"] = {n="血蹄长者",s="血蹄长者是一位先祖之魂，栖息在莫高雷血蹄村的北边。他在春节期间会显现给旅行者们，是血蹄部族备受尊崇的守护之灵。",h="血蹄长者是一位先祖之魂，栖息在莫高雷血蹄村的北边。他在春节期间会显现给旅行者们，是血蹄部族备受尊崇的守护之灵。",kw={"先祖","血蹄村","血蹄长者","春节","莫高雷","赤色石","牛头人灵魂"},ang={["class:Shaman"]="萨满祭司将血蹄长者视为先祖崇拜的化身，证明了先祖之灵是如何在物质世界指引并保护他们的后代的。",["race:Tauren"]="对于牛头人朝圣者来说，向血蹄长者致敬是与部族血脉的直接交流，以纪念那些在雷霆崖建立之前就漫步于莫高雷的先辈们的牺牲。"},sec={{t="先祖之魂",b="血蹄长者代表了牛头人与其血脉之间深厚的精神纽带。这位幽灵般的长者显现在血蹄村附近，守护着他的人民，并会奖赏在春节期间寻求智慧的恭敬旅者。他的存在加强了已故酋长和部落先辈们的长久指引，他们的灵魂与莫高雷的平原紧密相连。"}},faq={{q="谁是血蹄长者？",a="血蹄长者是一位幽灵般的牛头人灵魂，显现在莫高雷血蹄村的北边。他代表了血蹄部族受人尊敬的先祖，在春节这样的季节性传统节日期间，为拜访他的旅者提供祝福和古老的智慧。",al={"血蹄长者背景故事","血蹄村外的幽灵是谁","血蹄长者身份"}},{q="什么时候可以见到血蹄长者？",a="血蹄长者主要在一年一度的春节期间显现，他作为一位长者之灵提供节日祝福。",al={"血蹄长者在哪里","血蹄长者失踪","如何找到血蹄长者"}},{q="他与血蹄村有什么联系？",a="作为一位承载着氏族名号的受尊崇先祖，血蹄长者守护着血蹄村这处先祖定居点。在牛头人的传统中，先祖之灵停留在后代居住和聚集的地方具有深远的意义。",al={"他为什么在血蹄村附近","血蹄长者与凯恩的关系"}}},fx={["376494a8"]={q="血蹄长者效忠于哪一方？",a="血蹄长者是受人敬仰的血蹄牛头人先祖，也是部落的盟友。作为春节期间受到敬奉的先祖之魂之一，他会向缅怀他、尊崇其人民神圣传统的旅人赐予祝福和智慧。",al={"血蹄长者所属阵营","血蹄长者是否属于部落","血蹄长者为谁效力"}},f5643df0={q="血蹄长者想要什么？",a="血蹄长者希望生者记得并敬重他。春节期间，旅人寻访卡利姆多的古老先祖之魂时，他会赐予祝福、先祖硬币和箴言，以回应你对他的敬意和对往昔的铭记。",al={"血蹄长者的目标","血蹄长者想要什么","为何要与血蹄长者交谈"}},["2e395d43"]={q="血蹄长者为何在莫高雷？",a="他的灵魂徘徊在血蹄村以北，因为这片草原是他部族的祖居之地。他从死亡帷幕的另一端守望子孙，每年都会回到血蹄族生活和放牧的土地。",al={"血蹄长者为何在这里","血蹄长者为何在血蹄村外","血蹄长者所在位置的原因"}}},fp="15,221,23.396.0,23.275.0,33.131.0,44.246.0"}
P.entries["npc:elder-bronzebeard"] = {n="铜须长者",s="铜须长者是一位古老的土灵之魂，在春节期间会出现在铁炉堡的Mystic Ward。他承袭了统治这座城市的氏族之名，他的幽灵之躯架起了现代矮人与他们那石造先祖之间的桥梁。",h="铜须长者是一位古老的土灵之魂，在春节期间会出现在铁炉堡的Mystic Ward。他承袭了统治这座城市的氏族之名，他的幽灵之躯架起了现代矮人与他们那石造先祖之间的桥梁。",kw={"先祖","土灵","铜须长者","铁炉堡","春节","麦格尼","mystic ward"},ang={["faction:Alliance"]="春节期间访问铁炉堡的联盟朝圣者会发现这位代表着矮人王国基石的长者。",["race:Dwarf"]="对于矮人来说，会见铜须长者提供了一次难得的、直观审视其土灵祖先的机会，也印证了探险者协会正在发掘的历史发现。"},sec={{t="Mystic Ward中的先祖",b="铜须长者出现在铁炉堡Mystic Ward的水池旁，他并没有现代矮人的血肉之躯；相反，他的幽灵形态是土灵，这是由泰坦用活岩石锻造的古老种族。矮人学者和探险家们才刚刚开始通过在卡兹莫丹及其他地区的发掘来揭开他们的起源，这使得这位先祖之魂成为了一个引人注目的活遗迹。他的名字和形象都表明他是铜须氏族的直系祖先，默默见证着他的石裔后代演化至今的历程。"}},faq={{q="为什么铜须长者看起来像个土灵，而不是普通的矮人？",a="矮人是土灵的后裔，土灵是泰坦用岩石锻造出的古老存在，随着时间的推移，他们变成了血肉生物。由于铜须长者生活在这次转变发生之前的遥远过去，因此他的灵魂保留了土灵时期的岩石形态。",al={"为什么铜须长者是石头做的","铜须长者是土灵吗","铜须长者的种族"}},{q="他与国王麦格尼·铜须有血缘关系吗？",a="虽然古代家族谱系的细节已湮没在历史中，但他的名字和在矮人首都的出现有力地表明，他是铜须氏族受人尊敬的先祖，而铜须氏族正是目前在国王麦格尼统治下管理铁炉堡的家族。",al={"他是麦格尼的祖先吗","麦格尼·铜须的亲属","铜须家族族谱"}},{q="为什么铜须长者会出现在铁炉堡？",a="在春节期间，长者们的灵魂会在艾泽拉斯各地显现，为旅行者赐予智慧和祝福。铜须长者显现在铁炉堡的Mystic Ward，驻足在矮人法师和学者们聚集的宁静水池旁。",al={"铜须长者在这里做什么","铜须长者在哪里","mystic ward的鬼魂"}}},fx={f31842b8={q="铜须长者是谁？",a="铜须长者是一位古老的土灵，徘徊在铁炉堡的秘法区。他显现为岩石般的形态，与泰坦锻造的先祖相仿，而非血肉之躯；他象征着矮人深厚的先祖根源和绵延不绝的血脉。",al={"铜须长者是谁","铜须长者的身份","铜须长者是什么"}},["7b1c25c3"]={q="铜须长者效忠于哪一方？",a="作为一位受人敬仰、身处铁炉堡中心的先祖，铜须长者平和地守望着矮人首都。与所有春节长者一样，他不介入凡人的战争，会向任何前来拜访的旅人和朝圣者致意，不论他们属于哪一方。",al={"铜须长者所属阵营","铜须长者支持哪一方","铜须长者是否属于联盟"}},a81f3e52={q="铜须长者想要什么？",a="铜须长者别无所求，只愿与敬奉古老传统的人们分享交流。作为往昔的游荡之魂，他会向朝圣者致意，也会将自己的祝福赐予恭敬的访客。",al={"铜须长者想要什么","铜须长者的动机","铜须长者为何想要交谈"}}},fp="17,276,31.551.0,75.274.0,40.247.0,38.259.0"}
P.entries["npc:elder-darkcore"] = {n="暗灵长者",s="暗灵长者是一位古老的灵魂，在春节期间会出现在幽暗城上方的洛丹伦废墟王座厅内。他代表着世间受人尊敬的先祖，为前来寻找他的旅人提供祝福和节日代币。他的出现标志着在一座陨落的人类王国遗迹中，那段宁静而令人深思的时刻。",h="暗灵长者是一位古老的灵魂，在春节期间会出现在幽暗城上方的洛丹伦废墟王座厅内。他代表着世间受人尊敬的先祖，为前来寻找他的旅人提供祝福和节日代币。他的出现标志着在一座陨落的人类王国遗迹中，那段宁静而令人深思的时刻。",kw={"先祖","先祖硬币","暗灵长者","春节","洛丹伦废墟","王座厅","幽暗城"},ang={["faction:Alliance"]="拜访暗灵长者需要避开驻守在王都废墟周围的高等级被遗忘者岗哨和皇家卫兵，这使得他成为联盟玩家在节日期间最危险的行程之一。",["race:Undead"]="暗灵长者在距离幽暗城地面升降梯仅几步之遥的地方徘徊，伫立在曾经摧毁洛丹伦王国的土地上。"},sec={{t="王座厅中的灵魂",b="每年的春节期间，远古长者的灵魂都会现身于艾泽拉斯各处，与冒险者们分享他们的智慧。暗灵长者在世界上最阴郁的地方之一进行守望：位于洛丹伦废墟的皇家王座厅，就在幽暗城入口的正上方。在这个泰瑞纳斯·米奈希尔二世国王倒下的血染之地，这位幽灵般的先祖为那些勇敢地进入被遗忘者领土核心以表达敬意的冒险者提供先祖硬币和祝福。"}},faq={{q="暗灵长者是谁？",a="暗灵长者是春节期间显现的受人尊敬的幽灵先祖之一。他出现在幽暗城上方的王座厅，为到访者赐予祝福并赠予先祖硬币。",al={"暗灵长者","暗灵长者是谁"}},{q="在哪里可以找到暗灵长者？",a="他位于王都的废弃王座厅，就在洛丹伦废墟中通往幽暗城的入口坡道正上方。",al={"暗灵长者在哪里","暗灵长者位置","幽暗城长者"}},{q="暗灵长者对联盟有敌意吗？",a="暗灵长者本人是中立的，欢迎所有前来向他致敬的旅人。然而，由于他站在被遗忘者的据点洛丹伦废墟中，联盟冒险者必须小心避开在附近巡逻的敌对卫兵。",al={"联盟可以和暗灵长者对话吗","暗灵长者是部落的吗","幽暗城春节联盟"}},{q="向暗灵长者致敬有什么奖励？",a="向他表达敬意即可完成节日任务以纪念他，并获得一枚先祖硬币作为奖励。",al={"暗灵长者奖励","暗灵长者任务"}}},fx={["3a0e846b"]={q="暗灵长者效忠于哪一方？",a="暗灵长者不参与当今部落与联盟的冲突。作为参与春节庆典、受人敬仰的先祖之魂，他超然于凡俗争斗，欢迎任何尊敬地前来拜访的旅人，不论他们追随哪一面旗帜。",al={"暗灵长者所属阵营","暗灵长者属于部落还是联盟","暗灵的效忠对象"}},["32c6e8a4"]={q="暗灵长者想要什么？",a="在春节期间，暗灵长者希望分享先祖的古老智慧与祝福。他等待旅人向往昔致敬，并向那些尊崇他悠久记忆的人赐予祝福和长者传承的信物。",al={"暗灵长者想要什么","暗灵长者的目的","为何拜访暗灵长者"}},e5445cfd={q="暗灵长者为何在洛丹伦废墟？",a="作为艾泽拉斯各地庆祝春节的一部分，暗灵长者现身于幽暗城上方已成废墟的王座大厅。古老先祖的灵魂会在艾泽拉斯那些历史深厚、饱经哀伤之地显现，让凡人即便身处覆灭的王国，也能与先祖的记忆交流。",al={"暗灵长者为何在幽暗城","洛丹伦废墟与暗灵长者","暗灵长者所在位置的背景"}}},fp="14,358,27.525.0,22.210.0,32.148.0,42.248.0,43.102.0"}
P.entries["npc:elder-goldwell"] = {n="金井长者",s="金井长者是一位徘徊在丹莫罗矮人定居点卡拉诺斯附近的古老土灵之魂。这位备受尊崇的先祖在春节期间现身，代表了现代矮人文明那被遗忘的起源。",h="金井长者是一位徘徊在丹莫罗矮人定居点卡拉诺斯附近的古老土灵之魂。这位备受尊崇的先祖在春节期间现身，代表了现代矮人文明那被遗忘的起源。",kw={"先祖","丹莫罗","土灵","金井长者","卡拉诺斯","春节"},ang={["faction:Alliance"]="途经卡拉诺斯的联盟旅者常会寻找金井长者，以表达他们的敬意并获得传统的好运祝福。",["race:Dwarf"]="对于矮人而言，觐见金井长者提供了一个难得的机会，可以直观地了解他们古老的岩石锻造传承，以及连接现代铁炉堡与土灵的血脉渊源。"},sec={{t="土灵之魂",b="金井长者以半透明土灵之魂的形态显现，守护着卡拉诺斯的雪坡。与拥有血肉之躯的现代矮人不同，他那岩石般的形体呼应了铜须氏族所源出的远古泰坦造物种族。他在先祖庆典期间的现身，让旅者们有机会缅怀那古老的传承。"}},faq={{q="金井长者是谁？",a="金井长者是一位出现在丹莫罗的土灵先祖之魂。他在每年的先祖节庆期间造访卡拉诺斯，让现代旅者能够向矮人一族的先祖致敬。",al={"金井长者身份","金井长者是谁","金井长者背景故事"}},{q="金井长者位于何处？",a="他出现在丹莫罗的矮人城镇卡拉诺斯外，通常位于当地旅店和聚集区附近。",al={"金井长者位置","如何找到金井长者","寻找金井长者"}},{q="为什么金井长者看起来像是土灵而不是矮人？",a="矮人的祖先可以追溯到泰坦创造的岩石皮肤土灵。作为缅怀过去世代最古老的先祖之魂之一，金井长者保留了最初的土灵形象，而非现代矮人那种凡人的血肉之躯。",al={"为什么金井长者是土灵","金井长者是土灵吗","金井长者岩石矮人"}}},fp="14,232,23.344.0,22.202.0,32.124.0,65.240.0"}
P.entries["npc:elder-graveborn"] = {n="灰石长者",s="灰石长者是一位在春节期间显现于布瑞尔东南方的先祖之魂。他以土灵长者的幽灵形态现身，以此向旅者致意，并指引那些寻找散布在洛丹伦北部各地的其他古老之魂的朝圣者。",h="灰石长者是一位在春节期间显现于布瑞尔东南方的先祖之魂。他以土灵长者的幽灵形态现身，以此向旅者致意，并指引那些寻找散布在洛丹伦北部各地的其他古老之魂的朝圣者。",kw={"先祖","布瑞尔","土灵","灰石长者","春节","提瑞斯法林地"},ang={["faction:Alliance"]="联盟朝圣者必须小心避开布瑞尔的边缘地带，才能在不引起被遗忘者城镇卫兵和巡逻队愤怒的情况下，向灰石长者表示敬意。",["race:Undead"]="对于行走在布瑞尔与幽暗城之间道路上的被遗忘者而言，灰石长者是一个宁静的象征，提醒着人们艾泽拉斯那不受天灾军团或瘟疫干扰的古老过去。"},sec={{t="提瑞斯法林地的幽灵",b="灰石长者现身于被遗忘者城镇布瑞尔外，伫立在提瑞斯法林地的闹鬼森林中，作为全球春节庆典的一部分。尽管周围环境深受瘟疫侵蚀，且王国饱受苦难，这位幽灵长者仍向寻求节日传统祝福的旅者们致以和平的问候。除了传授自己的先祖智慧外，灰石长者还会分享有关附近其他长者的消息——为朝圣者指明幽暗城、瑟伯切尔以及整个瘟疫之地中那些长者所在的方位。"}},faq={{q="灰石长者是谁？",a="灰石长者是一位受人尊敬的先祖之魂，会在春节期间出现。他显现在提瑞斯法林地，布瑞尔的东南方，为路过的冒险者赐予节日祝福。",al={"灰石长者背景故事","灰石长者是谁","布瑞尔幽灵长者"}},{q="他为什么在提瑞斯法林地？",a="在春节期间，先祖之魂会出现在艾泽拉斯各地，以纪念过去的英雄和共同的传承。灰石长者守望着布瑞尔之外的土地，在陷落的洛丹伦王国中维持着一种古老的存在。",al={"为什么在布瑞尔","灰石长者在哪里"}},{q="联盟冒险者能和他交谈吗？",a="可以。节日长者欢迎双方阵营的旅者，无论身处何地。不过，联盟角色在接近他所在的安息之地时必须保持警惕，因为他所处的位置非常靠近被遗忘者的中心地带布瑞尔。",al={"联盟可以和灰石长者交谈吗","布瑞尔的联盟长者"}},{q="他为旅者提供什么信息？",a="灰石长者指引朝圣者寻找当地的其他先祖，并分享有关盘踞在幽暗城、银松森林的瑟伯切尔、圣光之愿礼拜堂、哭泣之洞和通灵学院的幽灵的传闻。",al={"灰石长者位置指引","灰石长者语录"}}},fx={a72aed3e={q="灰石长者想要什么？",a="在春节期间，灰石长者希望将古老的祝福与先祖智慧分享给游历各地的人们。作为重返世间、守护世界遗产的土灵之魂，他请旅人向往昔致敬，赐予他们祝福，并指引他们去寻找散布在大陆各地的其他受尊崇的长者。",al={"灰石长者的目标","为何拜访灰石长者","灰石长者想要什么"}},["066af8bb"]={q="灰石长者与谁有关联？",a="灰石长者知道其他几位先祖之魂的所在。他会指引旅人去寻找幽暗城的暗灵长者、瑟伯切尔附近的 Obsidian、圣光之愿礼拜堂的 Snowcrown、哭泣之洞的 Meadowrun，以及通灵学院的 Moonstrike。",al={"灰石长者的人际关系","灰石长者认识谁","灰石长者的关联"}}},fp="15,259,20.543.0,23.194.0,29.240.0,38.230.0,41.194.0"}
P.entries["npc:elder-morningdew"] = {n="晨露长者",s="晨露长者是一位古老的暗夜精灵之魂，会在春节期间现身于千针石林。她向那些在闪光平原干旱的峡谷与干涸盐碱地中寻找她的旅行者们提供智慧与先祖的祝福。",h="晨露长者是一位古老的暗夜精灵之魂，会在春节期间现身于千针石林。她向那些在闪光平原干旱的峡谷与干涸盐碱地中寻找她的旅行者们提供智慧与先祖的祝福。",kw={"先祖","长者","晨露长者","鬼魂","春节","暗夜精灵","千针石林"},ang={["race:NightElf"]="对于卡多雷来说，寻找像晨露长者这样的古老长者是一种神圣的敬意职责，将现代的暗夜精灵与他们之前受人尊敬的灵魂联系在了一起。",["race:Tauren"]="牛头人深深地尊崇先祖之魂，因此在卡利姆多各地与长者相遇，是他们对过去智慧文化崇敬的自然延伸。"},sec={{t="节日受人尊敬的灵魂",b="在整个春节期间，受人敬仰的先祖之魂会显现在卡利姆多和东部王国各地，以庆祝智慧、传承与和平。晨露长者就是其中一位显灵者，她造访千针石林来迎接前来致敬的朝圣者。她不受阵营或凡人冲突的束缚，会向任何怀着敬意寻求她指引并接受她祝福的冒险者赠予先祖硬币。"}},faq={{q="晨露长者是谁？",a="晨露长者是一位在一年一度的春节期间显灵的暗夜精灵先祖之魂。她在千针石林等待着联盟与部落的旅行者们前来致敬。",al={"晨露长者背景故事","晨露长者是谁","晨露长者身份"}},{q="寻找她的目的是什么？",a="冒险者们会在春节期间寻找她，以表达对先祖的敬意，并通过尊崇她的灵魂来换取一枚先祖硬币和智慧的祝福。",al={"为什么寻找晨露长者","晨露长者目的","春节长者"}},{q="她属于联盟还是部落？",a="像所有的春节长者一样，晨露长者对凡人的政治保持中立。联盟和部落的冒险者都可以平静地接近她，向她致敬。",al={"晨露长者是否有敌意","晨露长者阵营","部落可以与晨露长者交谈吗"}}},fp="16,246,33.411.0,24.191.0,39.181.0,41.170.0"}
P.entries["npc:elder-obsidian"] = {n="黑曜石长者",s="黑曜石长者是一位先祖土灵，在每年的春节期间会现身于银松森林的瑟伯切尔。他出现在被遗忘者所占据的墓地之中，为前来庆祝节日的旅行者们提供来自远古世界的智慧与祝福。",h="黑曜石长者是一位先祖土灵，在每年的春节期间会现身于银松森林的瑟伯切尔。他出现在被遗忘者所占据的墓地之中，为前来庆祝节日的旅行者们提供来自远古世界的智慧与祝福。",kw={"先祖","先祖硬币","土灵","黑曜石长者","春节","瑟伯切尔","银松森林"},ang={["faction:Alliance"]="想要寻找黑曜石长者的联盟朝圣者必须小心行事，因为他选择的驻留点位于被遗忘者定居点瑟伯切尔的中心地带。",["race:Dwarf"]="对于那些对泰坦造物血统感到好奇的矮人来说，与黑曜石长者这样的土灵交谈，能提供一次难得的机会，让他们一窥其石刻祖先的原始过去。"},sec={{t="瑟伯切尔的灵体",b="黑曜石长者伫立在瑟伯切尔阴郁的墓群之中，与银松森林灰暗的广袤大地形成了鲜明的对比。作为一位空灵的土灵长者，他的灵魂在春节期间现身，以纪念艾泽拉斯的远古传承。尽管周遭的地下墓穴被被遗忘者所占据，且受到狂野狼人的威胁，黑曜石长者仍以和平的态度迎接各阵营的路人，并向那些抽空寻访他智慧的人们赠予先祖硬币和古老的祝福。"}},faq={{q="谁是黑曜石长者？",a="黑曜石长者是一位出现在银松森林的远古土灵之魂。他仅在春节期间现身，迎接那些纪念世界先祖传承的旅行者。",al={"黑曜石长者背景故事","谁是黑曜石","瑟伯切尔长者"}},{q="在哪里可以找到黑曜石长者？",a="他可以在瑟伯切尔的墓地区域找到。瑟伯切尔是一个由被遗忘者控制的村落，坐落在银松森林中央的道路旁。",al={"黑曜石长者位置","黑曜石在哪里","寻找黑曜石长者"}},{q="为什么一位土灵长者会出现在银松森林？",a="在春节期间，远古长者的灵魂会在艾泽拉斯各地的土地上显现，分享他们的先祖智慧。黑曜石长者的灵体存在超越了当地的领土冲突，使他得以在古老的墓穴中静谧地交流。",al={"为什么黑曜石在银松森林","银松森林的土灵"}},{q="联盟冒险者可以与黑曜石长者交谈吗？",a="可以。节日长者对所有旅行者保持中立，无论阵营如何。然而，由于他驻留在瑟伯切尔，联盟冒险者必须小心避开驻扎在附近的敌对被遗忘者卫兵才能接近他。",al={"联盟可以访问黑曜石长者吗","黑曜石长者对联盟友好吗"}}},fx={cd669d85={q="黑曜石长者属于哪一方？",a="黑曜石长者超然于联盟与部落之间的凡人纷争之外。作为一位在春节期间重返世间的古老土灵之魂，他会向任何前来向长者致敬的冒险者赐予智慧与先祖祝福，无论对方效忠于哪一方，尽管他显现于被遗忘者聚居地瑟伯切尔附近。",al={"黑曜石长者属于联盟还是部落","黑曜石长者的阵营","黑曜石长者属于哪一方"}},["5cd08f2c"]={q="黑曜石长者想要什么？",a="黑曜石长者希望得到艾泽拉斯凡人的铭记与尊崇。春节庆典期间，他欢迎前来寻访他古老身影的旅人，并向那些向往昔致敬的人赐予祝福和一枚象征先祖庇佑的信物。",al={"黑曜石长者需要什么","黑曜石长者的目标","为何拜访黑曜石长者"}}},fp="14,275,25.494.0,22.188.0,34.153.0,54.251.0,51.227.0"}
P.entries["npc:elder-runetotem"] = {n="符文图腾长者",s="符文图腾长者是一位在春节期间出现在杜隆塔尔剃刀岭外的牛头人先祖之灵。作为春节期间受到尊崇的长者之一，她为那些穿越红色峡谷前来寻找她的旅行者们提供智慧与祝福。",h="符文图腾长者是一位在春节期间出现在杜隆塔尔剃刀岭外的牛头人先祖之灵。作为春节期间受到尊崇的长者之一，她为那些穿越红色峡谷前来寻找她的旅行者们提供智慧与祝福。",kw={"先祖硬币","杜隆塔尔","符文图腾长者","春节","剃刀岭","符文图腾","牛头人鬼魂"},ang={["faction:Horde"]="她伫立在戒备森严的剃刀岭定居点外，她的存在体现了杜隆塔尔的兽人与莫高雷的牛头人之间的精神盟约。",["race:Tauren"]="在远离莫高雷的地方找到一位受人尊敬的符文图腾氏族先祖，这是一个谦卑的提醒，时刻铭记舒哈鲁的灵魂在所有土地上守护着他们的盟友。"},sec={{t="杜隆塔尔之灵",b="尽管牛头人先祖之灵通常与莫高雷的青青草原和神圣的墓地紧密相连，但符文图腾长者却久久徘徊在远离族人牧场的地方。她显现在杜隆塔尔剃刀岭尘土飞扬的定居点旁。对于年轻的兽人和四处游历的冒险者来说，她那空灵的存在如同是一座桥梁，连接着舒哈鲁的古老传统与部落在无尽之海沿岸开辟的艰苦新家园。"},{t="先祖荣耀",b="春节期间，伟大的领袖、萨满祭司和英雄们的灵魂会显现在世界各地，与生者交流。符文图腾长者代表了符文图腾氏族，这是一个以对大地母亲的深刻敬畏和精神交流而闻名的血脉。向她致敬的旅行者将获得先祖徽记和她的精神祝福。"}},faq={{q="符文图腾长者是谁？",a="符文图腾长者是一位显现在杜隆塔尔剃刀岭附近的牛头人先祖之灵。她是春节期间归来以迎接旅行者并赐予先祖祝福的受尊崇长者之一。",al={"符文图腾长者背景故事","剃刀岭的牛头人鬼魂是谁","符文图腾之魂"}},{q="为什么杜隆塔尔会出现牛头人先祖之灵？",a="虽然大多数牛头人先祖之灵扎根于莫高雷，但春节的灵魂会游荡在卡利姆多和东部王国的广阔大地之上。她在剃刀岭的出现，让途经杜隆塔尔的部落旅行者们能够向大地母亲之子们的智慧致以敬意。",al={"为什么符文图腾在剃刀岭","杜隆塔尔的牛头人鬼魂"}},{q="她与符文图腾氏族有什么联系？",a="她冠有符文图腾氏族之名，这是著名的牛头人血脉之一，以其萨满祭司、精神向导以及与自然世界的联系而闻名。",al={"符文图腾氏族长者","符文图腾家族"}},{q="与她交谈能获得什么？",a="在春节期间与符文图腾长者交谈以纪念她，奖励冒险者一枚先祖硬币和来自灵魂的临时祝福。",al={"符文图腾长者提供什么","符文图腾奖励"}}},fx={c76d680b={q="符文图腾长者属于哪一方？",a="符文图腾长者不介入生者之间的战争。作为一位受尊崇的牛头人先祖之魂，她会向任何尊重先祖之道的冒险者，无论其属于部落还是联盟，赐予古老的智慧与祝福。",al={"符文图腾长者属于部落吗","符文图腾长者的阵营","符文图腾长者属于哪一方"}},["021a9c1d"]={q="符文图腾长者想要什么？",a="她希望向途经剃刀岭的旅人传递牛头人对先祖的追忆与敬意。她向生者伸出援手，提醒旅人有先祖之魂守望着这片土地，并让古老传统得以延续。",al={"符文图腾长者寻求什么","为何与符文图腾长者交谈","符文图腾长者的目标"}}},fp="15,259,19.432.0,16.352.0,23.207.0,42.296.0,53.162.0,34.163.0"}
P.entries["npc:elder-skyseer"] = {n="星灵长者",s="星灵长者是一位牛头人先祖的灵魂，居住在千针石林乱风岗高耸的峭壁之上。作为一位从灵界归来的受人尊敬的长者，他注视着部落不断的旅程，并始终与他族人的安息之地紧密相连。",h="星灵长者是一位牛头人先祖的灵魂，居住在千针石林乱风岗高耸的峭壁之上。作为一位从灵界归来的受人尊敬的长者，他注视着部落不断的旅程，并始终与他族人的安息之地紧密相连。",kw={"先祖","星灵长者","乱风岗","赤色石","牛头人幽灵","千针石林"},ang={["class:Shaman"]="作为与元素和灵魂对话的精神调解者，萨满祭司在星灵长者身上看到了那些继续守护着生者的先祖们历久弥新的智慧。",["race:Tauren"]="对于牛头人来说，与星灵长者的邂逅就是与先祖的直接交流，体现了赤色石和莫高雷平原上所传授的精神崇敬。"},sec={{t="乱风岗之灵",b="星灵长者栖居在千针石林盐碱峡谷的高处，徘徊在乱风岗这座风蚀的平顶山定居点。当乱风岗的牛头人在哨所险峻的桥梁和木制平台上忙碌时，星灵长者以一位跨越了凡世面纱的先祖身份守护着这片领域。他成为了那些寻求过去世代智慧的旅行者的先祖灯塔，为那些尊重古老传统的人提供祝福。"},{t="与祖地的联系",b="虽然他的灵魂通常显现在风蚀的石林之间，但星灵长者属于那长久传承的牛头人先祖，他们的族人尊崇莫高雷的神圣土地，在那里，赤色石的先祖之灵守护着部落。像星灵长者这样的灵魂揭示了牛头人的物质世界与先祖之灵之间的隔阂是多么薄弱，他们通过缅怀和仪式引导着未来的世代。"}},faq={{q="谁是星灵长者？",a="星灵长者是一位出现在千针石林乱风岗的牛头人先祖之灵。他是受人尊敬的长者之一，他们的灵魂守护着现代的旅行者，为那些寻找他的人提供先祖的指引。",al={"星灵长者背景故事","谁是星灵长者","星灵长者npc"}},{q="为什么星灵长者是幽灵？",a="他是一位已经离开凡世的古代先祖。牛头人文化与他们的先辈保持着深厚的精神联系，一些杰出的长者会以灵魂的形式徘徊或归来，以指引生者。",al={"为什么星灵长者死了","星灵长者死了吗","乱风岗幽灵牛头人"}},{q="他与莫高雷有什么联系？",a="和所有牛头人先祖一样，星灵长者受到以莫高雷为家园的族人的尊崇，在那里，赤色石的先祖之灵守护着部落。然而，他自己的灵魂却出现在千针石林的乱风岗。",al={"星灵长者赤色石","星灵长者与莫高雷的联系"}},{q="我在哪里可以找到星灵长者？",a="星灵长者位于千针石林的乱风岗，徘徊在峡谷底部上方高处的加固平顶山定居点之上。",al={"星灵长者位置","寻找星灵长者","星灵长者在哪里"}}},fx={e54499fb={q="星灵长者属于哪一方？",a="星灵长者不介入生者之间的战争。他作为一位徘徊于乱风岗风吹日晒的台地上方的牛头人先祖之魂，为任何尊崇他的旅人，无论其属于部落还是联盟，提供来自冥界的先祖指引与智慧。",al={"星灵长者的阵营","星灵长者属于部落吗","星灵长者的效忠对象"}}},fp="13,283,25.461.0,27.413.0,21.223.0,29.221.0,34.219.0,31.136.0"}
P.entries["npc:elder-starweave"] = {n="星纹长者",s="星纹长者是一位在春节期间受人尊崇的暗夜精灵先祖之魂。她栖息在黑海岸多雾的海岸边，位于奥伯丁港口小镇，与路过的朝圣者分享古老时代的智慧。",h="星纹长者是一位在春节期间受人尊崇的暗夜精灵先祖之魂。她栖息在黑海岸多雾的海岸边，位于奥伯丁港口小镇，与路过的朝圣者分享古老时代的智慧。",kw={"先祖","奥伯丁","先祖硬币","黑海岸","星纹长者","春节"},ang={["class:Druid"]="观察这一节日的德鲁伊发现，星纹长者对于天体的思考与塞纳里奥关于重生、记忆以及与自然世界和谐共处的教义不谋而合。",["race:NightElf"]="在黑海岸遇见星纹长者，让卡多雷冒险者能够直接连接上他们的漫长血脉，那些在古代大灾变中仰望艾露恩与群星的先辈们。"},sec={{t="奥伯丁的灯塔",b="星纹长者化作一道虚幻的幽影，出现在奥伯丁的沿海民居之间。她是塞纳里奥议会和卡利姆多各族人民所尊崇的先祖之一。尽管许多旅人穿过港口时行色匆匆，要么赶往内陆，要么准备出海，但那些在她面前驻足的人都会获得先祖的祝福。星纹长者讲述着天体的运行，她观察到现代的星辰正划过陌生的轨迹，为后代子孙指引着希望与坚韧的航向。"}},faq={{q="星纹长者是谁？",a="星纹长者是一位暗夜精灵先祖之魂，会在春节期间出现在奥伯丁，为旅人送上问候、古老的智慧以及先祖硬币。",al={"星纹长者背景故事","星纹长者是谁","长者星纹"}},{q="在哪里可以找到星纹长者？",a="她驻留在黑海岸边，就在奥伯丁定居点附近。",al={"星纹长者在哪里","星纹长者位置","星纹长者地点"}},{q="为什么她以灵魂的形式出现？",a="她是春节期间被唤醒的受尊崇的先祖，以灵魂形态出现，是为了让生者能够向那些塑造了暗夜精灵遥远过去的先辈致敬。",al={"为什么星纹长者是幽灵","星纹长者死了吗","为什么是幽灵"}},{q="部落玩家可以与她交谈吗？",a="可以。春节期间受尊崇的先祖长者欢迎所有阵营的旅人，不过部落冒险者在穿过联盟友好的奥伯丁港口时必须小心行事。",al={"部落可以访问星纹长者吗","部落星纹长者"}}},fx={["2e80733d"]={q="星纹长者属于哪一方？",a="星纹长者不介入生者之间的战争。作为一位安息于黑海岸、受尊崇的暗夜精灵先祖，她会向任何前来寻访她的旅人，无论其属于联盟还是部落，赐予星辰的祝福与智慧。",al={"星纹长者属于联盟吗","星纹长者的阵营","星纹长者为谁效力"}},d8911fea={q="星纹长者为何身在黑海岸？",a="星纹长者作为先祖之魂徘徊于黑海岸，观察世界并指引年轻一代。她注视着不断变换的星座，将天象视作希望与力量的指引，帮助人们迎接未来世代的考验。",al={"星纹长者为何在黑海岸","星纹长者为何在这里","星纹长者的目的"}}},fp="15,224,21.495.0,23.170.0,35.93.0,32.177.0,31.187.0"}
P.entries["npc:eleanor-shackleton"] = {n="Eleanor Shackleton",s="Eleanor Shackleton是一位被遗忘者户外生存专家，她的营地位于提瑞斯法林地布瑞尔的西南方。她没有选择在城镇或幽暗城中逗留，而是致力于帮助流浪的旅行者学习野外生存知识和实地手艺。她与该地区其他幸存的被遗忘者有着相同的姓氏，这暗示了他们在瘟疫爆发前的生活中可能存在某种联系。",h="Eleanor...",kw={"布瑞尔","露营基础知识","eleanor shackleton","shackleton","sticks and bones","the adventurer","the great outdoors","提瑞斯法林地"},ang={["profession:Cooking"]="Eleanor的教学内容涵盖了搭建野外篝火和在远离文明炉火的地方准备食物，这使她的营地成为旅行厨师的关键一站。",["race:Undead"]="对于被遗忘者来说，学会如何在没有生活舒适条件的情况下在野外生存至关重要，而Eleanor确保了新苏醒的同胞能够迅速适应在提瑞斯法林地的艰苦生活。"},sec={{t="林地指南",b="当许多刚苏醒的被遗忘者径直前往布瑞尔或深入幽暗城时，Eleanor Shackleton却在西南方向闹鬼的森林中扎下了营地。在提瑞斯法林地进行野外生存需要务实的独立精神，Eleanor担任着教官的角色，指导那些寻求在被诅咒的土地上生存的新手冒险者。通过各种实地教学，她指导旅行者搭建营地、收集柴火，并在远离文明社会的锻炉和厨房的情况下，维持专业技能的运作。"},{t="过往生活的羁绊",b="在洛丹伦破碎的废墟中，家族姓氏往往是亡灵与生前凡人过去唯一的幸存纽带。Eleanor沿用了Shackleton这个姓氏，幽暗城Magic Quarter里的Pierce Shackleton和Samantha Shackleton也姓这个。无论这三人是保持着紧密的联系，还是仅仅源于凡人时代的共同祖先，他们每个人都在为服务被遗忘者大业而在被诅咒的王国中扮演着独特的角色。"}},faq={{q="我可以在哪里找到Eleanor Shackleton？",a="Eleanor Shackleton在布瑞尔的西南方扎营，躲藏在提瑞斯法林地的树林中，远离主要的铺砌道路。",al={"eleanor shackleton位置","eleanor在哪里","shackleton营地"}},{q="Eleanor Shackleton教给冒险者什么？",a="Eleanor指导旅行者掌握野外生存的基础知识，提供关于露营、觅食以及在野外进行专业技能练习的指导。",al={"eleanor任务","eleanor做什么","提瑞斯法露营任务"}},{q="Eleanor和其他洛丹伦的Shackleton家族成员有关系吗？",a="她与幽暗城的Pierce Shackleton和Samantha Shackleton拥有相同的家族姓氏，这表明在王国沦陷于天灾军团之前，他们之间可能存在亲缘关系。",al={"pierce shackleton亲戚","samantha shackleton","shackleton家族传说"}},{q="她为什么要露宿布瑞尔外，而不是待在镇上？",a="Eleanor专注于实地手艺和野外生存。在树林中搭建营地让她能够接触到过往的行人，并直接在需要这些技能的地方对他们进行训练。",al={"为什么在布瑞尔外露营","eleanor shackleton营地"}}},fx={a3327cab={q="Eleanor Shackleton是谁？",a="Eleanor Shackleton是一位被遗忘者野外生存专家，在布瑞尔西南方的树林中扎营。她没有留在城镇里，而是选择在提瑞斯法林地的荒野中求生，指导初生的亡灵掌握野外生存的基本知识，并在野外学习基础技艺。",al={"eleanor shackleton是谁","eleanor shackleton的身份","eleanor shackleton的资料"}},afc076fe={q="Eleanor Shackleton属于哪一方？",a="Eleanor忠于被遗忘者与黑暗女王。她在布瑞尔郊外活动，帮助新近复生的族人适应不死生活，教他们如何在洛丹伦闹鬼的林地中求生、采集材料并磨练实用技艺。",al={"eleanor shackleton的阵营","eleanor shackleton属于部落吗","eleanor shackleton的效忠对象"}},["48da77ca"]={q="Eleanor Shackleton想要什么？",a="Eleanor希望冒险者学会必要的生存技能和野外技艺。她让旅人在露天环境中练习草药学、剥皮和烹饪等专业，确保离开聚居地庇护的被遗忘者能够妥善准备，自力更生。",al={"eleanor想要什么","eleanor shackleton的目标","eleanor shackleton的动机"}}},fp="18,356,21.516.0,21.437.0,36.125.0,47.154.0,53.177.0,60.171.0"}
P.entries["npc:electrocutioner-6000"] = {n="电刑器6000型",s="电刑器6000型是一台致命的、超高压的蜘蛛坦克，被部署在诺莫瑞根受辐射的殿堂内，以保卫Launch Bay。它为麦克尼尔·瑟玛普拉格及其追随的麻风侏儒效力，占据着高处的平台，阻挡任何试图深入这座陷落之城的入侵者。",h="电刑器6000型是一台致命的、超高压的蜘蛛坦克，被部署在诺莫瑞根受辐射的殿堂内，以保卫Launch Bay。它为麦克尼尔·瑟玛普拉格及其追随的麻风侏儒效力，占据着高处的平台，阻挡任何试图深入这座陷落之城的入侵者。",kw={"电刑器","诺莫瑞根","launch bay","蜘蛛坦克","瑟玛普拉格","车间钥匙"},ang={["faction:Alliance"]="突破Launch Bay并摧毁这台坦克，对于获得车间钥匙至关重要，它可以让人们在诺莫瑞根的收复行动中避开危险的前线走廊。",["profession:Engineering"]="工程师们对底盘内蕴含的原始高压输出感到惊叹，即使这种力量正被用来对付他们。",["race:Gnome"]="对于来自铁炉堡的流亡侏儒来说，电刑器6000型是对他们技艺的侮辱：这原本是一台侏儒的战争机器，在瑟玛普拉格的统治下，却被用来对付他们自己的人民。"},sec={{t="瑟玛普拉格的震撼机器",b="诺莫瑞根的陷落使其战争机器落入了麦克尼尔·瑟玛普拉格和追随他的麻风侏儒手中。电刑器6000型是一台庞大的、闪烁着高压电流的蜘蛛坦克，它守卫在诺莫瑞根Launch Bay的高处平台，并以电流抽打入侵者。"},{t="车间钥匙",b="这台机器还守护着一件战利品：车间钥匙，它能打开诺莫瑞根通往车间的后门。击败电刑器的人可以获得这把钥匙，从而开辟一条进入城市深处的捷径。"}},faq={{q="在哪里可以找到电刑器6000型？",a="电刑器6000型位于诺莫瑞根这座陷落之城内，俯瞰着Launch Bay的高架平台上。",al={"电刑器6000型位置","电刑器在哪里","找到电刑器6000型"}},{q="是谁在驾驶电刑器6000型？",a="在关于诺莫瑞根陷落的记载中，没有提及驾驶员。这台坦克是为麦克尼尔·瑟玛普拉格及其效忠的麻风侏儒作战的。",al={"谁在驾驶电刑器6000型","电刑器的驾驶员"}},{q="为什么这台机器如此不稳定？",a="它那装甲底盘引导着高压电流，并会释放给任何靠近的人。这种原始的电力使其成为Launch Bay最危险的守护者之一。",al={"为什么它会放电","电刑器原型机","瑟玛普拉格的设计"}},{q="为什么对于探险者来说，击败电刑器6000型很重要？",a="这台机器携带着车间钥匙，这是一种至关重要的装置，可以解锁通往诺莫瑞根更深处工程部门的后门，使突击小队能够更快地穿过被重新占领的设施。",al={"车间钥匙","为什么要击杀电刑器","电刑器6000型掉落"}},{q="电刑器是自动化装置还是载具？",a="它是一台机械坦克：一种侏儒制造的、带有蜘蛛腿的装甲战争机器，现在却被用来对付诺莫瑞根的复国者。",al={"电刑器是机器人吗","电刑器蜘蛛坦克类型"}}},fx={cad4dd7a={q="电刑器6000型是什么？",a="电刑器6000型是一台经过强化的机械蜘蛛坦克，负责守卫诺莫瑞根的Launch Bay。它电光闪烁，充满高压电流，为麦克尼尔·瑟玛普拉格及其麾下的麻疯侏儒而战。",al={"电刑器6000型是谁","电刑器6000型是什么","电刑器6000型的背景"}},["48c81a6d"]={q="电刑器6000型属于哪一方？",a="这台战争机器完全听命于麦克尼尔·瑟玛普拉格及其疯狂的麻疯侏儒派系。它狂热地捍卫瑟玛普拉格对诺莫瑞根的统治权，摧毁任何靠近Launch Bay的穴居人、联盟特工或部落闯入者。",al={"电刑器的阵营","电刑器为谁效力","电刑器的效忠对象"}},["5513927c"]={q="电刑器6000型想要什么？",a="这台坦克服务于麦克尼尔·瑟玛普拉格的狂妄野心。它的职责是电击并消灭任何胆敢闯入诺莫瑞根深处区域的人。",al={"电刑器6000型的目标","电刑器想要什么","电刑器的动机"}},e5de5943={q="电刑器6000型为何在Launch Bay？",a="这台坦克驻守在Launch Bay上层的高处栈道，守卫高架通道并封锁通往建筑群深处的入口。它持有车间钥匙，充当全副武装的检查哨，阻挡任何试图深入瑟玛普拉格据点核心的人。",al={"电刑器为何在这里","电刑器为何在launch bay","电刑器的用途"}},["06482735"]={q="电刑器6000型为何令人畏惧？",a="这台机器以致命的攻击力而臭名昭著。它的装甲车身能导引高压电流，并将其释放到任何靠近的人身上，因此它是挡在入侵者与瑟玛普拉格据点核心之间最危险的守卫之一。",al={"电刑器为何令人畏惧","电刑器的名声","电刑器为何出名"}}},fp="20,292,30.317.0,16.208.0,44.135.0,36.133.0,31.185.0,66.210.0,49.129.0"}
P.entries["npc:elling-trias"] = {n="埃林·提亚斯",s="埃林·提亚斯经营着提亚斯奶酪店，这是一家坐落在暴风城繁华的Trade District中的小店。虽然他表现得像是一个热情洋溢、热爱乳制品的商贩，但他实际上是王国里消息最灵通的情报掮客之一。在奶酪和亲切的寒暄背后，提亚斯的消息网延伸到了整片大陆。",h="埃林·提亚斯经营着提亚斯奶酪店，这是一家坐落在暴风城繁华的Trade...",kw={"elaine trias","埃林·提亚斯","mathias shaw","失踪的外交官","军情七处","暴风城","trade district","提亚斯奶酪店","泰里恩"},ang={["class:Rogue"]="任何深谙处世之道的人都知道，埃林的奶酪店是一个理想的接头点。他靠近Old Town的位置以及与马迪亚斯·肖尔的紧密联系，使他成为了暴风城地下世界的一座固定灯塔。",["faction:Alliance"]="埃林是联盟情报机构中一位默默无闻的支柱，他悄悄过滤着从塞拉摩到壁炉谷的传闻，以保护王国免受内部腐朽的侵害。"},sec={{t="奶酪大师",b="对于漫步在Trade District的普通顾客来说，埃林·提亚斯只不过是一位专注于制作精良奶酪的工匠，与他的妻子Elaine和儿子Ben一同经营着店铺。他热切地兜售着奶酪，并与镇民们友好地交谈。然而，知情人士都明白，提亚斯奶酪店是暴风城中最可靠的掩护点之一。城市商业的稳定喧嚣为那些需要在此进行秘密交流，且不引起城市守卫注意的情报人员、朝臣和冒险者提供了完美的掩护。"},{t="低语之网",b="对于一个店主来说，埃林那庞大的线人和盟友网络令人震惊。他与军情七处的马迪亚斯·肖尔保持着联系，与德拉维主教等教会人士进行协调，并与远至夜色镇、塞拉摩岛以及壁炉谷附近那遥远的瘟疫之地的特工们保持着通信。当奇怪的传闻浮出水面——无论是关于公路强盗还是乡村里的安静动向——提亚斯往往在王室注意到之前，就已经拼凑出了事情的真相。"},{t="失踪的外交官",b="当一名高级外交官在前往塞拉摩的航程中失踪时，埃林·提亚斯成为了揭开这场阴谋的关键枢纽。他引导调查人员联系他的线人——包括一位疏远的特工乔贞和老友泰里恩——帮助揭露了迪菲亚潜行者在这起绑架案中的所作所为。尽管他言辞尖刻、讽刺辛辣，但埃林意识到这场阴谋已经深入到了暴风城贵族阶层的核心。"}},faq={{q="谁是埃林·提亚斯？",a="埃林·提亚斯表面上是在暴风城的Trade District与家人一起经营提亚斯奶酪店的奶酪商人。在那层掩护之下，他是一位经验丰富的情报掮客，与军情七处、教会以及艾泽拉斯各地的遥远哨所都有着联系。",al={"谁是埃林","埃林·提亚斯的身份","提亚斯奶酪店老板"}},{q="他的奶酪店在哪里？",a="你可以在暴风城的Trade District找到提亚斯奶酪店，它位于通往Old Town的边界附近，靠外侧运河墙的一排商店里。",al={"提亚斯奶酪店位置","埃林·提亚斯在哪里","暴风城的提亚斯商店"}},{q="他和迪菲亚潜行者有什么关系？",a="提亚斯并不是迪菲亚潜行者的成员；相反，他通过自己的情报网追踪他们的动向。他协助联盟冒险者追踪迪菲亚在颠覆性阴谋中的参与情况，包括绑架一名王室外交官的事件。",al={"提亚斯与迪菲亚","提亚斯是迪菲亚吗"}},{q="他怎么认识马迪亚斯·肖尔的？",a="肖尔和埃林是旧识，每当官方渠道行不通时，肖尔就会求助于他，尽管两人都不喜欢这样：肖尔讨厌寻求他的帮助，而埃林每当自己的工作最终帮了肖尔和军情七处一个大忙时就会发牢骚。他的店铺提供了一个非正式的监听站，可以在官方王室渠道之外进行谨慎的调查。",al={"提亚斯和肖尔","提亚斯与军情七处","提亚斯是军情七处的人吗"}},{q="谁和他一起经营这家店？",a="埃林与他的妻子Elaine Trias和儿子Ben Trias一起经营提亚斯奶酪店。他们共同维持着一家忙碌而普通的家庭贸易店的形象。",al={"提亚斯的家人","埃林·提亚斯的妻子"}},{q="他参与了失踪外交官的调查吗？",a="经由德拉维主教推荐，调查人员利用埃林庞大的人脉网——包括他的老相识乔贞和泰里恩——追踪迪菲亚的动向，并发现了是谁绑架了前往塞拉摩的外交官。",al={"失踪的外交官与提亚斯","为什么要去提亚斯奶酪店"}}},fp="12,190,23.381.0,17.434.0,20.404.1,20.197.0,33.110.0,49.215.1,30.240.0,27.142.0,62.199.1"}
P.entries["npc:elu"] = {n="艾鲁",s="艾鲁是驻扎在千针石林乱风岗的一名风骑士学徒。为了早日开始正式训练并飞向蓝天，他委托部落的旅行者从附近的巢穴中取回野生双足飞龙蛋。",h="艾鲁是驻扎在千针石林乱风岗的一名风骑士学徒。为了早日开始正式训练并飞向蓝天，他委托部落的旅行者从附近的巢穴中取回野生双足飞龙蛋。",kw={"艾鲁","乱风岗","风巢","千针石林","风骑士","双足飞龙","双足飞龙蛋"},ang={["faction:Horde"]="为艾鲁收集双足飞龙蛋直接加强了部落的信使和运输网络，使卡利姆多各地的偏远哨站能够通过空中交通保持联系。",["race:Tauren"]="对于牛头人冒险者来说，协助艾鲁不仅是支持了一位正在努力掌握驯服双足飞龙这一古老而重要技艺的同胞，更是在祖先留下的峡谷高地上捍卫着他们的传统。"},sec={{t="热切的学徒",b="艾鲁身处乱风岗，高高凌驾于盐沼和峡谷底部，他每天都在照料这里的飞行坐骑，同时梦想着属于自己的飞行。作为一名年轻的牛头人学徒，他渴望加入巡逻卡利姆多高耸台地的风骑士大师们的行列。然而，在开始真正的飞行训练之前，他必须通过为巢穴补充新鲜的双足飞龙种群来证明自己的能力，因此他会派遣有能力的冒险者去风巢，从那里凶猛的野生双足飞龙窝中采集完整的龙蛋。"}},faq={{q="艾鲁是谁？",a="艾鲁是一名驻扎在千针石林乱风岗的牛头人风骑士学徒，负责帮助部落的航空网络获取和饲养新的坐骑。",al={"艾鲁 乱风岗","艾鲁是谁","牛头人学徒艾鲁"}},{q="艾鲁为什么要双足飞龙蛋？",a="艾鲁的任务是为风骑士大师补充双足飞龙的库存。从收集到的新鲜龙蛋开始饲养这些野兽，可以确保它们能得到妥善训练，并与部落建立起互信的坐骑关系。",al={"为什么需要双足飞龙蛋","艾鲁双足飞龙任务","艾鲁任务目标"}},{q="艾鲁派遣冒险者去哪里寻找龙蛋？",a="他指引冒险者前往风巢，那是千针石林西部一座危险的台地，成群的野生双足飞龙在那里凶猛地守护着它们的巢穴。",al={"双足飞龙蛋在哪里","风巢在哪里","艾鲁的龙蛋位置"}}},fx={["74f15e75"]={q="艾鲁效忠哪一方？",a="艾鲁效忠部落和他的牛头人同胞。他驻守在乱风岗的高崖之上，与部落的驭风者大师并肩工作，训练并供给飞行坐骑，以满足在卡利姆多各地旅行的需要。",al={"艾鲁的阵营","艾鲁是部落成员吗","艾鲁效忠谁"}},["3d25520c"]={q="艾鲁为什么在乱风岗？",a="艾鲁在乱风岗担任驭风者学徒。他留在这里协助飞行管理员，并努力赢得翱翔天空的资格；他的任务是从千针石林的高处巢穴获取新的双足飞龙，以供训练后交给部落骑手。",al={"艾鲁为什么在千针石林","艾鲁与乱风岗","艾鲁的目的"}},c552be8c={q="艾鲁隶属于谁？",a="艾鲁是部落驭风者大师的学徒。他听从那些培育卡利姆多飞翼双足飞龙的训练师和驯兽师的安排，在他们的指导下工作，希望开始接受正式的驭风者训练。",al={"艾鲁的师父","艾鲁为谁效力","艾鲁与驭风者"}}},fp="3,217,19.520.0,11.169.0,30.209.0,45.140.0"}
P.entries["npc:eva-sarkhoff"] = {n="艾瓦·萨克霍夫",s="艾瓦·萨克霍夫是巴罗夫家族前任女管家的幽灵残影，她与丈夫卢森徘徊在通灵学院恐怖气氛之外。在凯尔达隆陷落期间，她被屠夫折磨致死，她的灵魂寻求勇敢的凡人来为他们的死复仇，并摧毁他们被诅咒的遗骸。",h="艾瓦·萨克霍夫是巴罗夫家族前任女管家的幽灵残影，她与丈夫卢森徘徊在通灵学院恐怖气氛之外。在凯尔达隆陷落期间，她被屠夫折磨致死，她的灵魂寻求勇敢的凡人来为他们的死复仇，并摧毁他们被诅咒的遗骸。",kw={"巴罗夫","凯尔达隆","the cult of the damned","艾瓦·萨克霍夫","克拉斯蒂诺夫","卢森·萨克霍夫","通灵学院","屠夫"},ang={["class:Priest"]="目睹艾瓦和卢森挥之不去的折磨是天灾军团残忍行径的鲜明写照，这要求圣职者们给予他们不安的灵魂以安宁，并净化束缚着他们的邪恶魔法。",["race:Human"]="艾瓦和她的丈夫代表了洛丹伦普通的仆人，当巴罗夫家族将凯尔达隆卖给克尔苏加德时，他们被自己的腐败贵族所背叛。"},sec={{t="巴罗夫家族的陨落",b="艾瓦曾为富有的巴罗夫家族担任女管家长达数十年，与她的丈夫、家族管家卢森一起打理着凯尔达隆庞大的城堡。随着巴罗夫家族对日渐衰老的生命和巨额财富产生恐惧，他们与克尔苏加德达成了一项灾难性的契约。庄园逐渐被移交给初出茅庐的The Cult of the Damned，这座宏伟的宅邸被扭曲成了通灵学院，一所秘密的亡灵巫术学院。艾瓦和卢森在城堡的走廊里躲藏了六个月，靠搜寻食物为生，同时眼睁睁地看着邪教徒和怪物逐渐占据了他们的家园。"},{t="屠夫的手术刀",b="最终被天灾军团发现后，艾瓦和卢森被移交给了被称为“屠夫”的瑟奥伦·克拉斯蒂诺夫医生。克拉斯蒂诺夫对这对夫妇进行了数周痛苦的实验，利用黑暗魔法延长他们的生命，使其远超凡人承受的极限。即使在死后，他们的尸体也被喂给了食尸鬼，而他们不安的灵魂被束缚在凯尔达隆，艾瓦现在恳求路过的冒险者杀死克拉斯蒂诺夫并焚烧他们的遗骸。"}},faq={{q="艾瓦·萨克霍夫死前是谁？",a="艾瓦·萨克霍夫曾是贵族巴罗夫家族的女管家，与担任管家的丈夫卢森一起在凯尔达隆城堡居住和工作了数十年。",al={"艾瓦·萨克霍夫背景故事","谁是艾瓦·萨克霍夫","艾瓦背景知识"}},{q="艾瓦是怎么死的？",a="在躲避The Cult of the Damned数月后，艾瓦和卢森被发现并移交给了瑟奥伦·克拉斯蒂诺夫医生。克拉斯蒂诺夫对他们进行了数周毫不留情的折磨，用黑暗魔法让他们苟延残喘，直到他们最终死去，尸体被喂给了食尸鬼。",al={"艾瓦·萨克霍夫是怎么死的","艾瓦·萨克霍夫之死","谁杀死了艾瓦"}},{q="为什么艾瓦的灵魂还留在凯尔达隆？",a="艾瓦所受的折磨既恐怖又不自然，导致她的灵魂仍然被束缚在这个凡人位面。在她没有杀死克拉斯蒂诺夫医生并焚烧通灵学院内她的肉体残骸之前，她无法进入永恒。",al={"为什么艾瓦是幽灵","艾瓦的灵魂","为什么艾瓦徘徊不去"}}},fp="12,310,23.585.0,21.483.1,37.171.0,16.272.0,40.211.0"}
P.entries["npc:executor-arren"] = {n="执行官阿伦",s="执行官阿伦是一位驻守在丧钟镇的亡灵高阶军官。他负责监督该定居点的即时防御与巩固工作，以应对从坟墓中苏醒的亡灵。阿伦统筹着当地针对无脑的亡灵天灾僵尸、野兽以及步步紧逼的血色十字军狂热者的行动。",h="执行官阿伦是一位驻守在丧钟镇的亡灵高阶军官。他负责监督该定居点的即时防御与巩固工作，以应对从坟墓中苏醒的亡灵。阿伦统筹着当地针对无脑的亡灵天灾僵尸、野兽以及步步紧逼的血色十字军狂热者的行动。",kw={"丧钟镇","执行官阿伦","亡灵","夜行蜘蛛洞穴","血色十字军","sylvanas windrunner","提瑞斯法林地"},ang={["faction:Horde"]="阿伦在丧钟镇的前线指挥代表了部落在北洛丹伦的最初立足点，在充满敌意的环境中确保了生存。",["race:Undead"]="执行官阿伦是每个亡灵来到提瑞斯法林地后见到的第一批指挥官之一，让他们初次体验到效忠于黑暗女王的职责。"},sec={{t="丧钟镇指挥官",b="执行官阿伦坚定地站在丧钟镇的教堂外，作为亡灵新手在苏醒之地的首要军事代言人。当墓穴中的看守者引导刚复活的亡灵克服困惑时，阿伦指引他们将注意力转向生存。在Sylvanas Windrunner女王的旗帜下，他组织当地行动，清剿威胁村庄边界的无脑僵尸，在洛丹伦废墟的阴影下建立稳固的领土。"},{t="守卫边境",b="丧钟镇周围的危险远比困惑的亡灵新兵所面临的要致命得多。在阿伦的命令下，侦察兵和新兵袭击了盘踞在夜行蜘蛛洞穴的凶残蜘蛛，并消灭了游荡在林地边缘的危险捕食者。通过要求每一个有能力的人采取果断行动，阿伦考验着新来者的坚韧，确保只有那些有能力捍卫他们第二次生命的人才能继续效忠于黑暗女王。"},{t="血色威胁",b="阿伦最大的战略担忧在于血色十字军。这些狂热者认为所有亡灵都是必须彻底根除的怪物，他们未能或拒绝区分亡灵天灾与拥有自由意志的亡灵。阿伦组织针对驻扎在提瑞斯法林地荒野中的血色十字军巡逻队的定点打击，截获信使并分析窃取的公文，以保护丧钟镇免受圣火清洗。"}},faq={{q="执行官阿伦是谁？",a="执行官阿伦是负责提瑞斯法林地丧钟镇的军事指挥官。他将新苏醒的亡灵组织成一支有效的战斗力量，以保卫村庄并确保周边乡村的安全。",al={"阿伦的角色","阿伦是谁","丧钟镇执行官"}},{q="在亡灵中，执行官是什么军衔？",a="执行官是亡灵体系中备受信任的军事和行政指挥官。他们管理当地驻军，指导野外行动，并执行Sylvanas Windrunner女王的意志与法律。",al={"执行官头衔","什么是执行官","亡灵执行官军衔"}},{q="为什么阿伦派新兵去对付僵尸？",a="在丧钟镇附近游荡的僵尸是瘟疫摧毁洛丹伦后残留的无脑天灾余孽。阿伦下令清除它们，以免新苏醒的亡灵在离开墓穴时被撕成碎片。",al={"为什么要杀僵尸","被诅咒者任务","无脑的天灾军团"}},{q="为什么血色十字军会出现在提瑞斯法林地？",a="血色十字军是一个致力于消灭所有亡灵的激进人类派系。他们在洛丹伦废墟各地设有前哨站，并积极寻求清洗亡灵，将他们视为与亡灵天灾无异的存在。",al={"提瑞斯法林地的血色十字军","为什么十字军在这里","丧钟镇的十字军"}},{q="什么是夜行蜘蛛洞穴？",a="夜行蜘蛛洞穴是位于丧钟镇西北方的一座金矿，已被蜘蛛占领。亡灵需要其中的黄金，因此阿伦派遣新兵一点一点地清除这些蜘蛛。",al={"丧钟镇的蜘蛛洞穴","夜行蜘蛛洞穴","阿伦的蜘蛛任务"}},{q="新兵完成阿伦的任务后会被派往哪里？",a="一旦丧钟镇的直接威胁被消除，阿伦就会引导有能力的新兵前往布瑞尔，向执行官塞加德汇报，并协助亡灵在提瑞斯法林地的更大规模行动。",al={"丧钟镇之后的去向","阿伦之后去哪里","战场上的执行官"}}},fx={["610ddc26"]={q="执行官阿伦效忠哪一方？",a="执行官阿伦完全效忠被遗忘者和黑暗女王希尔瓦娜斯·风行者。作为丧钟镇的当地军事指挥官，他的职责是守卫新近苏醒的同胞最初踏足的地方，并铲除任何威胁这个新兴国度的势力，无论是失去理智的天灾僵尸、当地野兽，还是血色十字军的狂热分子。",al={"阿伦的效忠对象","执行官阿伦为谁效力","阿伦的阵营"}},["25e599ca"]={q="执行官阿伦想要什么？",a="阿伦希望牢牢确立被遗忘者对丧钟镇的控制，并考验新生者的决心。他要清除墓地里的无脑亡灵、肃清不断逼近的蛛类生物，并摧毁附近的血色十字军营地，好让新兵安全前往布瑞尔，加入提瑞斯法林地更广泛的防卫。",al={"阿伦想要什么","阿伦的目标","执行官阿伦的职责"}},["3c8717b4"]={q="执行官阿伦为什么在丧钟镇？",a="阿伦驻守丧钟镇，负责指挥最初的防卫；新近获得自由的被遗忘者最初就是在这里从坟墓中走出。若没有军事监督，迷惘的新兵很容易被山间游荡的无脑天灾亡灵击溃，或落入侦察定居点外围的血色十字军斥候之手。",al={"阿伦为什么在丧钟镇","阿伦驻守此地的原因","执行官阿伦为什么在这里"}}},fp="14,332,23.510.0,24.454.0,18.435.1,22.220.0,44.211.0,49.217.0,46.218.0,27.181.0,58.189.0"}
P.entries["npc:executor-zygand"] = {n="执行官塞加德",s="执行官塞加德是一位驻扎在布瑞尔市政厅的被遗忘者高级指挥官，负责监督整个提瑞斯法林地中部的防御和军事行动。他直接向幽暗城的最高指挥部报告，负责协调针对血色十字军渗入被遗忘者领地的清剿工作。",h="执行官塞加德是一位驻扎在布瑞尔市政厅的被遗忘者高级指挥官，负责监督整个提瑞斯法林地中部的防御和军事行动。他直接向幽暗城的最高指挥部报告，负责协调针对血色十字军渗入被遗忘者领地的清剿工作。",kw={"阿伦","布瑞尔","亡灵卫兵","执行官","蛆眼","血色十字军","提瑞斯法","塞加德"},ang={["faction:Horde"]="来自卡利姆多的旅行者在访问提瑞斯法林地时，能在塞加德身上看到被遗忘者为保卫洛丹伦而展现出的结构化、纪律严明的军事领导力。",["race:Undead"]="对于从丧钟镇走出来的被遗忘者而言，执行官塞加德代表了幽暗城更广泛的军事权威，欢迎新公民投身于对抗他们最凶恶敌人的战斗中。"},sec={{t="布瑞尔的指挥权",b="执行官塞加德身处布瑞尔的行政中心，在被遗忘者从丧钟镇初次苏醒后，负责协调该地区的防御工作。作为执行官阿伦等地区军官和亡灵卫兵林奈等野外哨兵的直接上级，塞加德汇总侦察情报并派遣有能力的受训者，以保卫洛丹伦边境免受侵犯。"},{t="对抗十字军的战争",b="塞加德的首要军事关注点是狂热的血色十字军，他们盘踞在提瑞斯法林地的各个前哨站中。在他的指挥下，特工们系统性地被派往打击十字军侦察兵、营地和前沿基地，以确保这些狂热者永远无法集结起足够威胁到幽暗城入口的力量。"}},faq={{q="执行官塞加德是谁？",a="执行官塞加德是一位在提瑞斯法林地的布瑞尔开展工作的被遗忘者高级军官。他指挥当地的亡灵卫兵驻军，接收下级军官的战术报告，并指挥针对当地威胁的军事行动。",al={"塞加德","执行官塞加德是谁","塞加德的角色"}},{q="我在哪里可以找到执行官塞加德？",a="他位于布瑞尔的主市政厅内或附近。布瑞尔是提瑞斯法林地中心地带的被遗忘者定居点，位于幽暗城正北方向。",al={"塞加德的位置","塞加德在哪里","执行官塞加德地图"}},{q="塞加德在提瑞斯法林地的主要目标是什么？",a="他的主要任务是组织针对血色十字军的区域战争。他监视这些狂热者在整个提瑞斯法的动向，并下令拆除他们的营地，清除他们的领导层，以阻止他们进军幽暗城。",al={"塞加德任务目标","为何对抗十字军","塞加德的目的"}},{q="谁向执行官塞加德报告？",a="塞加德是执行官阿伦（负责指挥丧钟镇新兵）以及亡灵卫兵林奈（在提瑞斯法林地主要十字路口巡逻的野外哨兵）的上级军官。",al={"塞加德的下属","谁为塞加德效力","阿伦的上级"}},{q="执行官塞加德会处理流氓亡灵的威胁吗？",a="是的。除了对抗血色十字军，塞加德还会发布地区悬赏令，以消灭野生亡灵和危险的流浪食腐者（例如偷尸体的豺狼人蛆眼），这些威胁会危及林地内的通行。",al={"蛆眼","塞加德悬赏","悬赏任务"}},{q="“执行官”在被遗忘者中是什么军衔？",a="执行官在被遗忘者的阶级体系中担任地区总督和军事指挥官。他们负责管理定居点，指挥当地的亡灵卫兵部队，并在洛丹伦的有争议地区执行希尔瓦娜斯女王的统治。",al={"什么是执行官","执行官军衔","被遗忘者执行官"}}},fx={["1dc7a0d0"]={q="执行官塞加德效忠哪一方？",a="执行官塞加德一心效忠被遗忘者和希尔瓦娜斯·风行者。作为布瑞尔的军官，他为幽暗城效力，协调当地防务、指挥亡灵卫兵，并组织战略打击，以守住提瑞斯法林地，抵御被遗忘者永无止境的敌人。",al={"塞加德的阵营","塞加德为谁效力","执行官塞加德属于哪一方"}},["673b7cce"]={q="执行官塞加德为什么驻守在布瑞尔？",a="塞加德驻守在布瑞尔，因为这座定居点是被遗忘者位于幽暗城正北方的主要军事据点。他从这里监控提瑞斯法林地各处的重大威胁，管理前线巡逻，并部署经验丰富的战士，确保重要补给线和边境安全。",al={"塞加德为什么在这里","塞加德在布瑞尔的职责","执行官塞加德为什么在布瑞尔"}}},fp="15,297,16.392.0,22.341.0,23.236.0,33.146.0,46.239.0,31.198.0,49.226.0,53.231.0"}
P.entries["npc:falfindel-waywarder"] = {n="法芬德尔",s="法芬德尔是一位驻扎在萨兰纳尔的暗夜精灵德鲁伊，这座前哨站守卫着菲拉斯与千针石林之间的边界。从这个边境哨所开始，他致力于治疗被腐蚀的土地，并守护着卡利姆多南部的荒野。从石爪山脉或贫瘠之地长途跋涉而来的旅者，经常会发现他正在寻求帮助，以恢复大自然的平衡。",h="法芬德尔是一位驻扎在萨兰纳尔的暗夜精灵德鲁伊，这座前哨站守卫着菲拉斯与千针石林之间的边界。从这个边境哨所开始，他致力于治疗被腐蚀的土地，并守护着卡利姆多南部的荒野。从石爪山脉或贫瘠之地长途跋涉而来的旅者，经常会发现他正在...",kw={"焦炭谷","法芬德尔","菲拉斯","石爪山脉","萨兰纳尔","千针石林","小精灵"},ang={["class:Druid"]="他派遣森林之灵和小精灵去治愈石爪山脉被烧焦的土壤，这体现了德鲁伊神圣的复原使命。",["faction:Alliance"]="对于从贫瘠之地或石爪山脉长途跋涉向南的联盟旅者来说，法芬德尔和萨兰纳尔的守望者们提供了一个温馨的避风港。",["race:NightElf"]="法芬德尔代表了你们的人民在卡利姆多边境的警觉，致力于修复大自然的伤痕，并防范荒野中迫近的危险。"},sec={{t="南部边界的守望者",b="萨兰纳尔是连接菲拉斯茂密森林与千针石林高耸台地及干燥盐平原的门户。法芬德尔驻守在这座偏远的前哨站，迎接那些穿越整个大陆、长途跋涉而来的疲惫旅者。周围既有壮丽的自然景观，也潜伏着危险，他不仅是监测当地威胁的联络点，也关注着整个卡利姆多大陆上更广泛的环境灾难。"},{t="治愈焦炭谷",b="尽管身处南部的哨所，法芬德尔依然深切担忧着远在北方石爪山脉的破坏。被黑暗魔法和烈火摧毁的焦炭谷，如同卡利姆多荒野上的一道痛苦伤疤。当冒险者向法芬德尔提供援助以助其恢复时，他会召唤森林之灵。他召唤出成群的小精灵，并指挥它们火速赶往北方的石爪山脉，开始修复那片被烧焦的土地。"},{t="密切关注野猪人和荒野",b="除了协调复原工作，法芬德尔还密切监视着周围的区域，包括剃刀沼泽的野猪人巢穴。通过查阅寻回的日记并收集关于野猪人首领的情报，法芬德尔确保联盟了解威胁菲拉斯和中央沙漠之间通道的日益严重的危险。"}},faq={{q="法芬德尔在哪里？",a="法芬德尔驻扎在萨兰纳尔，这是一座位于菲拉斯与千针石林边界的暗夜精灵前哨站。",al={"法芬德尔位置","法芬德尔在哪里","法芬德尔地图"}},{q="法芬德尔在萨兰纳尔担任什么职务？",a="他在前哨站担任德鲁伊和向导，监测诸如剃刀沼泽野猪人等区域性威胁，并协调针对焦炭谷等荒废之地的复原工作。",al={"法芬德尔做什么","法芬德尔目标","法芬德尔任务"}},{q="法芬德尔如何帮助焦炭谷？",a="当冒险者协助开展收复焦炭谷的工作时，法芬德尔会吟唱咒语召唤森林小精灵，并将它们派往北方的石爪山脉，以治愈那片被摧残的土地。",al={"法芬德尔石爪山脉","法芬德尔焦炭谷","收复焦炭谷法芬德尔"}},{q="为什么法芬德尔对剃刀沼泽感兴趣？",a="他研究野猪人对剃刀沼泽构成的威胁，并通过查阅亨里格·独眉的日记等物品，追踪其首领的影响力，例如剃刀沼泽的妖婆。",al={"剃刀沼泽妖婆法芬德尔","亨里格·独眉的日记法芬德尔","法芬德尔野猪人"}},{q="法芬德尔是属于联盟还是中立？",a="法芬德尔是一位效忠于达纳苏斯和联盟的暗夜精灵德鲁伊。部落的旅者在接近萨兰纳尔时，会发现该前哨站处于敌对状态。",al={"法芬德尔是联盟吗","法芬德尔阵营"}},{q="法芬德尔对旅者说些什么？",a="他会以友好的态度问候访客，体恤他们的长途跋涉，说道：“你看上去像是从远方而来。”",al={"法芬德尔闲谈","法芬德尔名言"}}},fx={["444437e8"]={q="法芬德尔是谁？",a="法芬德尔是一名暗夜精灵，驻守在萨兰纳尔哨站，该地毗邻菲拉斯和千针石林。他关心土地的健康，也留意卡利姆多南部地区面临的危险；他守望过往旅人，并与其他暗夜精灵密切合作，应对荒野中出现的新威胁。",al={"法芬德尔是谁","法芬德尔的背景"}},e0cb4d91={q="法芬德尔想要什么？",a="法芬德尔希望保护脆弱的荒野，并帮助受创的土地恢复生机。他指挥盟友召唤森林之灵，让焦炭谷重焕生机；协调物资运送，保障当地哨站的补给；还设法除掉潜伏在剃刀沼泽中的堕落猪人老妪。",al={"法芬德尔想要什么","法芬德尔的目标","法芬德尔任务的目的"}},["2bf92e29"]={q="法芬德尔为什么在这里？",a="法芬德尔在萨兰纳尔担任德鲁伊和向导，守卫千针石林与菲拉斯之间的通道。在这座偏远的哨站，他监视着从贫瘠之地蔓延而来的猪人威胁，并协调行动，恢复卡利姆多中部和南部遭污染森林的平衡。",al={"法芬德尔为什么在这里","法芬德尔为什么在萨兰纳尔","法芬德尔的职责"}}},fp="19,367,28.456.0,24.471.0,35.366.0,37.119.0,38.190.0,41.185.0,46.172.0,50.139.0,37.132.0"}
P.entries["npc:falla-sagewind"] = {n="菲拉·古风",s="菲拉·古风是一位隐居的牛头人秘法师，栖居在俯瞰贫瘠之地中部的一座岩石山峰之巅。她驻扎在十字路口与甜水绿洲之间，研究着困扰这片土地的自然与神秘异象。那些探索从附近哀嚎洞穴中渗出的扭曲腐化的冒险者们，常常会寻求她的指引。",h="菲拉·古风是一位隐居的牛头人秘法师，栖居在俯瞰贫瘠之地中部的一座岩石山峰之巅。她驻扎在十字路口与甜水绿洲之间，研究着困扰这片土地的自然与神秘异象。那些探索从附近哀嚎洞穴中渗出的扭曲腐化的冒险者们，常常会寻求她的指引。",kw={"贫瘠之地","十字路口","菲拉","发光的碎片","甜水绿洲","梦魇","古风","牛头人","哀嚎洞穴"},ang={["class:Druid"]="德鲁伊们会视菲拉为追踪纳拉雷克斯及其哀嚎洞穴中尖牙德鲁伊悲剧堕落的重要盟友。",["faction:Horde"]="菲拉通过解读侦察兵从贫瘠之地那片多争端的热带草原带回的奇异预兆和腐化圣物，为部落提供帮助。",["race:Tauren"]="菲拉·古风体现了牛头人守护大地的静默职责，当她的同胞在下方的道路上防御时，她从高处警惕着灵体的腐败。"},sec={{t="高崖的守望者",b="菲拉·古风将营地安扎在远离贫瘠之地尘土与喧嚣的高处，位于十字路口西南方的一座偏僻山峰上。从这个有利位置，她庄严地注视着下方脆弱的热带草原，观察着野生动物行为的突变以及从哀嚎洞穴地底裂隙中涌出的蔓延腐化。她孤独的守望使她远离了十字路口的日常贸易，使她成为了一位敏锐的隐士，时刻关注着灵体与这片土地无声的伤痕。"},{t="苏醒的梦魇",b="当奇怪且搏动的碎片从哀嚎洞穴的变异野兽身上被取出时，聪明的旅行者会得到指引，前往高崖寻找菲拉。她会协助解读那些破坏绿洲自然秩序的扭曲魔法。在意识到翡翠梦境在地底变得污秽的严峻迹象后，她会派遣英雄们去寻找塞纳里奥议会的智慧德鲁伊，以获取关于该地区扎根的梦魇的更深层答案。"}},faq={{q="菲拉·古风是谁？",a="菲拉·古风是一位独自居住在贫瘠之地十字路口西南方高崖上的牛头人秘法师。她守护着这片土地，并协助那些试图了解在该地区蔓延的奇异魔法疾患的旅行者。",al={"菲拉·古风是谁","菲拉是谁","菲拉·古风背景故事"}},{q="我在哪里可以找到菲拉·古风？",a="她位于十字路口正西南方、甜水绿洲以北的一座陡峭山峰之巅。要到达她的营地，需要沿着从周围热带草原蜿蜒而上的岩石小径攀登。",al={"菲拉·古风位置","菲拉在哪里","如何前往菲拉·古风处"}},{q="为什么菲拉·古风会对哀嚎洞穴感兴趣？",a="菲拉协助调查从哀嚎洞穴中回收的发光的碎片里所蕴含的奇异魔法。她会将旅行者引向经验丰富的德鲁伊以寻求进一步的建议。",al={"菲拉哀嚎洞穴","为什么菲拉关心绿洲","菲拉发光的碎片"}},{q="菲拉·古风隶属于任何氏族或家族吗？",a="她与其他牛头人共用“古风”这个姓氏，但尚无确凿的家族联系证据。",al={"古风家族","谁是古风族人","菲拉和塔胡有关系吗"}},{q="有哪些任务涉及菲拉·古风？",a="菲拉参与了围绕哀嚎洞穴的调查，主要是交还或进行诸如“发光的碎片”和“在梦魇中”等任务，这些任务深入探讨了正在腐蚀当地绿洲的黑暗梦境。",al={"菲拉·古风任务","来自菲拉的任务","在梦魇中任务"}},{q="联盟玩家可以与菲拉·古风互动吗？",a="可以。菲拉会帮助双方阵营的旅行者处理发光的碎片，将联盟冒险者派往达纳苏斯的玛斯雷·驭熊者处，将部落冒险者派往雷霆崖的哈缪尔·符文图腾处。",al={"菲拉·古风是敌对的吗","菲拉对联盟友好吗"}}},fx={["53e3505a"]={q="菲拉·古风效忠哪一方？",a="菲拉·古风是一名牛头人，不属于任何阵营。她驻守在贫瘠之地崎岖的高地，帮助调查哀嚎洞穴蔓延出的异常腐化的部落和联盟旅人，也协助那些致力于净化土地的人。",al={"菲拉·古风的阵营","菲拉·古风是部落成员吗","菲拉·古风效忠谁"}},["709098cb"]={q="菲拉·古风想要什么？",a="菲拉·古风希望了解并对抗从哀嚎洞穴渗出的日益严重的腐化。当冒险者带来奇异的遗物，例如从洞穴生物身上取下的发光碎片时，她会着手查明潜伏在地下泉水中的噩梦。",al={"菲拉·古风的目标","菲拉想要什么","菲拉·古风的职责"}},["26262d64"]={q="菲拉·古风为什么在这里？",a="菲拉·古风在十字路口西南方的山脊顶端守望，俯瞰甜水绿洲和附近的哀嚎洞穴入口。她从这处高地监视土地的腐化，并指引那些发现了与下方受扰梦者有关的黑暗遗物的旅人。",al={"菲拉·古风为什么在贫瘠之地","菲拉为什么在山上"}}},fp="14,352,24.528.0,20.446.1,22.242.0,32.209.0,56.171.0,53.89.0,35.214.0,50.194.0"}
P.entries["npc:fallen-hero-of-the-horde"] = {n="部落英雄的灵魂",s="部落英雄的灵魂是一位兽人战士的残影，伫立在悲伤沼泽通往南方的道路上。由于懊悔与耻辱的束缚，他警告路过的旅人，诅咒之地中正等待着他们的恐怖，并寻求勇士来解救他那些饱受折磨、深陷恶魔奴役的士兵。",h="部落英雄的灵魂是一位兽人战士的残影，伫立在悲伤沼泽通往南方的道路上。由于懊悔与耻辱的束缚，他警告路过的旅人，诅咒之地中正等待着他们的恐怖，并寻求勇士来解救他那些饱受折磨、深陷恶魔奴役的士兵。",kw={"阿里斯塔","部落英雄的灵魂","破坏者格罗尔","副官基里思","污染者拉兹里克","塞薇恩","束缚之石","沼泽行者"},ang={["class:Warrior"]="作为一位声名显赫的阵亡战士，他那幽灵般的共鸣强烈地触动着那些理解战友牺牲后独活的痛苦的尚武冒险者。",["faction:Horde"]="这位英雄体现了一位荣誉被恶魔残忍剥夺的战士的痛苦，他呼吁部落的冒险者为他失去的部下复仇，并洗刷掉他们失败的耻辱。"},sec={{t="悲剧的使命",b="生前，这位战士曾是一位受人称颂的勇士，他带领着一支精心挑选的士兵团前往诅咒之地进行调查，并报告燃烧军团的动向。但他派出的使者没能成功抵达；北上前往斯通纳德的信使遭到了沼泽行者及其鱼人的伏击并被杀害。在没有命令和援军的情况下，指挥官最终带领他的士兵向南挺进破碎的荒原，去面对那日益增长的黑暗。这是一个致命的误判。他的军队被恶魔势力压制，溃散、被俘，并遭受了恐惧魔王污染者拉兹里克惨无人道的折磨。"},{t="失败的代价",b="指挥官与他的副官基里思一同被俘，在盘蛇谷遭受了残酷的拷问，而他们的俘虏者则剥离了他幸存士兵的灵魂。他虽然逃脱，却因伤势过重在沼泽边缘死去，这位英雄的灵魂因而被禁锢在诅咒之地的入口处。他的士兵遭受了更黑暗的命运：他们失去灵魂的躯壳被束缚在神秘的法阵石上，沦为不死奴隶，被拉兹里克及其副官——大魔导师阿里斯塔、女勋爵塞薇恩和破坏者格罗尔——瓜分。除非他们的灵魂之石被击碎，折磨终结，否则他那不得安息的灵魂将永远无法平静。"}},faq={{q="部落英雄的灵魂生前是谁？",a="他是一位资深的兽人战士，被选定率领一支侦察部队深入诅咒之地以评估恶魔的威胁。他在从污染者拉兹里克的拷问中逃脱后，因伤势过重而亡，灵魂被困在悲伤沼泽通往外界的道路旁。",al={"部落英雄的灵魂身份","部落英雄的灵魂名字","部落英雄的灵魂是谁"}},{q="为什么他徘徊在诅咒之地的边缘？",a="他被失去部下和任务失败的耻辱所束缚。他拒绝离去，直到有勇敢的冒险者深入南方，摧毁那些将他的士兵囚禁在燃烧军团永恒奴役之下的束缚之石。",al={"为什么他是鬼魂","部落英雄的灵魂鬼魂","他为什么在这里"}},{q="他发往斯通纳德的命令发生了什么？",a="那位带着紧急报告返回斯通纳德前哨站的侦察兵，在沼泽中遭到了由沼泽行者率领的鱼人的伏击并被杀害。由于报告丢失，援军未能抵达，迫使这位英雄独自挺进诅咒之地。",al={"丢失的命令","他的命令发生了什么","沼泽行者信使"}},{q="他的副官基里思发生了什么？",a="副官基里思在盘蛇谷遭受了恶魔实验。他的灵魂被扭曲变形，肉体变成了一只潜伏在洞穴深处的恐怖邪犬。",al={"副官基里思","基里思是谁","基里思发生了什么"}},{q="为什么他的士兵无法被击败？",a="拉兹里克和他的副官将俘虏士兵的灵魂从肉体中剥离。没有了灵魂，他们的肉体便无法真正死亡。只有在他们的躯体被重创至濒临毁灭时，附近的灵魂束缚之石才会显露破绽，从而被摧毁。",al={"无法被击败的士兵","束缚之石","拉兹里克的仆从"}}},fp="24,325,16.645.0,20.641.1,32.284.0,51.232.0,47.259.0,40.194.1,34.293.1"}
P.entries["npc:fandral-staghelm"] = {n="范达尔·鹿盔",s="大德鲁伊范达尔·鹿盔在达纳苏斯的塞纳里奥区领导着塞纳里奥议会的德鲁伊们。在玛法里奥·怒风消失于翡翠梦境后，他接过权柄，并力主种植新的世界之树：泰达希尔。范达尔骄傲、尖刻且野心勃勃，他主张卡多雷激进复兴，这经常使他与泰兰德·语风大祭司发生冲突。",h="大德鲁伊范达尔·鹿盔在达纳苏斯的塞纳里奥区领导着塞纳里奥议会的德鲁伊们。在玛法里奥·怒风消失于翡翠梦境后，他接过权柄，并力主种植新的世界之树：泰达希尔。范达尔骄傲、尖刻且野心勃勃，他主张卡多雷激进复兴，这经常使他与泰兰德...",kw={"塞纳里奥议会","达纳苏斯","范达尔","玛法里奥","rajaxx","流沙之战","鹿盔","泰达希尔","valstann"},ang={["class:Druid"]="鹿盔指挥着达纳苏斯的德鲁伊，推动塞纳里奥议会走向直接的世俗权力，同时与沉睡的玛法里奥·怒风的传统教导相冲突。",["faction:Alliance"]="尽管泰达希尔是联盟在北卡利姆多的堡垒，但鹿盔对年轻种族怀有毫不掩饰的蔑视，仅在政治权宜之计需要时才容忍他们的存在。",["race:NightElf"]="作为达纳苏斯的主要领导人之一，范达尔体现了卡多雷的骄傲和愤怒，即使普通公民能感受到他的塞纳里奥区与Temple of the Moon之间的隔阂，他仍在推动泰达希尔的定居。"},sec={{t="泰达希尔的设计者",b="在第三次战争结束以及海加尔山的Nordrassil被牺牲后，暗夜精灵失去了他们的永生和神圣的庇护所。当玛法里奥·怒风失踪后，范达尔接管了德鲁伊的领导权，并说服了Circle of Ancients，认为现在是他们的人民重建家园并重获永生的时候了。在得到Circle of Ancients的批准后，他带领德鲁伊们在卡利姆多海岸边升起了泰达希尔。他将这根巨大的树枝视为卡多雷坚韧不拔的丰碑，并将其作为一个恢复他们失去的至高地位的容器，尽管Dragon Aspects明确表示对这一未获批准的努力不予祝福。"},{t="流沙之战中的悲剧",b="在第一次战争发生的一千年前，范达尔在流沙之战期间担任希利苏斯的卡多雷前线指挥官。在虫族Qiraji中，他被称为“Kar'sis”——大地之手，他与他挚爱的独子Valstann一起坚守前线。Qiraji的Rajaxx将军利用了范达尔的奉献精神，在南风村制造了佯攻并俘虏了Valstann，当着惊恐的大德鲁伊的面残忍地处决了他。这次失去击碎了范达尔的精神，促使了一场毁灭性的撤退，并使他那傲慢的举止中铭刻下了对虫群一种持久而苦涩的仇恨。"},{t="竞争与傲慢",b="在达纳苏斯的大理石枝叶间，范达尔以傲慢、顽固的手段治理着卡多雷的事务。与倾向于精神守护和谨慎外交的泰兰德·语风大祭司不同，范达尔认为军事扩张和决断力对他们人民的生存至关重要。"}},faq={{q="范达尔·鹿盔是谁？",a="范达尔·鹿盔是达纳苏斯塞纳里奥议会的代理大德鲁伊，在玛法里奥·怒风缺席期间主持卡多雷德鲁伊的事务。他以火爆的脾气和帝王般的野心而闻名，是创造泰达希尔的主要构想者。",al={"范达尔背景故事","大德鲁伊是谁","达纳苏斯的大德鲁伊"}},{q="为什么范达尔和泰兰德合不来？",a="范达尔主张卡多雷军事复兴、激进扩张并重获失去的永生。泰兰德·语风则通过艾露恩追求谨慎的精神指引。他们对暗夜精灵海加尔山之后未来的不同愿景在达纳苏斯内部引发了激烈的政治摩擦。",al={"范达尔与泰兰德","为什么德鲁伊和女祭司会有分歧","鹿盔与语风"}},{q="为什么要种植泰达希尔？",a="在海加尔山之战后，Nordrassil伤痕累累，暗夜精灵失去了他们的永生。由于玛法里奥失踪，范达尔说服了Circle of Ancients，认为现在是他们的人民重建家园并重获永生的时候了，在得到Circle of Ancients的批准后，他和最强大的德鲁伊们种植了泰达希尔。",al={"谁创造了泰达希尔","为什么范达尔要种植泰达希尔","泰达希尔的起源"}},{q="范达尔的儿子发生了什么事？",a="在希利苏斯的流沙之战期间，范达尔的儿子Valstann在南风村被诱入埋伏。Qiraji的Rajaxx将军俘虏了Valstann并在范达尔面前杀害了他，这让大德鲁伊悲痛欲绝并永远怀恨在心。",al={"范达尔的儿子","valstann是谁","valstann staghelm"}},{q="在哪里可以找到范达尔·鹿盔？",a="范达尔站在达纳苏斯的塞纳里奥区，周围环绕着他忠诚的德鲁伊，监管着卡多雷首都的事务。",al={"范达尔在哪里","范达尔位置","塞纳里奥区领袖"}}},fx={d5bab569={q="范达尔·鹿盔效忠哪一方？",a="范达尔是达纳苏斯的大德鲁伊，也是塞纳里奥议会的一位领袖，拥护卡多雷和联盟。然而，他的忠诚带有强烈的民族主义色彩。他不愿顺从塞纳里奥长老或月神祭司团一贯的谨慎作风，而是严格按照自己认定的暗夜精灵民族利益行事，追求强硬的军事路线。",al={"范达尔·鹿盔的阵营","范达尔效忠谁","范达尔的效忠对象"}},adee2909={q="范达尔·鹿盔想要什么？",a="范达尔渴望恢复暗夜精灵的力量、不朽之身和领土霸权。他厌倦了数百年来消极避世的生活，力主种下世界之树泰达希尔，以取代诺达希尔。他设想建立一个积极进取的卡多雷国度，随时准备征服边境，大胆扩张至卡利姆多各地，并重拾远古时代失去的荣光与活力。",al={"范达尔·鹿盔的目标是什么","范达尔的野心","大德鲁伊鹿盔想要什么"}},["6d220bca"]={q="范达尔·鹿盔为什么在达纳苏斯？",a="玛法里奥·怒风被困在翡翠梦境中，无法行动，范达尔便接过大德鲁伊之位。他在达纳苏斯的塞纳里奥区高处统领塞纳里奥议会的德鲁伊，与大祭司泰兰德·语风共同执政，并积极主导泰达希尔的政治与魔法未来。",al={"范达尔为什么在达纳苏斯","范达尔·鹿盔驻守此地的原因","范达尔为什么在这里"}},["53c16312"]={q="范达尔·鹿盔为何闻名？",a="在率领种下泰达希尔之前很久，范达尔曾在希利苏斯的流沙之战中担任杰出的卡多雷战地指挥官。他对其虫族大军发动的毁灭性战术打击，为他赢得了其拉虫人的称号“卡尔希斯”——大地之手。其拉虫人畏惧他在战场上的狂怒，直到他们策划了他儿子的悲惨处决。",al={"范达尔为何闻名","范达尔为何令人畏惧","范达尔的大地之手称号"}}},fp="16,417,23.634.0,29.638.0,18.306.0,24.261.0,43.290.0,27.323.0,31.269.0,36.135.0"}
P.entries["npc:farmer-furlbrow"] = {n="农夫法布隆",s="农夫西奥多·法布隆是一位被驱逐的西部荒野南瓜农，他和妻子维娜一起被困在贾森农场附近的路上。他们被迪菲亚潜行者赶出了家园，这对夫妇正试图修理他们损坏的马车，以便逃往艾尔文森林。",h="农夫西奥多·法布隆是一位被驱逐的西部荒野南瓜农，他和妻子维娜一起被困在贾森农场附近的路上。他们被迪菲亚潜行者赶出了家园，这对夫妇正试图修理他们损坏的马车，以便逃往艾尔文森林。",kw={"blanchy","迪菲亚","法布隆","传家宝","贾森","南瓜","西奥多","维娜","马车","怀表"},ang={["faction:Alliance"]="西奥多·法布隆的困境代表了西部荒野民政权力的彻底崩溃，王国忠诚的公民们被迫抛弃家园，却没有任何皇家士兵来保卫他们。"},sec={{t="装在马车上的生活",b="西奥多·法布隆曾经在西部荒野北部耕种一片南瓜地，但日益严重的犯罪浪潮迫使他和妻子维娜抛弃了他们所拥有的一切。他们收拾起所有能带走的东西，出发前往安全的艾尔文森林，并敦促像农夫萨丁这样的邻居也随之撤离。灾难在贾森农场附近的道路上降临，他们的马车抛锚了，使他们暴露在强盗和野兽的眼皮底下，被困在那里。当维娜照料着他们心爱的老马布兰契时，西奥多在绝望中注视着道路，渴望找回珍贵的物品——比如维娜的父亲在他们婚礼当天送给他的那块怀表——并希望能向哨兵岭发出警告，提醒他们逼近的强盗。"},{t="土地掠夺的证据",b="在法布隆夫妇逃离之前，迪菲亚暴徒威逼西奥多交出了他的农田地契，上面还有维娜的共同签名，他们认为这可以用来伪造他们自己的地契。如果冒险者能从强盗手中夺回这份地契并交还给他，那么一旦西部荒野再次变得适合诚实的人民居住，法布隆夫妇就有机会收回他们的土地。"}},faq={{q="农夫法布隆是谁？",a="西奥多·法布隆是一位来自西部荒野北部的流离失所的南瓜农。他和妻子维娜被迪菲亚潜行者强行赶出了家园，目前正被困在贾森农场附近他们那辆坏掉的马车旁。",al={"农夫法布隆","西奥多·法布隆","法布隆是谁"}},{q="为什么农夫法布隆被困在路上？",a="在从西部荒野逃往艾尔文森林的途中，他的马车坏了。在他修好马车或找到帮助之前，他和妻子只能带着他们的老马布兰契，蜷缩在路边。",al={"为什么他的马车坏了","法布隆为什么在路上","西部荒野坏掉的马车"}},{q="农夫法布隆丢失了什么传家宝？",a="在匆忙逃离农场期间，西奥多遗落了一块珍贵的怀表，那是维娜的父亲在他们婚礼那天送给他的。他请求那些有足够勇气穿过强盗横行的农场的旅行者把它带回来。",al={"被遗忘的传家宝怀表","法布隆的怀表","怀表"}},{q="农夫法布隆在西部荒野之外还有亲人吗？",a="没有记录显示他在西部荒野外有亲属。他的家人就是他的妻子维娜，此刻她正和他们的老马布兰契一起，陪他困在坏掉的马车旁。",al={"法布隆的家庭","法布隆的兄弟"}}},fp="15,193,24.554.0,24.341.1,23.210.0,44.137.0,39.127.0,54.162.0"}
P.entries["npc:farmer-saldean"] = {n="农夫萨丁",s="农夫萨丁是一位坚韧的人类垦荒者，他与妻子萨尔玛一起居住在西部荒野中部的萨丁农场。与许多逃离或放弃家园的邻近农夫不同，萨丁固执地守着他那多灾多难的农田，直面流氓收割傀儡和日益猖獗的强盗。",h="农夫萨丁是一位坚韧的人类垦荒者，他与妻子萨尔玛一起居住在西部荒野中部的萨丁农场。与许多逃离或放弃家园的邻近农夫不同，萨丁固执地守着他那多灾多难的农田，直面流氓收割傀儡和日益猖獗的强盗。",kw={"鸡饲料","农夫萨丁","收割看守者","萨丁","萨丁农场","萨尔玛","杀戮战场","西部荒野"},ang={["faction:Alliance"]="萨丁体现了西部荒野剩余忠诚者顽强的决心，即使在王国的士兵无处可寻时，依然紧守着王国的土地。",["profession:Cooking"]="像萨丁这样的农夫是暴风城食物供应中崩溃的脊梁；保护他的收成能让王国各地的人民吃上基本的面包。"},sec={{t="坚守耕犁",b="农夫萨丁还记得西部荒野曾经美好的日子。那些繁荣的岁月早已化为尘土。在杂草丛生的田野、横冲直撞的机械收割看守者和掠夺成性的强盗包围下，萨丁拒绝放弃他的土地。当其他垦荒者抛弃了他们的土地或转行做了盗贼时，他和他的妻子萨尔玛仍决心收获他们所能得到的仅存的一点谷物。出于现实的绝望，他招募过往的冒险者去摧毁那些占领了他自己和邻居农田的流氓收割看守者，以便清理土地进行耕种。"},{t="西部荒野的镰刀",b="萨丁对自己家园的顽强防守，使他成为哨兵岭和北部大桥之间平民生活中仅存的几个支柱之一。尽管环境恶劣，他仍与人民民兵保持着联系，一旦他自己眼前的问题解决，就会将有能力的旅行者引荐给格里安·斯托曼。萨丁非常清楚，清理掉野生的收割者只能为他的农场赢得暂时的喘息机会，除非能解决困扰整个乡村地区更广泛的无法无天的局面。"}},faq={{q="农夫萨丁是谁？",a="萨丁是一位资深的人类农夫，与妻子萨尔玛居住在西部荒野的萨丁农场。他是当地少数即使在饥荒、流氓收割傀儡和该地区日益严重的强盗活动的威胁下，仍固执地拒绝放弃土地的垦荒者之一。",al={"萨丁","萨丁是谁","萨丁npc"}},{q="为什么农夫萨丁的农场会有麻烦？",a="西部荒野的自动化收割傀儡发生了故障并陷入疯狂，它们在农田中徘徊，攻击视野内的任何人。萨丁需要冒险者去摧毁他自己农场和邻近农场的机械看守者，以便收复土地。",al={"为什么收割傀儡会攻击","萨丁农场问题"}},{q="在哪里可以找到农夫萨丁？",a="他位于萨丁农场的农舍外，就在西部荒野中心的主路旁，哨兵岭的北面。",al={"萨丁位置","萨丁在哪里","萨丁农场位置"}},{q="萨丁支持人民民兵吗？",a="是的。虽然萨丁主要专注于保卫自己的农作物和家园，但他会将有能力的冒险者指引到哨兵岭找格里安·斯托曼，以协助人民民兵保卫该地区。",al={"萨丁格里安·斯托曼","萨丁民兵"}},{q="萨丁出售什么独特的物品？",a="萨丁出售主食面包，并且是特殊的鸡饲料的主要供应商，这是一种奇怪的谷物，受到那些希望能与西部荒野当地禽类交好的旅行者的追捧。",al={"萨丁商贩","特殊的鸡饲料商贩"}}},fp="14,221,16.536.0,22.421.0,22.247.0,40.244.0,34.139.0,42.185.0,36.169.0"}
P.entries["npc:farthing"] = {n="Farthing",s="主教法席恩是一位居住在暴风城Cathedral of Light内的人类神职人员。作为一名圣光善良而睿智的仆人，他为教区居民提供指引，并将援助引向王国各地处境艰难的定居点。",h="主教法席恩是一位居住在暴风城Cathedral of Light内的人类神职人员。作为一名圣光善良而睿智的仆人，他为教区居民提供指引，并将援助引向王国各地处境艰难的定居点。",kw={"本尼迪塔斯","主教法席恩","cathedral of light","farthing","摩尔班·菲尔","寻求智慧","暴风城"},ang={["class:Priest"]="对于造访Cathedral of Light的牧师来说，法席恩代表了暴风城人类神职人员既定的等级制度和学术智慧。",["faction:Alliance"]="在暮色森林等联盟南部领地对抗蔓延腐蚀的冒险者们，会寻求法席恩及其同僚神职人员的神圣洞察与精神指引。"},sec={{t="暴风城的一位主教",b="在Cathedral of Light宁静的大理石殿堂中，主教法席恩是照料暴风城民众精神需求的重要人物之一。他与大主教本尼迪塔斯及其他神职人员一道，为旅行者提供建议，协助那些追求神圣艺术的人，并履行圣光教会的公民和牧灵职责。"},{t="对瘟疫之地的援助",b="尽管身处首都，法席恩仍会指引诚恳的旅行者前往王国那些急需神圣援助的阴暗角落。当有关死灵法师摩尔班·菲尔以及席卷暮色森林的亡灵天灾的忧虑报告传来时，法席恩会担任顾问，设法寻找克服黑暗魔法并净化被瘟疫侵蚀的前线区域的方法。"}},faq={{q="主教法席恩在哪里？",a="主教法席恩居住在Cathedral of Light内，位于暴风城Cathedral Square的中心。",al={"法席恩位置","法席恩在哪里","法席恩地图"}},{q="法席恩在教堂中扮演什么角色？",a="他是圣光教会的一名授职主教，为来访的信徒、受训的牧师以及寻求圣光智慧以援助遥远定居点的冒险者提供指导。",al={"法席恩做什么","法席恩是谁"}},{q="法席恩与暮色森林有何关联？",a="法席恩会被处理暮色森林亡灵威胁的冒险者求助，他会就维持死灵法师摩尔班·菲尔存在的黑暗艺术提供建议，并指引人们净化受污染的灵魂。",al={"法席恩暮色森林","法席恩摩尔班·菲尔"}},{q="法席恩与其他同姓的市民有关系吗？",a="人类领地中有几位姓氏为法席恩的个人，包括库勒曼·法席恩和伊维特·法席恩，但他本人从未主动提起过任何直接的家庭关系。",al={"库勒曼·法席恩亲属","法席恩家族"}}},fp="8,170,21.282.0,24.281.0,35.107.0,46.174.0,39.166.0,60.158.0"}
P.entries["npc:feegly-the-exiled"] = {n="被流放的费格雷",s="被流放的费格雷是一个矮人流放者，常在南贫瘠之地的巴尔莫丹矮人挖掘场附近徘徊。他曾经被誉为该探险队中最优秀的挖掘工之一，但因对一件出土遗物的痴迷而被双辫将军驱逐。",h="被流放的费格雷是一个矮人流放者，常在南贫瘠之地的巴尔莫丹矮人挖掘场附近徘徊。他曾经被誉为该探险队中最优秀的挖掘工之一，但因对一件出土遗物的痴迷而被双辫将军驱逐。",kw={"巴尔莫丹","贫瘠之地","挖掘者","挖掘","被放逐的","费格雷","众月之泪","穴居怪"},ang={["faction:Horde"]="费格雷对巴尔莫丹挖掘者的怨恨，使他成为了部落流浪者破坏贫瘠之地矮人探险行动的意外盟友。",["race:Dwarf"]="对于矮人来说，费格雷是一个悲惨而可怕的警示：一位卓有成就的挖掘者因痴迷于出土的遗物，而失去了在族人中的地位。"},sec={{t="挖掘者的毁灭",b="在被流放之前，费格雷被认为是巴尔莫丹最出色的挖掘者之一。“众月之泪”是他们在挖掘场发现的第一件重大文物，费格雷声称这件文物的力量属于他。双辫将军称这颗宝石受到了诅咒，将其锁在巴尔丹城堡并赶走了费格雷。他现在独自一人，不顾一切地想要夺回那颗让他遭受诅咒的宝石：当他最终再次握住它时，众月之泪碎裂了，他也变成了一个丑陋、驼背的穴居怪。"}},faq={{q="谁是被流放的费格雷？",a="费格雷是一个矮人，是被巴尔莫丹挖掘场驱逐的挖掘者，他垂涎着一件被称为“众月之泪”的遗物。",al={"谁是费格雷","费格雷背景故事","被流放的费格雷"}},{q="费格雷为何被巴尔莫丹驱逐？",a="费格雷对“众月之泪”产生了痴迷，这是巴尔莫丹发现的第一件重大文物。双辫将军称这颗宝石受到了诅咒，将其锁在巴尔丹城堡并赶走了费格雷。",al={"为什么被放逐","费格雷做了什么","费格雷的流放"}},{q="为什么费格雷愿意与部落冒险者交谈？",a="被同族矮人背叛并驱逐后，费格雷对联盟探险队毫无忠诚可言。他已绝望到不惜寻求部落旅行者的帮助，以取回他梦寐以求的遗物。",al={"为什么费格雷对部落友好","费格雷对部落友好"}},{q="什么是众月之泪？",a="众月之泪是挖掘者在巴尔莫丹发现的一颗宝石，也是他们在那里的第一个重大发现。费格雷声称它给了他力量，但双辫将军认为它受到了诅咒，并将其锁在巴尔丹城堡中。",al={"众月之泪","费格雷的宝石","费格雷的遗物"}}},fx={["21513985"]={q="被流放的费格雷是谁？",a="费格雷是来自贫瘠之地南部巴尔莫丹挖掘场的一名被流放的矮人挖掘者。他徘徊在挖掘场外，一心想找回一件名为众月之泪的遗物。",al={"费格雷是谁","费格雷的身份","费格雷的背景"}},ed9ce58e={q="被流放的费格雷想要什么？",a="费格雷想要得到众月之泪，这件遗物奇异的力量令他垂涎。他招募愿意帮忙的旅人前往巴尔丹城堡取回遗物，好让自己再次拥有它。",al={"费格雷想要什么","费格雷的动机","费格雷为什么需要众月之泪"}},["7eaaafaa"]={q="被流放的费格雷为什么在贫瘠之地？",a="费格雷徘徊在巴尔莫丹外的山丘上，因为双辫将军把他赶了出去，并将众月之泪锁了起来。他急于找回宝石，因此仍留在昔日挖掘场附近。",al={"费格雷为什么在这里","费格雷在哪里逗留","费格雷为什么在巴尔莫丹外"}},["0b854105"]={q="被流放的费格雷与谁有关联？",a="费格雷与巴尔莫丹的矮人远征队有关。他曾是队伍中最出色的挖掘者之一，后来遭到放逐。如今他与族人断绝往来，只能依靠路过的部落旅人为他办事，对付挖掘场的人。",al={"费格雷的关系","费格雷与谁合作","费格雷的人脉"}}},fp="17,252,15.460.1,25.113.0,38.184.0,51.189.0,30.214.0"}
P.entries["npc:feero-ironhand"] = {n="费罗·艾隆汉",s="费罗·艾隆汉是一名驻扎在灰谷西部的迈斯特拉岗哨的人类圣骑士。他守卫着黑海岸与森林之间的边界，并与净化者德尔格伦密切合作，共同对抗阴险的暗滩邪教。",h="费罗·艾隆汉是一名驻扎在灰谷西部的迈斯特拉岗哨的人类圣骑士。他守卫着黑海岸与森林之间的边界，并与净化者德尔格伦密切合作，共同对抗阴险的暗滩邪教。",kw={"灰谷","奥伯丁","暗滩邪教","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨"},ang={["faction:Alliance"]="对于从黑海岸前往危险的灰谷荒野的联盟旅行者来说，费罗提供了一个重要的落脚点。",["race:Human"]="在古老的暗夜精灵森林灰谷中看到一名人类守卫，是联盟通力协作的一个令人欣慰的象征。"},sec={{t="迈斯特拉岗哨的防线",b="Located along the road leading south from Darkshore into Ashenvale, Maestra's Post serves as a critical watchpoint for travelers and Alliance defenders alike. Feero Ironhand operates out of this outpost, maintaining communications and trade lines with Auberdine while keeping a vigilant watch over the surrounding woods. Together with Delgren the Purifier, Feero focuses his efforts against the malevolent Cult of the Dark Strand, ensuring the cultists and forest predators do not sever the path between Darnassus's supply lines and the front lines of Ashenvale."}},faq={{q="费罗·艾隆汉是谁？",a="费罗·艾隆汉是一名驻扎在灰谷西部迈斯特拉岗哨的联盟人类圣骑士。他为往返于黑海岸和灰谷之间的旅行者提供帮助，并协调与奥伯丁之间的后勤工作。",al={"费罗·艾隆汉","费罗是谁","费罗npc"}},{q="费罗在迈斯特拉岗哨的目的是什么？",a="费罗协助守卫该哨所，抵御当地威胁，支持净化者德尔格伦对抗暗滩邪教，同时确保通往黑海岸的重要信使和补给路线畅通无阻。",al={"为什么费罗在这里","费罗的角色","迈斯特拉岗哨人类"}},{q="什么是暗滩邪教？",a="暗滩邪教是一个在灰谷北部活动的邪恶组织，他们沉迷于黑魔法和污秽的仪式。迈斯特拉岗哨的联盟部队正积极采取行动，破坏并瓦解他们的活动。",al={"暗滩邪教","暗滩邪教组织","暗滩"}},{q="费罗与银色黎明有联系吗？",a="目前没有关于他与银色黎明有关联的记录。费罗本身是一名圣骑士，他与同样身为人类圣骑士、在森林中对抗黑暗力量的净化者德尔格伦紧密合作。",al={"费罗银色黎明","费罗是银色黎明成员吗"}}},fx={["996da789"]={q="费罗·艾隆汉支持哪一方？",a="费罗·艾隆汉坚定地支持联盟。他驻守在迈斯特拉岗哨——灰谷西部边境一处重要的暗夜精灵哨站——帮助旅人和当地军队对抗威胁这片古老森林的敌人。",al={"费罗·艾隆汉的阵营","费罗是联盟的吗","费罗·艾隆汉支持哪一方"}},bf9a9ed2={q="费罗·艾隆汉想要什么？",a="费罗的目标是支援迈斯特拉岗哨的守军，挫败阴险的黑海岸邪教。他与净化者德尔格伦并肩作战，力求清除他们在卡利姆多北部的腐化势力，并维持灰谷与黑海岸之间的补给线。",al={"费罗·艾隆汉的目标","费罗想要什么","费罗的动机"}}},fp="14,254,27.562.0,22.199.0,42.193.0,36.216.0,47.176.0"}
P.entries["npc:fel-zerul"] = {n="费泽鲁尔",s="费泽鲁尔是一位驻扎在悲伤沼泽昏暗深处斯通纳德的兽人术士。他直接听命于萨尔大酋长，负责调查潜伏在沉没的神庙——阿塔哈卡神庙中的险恶存在。",h="费泽鲁尔是一位驻扎在悲伤沼泽昏暗深处斯通纳德的兽人术士。他直接听命于萨尔大酋长，负责调查潜伏在沉没的神庙——阿塔哈卡神庙中的险恶存在。",kw={"阿塔哈卡神庙","费泽鲁尔","斯通纳德","悲伤沼泽","萨尔","术士"},ang={["class:Warlock"]="费泽鲁尔代表了萨尔对术士的正式任用，这表明新部落偶尔也会依赖黑暗艺术的修行者来对抗晦涩、深奥的威胁。",["faction:Horde"]="费泽鲁尔驻扎在斯通纳德，担任预警侦察员，确保沼泽中滋生的任何黑暗魔法都不会对部落在该地区的立足点造成突袭。"},sec={{t="关注沉没的神庙",b="虽然萨尔的部落通常对黑暗艺术持怀疑态度，但大酋长明白，了解邪恶力量需要那些研究它们的人。费泽鲁尔被专门派往斯通纳德，以揭开围绕泪水之池和被淹没的阿塔哈卡神庙的腐化之谜。通过指导冒险者回收神器并调查流亡的阿塔莱巨魔，这位术士试图在阴暗水域下的邪恶威胁到部落的南部哨所之前，查清究竟是什么在作祟。"}},faq={{q="费泽鲁尔是谁？",a="费泽鲁尔是一位居住在斯通纳德的兽人术士，斯通纳德是部落在悲伤沼泽的据点。他担任调查员，分析附近阿塔哈卡神庙中正在展开的黑暗仪式。",al={"费泽鲁尔","费泽鲁尔是谁","斯通纳德术士"}},{q="萨尔为什么要派一名术士去斯通纳德？",a="萨尔大酋长派遣费泽鲁尔是因为处理古老的诅咒和血腥仪式需要精通黑暗巫术的专家。费泽鲁尔的任务是监控沉没神庙周围令人不安的事态发展，并保护部落在沼泽中的利益。",al={"萨尔 费泽鲁尔","费泽鲁尔为什么在这里","费泽鲁尔的任务"}},{q="费泽鲁尔在调查什么？",a="费泽鲁尔正在调查阿塔哈卡神庙中泪水之池里的阿塔莱巨魔及其亵渎仪式。他招募侦察兵和冒险者去搜寻神器，并追查可能掌握关键知识的流亡祭司。",al={"费泽鲁尔任务背景","费泽鲁尔想要什么","泪水之池调查"}}},fp="9,228,25.509.0,17.203.0,41.259.0,32.240.0"}
P.entries["npc:felgur-twocuts"] = {n="费古尔·双刃",s="费古尔·双刃是驻扎在凄凉之地幽灵岗哨的一名粗鲁的兽人斥候。他负责协调部落针对该地区半人马氏族的作战行动。",h="费古尔·双刃是驻扎在凄凉之地幽灵岗哨的一名粗鲁的兽人斥候。他负责协调部落针对该地区半人马氏族的作战行动。",kw={"半人马赏金","凄凉之地","费古尔·双刃","幽灵岗哨","部落","科卡尔","兽人"},ang={["faction:Horde"]="费古尔在幽灵岗哨担任重要的行动联络员，帮助部落抵御凄凉之地咄咄逼人的半人马部落。",["race:Orc"]="秉持兽人在危险边境地带的一贯务实作风，费古尔看重力量、速度和立竿见影的成果，胜过闲谈。"},sec={{t="粗鲁的前哨斥候",b="费古尔·双刃站在凄凉之地中部幽灵岗哨那片荒凉的空地上，对客套话毫无耐心。作为部落的前线斥候，他负责评估那些穿越群山向西进发的旅行者和定居者所面临的威胁，尤其是当地的科卡尔半人马。"},{t="半人马之战",b="费古尔指挥部落勇士去猎杀当地的半人马首领，并搜集那些威胁要占领该地区的交战部落的赏金。对于任何寻求巩固部落在凄凉之地立足点的人来说，他是一个核心联络人。"}},faq={{q="费古尔·双刃是谁？",a="费古尔·双刃是一位兽人斥候和任务发布者，驻扎在凄凉之地的部落前哨站——幽灵岗哨。",al={"费古尔·双刃是谁","费古尔是谁"}},{q="我在哪里可以找到费古尔·双刃？",a="他位于幽灵岗哨，就在穿过凄凉之地的中央道路北侧。",al={"费古尔·双刃位置","费古尔在哪里","费古尔·双刃在哪里"}},{q="费古尔·双刃发布什么任务？",a="费古尔招募部落冒险者去打击当地的科卡尔半人马，追杀可汗德兹赫帕，并搜集敌对半人马的赏金。",al={"费古尔任务","费古尔想要什么"}},{q="为什么费古尔对访客如此生硬？",a="凄凉之地是一片危险而无情的荒原，周围环绕着敌对的半人马氏族。费古尔驻扎在偏远的岗哨，没有时间闲聊，更倾向于专注于生存和军事职责。",al={"为什么费古尔很粗鲁","快点费古尔"}}},fx={f5a09a6e={q="费古尔·双刃支持哪一方？",a="费古尔是部落的骄傲成员，驻守在遥远的边境，致力于推进部落的利益，并保护他们的营地免受当地威胁。",al={"费古尔·双刃的阵营","费古尔是部落的吗","费古尔效忠谁"}},["8c623583"]={q="费古尔·双刃想要什么？",a="费古尔想要遏制威胁凄凉之地部落的敌对半人马氏族。他招募有能力的勇士领取悬赏，并与可汗德兹赫帕交锋。",al={"费古尔·双刃的目标","费古尔想做什么","费古尔需要什么"}},a5d710fc={q="费古尔·双刃为什么驻扎在这里？",a="费古尔驻扎在幽灵岗哨，负责监视当地半人马部族，并指挥行动，应对威胁部落在凄凉之地立足之地的敌人。",al={"费古尔·双刃为什么在幽灵岗哨","费古尔在这里的职责","费古尔为什么在这里"}}},fp="14,144,21.297.0,18.233.0,22.122.0,32.92.0,36.138.0,36.213.0"}
P.entries["npc:felix-whindlebolt"] = {n="菲利克斯",s="菲利克斯是一位无家可归的侏儒难民，目前正在寒脊山谷的安威玛尔避难。他在逃离淹没诺莫瑞根的辐射时太过匆忙，弄丢了自己的私人物品，随后被充满敌意的霜鬃巨魔抢走了。",h="菲利克斯是一位无家可归的侏儒难民，目前正在寒脊山谷的安威玛尔避难。他在逃离淹没诺莫瑞根的辐射时太过匆忙，弄丢了自己的私人物品，随后被充满敌意的霜鬃巨魔抢走了。",kw={"安威玛尔","寒脊山谷","菲利克斯","霜鬃","诺莫瑞根","难民","白须营地"},ang={["race:Dwarf"]="当地的霜鬃巨魔在寒脊山谷中变得越来越猖獗，袭击了在安威玛尔附近徘徊的脆弱侏儒难民。",["race:Gnome"]="菲利克斯代表了你流离失所的同胞所面临的持续困境，在诺莫瑞根的灾难之后，他们被迫流落到残酷无情的丹莫罗寒冬之中。"},sec={{t="一名流离失所的旅行者",b="诺莫瑞根悲惨陷落之后，成千上万的侏儒发现自己流落于冰天雪地的丹莫罗，四处寻找安身之所。菲利克斯在逃离那座充满辐射的城市时过于匆忙，以至于弄丢了所有的个人财物和工具。更糟糕的是，霜鬃冰巨魔把他那箱子、盒子和一桶螺栓搬回了安威玛尔西南方的营地，让他陷入了困境，身无分文，只能依靠热心的游侠帮他取回被盗的装备。"}},faq={{q="菲利克斯是谁？",a="菲利克斯是一位侏儒难民，目前在寒脊山谷的安威玛尔避难。他在逃离诺莫瑞根时弄丢了财物，被当地的霜鬃巨魔抢走了。",al={"菲利克斯是谁","菲利克斯的背景故事","白须营地的侏儒"}},{q="菲利克斯原本想去哪里？",a="菲利克斯当时正在逃离诺莫瑞根的辐射。此前侏儒试图驱逐石腭怪，但行动彻底失败，导致城市被辐射吞没。他最终来到了安威玛尔，也就是位于寒脊山谷的矮人哨站，尽管他觉得那个地方并不适合侏儒居住。",al={"菲利克斯要去哪","菲利克斯的目的地","为什么菲利克斯在寒脊山谷"}},{q="他的财物发生了什么事？",a="在逃离诺莫瑞根的匆忙中，菲利克斯弄丢了他的箱子、盒子和一桶螺栓。霜鬃冰巨魔把它们搬到了安威玛尔西南方的营地，导致他身无分文，陷入困境。",al={"谁偷了菲利克斯的东西","菲利克斯被偷的装备","霜鬃巨魔与菲利克斯"}},{q="菲利克斯会向冒险者出售什么商品吗？",a="什么都不卖。菲利克斯不是商人：他在逃离诺莫瑞根时失去了所有的财产，在安威玛尔，他只能向那些帮他找回箱子、盒子和一桶螺栓的人表示感谢。",al={"菲利克斯出售的物品","菲利克斯提供什么","菲利克斯的库存"}}},fx={b1540142={q="菲利克斯支持哪一方？",a="菲利克斯支持诺莫瑞根流亡者和大联盟。和许多流离失所的侏儒一样，他逃离了受到辐射污染的诺莫瑞根废墟，如今在寒脊山谷的安威玛尔避难，希望能与族人团聚。",al={"菲利克斯的阵营","菲利克斯是联盟的吗","菲利克斯为谁效力"}}},fp="17,232,20.489.0,25.180.0,29.244.0,33.208.0,36.183.0"}
P.entries["npc:fenrus-the-devourer"] = {n="吞噬者芬鲁斯",s="吞噬者芬鲁斯是一只庞大的座狼，在影牙城堡的上层圣殿中徘徊。作为大法师阿鲁高的私人宠物和守卫，这只贪婪的野兽因充斥着非自然的魔法而变得臃肿不堪。任何胆敢闯入大法师私人书房的人，都必须面对这只狂野的恐怖生物以及守护着它的主人。",h="吞噬者芬鲁斯是一只庞大的座狼，在影牙城堡的上层圣殿中徘徊。作为大法师阿鲁高的私人宠物和守卫，这只贪婪的野兽因充斥着非自然的魔法而变得臃肿不堪。任何胆敢闯入大法师私人书房的人，都必须面对这只狂野的恐怖生物以及守护着它的主人...",kw={"阿鲁高","芬鲁斯","吞噬者芬鲁斯","影牙城堡","银松森林","座狼"},ang={["class:Hunter"]="不要浪费时间试图魅惑芬鲁斯。这只野兽的心智已被影牙城堡的黑暗艺术不可逆转地扭曲，无法被野性所束缚。",["class:Mage"]="芬鲁斯的出现令人毛骨悚然地提醒着人们，大法师阿鲁高已经堕落到何种地步——他利用奥术扭曲野生野兽，将其变成了怪诞的家养守卫。",["class:Warlock"]="大法师阿鲁高能召唤虚空行者来协助他的猎犬，这揭示了这位前达拉然法师在暗影禁忌召唤术中钻研得有多深。"},sec={{t="大法师书房里的野兽",b="在影牙城堡深处，大法师阿鲁高的私人房间外，潜伏着被称为吞噬者芬鲁斯的恐怖座狼。与徘徊在城墙上的狼人不同，芬鲁斯是一只真正的座狼，身体膨胀到了巨大的比例。这只野兽在阿鲁高私人书房的书架、卷轴和奥术装置间徘徊，既是宠物，又是防止任何企图取下这位疯狂法师首级的人入侵的暴力守卫。"},{t="被腐蚀的力量",b="芬鲁斯那不自然的庞大身躯表明，自从席瓦莱恩男爵陨落以来，它就一直受到充斥在城堡内的黑暗魔法的影响。大法师阿鲁高或他放出的狼人显然用奥术或暗影实验扭曲了这种生物，将一种本土的捕食者变成了一台贪婪的杀戮机器。芬鲁斯极其狂野，且被魔法束缚，任何猎人都无法魅惑或驯服它的心智。"},{t="阿鲁高的警觉之眼",b="打扰芬鲁斯对粗心大意者来说无异于自寻死路。当这只野兽发现入侵者时，它会发出震耳欲聋的嚎叫，回荡在整座堡垒中，直接引起阿鲁高本人的注意。大法师并不会让他的宠物孤军奋战，而是会将他的黑暗意志投射到房间里，召唤虚空行者协助芬鲁斯去淹没并吞噬入侵者。"}},faq={{q="芬鲁斯是什么生物？",a="芬鲁斯是一只体型异常庞大的座狼，这是一种洛丹伦本土的狼型捕食者，而非双足行走的狼人。它那不自然的庞大身躯和凶残的野性，是长期暴露在影牙城堡内施展的黑暗魔法下的直接结果。",al={"芬鲁斯是狼人吗","芬鲁斯生物类型","芬鲁斯是狼吗"}},{q="哪里可以找到芬鲁斯？",a="芬鲁斯在银松森林的影牙城堡高层的书房中徘徊。它的巢穴就位于通往大法师阿鲁高核心防御据点的必经之路上。",al={"芬鲁斯在哪里","芬鲁斯位置","芬鲁斯房间"}},{q="猎人可以驯服芬鲁斯作为宠物吗？",a="不能。尽管在分类上属于普通野兽，但芬鲁斯无法被驯服。它的心智已被彻底摧毁且变得狂野，并与大法师阿鲁高的黑暗意志紧密相连。",al={"可以驯服芬鲁斯吗","芬鲁斯可驯服吗","驯服芬鲁斯"}},{q="为什么芬鲁斯受到攻击时阿鲁高会召唤恶魔？",a="阿鲁高将芬鲁斯视为他珍视的宠物，也是他圣殿前的最后一道防线。当芬鲁斯在进入战斗时发出咆哮，阿鲁高便会直接干预，在房间中召唤虚空行者来淹没任何威胁他野兽的敌人。",al={"阿鲁高虚空行者","为什么阿鲁高会帮助芬鲁斯","芬鲁斯虚空行者小怪"}},{q="为什么芬鲁斯比普通的座狼大这么多？",a="芬鲁斯巨大的体型被认为是大法师阿鲁高黑暗魔法实验的结果，亦或是狼人侵染整座城堡后产生的魔法余波所致。",al={"为什么芬鲁斯这么大","芬鲁斯体型背景","巨型座狼"}},{q="战斗中芬鲁斯会发生什么？",a="当芬鲁斯加入战斗时，它会发出震耳欲聋的吼叫，整个影牙城堡内的人都能听到，从而提醒所有人阿鲁高房门外正在爆发战斗。",al={"芬鲁斯咆哮","芬鲁斯全副本嚎叫","影牙城堡巨响"}}},fx={b2b015f0={q="芬鲁斯支持哪一方？",a="芬鲁斯对大法师阿鲁高忠心耿耿。作为这名术士的私人魔兽和守卫，它听从影牙城堡主人扭曲意志的驱使，毫不犹豫地攻击任何擅闯上层圣所的入侵者。",al={"芬鲁斯的阵营","芬鲁斯效忠谁","芬鲁斯效忠对象"}},["01e73d00"]={q="芬鲁斯为什么在影牙城堡？",a="芬鲁斯在主书房中巡游，这间书房与阿鲁高的私人房间直接相连。它既是宠物，也是凶猛的看门犬，被安置在那里撕碎任何企图闯入大法师内室的人。",al={"芬鲁斯为什么在这里","芬鲁斯的位置和职责","芬鲁斯为什么守着书房"}}},fp="19,322,29.436.0,15.369.0,21.397.1,32.260.0,26.167.0,33.157.0,54.234.0,47.174.0,55.191.0"}
P.entries["npc:field-marshal-snowfall"] = {n="大元帅斯诺·落雪",s="大元帅斯诺·落雪是一位驻扎在铁炉堡Military Ward的矮人军官，负责协调联盟针对日益严重的其拉虫人威胁的战争行动。面对在希利苏斯南部沙漠中苏醒的古老邪恶，他统筹着武装盟军所需的庞大后勤补给工作。落雪负责追踪捐赠的原材料，并奖励那些为王国战备做出贡献的人。",h="大元帅斯诺·落雪是一位驻扎在铁炉堡Military...",kw={"安其拉","大元帅斯诺·落雪","铁炉堡","military ward","印记","希利苏斯","落雪","战争行动"},ang={["faction:Alliance"]="落雪代表了联盟统一的工业和军事意志，他号召从暴风城到To Darnassus的每一个种族清空他们的仓库，为即将到来的战斗做好准备。",["race:Dwarf"]="落雪驻扎在Great Forge的军事区，他自豪地谈论着要保护泰坦的造物免受一种古老而根深蒂固的堕落侵害。"},sec={{t="安其拉作战物资军需官",b="大元帅斯诺·落雪伫立在铁炉堡的Military Ward，担任联盟针对安其拉动员行动的核心协调员。他认为这场酝酿中的冲突不仅仅是一场边境冲突，而是针对泰坦造物所面临的一个古老敌人的关键战役。落雪监管着数量惊人的补给储备——数百万张绷带、成吨的金属锭、皮革、草药和冒险者收集来的口粮——以确保联盟军队在向南进军希利苏斯时，能够拥有充足的武器、盔甲和补给。"},{t="通往希利苏斯之路",b="动员整个阵营需要联盟各领地铁匠、采集者、厨师和士兵之间的通力协作。落雪监督着这项浩大工程的每一个阶段，接受嘉奖印记，并向志愿者提供物资征用任务。一旦双方阵营收集齐所需的战争物资，这些储备就会打包运往南方的塞纳里奥要塞，为对甲虫之墙后的虫群和上古之神发起的全面进攻做好准备。"}},faq={{q="谁是大元帅斯诺·落雪？",a="大元帅斯诺·落雪是一位驻扎在铁炉堡Military Ward的高级矮人指挥官。他的任务是负责监督和统计联盟为即将到来的希利苏斯针对其拉虫人的战争所进行的大规模物资收集工作。",al={"落雪的职责","谁是落雪","大元帅斯诺·落雪背景故事"}},{q="联盟为什么要收集这么多补给？",a="一股古老的力量正从安其拉之门外威胁着卡利姆多。为了在希利苏斯残酷的沙漠中发起一场成功的战役，联盟必须在军队开拔前积攒巨额的盔甲、金属锭、医疗绷带、食物和草药储备。",al={"为什么要捐赠布料","战争行动的目的","为什么需要战争物资"}},{q="收集的物资在完成后会被送往何处？",a="一旦联盟和部落都完成了各自的物资收集配额，商队和补给船会将庞大的储备运往希利苏斯的塞纳里奥要塞，联军将在那里建立前线补给站。",al={"物资去向","物资用途"}},{q="战争物资印记有什么用？",a="印记是奖励给那些为战争捐赠所需武器和材料的贡献者的。大元帅斯诺·落雪会成批地接受这些印记，并向尽职的联盟公民提供补给箱和装备作为服务的奖励。",al={"印记上交","印记用途"}}},fx={ec7ab6f1={q="大元帅斯诺·落雪效忠哪一方？",a="大元帅斯诺·落雪是联盟忠诚坚定的指挥官，驻扎在铁炉堡的Military Ward，负责统筹联盟各地的后勤与资源收集，为在卡利姆多发动联合攻势做准备。虽然这场行动要求联盟与部落勉强并肩合作，以筹集足够的物资，但落雪坚定效忠于大联盟的各个王国。",al={"大元帅斯诺·落雪属于联盟还是部落","落雪的阵营","落雪效忠谁"}},e1b72348={q="大元帅斯诺·落雪想要什么？",al={"大元帅斯诺·落雪的目标","落雪需要什么","落雪的任务目标"}},a597c3d5={q="大元帅斯诺·落雪为什么在铁炉堡？",a="落雪在铁炉堡的Military Ward设立了指挥部，因为这座矮人山城是联盟工业和贸易的中心枢纽。在这里，他可以追踪货运清单，协调由士兵市民收集并运来的物资，并在补给跨海运往希利苏斯集结地之前，备齐堆积如山的军需品。",al={"落雪为什么在铁炉堡","落雪和军事区","大元帅斯诺·落雪为什么在这里"}}},fp="22,407,37.558.0,20.505.0,30.238.0,48.269.0,49.224.0,47.239.0"}
P.entries["npc:field-marshal-stonebridge"] = {n="斯托布里奇元帅",s="斯托布里奇元帅是驻扎在暴风城入口附近的一名联盟高级军官。她守卫在英雄谷的暴风城大门旁，与马库斯·乔纳森将军一同负责城防工作，并作为重大军事胜利的权威见证人。",h="斯托布里奇元帅是驻扎在暴风城入口附近的一名联盟高级军官。她守卫在英雄谷的暴风城大门旁，与马库斯·乔纳森将军一同负责城防工作，并作为重大军事胜利的权威见证人。",kw={"元帅","城门","黑石之王","马库斯·乔纳森","奈法利安","斯托布里奇","暴风城","英雄谷"},ang={["class:Warrior"]="作为驻扎在城门的最高军事指挥官之一，斯托布里奇元帅赢得了那些努力在联盟中争取高阶军衔的前线士兵的尊敬。",["faction:Alliance"]="斯托布里奇与马库斯·乔纳森将军并肩站立，代表了联盟军队守卫暴风城、抵御外敌入侵的坚定警惕。"},sec={{t="大门前的堡垒",b="斯托布里奇元帅位于英雄谷巍峨的入口内侧，在正门附近的东侧拱门下守望。她在联盟军队中的高阶军衔使她跻身暴风城战略领导层的最高层，并与马库斯·乔纳森将军紧密协作。从这个显眼的据点，她注视着进入首都的守卫、旅客和归来的勇士，随时准备在威胁突破外围防线时组织守军进行防御。"},{t="战利品的接收者",b="除了在城门履行礼仪和防御职责外，斯托布里奇元帅还负责接收针对威胁王国的最强敌人的战役中的重要报告和战利品。高级指挥官们依赖像斯托布里奇这样的军官来核实关键情报，并庆贺在战场上赢得的重大胜利，包括击败盘踞在黑石山岩壁中的军阀和怪物。"}},faq={{q="斯托布里奇元帅在哪里？",a="她站在暴风城英雄谷东北侧的一座拱门下，当你穿过城门进入时，她就在马库斯·乔纳森将军的右侧。",al={"斯托布里奇位置","斯托布里奇元帅在哪里","寻找斯托布里奇"}},{q="斯托布里奇元帅在暴风城扮演什么角色？",a="她是一名联盟高级军官，协助马库斯·乔纳森将军守卫暴风城正门，并担任重要军事情报和联盟勇士带回的重大战利品的接收官。",al={"斯托布里奇的职责","斯托布里奇的作用","谁是斯托布里奇元帅"}},{q="联盟的元帅军衔有多高？",a="元帅是联盟军队指挥体系中最高的军官军衔之一，仅次于大元帅。该军衔的军官负责监督重大的战术部署、城市防区和战略驻军。",al={"联盟元帅军衔","斯托布里奇军衔等级"}},{q="有哪些涉及斯托布里奇元帅的重要任务？",a="她是负责接收“黑石之王”任务报告和战利品的军官，当联盟冒险者将奈法利安的头颅带回暴风城大门时，她会确认这位黑龙的陨落。",al={"斯托布里奇任务","黑石之王任务完成者"}}},fp="25,172,22.375.0,18.304.0,43.167.0,54.210.0,45.198.0,52.191.1"}
P.entries["npc:first-mate-fitzsimmons"] = {n="大副菲兹莫斯",s="大副菲兹莫斯是一个衣衫褴褛、浑身恶臭的水手，他整日借酒消愁，就坐在米奈希尔港的深水旅店外。他曾是库尔提拉斯第三舰队“波浪女主人号”的大副，也是第二次战争期间那支舰队覆灭后，唯一已知的幸存者。这段惨痛的往事令他备受折磨，他一直在寻找愿意伸出援手的冒险者，去面对那些亡魂不安的昔日同僚。",h="大副菲兹莫斯是一个衣衫褴褛、浑身恶臭的水手，他整日借酒消愁，就坐在米奈希尔港的深水旅店外。他曾是库尔提拉斯第三舰队“波浪女主人号”的大副，也是第二次战争期间那支舰队覆灭后，唯一已知的幸存者。这段惨痛的往事令他备受折磨，他...",kw={"深水旅店","帕雷斯之眼","大副菲兹莫斯","菲兹莫斯","库尔提拉斯","失落的舰队","米奈希尔港","第三舰队","波浪女主人号"},ang={["faction:Alliance"]="菲兹莫斯代表了联盟海军史上悲剧性的一章，提醒着英雄们在面对部落被奴役的巨龙军团时所承受的惨重损失。",["race:Human"]="作为一名库尔提拉斯老兵，菲兹莫斯与这个航海人类王国有着深刻的文化纽带，这个王国为了在第二次战争中保卫洛丹伦付出了巨大牺牲。"},sec={{t="一个破碎的水手",b="大副菲兹莫斯在米奈希尔港潮湿咸腥的空气中，无所事事地坐在深水旅店外。由于他身上那股洗不掉的恶臭，人们很容易忽略他，甚至干脆对他避之不及。对于大多数过客来说，他不过是另一个喝得烂醉、试图用酒精麻痹记忆的颓废老水手。但如果有人愿意坐下来听他倾诉，就会听到关于一支引以为傲的舰队如何被烈火和利爪毁灭的凄惨往事。"},{t="第三舰队的覆灭",b="在第二次战争期间，菲兹莫斯曾担任第三舰队“波浪女主人号”的大副，该舰队奉命出征对抗部落。在湿地海岸外，这支舰队遭到了埋伏，并被龙喉兽人奴役的红龙焚毁。船只碎裂并沉入海底，只有菲兹莫斯一人挣扎着游回了岸边。"},{t="徘徊不去的诅咒",b="逃过龙火并没有给菲兹莫斯带来安宁。那些船只的残骸，即后人所知的“失落的舰队”，被他曾经的船员亡魂所盘踞。他们化作了受到诅咒的亡灵，无法在水下的坟墓中安息。在愧疚与恐惧的驱使下，菲兹莫斯招募旅行者去消灭这些亡灵水手，并寻回那些可能最终解除束缚他们灵魂的邪恶的远古遗物。"}},faq={{q="谁是大副菲兹莫斯？",a="他是一位年迈的库尔提拉斯水手，曾是“波浪女主人号”的大副。他在第二次战争中幸免于难，经历了库尔提拉斯第三舰队的毁灭性沉没，现在终日酗酒，蜷缩在米奈希尔港的深水旅店外。",al={"菲兹莫斯背景故事","谁是菲兹莫斯","大副菲兹莫斯"}},{q="他的船发生了什么事？",a="在第二次战争期间，“波浪女主人号”及第三舰队的其他船只遭到了龙喉氏族骑乘的被奴役红龙的埋伏。船只在湿地海岸外的礁石区被烧毁并损毁。",al={"波浪女主人号发生了什么","第三舰队覆灭","他的船为什么沉没"}},{q="失落的舰队在哪里？",a="舰队的破碎船壳沉没在湿地米奈希尔港以北的岩石海岸边，现在被鱼人和溺亡水手不安的灵魂所占据。",al={"失落的舰队位置","沉船在哪里","菲兹莫斯的船在哪里"}},{q="他为什么要冒险者去攻击他以前的船员？",a="第三舰队的溺亡水手在死后变成了受诅咒、备受折磨的亡灵，无法安息。菲兹莫斯寻找勇敢的旅人去让他们解脱，并取回那些锁住他们灵魂的遗物。",al={"被诅咒的船员任务背景","为什么要杀他的船员"}},{q="帕雷斯之眼是什么？",a="它是一件随第三舰队出航的古老而强大的神器。它所蕴含的黑暗力量与困扰沉船水手的诅咒紧密相连，取回它对于让溺亡的船队获得安宁至关重要。",al={"帕雷斯之眼","帕雷斯遗物"}},{q="为什么菲兹莫斯身上那么臭？",a="舰队覆灭让他失去了一切，菲兹莫斯多年来在深水旅店外过着酗酒颓废的生活，穿着海水浸泡过的破烂衣服，几乎从不清洗。",al={"为什么菲兹莫斯有臭味","菲兹莫斯的恶臭"}}},fx={c1574e2a={q="大副菲兹莫斯效忠哪一方？",a="菲兹莫斯曾效忠库尔提拉斯和第三舰队，因此与联盟立场一致。不过如今，他不再效忠任何国家或领主。他只是个颓废的水手，终日在米奈希尔港的深水旅店外借酒消愁，依靠路过的联盟冒险者清理他过去留下的诅咒残迹。",al={"菲兹莫斯的阵营","菲兹莫斯效忠谁","菲兹莫斯属于联盟吗"}},["468babc7"]={q="大副菲兹莫斯为什么在米奈希尔港？",a="菲兹莫斯最终流落到米奈希尔港，因为他是库尔提拉斯第三舰队的唯一幸存者。第二次战争期间，这支舰队在湿地海岸遭到兽人龙骑兵摧毁。战友们惨死的景象令他挥之不去，于是他躲到深水旅店外的台阶上，借酒浇愁。",al={"菲兹莫斯为什么在这里","菲兹莫斯为什么在米奈希尔港","菲兹莫斯为什么在旅店外"}},["786aa53e"]={q="大副菲兹莫斯与谁有关联？",a="菲兹莫斯曾是库尔提拉斯舰船“Wave Mistress”号的大副，该船隶属于第三舰队。他仍与昔日的船长和船员们有着密切联系，如今他们作为受诅咒的亡灵徘徊在海岸附近的沉船中，被帕雷斯之眼之类的黑暗遗物束缚。",al={"菲兹莫斯的关系","菲兹莫斯的船","菲兹莫斯的船员"}}},fp="22,397,15.367.0,27.366.0,19.390.1,30.232.0,26.212.0,32.182.0,51.206.0,26.197.0,34.173.0"}
P.entries["npc:fizzle-brassbolts"] = {n="菲兹尔·铜栓",s="菲兹尔·铜栓是一位杰出的侏儒工程师，常驻于千针石林的闪光平原沙漠赛道。他和他的竞争对手——地精普兹克一起，共同创立了这座赛道，旨在通过高速火箭车比赛，将侏儒的精密工程学与地精的鲁莽发明进行较量。他一直在寻找零件、燃料和各种奇怪的沙漠试剂，以维持他的赛车团队正常运转。",h="菲兹尔·铜栓是一位杰出的侏儒工程师，常驻于千针石林的闪光平原沙漠赛道。他和他的竞争对手——地精普兹克一起，共同创立了这座赛道，旨在通过高速火箭车比赛，将侏儒的精密工程学与地精的鲁莽发明进行较量。他一直在寻找零件、燃料和各...",kw={"铜栓","菲兹尔","沙漠赛道","普兹克","火箭车","闪光平原","千针石林"},ang={["faction:Alliance"]="尽管在这一中立的速度区运营，但对于前往南方塔纳利斯的联盟漫游者来说，菲兹尔依然是一位友好的接待者，并能提供机械维修服务。",["profession:Engineering"]="同行工程师们会钦佩菲兹尔在恶劣的沙漠条件下，致力于优化火箭推进技术并绘制尖端汽车设计图的执着精神。",["race:Gnome"]="菲兹尔带着整个诺莫瑞根的荣誉来到了沙漠，决心证明侏儒的精密技术优于地精的鲁莽冲动。"},sec={{t="原则与活塞的问题",b="在闪光平原那热浪翻滚的荒原上，政治联盟和古老的恩怨都屈服于引擎的轰鸣声之下。菲兹尔·铜栓来到这里只有一个目标：彻底证明侏儒的精湛技艺远胜于粗糙的地精把戏。他和他的地精同行普兹克一起，协助规划了沙漠赛道，将赛车、维修队和观众带到了这片原本荒凉的盆地。"},{t="平原上的修补匠",b="在干涸的盐碱地上飞速行驶需要不断的临场发挥，而菲兹尔从不回避非传统的实验。无论是测试从当地生物毒液中提取的挥发性混合物，还是雇佣旅行者去获取机械更换零件，菲兹尔都决心让他的赛车比任何易爆的地精装置跑得更快。"}},faq={{q="菲兹尔·铜栓是谁？",a="菲兹尔·铜栓是一位侏儒工程学大师，也是常驻千针石林沙漠赛道的侏儒赛车队的首席组织者。",al={"谁是菲兹尔","菲兹尔·铜栓背景故事","赛道上的侏儒"}},{q="菲兹尔为什么来到闪光平原？",a="他是为了与地精工程师普兹克解决一场技术争论而来，争论的焦点是谁的种族拥有更卓越的工程学技术。他们共同建立了沙漠赛道，以便在平坦的盐碱盆地上对他们的火箭车进行正面测试。",al={"菲兹尔为何在此","赛道目的","建造赛道的原因"}},{q="铜栓兄弟是谁？",a="菲兹尔和他的兄弟维兹尔·铜栓共同运营着沙漠赛道的侏儒赛车队。他们的新型火箭车速度太快，导致驾驶员频频坠车，所以他们向铁炉堡的朋友飞行员比罗·长须求助，索要攻城坦克用的防撞头盔。",al={"铜栓兄弟","维兹尔·铜栓","菲兹尔的兄弟"}},{q="菲兹尔为什么要用生物毒液制造赛车？",a="菲兹尔不断地试验当地的试剂，以配制强效的发动机流体、添加剂和加速剂，从而使他的火箭车在与普兹克的机器比赛时占据优势。",al={"闪光平原毒液任务","毒液赛车燃料","他为何需要毒液"}},{q="菲兹尔会与地精作战吗？",a="不会用武器。虽然他们之间存在着深刻的专业嫉妒，但菲兹尔和普兹克在赛道上保持着一种不安的、中立的休战状态，以便专注于纯粹的高速竞技。",al={"菲兹尔是否敌视地精","菲兹尔与普兹克的竞争"}},{q="飞行员比罗·长须是谁？",a="飞行员比罗·长须是铁炉堡攻城部队的一名矮人攻城机驾驶员，也是铜栓兄弟的朋友，和他们一样，他也对危险的机械情有独钟。",al={"与飞行员比罗·长须的关系","菲兹尔的飞行员朋友"}}},fx={["092966e5"]={q="菲兹尔·铜栓效忠哪一方？",a="菲兹尔·铜栓代表侏儒及其在沙漠赛道的车队。他对联盟和部落的旅人都保持中立，在闪光平原与普兹克等地精工程师维持着务实的合作关系。虽然他竭力证明侏儒工程学优于地精工程学，但双方的竞争局限于沙漠赛道，而非公开交战。",al={"菲兹尔属于联盟吗","菲兹尔·铜栓的阵营","菲兹尔为谁效力"}},["4ec804ad"]={q="菲兹尔·铜栓想要什么？",a="菲兹尔一心想证明侏儒工程学绝对胜过地精技术。为此，他与地精对手普兹克共同创立了沙漠赛道。他专注于研发速度更快的火箭赛车，寻找闪光平原蝎子咸腥的毒液等珍稀燃料原料，并在盐碱地赛道上击败地精车队。",al={"菲兹尔想要什么","菲兹尔·铜栓的目标","菲兹尔为什么参加赛车"}}},fp="17,397,33.444.0,22.375.0,25.146.0,44.222.0,32.242.0,50.179.0,38.181.0,23.169.0"}
P.entries["npc:fleet-master-seahorn"] = {n="舰队指挥官卡拉·海角",s="舰队指挥官卡拉·海角是一位经验丰富的牛头人水手，担任藏宝海湾黑水强盗的舰队指挥官。他与大财主里维加兹一同驻扎在海角旅店的上层阳台上，负责监督这座地精港口的海洋防御工作。他的首要职责是保护港口，免受其宿敌血帆海盗带来的迫在眉睫的威胁。",h="舰队指挥官卡拉·海角是一位经验丰富的牛头人水手，担任藏宝海湾黑水强盗的舰队指挥官。他与大财主里维加兹一同驻扎在海角旅店的上层阳台上，负责监督这座地精港口的海洋防御工作。他的首要职责是保护港口，免受其宿敌血帆海盗带来的迫在...",kw={"黑水强盗","血帆","藏宝海湾","法迪尔海湾","法拉隆","舰队指挥官卡拉·海角","里维加兹","salty sailor tavern","海角","蛮荒海岸"},ang={["class:Rogue"]="在藏宝海湾活动的潜行者会发现卡拉·海角处于海岸间谍活动的核心，组织针对血帆战舰的秘密突袭并拦截敌人的命令。",["faction:Horde"]="虽然卡拉·海角是牛头人，但他的效忠对象严格属于热砂港和黑水强盗，对部落和联盟的旅行者均保持中立立场。",["race:Tauren"]="卡拉·海角是极少数抛弃了卡利姆多内陆平原并征服了公海的牛头人之一，担任着中立地精港口的舰队指挥官。"},sec={{t="公海上的公牛",b="虽然牛头人以卡利姆多的平原居民而闻名，但舰队指挥官卡拉·海角却选择了截然不同的海洋生活。他身穿海盗装束，指挥着黑水强盗的舰队，这是热砂港在荆棘谷行动中的私有海军武装。卡拉·海角驻扎在海角旅店顶层，与大财主里维加兹并肩工作，为藏宝海湾这个无法无天却管理严格的港口协调航运路线、船员部署和海岸防御。"},{t="守卫海湾",b="卡拉·海角最关心的持续问题是血帆海盗，他们在南部的蛮荒海岸建立了坚固的营地，并将战舰停泊在海岸附近。当报告显示舰队指挥官法拉隆和血帆海盗的领导层打算发动直接突袭以洗劫藏宝海湾时，卡拉·海角采取了果断行动。通过派遣雇佣兵夺取敌人的通信文件，并在旗舰上消灭法拉隆、基尔哈尔和斯蒂尔沃特，卡拉·海角成功地使该港口免遭彻底破坏。"},{t="远眺海洋",b="除了击退海盗袭击外，卡拉·海角还管理着东部王国各地的多种商业和打捞项目。他与打捞潜水员合作，协调法迪尔海湾附近阿拉希海岸的失落沉船财宝打捞工作，以确保获取精灵文物。他还让里维加兹随时了解城中经过的获利机会，例如竞技钓鱼和当地贸易，以确保黑水舰队获得充足的资金，并领先于竞争对手。"}},faq={{q="舰队指挥官卡拉·海角在哪里？",a="他位于藏宝海湾海角旅店的顶层和阳台上，就站在大财主里维加兹身边，俯瞰着码头。",al={"海角在哪里","海角位置","找到海角"}},{q="为什么牛头人会担任海盗舰队指挥官？",a="尽管大多数牛头人仍然与莫高雷的平原和精神传统紧密相连，但卡拉·海角却投身于航海和雇佣兵海军生活。他的航海技术和指挥风范使他获得了大财主里维加兹麾下黑水强盗的领导权。",al={"牛头人海盗","为什么海角是海盗","藏宝海湾的牛头人"}},{q="卡拉·海角和大财主里维加兹是什么关系？",a="卡拉·海角是大财主里维加兹的副手，也是他麾下黑水强盗的舰队指挥官。当里维加兹负责管理政治、贸易和财务时，卡拉·海角负责监管藏宝海湾的舰队、战术情报和防御性军事行动。",al={"海角和里维加兹","海角是里维加兹的保镖吗","谁为里维加兹工作"}},{q="黑水强盗是谁？",a="黑水强盗是一支效忠于热砂港的私掠舰队，以藏宝海湾为基地。与不分青红皂白进行掠夺的亡命之徒不同，他们作为受认可的海军，保护地精的商业利益并维护南部海域的秩序。",al={"黑水强盗","海角的阵营是什么","藏宝海湾海盗"}},{q="为什么卡拉·海角要阻止血帆海盗？",a="血帆海盗是黑水强盗的死敌。在舰队指挥官法拉隆的带领下，血帆海盗已沿着蛮荒海岸建立了营地，并意图征服藏宝海湾本身。卡拉·海角不断努力以预先阻止他们的入侵计划。",al={"海角对抗血帆","血帆冲突","为什么要对抗血帆"}},{q="卡拉·海角在荆棘谷之外还有生意吗？",a="是的。卡拉·海角与德拉克里格博士和沙克斯·奥布里等打捞代理人合作，回收在阿拉希高地外法迪尔海湾附近沉没的失落货物和精灵财宝，并将有价值的文物运回他在藏宝海湾的岗位。",al={"法迪尔海湾海角","海角沉船宝藏","阿拉希任务海角"}}},fp="20,378,23.506.0,17.524.1,20.470.0,38.143.0,49.254.0,51.250.0,31.277.0,55.254.0,57.242.0"}
P.entries["npc:foggy-mackreel"] = {n="醉鬼马克里尔",s="醉鬼马克里尔是一名勇敢的矮人，他正摇摇欲坠地被困在萨多尔大桥下方破损的砖石结构上。尽管脚下的石块已经碎裂，身下就是令人眩晕的深渊，但他唯一真正关心的事情是完成他那批运往北方南海镇的私酿酒的订单。",h="醉鬼马克里尔是一名勇敢的矮人，他正摇摇欲坠地被困在萨多尔大桥下方破损的砖石结构上。尽管脚下的石块已经碎裂，身下就是令人眩晕的深渊，但他唯一真正关心的事情是完成他那批运往北方南海镇的私酿酒的订单。",kw={"阿拉希","醉鬼","马克里尔","私酿酒","南海镇","萨多尔大桥","湿地"},ang={["faction:Alliance"]="在铁炉堡和北方前哨站南海镇之间往来的联盟信使经常会遇到马克里尔，他们会接下他那批被困的货物，以此帮助这位联盟同胞。",["race:Dwarf"]="马克里尔体现了矮人那种固执的坚韧——以及奇特的行事优先权——比起被困在致命深渊之上这种小事，他更看重那烈性酒能否按时送达。"},sec={{t="困在大桥上",b="醉鬼马克里尔栖身在破碎的萨多尔大桥下方断裂的桥墩上，他对这种危险的处境完全不以为意。虽然黑铁矮人的破坏和战争留下的创伤使得这座连接湿地和阿拉希高地的宏伟桥梁断裂开来，但马克里尔却把这种岌岌可危的立足点仅仅视为一个小麻烦。他首要考虑的不是如何获救，而是那批尚未送达的烈性私酿酒，那可是给希尔斯布莱德丘陵南海镇的酒客们准备的。他非常乐意雇佣那些动作敏捷、能下到他所在位置的路过的冒险者，替他完成这趟快递任务。"}},faq={{q="谁是醉鬼马克里尔？",a="醉鬼马克里尔是一位古怪的矮人信使，他被困在萨多尔大桥断桥下方损毁的石柱上。尽管深渊就在脚下，他依然保持着绝对的冷静，一心只想把他的私酿酒送出去。",al={"醉鬼马克里尔","醉鬼马克里尔是谁","马克里尔npc"}},{q="我能在哪里找到醉鬼马克里尔？",a="他位于萨多尔大桥断裂的中央桥段下方的一个石台上，可以从阿拉希高地一侧的大桥结构上小心跳下去找到他。",al={"醉鬼马克里尔在哪里","醉鬼马克里尔位置","如何找到马克里尔"}},{q="为什么醉鬼马克里尔会在那下面？",a="马克里尔在旅途中被困在了萨多尔大桥的残骸中。然而，他并没有寻求救援，而是更关心找人替他把私酿酒货物运到南海镇。",al={"为什么醉鬼被困住了","马克里尔是怎么到那里的","他为什么在桥上"}},{q="醉鬼马克里尔提供什么任务？",a="他提供“马克里尔的私酿酒”任务，请求旅人们将一罐烈酒带给穿过阿拉希高地，前往南海镇酒馆的客人们。",al={"醉鬼任务","马克里尔的私酿酒任务","醉鬼给什么任务"}}},fx={["28a25d1f"]={q="醉鬼马克里尔效忠哪一方？",a="醉鬼马克里尔是亲近联盟的矮人。尽管他被困在萨多尔大桥受损的遗迹上，他仍始终效忠于自己的族人和联盟的定居点，尤其希望把自酿的烈酒送往北方，交到希尔斯布莱德丘陵南海镇居民手中。",al={"醉鬼马克里尔的阵营","醉鬼马克里尔属于联盟吗","醉鬼马克里尔站在哪一方"}},c1253653={q="醉鬼马克里尔想要什么？",al={"醉鬼马克里尔的动机","醉鬼想要什么","醉鬼马克里尔的目标"}}},fp="14,264,20.583.0,22.226.0,32.183.0,33.217.0,37.143.0"}
P.entries["npc:foreman-oslow"] = {n="工头奥斯洛",s="工头奥斯洛是湖畔镇焦头烂额的首席建筑师，负责修复位于赤脊山中心地带受损的止水湖大桥。由于黑石兽人的火炮和豺狼人掠夺者的侵扰，加上货物遗失和设备沉没，他的重建工作陷入了停滞。他非常依赖路过的冒险者来寻回装备并获取物资，以便让湖畔镇重新连接起这条重要的贸易路线。",h="工头奥斯洛是湖畔镇焦头烂额的首席建筑师，负责修复位于赤脊山中心地带受损的止水湖大桥。由于黑石兽人的火炮和豺狼人掠夺者的侵扰，加上货物遗失和设备沉没，他的重建工作陷入了停滞。他非常依赖路过的冒险者来寻回装备并获取物资，以便...",kw={"黑石","止水湖大桥","工头奥斯洛","闪金镇","湖畔镇","奥斯洛","赤脊山","工具箱"},ang={["faction:Alliance"]="湖畔镇中断的大桥使东部前线暴露无遗，这使得奥斯洛的修复工作成为巩固联盟边境的战略必要举措。",["profession:Mining"]="奥斯洛依靠原材料、金属制品和采石场运来的物资来重建损毁的石砌建筑，这使他与当地的矿产运输紧密相连。"},sec={{t="一座被切断的城镇",b="站在止水湖大桥残破的石砖旁，工头奥斯洛面临着一场艰苦的战斗。这座大桥是湖畔镇的生命线，横跨止水湖，将通往艾尔文森林的西部道路与东岸连接起来。黑石兽人从石堡的峭壁上俯冲而下，瞄准了这座桥梁，以此削弱该镇的后勤和军事行动，使这里变得支离破碎且岌岌可危。"},{t="沉没的钢铁与被盗的石材",b="奥斯洛每一次重建的尝试似乎都饱受不幸的困扰。当大桥倒塌时，他的替换工具是从闪金镇通过陆路运来，并装载到了一艘湖上渡轮上。兽人投石机部队盯上了这艘船，将他沉重的铁制工具箱直接送入了止水湖的淤泥之中。更糟糕的是，当地的赤脊山豺狼人劫持了从暴风城运来的新物资车队，抢走了架设拱桥所需的铁桩和铆钉。"}},faq={{q="谁是工头奥斯洛？",a="工头奥斯洛是一位驻扎在湖畔镇的人类石匠和建筑师。他是负责维护和重建止水湖大桥的总工匠。",al={"工头奥斯洛","谁是奥斯洛","湖畔镇建筑师"}},{q="为什么止水湖大桥会断裂？",a="止水湖大桥是被赤脊山的黑石兽人摧毁的。摧毁这座桥梁切断了湖畔镇的主要干道，严重削弱了该镇的防御，并阻断了东岸和西岸之间的便捷交通。",al={"为什么桥断了","谁破坏了湖畔镇大桥","止水湖大桥被毁"}},{q="奥斯洛丢失的工具在哪里？",a="奥斯洛沉重的工具箱沉在了止水湖底。运送这些工具的船只从闪金镇出发，结果被黑石兽人的投石机齐射击中并沉没。",al={"工具在哪里","丢失的工具位置","奥斯洛的工具箱"}},{q="为什么大桥还没修好？",a="由于兽人的投石机火炮将他的工具沉入湖中，而豺狼人又从运来的补给中窃取建筑材料，奥斯洛在没有外界帮助的情况下缺乏恢复施工所需的物资和设备。",al={"为什么桥还没修好","湖畔镇大桥延期"}},{q="奥斯洛的补给最初是从哪里来的？",a="他的替换工具最初是用马车从艾尔文森林的闪金镇运来的，之后被转移到一艘湖上渡轮上，试图绕过断裂的桥梁。",al={"补给马车来源","工具从哪来"}},{q="奥斯洛正在应对哪些威胁？",a="奥斯洛面临着来自两方面的持续骚扰：驻扎在附近高地上的黑石氏族兽人，他们的攻城武器不断轰击湖面；以及潜伏在四周、不断袭击补给车队的豺狼人。",al={"奥斯洛的敌人","谁攻击了大桥"}}},fx={cf681f3e={q="工头奥斯洛效忠哪一方？",a="工头奥斯洛为暴风城王国和湖畔镇当地居民效力。作为镇上的首席建造者和工头，他负责维护赤脊山的重要基础设施，帮助当地居民在周边黑石兽人和敌对豺狼人不断袭击下生存下去。",al={"奥斯洛的阵营","工头奥斯洛为谁效力","工头奥斯洛属于联盟吗"}},["1a3f577b"]={q="工头奥斯洛想要什么？",a="奥斯洛的首要目标是重建被毁的止水桥，让湖畔镇继续与王国其他地区保持联系。为此，他急需打捞止水湖中的沉没工具箱，并找回遭当地豺狼人伏击和偷走的建筑材料。",al={"奥斯洛想要什么","工头奥斯洛的目标","奥斯洛为什么需要帮助"}},["765147a2"]={q="工头奥斯洛为什么在湖畔镇？",a="奥斯洛驻守在湖边，负责监督公共工程并主持止水桥的重建。桥梁是湖畔镇的命脉，但敌人不断袭击，补给又遭受重创，使他只能困守在湖边等待援助，才能继续工作。",al={"奥斯洛为什么在这里","奥斯洛在湖畔镇的职责","工头奥斯洛的工作"}}},fp="13,413,17.430.0,29.481.0,21.172.0,35.246.0,29.155.0,40.213.0,48.158.0,35.193.0"}
P.entries["npc:foreman-stonebrow"] = {n="工头乔尼·石眉",s="工头乔尼·石眉是一位矮人监督员，代表矿工联盟在丹莫罗东部的古博拉采掘场工作。在好战的穴居人从岩石中冲出并占领了挖掘现场后，他被迫组织防御并雇佣冒险者来清理矿坑。",h="工头乔尼·石眉是一位矮人监督员，代表矿工联盟在丹莫罗东部的古博拉采掘场工作。在好战的穴居人从岩石中冲出并占领了挖掘现场后，他被迫组织防御并雇佣冒险者来清理矿坑。",kw={"丹莫罗","工头乔尼·石眉","古博拉","古博拉采掘场","矿工联盟","石眉","穴居人"},ang={["profession:Mining"]="矿工们有职业上的动机去帮助石眉，因为重新夺回采掘场丰富的石料和矿石矿床对于卡兹莫丹的行会运作至关重要。",["race:Dwarf"]="对于矮人来说，穴居人对古博拉采掘场的入侵是对铁炉堡石材工业的直接打击，也是对潜伏在他们祖先土地下古老威胁的严峻提醒。"},sec={{t="古博拉的危机",b="工头乔尼·石眉负责指挥古博拉采掘场的行动，这是一个坐落在卡拉诺斯以东山区的关键矮人挖掘场。当深度挖掘破开了隐藏的穴居人巢穴时，地下野兽蜂拥而出，占据了矿坑并将矿工赶离了他们的设备。石眉拒绝完全放弃该地点，他留在了采掘场边缘，试图招募任何有能力的旅行者将穴居人赶走。"}},faq={{q="谁是工头乔尼·石眉？",a="工头乔尼·石眉是一位隶属于矿工联盟的矮人，负责监督丹莫罗古博拉采掘场的工作。他协调各项作业并试图保障采掘场的安全。",al={"石眉","谁是石眉","工头石眉背景故事"}},{q="为什么工头乔尼·石眉要寻求帮助？",a="古博拉采掘场的挖掘工作无意中闯入了地下的穴居人洞穴。穴居人涌入下层平台，杀死了工人并迫使幸存的矿工撤退到边缘的营地。",al={"古博拉穴居人问题","为什么需要帮助","采掘场任务"}},{q="什么是矿工联盟？",a="矿工联盟是一个总部位于铁炉堡的矮人工会和贸易组织，负责监管整个卡兹莫丹的采矿探险、资源开采和采石场运营。",al={"矿工联盟","什么是矿工联盟"}},{q="在哪里可以找到工头乔尼·石眉？",a="他驻扎在俯瞰古博拉采掘场的边缘营地，位于丹莫罗东部的丘陵地带，就在通往洛克莫丹的道路旁。",al={"石眉位置","工头石眉在哪里"}}},fx={c868fd05={q="工头乔尼·石眉为什么会在古博拉采掘场？",a="工头乔尼·石眉受矿工联盟之托，被派往古博拉采掘场监督挖掘和资源开采。如今他仍驻守在采掘场附近，召集援手并协调行动，试图在突如其来的穴居人侵袭击溃工人队伍后夺回此地。",al={"石眉为什么在这里","石眉与古博拉采掘场","石眉在这里做什么"}},["2635f3c5"]={q="工头乔尼·石眉效忠哪一方？",a="工头乔尼·石眉效忠于矿业工会和矮人王国铁炉堡，因此坚定地站在联盟一方。他负责丹莫罗的公共挖掘工程，并寻求联盟冒险者帮助清除铁炉堡采矿作业中的威胁。",al={"石眉的阵营","石眉效忠谁","石眉属于联盟吗"}}},fp="17,269,23.426.0,25.183.0,41.201.0,27.182.0,37.151.0"}
P.entries["npc:foreman-thazz-ril"] = {n="工头塔兹利尔",s="工头塔兹利尔是一位驻扎在杜隆塔尔试炼谷的兽人劳工监工。他的职责是确保苦工们按计划工作，并为年轻的战士们维护基础建设，但他总是因为懒惰的劳工和附近邪教徒的活动而感到恼火。",h="工头塔兹利尔是一位驻扎在杜隆塔尔试炼谷的兽人劳工监工。他的职责是确保苦工们按计划工作，并为年轻的战士们维护基础建设，但他总是因为懒惰的劳工和附近邪教徒的活动而感到恼火。",kw={"木棒","火刃氏族","杜隆塔尔","工头","懒惰的苦工","塔兹利尔","试炼谷"},ang={["profession:Mining"]="塔兹利尔很看重优质的采矿设备，这从他急切地想要从火刃集会所的黑暗深处寻回那把附魔矿镐就能看出来。",["race:Orc"]="对于即将成年的年轻兽人来说，塔兹利尔提供了一个关于部落社会的早期课题：战场上的力量只有在枯燥、纪律严明的劳动支持下才有可能实现。"},sec={{t="管教苦工",b="在杜隆塔尔严酷的红岩地貌上建立新家园需要无尽的体力劳动。在试炼谷，工头塔兹利尔负责监管那些砍伐木材和收集材料的苦工，这些物资既支持了营地，也支撑着部落更宏大的战争努力。对塔兹利尔来说不幸的是，苦工们出了名地喜欢偷懒，总爱在沙漠的烈日下打盹。为了让建设工作继续进行，他经常征召新来的应征者，用他那值得信赖的木棒给那些沉睡的工人来上一下，用这种直截了当的方式灌输服从意识。"},{t="落入险境的遗失矿镐",b="塔兹利尔的职责还包括勘测山谷的矿产资源，尽管这项工作导致了一次令人尴尬的失误。在侦察被称为火刃集会所的洞穴时，他被迫从潜伏在里面的黑暗邪教徒面前逃离，不慎遗落了他珍爱的附魔矿镐。因为顾忌聚集的术士和他们的恶魔爪牙，他不敢亲自去取回矿镐，于是只能依靠年轻的部落志向者深入洞穴，帮他找回工具。"}},faq={{q="工头塔兹利尔是谁？",a="工头塔兹利尔是杜隆塔尔试炼谷的一位兽人劳工监工。他负责管理劳工小队、砍伐木材，并为该地区进行资源勘测，以协助部落的定居工作。",al={"塔兹利尔是谁","塔兹利尔试炼谷","工头塔兹利尔背景"}},{q="为什么塔兹利尔要给玩家木棒？",a="在他监管下的苦工们经常躲在树下睡觉，而不是去砍伐木材。塔兹利尔提供了一根附魔的木棒，用来教训他们，让他们赶紧回去干活。",al={"为什么要打懒惰的苦工","塔兹利尔木棒","懒惰的苦工任务背景"}},{q="为什么塔兹利尔的矿镐会在火刃洞穴里？",a="在为矿脉勘测当地洞穴时，塔兹利尔误闯进了火刃集会所。被藏在阴影中的邪教徒吓坏后，他匆忙撤离，并遗落了他那把珍贵的附魔矿镐。",al={"塔兹利尔的矿镐","为什么矿镐在集会所","火刃矿镐"}},{q="他在部落中担任什么角色？",a="塔兹利尔并非前线战士或萨满，而是一位平民监工。他的职责侧重于杜隆塔尔的后勤基础：监管体力劳动、维护建筑物资供应，并保持苦工的生产力。",al={"塔兹利尔是战士吗","塔兹利尔军衔"}}},fx={["607050fc"]={q="工头塔兹利尔效忠于哪一方？",a="塔兹利尔效忠于萨尔的部落。他驻守在试炼谷，负责监督基础劳作和资源采集，帮助建设杜隆塔尔，并维持训练场的运作，以接纳新来的兽人和巨魔新兵。",al={"工头塔兹利尔效忠哪一方","塔兹利尔与部落","塔兹利尔的阵营"}},f77b2dd2={q="工头塔兹利尔想要什么？",a="塔兹利尔最希望工人们能好好干活。谷地里懒散的苦工总在偷懒，令他不胜其烦，于是他招募年轻的冒险者去叫醒他们。他还想找回自己珍爱的附魔矿镐，可惜他把它遗落在火刃氏族的营地附近。",al={"塔兹利尔的目标","塔兹利尔需要什么","塔兹利尔的任务动机"}},ee1167cb={q="工头塔兹利尔为什么在这里？",a="他被派到试炼谷指挥苦工劳动，并管理当地的采矿和伐木工作。维持定居点的运转、确保原材料供应，对年轻战士踏入杜隆塔尔广阔的土地前做好准备至关重要。",al={"塔兹利尔为什么在试炼谷","塔兹利尔在此地的原因"}}},fp="17,260,25.562.0,30.481.0,25.215.0,44.213.0,54.214.0,30.220.0"}
P.entries["npc:foreman-thistlenettle"] = {n="工头希斯耐特",s="工头希斯耐特曾是一位代表矿工联盟和探险者协会在西部荒野深处工作的矮人监工。在一场灾难性的塌方将他的小队困在死亡矿井的地下隧道后，他与工人们一同丧生，并作为一具亡灵食尸鬼复生。他现在徘徊在黑暗、坍塌的走廊中，除了他随身携带的工会徽章外，已无人能认出他。",h="工头希斯耐特曾是一位代表矿工联盟和探险者协会在西部荒野深处工作的矮人监工。在一场灾难性的塌方将他的小队困在死亡矿井的地下隧道后，他与工人们一同丧生，并作为一具亡灵食尸鬼复生。他现在徘徊在黑暗、坍塌的走廊中，除了他随身携带...",kw={"徽章","塌方","死亡矿井","工头","食尸鬼","矿工联盟","希斯耐特","维尔德"},ang={["profession:Mining"]="希斯耐特的命运提醒着所有矿工，隧道塌方和险恶的地下深处始终潜藏着危险。",["race:Dwarf"]="一位探险者协会工头和整支矮人小队的悲惨损失，凸显了人类王国下方潜藏的挥之不去的危险。"},sec={{t="兄弟的悲痛",b="回到暴风城，他的兄弟维尔德·蓟草度过了不安的数月，一直挂念着失踪的采矿小队的命运。由于被占领的隧道里没有任何消息传出，最终有传言称那位陨落的监工依然在死者中徘徊。冒险者们被要求深入死亡矿井外围，找到这位亡灵工头，终结他的痛苦，并收回他的徽章，以给悲痛的亲人一个了结。"},{t="死亡矿井的悲剧",b="在迪菲亚潜行者完全控制死亡矿井之前，合法的采矿探险队曾深入其丰富的矿脉。工头希斯耐特代表矿工联盟和探险者协会负责其中一项此类风险投资。在月溪镇下方的隧道深处，一场猛烈的塌方将他的小队与地面隔绝，灾难降临了。被困的矿工在黑暗中死去，但他们并未长眠；一股邪恶的死灵污秽将希斯耐特和他的小队复活为贪婪的食尸鬼，在阴暗的通道中游荡。"}},faq={{q="工头希斯耐特死前是谁？",a="他是一位与矿工联盟和探险者协会都有关联的矮人工头。在死亡矿井被法外之徒完全加固之前，他曾带领一队矿工进入其中，旨在挖掘和勘测地下的矿脉。",al={"希斯耐特背景故事","工头希斯耐特是谁","希斯耐特背景"}},{q="为什么工头希斯耐特会变成亡灵食尸鬼？",a="一场灾难性的塌方导致隧道崩塌，埋葬了希斯耐特和他的采矿小队，夺去了他们的生命。随后，矿井迷宫中阴暗的地下能量或残留的死灵法术使他们的遗骸复生，将这些矮人变成了永不安息的食尸鬼。",al={"他为何是食尸鬼","希斯耐特如何死亡","希斯耐特亡灵"}},{q="工头希斯耐特位于何处？",a="他徘徊在死亡矿井外部迷宫内一条死胡同的坍塌隧道中，位于通往副本内部的传送门之前，周围环绕着他那些复活的前矿工同伴。",al={"去哪里找到希斯耐特","希斯耐特位置","死亡矿井工头地点"}},{q="谁在寻找工头希斯耐特？",a="他的兄弟维尔德·蓟草，居住在暴风城的Dwarven District。维尔德寻求他兄弟命运的证据，并请求旅行者带回希斯耐特的徽章。",al={"谁想要希斯耐特死","兄弟维尔德","希斯耐特任务发布者"}}},fp="21,298,17.333.1,24.443.1,45.212.0,45.173.0,39.171.0,41.185.0"}
P.entries["npc:frahun-shadewhisper"] = {n="弗拉胡恩·影语者",s="弗拉胡恩·影语者是一位暗夜精灵潜行者训练师，驻扎在幽影谷的奥达希尔。他为刚入门的暗夜精灵斥候和潜行者提供潜行、敏捷和隐秘打击的基础技巧。他与达纳苏斯的另一位同职业训练师埃里恩·影语者拥有相同的姓氏。",h="弗拉胡恩·影语者是一位暗夜精灵潜行者训练师，驻扎在幽影谷的奥达希尔。他为刚入门的暗夜精灵斥候和潜行者提供潜行、敏捷和隐秘打击的基础技巧。他与达纳苏斯的另一位同职业训练师埃里恩·影语者拥有相同的姓氏。",kw={"奥达希尔","密文符记","埃里恩","弗拉胡恩","潜行者训练师","影语者","幽影谷","泰达希尔"},ang={["class:Rogue"]="弗拉胡恩·影语者是暗夜精灵潜行者的第一位职业导师，提供他们对潜行、伏击战术和武器技巧的初步介绍。",["race:NightElf"]="弗拉胡恩展示了暗夜精灵如何将他们与生俱来的夜间亲和力和闪避能力转化为致命且实用的战斗技能，以保护泰达希尔。"},sec={{t="阴影中的导师",b="在泰达希尔中心地带奥达希尔这处安全港湾内，弗拉胡恩·影语者指导新晋潜行者学习隐蔽和刃舞的静谧艺术。虽然暗夜精灵社会通常尊崇牧师、哨兵和德鲁伊，但斥候和渗透者这一特殊职业对于保卫世界之树的枝叶依然至关重要。弗拉胡恩欢迎带着密文符记前来的新兵，评估他们的潜力并引导他们初期的成长。"}},faq={{q="弗拉胡恩·影语者是谁？",a="弗拉胡恩·影语者是一位驻扎在泰达希尔奥达希尔的暗夜精灵潜行者训练师。他教导潜行者新手关于潜行、精确战斗和隐秘战术的基础知识。",al={"弗拉胡恩背景故事","弗拉胡恩是谁","弗拉胡恩·影语者的职责"}},{q="在哪里可以找到弗拉胡恩·影语者？",a="他位于泰达希尔幽影谷新手区中央的要塞，奥达希尔。",al={"弗拉胡恩位置","弗拉胡恩在哪","寻找弗拉胡恩·影语者"}},{q="弗拉胡恩和埃里恩·影语者有亲属关系吗？",a="鉴于他们共用同一个姓氏，且都致力于在泰达希尔训练潜行者，外界普遍认为弗拉胡恩是埃里恩·影语者的亲属，后者在达纳苏斯训练潜行者。",al={"埃里恩·影语者兄弟","弗拉胡恩埃里恩关系","影语者家族"}},{q="密文符记对他有什么作用？",a="暗夜精灵潜行者新手通过将密文符记直接带给弗拉胡恩开启他们的旅程，这标志着他们是准备好接受潜行者职业正规训练的候选人。",al={"密文符记上交","弗拉胡恩符记","潜行者起始任务"}}},fx={a27f02ba={q="弗拉胡恩·影语者效忠于哪一方？",a="弗拉胡恩坚定地支持达纳苏斯和联盟。他驻守在幽影谷奥达希尔的古老枝干间，为卡多雷同胞效力，确保擅长潜行与诡术的人能够磨炼技艺，守护暗夜精灵的土地。",al={"弗拉胡恩的阵营","弗拉胡恩效忠哪一方","弗拉胡恩是否属于联盟"}},["025c0171"]={q="弗拉胡恩·影语者想要什么？",a="弗拉胡恩希望教导有志成为暗夜精灵潜行者的人掌握暗影、开锁和潜行战斗的技艺。他确保新的斥候和行动人员在离开幽影谷的保护边界、前往泰达希尔更广阔的区域之前，彻底掌握自己的职业之道。",al={"弗拉胡恩的动机","弗拉胡恩的目标","弗拉胡恩做什么"}},["72dec556"]={q="弗拉胡恩·影语者为什么会在奥达希尔？",a="弗拉胡恩驻守在奥达希尔，指导刚刚觉醒或初出茅庐、踏上潜行者之路的暗夜精灵。在幽影谷这处安全之地，他为他们打下基础，确保初学者不会遭受林中潜伏的危险侵害。",al={"弗拉胡恩为什么在奥达希尔","弗拉胡恩为何在幽影谷","弗拉胡恩驻守此地的目的"}}},fp="19,308,23.468.0,27.178.0,39.100.0,40.173.0,49.172.0"}
P.entries["npc:furen-longbeard"] = {n="弗伦·长须",s="弗伦·长须是驻扎在暴风城繁忙的矮人区的一位矮人护甲大师。他师从著名铁匠格里曼德·艾尔莫，专注于为联盟的资深守卫打造重型防护装备和坚固的锁甲。王国各地的战士都会寻求他的冶金专长，以锻造特制的、适合战斗的护甲。",h="弗伦·长须是驻扎在暴风城繁忙的矮人区的一位矮人护甲大师。他师从著名铁匠格里曼德·艾尔莫，专注于为联盟的资深守卫打造重型防护装备和坚固的锁甲。王国各地的战士都会寻求他的冶金专长，以锻造特制的、适合战斗的护甲。",kw={"护甲商","铁匠","dwarven district","烈焰锁甲","弗伦·长须","格里曼德·艾尔莫","暴风城","战士"},ang={["class:Warrior"]="对于即将成年的联盟战士来说，弗伦·长须是一位关键的联系人，他能将纯粹的尚武决心和收集到的试剂转化为至关重要的烈焰锁甲。",["profession:Blacksmithing"]="弗伦代表了暴风城矮人铁匠的高标准，展示了格里曼德·艾尔莫传授的先进技术。",["race:Dwarf"]="即使远离铁炉堡，弗伦·长须依然在人类首都的中心让矮人冶金传统薪火相传。"},sec={{t="人类首都的矮人铁匠",b="弗伦·长须远离铁炉堡的宏大熔炉，在这片远离家乡的土地上施展着他的技艺，以暴风城矮人区的鹅卵石和煤烟为家。像许多同族一样，弗伦将传统的矮人冶金术带到了南方，以支持王国的重建与防御。他在炽热的炉火和叮当的铁砧声中工作，并与城内外的其他工匠保持着紧密的联系。"},{t="烈焰锁甲的锻造大师",b="在受人尊敬的工匠格里曼德·艾尔莫的教导下，弗伦已经完善了处理重型锁甲和板甲的技术，使其能够承受极端的战场考验。有前途的年轻战士若寻求耐用的防护，通常会求助于弗伦，而他需要来自世界遥远角落的稀有矿石、特种组件和奇异试剂来打造他标志性的烈焰锁甲。"}},faq={{q="弗伦·长须是谁？",a="弗伦·长须是一位在暴风城矮人区工作的矮人护甲商。对于想要获得大师级锁甲的联盟战士来说，他是至关重要的联系人和导师。",al={"弗伦是谁","弗伦·长须背景故事","暴风城矮人护甲商"}},{q="在哪里可以找到弗伦·长须？",a="他位于暴风城的矮人区，就在该区域随处可见的繁忙熔炉和铁匠铺附近。",al={"弗伦·长须在哪里","弗伦·长须位置","暴风城的弗伦"}},{q="是谁教导了弗伦的打铁手艺？",a="弗伦的护甲制作和冶金技术是由格里曼德·艾尔莫传授的，这是一位同样居住在矮人区的受人尊敬的资深工匠。",al={"弗伦的老师","弗伦的导师","谁训练了弗伦"}},{q="弗伦以制作什么护甲而闻名？",a="他以制作烈焰锁甲而闻名，这是一套通过严苛的冶金工艺制造出的韧性护甲，需要收集遍布整个大陆的稀有组件。",al={"烈焰锁甲","弗伦护甲任务","暴风城战士锁甲任务"}},{q="弗伦·长须和其他长须族人有亲戚关系吗？",a="他和东部王国其他几位显赫的矮人共享这个氏族名，比如铁炉堡的攻城器械驾驶员飞行员比罗·长须，尽管他只专注于打铁。",al={"弗伦的家族","长须氏族","飞行员比罗·长须的亲戚"}},{q="为什么战士们要寻找弗伦·长须？",a="那些已经证明了自身基本武技的战士会被指引去找弗伦，以获得能够抵御致命威胁、在第一线战斗中幸存下来的厚重耐用护甲。",al={"为什么战士要拜访弗伦","矮人区战士任务","弗伦战士训练师"}}},fp="15,230,36.295.0,29.357.0,23.177.0,35.121.0,36.135.0,40.166.0,47.181.0,41.169.0"}
P.entries["npc:furl-scornbrow"] = {n="弗恩·凝眉",s="弗恩·凝眉是一位年迈的兽人哨兵，驻扎在剃刀岭西北部的瞭望塔中。由于年事已高，他已无法在前方战线战斗，只能在杜隆塔尔的红色峡谷中守望，并为那些踏上旅途的年轻旅者制作结实的背包。",h="弗恩·凝眉是一位年迈的兽人哨兵，驻扎在剃刀岭西北部的瞭望塔中。由于年事已高，他已无法在前方战线战斗，只能在杜隆塔尔的红色峡谷中守望，并为那些踏上旅途的年轻旅者制作结实的背包。",kw={"承担重任","杜隆塔尔","弗恩·凝眉","瞭望者","兽人","剃刀岭","瞭望塔"},ang={["faction:Horde"]="弗恩驻扎在剃刀岭外的山脊上，代表着保护杜隆塔尔的新兴定居点免受残留威胁所需的警惕。",["race:Orc"]="弗恩体现了兽人的信仰：即使岁月剥夺了战士的武力，光荣的生活也意味着找到另一种为氏族和部落服务的方式。"},sec={{t="岭上守望者",b="弗恩·凝眉高高矗立在剃刀岭西北部的木制瞭望塔中，静静地注视着杜隆塔尔的中部平原。在奥格瑞玛建立之初的紧张时期，像弗恩这样的哨兵对于鸣响号角抵御敌对的野猪人、半人马和库尔提拉斯的入侵者至关重要。随着杜隆塔尔局势的稳定，剃刀岭的防线也愈发稳固，紧急情况变得愈发罕见，这也让弗恩在岗位上有了许多清静的时光。"},{t="有用的一双手",b="弗恩坦言，年迈的骨骼和逐渐衰退的力量让他无法再参加战斗，但兽人绝不会轻易放弃自己的使命。他没有闲坐着，而是动手为需要携带补给的新兵制作帆布袋和背包。通过换取粗线和实用材料，他为那些外出向部落证明自己价值的年轻冒险者提供装备。"}},faq={{q="弗恩·凝眉是谁？",a="弗恩·凝眉是一位年迈的兽人守望者，驻扎在剃刀岭西北部山崖顶上的瞭望塔中。由于年事已高，他无法作为前线战士服役，便一直在观察地平线上的危险，并为年轻的旅者制作背包。",al={"弗恩是谁","弗恩·凝眉背景故事","剃刀岭的弗恩"}},{q="弗恩在杜隆塔尔扮演什么角色？",a="他在号角塔值守，留意接近剃刀岭的入侵者。由于杜隆塔尔在部落的控制下日益安全，他鸣响警报的次数大为减少，便将空闲时间用于帮助新来的新兵整理装备。",al={"弗恩的工作","弗恩的使命"}},{q="为什么弗恩向旅行者索要材料？",a="弗恩认为，无论环境如何，部落的每一位成员都必须贡献自己的一份力量。既然他无法再战斗，他就缝制实用的旅行包来帮助年轻的战士，只需基本的材料（如粗线）即可完成工作。",al={"承担重任任务背景","弗恩为什么需要粗线"}}},fx={["1ce1cc0b"]={q="弗恩·凝眉效忠于哪一方？",a="弗恩坚定地支持部落。他驻守在剃刀岭上方的高处，俯瞰杜隆塔尔，保护年轻的兽人王国免受潜在入侵者威胁，并帮助效力于大酋长的旅人。",al={"弗恩·凝眉的阵营","弗恩·凝眉与部落","弗恩是否属于部落"}}},fp="14,282,21.468.0,22.410.0,22.248.0,31.249.0,42.251.0"}
P.entries["npc:gaerolas-talvethren"] = {n="盖洛拉斯·塔文斯伦",s="盖洛拉斯·塔文斯伦是一位暗夜精灵哨兵，驻守在泰达希尔的星风村废墟。作为沉睡德鲁伊的守护者，他寻求援助以应对具有侵略性的熊怪，以及扰乱林木的黑暗腐蚀。",h="盖洛拉斯·塔文斯伦是一位暗夜精灵哨兵，驻守在泰达希尔的星风村废墟。作为沉睡德鲁伊的守护者，他寻求援助以应对具有侵略性的熊怪，以及扰乱林木的黑暗腐蚀。",kw={"不安的微风","盖洛拉斯·塔文斯伦","棘皮熊怪的腐蚀","星风村","泰达希尔","沉睡者"},ang={["class:Druid"]="作为沉睡德鲁伊的守护者，盖洛拉斯的职责使得协助他完成任务不仅是出于保护他人的目的，更是为了保护塞纳里奥议会的同僚。",["race:NightElf"]="对于从多兰纳尔出发的年轻暗夜精灵来说，协助盖洛拉斯可以让他们深刻地认识到，泰达希尔神圣的林木受到的侵蚀有多么严重。"},sec={{t="沉睡者的守护者",b="盖洛拉斯·塔文斯伦身处动荡不安的星风村，肩负着守护那些在翡翠梦境中沉睡、与自然沟通的德鲁伊的重任。随着非自然的腐蚀在森林中蔓延，扰乱了泰达希尔的平衡，他的警戒也变得愈发艰巨。"},{t="棘皮熊怪的威胁",b="盖洛拉斯指引旅行者去反击棘皮熊怪部落，这些生物的心智已经变得疯狂而野蛮。通过调查从它们萨满身上蔓延开来的污秽，并找出它们痛苦的根源，他希望能保住泰达希尔东部仅存的净土。"}},faq={{q="盖洛拉斯·塔文斯伦是谁？",a="他是一位驻扎在星风村的暗夜精灵防御者，职责是守护沉睡的德鲁伊，并调查该地区出现的奇异腐蚀现象。",al={"盖洛拉斯","盖洛拉斯是谁","盖洛拉斯的角色"}},{q="我在哪里可以找到盖洛拉斯·塔文斯伦？",a="他位于泰达希尔东侧林地的星风村，在多兰纳尔以东。",al={"盖洛拉斯的位置","盖洛拉斯·塔文斯伦在哪里","寻找盖洛拉斯"}},{q="盖洛拉斯保护的“沉睡者”是指谁？",a="沉睡者指的是那些进入古树和圣所深眠以穿越翡翠梦境的暗夜精灵德鲁伊，他们将自己的肉体留在世间，这使得他们极其脆弱。",al={"沉睡者","沉睡者是谁","沉睡的德鲁伊"}},{q="盖洛拉斯担心哪些威胁？",a="他非常担心当地野生动物所遭受的腐蚀，以及棘皮熊怪部落突然爆发的疯狂敌意。",al={"星风村的威胁","盖洛拉斯的任务","棘皮熊怪的麻烦"}}},fx={["52ffd6bd"]={q="盖洛拉斯·塔文斯伦效忠于哪一方？",a="盖洛拉斯坚定地支持达纳苏斯的暗夜精灵和联盟。作为星风村沉睡德鲁伊的誓约守护者，他效忠于塞纳里奥议会、自己的族人以及泰达希尔的守卫。",al={"盖洛拉斯的阵营","盖洛拉斯效忠于谁","盖洛拉斯的效忠对象"}},["436c9e7a"]={q="盖洛拉斯·塔文斯伦想要什么？",a="盖洛拉斯想保护沉睡的德鲁伊，抵御侵入星风村的腐化势力。他希望你协助调查当地蔓延的可怕疫病，并铲除被腐化的瘤背熊怪所表现出的敌意。",al={"盖洛拉斯的目标","盖洛拉斯想做什么","盖洛拉斯的职责"}},["9c3b08f8"]={q="盖洛拉斯·塔文斯伦为什么在这里？",a="盖洛拉斯一直驻守在星风村，因为他被指定为沉睡者的守护者。德鲁伊们与翡翠梦境沟通时，完全无法抵御实体的危险，因此盖洛拉斯必须站岗，防范一切外来威胁。",al={"盖洛拉斯为什么在星风村","盖洛拉斯在此地的原因","盖洛拉斯·塔文斯伦为什么在这里"}}},fp="19,256,24.310.0,20.292.0,27.169.0,37.91.0,46.185.0,41.136.0"}
P.entries["npc:gakin-the-darkbinder"] = {n="黑暗缚灵者加科因",s="黑暗缚灵者加科因是一位术士大师，在暴风城 Mage Quarter 的 Slaughtered Lamb 酒馆深处秘密行动。他教导有志向的联盟修行者学习黑暗艺术，在开启召唤并奴役异界恶魔的仪式之前，先考验他们的意志。",h="黑暗缚灵者加科因是一位术士大师，在暴风城 Mage Quarter 的 Slaughtered Lamb 酒馆深处秘密行动。他教导有志向的联盟修行者学习黑暗艺术，在开启召唤并奴役异界恶魔的仪式之前，先考验他们的意志。",kw={"黑暗缚灵者","加科因","mage quarter","slaughtered lamb","魅魔","surena caledon","虚空行者","术士"},ang={["class:Warlock"]="加科因是人类和侏儒术士的重要导师，在暴风城的墓穴中提供关键的职业任务，以掌握虚空行者和魅魔的仪式。",["faction:Alliance"]="加科因的结社在首都地下秘密运作，展示了联盟核心为了生存所作出的务实而充满暗影的妥协。"},sec={{t="一个秘密聚集地",b="当暴风城的法师们在他们高耸的圣所中公开进行修习时，暗影和邪能的修行者却必须居住在窥探目光无法触及之处。在 Slaughtered Lamb 酒馆的吧台下隐藏着一间潮湿、如同墓穴般的地窖，里面配备了召唤法阵和阴森的法术书。加科因是这个秘密集会的支柱，确保年轻的术士在释放他们无法控制的恐怖力量之前，先学会纪律与克制。"},{t="恶魔大师",b="加科因的专长在于恶魔学和奴役仪式。获得他注意的学徒会被派往王国各地去获取稀有的圣物和材料——从被窃取的血石护身符到黑暗森林中的腐化木材。一旦试剂收集完毕，加科因就会在墓穴的召唤法阵中监督仪式，迫使新手在关乎生死的意志力考验中奴役虚空行者和魅魔。"},{t="背叛与后续麻烦",b="并非所有加科因的学生都能保持顺从。一位前学徒 Surena Caledon 带着一件珍贵的血石颈环潜逃，逃入了荒野。这种内部背叛威胁到了术士结社，可能会使其暴露在城市卫兵面前，因此加科因不得不派遣忠诚的追随者去回收丢失的神器，并在当局察觉之前解决后续麻烦。"}},faq={{q="我可以在哪里找到黑暗缚灵者加科因？",a="加科因位于暴风城 Mage Quarter 的 Slaughtered Lamb 酒馆深处。进入酒馆，找到后方的下坡通道，沿着石质隧道向下走，直到到达最底层墓穴的召唤法阵处。",al={"加科因位置","加科因所在地","slaughtered lamb地下室"}},{q="黑暗缚灵者加科因是做什么的？",a="他是联盟角色的重要术士任务发布者和导师。他通过派遣新手在艾泽拉斯各地进行试炼，并教导他们如何召唤和奴役虚空行者和魅魔等恶魔来考验他们。",al={"加科因的职责","加科因的角色","加科因的任务"}},{q="为什么术士被允许在 Slaughtered Lamb 下面活动？",a="恶魔魔法在暴风城是被禁止的，且深受信徒怀疑。Slaughtered Lamb 下的修行者在严格的秘密中行事，仅被视为一种危险的隐秘资产而受到容忍，并隐藏在城市卫兵和市民的视线之外。",al={"为什么允许术士存在","术士在暴风城是否合法","slaughtered lamb的传说"}},{q="Surena Caledon 是谁？",a="Surena Caledon 是加科因的一位前学徒，她从他那里窃取了一条强大的血石颈环。她的背叛对他们的秘密组织构成了威胁，促使加科因指派术士去追踪她。",al={"surena caledon","加科因的学生","谁偷了加科因的东西"}},{q="加科因帮助召唤哪些恶魔？",a="加科因监督虚空行者和魅魔的奴役仪式，引导术士将这些生物引入地下法阵并将其制服。",al={"加科因的恶魔","加科因的虚空行者","加科因的魅魔"}},{q="Strahad 是谁？为什么加科因提到他？",a="斯坦哈德·法尔杉是一位经验丰富的术士，居住在卡利姆多的棘齿城山丘上。当学生完成加科因的基础奴役仪式后，加科因会将他们指引到海外，继续跟随斯坦哈德·法尔杉进行更深层的黑暗教育。",al={"strahad","寻找strahad","加科因下一步的指引"}}},fp="20,182,24.330.0,16.401.0,24.281.1,38.196.0,34.156.0,52.190.0,22.179.0,36.143.0,46.204.0"}
P.entries["npc:galgar"] = {n="戈加尔",s="戈加尔是驻扎在杜隆塔尔试炼谷的一名兽人厨师。他为正在部落中迈出第一步的年轻新兵准备给养。为了教会新手如何在严酷的沙漠中进行基本的采集，他指派他们收集野外仙人掌果，来制作他的招牌菜。",h="戈加尔是驻扎在杜隆塔尔试炼谷的一名兽人厨师。他为正在部落中迈出第一步的年轻新兵准备给养。为了教会新手如何在严酷的沙漠中进行基本的采集，他指派他们收集野外仙人掌果，来制作他的招牌菜。",kw={"清凉果","仙人掌果","厨师","杜隆塔尔","戈加尔","部落新兵","试炼谷"},ang={["profession:Cooking"]="戈加尔体现了部落实用、质朴的烹饪方式，利用杜隆塔尔稀缺的自然资源，让新兵保持饱腹并随时准备战斗。",["race:Orc"]="对于在试炼谷迈出第一步的年轻兽人来说，为戈加尔跑腿是在面对更凶猛的荒野威胁之前，一种熟悉的试炼仪式。"},sec={{t="谷中的厨师",b="戈加尔位于试炼谷大兽穴的烹饪火堆旁，为正在进行初步试炼的年轻兽人和巨魔提供食物。杜隆塔尔是一片干旱无情、赤红色的荒原，每一丁点补给都必须从这片土地中攫取。通过让新手战士去采集成熟的仙人掌果，戈加尔既能保持厨房的库存，又能考验他们的注意力和适应能力。"},{t="清凉果",b="戈加尔的特色食谱被称为清凉果。虽然他公开承认寻找带刺的沙漠水果是一项刻意安排的简单任务，旨在让新兵轻松开启冒险生涯，但最终成品依然是饥饿学员的主要口粮。即使是部落最坚强的战士也必须从某处开始，而在戈加尔的注视下，这段旅程始于沙漠采集。"}},faq={{q="我在哪里可以找到戈加尔？",a="戈加尔位于试炼谷，这是杜隆塔尔西南部兽人和巨魔的起始峡谷。他站在大兽穴外中心营火和烹饪区附近。",al={"戈加尔位置","戈加尔在哪里","戈加尔坐标"}},{q="戈加尔让冒险者做什么？",a="他让新的冒险者从散布在试炼谷各处的野生仙人掌上采集成熟的仙人掌果，这样他就可以准备他的清凉果了。",al={"戈加尔任务","戈加尔想要什么"}},{q="为什么戈加尔要派新兵去摘水果？",a="戈加尔承认这项任务是刻意安排的简单工作。这对初出茅庐的战士来说是一项轻松的入门差事，能让他们熟悉山谷的地形，并练习在严酷的杜隆塔尔荒野中自给自足。",al={"为什么是仙人掌果","戈加尔的考验"}},{q="什么是清凉果？",a="这是戈加尔的招牌食谱，由采自杜隆塔尔当地沙漠植物的新鲜仙人掌果制成，用以滋养新手新兵。",al={"什么是清凉果","戈加尔的食物"}}},fx={["115dfff8"]={q="戈加尔是谁？",a="戈加尔是一名兽人厨师，驻扎在杜隆塔尔的试炼谷。他不训练战士进行蛮力战斗，而是为定居点准备丰盛的补给，支持这里的生活，尤其以他那道著名的清凉果闻名。",al={"戈加尔是谁","戈加尔的背景","谁是戈加尔"}},["7f3ad096"]={q="戈加尔效忠哪一方？",a="戈加尔效忠于萨尔的部落。他在试炼谷中为那些初次踏上为杜隆塔尔效力之路的年轻兽人和巨魔提供直接帮助。",al={"戈加尔的阵营","戈加尔是部落成员吗","戈加尔的效忠对象"}},d4d57a6c={q="戈加尔想要什么？",a="戈加尔想要新鲜食材，主要是生长在干旱山谷各处的成熟仙人掌果，这样他就能制作一批批招牌清凉果，让年轻的新兵吃饱并保持精力充沛。",al={"戈加尔需要什么","戈加尔的目标","戈加尔想要什么"}},["50f967f0"]={q="戈加尔为什么在试炼谷？",a="戈加尔驻扎在试炼谷，为营地的厨房提供支持。训练师教导有志者战争之道时，戈加尔确保营地有充足的食物，并让新来者熟悉基础野外工作。",al={"戈加尔为何在这里","戈加尔在试炼谷的原因","戈加尔为何在杜隆塔尔"}},["2e1d8215"]={q="戈加尔为何出名？",a="戈加尔以招牌食谱清凉果而闻名于整个试炼谷。几乎每个经过大兽穴的年轻新兵，都会在替他做入门杂务时尝到他的手艺。",al={"戈加尔出名吗","戈加尔以什么闻名","戈加尔的名声"}}},fp="6,294,20.415.0,21.418.0,24.177.0,39.157.0,48.211.0,30.139.0"}
P.entries["npc:gan-rul-bloodeye"] = {n="甘鲁尔·血眼",s="甘鲁尔·血眼是一位资深的兽人术士训练师，居住在奥格瑞玛暗影裂口深处的阴暗洞穴中。他远离地面城市的注视，引导部落术士进行更黑暗的恶魔仪式。在他的指导下，新手们学会了让虚空行者和魅魔等异界实体屈服于他们的意志。",h="甘鲁尔·血眼是一位资深的兽人术士训练师，居住在奥格瑞玛暗影裂口深处的阴暗洞穴中。他远离地面城市的注视，引导部落术士进行更黑暗的恶魔仪式。在他的指导下，新手们学会了让虚空行者和魅魔等异界实体屈服于他们的意志。",kw={"血眼","cleft of shadow","甘鲁尔","奥格瑞玛","魅魔","训练师","虚空行者","术士"},ang={["class:Warlock"]="对于寻求禁忌知识的术士来说，甘鲁尔是卡利姆多的一位重要导师，他提供了束缚虚空行者和魅魔所需的知识与试炼。",["faction:Horde"]="甘鲁尔体现了邪能魔法在萨尔部落中岌岌可危的地位——尽管它被用于军事力量，但却被限制在首都的地下深处。"},sec={{t="阴影中的大师",b="尽管大酋长萨尔容忍术士在新部落中的存在，但他们的黑暗技艺在杜隆塔尔明媚的阳光下并不受欢迎。甘鲁尔·血眼在大断崖安家，这是一个位于奥格瑞玛地下深处的避难所，暗影编织者、潜行者和邪能施法者可以在此不受干扰地进行研究。从这个地下据点开始，甘鲁尔成为了邪能魔法进阶者们的主要导师。"},{t="束缚虚空",b="甘鲁尔的主要职责是监督雄心勃勃的术士们必须进行的危险召唤仪式。那些寻求束缚更强大恶魔（如坚韧的虚空行者或诱惑的魅魔）的修行者必须咨询甘鲁尔，以获取仪式所需的材料，并学习精确的咒语，从而在被召唤的生物吞噬其主人之前将其制服。"}},faq={{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是一位驻扎在奥格瑞玛的兽人术士训练师。他指导部落的术士新手和进阶学员，教授他们如何召唤并束缚来自扭曲虚空的恶魔。",al={"甘鲁尔·血眼","甘鲁尔是谁","甘鲁尔·血眼的角色"}},{q="我在哪里可以找到甘鲁尔·血眼？",a="他位于暗影裂口，这是隐藏在奥格瑞玛地下深处的洞穴网络。他与其他黑暗修行者站在一起，远离城市的主要干道。",al={"甘鲁尔的位置","甘鲁尔·血眼在哪里","暗影裂口训练师在哪里"}},{q="为什么术士要隐藏在暗影裂口中？",a="在经历了兽人曾经被奴役的历史后，大酋长萨尔和新部落的萨满社会对邪能魔法和恶魔腐化有着极度的不信任。术士在部落中被允许存在完全是因为他们的功用，但他们的活动被限制在阴影中，以防止引发社会动荡。",al={"为什么在洞穴里","为什么要隐藏术士","暗影裂口背景"}},{q="甘鲁尔帮助召唤哪些恶魔？",a="甘鲁尔引导术士完成召唤并奴役虚空行者和魅魔所需的仪式。完成他的任务证明了召唤者拥有控制这些魔物所需的意志力。",al={"甘鲁尔教授的恶魔","甘鲁尔的恶魔任务","虚空行者魅魔训练师"}},{q="甘鲁尔有已知的亲属吗？",a="他与Halga Bloodeye拥有相同的姓氏，尽管他们之间的确切关系尚未有明确记录。",al={"甘鲁尔的亲属","halga bloodeye亲属"}},{q="甘鲁尔提到的斯坦哈德是谁？",a="斯坦哈德·法尔杉是一位居住在贫瘠之地靠近棘齿城山丘的一位造诣深厚的术士。甘鲁尔最终会将有前途的学生送往斯坦哈德那里，以接受更高级的指导和更大的挑战。",al={"寻找斯坦哈德","斯坦哈德是谁","斯坦哈德任务"}}},fx={["11e29292"]={q="甘鲁尔·血眼效忠哪一方？",a="甘鲁尔·血眼为部落效力，在萨尔的首都地下训练黑暗魔法的修习者。尽管萨满教领袖对术士深怀戒心，甘鲁尔仍将自己的奥术技艺用于增强部落的生存能力与力量，并指导愿意驾驭邪能、保卫部落的人。",al={"甘鲁尔·血眼的阵营","甘鲁尔的效忠对象","甘鲁尔为谁效力"}},["67b7b1ae"]={q="甘鲁尔·血眼想要什么？",a="甘鲁尔希望通过考验新晋术士、教导他们掌控扭曲虚空，来扩充部落中有能力的术士队伍。他要求学徒严守纪律、专注于秘术，并指导他们束缚虚空行者和魅魔等危险的恶魔生物，使黑暗魔法成为顺从的武器，而非吞噬一切的威胁。",al={"甘鲁尔的目标","甘鲁尔想要什么","甘鲁尔的目的"}}},fp="16,344,23.407.0,18.364.0,24.187.0,34.188.0,47.285.0,37.219.0,35.100.0,38.198.0"}
P.entries["npc:gann-stonespire"] = {n="加恩·石塔",s="加恩·石塔是一名心怀怨恨的牛头人游民，常年在南贫瘠之地靠近巴尔莫丹的道路上徘徊。由于部落祖传的猎场被矮人挖掘者占据，他被迫背井离乡，如今一心想要对这座步步进逼的挖掘场进行报复。",h="加恩·石塔是一名心怀怨恨的牛头人游民，常年在南贫瘠之地靠近巴尔莫丹的道路上徘徊。由于部落祖传的猎场被矮人挖掘者占据，他被迫背井离乡，如今一心想要对这座步步进逼的挖掘场进行报复。",kw={"巴尔莫丹","巴尔邓","加恩·石塔","勘探员卡兹戈姆","南贫瘠之地","石塔"},ang={["faction:Horde"]="协助加恩为部落提供了一个重要的战术机会，可以遏制在南贫瘠之地根深蒂固的联盟扩张主义。",["race:Tauren"]="加恩的境遇代表了游牧牛头人更广泛的斗争，他们的祖传土地和神圣大地正不断遭到外来联盟远征队的亵渎。"},sec={{t="流离失所自巴尔莫丹",b="在来自铁炉堡的矮人远征队抵达并建造巴尔莫丹要塞之前，周围的土地一直是加恩·石塔部落的祖传领地和猎场。矮人矿工拒绝了和平交涉，用鹤嘴锄、枪支和重型机械将当地的牛头人驱逐出了他们的家园。如今，加恩露宿在尘土飞扬的南贫瘠之地道路旁，拒绝默默放弃自己的传承，他正在集结过往的旅人，以反击这些挖掘者。"},{t="收复与破坏",b="加恩认识到和平外交已彻底失败，于是指挥部落的特工打破矮人对挖掘场的控制。他的报复目标锁定在远征队的核心领导层，特别是勘探员卡兹戈姆，并打算将矮人的爆破火药和军火改造成爆炸装置。通过将装置直接在矮人的飞行器下方引爆，加恩旨在摧毁他们的技术优势，并为其流离失所的族人赢回尊严。"}},faq={{q="谁是加恩·石塔？",a="加恩·石塔是一位牛头人战士，他的部落曾经居住在如今被巴尔莫丹矮人要塞所占据的土地上。在矮人建立挖掘场时，他被迫流离失所，现在他在南贫瘠之地的路边徘徊，寻求复仇并试图收复族人的家园。",al={"谁是加恩","加恩·石塔背景故事","巴尔莫丹外的牛头人"}},{q="为什么加恩要与巴尔莫丹的矮人作战？",a="巴尔邓矮人远征队抵达南贫瘠之地，为了建造他们的挖掘要塞，强行将当地的牛头人从祖传猎场中驱逐出去。在矮人拒绝了一切外交努力后，加恩下定决心要通过武力拆除他们的营地。",al={"加恩为何痛恨矮人","为何攻击巴尔莫丹","加恩与巴尔莫丹的冲突"}},{q="加恩针对挖掘场有什么计划？",a="加恩首先委托他人除掉矮人监工，包括勘探员卡兹戈姆，以夺取挖掘记录。随后，他利用偷来的矮人军火和爆破物资，策划组装一枚炸弹，旨在摧毁远征队的飞行器，从而瓦解他们的技术优势。",al={"加恩的复仇计划","加恩在做什么","巴尔莫丹炸弹"}},{q="加恩·石塔在哪里扎营？",a="你可以在南贫瘠之地巴尔莫丹以西的道路上找到他，他就在挖掘场周边区域之外徘徊。",al={"加恩在哪里","加恩·石塔位置"}}},fx={["60933082"]={q="加恩·石塔效忠哪一方？",a="加恩与部落及他的牛头人同胞并肩而立。他向途经南贫瘠之地的部落勇士寻求援助，打击侵占族人圣地的巴尔莫丹矮人。",al={"加恩·石塔是部落成员吗","加恩·石塔的阵营","加恩为谁而战"}},["59c620b8"]={q="加恩·石塔与谁有关联？",a="加恩属于一个牛头人部族，其祖居地横跨如今被巴尔莫丹占据的土地。他代表被迫离乡的族人行事；矮人的挖掘行动开始后，他们便遭到驱逐。",al={"加恩·石塔的部族","加恩的族人是谁","加恩·石塔的氏族"}}},fp="15,239,25.485.0,24.466.1,23.308.0,47.289.0,43.297.1,41.134.0"}
P.entries["npc:gar-thok"] = {n="加索克",s="加索克是一位老练的兽人战士，也是驻守在杜隆塔尔剃刀岭的前哨指挥官。他在库尔提拉斯人首次登陆杜隆塔尔海岸的入侵中幸存了下来，现在负责协调当地的防御力量，抵御人类入侵者和本土威胁。他指引着那些刚从试炼谷走出来的年轻部落新兵，保卫这片新家园的赤色荒野。",h="加索克是一位老练的兽人战士，也是驻守在杜隆塔尔剃刀岭的前哨指挥官。他在库尔提拉斯人首次登陆杜隆塔尔海岸的入侵中幸存了下来，现在负责协调当地的防御力量，抵御人类入侵者和本土威胁。他指引着那些刚从试炼谷走出来的年轻部落新兵，...",kw={"戴林","杜隆塔尔","加索克","库尔提拉斯","纳兹格雷尔","剃刀岭","雷克萨","提拉加德"},ang={["class:Warrior"]="作为一名在残酷的海军伏击中幸存下来的前线指挥官，加索克期望与他并肩作战的战士们拥有坚定的战斗意志和毫不犹豫的服从精神。",["faction:Horde"]="加索克确保所有部落种族的新兵都能理解他们这片新领地的危急局势，并指引他们去击退入侵的联盟残部。",["race:Orc"]="对于离开试炼谷的年轻兽人来说，加索克代表了那一代为赢得杜隆塔尔而流血牺牲的老兵们坚毅、不屈的纪律。"},sec={{t="赤色荒野的老兵",b="第三次大战后，加索克在大酋长萨尔的麾下开赴杜隆塔尔，并在建立新家园的初期担任纳兹格雷尔的副官。当半食人兽流浪者雷克萨初次抵达杜隆塔尔时，正是加索克提醒他注意当时正在袭击外围防线的刺背野猪人，并招募这位兽王来保卫这片脆弱的新定居点。"},{t="海军上将入侵中的幸存者",b="戴林·普罗德摩尔海军上将的库尔提拉斯舰队在杜隆塔尔东岸登陆时，加索克的意志受到了考验。当时他驻守在一个偏远的哨所，亲眼目睹了自己的驻军被海军陆战队以残忍的手段屠杀殆尽。虽然部队遭受了重创，但加索克在猛攻中幸存了下来。那次突袭的记忆令他时刻保持警惕，致力于对抗那些依然盘踞在提拉加德城堡和海岸沉船残骸中的残余海军。"},{t="保卫剃刀岭",b="如今，加索克在剃刀岭的军营中负责监督杜隆塔尔中部的军事防御工作。他从不浪费时间进行寒暄，而是立即指派新晋的部落战士、萨满和侦察兵去清理敌对的库尔提拉斯残部，回收被抢走的补给品，并找回遗落在海岸废墟中的军事命令。对他而言，杜隆塔尔的安全远未得到保障，必须时刻向那些质疑部落这片土地所有权的人施加压力。"}},faq={{q="谁是加索克？",a="加索克是一位驻守在剃刀岭的兽人军官，负责组织当地的军事力量以应对杜隆塔尔境内的敌对势力。他是第三次大战的老兵，在奥格瑞玛建立初期曾在纳兹格雷尔麾下服役。",al={"加索克背景故事","谁是加索克","剃刀岭指挥官"}},{q="在来到剃刀岭之前，加索克在哪里战斗过？",a="他曾在杜隆塔尔的一处前哨站担任纳兹格雷尔的副官，并与雷克萨并肩作战，平定早期的野猪人袭击，直到后来库尔提拉斯水兵攻占了该哨所并杀害了他的部下。",al={"加索克过去","加索克海加尔山","加索克历史"}},{q="为什么加索克如此痛恨杜隆塔尔的人类？",a="在戴林·普罗德摩尔海军上将领导的入侵期间，来自库尔提拉斯的水兵伏击了加索克在海岸上的前哨站，屠杀了他的部下。他在袭击中幸存下来，至今仍致力于铲除残存的海军营地。",al={"为什么加索克痛恨库尔提拉斯","加索克人类","提拉加德城堡加索克"}},{q="加索克会派冒险者去对付哪些威胁？",a="加索克派遣新兵去对抗盘踞在提拉加德城堡的敌对库尔提拉斯水兵，从海岸沉船残骸中回收补给品，击退入侵的野猪人，并寻找人类指挥官留下的任何命令。",al={"加索克任务","加索克想要什么","剃刀岭任务"}},{q="他与纳兹格雷尔和萨尔的关系如何？",a="在杜隆塔尔最初的殖民远征期间，加索克曾担任纳兹格雷尔麾下的一名可信副官，直接在大酋长萨尔的授权下行动，以确保这片新领地的边界安全。",al={"加索克纳兹格雷尔","加索克萨尔","加索克军衔"}},{q="在哪里可以找到加索克？",a="加索克站在位于杜隆塔尔中心定居点剃刀岭的主瞭望塔和兵营外，这里位于奥格瑞玛的南面。",al={"加索克位置","加索克在哪里","寻找加索克"}}},fx={["61b8b646"]={q="加索克效忠哪一方？",a="加索克完全效忠于部落和大酋长萨尔。他奉纳兹格雷尔之命驻扎在杜隆塔尔，不遗余力地保卫新兴的兽人家园，并确保新来的战士做好准备，守护部落的边境。",al={"加索克的阵营","加索克是部落成员吗","加索克为谁效力"}},["7b499593"]={q="加索克想要什么？",a="加索克希望杜隆塔尔得到稳固防护，免受一切威胁。他亲眼目睹自己的前哨站被库尔提拉斯入侵者屠戮，因此寻求向海岸上残存的人类水手复仇，并要求镇压骚扰定居点、不断逼近的猪人。",al={"加索克的目标","加索克想要什么","加索克的动机"}},["007248aa"]={q="加索克为什么在这里？",a="海岸前哨站遭库尔提拉斯军队摧毁后，加索克便在剃刀岭任职。他从这个中心定居点组织杜隆塔尔的防御，并指挥新晋的部落勇士抵御敌人的侵袭。",al={"加索克为何在剃刀岭","加索克为何在这里","加索克在剃刀岭的职责"}}},fp="8,352,27.382.0,32.468.0,21.473.0,16.219.0,53.185.0,53.239.0,53.219.0,49.219.0,28.133.0"}
P.entries["npc:gart-mistrunner"] = {n="加尔特·迷雾行者",s="加尔特·迷雾行者是驻扎在红云台地纳拉其营地的常驻德鲁伊训练师。他欢迎那些受到大地母亲感召的牛头人新手，并指引他们完成最初的自然魔法仪式。",h="加尔特·迷雾行者是驻扎在红云台地纳拉其营地的常驻德鲁伊训练师。他欢迎那些受到大地母亲感召的牛头人新手，并指引他们完成最初的自然魔法仪式。",kw={"纳拉其营地","德鲁伊训练师","加尔特·迷雾行者","迷雾行者","莫高雷","红云台地","牛头人德鲁伊"},ang={["class:Druid"]="对于牛头人德鲁伊来说，加尔特·迷雾行者是引导他们与荒野沟通以及领悟大地母亲馈赠的第一位导师。",["race:Tauren"]="加尔特代表了舒哈鲁古老德鲁伊传统的复兴，将祖先的智慧传授给纳拉其营地的年轻一代。"},sec={{t="红云台地的导师",b="加尔特·迷雾行者守卫着纳拉其营地，代表了舒哈鲁之中重燃的古老德鲁伊之道。新的牛头人德鲁伊在踏上红云台地后，通常会带着一封推荐他们接受其指导的“绿色便笺”，直接被引荐给加尔特。通过他耐心的教导，年轻的修行者们学会了与自然世界沟通，借用自然恢复的力量和穆沙的月光来治疗盟友并打击威胁这片土地的敌人。"}},faq={{q="加尔特·迷雾行者是谁？",a="加尔特·迷雾行者是一位位于莫高雷红云台地纳拉其营地的牛头人德鲁伊训练师。他负责指导新手牛头人德鲁伊学习最初的法术和仪式。",al={"加尔特是谁","加尔特·迷雾行者背景故事","加尔特·迷雾行者"}},{q="他会教导刚觉醒的德鲁伊什么法术？",a="加尔特会向初学者介绍基本的自然能力，教授早期的治疗法术（如愈合之触）以及攻击性的自然魔法（如月火术）。",al={"加尔特教什么","加尔特·迷雾行者训练","纳拉其营地德鲁伊法术"}},{q="他与迷雾行者氏族有什么联系？",a="迷雾行者只是加尔特的一个姓氏。目前没有任何传说描述过迷雾行者部族，也没有更多关于他亲属的信息；他仅仅以纳拉其营地的德鲁伊训练师而闻名。",al={"迷雾行者氏族","谁是迷雾行者"}}},fx={fd7992e7={q="加尔特·迷雾行者效忠哪一方？",a="加尔特·迷雾行者忠于牛头人部族，并与部落并肩作战。他驻扎在纳拉其营地，位于红云台地中心，在祖先的故土上守护牛头人传统，培育运用自然恩赐保护土地、服务族人的年轻修习者。",al={"加尔特·迷雾行者的阵营","加尔特为谁效力","加尔特·迷雾行者是部落成员吗"}},["4b2be6b9"]={q="加尔特·迷雾行者为什么在这里？",a="加尔特住在纳拉其营地，教导那些听见荒野召唤的牛头人新手。作为红云台地的德鲁伊训练师，他向新觉醒的学徒传授自然之道，引导他们在踏入莫高雷广阔的平原之前，打下灵性与武技的基础。",al={"加尔特为何在纳拉其营地","加尔特·迷雾行者的目的","加尔特·迷雾行者在这里做什么"}},["8def0ffd"]={q="加尔特·迷雾行者想要什么？",a="加尔特希望通过训练新晋德鲁伊领悟自然平衡，促进牛头人与大地母亲和谐共处。他希望年轻学徒掌握早期仪式，例如恢复活力的治疗术和平衡咒语，为他们治愈土地、保护部族免受逼近的威胁做好准备。",al={"加尔特·迷雾行者的目标","加尔特想要什么","加尔特·迷雾行者的动机"}}},fp="15,206,28.505.0,23.168.0,48.150.0,46.160.0"}
P.entries["npc:gath-ilzogg"] = {n="加塞尔佐格",s="加塞尔佐格是可怕的黑石氏族兽人督军，他指挥着占领了赤脊山石堡要塞的入侵部队。在他的残暴领导下，兽人们夺取了这座堡垒，并对湖畔镇发起了毁灭性的袭击，这使他遭到了绝望的镇长发出的紧急悬赏。",h="加塞尔佐格是可怕的黑石氏族兽人督军，他指挥着占领了赤脊山石堡要塞的入侵部队。在他的残暴领导下，兽人们夺取了这座堡垒，并对湖畔镇发起了毁灭性的袭击，这使他遭到了绝望的镇长发出的紧急悬赏。",kw={"黑石氏族","加塞尔佐格","湖畔镇","摩根斯","辛格","所罗门","石堡","石堡要塞"},ang={["faction:Alliance"]="击败加塞尔佐格可以粉碎威胁湖畔镇的黑石攻势核心，并回应所罗门镇长的绝望求助。",["race:Orc"]="加塞尔佐格代表了旧部落在黑暗部落领导下好战的黑石氏族传统，这与卡利姆多萨尔建立的新部落完全不同。"},sec={{t="石堡的灾祸",b="加塞尔佐格奉命从燃烧平原北上，意图为黑石氏族确保赤脊山的安全。在叛变的人类术士摩根斯的邪恶魔法协助下，加塞尔佐格的战团击溃了石堡要塞的守军，占据了俯瞰整个区域的制高点。从这个坚固的堡垒中，他指挥着对山谷以及下方湖畔镇大桥的猛烈突袭，不断蚕食着人类定居点。他很少孤身作战，身边总是跟着精英黑石卫兵和一只名叫辛格的凶猛黑龙幼龙。"},{t="脆弱的据点",b="尽管加塞尔佐格征服了石堡，他的胜利也带来了新的麻烦。摩根斯很快背叛了他以前的兽人盟友，召集了一支由牙皮豺狼人组成的军队，在副官芬戈尔的率领下，袭击黑石巡逻队和人类旅人。与此同时，所罗门镇长悬赏捉拿这位督军，恳求任何联盟雇佣兵或冒险者攀上石堡要塞的城墙，在城镇彻底沦陷前终结加塞尔佐格的恐怖统治。"}},faq={{q="谁是加塞尔佐格？",a="加塞尔佐格是隶属于黑石氏族的兽人督军。他率领着入侵赤脊山的前锋部队，并成功从联盟手中夺取了石堡要塞。",al={"加塞尔佐格背景故事","加塞尔佐格是谁","赤脊山黑石首领"}},{q="在哪里可以找到加塞尔佐格？",a="他盘踞在赤脊山东部峭壁上的石堡要塞的最顶端。",al={"加塞尔佐格位置","加塞尔佐格在哪里","寻找加塞尔佐格"}},{q="为什么加塞尔佐格有一只幼龙？",a="加塞尔佐格身边有一只名叫辛格的黑龙幼龙，普遍认为这是维克多·奈法里奥斯勋爵赠予这位督军的礼物，以奖励他成功夺取了石堡要塞。",al={"为什么加塞尔佐格旁边有幼龙","幼龙辛格","加塞尔佐格黑龙幼龙"}},{q="为什么他的项上人头会有悬赏？",a="湖畔镇的所罗门镇长发布了针对加塞尔佐格的高优先级悬赏，因为这位督军不断的袭击和对石堡的占领直接威胁到了湖畔镇，使其面临被彻底毁灭的危险。",al={"通缉加塞尔佐格","谁想要加塞尔佐格死","所罗门镇长悬赏"}},{q="加塞尔佐格和摩根斯之间发生了什么？",a="人类术士摩根斯最初利用暗影魔法帮助加塞尔佐格攻占了石堡。然而，堡垒陷落后，摩根斯背叛了兽人，并召集了一支牙皮豺狼人大军，同时攻击人类和黑石氏族。",al={"摩根斯与加塞尔佐格的盟约","为什么豺狼人攻击兽人","摩根斯背叛"}}},fx={["9f2c44f6"]={q="加塞尔佐格效忠哪一方？",a="加塞尔佐格是黑石氏族的军阀，效忠于盘踞在黑石山的黑暗部落。他和他的部队积极与暴风王国交战，对联盟以及任何踏入他们征服领土的人都怀有彻底的敌意。",al={"加塞尔佐格的阵营","加塞尔佐格为谁效力","加塞尔佐格是黑石氏族成员吗"}},["56c8e0ec"]={q="加塞尔佐格想要什么？",a="加塞尔佐格在石堡要塞策划摧毁湖畔镇，并彻底征服赤脊山。他指挥对人类定居点的袭击，致力于扩张黑石氏族对周边土地的统治。",al={"加塞尔佐格的目标是什么","加塞尔佐格的计划","加塞尔佐格为何发动袭击"}},d3a450f6={q="加塞尔佐格为什么在这里？",a="加塞尔佐格率领部队发动进攻，击溃了石堡要塞的联盟守军。占领这座堡垒后，他将其用作坚固的行动基地，以便深入赤脊山腹地发动袭击，并组织对湖畔镇的劫掠。",al={"加塞尔佐格为何在赤脊山","加塞尔佐格为何在石堡","加塞尔佐格与石堡"}},d6829113={q="加塞尔佐格与谁有关联？",a="除了指挥当地的黑石兽人之外，加塞尔佐格还曾与叛变的人类术士摩根斯结成阴险同盟，一同夺取石堡要塞。他还指挥着幼龙辛格；这头生物很可能是维克多·奈法里奥斯领主为嘉奖他的胜利而赐予他的。",al={"加塞尔佐格的盟友","谁与加塞尔佐格共事","加塞尔佐格的关系"}},b07f2498={q="加塞尔佐格为何令人畏惧？",a="加塞尔佐格成功策划攻陷石堡要塞，击溃当地联盟驻军，证明了自己的致命威胁。所罗门镇长认为他是湖畔镇存亡面临的首要军事威胁，因此对这名军阀悬赏重金。",al={"加塞尔佐格为何危险","加塞尔佐格出名吗","加塞尔佐格的名声"}}},fp="11,321,25.571.0,14.490.1,19.167.0,31.108.0,41.182.0,34.205.0,47.241.0"}
P.entries["npc:gaxim-rustfizzle"] = {n="加克希姆·尘链",s="加克希姆·尘链是一位雄心勃勃的侏儒学者和工匠，驻扎在石爪山脉蛛网小径旁的一个小型联盟营地中。作为奥术、炼金与工程科学启蒙学会的代表，他试图向持怀疑态度的暗夜精灵证明，先进的器械和炼金术能够保护他们的林地王国。他的科学好奇心与其对荆棘谷地精破坏性行动的强烈敌意相得益彰。",h="加克希姆·尘链是一位雄心勃勃的侏儒学者和工匠，驻扎在石爪山脉蛛网小径旁的一个小型联盟营地中。作为奥术、炼金与工程科学启蒙学会的代表，他试图向持怀疑态度的暗夜精灵证明，先进的器械和炼金术能够保护他们的林地王国。他的科学好奇...",kw={"学会","加克希姆","侏儒","凯拉","尘链","石爪山脉","荆棘谷地精","蛛网小径","狂风峭壁"},ang={["faction:Alliance"]="加克希姆驻扎在险峻的蛛网小径，提供关键的侦察、情报和破坏任务，以遏制石爪山脉中激进的工业入侵。",["profession:Engineering"]="加克希姆将工程学原理应用于实地，设计了专门针对干扰粗糙的荆棘谷地精机械的秘密行动和战术装置。",["race:Gnome"]="加克希姆代表了侏儒学术界的最高自豪感，向卡利姆多的古老文化展示了齿轮和试剂在拯救森林方面与自然魔法同样有效。",["race:NightElf"]="尽管传统主义者可能会嘲笑他的嗡嗡作响的小玩意和冒泡的药水，但加克希姆是一位坚定的盟友，积极保卫着灰谷和石爪山脉的边界，使其免受地精工业的侵扰。"},sec={{t="一位科学特使",b="虽然暗夜精灵传统上依赖于古老的德鲁伊教义和自然魔法，但加克希姆·尘链来到石爪山脉的崎岖隘口，是为了展示一种截然不同的视角。作为奥术、炼金与工程科学启蒙学会的代表，他真心相信，经过计算的机械装置和化学解决方案在保护和修复卡利姆多荒野方面，与向艾露恩祈祷同样有效。他与哨兵凯拉·影矛一起驻扎在蛛网小径，不知疲倦地工作，试图让这些高大且孤僻的盟友相信工程学的生态价值。"},{t="破坏锯木机",b="加克希姆的很大一部分精力都用于对抗荆棘谷地精，他们的滥砍滥伐和工业贪婪亵渎了附近的狂风峭壁。加克希姆认为，粗糙的地精机器既不值得尊重，也不值得怜悯，因此他协调了一系列针对其伐木作业的秘密行动和挥发性化学破坏。对他而言，瘫痪他们的伐木机并窃取其图纸不仅是战术上的对抗，更是一种实实在在的证明：优越的侏儒智慧总是能战胜粗心大意的企业掠夺。"}},faq={{q="加克希姆·尘链是谁？",a="加克希姆·尘链是一位侏儒学者和发明家，驻扎在石爪山脉蛛网小径旁的一个联盟哨所。他担任奥术、炼金与工程科学启蒙学会的特使。",al={"加克希姆是谁","加克希姆·尘链背景故事","石爪山脉的侏儒"}},{q="什么是奥术、炼金与工程科学启蒙学会？",a="这是一个由侏儒组成的学术和科学协会，致力于融合奥术魔法、炼金混合物和机械工程等学科。加克希姆在卡利姆多代表着他们的理想。",al={"启蒙学会","加克希姆所属阵营","加克希姆所属组织"}},{q="加克希姆为什么与暗夜精灵合作？",a="加克希姆希望向暗夜精灵证明，侏儒的科学和炼金术可以积极地保护和治愈自然林地，从而为森林保护提供一种除了传统德鲁伊教义之外的、现代的联盟式方案。",al={"加克希姆为什么在这里","加克希姆与暗夜精灵","加克希姆的目标"}},{q="加克希姆为什么痛恨荆棘谷地精？",a="荆棘谷地精正利用粗糙的机器和有毒的污染物在狂风峭壁进行残酷的滥砍滥伐。加克希姆鄙视他们这种鲁莽的剥削行为，并乐于利用挥发性化学品和破坏活动来对付他们的行动。",al={"加克希姆与荆棘谷地精","加克希姆对抗荆棘谷地精","为什么要打击荆棘谷地精"}},{q="谁和加克希姆一起驻扎在蛛网小径？",a="他和暗夜精灵哨兵凯拉·影矛共用一个小哨所，她负责监视通往狂风峭壁的小径。",al={"加克希姆的伙伴","谁和加克希姆在一起","加克希姆与凯拉"}},{q="在哪里可以找到加克希姆·尘链？",a="他位于石爪山脉蛛网小径旁的一个小型联盟营地，就在狂风峭壁工业伐木场的西南方。",al={"加克希姆位置","加克希姆在哪里","加克希姆·尘链地图位置"}}},fx={d5f6878f={q="加克希姆·尘链效忠哪一方？",a="加克希姆效忠联盟，并与石爪山的暗夜精灵并肩工作。他代表奥术学、炼金术与工程科学启蒙协会，作为侏儒智慧的使者，力图向心存疑虑的卡多雷盟友证明，将奥术知识、化学混合物与机械工艺结合起来，可以保护自然，而非毁灭自然。",al={"加克希姆·尘链阵营","加克希姆是否效忠联盟","加克希姆为谁效力"}}},fp="16,465,21.595.0,19.523.0,24.238.0,81.204.0,42.216.0,40.225.0,43.126.0,36.158.0"}
P.entries["npc:gazin-tenorm"] = {n="贾森·坦诺姆",s="贾森·坦诺姆是一名驻扎在暴风城光明大教堂祭坛附近的矮人。他与战友亨兹·法奥克一同执行了一项危险的侦察任务，旨在为国王的顾问们搜集迪菲亚潜行者活动的证据。",h="贾森·坦诺姆是一名驻扎在暴风城光明大教堂祭坛附近的矮人。他与战友亨兹·法奥克一同执行了一项危险的侦察任务，旨在为国王的顾问们搜集迪菲亚潜行者活动的证据。",kw={"cathedral of light","迪菲亚潜行者","达索瑞恩·拉尔","贾森·坦诺姆","亨兹·法奥克","圣骑士","神圣之书"},ang={["class:Paladin"]="学习同情与救赎之道的学徒们会在光明大教堂遇见贾森，并由此前去援助他那倒下的战友，亨兹·法奥克。",["race:Dwarf"]="贾森代表了铁炉堡与暴风城之间持久的团结，作为一名矮人勇士，他愿意为了王国的顾问们去对抗艾尔文森林的强盗。"},sec={{t="大教堂里的侦察兵",b="虽然贾森·坦诺姆整日待在安静的光明大教堂内，但他的心思依然留在艾尔文森林的荒野之中。贾森和他的挚友亨兹·法奥克曾深入丛林执行一项紧急任务：搜集关于迪菲亚潜行者动向的确凿证据，以便呈报给皇室议会。然而在探查途中，他们遭到了迪菲亚势力的伏击，行动因此受挫。贾森侥幸逃回了暴风城，但亨兹却被留在了极度危险的境地，这促使贾森不得不寻求一位坚定的圣光勇士来拯救他的同伴。"}},faq={{q="我在哪里可以找到贾森·坦诺姆？",a="贾森·坦诺姆位于暴风城的光明大教堂内，他站在后方的祭坛附近，与高阶教士和圣骑士导师们在一起。",al={"贾森位置","贾森·坦诺姆在哪里","贾森在哪里"}},{q="贾森·坦诺姆在艾尔文森林遭遇了什么？",a="在与同伴亨兹·法奥克调查迪菲亚潜行者时，贾森遭遇了暴徒势力的伏击。他拼死杀出重围并逃回了暴风城，但那次遭遇让他的朋友被困在了森林中。",al={"贾森背景故事","贾森遭遇了什么","为什么贾森受伤了"}},{q="贾森为什么要调查迪菲亚潜行者？",a="贾森和亨兹·法奥克深入艾尔文森林，旨在搜集迪菲亚潜行者非法活动的铁证，并打算将这些不容置疑的证据直接呈交给暴风城的国王顾问们。",al={"为什么要调查迪菲亚潜行者","贾森任务","贾森 亨兹 迪菲亚潜行者"}},{q="贾森与圣骑士的试炼有什么关联？",a="达索瑞恩·拉尔会将那些寻求《神圣之书》的人类圣骑士学徒指引给贾森。贾森会提供解救他落难同伴亨兹·法奥克的途径和指引，以此考验学徒的勇气与仁慈。",al={"贾森 神圣之书","圣骑士任务 贾森","亨兹·法奥克任务"}}},fp="12,127,24.374.0,30.135.0,47.174.0,51.140.0,45.162.0"}
P.entries["npc:gazrog"] = {n="加兹罗格",s="加兹罗格是一位驻扎在贫瘠之地中心地带十字路口的兽人战士。他负责维护萨拉瓦荒原上危险道路的后勤与安全，并征募有能力的部落旅者来处理地区威胁并调查失踪的巡逻队。",h="加兹罗格是一位驻扎在贫瘠之地中心地带十字路口的兽人战士。他负责维护萨拉瓦荒原上危险道路的后勤与安全，并征募有能力的部落旅者来处理地区威胁并调查失踪的巡逻队。",kw={"贫瘠之地","十字路口","多格兰","加兹罗格","部落前哨站","迅猛龙小偷","被偷走的银币"},ang={["faction:Horde"]="加兹罗格是离开杜隆塔尔或莫高雷的部落冒险者接触到的早期联络人，他提供关键工作来建立穿越卡利姆多的安全旅行走廊。",["race:Orc"]="作为一名坚守十字路口的兽人老兵，加兹罗格体现了征服无情的卡利姆多边疆所需的坚毅和务实的品质。"},sec={{t="十字路口的哨兵",b="十字路口是部落在卡利姆多所有交通往来的重要枢纽，但其孤立的位置使得补给线极易受到劫匪和野兽的袭击。加兹罗格与定居点的卫兵们一同站岗，努力确保货物、钱币和信使能够抵达目的地。在广袤的荒野中维持秩序需要时刻保持警惕，加兹罗格非常依赖路过的冒险者来处理前哨站栅栏外酝酿的危机。"},{t="荒原危机",b="从骚扰道路的掠食迅猛龙到伏击斥候的刺背野猪人氏族，加兹罗格的职责永远做不完。他经常协调对公路抢劫的回应——例如找回被盗的部落货物——并追踪像步兵多格兰这样失踪的士兵，后者最终成为了刺背野猪人手中受伤的俘虏。"}},faq={{q="在哪里可以找到加兹罗格？",a="加兹罗格位于十字路口，这是连接贫瘠之地北部、南部和东部路线的中心定居点。",al={"加兹罗格位置","加兹罗格在哪里","加兹罗格十字路口"}},{q="加兹罗格在部落中扮演什么角色？",a="他担任十字路口的行动协调员和守卫，分派任务以保障地区补给线安全、追回被拦截的货物，并定位失踪的部落人员。",al={"加兹罗格的工作","加兹罗格是谁","加兹罗格做什么"}},{q="加兹罗格提到的被偷走的银币发生了什么？",a="部落的运金车队经常成为聪明的萨拉瓦迅猛龙和在贫瘠之地小径上游荡的投机分子的目标，这促使加兹罗格派遣勇士去猎杀这些野兽并找回货物。",al={"被偷走的银币任务","谁偷了银币","贫瘠之地被盗的货物"}},{q="多格兰是谁？",a="多格兰是一位部落步兵，他被派驻到十字路口与加兹罗格共事。他执行任务后就再也没回来：加兹罗格听说他还活着，但受了伤，被刺背野猪人关押为俘虏，这个消息他宁愿瞒着多格兰的伴侣赞卡沙。",al={"多格兰的消息","多格兰在哪里","加兹罗格多格兰"}},{q="加兹罗格与棘齿城或地精有联系吗？",a="没有。加兹罗格直接在十字路口为部落服务，维护着兽人、牛头人和巨魔在贫瘠之地中部地区的利益安全。",al={"加兹罗格与棘齿城","加兹罗格阵营","加兹罗格地精"}},{q="为什么迅猛龙会在贫瘠之地偷窃补给品？",a="没人能完全确定。迅猛龙把被偷走的银币藏在了棘齿城南部的迅猛龙巢穴中，加兹罗格想知道，关于它们拥有智慧的传闻是否比他想象的更为真实。",al={"迅猛龙小偷原因","迅猛龙偷东西吗","迅猛龙闪亮物品"}}},fx={fdfa6042={q="加兹罗格想要什么？",a="加兹罗格力图为部落确保关键补给，并维持贫瘠之地各处的秩序。他派冒险者追回被当地迅猛龙盗走的银矿货物，同时也在打探失踪的同伴多格兰的下落。",al={"加兹罗格想要什么","加兹罗格需要什么","加兹罗格的目标"}},d6aec43d={q="加兹罗格为什么在十字路口？",a="加兹罗格驻守在十字路口这个战略据点，负责监督对部落在卡利姆多中部立足至关重要的行动。他在这里处理不断袭击商队的当地威胁，追查失踪的部落斥候，并追回对据点防御至关重要的被盗资源。",al={"加兹罗格为何在这里","加兹罗格在十字路口的职责","加兹罗格为何在贫瘠之地"}}},fp="6,258,28.475.0,16.329.0,26.129.0,41.187.0,53.196.0,14.237.0,49.145.0,49.211.0"}
P.entries["npc:gelbin-mekkatorque"] = {n="Gelbin Mekkatorque",s="Gelbin Mekkatorque是大工匠，也是侏儒的领袖，目前流亡在铁炉堡的Tinker Town。他是一位富有远见的工程师，以发明机械陆行鸟和矿道地铁而闻名。现在，他背负着诺莫瑞根陷落的沉重负担，指挥着收复他人民祖居之地的行动。",h="Gelbin Mekkatorque是大工匠，也是侏儒的领袖，目前流亡在铁炉堡的Tinker...",kw={"矿道地铁","gelbin","侏儒","诺莫瑞根","大工匠","铁炉堡","机械陆行鸟","mekkatorque","瑟玛普拉格","tinker town"},ang={["profession:Engineering"]="站在大工匠面前，就等于站在了机械陆行鸟的设计者和矿道地铁背后的驱动力面前。他在Tinker Town的工作室代表了科技创新的最前沿。",["race:Gnome"]="Mekkatorque是你们流亡人民的核心。尽管诺莫瑞根因中毒而产生的负罪感始终压在他心头，但他那卓越的才华和解放你们祖居之地的决心，使他在Tinker Town赢得了绝对的忠诚。"},sec={{t="大工匠兼首席发明家",b="侏儒的领导地位是通过智慧和功绩而非血统获得的，Gelbin Mekkatorque之所以能晋升为大工匠，完全是因为他那天才般的发明创造。Mekkatorque发明了第一台功能完备的机械陆行鸟，彻底改变了个人交通方式。他还协助铜须矮人开发了他们强大的攻城武器，并在连接铁炉堡和暴风城的矿道地铁的建设中发挥了核心作用。"},{t="铁炉堡的背叛与流亡",b="当石腭怪从深处入侵诺莫瑞根时，Mekkatorque遭遇了他人生中最大的悲剧。在密友兼首席顾问麦克尼尔·瑟玛普拉格的怂恿下，Mekkatorque下令向低层走廊排放放射性废料以消灭入侵者。然而，这些有毒气体不仅杀死了成千上万无辜的侏儒，还使幸存者发生了变异，而瑟玛普拉格则趁机夺取了这座沦陷的城市。虽然背负着深深的负罪感，但为了纠正自己的错误，Mekkatorque带领幸存的难民穿越丹莫罗前往铁炉堡。在国王麦格尼·铜须的收留下，大工匠在Tinker Town开展工作，指挥着侏儒的军事和科研力量，专注于一个坚定不移的目标：解放诺莫瑞根。"}},faq={{q="Gelbin Mekkatorque是谁？",a="Gelbin Mekkatorque是经过推选的大工匠，也是侏儒的领袖。他是一位工程学大师，设计了许多关键的侏儒科技，包括机械陆行鸟和矿道地铁。",al={"大工匠","侏儒领袖","谁是侏儒之王"}},{q="为什么Mekkatorque在铁炉堡而不是诺莫瑞根？",a="诺莫瑞根被野蛮的石腭怪大军占领，随后又发生了灾难性的放射性泄漏。Mekkatorque带领他的人民穿越丹莫罗撤离到铁炉堡，国王麦格尼·铜须在Tinker Town为他们提供了避难所，同时他们也在计划夺回城市。",al={"为什么mekkatorque在铁炉堡","为什么侏儒在铁炉堡","诺莫瑞根的陷落"}},{q="是什么导致了诺莫瑞根的灾难？",a="面对源源不断的石腭怪大军，在一位信任的顾问的劝说下，Mekkatorque下令向底层舱室排放有毒的放射性冷却剂以阻挡这些野兽。可悲的是，这些气体没能阻挡石腭怪，反而让整座城市遭受了辐射，导致数千名侏儒死亡。",al={"诺莫瑞根发生了什么","为什么诺莫瑞根会有辐射","瑟玛普拉格的背叛"}},{q="Mekkatorque在成为大工匠之前发明了什么？",a="Mekkatorque发明了机械陆行鸟，让侏儒拥有了属于自己的敏捷坐骑。他还协助开发了矮人的攻城武器，并在连接铁炉堡和暴风城的矿道地铁的建设中发挥了关键作用。",al={"mekkatorque的发明","gelbin建造了什么"}},{q="Mekkatorque是真正的国王吗？",a="侏儒没有世袭君主制；他们的领袖是经过推选的大工匠，由功绩和智力成就决定。他的头衔和权力来源于他作为大工匠的当选。",al={"mekkatorque是国王吗","侏儒之王"}}},fx={db25d752={q="Gelbin Mekkatorque效忠哪一方？",a="Gelbin Mekkatorque坚定地站在联盟一方。作为侏儒的领袖，他与国王麦格尼·铜须及铁炉堡的矮人保持着牢不可破的情谊；正是他们敞开城门，收留了流离失所的侏儒同胞。Mekkatorque承诺以侏儒的工程技术、智慧和军事资源，援助艾泽拉斯各地的联盟盟友。",al={"mekkatorque的阵营","gelbin是否效忠联盟","mekkatorque效忠谁"}},["0e3721be"]={q="Gelbin Mekkatorque想要什么？",a="Mekkatorque唯一的目标就是收复诺莫瑞根。家园沦陷、无数侏儒惨遭杀害，这些沉重的悲痛驱使他寻找办法，清除穴居人和污染大厅的辐射。从 Tinker Town 出发，他安排侦察行动并组织突击队，为夺回城市做好准备。",al={"mekkatorque的目标","gelbin想做什么","gelbin的计划"}},["39ae11c6"]={q="Gelbin Mekkatorque与谁有联系？",a="Mekkatorque与他在铁炉堡的热情东道主国王麦格尼·铜须密切合作，也与暴风城的联盟领袖协调行动。在个人层面上，诺莫瑞根的沦陷，以及他听从一位受信任顾问的建议、下令释放辐射后死去的数千名侏儒，一直令他难以释怀。",al={"mekkatorque的盟友","gelbin的人际关系","mekkatorque与谁合作"}},["5cf35b41"]={q="Gelbin Mekkatorque为何出名？",a="Mekkatorque在艾泽拉斯享有盛名，被誉为历史上最伟大的工程天才之一。他发明了第一台能够正常运作的机械陆行鸟，协助设计了矮人的攻城器械，还对连接铁炉堡与暴风城的矿道地铁的建造起到了关键作用。",al={"mekkatorque为何出名","gelbin以什么闻名","mekkatorque的发明"}}},fp="18,326,35.467.0,31.710.1,26.189.0,54.282.0,42.264.0,56.208.0,30.191.0"}
P.entries["npc:gelihast"] = {n="格里哈斯特",s="格里哈斯特是一位凶残的鱼人首领，手持双刃，栖身于黑暗深渊中的Pool of Ask'ar。在盲光鱼人的簇拥下，他守卫着沉没的神庙中被淹没的废墟里的一座奇异祭坛。",h="格里哈斯特是一位凶残的鱼人首领，手持双刃，栖身于黑暗深渊中的Pool of Ask'ar。在盲光鱼人的簇拥下，他守卫着沉没的神庙中被淹没的废墟里的一座奇异祭坛。",kw={"黑暗深渊","盲光","格里哈斯特","鱼人","pool of ask'ar","暮光之锤"},ang={["class:Warrior"]="格里哈斯特的剑速快如闪电；技巧高超的战士如果能稳住阵脚，就能将他疯狂的双持猛攻完全化解并反制。",["faction:Alliance"]="对于寻求净化灰谷腐蚀蔓延的联盟部队来说，除掉格里哈斯特对于确保沉没神庙北侧通道的安全至关重要。",["faction:Horde"]="被派遣去清理黑暗深渊的部落冒险者必须消灭格里哈斯特，才能扫清通往佐拉姆海岸下方沉没神庙更深处的道路。"},sec={{t="致命的召唤",b="大多数鱼人都会待在海岸浅滩附近，但格里哈斯特却占据了佐拉姆海岸之下黑暗深渊沉没神庙深处的一处巢穴。他挥舞双剑的速度极快，能在闯入者反应过来之前将其斩杀，而误入他攻击范围的施法者几乎无法幸存。"},{t="盲光之主",b="格里哈斯特统治着Pool of Ask'ar，身边簇拥着他的盲光族群，一旦遇到麻烦，它们就会蜂拥而至。他的巢穴后方伫立着一座祭坛；击败他并触碰祭坛的人将获得黑暗深渊的祝福。"}},faq={{q="格里哈斯特是谁？",a="格里哈斯特是一位邪恶的鱼人首领，统领着黑暗深渊中Pool of Ask'ar内的盲光部落。他以速度惊人的双刃进行战斗。",al={"格里哈斯特是谁","格里哈斯特背景故事","格里哈斯特背景"}},{q="为什么格里哈斯特会在黑暗深渊中？",a="没人知道是什么吸引他来到这里。他和他的盲光鱼人占据了淹没废墟中的Pool of Ask'ar，并极其凶残地抵御着所有入侵者。",al={"为什么黑暗深渊里有鱼人","为什么格里哈斯特在神庙里"}},{q="暮光之锤对他有什么反应？",a="关于格里哈斯特与神庙深处暮光之锤邪教徒之间的往来没有任何记录。他与他的盲光鱼人统治着属于自己的水池。",al={"格里哈斯特与暮光之锤","邪教徒喜欢格里哈斯特吗"}},{q="格里哈斯特身后的祭坛是什么？",a="他的水池后方伫立着一座祭坛。击败他的旅行者可以触碰它来获得黑暗深渊的祝福。",al={"深渊祭坛","格里哈斯特祭坛","黑暗深渊祝福祭坛"}},{q="他领导的是哪个鱼人部落？",a="他领导的是盲光鱼人，这是一个极具侵略性的部落，盘踞在洞穴内的Pool of Ask'ar中。",al={"格里哈斯特部落","黑暗深渊里有哪些鱼人"}},{q="如果放任格里哈斯特不管会发生什么？",a="他和他的盲光鱼人封锁了Pool of Ask'ar，阻挡任何试图深入探索这座沉没神庙的人。",al={"格里哈斯特的结局","谁杀了格里哈斯特"}}},fx={["18aa1a09"]={q="格里哈斯特想要什么？",a="格里哈斯特想要守住 Pool of Ask'ar。盲光鱼人围绕在他身边，他会残暴地砍杀任何闯入沉没神庙水域的人。",al={"格里哈斯特的目标","格里哈斯特想要什么","格里哈斯特的动机"}}},fp="8,225,16.288.0,24.226.0,16.166.0,41.173.0,43.156.0,34.110.0,35.104.0,49.120.0"}
P.entries["npc:gelkak-gyromast"] = {n="基尔卡克·旋杆",s="基尔卡克·旋杆是一位说话像海盗船长的侏儒，他被困在黑海岸北部的薄雾海那雾气缭绕的海岸线上。他的船在近海被鞭笞者击沉了，他想要修好他的机械大副：鞭笞终结者4100型。",h="基尔卡克·旋杆是一位说话像海盗船长的侏儒，他被困在黑海岸北部的薄雾海那雾气缭绕的海岸线上。他的船在近海被鞭笞者击沉了，他想要修好他的机械大副：鞭笞终结者4100型。",kw={"黑海岸","基尔卡克·旋杆","侏儒发明家","玛塞斯特拉","薄雾海","鞭笞终结者4100型"},ang={["profession:Engineering"]="基尔卡克的困境是一个典型的侏儒远离家乡的故事，他把复仇的希望寄托在鞭笞终结者4100型这样令人印象深刻的装置上。",["race:Gnome"]="看到一位同胞侏儒被困在卡利姆多的边缘，这让人深刻地意识到侏儒的冒险旅程会让他们离家有多远。"},sec={{t="流落薄雾海",b="基尔卡克·旋杆栖身于黑海岸荒凉的北海岸，就在古老的玛塞斯特拉废墟以西，在阴沉的暗夜精灵海岸线中显得格格不入。这位自封为船长的侏儒说话像个老海员，他的船在近海被鞭笞者击沉了。当他被冲上薄雾弥漫的沙滩时，他机械大副“鞭笞终结者4100型”的钥匙在岩石上摔断了，碎片被在残骸中翻找的爬行者、林精和鱼人叼走了。"},{t="鞭笞终结者故障",b="一旦冒险者找回了钥匙，旋杆就会派他们去启动他的大副并将其带回，迫不及待地想让它去对付海岸上的鱼人和野兽。鞭笞终结者4100型会顺从地跟随，但一到达船长身边就会发生故障并变得敌对，迫使冒险者不得不摧毁它。"}},faq={{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆是一位古怪的侏儒，他说话像个海盗船长，被困在黑海岸北部的海滩上（那里被称为薄雾海），位于玛塞斯特拉废墟以西。",al={"基尔卡克","基尔卡克是谁","旋杆"}},{q="为什么基尔卡克会被困在黑海岸？",a="他的船在近海被鞭笞者击沉了，他被冲到了荒凉的北海岸，随身还带着一把摔断的机械大副钥匙。",al={"为什么基尔卡克会在这里","基尔卡克黑海岸"}},{q="鞭笞终结者4100型是什么？",a="鞭笞终结者4100型是基尔卡克发明的机械装置，自封为他的大副。他希望能修好它，这样它就能向海岸上的鱼人和野兽复仇了。",al={"鞭笞终结者","基尔卡克机器","机器人"}},{q="基尔卡克需要旅行者提供什么帮助？",a="基尔卡克请求能干的冒险者从海岸上的爬行者、林精和鱼人身上找回他断掉的钥匙的三块碎片，然后用它启动鞭笞终结者4100型并将其带回。",al={"基尔卡克任务","旋杆任务"}}},fx={["77810e79"]={q="基尔卡克·旋杆效忠哪一方？",a="基尔卡克是效忠联盟的侏儒，不过在黑海岸这片偏僻的海岸上，他只为自己行事。他被困在远离任何大型聚居地的地方，欢迎任何愿意帮忙解决他的机械故障、对联盟友好的旅行者。",al={"基尔卡克·旋杆的阵营","基尔卡克是否效忠联盟","基尔卡克效忠谁"}}},fp="15,271,23.509.0,32.325.1,23.173.0,36.145.0,34.186.0,42.209.0"}
P.entries["npc:general-marcus-jonathan"] = {n="马库斯·乔纳森将军",s="马库斯·乔纳森将军是暴风城防卫部队的最高指挥官，驻扎在英雄谷的大门处。作为第二次战争的退伍军人，他负责统领保护首都的守军，并处理王国边境定居点的军事请求。",h="马库斯·乔纳森将军是暴风城防卫部队的最高指挥官，驻扎在英雄谷的大门处。作为第二次战争的退伍军人，他负责统领保护首都的守军，并处理王国边境定居点的军事请求。",kw={"乔纳森将军","湖畔镇","所罗门镇长","马库斯·乔纳森","雷吉纳德·温德索尔","暴风城军队","暴风城防卫部队","英雄谷"},ang={["class:Warrior"]="作为暴风城大门的最高指挥官和第二次战争的退伍老兵，乔纳森代表了王国步兵队伍中标准的军事职责的巅峰。",["faction:Alliance"]="马库斯·乔纳森体现了暴风城在首都大门处的尚武精神。"},sec={{t="城门指挥官",b="马库斯·乔纳森将军骑在战马上，驻守在英雄谷，他是负责监管城市大门的第一道防线，也是最高级别的军事长官。他曾在图拉扬将军的指挥下，与雷吉纳德·温德索尔等著名将领并肩作战，参与了第二次战争。在这个局势日益紧张的时代，乔纳森必须在首都的即时安全与湖畔镇等边境城镇日益迫切的求援需求之间寻找平衡。"},{t="紧绷的指挥权",b="虽然像湖畔镇这样的城镇恳求暴风城派遣士兵击退黑石兽人和豺狼人，乔纳森向当地治安官保证他会尽力提供援助，但他私下里却感到王室变得疏远，而且摄政王幼王的行为也十分怪异。"}},faq={{q="我在哪里可以找到马库斯·乔纳森将军？",a="他骑马驻扎在暴风城正门内，俯瞰着英雄谷的入口大桥。",al={"马库斯·乔纳森位置","乔纳森将军在哪里","暴风城城门指挥官"}},{q="马库斯·乔纳森的军事履历是什么？",a="马库斯·乔纳森是一位老兵，曾在第二次战争期间在图拉扬将军麾下服役。他曾与雷吉纳德·温德索尔等战友并肩作战，最终晋升为暴风城防卫部队的最高指挥官。",al={"马库斯·乔纳森过去","马库斯·乔纳森背景故事","马库斯参加过第二次战争吗"}}},fx={d649e9ed={q="马库斯·乔纳森将军是谁？",a="马库斯·乔纳森将军是暴风城防卫军的最高指挥官。他是一位经验丰富的老兵，曾在第二次战争期间效力于图拉扬将军麾下，如今负责统领守卫首都及周边领土的军队。",al={"马库斯·乔纳森是谁","马库斯·乔纳森的身份","乔纳森将军是谁"}},["59fdae30"]={q="马库斯·乔纳森将军效忠哪一方？",a="他全心效忠暴风王国和大联盟。他以绝对认真的态度履行保卫王国、保护民众的职责，直接听命于王室和暴风城的高层领袖。",al={"马库斯·乔纳森的效忠对象","马库斯·乔纳森效忠谁","马库斯·乔纳森的阵营"}},["5549e5c1"]={q="马库斯·乔纳森将军想要什么？",a="乔纳森希望守护暴风城，并确保湖畔镇等外围定居点得到迫切需要的军事支援。然而，瓦里安·乌瑞恩国王失踪，王室宫廷的行事也十分反常，这严重妨碍了他按计划调动军队。",al={"马库斯·乔纳森的目标","马库斯·乔纳森需要什么","马库斯·乔纳森的动机"}},b8230eb1={q="马库斯·乔纳森将军为何与赤脊山有关？",a="湖畔镇的所罗门镇长直接向乔纳森将军请求军事援助，因为他知道乔纳森在暴风城说得上话。作为军队的指挥官，乔纳森有权向王室请求增派援军，保卫赤脊山。",al={"马库斯·乔纳森与赤脊山","马库斯·乔纳森与湖畔镇","为什么要给马库斯·乔纳森传信"}},ab66a8e6={q="马库斯·乔纳森将军与谁有联系？",a="他与雷吉纳德·温德索尔元帅交情深厚，第二次战争期间曾在图拉扬将军麾下与他并肩作战。在暴风城，他经常与王室协调，也会回应所罗门镇长等地区领袖的紧急请求。",al={"马库斯·乔纳森的人际关系","谁认识马库斯·乔纳森","马库斯·乔纳森的盟友"}}},fp="23,272,22.465.0,18.256.1,41.132.0,43.215.0"}
P.entries["npc:gerard-tiller"] = {n="葛拉德·提勒",s="葛拉德·提勒是一位口渴的人类农夫，在艾尔文森林的马科伦农场谷仓外工作。在温暖的阳光下照料葡萄园时，他总是很乐意用一颗爽脆的新鲜的红苹果，来交换任何旅行者愿意提供的清凉的泉水。",h="葛拉德·提勒是一位口渴的人类农夫，在艾尔文森林的马科伦农场谷仓外工作。在温暖的阳光下照料葡萄园时，他总是很乐意用一颗爽脆的新鲜的红苹果，来交换任何旅行者愿意提供的清凉的泉水。",kw={"艾尔文森林","葛拉德·提勒","给葛拉德水","马科伦农场","清凉的泉水","新鲜的红苹果"},ang={["profession:Cooking"]="葛拉德乐意用新鲜的苹果交换普通的泉水，这使他成为了游历的厨师寻找简单食材时一个便利的水果来源。"},sec={{t="一位口渴的农夫",b="葛拉德·提勒每天都在马科伦农场的田野里劳作，照料谷仓外的土地。该农场位于闪金镇以南，出产艾尔文森林最著名的一些葡萄，但维持丰收是一项艰苦的工作。提勒因为繁重的杂务而总是感到口渴，这使他很乐意与路过的冒险者进行物物交换。如果有人给他一皮袋清凉的泉水，他会很乐意用从当地果园直接采摘的新鲜的红苹果来回报这份善意。"}},faq={{q="谁是葛拉德·提勒？",a="葛拉德·提勒是一位人类农夫，驻守在艾尔文森林南部的马科伦农场谷仓外。",al={"葛拉德·提勒身份","葛拉德是谁","提勒 艾尔文"}},{q="我在哪里可以找到葛拉德·提勒？",a="他站在马科伦农场的大木谷仓外，该农场位于闪金镇以南，斯通菲尔德农场以东。",al={"葛拉德·提勒位置","葛拉德在哪里","艾尔文森林 葛拉德"}},{q="葛拉德·提勒交易什么？",a="葛拉德会用一颗新鲜的红苹果来换取任何旅行者带来的清凉的泉水，以解他的口渴。",al={"葛拉德 苹果交易","葛拉德·提勒 泉水","葛拉德想要什么"}},{q="葛拉德会卷入马科伦和斯通菲尔德的世仇吗？",a="不会。虽然他在马科伦农场工作，但葛拉德专注于自己的杂务和补充水分，而不是去插手马科伦家族和斯通菲尔德家族之间的世仇。",al={"葛拉德·提勒 世仇","马科伦世仇 葛拉德"}}},fp="13,165,18.354.0,21.108.0,31.112.0,30.70.0,60.148.0"}
P.entries["npc:gerrig-bonegrip"] = {n="葛利·硬骨",s="葛利·硬骨是一位不起眼的矮人店主，隐居在铁炉堡Forlorn Cavern的阴暗走廊中。在他的“硬骨符文与厄运”商店柜台后，他悄悄地买卖着关于黑暗仪式和被遗忘的远古力量的深奥文献。",h="葛利·硬骨是一位不起眼的矮人店主，隐居在铁炉堡Forlorn Cavern的阴暗走廊中。在他的“硬骨符文与厄运”商店柜台后，他悄悄地买卖着关于黑暗仪式和被遗忘的远古力量的深奥文献。",kw={"黑暗深渊","硬骨","forlorn cavern","葛利","铁炉堡","洛迦里斯手稿","硬骨符文与厄运"},ang={["class:Warlock"]="对于经常出没于Forlorn Cavern阴暗角落的术士来说，硬骨所收藏的深奥仪式和黑暗典籍提供了一个获取危险知识的便捷源泉。",["race:Dwarf"]="对于矮人访客来说，硬骨对禁忌知识的交易为铁炉堡的学术生活投下了一层令人不安的阴影。"},sec={{t="硬骨符文与厄运",b="葛利·硬骨在Forlorn Cavern阴暗的角落里经营着生意，在大多数市民眼中，他只是个贩卖奇奇怪怪的遗物和禁忌知识的古怪商人。然而，他那简陋的商店有着极其黑暗的用途。硬骨是虚无主义教派“暮光之锤”的活跃成员，他利用自己的店铺在铁炉堡议会和High Seat的眼皮底下搜集关于上古之神的危险手稿和晦涩文献。"},{t="搜集禁忌知识",b="葛利积极招募不知情的联盟冒险者去取回远古神器，例如丢失在黑暗深渊深处的洛迦里斯手稿。一旦这些遗物落入他手中，他就会抄写这些亵渎知识，并直接传播给艾泽拉斯各地的邪教同伙。通过与斯奎尔图等阴暗同伙，以及与迈兹拉尔等远古原生实体打交道的人物的微妙联系，硬骨不遗余力地推动着该教派的末日计划。"}},faq={{q="葛利·硬骨是谁？",a="葛利·硬骨是一名在铁炉堡Forlorn Cavern经营“硬骨符文与厄运”的矮人。他从事与远古仪式相关的古怪珍品和晦涩文献的交易。",al={"葛利·硬骨是谁","葛利·硬骨背景故事","铁炉堡的硬骨"}},{q="他用洛迦里斯手稿做什么？",a="他从黑暗深渊中寻找洛迦里斯手稿，以扩充他的珍稀文献收藏。进一步调查可以揭示更多关于他如何使用这些手稿的信息。",al={"硬骨为什么需要洛迦里斯手稿","深渊中的知识任务提交","洛迦里斯手稿的用途"}},{q="葛利如何在铁炉堡开展活动？",a="葛利在Forlorn Cavern以古怪学者和商人的身份保持低调，在那里买卖晦涩的文献。",al={"铁炉堡知道硬骨是邪教徒吗","为什么硬骨被允许留在铁炉堡"}},{q="他与迈兹拉尔有什么联系？",a="葛利是矮人斯奎尔图的老相识，斯奎尔图负责调查阿拉希高地中被封印的土元素迈兹拉尔。通过这些联系，葛利协助策划与远古束缚仪式和原生力量有关的任务。",al={"葛利·硬骨与迈兹拉尔","斯奎尔图与葛利"}}},fx={ec528c98={q="葛利·硬骨站在哪一方？",a="葛利是来自铁炉堡的矮人，在Forlorn Cavern经营硬骨符文与厄运店。他交易有关仪式和古代力量的晦涩知识，并警告访客，他掌握的某些知识并非初学者所能涉足。",al={"葛利·硬骨所属阵营","葛利为谁工作","葛利·硬骨是邪恶的吗"}},f2a99842={q="葛利·硬骨为什么在铁炉堡？",a="葛利在铁炉堡幽暗的Forlorn Cavern开店，收集、购买和出售稀有手稿、符文以及有关仪式的古老知识。他会付钱请冒险者从黑暗深渊等地找回洛迦里斯手稿之类的文本。",al={"葛利为什么在铁炉堡","葛利·硬骨在这里做什么","葛利·硬骨为什么在forlorn cavern"}}},fp="15,264,26.449.1,30.487.1,23.172.2,45.149.1,37.129.2,34.238.0"}
P.entries["npc:gershala-nightwhisper"] = {n="戈沙拉·夜语",s="戈沙拉·夜语是一位定居在黑海岸沿海城镇奥伯丁的暗夜精灵研究员。出于对奎尔萨拉斯高等精灵所走道路的严重担忧，他开始研究被诅咒的水生生物和恶魔生物的样本，以了解魔法腐蚀如何扭曲身心。",h="戈沙拉·夜语是一位定居在黑海岸沿海城镇奥伯丁的暗夜精灵研究员。出于对奎尔萨拉斯高等精灵所走道路的严重担忧，他开始研究被诅咒的水生生物和恶魔生物的样本，以了解魔法腐蚀如何扭曲身心。",kw={"奥伯丁","黑暗深渊","腐蚀","黑海岸","戈沙拉","娜迦","夜语","萨特"},ang={["faction:Alliance"]="戈沙拉是派遣联盟远征队前往黑暗深渊险境的主要赞助人，以确保他们的入侵能获得宝贵的奥术知识。",["race:NightElf"]="对于暗夜精灵来说，戈沙拉冷峻的调查是对古老的大分裂和魔法成瘾所带来的惨痛代价的深刻提醒，正是这种代价曾将他们的同胞重塑为恐怖的存在。"},sec={{t="转化的研究",b="戈沙拉·夜语平静地驻扎在奥伯丁，他的目光越过了黑海岸眼前的沿海困境，投向了更广阔、更阴险的威胁。在惊恐地注视着幸存的高等精灵拥抱危险的奥术实践并自称为血精灵时，戈沙拉试图了解这种不受限制的魔法所导致的生物学和精神上的堕落。为了解开这些秘密，他指引经验丰富的联盟冒险者前往淹没在水下的黑暗深渊大厅，从居住在其中的娜迦和萨特身上收集被腐蚀的脑干。"},{t="毁灭的解药",b="戈沙拉对娜迦和萨特脑干的冷峻关注源于它们共同的血统：这两个种族曾经都是暗夜精灵，后来屈服于艾萨拉女王和恶魔的契约。通过解剖千年来的恶魔和深渊能量在它们神经系统上留下的物理痕迹，他希望揭示出警告或防护措施，以防止其他精灵同胞陷入类似的怪物畸变。"}},faq={{q="在哪里可以找到戈沙拉·夜语？",a="戈沙拉·夜语可以在黑海岸沿岸的联盟主要港口城镇奥伯丁找到。",al={"戈沙拉位置","戈沙拉在哪里","寻找戈沙拉·夜语"}},{q="戈沙拉为什么要收集娜迦和萨特的脑干？",a="戈沙拉研究被腐蚀的脑干是为了检查深层的魔法和恶魔转化如何改变了曾经的暗夜精灵的解剖结构。娜迦和萨特曾经都是精灵，他旨在了解其腐化背后的物理机制。",al={"为什么需要脑干","腐蚀传说研究","戈沙拉研究什么"}},{q="戈沙拉希望通过他的研究达成什么目标？",a="戈沙拉希望他的研究能提供关键的见解，以防止血精灵因过度依赖邪能和不受限制的奥术力量而堕落为邪恶的怪物。",al={"戈沙拉的目标","为什么要帮助血精灵","戈沙拉研究的目的"}},{q="戈沙拉需要的样本在哪里？",a="他指引冒险者前往黑暗深渊，那是一座位于灰谷海岸的古老水下神庙遗迹，里面盘踞着娜迦和萨特。",al={"脑干在哪里","黑暗深渊脑干","去哪里找戈沙拉的物品"}}},fx={["19945428"]={q="戈沙拉·夜语是谁？",a="戈沙拉·夜语是一位暗夜精灵学者，居住在黑海岸的沿海聚居地奥伯丁。出于学术好奇和对广阔世界的关切，他致力于了解魔法与生物受到的腐化。他研究被黑暗力量扭曲的生物变异后的形态，希望通过细致研究，避免其他族群遭遇类似的厄运。",al={"戈沙拉是谁","戈沙拉·夜语的背景故事","戈沙拉的背景"}},["087b63f5"]={q="戈沙拉·夜语站在哪一方？",a="戈沙拉与达纳苏斯的暗夜精灵结盟，也是联盟成员的友善学者。他在奥伯丁开展研究，致力于保护卡利姆多和更广泛的凡人种族，抵御恶魔与魔法侵蚀带来的威胁。",al={"戈沙拉所属阵营","戈沙拉属于联盟吗","戈沙拉的效忠对象"}},aee12c2d={q="戈沙拉·夜语为什么在这里？",a="戈沙拉定居奥伯丁，是因为黑海岸紧邻黑暗深渊等深受古老邪恶侵染之地。从这处海岸避风港出发，他可以招募南下的旅人和冒险者，为持续进行的研究收集受到腐化的样本。",al={"戈沙拉为什么在奥伯丁","戈沙拉在黑海岸的目的"}}},fp="21,311,23.550.0,19.411.0,37.111.0,50.251.0,56.201.0,47.138.0"}
P.entries["npc:ghamoo-ra-classic"] = {n="加摩拉",s="加摩拉是一只古老的巨型海龟，栖息在黑暗深渊内的Pool of Ask'ar，这座沉没的艾露恩神庙如今已被暮光之锤教派所占据。它披着坚硬的厚甲，残暴地践踏着任何靠近其岛屿的入侵者。",h="加摩拉是一只古老的巨型海龟，栖息在黑暗深渊内的Pool of Ask'ar，这座沉没的艾露恩神庙如今已被暮光之锤教派所占据。它披着坚硬的厚甲，残暴地践踏着任何靠近其岛屿的入侵者。",kw={"黑暗深渊","艾露恩","加摩拉","pool of ask'ar","驯服","海龟","暮光之锤"},ang={["class:Druid"]="德鲁伊在加摩拉身上看到了一种深渊中的古老生物，在被亵渎的神庙废墟中变得狂暴。",["class:Hunter"]="深入黑暗深渊的猎人或许会同情加摩拉这只高贵、古老的深渊野兽，不过耐心的猎人仍然可以将其驯服。",["race:NightElf"]="对于暗夜精灵来说，加摩拉在艾露恩沉没神庙中的狂暴存在，痛苦地提醒着这处圣地在邪恶的暮光之锤手中堕落到了何种地步。"},sec={{t="沉没神庙中的野兽",b="黑暗深渊曾是一座供奉艾露恩的暗夜精灵神庙，如今已被洪水淹没，并被纳迦、萨特和虚无主义的暮光之锤教派所占领。加摩拉栖息在这些被淹没的废墟中，这只巨大的海龟拥有厚重的外壳，能抵挡住除最猛烈攻击之外的所有伤害。"},{t="深渊守护者",b="加摩拉在Pool of Ask'ar的一座小岛上徘徊，周围环绕着对旅行者不加理会的普通海龟。唯有它会发起攻击，将任何靠近的生物践踏在它沉重的躯体之下。"}},faq={{q="谁是加摩拉？",a="加摩拉是一只巨型海龟，位于黑暗深渊内的Pool of Ask'ar，这座被洪水淹没的艾露恩神庙如今已被暮光之锤控制。它会攻击任何靠近其岛屿的人。",al={"加摩拉背景故事","黑暗深渊巨型海龟","谁是加摩拉"}},{q="为什么加摩拉对外来者充满敌意？",a="没有记录显示它是如何变得如此狂暴的。它只是会攻击任何闯入其Pool of Ask'ar岛屿的人，践踏所有靠近的生物。",al={"为什么海龟很愤怒","为什么海龟会攻击","加摩拉疯狂"}},{q="猎人可以驯服加摩拉吗？",a="可以。尽管体型庞大且经历了多年的折磨，但经验丰富的猎人依然可以驯服加摩拉。",al={"驯服加摩拉","猎人能驯服黑暗深渊海龟吗"}},{q="Pool of Ask'ar是什么？",a="Pool of Ask'ar是黑暗深渊内的一处被淹没的地下洞穴。加摩拉在其中一座小岛的中心游荡，周围环绕着温顺的本土海龟。",al={"pool of ask'ar","加摩拉在哪里"}},{q="它与上古之神有什么联系吗？",a="没有任何记录。加摩拉只是深渊中的一只野兽，尽管崇拜上古之神的暮光之锤教徒已经占领了它周围这座沉没的神庙。",al={"加摩拉与上古之神","海龟被腐化了吗"}}},fx={["650cf597"]={q="加摩拉站在哪一方？",a="加摩拉不为任何人效力。他是深海中的凶猛野兽，会攻击任何接近Ask'ar水池中那座岛屿的人；那座岛位于被暮光之锤占据的淹没神殿内。",al={"加摩拉所属阵营","加摩拉为谁效力","加摩拉属于暮光之锤吗"}},ff96574e={q="加摩拉想要什么？",a="加摩拉没有什么远大企图。这只巨龟只是会猛烈攻击靠近Ask'ar水池中那座岛屿的入侵者，将他们碾碎。",al={"加摩拉的目标","这只乌龟想要什么","加摩拉的动机"}},f3d3c23f={q="加摩拉为什么在这里？",a="加摩拉栖居在Ask'ar水池中的一座小岛上，位于黑暗深渊深处。这里曾是伊露恩的淹没神殿，如今已被娜迦、萨特和暮光之锤占据。关于它如何来到这里，并无记载。",al={"加摩拉为什么在黑暗深渊","加摩拉在ask'ar水池的原因","这里为什么有一只巨龟"}}},fp="9,255,29.275.0,21.180.0,17.189.0,38.155.0,28.87.0,27.161.0,45.157.0"}
P.entries["npc:gilnid"] = {n="基尔尼格",s="被称为“熔炉之主”的基尔尼格是一位地精总工程师，负责管理死亡矿井深处的熔炉。他监督着将矿石冶炼成精炼金属与军火的过程，以此为艾德温·范克里夫那艘隐藏的铁甲战舰提供支持。如果没有他的那些炽热的熔炼作业，迪菲亚潜行者们将无法获得突袭暴风城所必需的重型火炮。",h="被称为“熔炉之主”的基尔尼格是一位地精总工程师，负责管理死亡矿井深处的熔炉。他监督着将矿石冶炼成精炼金属与军火的过程，以此为艾德温·范克里夫那艘隐藏的铁甲战舰提供支持。如果没有他的那些炽热的熔炼作业，迪菲亚潜行者们将无法...",kw={"火炮","死亡矿井","迪菲亚","熔炉","铸造厂","基尔尼格","地精","战舰","熔炼师","范克里夫"},ang={["faction:Alliance"]="阻止基尔尼格将切断迪菲亚的武器装配线，从而防止范克里夫的战舰在威胁暴风城港口之前完成全面武装。",["profession:Engineering"]="基尔尼格的铸造厂是地精重工业的典型代表，在极端条件下源源不断地生产着标准化的海军火炮、弹药和结构装甲。",["profession:Mining"]="基尔尼格工作室中巨大的高炉和熔炼罐展示了迪菲亚潜行者是如何将西部荒野的原始矿产财富转化为精炼铁矿和军火的。"},sec={{t="熔炉之主",b="在死亡矿井深处，迪菲亚潜行者依靠工业技术来锻造战争武器。基尔尼格担任范克里夫的首席熔炼师，在中央铸造厂指挥着一支由地精劳工、技工和铁匠组成的小型军队。他比大多数同族都要高大，在烟雾和矿渣中无情地驱使着他的团队，大声呵斥并拒绝让他们休息，以确保铁矿石能被加工成重型装甲和致命的弹药。"},{t="武装战舰",b="这些冶炼工程对于迪菲亚潜行者的宏大野心至关重要。基尔尼格直接负责锻造那些重型火炮和弹药，这些武器旨在装备那艘停靠在他工作室后方地下海湾中的巨型铁甲战舰。除非他的铸造厂能生产出所有的火炮、炮管和炮弹，否则这艘迪菲亚战舰将无法准备好执行其对暴风城的既定袭击计划。"}},faq={{q="基尔尼格是谁？",a="基尔尼格是一位地精工程师，也是艾德温·范克里夫在死亡矿井中的首席熔炼师。他负责监督迪菲亚潜行者的熔炉，并领导工业生产，为他们的战争机器铸造火炮和弹药。",al={"基尔尼格 死亡矿井","谁是基尔尼格","熔炉之主"}},{q="为什么基尔尼格会在死亡矿井里？",a="迪菲亚潜行者雇佣了雇佣兵性质的地精工程师来建造并补给他们隐藏的战舰。基尔尼格被委以冶炼工作的重任，将开采出的铁矿石转化成精炼的零件、装甲和火炮。",al={"为什么地精在死亡矿井","基尔尼格 迪菲亚背景","基尔尼格在做什么"}},{q="基尔尼格正在制造什么？",a="基尔尼格负责制造大量的火炮、船只零件和炮弹，这些都是武装藏在矿井深处码头里的战舰所必需的。",al={"基尔尼格 火炮","基尔尼格在制造什么","死亡矿井熔炉目的"}},{q="为什么必须击败基尔尼格？",a="基尔尼格控制着通往海湾的工业铸造厂。在清理熔炼室之前，通往迪菲亚战舰的重型爆破门将一直保持封锁状态。",al={"为什么要杀基尔尼格","基尔尼格身后的门"}},{q="基尔尼格是直接为艾德温·范克里夫工作的吗？",a="是的。他不是最初石匠兄弟会的成员，而是范克里夫直接雇佣的地精专家，负责处理重型冶金和武器生产工作。",al={"范克里夫和基尔尼格","基尔尼格是迪菲亚首领吗"}},{q="为什么他周围有那么多地精？",a="基尔尼格在铸造厂领导着一支专业的地精工程团队。在他的严格监管下，他们操作高炉、浇筑铁水并组装军火，片刻不得停歇。",al={"基尔尼格的地精","死亡矿井熔炉团队"}}},fx={["1c6d7566"]={q="基尔尼格站在哪一方？",a="基尔尼格坚定地效忠于迪菲亚潜行者。地精通常以独立承接雇佣契约、保持中立而闻名，但基尔尼格将自己出众的冶金技艺献给了艾德温·范克里夫的叛乱事业，在兄弟会地下据点深处担任首席监工。",al={"基尔尼格所属阵营","基尔尼格与迪菲亚潜行者","基尔尼格为谁而战"}},["88f08ccf"]={q="基尔尼格想要什么？",a="基尔尼格只希望迪菲亚潜行者这台战争机器得到完善装备并投入运作。作为首席熔炼师，他最关心的是确保每一门火炮、炮身和重型弹药都铸造完美。他毫不留情地驱使手下的地精劳工不停歇地干活，直到巨大战舰准备启航。",al={"基尔尼格的目标","基尔尼格想做什么","基尔尼格的动机"}}},fp="6,339,21.433.0,21.374.1,14.208.0,31.218.0,26.155.0,28.179.0,45.177.0,41.182.0"}
P.entries["npc:gilshalan-windwalker"] = {n="基尔沙兰·风行者",s="基尔沙兰·风行者是一名在幽影谷的巨树奥达希尔底部休息的暗夜精灵研究员。由于泰达希尔内部突然出现的腐蚀令人担忧，他正在研究当地的野生生物，试图了解困扰这些枝叶的非自然攻击性。他对树林蜘蛛的调查为这棵世界之树所遭受的腐坏提供了早期线索。",h="基尔沙兰·风行者是一名在幽影谷的巨树奥达希尔底部休息的暗夜精灵研究员。由于泰达希尔内部突然出现的腐蚀令人担忧，他正在研究当地的野生生物，试图了解困扰这些枝叶的非自然攻击性。他对树林蜘蛛的调查为这棵世界之树所遭受的腐坏提供...",kw={"奥达希尔","基尔沙兰","幽影谷","蜘蛛","特纳隆","毒液","树林蜘蛛","风行者"},ang={["class:Druid"]="他的研究直接支持了塞纳里奥议会试图诊断幽影谷枝叶中滋生的生态失衡所做的努力。",["race:NightElf"]="基尔沙兰代表了你们的人民为理解这棵新种植的世界之树为何已经在产生受感染的、暴力性的野生生物而做的早期努力。"},sec={{t="树根下的学者",b="基尔沙兰·风行者平静地坐在通往奥达希尔的石阶上，带着日益增长的不安注视着幽影谷宁静的树冠。泰达希尔的种植是为了恢复暗夜精灵失去的庇护所和与自然的和谐，但深层精神不安的迹象几乎立刻就显现了出来。基尔沙兰致力于研究这种腐蚀是如何在当地野兽身上体现的，首先从在附近织网的毒蜘蛛开始。"},{t="树林蜘蛛的威胁",b="基尔沙兰的主要研究重点是潜伏在北方黑丝洞中的树林蜘蛛。这些生物曾经是森林生态系统平衡的一部分，现在却变得异常敌对且被玷污了。通过派遣年轻的新手去收集毒囊和完整的树林蜘蛛的卵，基尔沙兰试图分析毒液性质的变化，并辨别这种腐蚀是代代相传的，还是通过泰达希尔的土壤从外部传播的。"},{t="给大德鲁伊的消息",b="手握毒液和一颗卵，基尔沙兰相信蜘蛛的毒液会显示出与新世界之树近期生长相关的特性。他安排将这些样本送往达纳苏斯，他将在那里继续他的研究。他还向有前途的保护者们传话，说特纳隆·雷拳一直在奥达希尔最高的房间里找他们，德鲁伊领袖们正是在那里守护着这棵幼小的世界之树。"}},faq={{q="谁是基尔沙兰·风行者？",a="基尔沙兰·风行者是一名坐在幽影谷的奥达希尔底部的暗夜精灵学者。他正在调查逐渐侵蚀泰达希尔野生生物的神秘腐蚀。",al={"基尔沙兰","谁是基尔沙兰","风行者暗夜精灵"}},{q="为什么基尔沙兰需要树林蜘蛛的毒液？",a="基尔沙兰试图研究毒液的化学和精神特性，以了解森林里的蜘蛛为何变得如此具有攻击性且发生变异。",al={"为什么需要树林蜘蛛毒液","树林蜘蛛毒液任务","蜘蛛毒液基尔沙兰"}},{q="他打算如何处理树林蜘蛛的卵？",a="他想要活体样本进行研究，但长大的巨型蜘蛛太危险，难以捕捉。未孵化的卵运输起来要容易得多，所以他把它和毒液一起送往达纳苏斯，在那里可以将孵出的幼蛛隔离并进行研究。",al={"树林蜘蛛的卵任务","为什么要蜘蛛卵","树林蜘蛛的卵"}},{q="基尔沙兰接下来让冒险者去哪儿？",a="在卵被送走后，他告诉冒险者特纳隆·雷拳一直在找他们，并让他们前往奥达希尔顶部的最高房间。",al={"特纳隆召唤","基尔沙兰之后找谁","树林蜘蛛的卵之后"}},{q="基尔沙兰·风行者位于哪里？",a="他坐在奥达希尔北部的石径上，就在幽影谷中心树木的空心入口外。",al={"基尔沙兰位置","风行者在哪里","找到基尔沙兰"}},{q="为什么泰达希尔的野生生物具有攻击性？",a="一种未知的枯萎病已经开始通过泰达希尔的根部和土壤渗入，腐蚀了生物的思想和天性，引起了像基尔沙兰这样的居民的学术担忧。",al={"为什么蜘蛛发疯","泰达希尔腐蚀","幽影谷受腐蚀的野兽"}}},fx={["4b23360a"]={q="基尔沙兰·风行者站在哪一方？",a="基尔沙兰坚定地支持暗夜精灵同胞和联盟。他驻守在幽影谷奥达希尔的树根处，帮助年轻冒险者了解并对抗影响泰达希尔当地野生生物的奇异腐化力量。",al={"基尔沙兰所属阵营","基尔沙兰为谁效力","基尔沙兰·风行者属于联盟吗"}},["61ec761c"]={q="基尔沙兰·风行者为什么在这里？",a="他坐在奥达希尔的树根处，监视幽影谷新出现的腐化迹象。基尔沙兰研究躁动的林网蜘蛛的毒液样本和未孵化的卵，试图查明是什么破坏了这棵伟大世界之树的自然和谐。",al={"基尔沙兰为什么在幽影谷","基尔沙兰·风行者在奥达希尔的目的"}},ba2e5485={q="基尔沙兰·风行者与谁有关联？",a="基尔沙兰听命于特纳隆·雷拳，他是驻扎在奥达希尔高处枝杈间的长老德鲁伊之一。在完成对林网蜘蛛的初步调查后，他会指引有潜力的新人前去拜见特纳隆，继续协助保卫泰达希尔。",al={"基尔沙兰向谁汇报","基尔沙兰与特纳隆的关系","基尔沙兰的关系"}}},fp="20,370,22.466.0,18.458.0,21.429.1,28.174.0,38.153.0,37.236.0,43.151.0,38.131.0,45.187.0"}
P.entries["npc:gilthares-firebough"] = {n="基尔萨瑞斯·火枝",s="基尔萨瑞斯·火枝是一名精灵水手，被关押在北方城堡的一座塔楼内。他曾效力于塔洛丹私掠者船队，在一艘往返于棘齿城和藏宝海湾的私酒运输船上工作，现在他正寻求一切机会从他的塞拉摩俘虏手中逃脱。",h="基尔萨瑞斯·火枝是一名精灵水手，被关押在北方城堡的一座塔楼内。他曾效力于塔洛丹私掠者船队，在一艘往返于棘齿城和藏宝海湾的私酒运输船上工作，现在他正寻求一切机会从他的塞拉摩俘虏手中逃脱。",kw={"藏宝海湾","从堡垒中逃脱","基尔萨瑞斯·火枝","北方城堡","棘齿城","塔洛丹私掠者"},ang={["faction:Alliance"]="基尔萨瑞斯虽然起初对路人漠不关心，但他对摧毁了他的船并将其关进牢房的联盟水手怀有强烈的敌意。",["faction:Horde"]="将基尔萨瑞斯从北方城堡护送出来，是对塞拉摩在贫瘠之地海岸线上的侵略行径的一次有力打击。"},sec={{t="囚笼中的走私者",b="在往返于棘齿城和藏宝海湾运送非法货物时，基尔萨瑞斯·火枝目睹了他的船被来自塞拉摩的海军力量轰成了碎片。作为袭击中唯一的幸存者，这名私掠者被拖上岸戴上枷锁，关进了北方城堡的一座塔楼里。尽管他身着鲜艳的红色衣服，对那些屠杀了他船员的联盟狂热分子毫无好感，但基尔萨瑞斯并不挑剔是谁来帮他越狱——只要对方能杀出一条路离开城墙即可。"}},faq={{q="谁是基尔萨瑞斯·火枝？",a="基尔萨瑞斯是一名隶属于塔洛丹私掠者的精灵水手。当北方城堡的军队拦截并击沉了他在贫瘠之地海岸附近的商船后，他被俘虏了。",al={"谁是基尔萨瑞斯","基尔萨瑞斯背景故事","这个精灵是谁"}},{q="他为何被囚禁在北方城堡？",a="基尔萨瑞斯当时在一艘运送私酒的运输船上工作，往返于棘齿城和藏宝海湾之间。塞拉摩的士兵击沉了这艘船，杀死了其余船员，并将基尔萨瑞斯作为违禁货物和战俘关押在北方城堡。",al={"他为什么在监狱里","为什么在笼子里","北方城堡囚犯"}},{q="基尔萨瑞斯是高等精灵还是血精灵？",a="基尔萨瑞斯是一名精灵，他是一名独立水手，并不效忠于联盟或银月城的统治者。虽然他红色的装束通常让人联想到辛多雷，但他服务的是私掠者，而非任何国家派系。",al={"基尔萨瑞斯是什么种类的精灵","高等精灵还是血精灵","基尔萨瑞斯种族"}},{q="塔洛丹私掠者是谁？",a="塔洛丹私掠者是一个独立的航海组织，参与了整个无尽之海的走私活动，包括连接棘齿城和藏宝海湾的有利可图的私酒贸易线路。",al={"塔洛丹私掠者","他为谁工作","基尔萨瑞斯的船员"}}},fx={["4d14e07a"]={q="基尔萨瑞斯·火枝站在哪一方？",a="基尔萨瑞斯既不效忠部落，也不效忠联盟。他是一名独立水手，隶属于塔洛丹私掠船队，这支自由航行的船队活动于棘齿城和藏宝海湾之间的贸易航线上。他对部落并无特别好感，但塞拉摩的狂热分子暴力抓捕并残酷奴役了他，使他公开敌视占据北方城堡的联盟势力。",al={"基尔萨瑞斯·火枝所属阵营","基尔萨瑞斯属于部落还是联盟","基尔萨瑞斯的效忠对象"}},["84aa2a4b"]={q="基尔萨瑞斯·火枝想要什么？",a="基尔萨瑞斯只想逃出北方城堡的牢笼，摆脱抓捕他的狂热分子。他的私酿酒运输船遭到暴力摧毁后，他侥幸活了下来，却被关进一座海岸高塔。他迫切希望有人能为他扫清守军，助他逃离囚禁。",al={"基尔萨瑞斯·火枝的目标","基尔萨瑞斯想要什么","基尔萨瑞斯·火枝的目的"}}},fp="19,254,22.498.0,27.182.0,40.239.0,39.241.0,33.187.0"}
P.entries["npc:glorin-steelbrow"] = {n="戈罗林·钢眉",s="戈罗林·钢眉是一位矮人特工，在米奈希尔港的深水旅店中畅饮。他作为暴风城Cathedral of Light的主教法席恩的助手，帮助冒险者调查失踪的第三舰队，并找回散落在湿地海岸的圣物和材料。他的努力将暮色森林那闹鬼的荒野与北方的沉船残骸直接联系了起来。",h="戈罗林·钢眉是一位矮人特工，在米奈希尔港的深水旅店中畅饮。他作为暴风城Cathedral of...",kw={"主教法席恩","深水旅店","被诅咒的舰队","暮色森林","帕雷斯之眼","戈罗林·钢眉","光铸铁","米奈希尔港","湿地"},ang={["class:Paladin"]="遵循法席恩命令的圣骑士会发现戈罗林在回收光铸铁方面是不可或缺的，这种圣金是打造经由圣光祝福的武器的关键材料。",["faction:Alliance"]="戈罗林在回收湿地海军灾难中丢失的关键联盟军事圣物和圣化材料方面发挥着重要作用。",["race:Dwarf"]="戈罗林代表了矮人的事业与团结，他从米奈希尔港这个海运枢纽进行统筹，以支持卡兹莫丹和南方人类王国的盟友。"},sec={{t="港口的联系",b="当主教法席恩在暴风城的Cathedral of Light为对抗暮色森林日益逼近的恐怖而援助当地居民时，他也在遥远的北方米奈希尔港维持着联系。戈罗林·钢眉驻扎在繁忙的深水旅店里，充当法席恩在海岸上的耳目。他为那些北上寻找圣金和遗失圣物的旅行者提供援助和指引，在南部森林的危机与湿地的沉船残骸之间架起了一座至关重要的桥梁。"},{t="被诅咒的舰队与遗失的圣物",b="钢眉非常了解第三舰队的悲剧，该舰队的船只在湿地海岸边被重创并拖入深海。他引导冒险者搜寻那些闹鬼的残骸，寻找遗失的光铸铁锭和那件强大而又被诅咒的神器——帕雷斯之眼。戈罗林知道，找回这些神圣的武器对于铸造能够抵御威胁联盟的黑暗势力的兵器至关重要。"}},faq={{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一位驻扎在米奈希尔港深水旅店的矮人。他与暴风城的主教法席恩协同工作，协助前往北方打捞湿地海岸外沉船货物和圣物的冒险者。",al={"戈罗林是谁","戈罗林·钢眉背景故事","戈罗林做什么"}},{q="我在哪里可以找到戈罗林·钢眉？",a="戈罗林位于湿地西海岸米奈希尔港深水旅店的一楼。",al={"戈罗林位置","戈罗林·钢眉在哪里","戈罗林深水旅店"}},{q="为什么米奈希尔港的一位矮人会与暮色森林有关？",a="暴风城Cathedral of Light的主教法席恩正在寻求强大的圣物和圣金，以对抗侵蚀暮色森林的黑暗。他派遣心腹信使前往寻找戈罗林·钢眉，因为后者了解湿地海岸，能为打捞者指引第三舰队沉船残骸的方向。",al={"为什么在湿地有暮色森林任务","与法席恩的联系","为什么派往湿地"}},{q="戈罗林所说的第三舰队是什么？",a="第三舰队是一支在湿地海岸外遭遇灾难的联盟海军远征军。其破碎的船体如今散落在海底，被溺亡水手们的亡魂所缠绕，并隐藏着光铸铁和古代圣物等宝贵的货物。",al={"被诅咒的舰队是什么","湿地第三舰队","被诅咒的舰队任务"}},{q="什么是帕雷斯之眼？",a="帕雷斯之眼是一件随沉没舰队漂流的古代宗教圣物。在戈罗林的指引下从海底找回后，由于沉船周围残留着黑暗腐化，它必须经过圣职者的净化。",al={"帕雷斯之眼","帕雷斯圣物","什么是帕雷斯之眼"}},{q="光铸铁有什么用途？",a="光铸铁是一种稀有的圣化金属，用于打造受祝福的武器，能够打击强大的亡灵和恶魔力量。戈罗林协助从沉船残骸中回收遗失的铁锭，以援助暮色森林的保卫者。",al={"光铸铁","遗失的铁锭","受祝福的武器"}}},fx={["65727266"]={q="戈罗林·钢眉站在哪一方？",a="戈罗林坚定地支持联盟和圣光教会。他驻守在米奈希尔港，与暴风城的主教法席恩等领袖协作，向值得信赖的联盟冒险者寻求帮助，找回沿着险恶海岸遗失的圣物和物资。",al={"戈罗林·钢眉所属阵营","戈罗林·钢眉为谁效力","戈罗林·钢眉属于联盟吗"}},cbae8fd4={q="戈罗林·钢眉想要什么？",a="戈罗林想找回被大海吞没的神圣货物，尤其是沉没的第三舰队运载的货物。他努力招募冒险者，取回稀有的圣铸铁锭和帕雷斯之眼等圣物，确保它们得到净化并归还教会。",al={"戈罗林·钢眉需要什么","戈罗林·钢眉的目标","戈罗林·钢眉在寻找什么"}},["72c86ba2"]={q="戈罗林·钢眉与谁有关联？",a="戈罗林是暴风城 Cathedral of Light 的主教法席恩的同僚。他直接与暴风城的神职人员协调，寻找遗失的圣物，并在湿地港口担任他们的联络人，打捞原本由教会运送或在教会行动中遗失的货物。",al={"戈罗林·钢眉的关系","戈罗林·钢眉认识谁","戈罗林·钢眉与主教法席恩"}}},fp="16,405,19.496.0,32.444.1,24.239.0,34.128.0,57.294.0,48.240.0,26.243.1,33.221.0"}
P.entries["npc:gnoarn"] = {n="诺恩",s="诺恩是一位居住在铁炉堡矮人山城中Tinker Town的流亡侏儒。在诺莫瑞根毁灭后，他流离失所，通过指引冒险者帮助其他的侏儒工程师和幸存者，以此协助自己四散的同胞。",h="诺恩是一位居住在铁炉堡矮人山城中Tinker Town的流亡侏儒。在诺莫瑞根毁灭后，他流离失所，通过指引冒险者帮助其他的侏儒工程师和幸存者，以此协助自己四散的同胞。",kw={"宾格斯","诺恩","侏儒爆炸头","诺莫瑞根","铁炉堡","沉默的舒尼","tinker town"},ang={["faction:Alliance"]="路过铁炉堡的联盟英雄可以与诺恩交谈，寻找关于丹莫罗、洛克莫丹和暴风城各地正在进行的各类侏儒工程计划的线索。",["race:Gnome"]="对于其他侏儒而言，诺恩体现了Tinker Town难民社区的韧性，确保了流亡的工程师们能在东部王国各地保持联络。"},sec={{t="诺莫瑞根的流离失所者",b="和他的大多数族人一样，当穴居人入侵且灾难性的辐射使这座伟大的地下都市变得无法居住时，诺恩被迫逃离了诺莫瑞根的深处。他在铁炉堡的Tinker Town避难，受到铜须矮人的款待，诺恩每天都在关注其他幸存者的动向。他在难民中充当着非正式协调员的角色，将有能力的旅行者引向各地急需援助的侏儒，例如洛克莫丹遇险的飞行员宾格斯·雷管，或者暴风城雄心勃勃的工程师沉默的舒尼。"}},faq={{q="诺恩是谁？",a="诺恩是一位住在铁炉堡侏儒区Tinker Town的侏儒幸存者。他指引旅行者去帮助其他分散在联盟领地各处、正在进行各种项目的流亡侏儒。",al={"这个侏儒是谁","诺恩背景故事","诺恩npc"}},{q="诺恩在哪里？",a="他可以在铁炉堡东北部的Tinker Town找到，周围是他流亡族人们轰鸣的机器、齿轮和工作台。",al={"诺恩位置","诺恩在哪里","寻找诺恩"}},{q="诺恩会发布什么任务？",a="诺恩指引冒险者去协助其他分散各地的侏儒。值得注意的是，他派遣冒险者前往洛克莫丹查看失踪的飞行员宾格斯·雷管，并派旅行者前往暴风城与发明家沉默的舒尼交谈，商讨有关她旋风钻挖掘机的事宜。",al={"诺恩任务","诺恩想要什么"}},{q="诺恩的头发怎么了？",a="在诺莫瑞根陷落之前，诺恩以留着古怪的“侏儒爆炸头”而闻名。可悲的是，在家园城市遭遇灾难性的辐射泄露和破坏后，他失去了那引以为傲的发型。",al={"诺恩侏儒爆炸头","诺恩头发"}}},fx={["38923b37"]={q="诺恩效忠于哪一方？",a="诺恩忠于诺莫瑞根的侏儒同胞和联盟。他住在Tinker Town的流亡侏儒聚居区，努力维持社区的组织与团结，并与铁炉堡的盟友保持联系。",al={"诺恩所属阵营","诺恩是否属于联盟","诺恩效忠于谁"}},ce7102b3={q="诺恩为什么在铁炉堡？",a="和成千上万的其他侏儒一样，诺恩在诺莫瑞根沦陷后被迫离开家园。穴居人占领了这座地下科技奇观，有毒辐射污染了它的通道，幸存者只得向上逃离，在铁炉堡的矮人亲族中寻求庇护，并在Tinker Town开辟新家园。",al={"诺恩为什么在这里","诺恩为何来到铁炉堡","是什么让诺恩来到铁炉堡"}},["82a3a1ba"]={q="诺恩想要什么？",a="诺恩关心流离失所的亲族是否安全、身在何处。诺莫瑞根撤离后局势混乱，他四处寻找宾格斯等失踪的同伴，并指引有能力的冒险者帮助沉默的舒尼等知名发明家和专家。",al={"诺恩想做什么","诺恩的目标","诺恩需要什么"}},efead32c={q="诺恩与哪些人有联系？",a="诺恩与铁炉堡的其他诺莫瑞根幸存者保持密切联系，尤其与著名发明家沉默的舒尼联络，并协调寻找宾格斯·雷管等难民同胞。",al={"诺恩的盟友","诺恩认识谁","诺恩的人脉"}}},fp="6,259,33.597.0,14.214.0,26.161.0,32.286.0,31.230.0"}
P.entries["npc:godrick-farsan"] = {n="高德瑞克·法杉",s="高德瑞克·法杉是一位位于幽暗城的亡灵术士助手，与凯伦丁·哈加尔一起在魔法区供职。尽管双目完全失明，但他声称自己能以另一种方式看见事物。",h="高德瑞克·法杉是一位位于幽暗城的亡灵术士助手，与凯伦丁·哈加尔一起在魔法区供职。尽管双目完全失明，但他声称自己能以另一种方式看见事物。",kw={"凯伦丁·哈加尔","高德瑞克·法杉","纯洁的心","斯坦哈德·法尔杉","魅魔","幽暗城","术士"},ang={["class:Warlock"]="想要掌握魅魔召唤术的被遗忘者术士必须咨询高德瑞克，以准备必要的诱饵并了解恶魔仆从的吞噬本性。",["race:Undead"]="高德瑞克体现了被遗忘者术士的哲学，拥抱肉体的毁灭和失明，同时磨练黑暗魔法感知力来取代凡人的脆弱。"},sec={{t="黑暗之眼",b="高德瑞克·法杉身处幽暗城魔法区的召唤法阵之中，协助凯伦丁·哈加尔大师指导有志向的被遗忘者术士。虽然失去了肉眼的视觉，高德瑞克自称仍能以另一种方式视物，但他并未解释其中的缘由。他负责测试那些试图束缚更强大恶魔实体的修行者，派遣他们去收集复杂的召唤仪式所需的纯洁的心和精华。"}},faq={{q="高德瑞克·法杉是谁？",a="高德瑞克·法杉是一位驻扎在幽暗城魔法区的被遗忘者术士。他担任凯伦丁·哈加尔大师的助手，协助指导初出茅庐的术士并协助进行仪式。",al={"高德瑞克·法杉","高德瑞克是谁"}},{q="高德瑞克失明了，他是怎么看见的？",a="高德瑞克说，尽管他失明了，但他能以另一种方式视物。具体的手段并未解释。",al={"高德瑞克是盲人吗","高德瑞克如何视物"}},{q="高德瑞克和斯坦哈德·法尔杉有亲戚关系吗？",a="他们有着相同的姓氏，但没有任何亲属关系得到证实。",al={"斯坦哈德·法尔杉的关系","斯坦哈德·法尔杉的兄弟","高德瑞克和斯坦哈德有亲戚关系吗"}},{q="他在术士训练中扮演什么角色？",a="高德瑞克协助监督术士的束缚仪式，具体指导他们完成诸如获取纯洁的心以引诱和束缚魅魔等任务。",al={"高德瑞克术士任务","纯洁的心任务"}}},fx={["5d2f41c4"]={q="高德瑞克·法杉效忠于哪一方？",a="高德瑞克效忠于被遗忘者和黑暗女王，居住在幽暗城深处。他与凯伦丁·哈加尔共事，协助研习黑暗魔法的人，并引导寻求掌握恶魔力量的部落术士。",al={"高德瑞克·法杉的效忠对象","高德瑞克效忠于谁","高德瑞克·法杉所属阵营"}},f8f4201c={q="高德瑞克·法杉为什么在这里？",a="你会在幽暗城阴暗的区域找到高德瑞克，他是凯伦丁·哈加尔忠实的助手。他留在此处监督有志成为术士者的试炼，帮助他们束缚强大的恶魔实体，例如魅魔。",al={"高德瑞克为什么在幽暗城","高德瑞克·法杉在幽暗城的目的","高德瑞克·法杉在这里做什么"}},["57b226ed"]={q="高德瑞克·法杉想要什么？",a="高德瑞克希望推动幽暗城术士的黑暗研究。他通过严酷的试炼考验你的决心和驾驭危险虚空恶魔的能力，试炼中会用到仪式材料，例如纯洁无辜者的心脏。",al={"高德瑞克·法杉的目标","高德瑞克想要什么","高德瑞克·法杉的动机"}}},fp="14,198,16.410.0,22.199.0,35.104.0,37.60.0,43.152.0"}
P.entries["npc:golnir-bouldertoe"] = {n="高尼尔·石趾",s="高尼尔·石趾是一位矮人采矿供应商，驻扎在铁炉堡繁忙的Great Forge旁。他为矿工和勘探者提供基本补给，同时也负责处理当地信使和旅行者的调度工作。",h="高尼尔·石趾是一位矮人采矿供应商，驻扎在铁炉堡繁忙的Great Forge旁。他为矿工和勘探者提供基本补给，同时也负责处理当地信使和旅行者的调度工作。",kw={"石趾","煤块","助熔剂","高尼尔","great forge","铁炉堡","采矿供应商"},ang={["profession:Mining"]="造访Great Forge的矿工们依赖高尼尔提供这一技艺的关键工具，包括备用矿工锄和将原矿熔炼成精炼锭所需的助熔剂。",["race:Dwarf"]="对于从Coldridge或卡拉诺斯首次旅行归来的矮人来说，高尼尔是他们在首都的早期联系人，在山脉那炽热的心脏旁欢迎着每一位旅行者。"},sec={{t="Great Forge商人",b="高尼尔·石趾站在铁炉堡Great Forge的灼热之中，为勘探者和工匠提供他们行业所需的必需品。从坚固的矿工锄到助熔剂和煤块，他的商品为定义了这座矮人首都的永不停歇的熔炼之火和锻造场提供了燃料。作为Geofram Bouldertoe的族人，高尼尔是抵达城市的工人们可靠的联络点，他经常指引新人或接收从附近前哨站运来的补给信件。"}},faq={{q="我在哪里可以找到高尼尔·石趾？",a="高尼尔·石趾位于铁炉堡的Great Forge，站在中央熔炼和锻造区附近，与其他贸易商人在一起。",al={"高尼尔位置","高尼尔在哪里","高尼尔·石趾铁炉堡"}},{q="高尼尔出售什么商品？",a="他担任采矿供应商，出售矿工锄、煤块和助熔剂等基本的行业装备，以协助勘探者挖掘和提炼原矿。",al={"高尼尔供应商商品","高尼尔卖什么","高尼尔库存"}},{q="高尼尔·石趾参与任何任务吗？",a="是的。连接周围矮人定居点与首都的信使任务，例如涉及Gryth Thurden以及来自塞尔萨玛等前哨站的进港航班的跑腿任务，都会指引旅行者将消息直接送到高尼尔手中。",al={"高尼尔任务","前往铁炉堡高尼尔"}},{q="高尼尔与丹莫罗的其他人有亲属关系吗？",a="高尼尔与Geofram Bouldertoe共享同一个家族姓氏，后者是在铁炉堡Great Forge与他并肩工作的采矿训练师。",al={"石趾家族","geofram bouldertoe亲戚"}}},fx={["5f6dd933"]={q="高尼尔·石趾是谁？",a="高尼尔·石趾是一名矮人商人，在铁炉堡的Great Forge经营采矿用品。他为在城市熔炉中心劳作的勘探者和铁匠提供必需的补给、矿镐和冶炼用品。",al={"高尼尔是谁","高尼尔·石趾的背景","高尼尔的身份"}},b602f757={q="高尼尔·石趾效忠于哪一方？",a="高尼尔是铁炉堡和铜须氏族的忠实臣民，坚定地支持联盟。他在王国繁华的中心经营生意，为矮人同胞和来访的联盟旅客提供服务。",al={"高尼尔所属阵营","高尼尔的效忠对象","高尼尔站在哪一方"}},["7131f874"]={q="高尼尔·石趾为什么在这里？",a="高尼尔待在Great Forge附近，那里炉火不熄，矿石不断被冶炼。来自丹莫罗各地及更远地区的矿工和铁匠会把矿石直接运到铁炉堡的中央炉膛，因此高尼尔把店铺开在附近，为他们提供必需的装备。",al={"高尼尔为什么在铁炉堡","高尼尔在great forge的职责","高尼尔为什么在这里"}}},fp="17,218,27.473.0,35.154.0,28.154.0,44.236.0,47.125.0"}
P.entries["npc:gorbold-steelhand"] = {n="高尔博德·钢手",s="高尔博德·钢手是一位驻扎在黑海岸多雾海岸边奥伯丁的矮人商人。他远离卡兹莫丹的雪山大厅，为旅客、工匠和当地的暗夜精灵提供各种日用品和贸易物资。",h="高尔博德·钢手是一位驻扎在黑海岸多雾海岸边奥伯丁的矮人商人。他远离卡兹莫丹的雪山大厅，为旅客、工匠和当地的暗夜精灵提供各种日用品和贸易物资。",kw={"奥伯丁","黑海岸","深海，无尽之海","高尔博德","铁炉堡","商人","钢手","供应商"},ang={["faction:Alliance"]="高尔博德展示了联盟东部种族与暗夜精灵之间实际的合作，保持着无尽之海上的贸易畅通。",["race:Dwarf"]="在黑海岸那多雾的夜色环境中，看到像高尔博德这样熟悉的铁炉堡面孔，为矮人旅行者提供了一种受欢迎的家乡慰藉。"},sec={{t="卡利姆多的一位矮人商人",b="虽然卡利姆多的北部地区大多居住着神秘的暗夜精灵，但像奥伯丁这样的联盟哨站仍依赖来自无尽之海彼岸的商人们来维持贸易往来。高尔博德·钢手代表了铁炉堡商业在该地区的深远影响力。他与卡多雷并肩工作，向准备探索黑海岸险恶海岸和森林的冒险者出售贸易商品、试剂、工艺杂货和工具。"},{t="海上风险",b="除了储存日常用品外，高尔博德还密切关注着奥伯丁外海危险的沿海水域。黑海岸布满暗礁的海域因吞噬了众多联盟船只而臭名昭著，而像高尔博德这样的商人对沉入波涛之下的货物有着直接的兴趣。愿意潜入深海的旅行者常常会发现他对散落在沉船残骸中的打捞品和失踪的航海日志很感兴趣。"}},faq={{q="高尔博德·钢手是谁？",a="高尔博德·钢手是一位矮人综合贸易商，常驻黑海岸的奥伯丁沿海港口。",al={"高尔博德","高尔博德·钢手是谁","奥伯丁的矮人"}},{q="高尔博德·钢手卖什么？",a="他经营一般贸易物资、制造材料、采集工具以及诸如药瓶和丝线等供路过奥伯丁的工匠使用的试剂。",al={"高尔博德卖什么","高尔博德贸易商品","高尔博德供应商列表"}},{q="为什么铁炉堡的矮人会住在黑海岸？",a="奥伯丁是连接卡利姆多和东部王国的关键联盟中转枢纽。矮人们经常来到这里进行贸易、探索，并支持盟友暗夜精灵的行动。",al={"为什么这里有矮人","为什么高尔博德在黑海岸","奥伯丁的铁炉堡"}},{q="高尔博德提供任务吗？",a="是的，他指引冒险者前往黑海岸海岸外的沉船残骸，在任务“深海，无尽之海”中回收丢失的船只货物。",al={"高尔博德任务","深海，无尽之海任务发布者"}}},fx={["59afaf53"]={q="高尔博德·钢手效忠于哪一方？",a="高尔博德·钢手坚定地支持联盟。他是一名在暗夜精灵避难所奥伯丁经商的铁炉堡矮人，与当地卡多雷保持友好关系，也欢迎途经黑海岸、忠于联盟的旅客。",al={"高尔博德·钢手所属阵营","高尔博德·钢手是否属于联盟","高尔博德的效忠对象"}}},fp="17,242,28.454.0,17.401.0,25.106.0,33.157.0,46.193.0,30.141.0"}
P.entries["npc:gordon-wendham"] = {n="高顿·温德哈姆",s="高顿·温德哈姆是一位被遗忘者武器匠兼商人，在幽暗城熙熙攘攘的Trade Quarter开展业务。他为新近抵达的勇士和黑暗女王的当地守卫提供可靠的钢铁武器、利刃和钝器。除了贩卖基础军火外，他经常作为从地表抵达的信使们的当地联络点。",h="高顿·温德哈姆是一位被遗忘者武器匠兼商人，在幽暗城熙熙攘攘的Trade...",kw={"被遗忘者","高顿·温德哈姆","迈克尔·加勒特","trade quarter","幽暗城","武器商人"},ang={["class:Warrior"]="高顿为那些希望在都城磨练武器熟练度的前线战士提供了可靠的基础刀剑和钝器。",["race:Undead"]="对于刚从丧钟镇离开的获得新生的被遗忘者来说，像Trade Quarter的高顿·温德哈姆这样的商人代表了他们这个新兴国家战争机器的实际支柱。"},sec={{t="Trade Quarter的军火",b="高顿·温德哈姆坐落在幽暗城Trade Quarter潮湿的石质建筑和化学运河之间，为那些拿起武器为被遗忘者而战的人提供必要的装备。从基本的匕首和手斧，到坚固的长剑和钉头锤，他的存货满足了那些需要在前往洛丹伦纷争之地冒险前装备可靠铁器的初出茅庐的战士们的需求。"},{t="信使的目的地",b="除了商贸活动外，温德哈姆还融入了这座都城繁忙的后勤网络。受飞行管理员和信使派遣的旅行者——比如那些从废墟上方的蝙蝠管理员处接驳的信使——通常会被直接引向他的摊位。他在Trade Quarter的核心位置使他成为在地下城协调基础物资和分发调度时，一位易于找到且为人熟知的关键人物。"}},faq={{q="高顿·温德哈姆是谁？",a="高顿·温德哈姆是一位驻扎在幽暗城Trade Quarter的亡灵商人。他出售制式武备，并担任抵达都城的信使们的联络人。",al={"高顿·温德哈姆背景故事","温德哈姆是谁","幽暗城高顿"}},{q="高顿·温德哈姆在哪里？",a="你可以在Trade Quarter找到他，他在那里照看自己的武器摊位，这是位于幽暗城地下大厅内的商业环区。",al={"高顿·温德哈姆位置","幽暗城高顿在哪里","trade quarter武器商人"}},{q="他出售什么？",a="他提供种类繁多的基础级制式武器，包括剑、匕首、钉头锤、法杖、斧头以及各种适合升级期冒险者的投掷武器。",al={"温德哈姆的商品","高顿出售什么","高顿·温德哈姆武器"}},{q="有哪些任务与他有关？",a="他与连接地表蝙蝠栖息处到幽暗城内部的引导性递送任务有关，包括他与蝙蝠管理员迈克尔·加勒特之间的物资运送。",al={"高顿·温德哈姆任务","前往幽暗城","迈克尔·加勒特任务"}}},fx={["84654bd5"]={q="高顿·温德哈姆效忠于哪一方？",a="高顿·温德哈姆忠于希尔瓦娜斯·风行者女王和被遗忘者，也站在更广泛的部落一方。他在幽暗城经营店铺，为自己的亡灵同胞提供装备，支持他们保卫洛丹伦废墟下方收复的王国。",al={"高顿·温德哈姆所属阵营","高顿·温德哈姆效忠于谁","高顿·温德哈姆是否属于部落"}},d70aab3f={q="高顿·温德哈姆为什么在幽暗城？",a="高顿·温德哈姆在幽暗城繁华的Trade Quarter经营武器店。他身处被遗忘者首都的地下大厅，随时为准备前往地表敌对区域的人提供刀剑、斧头和钝器。",al={"高顿·温德哈姆为什么在这里","高顿·温德哈姆在幽暗城的目的","高顿·温德哈姆为何来到这里"}}},fp="14,351,30.365.0,23.429.0,22.181.0,32.140.0,18.166.0,24.173.0"}
P.entries["npc:gornek"] = {n="高内克",s="高内克是一位驻扎在杜隆塔尔试炼谷的兽人督军。他是新部落主要负责接收准备证明自己价值的兽人和暗矛巨魔新兵的联络人。",h="高内克是一位驻扎在杜隆塔尔试炼谷的兽人督军。他是新部落主要负责接收准备证明自己价值的兽人和暗矛巨魔新兵的联络人。",kw={"大兽穴","杜隆塔尔","高内克","羊皮纸","新部落","试炼谷"},ang={["race:Orc"]="对于年轻的兽人来说，向高内克报到是摆脱童年并赢得在杜隆塔尔光荣地位的第一步。",["race:Troll"]="作为受萨尔庇护的盟友，暗矛巨魔向高内克出示他们的证明，以证明他们能与兽人兄弟并肩成为同样强大的同伴。"},sec={{t="欢迎初试者",b="高内克站在试炼谷的中心，代表了部落未来的战士、斥候和施法者所面临的最初纪律考验。根据萨尔大酋长的命令，每一位年轻人和新人都必须通过毅力和坚持来赢得自己的地位，而不是靠特权。高内克负责评估进入山谷的人，审阅他们的介绍信，并引导他们前往营地各处的训练师那里。无论新兵携带的是加密卷轴、Glyphic Parchment还是普通石板，都是由高内克来接收这些凭证，并让他们踏上残酷的生存之路。"},{t="在杜隆塔尔的服役生涯",b="山谷中干旱的峡谷考验的不只是战斗技巧；它们灌输了新部落的共同精神。高内克确保新手们不会漫无目的地徘徊，他指引他们前往附近的蝎群巢穴、野猪巢穴进行试炼，并接受资深教官的监督。对于那些在训练场幸存下来并消灭了红岩沟壑中潜伏的威胁的人，高内克会在将他们派往杜隆塔尔更广阔、危险的土地之前，给予他们最终的认可。"}},faq={{q="谁是高内克？",a="高内克是试炼谷的一位兽人接待员和工头。他负责监管部落的新兵，审阅他们的入伍文件，并引导他们前往各自的职业训练师处。",al={"高内克","这个兽人是谁","谁是高内克"}},{q="我在哪里可以找到高内克？",a="他站在杜隆塔尔西南部试炼谷的中心附近，大兽穴内，年轻的兽人和暗矛巨魔就是从这里开始他们的旅程。",al={"高内克的位置","高内克在哪里","高内克地图"}},{q="为什么新兵要向他报到？",a="新来者携带着标明其所选学科的训练卷轴和石板。高内克会对这些介绍信进行评估，确认他们的资格，并将他们送到山谷内合适的导师那里。",al={"为什么要找高内克","羊皮纸任务","石板任务"}},{q="他在新部落中扮演什么角色？",a="他担任萨尔新部落的入伍协调员。他的职责是确保没有新兵在学习荣誉、生存和战斗准备的基本原则之前，就进入杜隆塔尔更广阔的土地。",al={"高内克的部落角色","高内克是做什么的"}}},fx={a3ac85eb={q="高内克效忠于哪一方？",a="高内克对萨尔的新部落忠心耿耿。他驻扎在杜隆塔尔，在试炼谷担任监督者，确保每一位新近觉醒的兽人和前来报到的巨魔新兵都懂得纪律、力量和生存之道，以保卫他们初建的国家。",al={"高内克所属阵营","高内克效忠于谁","高内克属于部落还是联盟"}},e623e91b={q="高内克想要什么？",a="高内克要你证明自己配得上部落。杜隆塔尔环境恶劣，遍布掠食者和敌对的渗透者，他不愿把资源浪费在缺乏纪律的新兵身上。他派遣年轻的战士猎杀危险的野兽、铲除当地威胁，将他们锻炼成能干的战士。",al={"高内克的目标","高内克需要什么","高内克的任务动机"}},a6376a9f={q="高内克为什么在试炼谷？",a="试炼谷是部落新兵指定的试炼场。高内克驻扎在这里，负责引导新来者、评估他们初期的能力，并带他们认识训练师和各项试炼，为他们应对杜隆塔尔及更远地区的挑战做好准备。",al={"高内克为什么在这里","高内克在试炼谷的职责","高内克为什么在杜隆塔尔"}}},fp="6,204,22.613.0,28.513.0,14.190.0,24.149.0,34.221.0,34.207.0"}
P.entries["npc:gramma-stonefield"] = {n="米莱德·斯通菲尔德",s="米莱德·斯通菲尔德（她的本名是米莱德）是居住在艾尔文森林农场中的斯通菲尔德家族的长者。与她那些好争斗的亲戚不同，她已经厌倦了与邻居马科伦家族之间那场旷日持久的苦涩世仇。她背着家人悄悄行动，尽其所能帮助她的孙子托米·乔·斯通菲尔德追求与梅贝尔·马科伦之间那段禁忌的恋情。",h="米莱德·斯通菲尔德（她的本名是米莱德）是居住在艾尔文森林农场中的斯通菲尔德家族的长者。与她那些好争斗的亲戚不同，她已经厌倦了与邻居马科伦家族之间那场旷日持久的苦涩世仇。她背着家人悄悄行动，尽其所能帮助她的孙子托米·乔·斯...",kw={"艾尔文","米莱德·斯通菲尔德","马科伦","梅贝尔","米莱德","斯通菲尔德农场","托米·乔","威廉·匹斯特"},ang={["faction:Alliance"]="米莱德·斯通菲尔德是一个温柔的提醒，即便是身处联盟的核心腹地，地方冲突往往也需要通过安静的外交和单纯的同理心，而非武力来解决。"},sec={{t="秘密的调停者",b="作为斯通菲尔德家族现存最年长的成员，米莱德·斯通菲尔德目睹了数十年间，她家与马路对面马科伦家族之间琐碎的争吵。她不仅没有火上浇油，反而认为这种持久的敌对毫无意义且具有破坏性。当她的孙子托米·乔·斯通菲尔德爱上梅贝尔·马科伦时，米莱德·斯通菲尔德选择了同情而非家族忠诚。依靠与闪金镇威廉·匹斯特的深厚友谊，她悄悄策划帮助这对苦命鸳鸯秘密相会，以此瓦解阻隔两个农场的顽固敌意。"}},faq={{q="米莱德·斯通菲尔德是谁？",a="米莱德·斯通菲尔德（本名米莱德）是居住在艾尔文森林中部农场里的斯通菲尔德家族的长者。她是托米·乔·斯通菲尔德的祖母。",al={"米莱德是谁","米莱德·斯通菲尔德","斯通菲尔德老奶奶"}},{q="她如何看待与马科伦家族的世仇？",a="米莱德对维持这场世仇毫无兴趣。与两个家族的大多数成员不同，她认为这种怨恨愚蠢且有害，比起无休止的争吵，她更希望看到两家和睦相处。",al={"斯通菲尔德与马科伦的世仇","她憎恨马科伦吗"}},{q="为什么她要帮助托米·乔和梅贝尔？",a="她爱她的孙子托米·乔，希望他能幸福。因为她拒绝家族世仇，所以她积极帮助他与梅贝尔·马科伦那段禁忌的恋情，求助于她的老朋友威廉·匹斯特，为这对恋人想出解决办法。",al={"为什么要帮助托米·乔","米莱德的爱情药水","帮助恋人"}},{q="威廉·匹斯特对她来说是什么人？",a="威廉·匹斯特是住在闪金镇Lion's Pride Inn的炼金师，也是米莱德·斯通菲尔德的一位老朋友和值得信赖的伙伴。她通过值得信赖的信使联系他，为托米·乔配制一些巧妙的补救药剂和辅助品。",al={"威廉·匹斯特的关系","威廉·匹斯特与米莱德"}}},fp="17,88,19.477.0,25.172.0,51.165.0,41.197.0,29.226.0"}
P.entries["npc:grand-mason-marblesten"] = {n="大石匠玛布勒斯坦",s="大石匠玛布勒斯坦是一位受人尊敬的矮人石匠，驻扎在繁忙的铁炉堡平民区。他深深地效忠于Khaz Modan的皇室传统，受国王麦格尼·铜须委任，为在萨多尔大桥悲剧中牺牲的矮人战士Sully Balloo建造一座纪念碑。冒险者在协助收集完成这一庄严致敬所需的材料时，经常会见到他。",h="大石匠玛布勒斯坦是一位受人尊敬的矮人石匠，驻扎在繁忙的铁炉堡平民区。他深深地效忠于Khaz Modan的皇室传统，受国王麦格尼·铜须委任，为在萨多尔大桥悲剧中牺牲的矮人战士Sully...",kw={"国王的致敬","铜须","平民区","大石匠","铁炉堡","麦格尼","玛布勒斯坦","石匠","sully balloo"},ang={["faction:Alliance"]="缅怀Sully Balloo的牺牲，提醒着联盟记住在战争中失去的每一位士兵。",["profession:Mining"]="与丹莫罗及其他地区的岩石打交道的矿工，会对玛布勒斯坦对原始矿物质量的高标准要求表示赞赏。",["race:Dwarf"]="对于矮人来说，石雕是祖传的遗产；协助玛布勒斯坦不仅是对Khaz Modan工艺的致敬，也是对已故士兵Sully Balloo的纪念。"},sec={{t="石之大师",b="矮人石匠工艺不仅仅是一门手艺；它是塑造铁炉堡灵魂的永恒艺术。大石匠玛布勒斯坦是城中首屈一指的凿刻大师，代表了从活生生的山脉中直接雕刻大厅、柱子和伟大雕像的千年传统。他以平民区为基地，负责监督那些让铜须历史永垂不朽的市政工程和纪念碑。"},{t="国王的致敬",b="玛布勒斯坦最感人的任务是为国王麦格尼委任建造的Sully Balloo纪念碑，Sully Balloo是一位在萨多尔大桥悲剧中丧生的士兵，这座纪念碑旨在向他悲痛的遗孀致敬。为了得到一件真正持久的作品，这位大石匠坚持使用最优质的石材：来自希尔斯布莱德达隆山的奥特兰克花岗岩。"}},faq={{q="大石匠玛布勒斯坦是谁？",a="大石匠玛布勒斯坦是位于铁炉堡平民区的一位资深矮人石匠。他负责市政和皇室的雕刻工程，其中最著名的是受国王麦格尼·铜须委任，为牺牲的士兵Sully Balloo建造的纪念碑。",al={"玛布勒斯坦是谁","玛布勒斯坦的角色","大石匠npc"}},{q="我在哪里可以找到大石匠玛布勒斯坦？",a="他位于铁炉堡的平民区，周围环绕着石块和建筑作品，距离城市繁忙的商店和银行不远。",al={"玛布勒斯坦的位置","玛布勒斯坦在哪里","铁炉堡玛布勒斯坦"}},{q="玛布勒斯坦正在建造什么纪念碑？",a="他正在为在萨多尔大桥悲剧中牺牲的矮人战士Sully Balloo建造一座纪念碑。国王麦格尼·铜须委任他建造此碑，以向Balloo和其悲痛的遗孀致敬。",al={"他在建造什么","国王的致敬任务","玛布勒斯坦雕像"}},{q="为什么玛布勒斯坦需要冒险者收集材料？",a="玛布勒斯坦想要一件真正史诗般且持久的作品，因此他只愿意使用现有的最优质石材。他派遣旅行者前往希尔斯布莱德的达隆山采集奥特兰克花岗岩。",al={"玛布勒斯坦任务","为什么需要石头","纪念碑材料"}},{q="在矮人社会中，‘大石匠’的头衔意味着什么？",a="在矮人中，石雕与锻造同样受到尊崇。‘大石匠’是一位技艺精湛的石刻大师，受命负责重大的国家项目、皇室建筑设计和仪式纪念碑。",al={"什么是大石匠","矮人石匠等级"}},{q="玛布勒斯坦是联盟官员还是私人承包商？",a="玛布勒斯坦直接在铁炉堡内工作，服务于铁炉堡王国和联盟，并与国王麦格尼·铜须的宫廷密切协调，执行皇室委任。",al={"玛布勒斯坦为谁工作","玛布勒斯坦派系"}}},fx={a77cb24b={q="大石匠玛布勒斯坦效忠于哪一方？",a="玛布勒斯坦完全忠于铁炉堡和联盟。他驻扎在城市公共区的中心，为国王麦格尼·铜须和矮人王国效力，将自己的技艺与石工本领用于彰显矮人传统和王权。",al={"玛布勒斯坦所属阵营","玛布勒斯坦效忠于谁","玛布勒斯坦是否属于联盟"}},["1dc5a337"]={q="大石匠玛布勒斯坦想要什么？",a="玛布勒斯坦正在监督一座王室纪念碑的建造，需要优质材料才能完工。他参与修建“国王的礼物”，希望有能干的冒险者帮忙收集必要资源，为阵亡士兵萨利·巴鲁修建纪念碑。这座纪念碑由国王麦格尼委托建造。",al={"玛布勒斯坦想要什么","玛布勒斯坦的目标","玛布勒斯坦为什么需要帮助"}},["98aae54f"]={q="大石匠玛布勒斯坦为什么在公共区？",a="玛布勒斯坦在铁炉堡繁华的公共区设有工坊，以监督这座宏伟山中要塞的石工工程，并统筹王座相关的建造工作。开阔的广场便于他协调项目，也方便招募途经城市的旅客。",al={"玛布勒斯坦为什么在铁炉堡","玛布勒斯坦为什么在这里","玛布勒斯坦与铁炉堡公共区"}}},fp="22,395,19.426.0,16.312.0,30.247.0,40.154.0,39.182.0,57.184.0,58.210.0,59.176.0"}
P.entries["npc:granis-swiftaxe"] = {n="格兰尼斯·快斧",s="格兰尼斯·快斧是一位驻扎在卡拉诺斯雷酒酿制厂内的矮人战士训练师。他以直率的个性和严苛的训练方式而闻名，负责指导从寒脊山小径走出来的新晋联盟战士，随后将经验丰富的战士指引至铁炉堡。",h="格兰尼斯·快斧是一位驻扎在卡拉诺斯雷酒酿制厂内的矮人战士训练师。他以直率的个性和严苛的训练方式而闻名，负责指导从寒脊山小径走出来的新晋联盟战士，随后将经验丰富的战士指引至铁炉堡。",kw={"丹莫罗","格兰尼斯·快斧","卡拉诺斯","穆瑞恩·风暴之矛","雷酒酿制厂","战士训练师"},ang={["class:Warrior"]="对于离开寒脊山谷的矮人和侏儒战士来说，格兰尼斯在酿制厂里提供必要的早期战斗指导，顺便还能来上一杯新鲜的麦酒。",["race:Dwarf"]="格兰尼斯体现了铁炉堡步兵那种强壮而固执的精神，他将军事纪律与当地麦酒的舒适感结合在了一起。"},sec={{t="卡拉诺斯的粗鲁导师",b="格兰尼斯·快斧通常被发现正待在雷酒酿制厂的酒桶旁取暖，他是那些游历在丹莫罗的年轻战士们的主要战斗导师。他拥有矮人战士那种坚韧不拔的自豪感，对于试图接近他的非战士职业者，他表现得十分轻蔑甚至嘲讽。一旦学生证明了自己的战斗能力，格兰尼斯就会将他们送上山路，去铁炉堡的Military Ward寻找高级训练师穆瑞恩·风暴之矛。"}},faq={{q="谁是格兰尼斯·快斧？",a="格兰尼斯·快斧是一位矮人战士训练师，位于卡拉诺斯的雷酒酿制厂一楼。他为在丹莫罗冒险的年轻矮人和侏儒战士传授早期的战斗技巧。",al={"格兰尼斯·快斧","格兰尼斯是谁","卡拉诺斯战士训练师"}},{q="为什么格兰尼斯嘲笑我的角色？",a="对于那些不走战士之路的人，格兰尼斯毫无耐心。如果其他职业的冒险者与他交谈，他会嘲笑他们根本无法在他的高强度训练下坚持哪怕一天。",al={"格兰尼斯的粗鲁名言","为什么格兰尼斯在嘲笑我","格兰尼斯对非战士职业的对话"}},{q="格兰尼斯将进阶后的战士送到哪里？",a="一旦战士在丹莫罗获得了足够的经验，格兰尼斯就会指引他们去找穆瑞恩·风暴之矛，他是位于铁炉堡Military Ward的一位资深战士训练师。",al={"穆瑞恩·风暴之矛任务","格兰尼斯任务线","格兰尼斯将你指引给谁"}},{q="格兰尼斯与其他在卡兹莫丹的“快斧”成员有亲戚关系吗？",a="他与其他矮人共用“快斧”这个姓氏，但尚未确认有任何家族关系。",al={"快斧家族","格兰尼斯·快斧的亲戚"}}},fx={b8e95117={q="格兰尼斯·快斧站在哪一方？",a="格兰尼斯坚定地支持铁炉堡的矮人以及更广泛的联盟。他驻守在卡拉诺斯，将自己的战斗专长用于训练新一代守卫者，抵御丹莫罗周边的穴居人、霜鬃巨魔和其他威胁。",al={"格兰尼斯·快斧阵营","格兰尼斯为谁而战","格兰尼斯与联盟"}},["760b1803"]={q="格兰尼斯·快斧为什么在卡拉诺斯？",a="格兰尼斯驻扎在卡拉诺斯的雷酒酿制厂内，训练从寒脊山小径出发的新晋联盟战士。丹莫罗正承受着本土穴居人和温迪戈日益加剧的压力，因此他严格的战斗训练对当地防卫至关重要。",al={"格兰尼斯为什么在这里","格兰尼斯·快斧在此的原因","是什么让格兰尼斯来到卡拉诺斯"}},cf3183bb={q="格兰尼斯·快斧想要什么？",a="格兰尼斯只希望训练出坚韧守纪、能够守住卡兹莫丹防线的战士。他对弱者和未经训练的人缺乏耐心，要求新兵全心投入，然后才会把有潜力的老兵推荐给铁炉堡的穆伦·风矛等大师。",al={"格兰尼斯·快斧的目标","格兰尼斯想要什么","格兰尼斯的目的"}}},fp="15,285,26.485.0,23.216.0,34.218.0,42.170.0,51.91.0"}
P.entries["npc:great-father-winter"] = {n="冬天爷爷",s="冬天爷爷是一位年迈的兽人，受聘于烟林牧场，在奥格瑞玛扮演这一传说中的节日人物。冬幕节期间，他驻扎在力量谷的Grommash Hold附近，一边倾听孩子们的愿望，一边却明显对商业化的节日欢庆感到厌倦。为了换取节日礼物和完成季节性任务，他经常向路人索要姜饼和冰镇牛奶。",h="冬天爷爷是一位年迈的兽人，受聘于烟林牧场，在奥格瑞玛扮演这一传说中的节日人物。冬幕节期间，他驻扎在力量谷的Grommash...",kw={"姜饼","冬天爷爷","奥格瑞玛","烟林牧场","valley of strength","冬幕节"},ang={["faction:Horde"]="他作为部落在奥格瑞玛的主要季节性象征人物，代表烟林牧场提供节日礼物和任务。",["profession:Cooking"]="厨师可以使用节日配方制作姜饼，并将其与牛奶一起交给冬天爷爷，以恢复他的精神。",["race:Orc"]="尽管兽人崇敬季节的更替和元素，但看到他们的一员沦为推销商家折扣的着装吉祥物，依然在考验着传统主义者的耐心。"},sec={{t="受雇的神话",b="虽然古老的传说将冬天爷爷描述为一位雄伟的元素之灵，游荡在大地上，带来冰雪和季节的更替，但坐在力量谷里的这位却显得平凡得多。他是一名烟林牧场雇佣的兽人演员，专门负责刺激消费、推销公司商品，并为部落的年轻人提供娱乐。批评者抱怨这种商业吉祥物拉低了真正季节传统的格调，但不可否认的是，他确实为城市街道带来了节日的喧嚣。"},{t="力量谷的轮班工作",b="这位替身就驻扎在Grommash Hold外，装饰着常青树的枝桠下，忍受着孩子们爬到他膝盖上提出礼物要求所带来的精疲力竭。在推销烟林牧场的打折促销活动和敷衍的节日问候之间，他的耐力经常会耗尽。他毫不讳言自己会在背包里藏上一瓶节日烈酒，以便在轮班结束后立刻喝上一口来隔绝噪音，他也非常依赖来往的冒险者提供零食来支撑他继续工作。"}},faq={{q="这是真正的冬天爷爷吗？",a="不是。他只是一名普通的兽人，被烟林牧场雇佣来装扮成冬天爷爷的样子，扮演这位传说中的冬幕节人物，并在奥格瑞玛分发节日宣传品。",al={"他是真的吗","谁是冬天爷爷","他是个演员吗"}},{q="在奥格瑞玛哪里可以找到冬天爷爷？",a="他位于力量谷，就在Grommash Hold入口外，冬幕节树和节日摊位旁边。",al={"冬天爷爷位置","冬天爷爷在哪里","哪里找冬幕节兽人"}},{q="他在冬幕节期间做什么？",a="他负责招待过节的游客，倾听孩子们的礼物需求，发布烟林牧场的促销任务，并在节日达到高潮时在树下分发节日礼物。",al={"他做什么","冬天爷爷的作用","冬幕节任务"}},{q="他为什么想要姜饼和牛奶？",a="整天忍受着吵闹的人群和一个个轮流坐到他膝盖上的孩子，让他感到筋疲力尽。他请求冒险者带给他新鲜的姜饼和牛奶，以保持他在轮班期间的体力。",al={"给冬天爷爷的礼物","为什么牛奶和饼干","姜饼任务"}},{q="他如何看待这份工作？",a="他觉得这种表演既乏味又耗费精力。他公开抱怨那些急切的孩子们，草草念完公司的口号，并急切地倒数着时间，盼望着能去喝一口藏在包里的烈酒。",al={"他喜欢他的工作吗","冬天爷爷语录","他喝醉了吗"}},{q="联盟有对应的角色吗？",a="有。联盟的冬天爷爷是一位受雇于烟林牧场的老矮人，他坐在铁炉堡平民区的节日树旁。",al={"联盟冬天爷爷","铁炉堡圣诞老人","联盟对应角色"}}},fx={["1d43ce2e"]={q="冬天爷爷站在哪一方？",a="这位冬天爷爷是一名兽人，只在奥格瑞玛为部落效力，不过他最终的雇主是烟林牧场。这家地精企业雇用他为力量谷带来节日欢乐，也带动节日消费。虽然他穿着传说中的节日红衣，真正效忠的却是自己的薪水，以及熬过这段艰苦的轮班。",al={"冬天爷爷属于部落吗","冬天爷爷阵营","冬天爷爷为谁工作"}},["796ea74c"]={q="冬天爷爷为什么在这里？",a="他驻扎在Grommash Hold外，因为烟林牧场雇用了他，让他为部落首都的冬幕节庆典助阵。这些精明的地精商人安排他逗乐城里的孩子、倾听他们想要的礼物，并引导满怀期待的家庭购买节日商品和应景点心。",al={"冬天爷爷为什么在奥格瑞玛","是什么让冬天爷爷来到这里","冬天爷爷在此的原因"}},f14772a5={q="冬天爷爷与谁有关联？",a="他直接受雇于烟林牧场。这家精明的地精企业负责在整个世界推广冬幕节。他们为他提供节日服装，安排宣传台词，并组织他在Grommash Hold附近分发的礼物和点心。",al={"谁雇用了冬天爷爷","冬天爷爷的人际关系","烟林牧场与冬天爷爷"}},["826ac72e"]={q="冬天爷爷为何出名？",a="他自称冬天爷爷，并装扮成这位古老的超自然人物。艾泽拉斯各地的人们都庆祝冬天爷爷迎来季节更迭。学者们争论这名穿着戏服的兽人不过是商业吉祥物，但孩子和节日庆祝者仍纷纷前来，把他视为冬幕节欢乐的化身。",al={"人们为什么知道冬天爷爷","冬天爷爷是传说人物吗","冬天爷爷的名望"}}},fp="19,438,12.510.0,36.525.0,36.154.0,50.145.0,48.183.0,46.205.0,30.223.0,44.149.0"}
P.entries["npc:greatfather-winter"] = {n="冬天爷爷",s="冬天爷爷是冬季的传奇化身，也是冬幕节的核心人物。虽然古老的传说将他尊为神话般的存在，用白雪覆盖Azeroth，让大地休养生息并焕发新生，但现代的城市居民主要通过Smokywood Pastures的地精所经营的商业庆典来认识他。",h="冬天爷爷是冬季的传奇化身，也是冬幕节的核心人物。虽然古老的传说将他尊为神话般的存在，用白雪覆盖Azeroth，让大地休养生息并焕发新生，但现代的城市居民主要通过Smokywood...",kw={"丹莫罗","姜饼","冬天爷爷","铁炉堡","奥格瑞玛","smokywood pastures","冬幕节"},ang={["profession:Cooking"]="这个节日依靠熟练的厨师为Smokywood Pastures和冬天爷爷本人制作姜饼和其他节日美食。",["race:Dwarf"]="矮人将冬天爷爷视为塑造世界的泰坦的一个侧面，并将丹莫罗的雪峰视为他造访的活见证。"},sec={{t="神话与新生",b="根据古老的传说，冬天爷爷是一位超凡脱俗的漫游者，在岁末时行走于世间，将他那翻涌的雪白斗篷披在在大地上，让大自然沉睡并重生。矮人们视他为泰坦的化身或使者，并指出丹莫罗冰霜覆盖的悬崖就是他偏爱的活生生证据。其他传统，比如牛头人的传统，尊重他在季节更替中的作用，同时将寒冷和风暴归因于太阳和月亮的元素之力，让Earth Mother得以休息。无论这个传说流传到哪里，各个社群都学会了聚集在一起，共同抵御寒冷，庆祝生命回归的承诺。"},{t="Smokywood Pastures与城市庆典",b="在像铁炉堡和奥格瑞玛这样的大型定居点，这位古老的灵魂已经被富有进取心的Smokywood Pastures地精彻底重塑。这个贸易集团普及了冬天爷爷的形象：一位留着白胡子、身穿红衣的快乐长者，他乘坐着飞行的雪橇，分发节日礼物和玩具。Smokywood Pastures雇佣了当地的演员——在铁炉堡雇佣矮人，在奥格瑞玛雇佣兽人——来倾听孩子们的愿望清单，接受牛奶和姜饼的供奉，并在装饰华丽的树下宣传季节性商品。"}},faq={{q="铁炉堡里的冬天爷爷是真正的灵魂吗？",a="不是，坐在铁炉堡节日树旁的冬天爷爷是由地精商会Smokywood Pastures雇佣的演员。该公司安排这种出场是为了取悦孩子并销售季节性糖果，尽管真实的传说中确实提到过一位在冬季行走于世间的超凡存在。",al={"冬天爷爷是真的吗","铁炉堡里的那个人是谁","他是演员吗"}},{q="为什么矮人尊崇冬天爷爷？",a="矮人将冬天爷爷与他们的创造者泰坦联系在一起。他们将他洒向大地的雪被视为一种祝福，并将他们终年寒冷的家园丹莫罗作为他偏爱的首要证据。",al={"矮人冬幕节","矮人冬天爷爷","铁炉堡冬天爷爷"}},{q="冬天爷爷会用人们带给他的饼干和牛奶做什么？",a="根据Smokywood Pastures推广的节日传说，冬天爷爷喜欢一边享用节日的姜饼和冰镇牛奶，一边查看愿望清单并传播节日欢乐。",al={"给冬天爷爷的款待","为什么是牛奶和饼干","姜饼任务"}},{q="部落如何看待冬天爷爷？",a="部落参与庆典主要通过Smokywood Pastures在奥格瑞玛的城市宣传活动，在这里冬天爷爷被描绘成一个兽人。在文化上，牛头人认为冬季是Earth Mother沉睡和元素更新的关键时期，他们尊重冬天爷爷在季节循环中的作用，同时避免对其进行字面意义上的泰坦崇拜。",al={"部落冬天爷爷","奥格瑞玛冬天爷爷","牛头人冬幕节"}}},fx={["66677a0e"]={q="冬天爷爷站在哪一方？",a="他不属于任何阵营。传说中的冬天爷爷是一股古老的超自然自然之力，为整个世界带来季节更替与丰饶，不受凡人阵营归属的影响。你在铁炉堡看到的这位人物由地精贸易公司烟林牧场赞助，该公司奉行严格中立、以盈利为导向的经营方式。事实上，烟林牧场还雇了一位兽人对应者坐镇奥格瑞玛，同时为部落传播节日欢乐。",al={"冬天爷爷属于联盟还是部落","冬天爷爷属于联盟吗","冬天爷爷阵营"}},a8f1de98={q="冬天爷爷想要什么？",a="神话中的古老精魂只希望让冬日笼罩世界，让大地得以休养、重生，最终焕发生机，同时赐福于欢迎他的人。然而，你在铁炉堡遇到的凡人扮演者受雇于烟林牧场。他们的目标完全出于节庆和商业考虑：带来欢乐，为乖巧的孩子分发点心，并推动节日商品和玩具的热销。",al={"冬天爷爷的动机","冬天爷爷想要什么","冬天爷爷为什么送礼物"}},daa32740={q="冬天爷爷为什么在铁炉堡？",a="烟林牧场把他安排在冬幕节之树旁，为季节庆典助阵。节日期间的几周里，这位和蔼的人物会与市民和孩子们见面，听取他们的节日愿望、收取信件，并与地精助手们一起传播善意，同时帮助烟林牧场推广应季商品。",al={"冬天爷爷为什么在铁炉堡","冬天爷爷为什么在这里","冬天爷爷在铁炉堡的位置"}},["8b922b4d"]={q="冬天爷爷与谁有关联？",a="矮人传统将这位古老精魂与泰坦紧密联系起来，认为他体现了泰坦塑造艾泽拉斯四季的力量。在日常庆典中，城里出现的节日版冬天爷爷与烟林牧场合作，身边围着他们的小小助手和节日雪人。",al={"冬天爷爷与谁有关联","冬天爷爷的人际关系","谁和冬天爷爷共事"}}},fp="18,362,16.674.0,39.571.0,55.303.0,41.228.0,73.202.0,43.359.0"}
P.entries["npc:greatmother-hawkwind"] = {n="鹰风酋长的母亲",s="鹰风酋长的母亲是一位受人尊敬的牛头人长者，居住在红云台地的水井旁。作为纳拉其营地领袖鹰风酋长的母亲，尽管年事已高，她依然体现了部落坚韧的精神和共同的责任感。",h="鹰风酋长的母亲是一位受人尊敬的牛头人长者，居住在红云台地的水井旁。作为纳拉其营地领袖鹰风酋长的母亲，尽管年事已高，她依然体现了部落坚韧的精神和共同的责任感。",kw={"谦卑的任务","纳拉其营地","鹰风酋长","鹰风酋长的母亲","莫高雷","红云台地","牛头人长者"},ang={["race:Tauren"]="对于在红云台地开始旅程的年轻牛头人来说，鹰风酋长的母亲体现了大地母亲的核心价值观：尊敬长者、团结社区以及谦卑奉献。"},sec={{t="台地长者",b="鹰风酋长的母亲整日守在纳拉其营地的淡水井旁，为那些开始试炼之路的年轻牛头人担任精神导师。虽然岁月放缓了她的脚步，但她拒绝让年老阻碍自己对村庄尽责。她相信部落的每一位成员，无论老幼，在维持社区运转方面都有不可或缺的作用，因此经常请那些初出茅庐的年轻后辈帮忙做些简单的家务，比如打取淡水。"},{t="母亲的指引",b="作为纳拉其营地首领鹰风酋长的母亲，鹰风酋长的母亲在红云台地面临威胁时提供了稳定的建议和沉静的尊严。当她的儿子组织猎人和勇士对抗入侵的刺鬃野猪人和当地掠食者时，她细心呵护着定居点的道德核心，提醒新觉醒者力量源于谦逊和对亲族的奉献。"}},faq={{q="谁是鹰风酋长的母亲？",a="鹰风酋长的母亲是一位居住在红云台地纳拉其营地的牛头人长者。她是营地首领鹰风酋长的母亲，并担任年轻冒险者的长者向导。",al={"鹰风酋长的母亲背景故事","谁是鹰风酋长的母亲","纳拉其营地长者"}},{q="她在哪里？",a="她坐在纳拉其营地东南方，莫高雷西南部的红云台地的水井旁。",al={"鹰风酋长的母亲位置","鹰风酋长的母亲在哪里"}},{q="她会给年轻牛头人分配什么任务？",a="她会交给年轻牛头人“谦卑的任务”，请他们从村里的水井打水并送到营地的其他人手中。这项琐事教导他们：对于部落的真正仆人来说，没有哪项任务是低贱的。",al={"鹰风酋长的母亲任务","谦卑的任务"}},{q="她与鹰风酋长是什么关系？",a="她是鹰风酋长的母亲，鹰风酋长负责纳拉其营地的防御以及年轻勇士的训练工作。",al={"鹰风酋长的母亲","她和鹰风酋长有亲属关系吗"}}},fx={f701fe56={q="鹰风酋长的母亲站在哪一方？",a="鹰风酋长的母亲忠于自己的族人——部落的牛头人。作为纳拉其营地的年长族长，她完全效忠于自己的部族、家人，以及那些踏上征程、准备侍奉先祖和大地母亲的年轻勇士。",al={"鹰风酋长的母亲阵营","鹰风酋长的母亲为谁效力","鹰风酋长的母亲的忠诚归属"}},["8d52ad78"]={q="鹰风酋长的母亲想要什么？",a="尽管年事已高，鹰风酋长的母亲仍坚持尽力照料纳拉其营地。她操持定居点的事务，做些从村中水井打水之类的简单家务，并请年轻的牛头人搭把手，帮忙完成这些平凡的日常杂务。",al={"鹰风酋长的母亲需要什么","鹰风酋长的母亲的目标","为什么要找鹰风酋长的母亲交谈"}},["2db356dc"]={q="鹰风酋长的母亲为什么在这里？",a="鹰风酋长的母亲住在纳拉其营地，是村中的长者，也是鹰风酋长的母亲。你会在定居点中央的水井旁找到她，她正勤勉地为部族操劳，并照看着那些在红云台地开始旅程的年轻猎人和萨满。",al={"鹰风酋长的母亲为什么在纳拉其营地","鹰风酋长的母亲在此的原因","她为什么在水井旁"}}},fp="20,247,17.476.0,19.413.0,28.203.0,23.96.0,40.205.0,39.107.0"}
P.entries["npc:grelin-whitebeard"] = {n="格瑞林·白须",s="格瑞林·白须是一名矮人斥候，受皇家法令指派驻守在寒脊山谷，负责评估霜鬃巨魔的威胁。他独自在一座偏远的营地中行动，依靠崛起的冒险者来压制巨魔，因为铁炉堡的注意力目前正被穴居人危机所牵制。",h="格瑞林·白须是一名矮人斥候，受皇家法令指派驻守在寒脊山谷，负责评估霜鬃巨魔的威胁。他独自在一座偏远的营地中行动，依靠崛起的冒险者来压制巨魔，因为铁炉堡的注意力目前正被穴居人危机所牵制。",kw={"寒脊山谷","丹莫罗","霜鬃","格瑞林·白须","格里尼尔","铁炉堡议会","森内尔·白须","被盗的日记"},ang={["faction:Alliance"]="格瑞林的困境揭示了联盟和铁炉堡军队在丹莫罗的兵力是何等捉襟见肘，迫使单独的斥候不得不对巨魔聚集地发动静默战争。",["race:Dwarf"]="直接效忠于国王麦格尼·铜须的格瑞林，代表了铁炉堡斥候那种静默而顽强的毅力，他们坚守着丹莫罗的边境，抵御着日益加剧的内部威胁。",["race:Gnome"]="刚经历诺莫瑞根惨剧的侏儒新兵们在寒脊山谷发现，格瑞林是一位非常欢迎任何能对抗霜鬃巨魔的能人巧手的矮人。"},sec={{t="王室指令",b="格瑞林·白须和他的兄弟森内尔受铁炉堡议会和国王麦格尼·铜须本人的直接命令被派往寒脊山谷。他们的任务非常明确：评估并消除当地霜鬃巨魔带来的威胁。由于铁炉堡的正规军已深陷于打击遍布丹莫罗的穴居人暴乱之中，兄弟俩在执行任务时得到的资源非常有限。格瑞林不得不在雪山中建立了一个前哨站，并寄希望于当地的招募者和路过的新手来完成必要的工作。"},{t="南方的麻烦",b="格瑞林在他的营地里监视着寒脊山谷以南不断入侵的霜鬃部族。这些巨魔变得越来越好斗，在他们山洞外发动的袭击也愈发大胆。在一次此类突袭中，一个身上涂满油彩的蛮兵，名为寒冷者格里尼尔，潜入了无人看守的营地，偷走了格瑞林的战地日记，里面记载着他至关重要的观察结果。由于不愿辜负国王的期望，格瑞林利用无畏的旅行者深入霜鬃巨魔的洞穴，找回被偷走的手稿，并确保他最终的军情能传达给卡拉诺斯的森内尔。"}},faq={{q="格瑞林·白须为什么会在这片雪地里？",a="格瑞林受铁炉堡议会和国王麦格尼·铜须的正式委任，负责调查并平定寒脊山谷的霜鬃巨魔威胁。由于矮人军队被困在其他地方对抗穴居人的威胁，格瑞林必须依靠独立的志愿者。",al={"格瑞林为何在此","格瑞林·白须的目的","谁是格瑞林·白须"}},{q="是谁偷了格瑞林的日记？",a="一个名叫寒冷者格里尼尔的霜鬃巨魔在格瑞林的营地无人看守时发动了突袭。格瑞林只瞥见了一个身上有明显标记的蛮兵带着他的战地笔记逃进了南方的巨魔洞穴。",al={"谁偷了日记","被盗日记的窃贼","格瑞林日记"}},{q="格瑞林的兄弟是谁？",a="他的兄弟是森内尔·白须，一名驻扎在山下卡拉诺斯镇的特工。格瑞林将他对巨魔动向的调查结果汇编成报告，并派遣可靠的信使直接送达给森内尔。",al={"格瑞林兄弟","森内尔·白须","谁是森内尔"}},{q="格瑞林的营地里还有谁？",a="没有记录显示他有同伴。他和他的兄弟森内尔被派去独自处理巨魔问题，所以格瑞林在能干的招募者到来之前几乎没有帮手，当巨魔突袭时，他的营地正处于无人看守的状态。",al={"白须营地npc","格瑞林有同伴吗","格瑞林的同伴"}},{q="铁炉堡为什么不派遣正规士兵来协助他？",a="铁炉堡的守卫和议会军队几乎全被遍布丹莫罗的穴居人虫害所牵制。这使得像格瑞林这样的斥候只能利用当地的招募者来解决区域性的威胁。",al={"为什么没有矮人军队","铁炉堡守卫在哪","为什么没有士兵"}}},fx={bc052fbe={q="格瑞林·白须是谁？",a="格瑞林·白须是代表铁炉堡议会和国王麦格尼·铜须派往寒脊山谷的调查员。他受命评估霜鬃巨魔的进犯动向，在白雪覆盖的山谷中设立了偏远营地，并依靠新招募的登山者击退巨魔，而矮人主力军则忙于他处。",al={"格瑞林是谁","格瑞林·白须的背景","白须是谁"}},d217c46a={q="格瑞林·白须站在哪一方？",a="格瑞林完全忠于铁炉堡王国和大联盟。他直接听命于铁炉堡议会，携带盖有国王麦格尼亲笔印记的密令，不遗余力地保护矮人领地免受外敌威胁。",al={"格瑞林·白须阵营","格瑞林为谁工作","格瑞林属于联盟吗"}},["6d2fc414"]={q="格瑞林·白须想要什么？",a="格瑞林希望尽快解决寒脊山谷南部的霜鬃巨魔问题。由于矮人卫兵正忙于抵御穴居人的入侵，他需要身强力壮的冒险者清剿凶暴的巨魔，从巨魔首领格里克尼尔手中夺回被偷走的日志，并把最终版侦察报告送给他在卡拉诺斯的兄弟。",al={"格瑞林想做什么","格瑞林·白须的目标","格瑞林需要什么"}}},fp="17,282,15.563.0,20.567.0,46.284.0,27.207.0,24.228.0,31.221.0,56.221.0"}
P.entries["npc:greta-mosshoof"] = {n="格雷塔·苔蹄",s="格雷塔·苔蹄是一位牛头人德鲁伊，隶属于费伍德森林南部的翡翠圣地，与翡翠之环结盟。她与暗夜精灵以及其他自然守护者并肩作战，调查蔓延在这片古老森林中的邪恶腐化，并指引侦察兵深入暗影议会的据点加德纳尔。",h="格雷塔·苔蹄是一位牛头人德鲁伊，隶属于费伍德森林南部的翡翠圣地，与翡翠之环结盟。她与暗夜精灵以及其他自然守护者并肩作战，调查蔓延在这片古老森林中的邪恶腐化，并指引侦察兵深入暗影议会的据点加德纳尔。",kw={"受污染的水","翡翠之环","翡翠圣地","费伍德森林","格雷塔·苔蹄","水之先知伊斯伦","加德纳尔"},ang={["class:Druid"]="对于致力于清除燃烧军团创伤的德鲁伊来说，格雷塔·苔蹄代表了塞纳里奥议会的合作精神，搁置了阵营偏见，只为恢复卡利姆多的荒野。",["race:Tauren"]="格雷塔展现了牛头人致力于治愈大地母亲创伤的奉献精神，即使是在遥远的北方，在那片曾经仅由暗夜精灵守护的土地上亦是如此。"},sec={{t="森林的守护者",b="格雷塔·苔蹄驻扎在费伍德森林南部边缘的翡翠圣地，与翡翠之环共同致力于对抗侵蚀这片古老森林的普遍腐化。她没有向第三次战争后留下的恶魔污染屈服，而是协调各方力量来了解并遏制这种扩散的腐烂。她的调查重点是费伍德森林被毒化的水源以及潜伏在加德纳尔内部的邪恶邪教徒。"},{t="打击暗影议会",b="格雷塔·苔蹄在揭露暗影议会从加德纳尔深处运作的阴谋方面发挥了关键作用。她意识到裂谷中受污染的泉水和邪恶结界直接导致了这片土地所遭受的病痛。为此，她招募旅行者采集受污染的水样，寻求远方海岸上的萨满祭司水之先知伊斯伦的协助，并拆除保护恶魔阴谋集团免受入侵的仪式火盆。"}},faq={{q="格雷塔·苔蹄是谁？",a="格雷塔·苔蹄是翡翠之环的一名牛头人成员，驻扎在费伍德森林的翡翠圣地。她协助旅行者和德鲁伊调查并消除正在毒害森林的恶魔枯萎病。",al={"格雷塔·苔蹄背景故事","格雷塔·苔蹄是谁","格雷塔 费伍德森林"}},{q="格雷塔·苔蹄属于哪个阵营？",a="格雷塔·苔蹄是翡翠之环的成员，这是一个致力于治愈自然的组织。因此，她会为联盟和部落的冒险者提供指引和任务。",al={"格雷塔·苔蹄是部落还是联盟","格雷塔·苔蹄声望","格雷塔阵营"}},{q="为什么格雷塔要派遣冒险者进入加德纳尔？",a="加德纳尔是暗影议会在费伍德森林的据点，他们负责向这片土地的水道排放恶魔胆汁，并维持庇护恶魔的结界。格雷塔指挥对加德纳尔的打击行动，以摧毁他们的仪式并净化被污染的泉水。",al={"为什么加德纳尔任务","格雷塔·苔蹄 加德纳尔","加德纳尔势力原因"}},{q="格雷塔·苔蹄与水之先知伊斯伦有什么联系？",a="格雷塔与居住在贫瘠之地海岸的一位睿智萨满水之先知伊斯伦是好友。当格雷塔发现费伍德森林中受污染的水样时，她会指引冒险者寻求伊斯伦的精神掌控能力来净化这些液体，以便它们能清除被毒化的泉水。",al={"格雷塔和伊斯伦","水之先知伊斯伦联系"}}},fp="14,297,22.465.0,30.441.1,22.202.0,43.181.0,47.265.0,55.268.0"}
P.entries["npc:grif-wildheart"] = {n="格瑞夫",s="格瑞夫是一位经验丰富的矮人猎人训练师，驻扎在卡拉诺斯的雷酒酿制厂外。他在当地的山地探险队员中享有盛名，因为他与野生动物有着深厚的渊源。他指导初出茅庐的神射手们学习追踪、射击以及驯服野兽的仪式。对于从寒脊山谷走出的年轻猎人来说，格瑞夫架起了一座至关重要的桥梁，让他们从只会开火的火枪手转变为与忠诚的动物伙伴并肩作战的猎人。",h="格瑞夫是一位经验丰富的矮人猎人训练师，驻扎在卡拉诺斯的雷酒酿制厂外。他在当地的山地探险队员中享有盛名，因为他与野生动物有着深厚的渊源。他指导初出茅庐的神射手们学习追踪、射击以及驯服野兽的仪式。对于从寒脊山谷走出的年轻猎人...",kw={"驯兽","丹莫罗","格瑞夫","猎人训练师","卡拉诺斯","山地探险队员","taming the beast","雷酒酿制厂"},ang={["class:Hunter"]="格瑞夫是引领联盟猎人掌握驯兽术的关键导师，他提供至关重要的任务，让你能够与漫游在丹莫罗各处的野外掠食者建立羁绊。",["faction:Alliance"]="格瑞夫驻扎在卡拉诺斯，他帮助联盟斥候和神射手在铁炉堡山城周围严酷的荒野中生存下来。",["race:Dwarf"]="格瑞夫体现了矮人山地探险队员的传统，他展示了矮人粗犷的坚韧如何使他们特别适合与凶猛的山地野兽并肩生活。"},sec={{t="野外生活",b="虽然许多铁炉堡的矮人更喜欢锻炉的热浪或镐头撞击的稳健节奏，但格瑞夫将自己的一生完全献给了丹莫罗冰封的荒野。当地的山地探险队员半开玩笑地说，他与四足野兽相处的时间太多了，但没人能否认他对野外生存的精通。在冰雪覆盖的山脊上与经验丰富的狩猎伙伴并肩追踪多年后，格瑞夫对漫游在岩石间的天然掠食者有着深刻的了解。"},{t="野兽之道",b="当年轻的矮人猎人在寒脊山谷完成初步试炼后，他们会直接前往卡拉诺斯寻求格瑞夫的指导。虽然他会磨练他们的准头并教授基本的野外生存技巧，但他真正的专长在于建立猎人与野兽之间的羁绊。通过一系列严格的试炼，格瑞夫会派遣他的学生带着驯兽棒进入冰冻荒原，在丹莫罗的标志性掠食者——大型岩石野猪、雪豹和冰爪熊面前考验他们的勇气。"},{t="前往Hall of Arms",b="一旦猎人证明了自己有足够的意志和镇定去安抚三头不同的野生野兽，格瑞夫在卡拉诺斯的教导就告一段落了。他意识到猎人还需要学习喂养、管教和训练他们的新盟友，于是他将毕业生们送上了前往铁炉堡的山路。在那里，在矮人主城的巨大拱顶之下，新手猎人会向高级野兽训练师报到，学习如何照料他们终身相伴的伙伴，这是一门更为深奥的艺术。"}},faq={{q="格瑞夫是谁？",a="格瑞夫是一位位于丹莫罗卡拉诺斯的矮人猎人训练师。他是联盟新手猎人学习狩猎技艺的主要导师，这些猎人通常是在离开寒脊山谷后开始学习的。",al={"格瑞夫是谁","格瑞夫的身份","关于格瑞夫"}},{q="我在哪里可以找到格瑞夫？",a="他站在卡拉诺斯村的雷酒酿制厂外，位于连接寒脊山小径和铁炉堡的雪路上。",al={"格瑞夫的位置","格瑞夫在哪里","卡拉诺斯的格瑞夫"}},{q="格瑞夫教导新手猎人什么？",a="除了提供通用的猎人技能和远程战斗技巧外，格瑞夫还指导年轻猎人完成驯服野兽的试炼，教他们如何安抚并驾驭野猪、豹和熊。",al={"格瑞夫教授什么","格瑞夫的猎人训练","格瑞夫的技能"}},{q="格瑞夫让猎人去驯服哪些野兽？",a="格瑞夫要求他的学生追踪并驯服丹莫罗的三种特定生物：大型岩石野猪、雪豹和冰爪熊。",al={"格瑞夫的驯兽任务","在丹莫罗驯服什么动物","taming the beast的目标"}},{q="完成驯兽试炼后，格瑞夫会把猎人送到哪里？",a="在证明了自己驯服野生动物的能力后，格瑞夫会指引猎人前往铁炉堡，向高级野兽训练师咨询有关喂养和指挥宠物的事宜。",al={"找格瑞夫之后去哪","training the beast的下一步","格瑞夫的后续任务"}},{q="铁炉堡的山地探险队员怎么看格瑞夫？",a="当地的铁炉堡山地探险队员指出，格瑞夫花在动物身上的时间比花在人身上的时间多，但他们也乐于承认，他比任何人都更精通猎人之道。",al={"山地探险队员对格瑞夫的看法","格瑞夫是否受人尊敬","格瑞夫的声望"}}},fx={["5a030de6"]={q="格瑞夫站在哪一方？",a="格瑞夫坚定地忠于铁炉堡和大联盟。他在卡拉诺斯教导年轻的矮人猎人，以此服务族人，确保他们掌握纪律和生存技能，能够保护这个山地王国及其领土。",al={"格瑞夫阵营","格瑞夫属于联盟吗","格瑞夫效忠于谁"}},a3b5e7f5={q="格瑞夫想要什么？",a="格瑞夫致力于传授荒野生存的技艺。他希望有志成为猎人的人掌握驯服野兽和野外求生的本领，派新手进入丹莫罗的雪地，学习尊重与耐心，并学会与山间生物建立长久的羁绊。",al={"格瑞夫的目标","格瑞夫想要什么","格瑞夫的动机"}},["20183458"]={q="格瑞夫为什么在卡拉诺斯？",a="格瑞夫驻扎在卡拉诺斯，训练从寒脊山谷下来的新兵。卡拉诺斯是丹莫罗的交通要道，也是年轻猎人的理想试炼场，他们可以在此考验自己，应对山中的野猪、豹子和熊。",al={"格瑞夫为什么在这里","格瑞夫为什么在丹莫罗","格瑞夫为什么在卡拉诺斯"}}},fp="14,424,19.495.0,20.507.0,27.472.0,22.187.0,32.138.0,36.200.0,43.152.0,66.188.0,49.198.0"}
P.entries["npc:grimbooze-thunderbrew"] = {n="葛瑞姆·雷酒",s="葛瑞姆·雷酒是一位古怪的雷酒氏族矮人酿酒师，他在西部荒野的匕首岭扎营。他终日致力于调制烈酒，且说话几乎全用诗句。",h="葛瑞姆·雷酒是一位古怪的雷酒氏族矮人酿酒师，他在西部荒野的匕首岭扎营。他终日致力于调制烈酒，且说话几乎全用诗句。",kw={"麦酒","酿酒师","匕首岭","酿制厂","葛瑞姆","卡拉诺斯","雷酒","西部荒野"},ang={["profession:Cooking"]="烹饪冒险家和烈酒工匠们推崇雷酒家族的遗产，这使得与葛瑞姆的邂逅成为了一堂手工酿酒课。",["race:Dwarf"]="每个矮人都知道雷酒这个名字，能在西部荒野的丘陵中发现雷酒兄弟中的一位正在酿制狂野的配方，这是一种令人怀念的丹莫罗风味。"},sec={{t="流亡的酿酒师",b="葛瑞姆来自卡拉诺斯赫赫有名的雷酒酿酒家族，他离开了丹莫罗积雪的山峰，来到了西部荒野风大丘陵。他以性情开朗和对烈酒的狂热而闻名，且有个独特的习惯，那就是只用押韵的句子说话。只有当旅者为他完成简单的任务后，他才会回答他们的问题。路过危险的匕首岭的旅者可以找到他，他当时正在照看自己的私酿酒桶，总是渴望着考验一下口渴旅者的味蕾。"}},faq={{q="我在哪里可以找到葛瑞姆·雷酒？",a="葛瑞姆·雷酒驻扎在西部荒野南部的匕首岭，他在丘陵间安营扎寨，随身带着他的酿酒设备。",al={"葛瑞姆位置","葛瑞姆在哪里","去哪里找葛瑞姆·雷酒"}},{q="为什么葛瑞姆要用押韵说话？",a="没人能说得准。葛瑞姆只是单纯喜欢诗句，而且他坚持认为任何有事想问他的人都必须先完成一个简单的任务。",al={"为什么葛瑞姆说话押韵","葛瑞姆押韵","他为什么用诗句说话"}},{q="他和雷酒酿制厂有什么联系？",a="葛瑞姆是丹莫罗卡拉诺斯著名的雷酒氏族的一员。虽然像拉格纳·雷酒这样的亲戚在老家照看着家族的酿制厂，但葛瑞姆在西部荒野的丘陵中独自酿酒。",al={"雷酒酿制厂","葛瑞姆和拉格纳有关系吗","雷酒家族"}}},fp="21,144,17.395.0,39.116.0,36.148.0,53.199.0"}
P.entries["npc:grish-longrunner"] = {n="瑞什·远行者",s="瑞什·远行者是一位驻扎在升降梯附近的牛头人侦察兵和信使，升降梯是连接南贫瘠之地与千针石林峡谷之间至关重要的机械通道。他在这条繁忙的边界线上为部落服务，监视过往旅客，并协调该边境地区的军事行动。",h="瑞什·远行者是一位驻扎在升降梯附近的牛头人侦察兵和信使，升降梯是连接南贫瘠之地与千针石林峡谷之间至关重要的机械通道。他在这条繁忙的边界线上为部落服务，监视过往旅客，并协调该边境地区的军事行动。",kw={"贫瘠之地","请求增援","升降梯","瑞什","远行者","牛头人","千针石林"},ang={["faction:Horde"]="对于前往南方千针石林或北上返回贫瘠之地的部落信使和战士来说，瑞什在升降梯处担任着重要的哨兵和联络点。",["race:Tauren"]="瑞什背负着“远行者”这个引以为傲的姓氏，代表着舒哈鲁在守护其祖先领地重要通道时的坚韧与警惕。"},sec={{t="升降梯守望者",b="瑞什·远行者驻守在升降梯那高耸的机械装置旁，监视着卡利姆多中部最险峻的边境通道之一。这座平台电梯是连接南贫瘠之地的荒原与下方千针石林被风吹拂的台地之间的生命线。在野猪人流寇和各方领土威胁的夹击下，沿着这条垂直边界旅行非常危险，这使得像瑞什这样的侦察兵对于维持部落的情报畅通以及在急需时召集援军显得至关重要。"}},faq={{q="瑞什·远行者是谁？",a="瑞什·远行者是一位效忠于部落的牛头人侦察兵，他驻扎在升降梯的边缘，这里是从贫瘠之地通往下方千针石林的必经之路。",al={"瑞什是谁","瑞什·远行者身份","瑞什做什么"}},{q="我在哪里可以找到瑞什·远行者？",a="他位于贫瘠之地的南端，就在通往千针石林的升降梯机械入口附近。",al={"瑞什·远行者位置","瑞什在哪里","找到瑞什"}},{q="他在该地区扮演什么角色？",a="瑞什是部落信使和旅行者的联络点，尤其在通过诸如“请求增援”之类的任务来召集和指挥当地援军方面提供协助。",al={"瑞什的目的","瑞什的任务","请求增援瑞什"}}},fx={["0053ed11"]={q="瑞什·远行者效忠于哪一方？",a="瑞什是自豪的牛头人部族成员，效忠于部落。他在贫瘠之地边境和通往千针石林的下坡路一带活动，为往来于危险区域之间的部落旅人提供联络。",al={"瑞什·远行者的阵营","瑞什是部落的吗","瑞什·远行者效忠哪一方"}}},fp="16,329,19.537.0,24.164.0,34.140.0,35.180.0"}
P.entries["npc:grub"] = {n="格拉布",s="格拉布是一位极具商业头脑的兽人，住在贫瘠之地十字路口以东的一间路边小屋里。他与一名厨师和一名面包师共同经营着一家简朴的边境餐馆，他因向旅客推广当地害虫的烹饪用途而闻名——或者说，臭名昭著。",h="格拉布是一位极具商业头脑的兽人，住在贫瘠之地十字路口以东的一间路边小屋里。他与一名厨师和一名面包师共同经营着一家简朴的边境餐馆，他因向旅客推广当地害虫的烹饪用途而闻名——或者说，臭名昭著。",kw={"贫瘠之地","十字路口","掘地鼠炖肉","杜恩","格拉布","塔班·炉谷"},ang={["faction:Horde"]="格拉布的路边厨房位于十字路口外，为在严酷平原上生存的部落旅行者提供了丰盛的食物和关于足智多谋的一课。",["profession:Cooking"]="对于有抱负的边境厨师来说，格拉布是一个必去之地，他乐于与任何有胆量收集食材的人分享掘地鼠炖肉的食谱。"},sec={{t="边境的胃口",b="格拉布的小屋坐落在十字路口以东的山崖旁，他与厨师杜恩，以及面包师塔班·炉谷共同住在这里。虽然贫瘠之地的生活需要一个强健的胃，但格拉布把这种边境自给自足的精神发挥到了极致。他不忍浪费贫瘠之地随处可见的掘地鼠，将它们变成了主要的食材，并主动教路过的流浪者如何将这些地下啮齿动物炖成一锅美味，尽管看起来并不怎么体面。"}},faq={{q="格拉布是谁？",a="格拉布是一位兽人，住在贫瘠之地十字路口以东的一间小屋里。他与厨师杜恩和面包师塔班·炉谷一起经营着一个小餐馆，为经过这片尘土飞扬的边境的旅客提供服务。",al={"格拉布","格拉布是谁","十字路口以东的兽人"}},{q="在哪里能找到格拉布？",a="格拉布位于贫瘠之地十字路口以东，山脚下，主路旁的一间小屋内。",al={"格拉布位置","格拉布在哪里","格拉布的小屋"}},{q="格拉布需要什么帮助？",a="格拉布委托旅客在贫瘠之地收集掘地鼠，用来制作他的招牌菜：掘地鼠炖肉。作为交换，他会将食谱传授给愿意烹饪它的厨师。",al={"格拉布任务","掘地鼠炖肉任务"}}},fx={["1dd1f89b"]={q="格拉布效忠于哪一方？",a="格拉布是与部落结盟的兽人，平和地生活在贫瘠之地十字路口外。他欢迎部落旅人来到自己的小家园，与其他厨师、面包师和过路的冒险者做生意，不卷入军事冲突。",al={"格拉布的阵营","格拉布是部落的吗","格拉布属于联盟还是部落"}},bef281f8={q="格拉布为什么在这里？",a="格拉布在十字路口以东、山脚下建起了一处小型居住点。他没有前往前线服役，而是与厨师杜恩和面包师塔班·炉谷一起经营一处烹饪居所，搜集并烹制当地边境风味的食物。",al={"格拉布为什么在贫瘠之地","格拉布的十字路口小屋","格拉布在这里做什么"}},c7807b4d={q="格拉布和谁有联系？",a="格拉布与杜恩共住路边小屋，杜恩负责烹饪；面包师塔班·炉谷则负责烘焙。这群不寻常的伙伴在贫瘠之地崎岖的平原上共同经营着他们的小小炉火之家。",al={"格拉布和谁共事","格拉布的同伴","格拉布的伙伴"}}},fp="4,263,19.477.0,12.229.0,22.144.0,30.181.0"}
P.entries["npc:grull-hawkwind"] = {n="格鲁尔·鹰风",s="格鲁尔·鹰风是一名驻扎在莫高雷红云台地纳拉其营地的牛头人勇士。作为鹰风酋长的儿子，他负责指引初出茅庐的牛头人踏出探索世界的第一步。他指导年轻的猎人和战士完成最初的试炼，以考验他们的意志并向先祖致敬。",h="格鲁尔·鹰风是一名驻扎在莫高雷红云台地纳拉其营地的牛头人勇士。作为鹰风酋长的儿子，他负责指引初出茅庐的牛头人踏出探索世界的第一步。他指导年轻的猎人和战士完成最初的试炼，以考验他们的意志并向先祖致敬。",kw={"纳拉其营地","鹰风酋长","格鲁尔·鹰风","莫高雷","红云台地","力量试炼","牛头人"},ang={["class:Hunter"]="格鲁尔为新手猎人提供基础的早期任务，通过莫高雷的动物群来考验他们的耐心和技巧。",["race:Tauren"]="对于踏上红云台地的年轻牛头人来说，格鲁尔·鹰风往往是第一个考验他们勇气并向他们介绍舒哈鲁传统的人。"},sec={{t="酋长之子",b="格鲁尔·鹰风自豪地站在纳拉其营地的勇士和长者身旁，肩负着继承鹰风酋长显赫家世的重任，同时也承担着培养部族年轻一代的责任。作为红云台地新来者的启蒙导师，他负责评估他们为舒哈鲁效力的准备情况。通过指派考验耐力、追踪能力以及与平原陆行鸟和山地美洲狮等当地野兽战斗的试炼，格鲁尔确保年轻的牛头人明白，平衡与对自然的尊重是莫高雷生活的基础。"}},faq={{q="格鲁尔·鹰风是谁？",a="格鲁尔·鹰风是一位居住在红云台地纳拉其营地的牛头人任务发布者。他是该定居点领袖鹰风酋长的儿子，也是年轻牛头人开始旅程时的主要导师之一。",al={"格鲁尔·鹰风的角色","格鲁尔是谁","格鲁尔·鹰风背景故事"}},{q="格鲁尔·鹰风对年轻冒险者起什么作用？",a="格鲁尔负责评估新手牛头人的基础训练，接收来自部族长者的介绍性说明，并委派年轻人执行关于狩猎和生存的初步试炼。",al={"格鲁尔的任务","格鲁尔做什么","格鲁尔·鹰风的职责"}},{q="格鲁尔与营地的领导层有亲属关系吗？",a="是的，格鲁尔是纳拉其营地酋长鹰风酋长的儿子。他秉承父亲的传统，协助培养营地的保卫者。",al={"鹰风酋长之子","格鲁尔·鹰风的家庭","格鲁尔与酋长有亲属关系吗"}}},fx={["36d17655"]={q="格鲁尔·鹰风效忠于哪一方？",a="格鲁尔·鹰风自豪地支持牛头人部族和部落。他居住在纳拉其营地，在父亲兼大酋长凯恩·血蹄的领导下为族人效力，致力于帮助年轻的牛头人成长为合格的守卫者，保卫他们在莫高雷的祖居地。",al={"格鲁尔·鹰风的阵营","格鲁尔为谁效力","格鲁尔·鹰风效忠哪一方"}},["56962b2d"]={q="格鲁尔·鹰风想要什么？",a="格鲁尔希望看到年轻的牛头人证明自己的力量和对部族的忠诚。他会考验前来受训的年轻人，确保他们具备在荒野中生存、保护纳拉其营地免受附近威胁所需的毅力、纪律和狩猎技巧。",al={"格鲁尔想要什么","格鲁尔·鹰风的目标","格鲁尔为什么发布任务"}},["379dd378"]={q="格鲁尔·鹰风为什么在纳拉其营地？",a="纳拉其营地是红云台地上年轻人通过成年仪式的祖传试炼之地，由格鲁尔的父亲鹰风酋长管理。格鲁尔留在这里，帮助引导新晋者完成入门仪式，并协助家族管理营地。",al={"格鲁尔为什么在这里","格鲁尔在纳拉其营地的职责","格鲁尔为什么在红云台地"}}},fp="14,320,17.542.0,22.230.0,57.194.0,42.146.0"}
P.entries["npc:grunt-dogran"] = {n="步兵多格兰",s="步兵多格兰是部落的一名兽人战士，被俘虏在南贫瘠之地的野猪人领地深处。他最初被派往十字路口，后来转至陶拉祖营地，他在一次对阿迦玛戈的突袭中遭遇了惨败。",h="步兵多格兰是部落的一名兽人战士，被俘虏在南贫瘠之地的野猪人领地深处。他最初被派往十字路口，后来转至陶拉祖营地，他在一次对阿迦玛戈的突袭中遭遇了惨败。",kw={"阿迦玛戈","贫瘠之地","陶拉祖营地","十字路口","多格兰","步兵多格兰","野猪人"},ang={["faction:Horde"]="他的被俘展示了部落驻军为在贫瘠之地保护商路和边境免受好战的野猪人部落侵扰所付出的巨大代价。",["race:Orc"]="多格兰体现了兽人的传统理想，即在战斗中牺牲比作为无助的残废苟活更光荣。"},sec={{t="步兵的职责",b="在部落军队晋升后，步兵多格兰被从十字路口派遣至陶拉祖营地进行增援。在带领一支步兵小队进入刺鬃野猪人的领地阿迦玛戈时，他的部队发生了激烈的冲突。在战斗中，多格兰身受重伤导致残疾，无法被撤退的战友带走，最终被拖走囚禁了起来。"},{t="荣耀的归宿",b="尽管深陷敌后且因伤残疾，多格兰仍保持着兽人战士特有的固执自尊。他宁愿在与野猪人的最后决战中牺牲，也不愿残废地回到家中，强迫自己的伴侣照顾一个废人；他只请求将一件代表他永恒爱意的信物带回给挚爱之人。"}},faq={{q="步兵多格兰在哪里？",a="多格兰被囚禁在阿迦玛戈，这是一个位于南贫瘠之地、陶拉祖营地以北的密集野猪人营地。",al={"多格兰位置","多格兰在哪里","在贫瘠之地寻找多格兰"}},{q="多格兰为什么会被野猪人俘虏？",a="在带领巡逻队从陶拉祖营地出击进攻野猪人时，多格兰在冲突中身受重伤，致使残疾。他的战友没能及时将他救出，让他只能任由这些野兽摆布。",al={"多格兰为何被俘","多格兰是如何被抓的"}},{q="为什么多格兰拒绝被营救？",a="多格兰在战斗中永久致残，他不愿作为伴侣的负担回到家中。以典型的兽人方式，他宁愿按自己的意愿在与野猪人的战斗中死去，也不愿作为废人度过余生。",al={"多格兰为何不愿离开","营救多格兰"}},{q="谁在寻找多格兰？",a="他在奥格瑞玛的伴侣赞卡沙，自从他去执行任务后，她就再也没有收到过他的消息。她的担忧促使旅行者前往十字路口的加兹罗格，随后又前往陶拉祖营地的步兵劳格玛，士兵们在那里拼凑出了他失踪巡逻队的下落。",al={"谁派遣寻找多格兰","多格兰任务接取"}}},fx={["3efd280a"]={q="步兵多格兰是谁？",a="步兵多格兰是部落的一名兽人战士。晋升后，他先被派驻十字路口，之后调往陶拉祖营地。在率领一队步兵进入南贫瘠之地对付刺背野猪人时，他在战斗中身受重伤，失去了行动能力，并被这些浑身尖刺的野兽俘虏。如今他被绑在它们位于阿迦玛戈的营地里。",al={"多格兰是谁","步兵多格兰的身份","多格兰的故事"}},["30754355"]={q="步兵多格兰效忠于哪一方？",a="多格兰是部落忠诚的士兵。他自豪地在大酋长麾下担任步兵，驻扎在贫瘠之地，保护部落据点和定居点免受剃刀沼泽野猪人、刺背野猪人等敌对势力的侵袭。",al={"多格兰是部落的吗","多格兰效忠哪一方","多格兰的阵营"}}},fp="12,236,14.400.0,17.335.1,30.126.0,40.210.0,37.209.1,26.243.0"}
P.entries["npc:grunt-logmar"] = {n="步兵劳格玛",s="步兵劳格玛是一名驻扎在南贫瘠之地陶拉祖营地的部落兽人战士。他尽职尽责且保持警惕，负责监控营地周边的威胁，并协调寻找和援助该地区失踪部落侦察兵的工作。",h="步兵劳格玛是一名驻扎在南贫瘠之地陶拉祖营地的部落兽人战士。他尽职尽责且保持警惕，负责监控营地周边的威胁，并协调寻找和援助该地区失踪部落侦察兵的工作。",kw={"陶拉祖营地","多格兰","步兵劳格玛","肯兹格拉的伤药","兽人步兵","陶拉祖","贫瘠之地"},ang={["faction:Horde"]="劳格玛代表了支持贫瘠之地牛头人的前线军事力量，并依靠部落勇士来照看阵亡和被俘的侦察兵。",["race:Orc"]="作为一名远离奥格瑞玛驻扎的兽人步兵，劳格玛展现了部落与牛头人盟友并肩作战的承诺。"},sec={{t="陶拉祖营地的职责",b="步兵劳格玛驻扎在陶拉祖营地的牛头人中间，作为一名警惕的兽人卫兵守护着南贫瘠之地的边境。这座定居点毗邻充满敌意的野猪人领地，以及通往Stonetalon和莫高雷的山隘，因此需要时刻保持警惕。劳格玛负责协调侦察报告，并在他的同伴遭到当地敌对势力的伏击或俘虏时，向有能力的部落旅者寻求帮助。"}},faq={{q="谁是步兵劳格玛？",a="步兵劳格玛是一名驻扎在南贫瘠之地陶拉祖营地的兽人士兵，他通过保卫定居点以及监督救援和侦察任务来为部落服务。",al={"步兵劳格玛","劳格玛是谁","劳格玛 贫瘠之地"}},{q="在哪里可以找到步兵劳格玛？",a="他位于陶拉祖营地，这是一个坐落在贫瘠之地南部的哨站，位于通往升降梯和千针石林的道路沿线。",al={"劳格玛在哪里","劳格玛位置","寻找步兵劳格玛"}},{q="劳格玛负责什么事务？",a="劳格玛负责失踪部落侦察兵的安全事宜，特别是委托旅者调查步兵多格兰的失踪与被俘情况，并确保获得诸如肯兹格拉的伤药之类的补给品。",al={"劳格玛任务","劳格玛想要什么","多格兰救援"}}},fx={ce116068={q="步兵劳格玛效忠于哪一方？",a="步兵劳格玛是部落忠诚的士兵。他驻扎在牛头人定居点外围，为大酋长效力，监视南部边境，并支援部落在平原各地的行动。",al={"劳格玛是部落的吗","步兵劳格玛的阵营","步兵劳格玛效忠哪一方"}},["1f3f5c49"]={q="步兵劳格玛为什么在这里？",a="劳格玛作为前哨卫兵驻守此地，以加强防御并保持军事联络。周围的荒野时刻受到敌对野生动物、半人马掠夺者和附近野猪人的威胁，因此需要坚定的士兵保护旅人，确保南贫瘠之地安全。",al={"步兵劳格玛为什么在这里","劳格玛为什么在陶拉祖营地","劳格玛的驻地"}},e7dd0701={q="步兵劳格玛想要什么？",a="劳格玛希望有人帮助解决当地紧迫的军事危机，尤其是营救并找回被俘的战友，例如多格兰；此外还要找到恢复药剂，以支撑战友们在前线作战。",al={"劳格玛想要什么","步兵劳格玛的目标","步兵劳格玛需要什么"}}},fp="12,235,20.419.0,20.174.0,32.155.0,33.201.0"}
P.entries["npc:grunth"] = {n="Grunth",s="Grunth是一个精力充沛的年轻兽人孤儿，住在奥格瑞玛精神谷的孤儿院中。在儿童周期间，他会热切地陪伴部落勇士们踏上横跨卡利姆多和东部王国的伟大旅程，去了解英雄的真正含义。",h="Grunth是一个精力充沛的年轻兽人孤儿，住在奥格瑞玛精神谷的孤儿院中。在儿童周期间，他会热切地陪伴部落勇士们踏上横跨卡利姆多和东部王国的伟大旅程，去了解英雄的真正含义。",kw={"儿童周","grunth","兽人孤儿","奥格瑞玛","孤儿监护员巴特维尔","孤儿哨","精神谷"},ang={["faction:Horde"]="在儿童周期间指导Grunth，提醒着部落的勇士们他们的阵营在为什么而奋斗：保护那一代诞生于自由而非恶魔奴役下的后起之秀。",["race:Orc"]="Grunth体现了杜隆塔尔的青年一代，他们成长过程中了解的是部落荣誉与生存，而不是集中营里那昏暗的颓废。"},sec={{t="一个好奇的部落孩子",b="Grunth住在奥格瑞玛的精神谷，在孤儿监护员巴特维尔的注视下成长，代表着新建立的部落的下一代。像许多在杜隆塔尔严酷的红色荒野中长大的绿皮小家伙一样，他用惊奇的目光注视着全副武装的冒险者，并有问不完的问题——想知道全副武装的战士是否真的那么可怕，为什么水上的闪电不会杀死所有的鱼，以及他是否能亲眼看到有人与真正的龙战斗。"},{t="儿童周之旅",b="当节日来临时，冒险者会吹响兽人孤儿哨召唤Grunth，并带着他进行一场环游世界的旅行。他的愿望清单涵盖了部落领地的广阔范围：在莫高雷觐见大酋长凯恩·血蹄，冒险进入洛丹伦那残破的王座大厅，并造访他的族人为未来而战的崎岖边疆。"}},faq={{q="Grunth是谁？",a="Grunth是一个住在奥格瑞玛精神谷孤儿院的兽人小孩。他由孤儿监护员巴特维尔照顾，梦想着成为部落的传奇英雄。",al={"grunth npc","兽人孤儿","奥格瑞玛孤儿"}},{q="在哪里可以找到Grunth？",a="他和其他孤儿一起待在奥格瑞玛的精神谷，但在儿童周期间，冒险者可以使用从孤儿监护员巴特维尔那里获得的兽人孤儿哨在任何地方召唤他。",al={"grunth位置","grunth在哪里","寻找grunth"}},{q="Grunth想去哪些地方参观？",a="Grunth渴望看到部落最伟大的标志。他想去的地方包括前往雷霆崖拜访大酋长凯恩·血蹄、参观棘齿城码头，以及一路前往洛丹伦那残破的王座大厅。",al={"grunth任务","孤儿想要什么","grunth旅行"}},{q="Grunth的性格如何？",a="Grunth大声喧哗、充满好奇心且想象力丰富。他不断向带领他的冒险者提出荒谬的谜题和孩子气的问题，比如询问“zug zug”到底是什么意思，没有翅膀的苍蝇是不是叫“走（walk）”，还会随口提到他把一块石头塞进了鼻子里。",al={"grunth语录","grunth对话","grunth说什么"}}},fx={ec5570c7={q="格鲁恩斯效忠于哪一方？",a="格鲁恩斯完全属于部落。他在奥格瑞玛长大，由孤儿监护员巴特维尔照料。他仰慕部落的英雄，梦想亲眼见证伟大的壮举，比如看一位英雄与凶猛的巨龙交战。",al={"格鲁恩斯属于部落还是联盟","格鲁恩斯是部落的吗","格鲁恩斯的阵营"}},["06889c57"]={q="格鲁恩斯为什么在奥格瑞玛？",a="格鲁恩斯是名兽人孤儿，住在奥格瑞玛贫民窟的孤儿院，由孤儿院照料。儿童周期间，他获准与一位经验丰富的部落冒险者同行，探索世界；这位冒险者会回答他热切提出的问题，让他见识更广阔的世界。",al={"格鲁恩斯为什么在这里","格鲁恩斯为什么在奥格瑞玛","格鲁恩斯为何在此地"}},["0a265be0"]={q="格鲁恩斯和谁有联系？",a="格鲁恩斯由奥格瑞玛孤儿院的孤儿监护员巴特维尔照料。她照看这个年幼的兽人，并将他托付给愿意指导他、带他游历卡利姆多乃至更远地方的部落冒险者。",al={"谁在照料格鲁恩斯","格鲁恩斯的关系","格鲁恩斯与孤儿监护员"}}},fp="6,260,28.483.0,24.393.0,14.169.0,26.194.0,38.226.0,42.291.0"}
P.entries["npc:gryan-stoutmantle"] = {n="格里安·斯托曼",s="格里安·斯托曼是一位白银之手圣骑士，同时也是人民军的指挥官，在西部荒野的哨兵岭开展行动。他出生于西部荒野，在暴风城王室抛弃该地区导致匪患横行后，他从饱受战火蹂躏的北方王国洛丹伦返回家乡，以此守护自己的故土。",h="格里安·斯托曼是一位白银之手圣骑士，同时也是人民军的指挥官，在西部荒野的哨兵岭开展行动。他出生于西部荒野，在暴风城王室抛弃该地区导致匪患横行后，他从饱受战火蹂躏的北方王国洛丹伦返回家乡，以此守护自己的故土。",kw={"死亡矿井","格里安","人民军","哨兵岭","白银之手","斯托曼","范克里夫","西部荒野","威利"},ang={["class:Paladin"]="斯托曼是白银之手职责的活生生例证：当教会和王室的高层无视穷人时，他将圣光的庇护直接带给了最需要它的朴实农民。",["faction:Alliance"]="格里安对独立志愿者的依赖揭示了联盟腹地内痛苦的裂痕，暴风城的政治不作为迫使忠诚的公民拿起武器保卫自己。",["race:Human"]="格里安出生于西部荒野，代表了暴风城农村居民的韧性，他们坚定地对抗着地区强盗，同时也对抗着来自首都的官僚主义遗弃。"},sec={{t="一位回归的骑士",b="格里安·斯托曼的服役生涯始于远离艾泽拉斯南部宁静田野的地方。他年轻时前往北方的洛丹伦，成为了一名白银之手骑士，并亲历了第三次战争的恐怖。当他得知自己的家乡西部荒野正陷入无法无天的境地，被有组织的强盗横行，且被王室抛弃时，格里安离开了北方前线。他放弃了帝国战场，转而投身于保护朴实的农民，发誓绝不让自己的家乡重蹈北方的覆辙。"},{t="人民军",b="回到家乡后，格里安发现西部荒野几乎处于毫无防备的状态。由于王室的疏忽和贵族议会内部的政治瘫痪，暴风城拒绝派遣驻军。作为回应，斯托曼在哨兵岭建立了人民军，将当地的农民、卫兵和四处游荡的雇佣兵集结成一支志愿防卫部队。他的军队在对抗迪菲亚潜行者、河爪豺狼人和敌对机械生物时只能勉强维持防线，甚至在湖畔镇等邻近定居点请求援助时也无力提供增援。"},{t="揭开幕后黑手的真面目",b="为了不盲目作战，斯托曼求助于一个庞大的情报网络，试图查明是谁在操纵西部荒野的毁灭。格里安通过追讨赤脊山黑衣威利的一笔旧账，并与军情七处的Mathias Shaw商议，最终看穿了真相：这些强盗的首领正是艾德温·范克里夫，这位曾经的石匠工会大师，因怀才不遇而心怀怨恨。在民兵抓获一名试图抢劫当地货车的强盗后，格里安利用这名叛徒确定了迪菲亚潜行者在月溪镇下方死亡矿井中的藏身处，并委派资深勇士直接前去击败范克里夫。"}},faq={{q="格里安·斯托曼是谁？",a="格里安·斯托曼是一位白银之手圣骑士，也是人民军的创始人和指挥官，这支志愿驻军的总部设在哨兵岭，负责保卫西部荒野。",al={"格里安是谁","斯托曼背景故事","西部荒野领袖"}},{q="如果西部荒野属于暴风城，为什么还需要人民军？",a="暴风城的贵族议会拒绝派遣王室士兵或动用财政资金来保护这一边远行省。在被抛弃面对掠夺者和豺狼人的情况下，当地农民在格里安的领导下组建了自己的独立防卫力量。",al={"为什么需要民兵","暴风城军队在哪","暴风城为何放弃西部荒野"}},{q="格里安与白银之手有什么历史？",a="格里安在年轻时前往洛丹伦，成为了一名白银之手的圣骑士。他在第三次战争期间曾服役于北方战场，随后离开北方回援他那身陷危机的家乡。",al={"格里安是圣骑士吗","格里安白银之手","洛丹伦时期的格里安"}},{q="为什么格里安拒绝向湖畔镇提供援助？",a="当湖畔镇的所罗门镇长请求增援以对抗赤脊山的豺狼人和兽人时，格里安被迫拒绝了。人民军在守卫哨兵岭时已经精疲力竭，几乎达到了崩溃的极限；即使派出一小支分遣队，也会导致西部荒野沦陷于迪菲亚潜行者之手。",al={"所罗门镇长请求","援助赤脊山","为什么不派兵去湖畔镇"}},{q="格里安是如何发现迪菲亚潜行者藏身之处的？",a="格里安向黑衣威利和Mathias Shaw寻求情报，随后请冒险者去调查潜行者。随后的发现将在剧透部分中详细描述。",al={"寻找死亡矿井","谁发现了范克里夫","迪菲亚叛徒故事"}},{q="黑衣威利对格里安来说是谁？",a="黑衣威利是一位居住在湖畔镇旅店的联络人，他曾欠格里安一条命。尽管斯托曼对这个潜行者卑劣的本性并无好感，但他利用这笔人情债获得了关于迪菲亚潜行者行动的关键情报。",al={"威利与格里安","黑衣威利的债务"}}},fp="17,202,22.446.0,20.495.0,21.540.1,25.163.0,68.209.0,45.185.0,47.256.0,52.167.1,32.195.0"}
P.entries["npc:guard-berton"] = {n="卫兵伯尔顿",s="卫兵伯尔顿是一名驻扎在赤脊山湖畔镇旅店外的城镇卫兵。由于对暴风城法律体系中官僚作风导致的延误感到沮丧，他寻求对被囚禁的兽人领袖——可怕的塔格尔——实施迅速的正义制裁。",h="卫兵伯尔顿是一名驻扎在赤脊山湖畔镇旅店外的城镇卫兵。由于对暴风城法律体系中官僚作风导致的延误感到沮丧，他寻求对被囚禁的兽人领袖——可怕的塔格尔——实施迅速的正义制裁。",kw={"伯尔顿","卫兵伯尔顿","湖畔镇","赤脊山","塔格尔","可怕的塔格尔","监狱","恶有恶报"},ang={["faction:Alliance"]="伯尔顿代表了农村联盟定居点中日益增长的挫败感，当地守军眼睁睁看着暴风城的中央官僚机构延误正义，而边境城镇却在为生存而战。"},sec={{t="寻求正义的卫兵",b="当赤脊山在黑石兽人入侵的威胁下摇摇欲坠时，卫兵伯尔顿仍然坚守在湖畔镇旅店外。尽管当地防御力量已濒临崩溃，伯尔顿却将注意力集中在一名俘虏身上：可怕的塔格尔。塔格尔因其对王国的罪行被捕并关押在暴风城监狱深处，被判处死刑。然而，由于暴风城的死刑执行被无限期推迟，伯尔顿拒绝让这个残暴的劫掠者在湖畔镇流血牺牲时继续苟活在牢房里。他决定亲自采取行动，雇佣愿意帮忙的冒险者绕过王国的拖延，直接处决这名兽人。"}},faq={{q="卫兵伯尔顿是谁？",a="卫兵伯尔顿是一名驻扎在赤脊山湖畔镇旅店外的联盟卫兵。他最主要的身份是雇佣冒险者，对一名臭名昭著的兽人囚犯执行正义。",al={"伯尔顿 湖畔镇","伯尔顿是谁"}},{q="卫兵伯尔顿为什么要杀死可怕的塔格尔？",a="可怕的塔格尔因其罪行被判处死刑，但暴风城的领导层搁置了这一判决。由于在赤脊山仍处于围困状态时对这种拖延感到沮丧，伯尔顿安排人在监狱中除掉塔格尔。",al={"为什么要杀死塔格尔","塔格尔的处决","恶有恶报任务背景"}},{q="可怕的塔格尔被关押在哪里？",a="塔格尔被关押在监狱中，这是一座位于暴风城运河区的高安全级别地下城。",al={"塔格尔的位置","塔格尔在哪里"}},{q="在哪里可以找到卫兵伯尔顿？",a="他站在湖畔镇旅店入口外值守，可以俯瞰湖畔镇的中心地带。",al={"伯尔顿在哪里","伯尔顿的位置"}}},fx={["352370f6"]={q="卫兵伯尔顿效忠哪一方？",a="卫兵伯尔顿是暴风王国与联盟的忠诚守卫。他驻扎在赤脊山，职责是保护饱受困扰的湖畔镇及其居民，抵御周边荒野的种种威胁，包括四处劫掠的黑石兽人。",al={"伯尔顿的阵营","卫兵伯尔顿效忠谁","伯尔顿是联盟成员吗"}},bd53caa6={q="卫兵伯尔顿与谁有关联？",a="伯尔顿是驻扎在湖畔镇的赤脊山卫兵之一，与同伴们一同守卫当地旅店外侧。除了当地驻军的职责外，他的仇怨还与可怕的塔格尔直接相关。这个臭名昭著的囚犯被关押在暴风城监狱中。",al={"卫兵伯尔顿的关联人物","伯尔顿与城镇卫兵","伯尔顿与谁共事"}}},fp="12,240,23.633.0,20.196.0,52.246.0,32.119.0,32.117.0"}
P.entries["npc:guard-howe"] = {n="卫兵豪维",s="卫兵豪维是一名驻守在赤脊山止水湖大桥南端脚下的城镇卫兵。由于对不断侵蚀该山谷的黑石兽人怀有私仇，他会向任何愿意消灭入侵者的冒险者提供悬赏。",h="卫兵豪维是一名驻守在赤脊山止水湖大桥南端脚下的城镇卫兵。由于对不断侵蚀该山谷的黑石兽人怀有私仇，他会向任何愿意消灭入侵者的冒险者提供悬赏。",kw={"黑石悬赏","黑石兽人","卫兵豪维","豪维","湖畔镇","赤脊山"},ang={["faction:Alliance"]="湖畔镇几乎得不到暴风城的直接援助，这使得像豪维这样的前线卫兵必须依靠到访的联盟勇士来防止黑石兽人淹没整个城镇。"},sec={{t="桥上的恩怨",b="卫兵豪维位于横跨止水湖的大石桥南侧，驻守在湖畔镇的中心地带。和这座饱受困扰的城镇中的许多人一样，他将黑石兽人的入侵视为对赤脊山的生存威胁。由于对该部族怀有强烈的复仇欲望，豪维会积极招募路过的雇佣兵前往东部丘陵猎杀兽人，并以他们的首级作为赏金交换。"}},faq={{q="卫兵豪维是谁？",a="卫兵豪维是一名人类城镇卫兵，驻扎在赤脊山湖畔镇的大桥南侧。他协助保卫定居点，并引导有能力的战士反击入侵的黑石兽人。",al={"卫兵豪维","豪维 湖畔镇","豪维是谁"}},{q="为什么卫兵豪维要杀死黑石兽人？",a="豪维对黑石氏族怀有私仇，该氏族已经深入赤脊山，使湖畔镇承受了巨大的压力。他寻求复仇，并向任何能削弱兽人势力的人提供悬赏。",al={"为什么悬赏黑石","豪维 兽人","为什么豪维痛恨兽人"}},{q="卫兵豪维在这一地区有亲属吗？",a="他与所罗门·豪维同姓，这表明他们可能是亲属，尽管他只专注于守卫城镇和对抗兽人的职责。",al={"豪维的亲属","所罗门·豪维的关系"}}},fx={["59b92c48"]={q="卫兵豪维效忠哪一方？",a="卫兵豪维效忠暴风王国，是湖畔镇卫兵的一员。他驻扎在赤脊山前线，奋力保护当地的人类居民，抵御不断侵扰边境的威胁。",al={"卫兵豪维的阵营","卫兵豪维是联盟成员吗","卫兵豪维效忠谁"}},d5289960={q="卫兵豪维为什么在这里？",a="卫兵豪维驻扎在湖畔镇桥梁以南不远处，负责监视城镇外围。赤脊山正遭受豺狼人围攻，黑石兽人也不断逼近，因此这座桥是重要的通道，也是必须防范突袭的关键隘口。",al={"卫兵豪维为什么在湖畔镇","卫兵豪维的驻守地点","卫兵豪维为何守桥"}}},fp="10,269,22.433.0,18.224.0,47.229.0,51.156.0"}
P.entries["npc:guard-thomas"] = {n="卫兵托马斯",s="卫兵托马斯是暴风城军队的一名忠诚士兵，驻扎在东谷伐木场西侧的桥梁上。他独自守卫在艾尔文森林的东部边境，负责保护当地定居者免受掠食性野生动物和入侵鱼人的威胁。",h="卫兵托马斯是暴风城军队的一名忠诚士兵，驻扎在东谷伐木场西侧的桥梁上。他独自守卫在艾尔文森林的东部边境，负责保护当地定居者免受掠食性野生动物和入侵鱼人的威胁。",kw={"东谷","东谷伐木场","艾尔文森林","卫兵托马斯","失踪卫兵","鱼人","暴风城军队","托马斯"},ang={["class:Warrior"]="对于联盟的年轻战士来说，托马斯代表了前线的纪律，以及边境防御现实中不那么光鲜的一面。",["faction:Alliance"]="卫兵托马斯体现了暴风城军队兵力不足的现状，他在没有王室提供多少支持的情况下，坚守着边境的一处重要哨所。"},sec={{t="在东部边境",b="当王国的大部分注意力都集中在首都或者西部的西部荒野时，卫兵托马斯坚守着艾尔文森林中最安静但也最危险的哨位之一。托马斯驻扎在横跨河流、通往东谷伐木场的石桥上，他是在日常工作的伐木工人和森林中横行的凶猛生物之间筑起的一道薄弱的防线。由于暴风城兵力吃紧，像托马斯这样的卫兵只能严重依赖路过的冒险者来维持秩序，并向中央指挥部传递信息。"},{t="边境的麻烦",b="艾尔文森林的东部边缘正面临着持续的压力。凶猛的熊和潜行者在林线徘徊，威胁着伐木工和路人，与此同时，奇异的鱼人部落沿着水道建立了营地。托马斯追踪着这些水生掠食者的行踪，并发布悬赏令来减少它们的数量。更糟糕的是，沿着河流巡逻的侦察兵偶尔会离奇失踪，这让托马斯不得不在此地日益动荡的局势中拼凑出他同僚们的命运。"}},faq={{q="我在哪里可以找到卫兵托马斯？",a="卫兵托马斯驻扎在艾尔文森林东部道路旁，横跨河流、位于东谷伐木场正西方的石桥上。",al={"卫兵托马斯位置","托马斯在哪里","卫兵托马斯桥梁"}},{q="卫兵托马斯在艾尔文森林的职责是什么？",a="他是暴风城军队的一名军官，被指派保护艾尔文的东部边境。他的职责包括确保贸易桥梁的安全，保护附近的工人免受野生掠食者的侵害，以及监视河流沿岸鱼人的敌对入侵活动。",al={"托马斯做什么","卫兵托马斯职责","托马斯东谷"}},{q="为什么卫兵托马斯要请求帮助寻找失踪的卫兵？",a="被派往流域进行巡逻的士兵没有按时汇报。由于没有足够的增援让他离开岗位，托马斯只能招募路过的冒险者去搜索水道，查明他失踪同僚的下落。",al={"艾尔文森林失踪卫兵","卫兵托马斯失踪侦察兵","卫兵发生了什么"}},{q="为什么鱼人对卫兵托马斯来说是个问题？",a="鱼人部落正越来越多地潜入东艾尔文的河流系统。它们日益增长的威胁不仅影响了当地的伐木作业，也威胁到了陆路补给路线，这促使托马斯悬赏收集鱼人鳍，以保持水道的畅通。",al={"东谷鱼人","为什么要杀鱼人","卫兵托马斯鱼人悬赏"}},{q="卫兵托马斯向谁汇报？",a="托马斯隶属于暴风城军队，通过军事指挥系统向闪金镇的地区指挥部及首都汇报。随着边境局势的恶化，他的报告也需要与西部荒野的格里安·斯托曼等边境指挥官进行协调。",al={"托马斯的上级","暴风城军队指挥链","托马斯为谁工作"}},{q="当冒险者在艾尔文的任务完成后，卫兵托马斯会指引他们去哪里？",a="一旦东谷及东部河流周围的直接威胁得到解决，托马斯会提供报告，指引经验丰富的旅行者前往西部荒野，协助格里安·斯托曼和苦苦挣扎的人民民兵。",al={"卫兵托马斯之后","东谷之后去哪","西部荒野报告"}}},fp="12,170,21.348.0,17.361.1,30.125.0,45.186.0,53.192.0,43.165.0,32.228.0,75.178.0"}
P.entries["npc:gubber-blump"] = {n="古博·布拉普",s="古博·布拉普是一位矮人渔夫兼训练师，驻扎在Darkshore的奥伯丁海岸。他位于码头和飞行管理员之间的沙滩上，是一位钓鱼技巧和海鲜（尤其是新鲜蟹肉）的热情爱好者。",h="古博·布拉普是一位矮人渔夫兼训练师，驻扎在Darkshore的奥伯丁海岸。他位于码头和飞行管理员之间的沙滩上，是一位钓鱼技巧和海鲜（尤其是新鲜蟹肉）的热情爱好者。",kw={"奥伯丁","布拉普","darkshore","钓鱼","graun blump","古博","礁栖蟹","闪亮的珠子"},ang={["profession:Cooking"]="古博对沿海美食充满热情，尤其是新鲜的礁栖蟹肉，这使他成为了那些寻求Darkshore水域食材的厨师们志同道合的朋友。",["race:Dwarf"]="看到一个矮人安逸地生活在雾气蒙蒙的卡利姆多海岸线上，而不是在Khaz Modan，这并不常见，但他关于亲戚的直言不讳的玩笑证明他并没有忘记自己的铁炉堡根源。"},sec={{t="奥伯丁的钓鱼者",b="虽然大多数矮人都喜欢在石头底下或熊熊燃烧的熔炉旁寻找舒适感，但古博·布拉普却更喜欢Darkshore多雾的海岸线。古博驻扎在奥伯丁的海滩上，位于飞行管理员和轮渡码头之间，他向过往的旅行者教授钓鱼技巧，并出售基本的鱼竿和钓鱼装备。他对蟹肉有着深厚的美食鉴赏力，尽管他经常依靠冒险者来帮助他在危险的海岸边捕获猎物，以及找回具有纪念意义的家族渔具。"},{t="家族纽带与海洋的恩惠",b="古博以分享有关他家人的坦诚故事而闻名，尤其是他的表亲Graun Blump，他坚称她既有胡子又有种不同寻常的气味。那些伸出援手处理他海岸琐事的旅行者——无论是拖回礁栖蟹腿还是找回他的家族鱼竿——经常会收到古博写的一封深思熟虑的感谢信，通常还会附带一个闪亮的珠子，以鼓励他们未来的抛竿。"}},faq={{q="古博·布拉普是谁？",a="古博·布拉普是一位矮人钓鱼训练师兼商人，位于奥伯丁的海滩上，就在村庄码头和角鹰兽管理员之间。",al={"古博·布拉普是谁","古博·布拉普npc","古博·布拉普在哪里"}},{q="古博·布拉普教授什么或出售什么？",a="他为钓鱼专业的新手提供训练，并为潜在的钓鱼者储备基本装备，包括标准鱼竿和闪亮的珠子。",al={"古博出售什么","古博·布拉普训练师","darkshore钓鱼训练师"}},{q="古博·布拉普会发布什么任务？",a="古博会请求旅行者帮他找回丢失的家族鱼竿，并从海岸收集新鲜的蟹肉，任务如“The Family and the Fishing Pole”和“Fruit of the Sea”。",al={"古博·布拉普任务","fruit of the sea","the family and the fishing pole"}},{q="Graun Blump是谁？",a="Graun Blump是古博的矮人表亲。古博坦率地评论说，她长着一把引人注目的胡子，而且身上有一种相当不同寻常的气味。",al={"graun blump","古博·布拉普表亲"}}},fx={["0ab58c9b"]={q="古博·布拉普效忠哪一方？",a="古博·布拉普是一名亲近联盟的矮人，平静地与奥伯丁的暗夜精灵比邻而居。他大多只顾自己的事，专心于手艺，同时也热情欢迎联盟旅人前来交易、训练，一同分享海滨渔获。",al={"古博·布拉普是联盟成员吗","古博·布拉普的阵营","古博·布拉普效忠谁"}},["09bb4e46"]={q="古博·布拉普想做什么？",a="古博热爱钓鱼和美食，尤其喜欢用当地水域捕获的新鲜螃蟹制作的蟹肉佳肴。他最希望尽情享受海洋的馈赠，找回家族遗失的渔具，并教其他钓鱼爱好者掌握这门技艺的诀窍。",al={"古博·布拉普的目标是什么","古博·布拉普需要什么","古博·布拉普的动机"}},["77301056"]={q="古博·布拉普为什么在黑海岸？",a="古博在奥伯丁的海岸边安了家，住处位于码头和飞行管理员之间。雾气弥漫的海岸拥有充足的渔场，也盛产礁蟹，是矮人渔夫安心垂钓的理想地点。",al={"古博·布拉普为什么在这里","矮人为什么在黑海岸","古博为什么在奥伯丁"}}},fp="12,256,23.502.0,28.409.0,20.153.0,37.142.0,38.178.0,19.127.0"}
P.entries["npc:gunther-arcanus"] = {n="冈瑟尔·阿坎努斯",s="冈瑟尔·阿坎努斯是一位极其强大的死灵法师，居住在澈水湖中的一座孤岛上。他在第三次战争中阵亡并被复活为亡灵，但他仅凭一己之力就成功粉碎了巫妖王的精神控制。他长期以来一直认为自己是唯一拥有自由意志的亡灵，并在被遗忘者发现之前，一直防御着所有外来者，守护着他的隐居之所。",h="冈瑟尔·阿坎努斯是一位极其强大的死灵法师，居住在澈水湖中的一座孤岛上。他在第三次战争中阵亡并被复活为亡灵，但他仅凭一己之力就成功粉碎了巫妖王的精神控制。他长期以来一直认为自己是唯一拥有自由意志的亡灵，并在被遗忘者发现之前...",kw={"阿坎努斯","比索","澈水","达拉然","冈瑟尔","埃斯沙德","肯瑞托","巫妖","死灵法师","瑟尔","提瑞斯法"},ang={["class:Mage"]="冈瑟尔曾受训于达拉然，他是肯瑞托巫师的代表，在天灾军团入侵洛丹伦之前，他们曾暗中涉猎禁忌的死灵法术。",["class:Warlock"]="冈瑟尔对黑魔法和复活术的掌控力展示了禁忌学术在脱离达拉然领导层监视的情况下，能够发展到何种地步。",["race:Undead"]="冈瑟尔的自我解脱使他成为被遗忘者中的异类，证明了深厚的奥术造诣和钢铁般的意志有时确实能够粉碎巫妖王的精神统治。"},sec={{t="打破枷锁",b="当第三次战争期间天灾军团横扫北方时，冈瑟尔死于亡灵瘟疫并被复活为奴仆。与大多数需要借助巫妖王力量减弱或是希尔瓦娜斯女王打破枷锁的亡灵不同，冈瑟尔凭借他深厚的奥术造诣和纯粹的意志力，独自摆脱了巫妖王的精神控制。他坚信其他所有的行尸走肉依然是天灾军团的无脑傀儡，于是他退隐到提瑞斯法林地的一座岛屿上，用蹒跚的守卫将自己重重包围，切断了与生者和死者的一切联系。"},{t="浪子巫妖",b="为了寻求对抗天灾军团的强力盟友，被遗忘者派遣使者去取回这位神秘死灵法师的法术书。在幽暗城查阅了这本奥术法典后，比索·埃斯沙德认出了他那位失踪已久的同窗的独特笔迹。通过对比索送回的法术书进行附魔，并要求冈瑟尔消灭当地的天灾军团指挥官，冈瑟尔终于意识到他在追寻自由的道路上并不孤单。他坚信希尔瓦娜斯的阵营代表了对天灾军团的真正反抗，于是他与昔日的同窗结成盟约，加入被遗忘者的阵营。"},{t="达拉然的学生",b="在洛丹伦陷落之前，冈瑟尔曾是达拉然肯瑞托中一位前途无量的学徒。他与好友比索·埃斯沙德和瑟尔·雷文克劳一起研习奥术，尽管肯瑞托严禁黑魔法，但他仍暗中钻研死灵法术。为了纪念他们的兄弟情谊，三人曾将他们的学徒法杖融合在一起，成为一件传家宝。"}},faq={{q="冈瑟尔·阿坎努斯是谁？",a="他是达拉然肯瑞托的一位前巫师，在第三次战争中阵亡。他被复活为亡灵后，独自摆脱了巫妖王的控制，并退隐到提瑞斯法林地澈水湖中的一座岛屿上。",al={"冈瑟尔是谁","冈瑟尔背景故事","冈瑟尔·阿坎努斯的故事"}},{q="为什么冈瑟尔看起来像一个普通的被遗忘者，而不是一具枯骨状的巫妖？",a="传统的巫妖会将灵魂转移到命匣中，并形成畸形的漂浮骸骨形态，而冈瑟尔在达成他那种巫妖般的死灵状态时，并没有放弃他原本的复活尸体，从而保留了他生前的肉体外貌。",al={"为什么冈瑟尔看起来像人类","冈瑟尔不是骷髅","为什么冈瑟尔是巫妖"}},{q="为什么冈瑟尔独自居住在岛上？",a="在打破巫妖王的精神控制后，冈瑟尔认为他是世上唯一拥有自由意志的亡灵。他假定其他所有的死者依然是天灾军团无脑的奴隶，于是他选择避世隐居，并命令他的爪牙击杀任何靠近的人。",al={"为什么冈瑟尔独自一人","冈瑟尔的孤岛隐居","为什么冈瑟尔要躲藏"}},{q="冈瑟尔是如何认识比索·埃斯沙德的？",a="他们是达拉然肯瑞托旗下的同学和好友，还有第三位法师名叫瑟尔·雷文克劳。这三位朋友甚至将他们的学徒法杖融合在了一起，作为他们情谊的象征。",al={"比索和冈瑟尔","冈瑟尔如何认识比索","比索·埃斯沙德的历史"}},{q="冈瑟尔加入被遗忘者了吗？",a="是的。当冒险者带回他的附魔法术书并处决了当地的天灾军团特工莉莉丝·内法拉，以证明他们确实脱离了巫妖王的控制后，冈瑟尔对比索和被遗忘者的大义宣誓效忠。",al={"冈瑟尔是否加入部落","冈瑟尔所属阵营","冈瑟尔是被遗忘者吗"}},{q="莉莉丝·内法拉是谁？",a="莉莉丝·内法拉是驻扎在提瑞斯法林地的天灾军团特工。冈瑟尔要求除掉她，以此作为冒险者真正服务于巫妖王之敌、而非效忠于天灾军团本身的证明。",al={"莉莉丝·内法拉","内法拉","冈瑟尔的目标"}}},fx={["3744b38d"]={q="冈瑟尔·阿坎努斯想做什么？",a="冈瑟尔最看重的是摆脱巫妖王的控制。凭借强大的意志力挣脱束缚后，他独自隐居多年，提防着他以为是天灾爪牙的存在。他渴望远离天灾，在信任任何声称与他一样获得自由的人之前寻求证据，并希望确认你确实反对巫妖王的统治。",al={"冈瑟尔想做什么","冈瑟尔·阿坎努斯的目标","冈瑟尔·阿坎努斯的动机"}},["2466094b"]={q="冈瑟尔·阿坎努斯为何声名显赫或令人畏惧？",a="即使身为达拉然的凡人法师，冈瑟尔也精通禁忌的通灵术。成为亡灵后，他达到了极为罕见的巫妖境界，同时保留了原本的凡人形体。最令人恐惧的是，他仅凭一己之力就彻底粉碎了巫妖王的精神控制，能够以绝对意志支配亡灵仆从。",al={"冈瑟尔·阿坎努斯实力强大吗","冈瑟尔·阿坎努斯为何令人畏惧","冈瑟尔·阿坎努斯的声望"}}},fp="15,371,21.596.0,17.549.1,20.392.1,23.229.0,73.258.0,42.272.0,38.213.1,31.216.1,22.198.1"}
P.entries["npc:gurda-ragescar"] = {n="古尔达·怒痕",s="古尔达·怒痕是驻扎在灰谷碎木岗哨西南方一个小部落哨所的兽人。她与费兰·强风一道，在保卫营地抵御这片阴影森林中当地威胁的战斗中牺牲。",h="古尔达·怒痕是驻扎在灰谷碎木岗哨西南方一个小部落哨所的兽人。她与费兰·强风一道，在保卫营地抵御这片阴影森林中当地威胁的战斗中牺牲。",kw={"灰谷","费兰·强风","古尔达","兽人","怒痕","碎木岗哨","遗失的页面"},ang={["faction:Horde"]="这座沦陷的营地令人悲伤地提醒着人们，部落为了在灰谷的神圣森林中占据一席之地付出了多么惨痛的代价。"},sec={{t="被摧毁的哨所",b="古尔达·怒痕在灰谷茂密的林冠下维护着一个简陋的部落营地，位置就在碎木岗哨坚固城墙的西南方。由于身处暗夜精灵守军和野生野兽争夺的腹地，维持这样孤立的据点是一项危险的工作。最终，古尔达与费兰·强风以及他们的卫兵分队在哨所中被压倒性优势的敌人击溃并杀害，只留下了他们最后抵抗的残迹，等待路过的盟友发现。"},{t="阵亡的斥候",b="路过附近小径的旅行者可能会偶然发现古尔达战败的惨状。即使在死后，她营地中留下的物品和任务也为部落在森林各处的行动提供了线索，其中包括因伏击而遗失的文件和被打乱的命令。"}},faq={{q="古尔达·怒痕是谁？",a="古尔达·怒痕是一位兽人斥候和任务发布者，她位于灰谷碎木岗哨西南方的一个小营地，最终与她的哨所同伴一起惨死。",al={"古尔达是谁","古尔达·怒痕背景故事"}},{q="在哪里可以找到古尔达·怒痕？",a="她的尸体位于碎木岗哨西南方的一个被摧毁的营地中，就在横穿灰谷中部的小路旁边。",al={"古尔达位置","古尔达·怒痕在哪里"}},{q="谁和她一起被杀？",a="在对他们小营地的袭击中，她与费兰·强风以及他们的卫兵随从一同牺牲。",al={"谁和古尔达一起牺牲了","费兰·强风"}},{q="有哪些涉及古尔达·怒痕的任务？",a="古尔达与任务“遗失的页面”有关，该任务涉及找回灰谷荒野中散落的文件。",al={"古尔达任务","遗失的页面"}}},fx={["28561f13"]={q="古尔达·怒痕属于哪个阵营？",a="古尔达·怒痕曾效忠部落。她与同伴驻扎在碎木岗哨西南方的一处小型前哨，代表着部落在灰谷争议边境深处的坚固据点。",al={"古尔达·怒痕的阵营","古尔达属于部落还是联盟","古尔达为谁而战"}},e9ae8f07={q="古尔达·怒痕为什么驻扎在碎木岗哨西南方？",a="古尔达·怒痕与 Feran Strongwind 及一队卫兵在碎木岗哨西南方维持着部落的前沿营地。她的岗哨位于争议不断的林间小径沿线，负责支援部落行动，并在灰谷危机四伏的森林中找回失落物资。",al={"古尔达·怒痕为什么在这里","古尔达营地的用途","古尔达为何在灰谷"}}},fp="14,208,15.473.0,17.266.0,22.179.0,34.115.0,29.108.0,35.117.0"}
P.entries["npc:gwennyth-bly-leggonde"] = {n="温尼斯·布莱葛",s="温尼斯·布莱葛是一位居住在奥伯丁沿海港口的暗夜精灵。她驻守在迷雾笼罩的黑海岸边，观察潮汐变化，并指引旅行者去调查冲上岸的奇异残骸。她主要关注那些神秘的海洋生物和巨大的海龟，它们的尸体已经开始布满北部海滩。",h="温尼斯·布莱葛是一位居住在奥伯丁沿海港口的暗夜精灵。她驻守在迷雾笼罩的黑海岸边，观察潮汐变化，并指引旅行者去调查冲上岸的奇异残骸。她主要关注那些神秘的海洋生物和巨大的海龟，它们的尸体已经开始布满北部海滩。",kw={"奥伯丁","搁浅海洋生物","搁浅海龟","布莱葛","黑海岸","温尼斯","卡多雷","遮蔽之海","冲上岸"},ang={["class:Druid"]="致力于维护卡利姆多自然和谐的德鲁伊们会发现，温尼斯关于搁浅海洋生物的报告是沿海生态系统受到干扰的警示信号。",["faction:Alliance"]="奥伯丁是联盟在卡利姆多北部的首要沿海港口；保护其水道和海滩免受潜在威胁，对于所有在此冒险的联盟种族来说都至关重要。",["race:NightElf"]="对于卡多雷来说，黑海岸外巨大海兽非自然的死亡是其祖地失衡的令人担忧的迹象，这使得温尼斯的海岸守望工作显得尤为迫切。"},sec={{t="流沙守望者",b="温尼斯·布莱葛以奥伯丁为家，这是黑海岸边一个繁忙的避风港。虽然镇上的许多人关心森林或是在遮蔽之海的航运，但温尼斯的目光始终紧盯着海岸线。最近潮汐变得诡异，将巨大海洋生物的残骸冲上了滩头。为了了解近海发生了什么，她依靠热心的冒险者去搜寻沙滩，找回骨骼样本，并带回答案。"},{t="搁浅的巨人",b="在奥伯丁南北两边的海滩上，搁浅的海洋生物和古老海龟的数量惊人地增加。温尼斯不愿让它们的死亡被忽视，于是委托旅行者去检查这些倒下的泰坦。通过研究骨骼并发现是什么迫使这些野兽冲上岸或是夺走了它们的生命，她希望能拼凑出潜伏在卡利姆多北部海岸外的隐藏危险。"}},faq={{q="温尼斯·布莱葛是谁？",a="她是居住在黑海岸奥伯丁的一位暗夜精灵，负责研究最近沿海发生的生态异常。她招募旅行者来勘测海滩，并调查从海中冲上岸的奇异事物。",al={"温尼斯是谁","温尼斯奥伯丁","温尼斯背景故事"}},{q="我在哪里可以找到温尼斯·布莱葛？",a="你可以在奥伯丁的沿海定居点找到她，那里位于黑海岸迷雾笼罩的海岸边的海滩和码头附近。",al={"温尼斯在哪里","温尼斯位置","寻找温尼斯"}},{q="她为什么对搁浅的生物感兴趣？",a="巨型海龟和神秘海洋巨兽的突然死亡并搁浅，预示着黑海岸外的水域中存在某种失衡或看不见的掠食者。温尼斯试图通过检查从海岸沿线回收的残骸来查明原因。",al={"为什么有搁浅海龟","她为什么需要骨头","冲上岸任务"}},{q="温尼斯提供什么任务？",a="她会派遣冒险者去执行“冲上岸”的任务，并且是上交与黑海岸沿岸发现的搁浅海洋生物和搁浅海龟相关的各种发现的交任务点。",al={"温尼斯任务","她给什么奖励"}},{q="她是塞纳里奥议会或哨兵部队的成员吗？",a="都谈不上。她是一位服务于奥伯丁艾露恩姐妹会的月之祭司，而非塞纳里奥德鲁伊或哨兵指挥官，但她和同族一样，深切关注黑海岸自然环境的健康与平衡。",al={"温尼斯阵营","温尼斯是德鲁伊吗"}},{q="她的名字是什么意思？",a="虽然符合卡多雷富有韵律的命名风格，但她不寻常的姓氏“Bly'Leggonde”是“Leggy Blonde”（长腿金发女郎）的字母易位构词，这是游戏创造者们的一个调皮的小彩蛋。",al={"布莱葛名字含义","温尼斯名字彩蛋"}}},fx={["9c9d3ff5"]={q="温尼斯·布莱葛为什么在黑海岸？",a="温尼斯住在奥伯丁这座海滨港口，守望着黑海岸雾气笼罩的海滩。海岸上冲来的反常疫病令她忧心忡忡，因此她一直留意搁浅的海洋生物，并请路过的旅人调查搁浅的海兽和海龟，查明它们为何受到水域中奇异腐化的侵袭。",al={"温尼斯为什么在这里","温尼斯·布莱葛为何在奥伯丁","温尼斯为什么在黑海岸"}}},fp="21,348,29.489.0,19.409.0,29.212.0,39.134.0,43.248.0,32.196.0,52.234.0,24.167.0"}
P.entries["npc:hagar-lightninghoof"] = {n="哈加尔·雷蹄",s="哈加尔·雷蹄是一名驻守在千针石林乱风岗高处的牛头人斥候。由于传闻在峡谷深处隐藏着一窝奇怪的卵，他开始调查有关一枚由当地风蛇拼命守护的异型卵的报告。",h="哈加尔·雷蹄是一名驻守在千针石林乱风岗高处的牛头人斥候。由于传闻在峡谷深处隐藏着一窝奇怪的卵，他开始调查有关一枚由当地风蛇拼命守护的异型卵的报告。",kw={"异型卵","阿雅拉","乱风岗","哈加尔","雷蹄","莫特加·火鬃","千针石林","风蛇"},ang={["faction:Horde"]="驻守在乱风岗峡谷底部的上方，哈加尔依靠有能力的部落战士去冒险进入普通的斥候无法安全闯入的危险洞穴。",["race:Tauren"]="对于牛头人旅行者来说，协助哈加尔会让他们意识到，关于阿雅拉——那个带翼的复仇化身——的古老传说，在下方的峡谷中竟是活生生的现实。"},sec={{t="奇怪的卵",b="当驻守在乱风岗高耸的悬崖间时，哈加尔·雷蹄听到了一些传言，说是下方的洞穴深处藏着一枚非同寻常的卵。当地的风蛇异常凶猛地守护着巢穴，令好奇的斥候们无法靠近。为了寻找一位敢于深入蛇穴的冒险者，哈加尔希望能亲手研究这个样本，弄清究竟是什么野兽能让峡谷中的天敌表现出如此强烈的防御本能。"},{t="神话孵化",b="当冒险者最终找回那枚卵并将其带回乱风岗时，它在哈加尔面前孵化了，现出了一只幼年风蛇，看起来就像传说中的阿雅拉——在牛头人传说中，它是复仇的化身。意识到这只生物的回归具有重大的文化和精神意义，哈加尔立刻派遣这位旅行者去请教莫特加·火鬃长老。"}},faq={{q="哈加尔·雷蹄是谁？",a="哈加尔·雷蹄是一位居住在千针石林乱风岗的牛头人任务发布者。他负责调查峡谷中异常的野生生物，特别是在附近洞穴深处发现的一枚不同寻常的风蛇卵。",al={"哈加尔是谁","哈加尔·雷蹄的角色","哈加尔背景故事"}},{q="在哪里可以找到哈加尔·雷蹄？",a="他位于乱风岗顶端，这是位于千针石林中部巨大石柱上的部落据点。",al={"哈加尔在哪里","哈加尔·雷蹄的位置","乱风岗的哈加尔"}},{q="哈加尔寻找的“异型卵”是什么？",a="异型卵是一枚被地底洞穴中的风蛇守护的奇怪的卵。哈加尔请求冒险者将其取回，以便他能研究其本质。",al={"异型卵","卵是什么","风蛇卵"}},{q="哈加尔向谁咨询关于这枚卵的事情？",a="哈加尔派遣冒险者去与乱风岗的莫特加·火鬃交谈，他是一位对牛头人传统有着更深见解的长者。",al={"谁来接手风蛇任务","哈加尔的后续任务","哈加尔之后去哪里"}}},fx={d173f224={q="哈加尔·雷蹄效忠哪一方？",a="哈加尔·雷蹄效忠部落和他的牛头人同胞。他驻扎在高耸的乱风岗尖塔之上，只把任务交给那些证明自己有能力冒险深入下方危险峡谷的部落勇士。",al={"哈加尔·雷蹄的阵营","哈加尔是部落成员吗"}},c809f2c7={q="哈加尔·雷蹄为什么会在乱风岗？",a="哈加尔听说风蛇巢穴中发现了一枚奇特的异型卵后，便前往千针石林。这个奇异的发现令他十分好奇，于是他在乱风岗扎营，希望找到一位胆识过人的人，能越过风蛇守卫将它取回。",al={"哈加尔为什么在这里","哈加尔为什么来到千针石林"}},a74332ba={q="哈加尔·雷蹄与谁关系密切？",a="哈加尔与乱风岗的牛头人守卫并肩行事，并与莫特加·火鬃密切商议。当他的调查牵涉到古老的牛头人传说和神圣的征兆时，他便向莫特加请教。",al={"哈加尔的关系","哈加尔与谁共事"}}},fp="19,239,18.474.0,14.425.1,27.220.0,39.126.0,45.151.1,37.140.1"}
P.entries["npc:halaan-hawk-eye"] = {n="Halaan Hawk-Eye",s="Halaan Hawk-Eye是一名驻扎在泽风岛森达尔村瞭望塔上的Skyborne哨兵。由于缺乏魔法感知能力以及同族所拥有的神秘“天视（skysight）”，他依靠敏锐的凡人视觉来监控周围的岛屿。从他的栖身之处，他追踪着远处的锚定塔，并向游客发出警告，提醒他们这些塔的奥术稳定性正在减弱。",h="Halaan...",kw={"锚定塔","halaan","hawk-eye","skyborne","天视","森达尔村","泽风岛"},ang={["race:Skyborne"]="Halaan代表了Skyborne中那些缺乏地脉操纵天赋或“天视”能力的人，他们通过坚定的警惕和职责履行来为社区服务。"},sec={{t="没有魔法的守望者",b="Halaan Hawk-Eye高高地栖身于森达尔村上方，他在没有Skyborne常见的那些天赋的情况下服务着他的人民。他无法汲取流经泽风岛地下的地脉中的奥术能量，也无法通过神秘的“天视”在世界之间窥探。相反，Halaan完全依赖他敏锐的自然感官。从他在瞭望塔上的有利位置，他扫描地平线以观察岛上的锚定塔，并提醒人们注意这些塔日益不稳定且不连贯的奥术能量。"}},faq={{q="Halaan Hawk-Eye是谁？",a="Halaan Hawk-Eye是一名驻扎在泽风岛森达尔村瞭望塔上的Skyborne哨兵。他观察着周围的土地，并向冒险者们通报影响岛上锚定塔的不稳定魔法。",al={"halaan hawkeye","halaan是谁","森达尔瞭望塔npc"}},{q="Halaan与其他Skyborne有何不同？",a="与他族人中的许多人不同，Halaan既没有能够穿透世界面纱的神秘“天视”，也没有驾驭泽风岛地底地脉的先天能力。他依靠的是敏锐的肉眼和自然观察力。",al={"halaan的能力","halaan会魔法吗","halaan的天视"}},{q="为什么Halaan担心锚定塔？",a="Halaan监视着远处的锚定塔，他注意到它们的魔法输出变得不稳定且不连贯，这对泽风岛的稳定性构成了未知的风险。",al={"塔出了什么问题","泽风岛锚定塔问题"}},{q="我在哪里可以找到Halaan Hawk-Eye？",a="他位于泽风岛森达尔村的一座木制瞭望塔顶端，向地平线望去。",al={"halaan在哪里","halaan位置"}}},fx={d6a0f6c4={q="Halaan Hawk-Eye属于哪一方？",a="Halaan是Skyborne的一员，与泽风岛上的同族站在一起。虽然他不像同伴那样天生能够施展 ley line 魔法，也没有超凡的 sky sight，他仍忠心地为族人效力，守望森达尔村，并提醒旅人注意威胁家园的动荡正在逐渐加剧。",al={"halaan的阵营","halaan hawk-eye属于哪一方","halaan为谁效力"}},e8313a77={q="Halaan Hawk-Eye为什么驻守在瞭望塔？",a="Halaan驻守在森达尔村的塔顶，因为他无法像其他Skyborne那样汲取当地的 ley line 能量或施展魔法 sky sight。因此，他凭借敏锐的天生视力巡视泽风岛，监视远处的锚定塔柱，留意它们的魔法稳定性开始减弱。",al={"halaan hawk-eye为什么在这里","halaan为什么在瞭望塔","halaan在此的原因"}}},fp="15,358,24.509.0,23.227.0,48.260.0,46.185.0,33.117.0"}
P.entries["npc:hamhock"] = {n="哈姆霍克",s="哈姆霍克是一个巨大的双头食人魔，被囚禁在暴风城监狱的深处。他被关押在首都地下，与穷凶极恶的迪菲亚潜行者和暴徒们关在一起。在监狱暴动期间，他成了一个格外凶残且意想不到的囚犯。",h="哈姆霍克是一个巨大的双头食人魔，被囚禁在暴风城监狱的深处。他被关押在首都地下，与穷凶极恶的迪菲亚潜行者和暴徒们关在一起。在监狱暴动期间，他成了一个格外凶残且意想不到的囚犯。",kw={"暮色森林","哈姆霍克","食人魔","监狱","裂拳","暴风城监狱","暴风城","双头"},ang={["class:Warrior"]="想要制服哈姆霍克，需要在监狱狭窄的走廊中正面迎击他那原始而巨大的力量。",["faction:Alliance"]="在一个大都市的街道之下发现一只未受束缚的双头食人魔，凸显了城市守卫在监狱控制权上的彻底失守。"},sec={{t="铁窗后的恶棍",b="暴风城监狱本是用来关押小偷、谋杀犯和政治异见分子的，因此一个高大的双头食人魔出现在牢房中显得格外引人注目。当囚犯们发动起义并控制了这座设施时，哈姆霍克依然固守在混乱的中心，碾碎任何胆敢闯入他监区的蠢货。"},{t="扑朔迷离的出身",b="没有任何记录解释哈姆霍克是如何被抓获的，或者为什么一个双头食人魔会被关在暴风城的小偷和异见分子之中。不管是什么原因让他进了监狱，他现在都是这里最危险的囚犯之一。"}},faq={{q="哈姆霍克是谁？",a="哈姆霍克是被关押在暴风城监狱中的一名精英双头食人魔囚犯。在迪菲亚囚犯领导的起义中，他是深入监狱走廊时的一大危险阻碍。",al={"哈姆霍克","监狱里的食人魔是谁","监狱食人魔首领"}},{q="为什么食人魔会被关进暴风城监狱？",a="没有任何记录解释他是如何被抓获或带到暴风城的。",al={"哈姆霍克为什么在监狱里","哈姆霍克是怎么被抓的","为什么监狱里有食人魔"}},{q="哈姆霍克是迪菲亚暴徒的同伙吗？",a="虽然整座设施都在迪菲亚头目的领导下陷入了叛乱，但尚不清楚哈姆霍克是否真的与他们有协同行动，还是仅仅沉浸在牢房破碎后那肆无忌惮的混乱中。",al={"哈姆霍克是迪菲亚吗","哈姆霍克 迪菲亚潜行者","哈姆霍克为巴基尔工作吗"}},{q="哈姆霍克和暮色森林的食人魔有关系吗？",a="没有任何联系。暮色森林沃古尔食人魔山的裂拳食人魔是离暴风城最近的食人魔氏族，但没有记录显示哈姆霍克来自何处。",al={"哈姆霍克是裂拳氏族吗","哈姆霍克 沃古尔","沃古尔食人魔 监狱"}},{q="哈姆霍克与特定的悬赏或任务有关联吗？",a="没有任何针对哈姆霍克人头的官方悬赏或城市通缉令。他只是冒险者在清理这座暴乱堡垒时遇到的一个意外威胁。",al={"哈姆霍克任务","有没有哈姆霍克的任务","哈姆霍克悬赏"}},{q="双头食人魔有什么特别之处？",a="双头食人魔的两个头拥有独立的个性，通常比单头同类更狡猾或更精通魔法，这使得哈姆霍克对普通的监狱守卫来说异常危险。",al={"双头食人魔背景故事","为什么有两个头"}}},fp="7,255,19.324.0,13.209.0,15.192.0,49.63.0,42.197.0,44.166.0,48.179.0,37.209.0"}
P.entries["npc:hana-zua"] = {n="哈纳祖",s="哈纳祖是一名暗矛巨魔斥候，驻扎在试炼谷，却不幸遭到了徘徊在峡谷脊背上的剧毒野兽的袭击。他被巨大的蝎子Sarkoth重创，此时正躺在那里，等待着渴望证明自己勇气的部落年轻新兵前来援助。",h="哈纳祖是一名暗矛巨魔斥候，驻扎在试炼谷，却不幸遭到了徘徊在峡谷脊背上的剧毒野兽的袭击。他被巨大的蝎子Sarkoth重创，此时正躺在那里，等待着渴望证明自己勇气的部落年轻新兵前来援助。",kw={"暗矛","杜隆塔尔","哈纳祖","sarkoth","蝎子","试炼谷"},ang={["faction:Horde"]="哈纳祖的存活和复仇是部落未来勇士们最早面临的关于忠诚度和战斗准备的考验之一。",["race:Troll"]="对于刚在杜隆塔尔开始旅程的暗矛新兵来说，发现一名受伤的族人突显了当地野生生物的致命性，以及保护他们新结识的盟友的必要性。"},sec={{t="倒在毒液下的斥候",b="在穿越俯瞰试炼谷的干旱高地时，哈纳祖遇到了Sarkoth，一只极其凶残且带有剧毒、潜伏在悬崖上的蝎子。在与野兽的搏斗中，这名巨魔惨遭毒刺，险些丧命。由于无法独自移动或返回营地，他只能在尘土中奄奄一息，寄希望于路过的征募兵能除掉这只野兽，并将他的困境传回大兽穴。"}},faq={{q="哈纳祖是谁？",a="哈纳祖是一名在杜隆塔尔的试炼谷中被发现受伤的暗矛巨魔。他在追踪脊背上的野兽时遭到了伏击并中毒。",al={"哈纳祖","哈纳祖是谁","试炼谷的受伤巨魔"}},{q="哈纳祖发生了什么事？",a="他被Sarkoth击倒了，那是一只潜伏在训练场上方岩石上的巨大而致命的蝎子。它强烈的毒液使他丧失了行动能力，无法回到安全地带。",al={"哈纳祖为什么受伤","谁毒害了哈纳祖","哈纳祖的伤势"}},{q="他请求旅行者做什么？",a="哈纳祖请求有能力的冒险者为他的伤势复仇，去杀死Sarkoth，收集该野兽的爪子作为证据，并将他的状况传达给大兽穴的教官们。",al={"哈纳祖任务","哈纳祖想要什么"}}},fx={eb2d80d7={q="哈纳祖属于哪一方？",a="哈纳祖忠于部落和暗矛巨魔。和其他来到试炼谷的年轻兽人和巨魔一样，他进入试炼场证明自己的力量，表明自己已准备好为萨尔建立的新国家效力。",al={"哈纳祖的阵营","哈纳祖为谁效力","哈纳祖是部落的吗"}}},fp="8,277,23.422.0,16.145.0,26.178.0,33.182.0"}
P.entries["npc:hands-springsprocket"] = {n="汉兹·跳链",s="汉兹·跳链是一位勤劳的侏儒，驻扎在丹莫罗的寒脊山小径入口处。他负责协调寒脊山谷这个与世隔绝的训练场与卡拉诺斯镇之间的物资运输，不过最近穴居人的入侵严重阻碍了他的工作。",h="汉兹·跳链是一位勤劳的侏儒，驻扎在丹莫罗的寒脊山小径入口处。他负责协调寒脊山谷这个与世隔绝的训练场与卡拉诺斯镇之间的物资运输，不过最近穴居人的入侵严重阻碍了他的工作。",kw={"寒脊山小径","寒脊山谷","丹莫罗","汉兹·跳链","卡拉诺斯","跳链","运往塔诺克的补给"},ang={["faction:Alliance"]="汉兹维持着寒脊山谷的矮人新兵与丹莫罗深处定居点之间至关重要的内部补给线。",["race:Gnome"]="对于从诺莫瑞根流离失所的侏儒难民来说，汉兹代表了侏儒融入丹莫罗当地贸易和后勤体系，并与他们的矮人盟友并肩作战的那种沉稳与决心。"},sec={{t="隘口的瓶颈",b="汉兹·跳链守在寒脊山小径的入口，发现他常规的补给运输工作受到了极大的干扰。他通常会向雷酒酿制厂和卡拉诺斯的旅店运送物资，但敌对的石腭怪已经占领了通往山谷外的地下通道。由于贸易和通行被这些野兽阻断，汉兹不得不依靠有能力的旅行者，将必要的板条箱通过这条危险的山间走廊运送出去。"}},faq={{q="汉兹·跳链是谁？",a="他是一位效忠于联盟的侏儒，驻扎在寒脊山谷，位置就在寒脊山小径入口外，负责向丹莫罗的下游地区运送补给。",al={"汉兹·跳链是谁","汉兹·跳链背景故事","这个侏儒是谁"}},{q="他为什么需要帮助搬运物资？",a="连接寒脊山谷和丹莫罗其他地区的隘口已经被凶残的石腭怪所占据，如果没有武装护卫或有能力的冒险者，常规的运输工作会变得过于危险。",al={"为什么汉兹需要帮助","寒脊山小径的补给","为什么补给被困"}},{q="他的物资要运往哪里？",a="他安排了运往卡拉诺斯的定期补给，包括提供给塔诺克·霜锤以及当地旅店老板的货物，他们都依赖于从雪峰彼端运来的日常补给。",al={"补给运往何处","汉兹的补给路线","谁负责接收板条箱"}}},fx={d7333ab8={q="汉兹·跳链属于哪一方？",a="汉兹是联盟的忠实成员，也是丹莫罗矮人们的朋友。许多侏儒因诺莫瑞根的惨剧流离失所，汉兹和其中不少人一样，与铁炉堡的盟友紧密合作，负责物流和运送，为卡拉诺斯等当地社区提供支持。",al={"汉兹·跳链的阵营","汉兹·跳链是联盟的吗"}},["8576a218"]={q="汉兹·跳链想要什么？",a="汉兹希望把货物安全地运过寒脊山小径，送到卡拉诺斯雷酒酿制厂的塔诺克·霜锤手中。隧道里敌对的石腭怪近期骤增，导致他的货运彻底停滞；他急需一位愿意冒险运送货箱的冒险者。",al={"汉兹想要什么","汉兹·跳链的目标"}},d21580a2={q="汉兹·跳链与谁关系密切？",a="汉兹经常与卡拉诺斯雷酒酿制厂的旅店老板塔诺克·霜锤做生意。低地需要补给时，汉兹就会安排货物经由山道运送；道路变得危险时，他会依靠旅人来接续运输。",al={"汉兹与谁共事","汉兹·跳链的关系"}}},fp="20,279,24.453.0,28.176.0,38.192.0,32.175.0"}
P.entries["npc:hansel-heavyhands"] = {n="汉瑟尔·重拳",s="汉瑟尔·重拳是一名异常高大的黑铁矮人，驻扎在灼热峡谷的瑟银哨塔，隶属于瑟银兄弟会。哨塔的监工经常给他指派危险的实地任务，但他总是用各种花样百出的身体不适为借口，将这些危险的工作推给路过的冒险者。他那魁梧的身材在同族中显得鹤立鸡群，尽管他对实地工作的热情完全配不上他的体格。",h="汉瑟尔·重拳是一名异常高大的黑铁矮人，驻扎在灼热峡谷的瑟银哨塔，隶属于瑟银兄弟会。哨塔的监工经常给他指派危险的实地任务，但他总是用各种花样百出的身体不适为借口，将这些危险的工作推给路过的冒险者。他那魁梧的身材在同族中显得...",kw={"大熔炉","黑铁","汉瑟尔·重拳","火源食人兽","熔岩蜘蛛","灼热峡谷","瑟银兄弟会","瑟银哨塔"},ang={["faction:Alliance"]="虽然联盟通常与黑铁阵营的人发生冲突，但瑟银兄弟会欢迎任何身手不凡的人，这使得汉瑟尔成为了一个方便的当地赏金任务来源。",["faction:Horde"]="部落的旅行者会觉得汉瑟尔的庞大身躯让人想起兽人或牛头人，尽管他拒绝进行荣誉战斗的态度肯定会让人侧目。",["race:Dwarf"]="铜须和蛮锤矮人可能会对汉瑟尔庞大的体型感到惊奇，或者嗤之以鼻，纳闷一个黑铁矮人是如何在整天逃避劳作的情况下长到如此高大的。"},sec={{t="矮人中的巨人",b="即使以肩膀宽阔的黑铁矮人标准来看，汉瑟尔·重拳也是一个异类。他那庞大的身躯在宽度和高度上都接近兽人，远超他的同胞。他那极其壮硕的体格本应是为前线杀戮而生的战士，然而尽管有着如此威武的身材和响亮的名号，汉瑟尔似乎对任何不必要的体力劳动毫无兴趣，更愿意待在火山灰之上那相对安全的瑟银兄弟会营地里。"},{t="借口大师",b="监工斯克兰格和大铁匠博恩奈特经常指派汉瑟尔去完成清理下方熔渣坑中凶猛野兽的苦差事。当被命令去清理大熔炉中横行的火源食人兽时，汉瑟尔就以脚疼为由推脱。当被命令去猎杀肆虐在灼热荒原上的大型熔岩蜘蛛时，他又声称这片炙热的火山脊气候“极其寒冷”，让他得了重感冒。因此，任何愿意冒险进入岩浆流的雇佣兵，都会发现汉瑟尔早就准备好了一份现成的委托。"}},faq={{q="汉瑟尔·重拳是谁？",a="汉瑟尔·重拳是一名效力于瑟银兄弟会的黑铁矮人。他驻扎在灼热峡谷的瑟银哨塔，以惊人的体型和推脱危险实地工作的离奇本领而闻名。",al={"汉瑟尔是谁","汉瑟尔·重拳背景故事","矮人汉瑟尔"}},{q="为什么汉瑟尔比其他矮人高大得多？",a="关于他身材魁梧的原因并没有明确的解释。汉瑟尔就是一个异常巨大的黑铁矮人，他肩膀宽阔、四肢粗壮，整体体格接近兽人。",al={"为什么汉瑟尔这么大","灼热峡谷巨大矮人","兽人大小的矮人"}},{q="汉瑟尔给冒险者什么任务？",a="汉瑟尔招募路过的旅行者来处理上级下达的任务。具体来说，他会付钱给雇佣兵，让他们去猎杀整个灼热峡谷中的大型熔岩蜘蛛，并深入大熔炉猎杀火源食人兽。",al={"汉瑟尔·重拳任务","汉瑟尔提供什么任务"}},{q="为什么汉瑟尔不自己做杂活？",a="每当危险降临时，汉瑟尔总能编出各种借口。他声称脚疼而无法去大熔炉对付火源食人兽，当被命令去猎杀熔岩蜘蛛时，他又抱怨炙热的灼热峡谷冷得让他得了重感冒。",al={"为什么汉瑟尔不战斗","汉瑟尔的借口"}},{q="汉瑟尔效忠于黑铁皇帝吗？",a="汉瑟尔属于瑟银兄弟会，这是一个背离了达格兰·索瑞森大帝和拉格纳罗斯的黑铁矮人叛军派系。他对造访瑟银哨塔的联盟和部落旅行者均持中立态度。",al={"汉瑟尔效忠暗炉城吗","汉瑟尔是敌人吗"}},{q="在哪里可以找到汉瑟尔·重拳？",a="他位于瑟银哨塔，那是一座坐落在俯瞰灼热峡谷的北部山脊上的岩石哨所。",al={"汉瑟尔位置","汉瑟尔在哪里"}}},fp="17,420,21.485.0,17.557.0,25.235.0,48.192.0,43.232.0,37.254.0,41.227.0,37.110.0"}
P.entries["npc:harb-clawhoof"] = {n="哈布·爪蹄",s="哈布·爪蹄是一位牛头人坐骑饲养员，驻扎在莫高雷的血蹄村外。他照料着部落里结实的科多兽，并将它们提供给值得信赖的牛头人骑手和雷霆崖的勇士。",h="哈布·爪蹄是一位牛头人坐骑饲养员，驻扎在莫高雷的血蹄村外。他照料着部落里结实的科多兽，并将它们提供给值得信赖的牛头人骑手和雷霆崖的勇士。",kw={"血蹄村","哈布·爪蹄","科多兽训练师","科多兽商人","坐骑商人","莫高雷科多兽","雷霆崖坐骑"},ang={["faction:Horde"]="对于兽人、巨魔和被遗忘者来说，从哈布那里获得一头科多兽是雷霆崖长者所认可的最高荣誉和友谊的标志。",["race:Tauren"]="哈布·爪蹄提供属于你们种族传统的经典坐骑，它既是在莫高雷旅行的实用工具，也是你们游牧传统的象征。"},sec={{t="巨型科多兽饲养员",b="哈布·爪蹄位于血蹄村的围栏附近，每天都在照料那些作为牛头人旅行和劳动支柱的巨型科多兽。这些结实的动物专为在广阔的距离上承载巨大的重量而生，对平原上的生活至关重要。哈布确保每一头野兽都得到妥善照顾、训练有素，并且只配给那些赢得牛头人人民尊重的骑手。"},{t="平原坐骑",b="虽然牛头人可以自然地获得骑乘哈布的科多兽所需的信任，但外族人则面临更严格的审查。由于体型巨大且脾气特殊，不熟悉科多兽习性的人很难驾驭它们。想要骑上哈布珍贵的坐骑离去的非牛头人盟友，必须首先证明他们的忠诚并获得雷霆崖的崇拜声望。"}},faq={{q="在哪里可以找到哈布·爪蹄？",a="哈布·爪蹄驻扎在莫高雷中部血蹄村郊外的科多兽围栏旁，就在雷霆崖的正南方。",al={"哈布·爪蹄位置","哈布·爪蹄在哪里","科多兽商人在哪"}},{q="哈布·爪蹄出售什么？",a="哈布出售各种类型的科多兽坐骑，包括普通的棕色和灰色科多兽，以及为经验丰富的骑手提供的重甲巨型科多兽。",al={"哈布出售什么","哈布的坐骑","科多兽商人商品"}},{q="非牛头人玩家可以从哈布那里购买科多兽吗？",a="可以，但前提是他们必须在雷霆崖获得崇拜声望。牛头人可以直接购买，但其他部落种族必须向部族证明自己，哈布才会放心地将科多兽交给他们。",al={"兽人可以购买科多兽吗","巨魔可以骑科多兽吗","科多兽声望要求"}},{q="为什么科多兽对牛头人如此重要？",a="科多兽是一种强大而坚韧的生物，非常适合卡利姆多中部游牧的生活方式和开阔的平原。它们是可靠的负重牲畜、作战坐骑，也是穿越崎岖地形的贸易运输工具。",al={"牛头人科多兽背景故事","为什么选择科多兽"}}},fx={["2e2e2604"]={q="哈布·爪蹄是谁？",a="哈布·爪蹄是驻扎在血蹄村的牛头人科多兽饲养员和坐骑商人。他因饲养和照料莫高雷的强大野兽而受到族人敬重，并确保有能力的勇士能获得可靠的坐骑，以应对在卡利姆多各地旅行和战斗的艰辛。",al={"哈布是谁","哈布·爪蹄的背景","哈布·爪蹄是谁"}},ceacb5fa={q="哈布·爪蹄属于哪一方？",a="哈布对雷霆崖和部落忠心耿耿。他乐意为牛头人同胞提供坐骑，但其他部落种族的外来者必须证明自己的忠诚，并在雷霆崖赢得足够高的声望，他才会放心把珍贵的科多兽交给他们。",al={"哈布·爪蹄的阵营","哈布·爪蹄是部落的吗","哈布·爪蹄效忠于谁"}},["0020906d"]={q="哈布·爪蹄想要什么？",a="哈布希望培育强壮可靠的科多兽，并确保它们只交给真正尊重它们的骑手。在牛头人眼中，科多兽不仅仅是驮兽，更是他们文明的支柱；哈布致力于守护这份神圣的羁绊。",al={"哈布想要什么","哈布·爪蹄的目标","哈布·爪蹄的职责"}},efcee9d4={q="哈布·爪蹄为什么在血蹄村？",a="血蹄村是年轻牛头人和旅人的重要聚集地，他们从纳拉其营地出发，前往莫高雷广阔的平原。哈布在此经营马厩，这里有充足的开阔牧场，可以放牧并培育强健的科多兽群，以保卫部族、促进繁荣。",al={"哈布为什么在血蹄村","哈布为什么在这里","哈布 血蹄村"}}},fp="13,208,25.403.0,20.360.0,31.139.0,29.141.0,35.205.0,41.221.0"}
P.entries["npc:harken-windtotem"] = {n="哈肯·风之图腾",s="哈肯·风之图腾是一名居住在莫高雷血蹄村的牛头人猎手。他致力于本族的传统，经常指派年轻的猎人和旅行者在金色平原上证明他们的追踪和觅食技能。",h="哈肯·风之图腾是一名居住在莫高雷血蹄村的牛头人猎手。他致力于本族的传统，经常指派年轻的猎人和旅行者在金色平原上证明他们的追踪和觅食技能。",kw={"血蹄村","哈肯·风之图腾","莫高雷","狩猎掠食者","牛头人","风之图腾"},ang={["class:Hunter"]="对于途经血蹄村的荒野追踪者来说，哈肯指派的击落空中掠食者的任务是对其射术和猎物采集能力的一项重要早期考验。",["race:Tauren"]="哈肯·风之图腾体现了牛头人祖先的狩猎哲学：在平原上证明自律与自给自足，同时向大地母亲的野兽致敬。"},sec={{t="血蹄村猎手",b="哈肯·风之图腾位于血蹄村中心附近，他为那些学习牛头人狩猎之道的族人担任导师和向导。莫高雷平原上的生活既要求人们尊重自然世界，也需要维持部落生存的实际技能。哈肯会通过指引年轻的冒险者去狩猎盘旋在平顶山周围的本地掠食者，并收集它们的羽毛来评估猎人的耐心、准头以及在不浪费资源的情况下进行采集的能力，以此来考核他们。"}},faq={{q="谁是哈肯·风之图腾？",a="哈肯是一名居住在莫高雷中部血蹄村的牛头人猎人。他指导旅行者和刚起步的冒险者学习牛头人基本的追踪和狩猎传统。",al={"哈肯·风之图腾背景故事","哈肯是谁"}},{q="在哪里可以找到哈肯·风之图腾？",a="哈肯驻扎在血蹄村，这是一个位于雷霆崖南部、莫高雷中部的定居点。",al={"哈肯位置","哈肯·风之图腾在哪里"}},{q="哈肯会给冒险者什么任务？",a="他会提供“狩猎掠食者”任务，要求猎人们前往莫高雷的草原，猎杀野生的掠食者并收集它们坚韧的飞行羽毛。",al={"哈肯·风之图腾任务","狩猎掠食者任务"}},{q="哈肯和博温·风之图腾有关系吗？",a="他们共享风之图腾氏族的姓氏，这暗示了部落血缘或家族联系，尽管哈肯的注意力仍然集中在莫高雷当地村庄的狩猎事务上。",al={"哈肯和博温有关系吗","博温·风之图腾关系"}}},fx={b6c1a716={q="哈肯·风之图腾属于哪一方？",a="哈肯·风之图腾忠于牛头人部族和部落。他驻扎在血蹄村，全心支持当地居民，并指导年轻猎人维持莫高雷族人的生计。",al={"哈肯·风之图腾的阵营","哈肯为谁效力","哈肯是部落的吗"}},fffafcb2={q="哈肯·风之图腾想要什么？",a="哈肯希望有能力的猎人减少当地的 swoop 数量，并收集它们的羽针。莫高雷的平原要求人们自力更生；让初出茅庐的猎人接受对抗 swoop 的考验，既能收集有用的材料，也能磨炼年轻旅人的本领。",al={"哈肯想要什么","哈肯·风之图腾的目标","哈肯为什么发布任务"}},["4b75134c"]={q="哈肯·风之图腾为什么在血蹄村？",a="哈肯是居住在血蹄村的风之图腾部族成员，负责统筹中央平原的狩猎事务。他留在村中指引路过的猎人，确保野生动物数量保持平衡，并为村庄提供所需资源。",al={"哈肯为什么在这里","哈肯·风之图腾的职责","哈肯为什么在血蹄村"}}},fp="16,233,21.468.0,24.194.0,36.106.0,43.155.0,37.150.0"}
P.entries["npc:harlan-bagley"] = {n="哈兰·巴格雷",s="哈兰·巴格雷是一位人类护甲商和商人，在暴风城的繁华贸易区经营着狮王之傲军械库。他在该区中心北侧照看他的商店，为市民和来访的冒险者提供武器和装备。",h="哈兰·巴格雷是一位人类护甲商和商人，在暴风城的繁华贸易区经营着狮王之傲军械库。他在该区中心北侧照看他的商店，为市民和来访的冒险者提供武器和装备。",kw={"护甲商","哈兰·巴格雷","狮王之傲军械库","商人","暴风城","trade district"},ang={["faction:Alliance"]="像哈兰·巴格雷这样的商人，在周围领土的常规补给线受到威胁时，依然能为联盟的主要首都提供装备和商品。"},sec={{t="狮王之傲军械库",b="狮王之傲军械库坐落于贸易区北侧，是暴风城中心一家稳定的商业店铺。哈兰·巴格雷在柜台后管理库存并经营防御装备，依靠进出口贸易和区域信使来保持货架充足，以应对首都面临的遥远边境冲突和物资短缺问题。"}},faq={{q="哈兰·巴格雷是谁？",a="哈兰·巴格雷是一位人类店主和商人，经营着位于暴风城贸易区的装备商店——狮王之傲军械库。",al={"哈兰是谁","哈兰·巴格雷背景故事","狮王之傲军械库商贩"}},{q="我在哪里可以找到哈兰·巴格雷？",a="他位于暴风城贸易区中央广场北侧的狮王之傲军械库内。",al={"哈兰·巴格雷位置","哈兰在哪里","狮王之傲军械库位置"}},{q="他在暴风城的商业中扮演什么角色？",a="作为王国首都的一名当地商人，巴格雷供应护甲和装备，偶尔会雇佣冒险者来运送货物，并确保维持其军械库正常运营所需的物资供应。",al={"哈兰卖什么","哈兰·巴格雷的生意"}}},fp="13,243,20.277.0,21.134.0,31.134.0,47.184.0"}
P.entries["npc:harlo-barnaby"] = {n="哈尔罗·巴纳比",s="哈尔罗·巴纳比是一位住在米奈希尔港的受伤矮人难民。他在黑铁部族夺取丹莫德时侥幸逃脱了大屠杀，现在他正在提醒旅行者沼泽地北部的惨剧。",h="哈尔罗·巴纳比是一位住在米奈希尔港的受伤矮人难民。他在黑铁部族夺取丹莫德时侥幸逃脱了大屠杀，现在他正在提醒旅行者沼泽地北部的惨剧。",kw={"黑铁部族","丹莫德","哈尔罗·巴纳比","米奈希尔港","萨多尔大桥","湿地"},ang={["faction:Alliance"]="丹莫德的陷落威胁到了沼泽地与阿拉希之间关键的陆路通道，这使得哈尔罗的警告对联盟军队来说至关重要。",["race:Dwarf"]="哈尔罗就像是一个活生生的警示，提醒着人们针对奸诈的黑铁部族那场持久而血腥的部族战争，他们企图切断卡兹莫丹与北方的联系。"},sec={{t="逃离丹莫德",b="在那座北方要塞遭黑铁矮人突然而野蛮的袭击沦陷之前，哈尔罗·巴纳比一直住在丹莫德。在伏击的混乱中，哈尔罗向南逃往安全地带，却被一把流散的斧头击中了后背。重击之下他失去了知觉，但他竟奇迹般地在穿过沼泽地的路途中活了下来，最终在米奈希尔港醒来时已接受了包扎。虽然保住了性命，但伤痛和对那场屠杀的记忆使他无法重返故地，因此他敦促联盟的冒险者去调查他曾经的家园那冒着烟的废墟。"}},faq={{q="哈尔罗·巴纳比是谁？",a="哈尔罗·巴纳比是一位住在米奈希尔港的铁炉堡矮人，他在黑铁部族对丹莫德前哨站的残酷袭击中幸存了下来。",al={"哈尔罗·巴纳比","哈尔罗是谁","米奈希尔港矮人"}},{q="哈尔罗·巴纳比是怎么来到米奈希尔港的？",a="在逃离丹莫德的入侵时，他的后背被一把飞斧击中。他在撤退途中失去了知觉，醒来时已身处米奈希尔港，在当地治疗师的照料下脱离了危险。",al={"哈尔罗如何来到这里","哈尔罗·巴纳比背部伤势"}},{q="丹莫德发生了什么？",a="丹莫德被从萨多尔大桥南下的敌对黑铁矮人攻占并摧毁，当地的矮人守卫被消灭殆尽，幸存者则被驱赶进了湿地。",al={"丹莫德陷落","丹莫德发生了什么"}}},fx={["2ef93137"]={q="哈尔罗·巴纳比属于哪一方？",a="哈尔罗·巴纳比忠于铁炉堡和联盟。作为丹莫德北部前哨遭受灾难性袭击后的幸存者，他与铜须矮人同胞并肩作战，并寻找勇敢的联盟冒险者，共同对付占据北部山道的黑铁入侵者。",al={"哈尔罗·巴纳比的阵营","哈尔罗·巴纳比为谁效力","哈尔罗·巴纳比是联盟的吗"}},["4a6adfe0"]={q="哈尔罗·巴纳比想要什么？",a="哈尔罗仍在养伤，他希望你传递有关丹莫德陷落的消息并寻求援助。黑铁矮人攻破北部堡垒时，他侥幸逃出生天；如今他正寻找能干的战士，让他们惩治叛徒并夺回失去的一切。",al={"哈尔罗·巴纳比的动机","哈尔罗想让你做什么","哈尔罗·巴纳比的任务目标"}}},fp="13,226,20.526.0,21.131.0,48.192.0,26.181.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="海格纳·重枪",s="海格纳·重枪是一位矮人枪匠，驻守在从寒脊山小径通往卡拉诺斯的积雪道路旁。他经营着一个繁忙的射击场，并为当地的猎人和山地探险者提供枪械和弹药。",h="海格纳·重枪是一位矮人枪匠，驻守在从寒脊山小径通往卡拉诺斯的积雪道路旁。他经营着一个繁忙的射击场，并为当地的猎人和山地探险者提供枪械和弹药。",kw={"弹药","寒脊山小径","丹莫罗","枪匠","海格纳·重枪","卡拉诺斯","射击场"},ang={["class:Hunter"]="对于那些从寒脊山谷出发前往丹莫罗更广阔雪峰的神射手们，海格纳提供了必要的弹药、弹药包和备用枪械。",["race:Dwarf"]="矮人以精湛的工艺和枪法为傲，这使得海格纳路边的练习场成为了那些想要一试身手的旅行者们的天然聚集地。"},sec={{t="路上的枪匠",b="海格纳·重枪在寒脊山小径和卡拉诺斯之间的小型营地安营扎寨，为矮人神射手、旅行者和当地民兵提供服务。他的营地设有一个很受欢迎的射击场，山民们可以在此磨练枪法，以对抗丹莫罗四处游荡的野兽。由于要为如此多的射击爱好者提供补给，海格纳消耗弹药的速度非常快，这使他不得不持续依赖他的供应商——矮人工程师罗斯洛·鲁治运送新鲜的弹药。"}},faq={{q="海格纳·重枪是谁？",a="海格纳·重枪是一位矮人枪匠，他在寒脊山小径和卡拉诺斯之间的主路旁经营着一个户外靶场和营地。",al={"海格纳是谁","海格纳·重枪 npc","丹莫罗的枪匠"}},{q="海格纳从哪里获得弹药？",a="海格纳依赖罗斯洛·鲁治，一位位于丹莫罗其他地方的矮人工程供应商，来制造和供应维持他射击场运营所需的弹药。",al={"海格纳的供应商","谁为重枪供应物资","重枪的弹药任务"}},{q="海格纳为当地的矮人们做了什么？",a="他为当地的猎人和民兵成员配备枪支和弹药，同时为穿行于丹莫罗的神射手们提供练习场。",al={"海格纳为什么在这里","海格纳射击场","重枪的角色"}}},fx={f158c8ab={q="海格纳·重枪效忠于哪一方？",a="海格纳坚定地效忠于铁炉堡和联盟。他驻守在山路沿线，为丹莫罗当地的民兵、守卫和猎人配备可靠的火器，守护王国的雪山隘口，使其免受不断逼近的威胁。",al={"海格纳·重枪所属阵营","海格纳是联盟的吗","海格纳为谁效力"}},["932ff4bf"]={q="海格纳·重枪想要什么？",a="海格纳需要稳定的弹药供应，才能维持他的工坊和练习场运转。当地的神枪手和民兵不断在他的营地训练、补充装备，导致物资消耗很快，因此他的工程师伙伴罗斯洛·鲁治必须定期运送补给。",al={"海格纳需要什么","海格纳·重枪的目标","海格纳的任务"}},["3c40a283"]={q="海格纳·重枪为什么驻扎在这条路边？",a="他在寒脊山小径与卡拉诺斯之间的繁忙道路旁搭建了营地和射击场。这个理想地点既方便为刚走出山谷的新兵提供装备，也能支援守卫丹莫罗腹地雪原的巡逻队。",al={"海格纳为什么驻扎在外面","海格纳的营地位置","海格纳为什么搭建营地"}}},fp="17,225,22.470.0,25.142.0,37.168.0,42.144.0"}
P.entries["npc:henze-faulk"] = {n="亨兹·法奥克",s="亨兹·法奥克是一名矮人冒险者，人们发现他生命垂危地躺在艾尔文森林英雄哨岗外的石环旁。他在保护同伴时被迪菲亚潜行者击倒，他的存在对正在学习运用复活天赋的圣骑士学徒们来说，是一次关键的考验。",h="亨兹·法奥克是一名矮人冒险者，人们发现他生命垂危地躺在艾尔文森林英雄哨岗外的石环旁。他在保护同伴时被迪菲亚潜行者击倒，他的存在对正在学习运用复活天赋的圣骑士学徒们来说，是一次关键的考验。",kw={"迪菲亚潜行者","艾尔文森林","贾森·坦诺姆","亨兹·法奥克","英雄哨岗","复活","生命符记","神圣法典"},ang={["class:Paladin"]="亨兹·法奥克代表了你对神圣慈悲的第一次真正考验。用生命符记将他从死亡边缘拉回，这教会了一位圣骑士：圣光不仅仅是战斗的武器，更是一种可以对抗死亡的庄严力量。",["race:Dwarf"]="看到同族矮人倒在人类的土地上是一个令人清醒的提醒：迪菲亚歹徒不仅对暴风城的当地人构成威胁，对所有种族的旅行者来说都是致命的危险。"},sec={{t="英雄哨岗的牺牲",b="在暴风城以东的古老石环附近坐落着英雄哨岗，这里经常有在艾尔文森林中徘徊的迪菲亚强盗出没。亨兹·法奥克和他的朋友贾森·坦诺姆在这里遭到了迪菲亚掠夺者的伏击。为了确保贾森能活下来，亨兹挺身而出挡在危险面前，最终倒在了强盗的利刃之下。虽然他的同伴成功逃脱并向大教堂请求援助，但亨兹的身体依然徘徊在生死边缘，等待着携带生命符记的圣骑士进行神圣的干预。"}},faq={{q="亨兹·法奥克是谁？",a="亨兹·法奥克是一名铁炉堡矮人，人们发现他受了致命伤，躺在艾尔文森林英雄哨岗附近的石环旁。他在营救同伴贾森·坦诺姆时遭到了迪菲亚强盗的伏击并被击倒。",al={"亨兹·法奥克","英雄哨岗的矮人","艾尔文森林中垂死的矮人"}},{q="亨兹·法奥克为什么躺在地上？",a="亨兹在与贾森·坦诺姆结伴旅行时遭到了迪菲亚潜行者的伏击。他为了让贾森逃脱独自承受了大部分攻击，导致身受重伤，等待着圣光的修行者将其复活。",al={"亨兹为什么快死了","亨兹死了吗","亨兹·法奥克之死"}},{q="亨兹与圣骑士有什么联系？",a="亨兹是年轻圣骑士进行神圣法典试炼时的核心人物。圣骑士学徒会被授予一枚生命符记，并被派往艾尔文森林将亨兹从死亡边缘拉回，以证明他们掌握了圣光最神圣的救赎祝福。",al={"亨兹圣骑士任务","神圣法典矮人"}},{q="贾森·坦诺姆是谁？",a="贾森·坦诺姆是亨兹·法奥克的同伴。当两人被迪菲亚歹徒围困时，亨兹保护了贾森，使贾森得以幸存并向圣光大教堂寻求帮助。",al={"贾森是谁","贾森·坦诺姆朋友"}}},fp="11,170,28.363.0,19.187.0,39.218.0,39.255.0,20.162.0"}
P.entries["npc:heralath-fallowbrook"] = {n="赫尔拉斯·静水",s="赫尔拉斯·静水是一名濒死的暗夜精灵德鲁伊，被关押在剃刀沼泽深处。他被派去调查环绕着阿迦玛甘遗骸的荆棘腐化，却被剃刀沼泽的野猪人俘获并遭到残忍对待。在弥留之际，他希望能将自己的命运传达出去，并将一枚珍贵的坠饰带回达纳苏斯，交还给他的妻子。",h="赫尔拉斯·静水是一名濒死的暗夜精灵德鲁伊，被关押在剃刀沼泽深处。他被派去调查环绕着阿迦玛甘遗骸的荆棘腐化，却被剃刀沼泽的野猪人俘获并遭到残忍对待。在弥留之际，他希望能将自己的命运传达出去，并将一枚珍贵的坠饰带回达纳苏斯，...",kw={"阿迦玛甘","静水","亨里格·孤眉","赫尔拉斯","凋零的生命","野猪人","剃刀沼泽","塔莎拉"},ang={["class:Druid"]="目睹一位同袍德鲁伊被剃刀沼泽的残暴荆棘所摧毁，这深刻地提醒了人们：那股狂野且无法抑制的腐化力量正在南贫瘠之地肆意蔓延。",["race:NightElf"]="将赫尔拉斯的坠饰带回达纳苏斯，是为了向一位倒下的兄弟致敬，他为了理解并治愈卡利姆多那片伤痕累累的土地而献出了生命。"},sec={{t="悲剧的任务",b="赫尔拉斯·静水受族人派遣，去调查远古野猪神阿迦玛甘以及正在扼杀南贫瘠之地的蔓延荆棘，他试图寻找剃刀沼泽腐化的根源。然而这名暗夜精灵不仅没有找到答案，反而被野猪人俘虏。他被锁在肮脏的兽栏里，不断遭受毒打，最终伤重染病。在生命走到尽头之前，他向同为囚犯的矮人亨里格·孤眉分享了他所知的信息，恳求他向萨兰纳尔的哨所发出警告，提醒他们注意野猪人巫婆卡尔加·刺肋所煽动的侵略行径。"},{t="临终遗愿",b="虽然孤眉成功逃脱，但赫尔拉斯已经虚弱得无法逃离。这名德鲁伊在剃刀沼泽错综复杂的兽栏中徘徊在死亡边缘，他仅存的意识只够支撑他恳求过往的冒险者。他请求的不是营救，而是希望冒险者能从俘虏他的敌人手中找回他妻子塔莎拉的坠饰，并将其带回达纳苏斯，好让她知道他的结局，并让她知道他在生命的最后一刻仍铭记着她。"}},faq={{q="赫尔拉斯·静水是谁？",a="赫尔拉斯·静水是一名被关押在剃刀沼泽内的暗夜精灵德鲁伊。他前往贫瘠之地是为了研究荆棘的腐化以及已故的野猪半神阿迦玛甘的遗迹，但被野猪人俘虏并遭受了致命的折磨。",al={"赫尔拉斯是谁","赫尔拉斯·静水","剃刀沼泽的暗夜精灵"}},{q="赫尔拉斯在剃刀沼泽遭遇了什么？",a="在被剃刀沼泽的野猪人俘获后，赫尔拉斯遭到了殴打并被关押在小屋中。在无尽的虐待和疾病的双重折磨下，他的身体垮了，以至于当救援者找到他时，他已奄奄一息。",al={"赫尔拉斯为什么会死","赫尔拉斯·静水遭遇了什么"}},{q="赫尔拉斯请求旅行者做什么？",a="由于深知自己活不成了，赫尔拉斯乞求冒险者从野猪人手中找回他妻子的坠饰，并将其带回达纳苏斯，将他死亡的悲剧消息传达给她。",al={"赫尔拉斯任务","凋零的生命任务"}},{q="亨里格·孤眉与赫尔拉斯是什么关系？",a="亨里格·孤眉是与赫尔拉斯关在同一个兽栏里的矮人俘虏。在亨里格逃跑前，赫尔拉斯与他分享了关于阿迦玛甘的重要信息，并恳求他将卡尔加·刺肋的动向通知萨兰纳尔的哨所。",al={"亨里格·孤眉 赫尔拉斯","剃刀沼泽的矮人俘虏"}}},fx={["4cf4e465"]={q="赫尔拉斯·静水效忠于哪一方？",a="赫尔拉斯是一名效忠于达纳苏斯和联盟的暗夜精灵。他作为族中的德鲁伊，受命深入南贫瘠之地，调查野猪人中滋生的诡异腐化，并守护卡利姆多，抵御剃刀沼泽深处涌动的黑暗。",al={"赫尔拉斯·静水所属阵营","赫尔拉斯是联盟的吗","赫尔拉斯的效忠对象"}},["6e64ea11"]={q="赫尔拉斯·静水为什么会在剃刀沼泽？",a="他来到这里调查有关倒下的远古守护者阿迦玛甘的种种传闻，并查明侵蚀剃刀沼泽的腐化源头。不幸的是，他的探险以惨剧告终：凶悍的剃刀沼泽野猪人俘虏了他，对他施以残酷囚禁，并使他身负致命伤。",al={"赫尔拉斯为什么在这里","赫尔拉斯在剃刀沼泽的目的","赫尔拉斯为什么来到剃刀沼泽"}}},fp="20,351,16.596.0,12.413.1,28.252.0,48.213.0,39.174.0,36.262.0"}
P.entries["npc:herod"] = {n="赫洛德",s="赫洛德是血色十字军中一位享有盛名的勇士和狂战士，统领着血色修道院内的军械库。他以凶猛的武艺和不屈的狂热而闻名，负责训练新兵掌握发动圣战所需的残酷近战技巧。无论是联盟的异见者，还是幽暗城部落的统治者，都想要他的命，以削弱十字军的军事核心。",h="赫洛德是血色十字军中一位享有盛名的勇士和狂战士，统领着血色修道院内的军械库。他以凶猛的武艺和不屈的狂热而闻名，负责训练新兵掌握发动圣战所需的残酷近战技巧。无论是联盟的异见者，还是幽暗城部落的统治者，都想要他的命，以削弱十...",kw={"军械库","狂战士","赫洛德","虔诚的莱雷恩","破坏者","血色十字军","血色修道院","瓦里玛萨斯"},ang={["class:Warrior"]="赫洛德是一位狂暴战士的典型，他那愤怒的旋风斩和鲁莽的进攻使他成为血色十字军新兵中令人敬畏的武学典范。",["faction:Alliance"]="回应虔诚的莱雷恩请求的联盟英雄们，可以亲眼见证曾经高贵的洛丹伦保卫者们是如何在像赫洛德这样的领袖领导下，堕落成疯狂、狂热的嗜血之徒的。",["faction:Horde"]="对于部落，尤其是被遗忘者来说，消灭赫洛德直接执行了瓦里玛萨斯的命令，以打破威胁提瑞斯法林地边界的领导层。"},sec={{t="军械库勇士",b="在血色修道院军械库那防御森严的大厅里，赫洛德是十字军尚武激进的化身。与大教堂里引导神圣魔法的施法者和圣骑士不同，赫洛德依靠的是纯粹、嗜血的肉体力量。他身披锁甲，手持巨型双手斧，亲自训练成群的血色新兵，向他们灌输对消灭任何非其狂热事业盟友之人的狂暴忠诚。"},{t="高优先级目标",b="由于赫洛德负责管理十字军前线战士的装备与军事训练，对于任何试图瓦解该组织的人来说，击败他至关重要。虔诚的莱雷恩曾是十字军的一员，如今因对组织疯狂行径的失望而隐居在南海镇，他呼吁处决赫洛德以粉碎其军事领导层。在洛丹伦各地，幽暗城的恐惧魔王瓦里玛萨斯也同样寻求处决他，以清除这个毗邻被遗忘者领地的危险人类堡垒。"}},faq={{q="赫洛德是谁？",a="赫洛德是一位精英人类战士，也是血色修道院军械库的指挥官。他是修道院的四位主要领袖之一，负责为十字军狂热的近战战士装备武器并进行操练。",al={"赫洛德背景故事","赫洛德是谁","血色修道院赫洛德"}},{q="赫洛德在哪里？",a="赫洛德位于提瑞斯法林地东北部的血色修道院军械库的中心。他在一个被看台环绕的中央训练场等待着挑战者。",al={"赫洛德在哪里","赫洛德位置","寻找赫洛德"}},{q="为什么部落想要赫洛德死？",a="代表幽暗城被遗忘者的恐惧魔王瓦里玛萨斯，寻求消灭修道院的关键指挥官（包括赫洛德），以铲除就在被遗忘者首都门口的十字军残留威胁。",al={"瓦里玛萨斯赫洛德任务","为什么部落要杀赫洛德","进入血色修道院"}},{q="为什么联盟想要赫洛德死？",a="驻扎在希尔斯布莱德丘陵的前血色十字军成员虔诚的莱雷恩，认识到该组织已经沦落到狂热的地步。他请求联盟勇士清除赫洛德，以剥夺十字军残酷的战士领导层。",al={"以圣光之名","虔诚的莱雷恩赫洛德","为什么联盟要杀赫洛德"}},{q="当赫洛德被击败时会发生什么？",a="在赫洛德被击败后，一大群年轻的血色新兵会从周围的兵营涌入训练场，为他们的导师复仇，这充分体现了他所培养的学生对他那深沉的忠诚。",al={"血色新兵","赫洛德新兵冲锋","赫洛德死亡事件"}},{q="赫洛德是什么类型的战士？",a="赫洛德是一位狂战士和战士，而非传统的圣骑士。他使用凶猛的冲锋和横扫的旋风斩来粉碎敌人，依靠纯粹的物理狂暴而非圣光法术。",al={"赫洛德战斗风格","赫洛德是圣骑士吗"}}},fx={["3c3e6bcb"]={q="赫洛德效忠于哪一方？",a="赫洛德是血色十字军的高级指挥官，是驻守在血色修道院内的四位关键领袖之一。他狂热地忠于血色十字军的激进使命，负责指挥他们的军事训练和军械库，对付一切被血色十字军视为不洁或敌对的人。",al={"赫洛德所属阵营","赫洛德为谁效力","赫洛德属于哪一方"}},["78320a40"]={q="赫洛德想要什么？",a="赫洛德一心训练血色十字军的新一代战士，消灭他们的敌人。他负责军械库，训练新兵，使他们拥有和自己一样永不熄灭的战斗热忱，并力图击溃任何胆敢擅闯修道院圣地的人。",al={"赫洛德的目标","赫洛德的目的","赫洛德想做什么"}},["60fea3ae"]={q="赫洛德为什么在这里？",a="赫洛德统领血色修道院的军械库区域。作为血色新兵的勇士和教官，他监管血色十字军的军械库，并亲自考验任何胆敢挑战血色十字军核心地带的人。",al={"赫洛德为什么在军械库","赫洛德为什么在血色修道院","赫洛德在军械库的职责"}},f73350c1={q="赫洛德与哪些人有联系？",a="赫洛德与血色修道院的核心领袖并肩共事，其中包括大检察官怀特迈恩、血色十字军指挥官莫格莱尼和驯犬者洛克希。他们共同统治着提瑞斯法林地的血色十字军堡垒。",al={"谁领导赫洛德","赫洛德的盟友","赫洛德与谁共事"}},["9c060a47"]={q="赫洛德为何声名远扬或令人畏惧？",a="赫洛德被称为血色勇士，以凶猛的狂战士战斗风格闻名。他挥舞着巨大的战斧，尤其以旋转挥砍、化作势不可挡的钢铁旋风而臭名昭著，能将附近的敌人撕成碎片。",al={"赫洛德为何令人畏惧","赫洛德的名声","赫洛德为何如此危险"}}},fp="5,373,26.452.0,22.488.0,13.228.0,23.200.0,35.239.0,38.254.0,36.201.1,30.210.0"}
P.entries["npc:high-executor-darthalia"] = {n="高级执行官达萨利亚",s="高级执行官达萨利亚是一位驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者高级军事指挥官。她在Sylvanas Windrunner和瓦里玛萨斯的直接领导下行动，指挥被遗忘者针对南海镇人类据点和当地辛迪加暴徒的军事行动。她的领导对于巩固部落在洛丹伦的南部侧翼至关重要。",h="高级执行官达萨利亚是一位驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者高级军事指挥官。她在Sylvanas...",kw={"达萨利亚","高级执行官","希尔斯布莱德","希尔斯布莱德丘陵","南海镇","希尔瓦娜斯","辛迪加","塔伦米尔","瓦里玛萨斯"},ang={["faction:Alliance"]="对于南海镇的人类及其盟友来说，达萨利亚是威胁他们在这片土地上最后一个据点的无情攻击的幕后策划者。",["faction:Horde"]="部落冒险者向达萨利亚汇报，以遏制联盟的侵略并守住希尔斯布莱德丘陵这片冲突前线。",["race:Undead"]="对于被遗忘者来说，达萨利亚代表了幽暗城的钢铁意志，确保洛丹伦牢牢掌握在自由意志的亡灵手中。"},sec={{t="塔伦米尔指挥官",b="高级执行官达萨利亚在塔伦米尔开展行动，担任希尔斯布莱德丘陵地区被遗忘者部队的作战指挥官。她的主要战略目标是遏制人类抵抗力量的扩张，牵制南海镇的联盟部队，并追捕那些盘踞在周边乡村的法外之徒——辛迪加盗贼。所有针对希尔斯布莱德南部的攻势都由她直接指挥。"},{t="希尔斯布莱德之战",b="在幽暗城最高层——女妖之王和她的恐惧魔王副官瓦里玛萨斯——的直接命令下，达萨利亚负责监督希尔斯布莱德全境旷日持久的消耗战。她协调侦察任务、对人类领导层进行针对性打击，并悬赏通缉那些威胁到被遗忘者在北洛丹伦统治地位的危险不法分子。"}},faq={{q="高级执行官达萨利亚是谁？",a="高级执行官达萨利亚是一位驻扎在希尔斯布莱德丘陵的被遗忘者军事领袖。她负责指挥部落和被遗忘者的军事力量，打击南海镇的人类城镇，并清除地区内的敌对威胁。",al={"达萨利亚是谁","达萨利亚身份","执行官达萨利亚"}},{q="达萨利亚在哪里？",a="她从塔伦米尔指挥被遗忘者部队，组织军队并在洛丹伦中部地区协调攻势。",al={"达萨利亚位置","达萨利亚在哪里","执行官达萨利亚地图"}},{q="达萨利亚受谁指挥？",a="达萨利亚在幽暗城的直接军事指挥体系下运作，听命于Sylvanas Windrunner和恐惧魔王瓦里玛萨斯，他们共同负责协调被遗忘者领地的防御和扩张。",al={"达萨利亚首领","达萨利亚阵营","谁指挥达萨利亚"}},{q="达萨利亚会给冒险者什么任务？",a="达萨利亚派遣部落勇士直接打击人类定居点，处决危险的法外之徒，并追捕在希尔斯布莱德丘陵各地活动的辛迪加成员。",al={"达萨利亚任务","达萨利亚的任务","达萨利亚想要什么"}},{q="为什么达萨利亚要攻击南海镇的人类？",a="南海镇是联盟在洛丹伦的主要军事据点。达萨利亚的任务是压制人类的势力，保护塔伦米尔，并防止联盟向北推进至幽暗城。",al={"为什么要攻击南海镇","南海镇战争","希尔斯布莱德冲突"}},{q="达萨利亚在被遗忘者军队中是什么军衔？",a="作为一名高级执行官，达萨利亚拥有被遗忘者军事等级中最高的外勤军衔之一，这使她能够指挥该地区的部队、前哨站和作战策略。",al={"高级执行官军衔","达萨利亚头衔"}}},fx={c2c985e7={q="高级执行官达萨利亚效忠于哪一方？",a="高级执行官达萨利亚为被遗忘者和部落效力。她是希尔斯布莱德丘陵的高级军事指挥官，受希尔瓦娜斯·风行者女士和瓦里玛萨斯指挥，负责统领部落在当地的行动，防止联盟势力侵入。",al={"达萨利亚所属阵营","达萨利亚为谁而战","达萨利亚是部落的吗"}},["77f4a495"]={q="高级执行官达萨利亚想要什么？",a="达萨利亚力图遏制人类势力扩张，并根除联盟在希尔斯布莱德丘陵的影响。她协调对南海镇等附近人类据点的袭击，并铲除辛迪加等敌对势力，以确保被遗忘者对这片领土的统治不受挑战。",al={"达萨利亚的目标","达萨利亚想做什么","达萨利亚的目的"}},f4963853={q="高级执行官达萨利亚为什么在这里？",a="她驻扎在塔伦米尔，负责监督被遗忘者在希尔斯布莱德丘陵的战役。她以这处前线中心为据点，组织针对南方敌对人类聚居地的战争行动，并守卫通往提瑞斯法林地和幽暗城的南部通道。",al={"达萨利亚为什么在塔伦米尔","达萨利亚为何身处希尔斯布莱德","达萨利亚在此地的原因"}}},fp="23,385,24.440.0,21.364.0,31.235.0,29.129.0,29.208.0,46.198.0,51.216.0,50.207.0"}
P.entries["npc:high-executor-derrington"] = {n="高级执行官德灵顿",s="高级执行官德灵顿指挥着驻扎在提瑞斯法林地东部边界亡灵壁垒的被遗忘者先锋部队。作为一名务实的军官，他负责监督部落在西瘟疫之地前线对天灾军团和血色十字军威胁的防御。在这个设防的壁垒中，他引导经验丰富的勇士前往诸如安多哈尔和通灵学院等冲突不断的废墟。",h="高级执行官德灵顿指挥着驻扎在提瑞斯法林地东部边界亡灵壁垒的被遗忘者先锋部队。作为一名务实的军官，他负责监督部落在西瘟疫之地前线对天灾军团和血色十字军威胁的防御。在这个设防的壁垒中，他引导经验丰富的勇士前往诸如安多哈尔和通...",kw={"andorhal","亡灵壁垒","德灵顿","被遗忘者","高级执行官德灵顿","天灾军团","提瑞斯法林地","西瘟疫之地"},ang={["class:Warrior"]="德灵顿体现了一名前线士兵严峻而务实的勇气，比起宫廷权谋，他更看重军事能力和战场成果。",["faction:Horde"]="对于抵达提瑞斯法林地的部落旅行者来说，德灵顿是指挥部队进入西瘟疫之地危险冲突中的主要军事指挥官。",["race:Undead"]="德灵顿代表了被遗忘者军队的军事支柱，专注于将他们收复的土地从天灾军团的再侵略和血色十字军的狂热中保护出来。"},sec={{t="边境指挥官",b="高级执行官德灵顿站在亡灵壁垒的防御工事前，作为提瑞斯法林地那受诅咒的“安宁”与西瘟疫之地腐烂恐怖之间的守门人。德灵顿对幽暗城的政治博弈毫无耐心，他认为前线是纯粹的生存试炼场。对于那些想要证明自己实力的部落士兵和雇佣兵，德灵顿会直接下达军事指令，派遣斥候和突击小队深入瘟疫肆虐的领土，在敌人入侵提瑞斯法之前将其削弱。"},{t="双线战争",b="德灵顿的防御阵地在多个方向上都受到围攻。向东是盘踞在安多哈尔破碎城镇中的天灾军团，并通过腐化大锅向四周蔓延。与此同时，血色十字军的狂热信徒也在争夺北方的防御工事，并不时与被遗忘者的巡逻队发生冲突。德灵顿协调着外科手术式的反击，破坏血色十字军的防线，并有系统地干扰天灾军团的瘟疫大锅场，以保卫东部边界。"}},faq={{q="高级执行官德灵顿是谁？",a="高级执行官德灵顿是亡灵壁垒的被遗忘者最高指挥官，这座军事前哨将提瑞斯法林地与西瘟疫之地隔开。他负责协调部落向东的战略推进，以对抗天灾军团和血色十字军。",al={"德灵顿","德灵顿是谁","高级执行官德灵顿背景故事"}},{q="德灵顿在哪里？",a="他驻扎在亡灵壁垒，这是一个位于提瑞斯法林地最东端，通往西瘟疫之地的道路上的设防要冲。",al={"德灵顿在哪里","德灵顿位置","寻找高级执行官德灵顿"}},{q="德灵顿在亡灵壁垒的目标是什么？",a="德灵顿的目标是通过保持针对天灾军团的强大防御周界并向东挺进西瘟疫之地，来确保被遗忘者的生存。他指派冒险者侦察安多哈尔、摧毁瘟疫大锅，并清除血色十字军的行动。",al={"德灵顿想要什么","亡灵壁垒的作用","德灵顿的任务"}},{q="德灵顿关心幽暗城的政治吗？",a="不。德灵顿对宫廷阴谋家和政客表现出公开的蔑视，他指出在前线，生存必须每天通过战斗来争取，那里不存在那种奢侈。",al={"德灵顿的个性","德灵顿参与政治吗"}},{q="德灵顿派遣士兵去对付哪些主要威胁？",a="德灵顿主要针对盘踞在安多哈尔废墟中的天灾军团、通灵学院内的黑暗通灵师，以及附近威胁部落东部补给线的血色十字军驻军。",al={"德灵顿的任务线","德灵顿对付什么敌人"}},{q="为什么亡灵壁垒防御如此严密？",a="亡灵壁垒是提瑞斯法林地的相对安全区与瘟疫之地的活跃战斗区之间的主要瓶颈。德灵顿的部队守卫着这个通道，以防止天灾军团的大规模虫群或血色十字军的远征部队直接横扫向幽暗城。",al={"为什么要建立亡灵壁垒","亡灵壁垒背景故事"}}},fx={["895ac470"]={q="高级执行官德灵顿效忠于哪一方？",a="高级执行官德灵顿坚定地支持被遗忘者和部落。作为黑暗女王麾下的高级军事指挥官，他一心守卫他们的领土，确保他们在洛丹伦拥有立足之地，对抗一切企图将他们赶尽杀绝的势力。",al={"德灵顿所属阵营","德灵顿为谁效力","德灵顿是部落的吗"}},e8355a95={q="高级执行官德灵顿为什么驻守在亡灵壁垒？",a="德灵顿负责指挥提瑞斯法林地的前线防御。他驻守在提瑞斯法与西瘟疫之地的边界，监督防御工事，阻挡天灾军团的入侵，并为被遗忘者向东推进、深入疫病之地腹地做好准备。",al={"德灵顿为什么在这里","德灵顿驻守亡灵壁垒","德灵顿为什么在边境"}}},fp="24,400,26.575.0,19.517.0,32.252.0,28.161.0,46.293.0,46.176.0,57.199.0,40.282.0"}
P.entries["npc:high-executor-hadrec"] = {n="高级执行官哈德瑞克",s="高级执行官哈德瑞克是驻守在银松森林瑟伯切尔的被遗忘者驻军的军事指挥官。从这座中心地穴出发，他监督着针对该地区威胁的防御工作，包括烂皮豺狼人氏族，并调查整个地区侦察兵的失踪事件。他是指挥整个银松森林部落行动的主要军官。",h="高级执行官哈德瑞克是驻守在银松森林瑟伯切尔的被遗忘者驻军的军事指挥官。从这座中心地穴出发，他监督着针对该地区威胁的防御工作，包括烂皮豺狼人氏族，并调查整个地区侦察兵的失踪事件。他是指挥整个银松森林部落行动的主要军官。",kw={"死亡猎手","芬里斯岛","哈德瑞克","高级执行官","烂皮","瑟伯切尔","影牙城堡","银松森林"},ang={["class:Rogue"]="哈德瑞克非常依赖死亡猎手提供的情报，经常派遣隐秘的特工去寻找失踪的战友，并收集敌人的体液和文件。",["faction:Horde"]="从卡利姆多抵达的被遗忘者盟友会向哈德瑞克报到，以协助稳定银松森林，并亲身体会到部落在北洛丹伦的立足点是多么的不稳固。",["race:Undead"]="对于从丧钟镇向南旅行的被遗忘者来说，哈德瑞克代表了幽暗城最高指挥部的声音，将新生的亡灵转变为有组织的洛丹伦保卫者。"},sec={{t="瑟伯切尔的指挥官",b="高级执行官哈德瑞克驻扎在昏暗的瑟伯切尔，指挥着被遗忘者在整个银松森林的军事行动。虽然提瑞斯法林地在黑暗女王的部队控制下相当稳固，但银松森林依然危机四伏，受到敌对的达拉然法师、野性狼人以及不断侵扰的豺狼人的威胁。哈德瑞克承担着巩固被遗忘者领土的重任，并负责铲除任何挑战幽暗城在首都以南权威的势力。"},{t="烂皮之祸",b="哈德瑞克目前的大部分关注点都围绕着烂皮豺狼人和芬里斯岛。这些受到亡灵腐蚀的野兽已经侵扰了死者田野和洛丹米尔湖岸，对被遗忘者的巡逻队构成了不可预测且凶残的威胁。哈德瑞克派遣特工去搜寻破败的渡口和腐烂的农舍以寻找线索，查明是什么在增强这些野兽的力量，并准备对它们的岛屿据点进行全面打击。"},{t="注视影牙城堡",b="除了豺狼人的滋扰，哈德瑞克还密切关注着死亡猎手——被遗忘者秘密的盗贼情报机构——收集的情报。当潜伏的特工在影牙城堡诡异的尖塔附近失踪时，哈德瑞克会委派冒险者去查明他们的命运，确保黑暗女王能够及时了解狡诈的大法师阿鲁高及其被诅咒的狼人的动向。"}},faq={{q="高级执行官哈德瑞克是谁？",a="哈德瑞克是一位被遗忘者军官，军衔为高级执行官。他指挥着驻扎在瑟伯切尔的驻军，这使他成为被遗忘者在银松森林地区行动的最高权威。",al={"哈德瑞克背景故事","哈德瑞克是谁","瑟伯切尔指挥官"}},{q="在哪里可以找到高级执行官哈德瑞克？",a="他位于瑟伯切尔内，这是位于银松森林中部南北主干道旁的一处被遗忘者定居点。",al={"哈德瑞克位置","哈德瑞克在哪里","寻找哈德瑞克"}},{q="哈德瑞克指挥玩家对抗哪些威胁？",a="哈德瑞克指挥士兵和冒险者对抗肆虐死者田野和芬里斯岛的烂皮豺狼人。他还负责监督寻找失踪的死亡猎手间谍的任务，并揭开影牙城堡内正在发生的事情。",al={"哈德瑞克任务","哈德瑞克做什么","银松森林任务"}},{q="高级执行官在被遗忘者军事结构中负责什么？",a="高级执行官是被遗忘者军队中高级别的战地指挥官，受希尔瓦娜斯·风行者之命，被赋予对整个区域性前哨站或前线的全面战略监督权。",al={"被遗忘者高级执行官","高级执行官军衔","哈德瑞克军衔"}},{q="为什么哈德瑞克对芬里斯岛感兴趣？",a="芬里斯岛已成为烂皮豺狼人的主要巢穴。为了确保洛丹米尔湖及周边水道的被遗忘者补给线安全，哈德瑞克正在协调侦察行动，并计划进行最终突袭以摧毁豺狼人的领导层。",al={"芬里斯岛哈德瑞克","为什么突袭芬里斯岛","烂皮豺狼人与芬里斯岛"}},{q="哈德瑞克与影牙城堡有什么联系？",a="哈德瑞克与被遗忘者的间谍组织——死亡猎手进行协调。当派往影牙城堡的侦察兵失去联系时，哈德瑞克会委派受信任的特工前往调查城堡，并查明他们遭遇了什么。",al={"影牙城堡哈德瑞克","哈德瑞克与阿鲁高","影牙城堡中的死亡猎手"}}},fx={["4117c6ac"]={q="高级执行官哈德瑞克与谁关系密切？",a="哈德瑞克与被遗忘者的秘密情报部门——亡首卫队——密切协作，接收前线报告，并派遣援军揭露潜藏的威胁。他还与药剂师伦弗利尔等当地专家合作，研究诸如腐皮豺狼人之类的地区威胁。",al={"哈德瑞克的盟友","哈德瑞克的关系","哈德瑞克与谁共事"}},["82ec3fb8"]={q="高级执行官哈德瑞克效忠于哪一方？",a="高级执行官哈德瑞克是部落的一员，为被遗忘者和黑暗女王希尔瓦娜斯·风行者效力。他驻扎在瑟伯切尔，统领被遗忘者在银松森林的军事行动，直接为幽暗城的利益行事。",al={"哈德瑞克所属阵营","哈德瑞克为谁效力","哈德瑞克是部落的吗"}},["3524c842"]={q="高级执行官哈德瑞克想要什么？",a="哈德瑞克的目标是为被遗忘者夺取银松森林，并保护幽暗城的南翼。他协调各方收集敌军动向的情报，剿灭盘踞当地的腐皮豺狼人，并清除从芬里斯岛到影牙城堡外围潜伏在森林各处的敌对威胁。",al={"哈德瑞克的目标是什么","哈德瑞克的动机","哈德瑞克在银松森林的目标"}},ed357496={q="高级执行官哈德瑞克为什么在瑟伯切尔？",a="哈德瑞克驻扎在瑟伯切尔，因为这里是被遗忘者在银松森林的中央军事和行动据点。作为高级执行官，他负责监督地区行动、协调亡灵哨兵的前线报告，并派遣勇士消除步步逼近的威胁，以确保被遗忘者统治这片领土。",al={"哈德瑞克为什么在瑟伯切尔","哈德瑞克在银松森林的位置","哈德瑞克为什么在银松森林"}}},fp="20,377,26.464.0,20.432.0,17.369.1,28.201.0,40.130.0,48.229.0,60.208.0,40.233.0,47.226.0"}
P.entries["npc:high-inquisitor-fairbanks"] = {n="大检察官法尔班克斯",s="大检察官法尔班克斯曾是白银之手骑士团备受尊崇的牧师，也是大领主亚历山德罗斯·莫格莱尼的亲信顾问。他曾是洛丹伦幸存的守卫者中杰出的精神领袖，但他的命运却与血色十字军的堕落紧紧联系在了一起。",h="大检察官法尔班克斯曾是白银之手骑士团备受尊崇的牧师，也是大领主亚历山德罗斯·莫格莱尼的亲信顾问。他曾是洛丹伦幸存的守卫者中杰出的精神领袖，但他的命运却与血色十字军的堕落紧紧联系在了一起。",kw={"灰烬使者","大教堂","法尔班克斯","检察官","莫格莱尼","雷诺","血色修道院","白银之手","斯坦索姆"},ang={["class:Paladin"]="法尔班克斯见证了白银之手最黑暗的时刻：那一天，一位受人尊敬的圣骑士将一把传奇圣剑刺向了自己的父亲。",["class:Priest"]="在堕落之前，法尔班克斯是圣光的一名牧师，也是灰烬使者大领主莫格莱尼最亲近的顾问。",["faction:Alliance"]="法尔班克斯的悲剧可以追溯到已陷落的洛丹伦王国，当时大联盟的残部分裂成了狂热者和被遗弃者。",["race:Undead"]="法尔班克斯证明了血色十字军终极的伪善：他们将自己人死后的尸体藏在祭坛后，却在焚烧无辜的被遗忘者。"},sec={{t="灰烬使者的顾问",b="在洛丹伦陷落之前，法尔班克斯是白银之手骑士团中受人尊敬的圣职者，也是传奇武器灰烬使者的持有者——大领主亚历山德罗斯·莫格莱尼最信任的顾问。当莫格莱尼、大将军阿比迪斯和大检察官伊希利恩创立血色十字军时，他便侍奉在大领主身侧。当时的血色十字军是一个誓要消灭天灾军团的高尚组织。"},{t="斯坦索姆的背叛",b="当大领主的长子雷诺将他们引诱至斯坦索姆外的一场可怕的天灾军团伏击时，法尔班克斯正陪同在亚历山德罗斯·莫格莱尼身旁。法尔班克斯在亡灵爪牙的重压下很快倒下，被埋在成堆的腐烂尸体之下。从这个恐怖的位置，他默默目睹了雷诺夺过掉落的灰烬使者，并将其刺入自己父亲的心脏，用弑父之罪玷污了这把圣剑。在屠杀中幸存下来的法尔班克斯从死人堆中爬出，回到了血色修道院以揭露雷诺的背叛。"},{t="处决与流放",b="法尔班克斯绝望的警告让洛丹伦剩余的守卫者分崩离析。那些相信他恐怖陈述的人离开了这个狂热的组织，组建了银色黎明。而那些仍忠于雷诺和赛丹·达索汉的人则称法尔班克斯为亵渎者和疯子。法尔班克斯被血色十字军秘密处决。十字军并没有给予他神圣的安葬，而是将他的尸体丢弃在大教堂祭坛后的一个隐藏房间里。在那里，他最终复生为他们誓要清洗的怪物。"}},faq={{q="我在哪里可以找到大检察官法尔班克斯？",a="法尔班克斯隐藏在血色修道院的大教堂区内。要找到他，需要进入主祭坛右侧的侧室，拉动一个隐藏的壁挂火把，这会打开通往一处隐蔽墓穴的秘密石门。",al={"法尔班克斯位置","如何找到法尔班克斯","法尔班克斯的秘密房间","修道院秘密大门"}},{q="为什么法尔班克斯是不死生物？",a="没有人确切解释过他是如何复生的。在斯坦索姆的伏击中，法尔班克斯曾被埋在成堆的天灾军团尸体下；而在他因指控血色十字军领导层而被处决后，他被丢弃的尸体被藏在一个秘密房间里，最终在那里复生成为了不死者。",al={"为什么法尔班克斯是僵尸","法尔班克斯是天灾军团吗","为什么法尔班克斯是不死者"}},{q="法尔班克斯在被处决前是谁？",a="法尔班克斯曾是白银之手骑士团的一名虔诚牧师，也是灰烬使者——大领主亚历山德罗斯·莫格莱尼的首席顾问。他是洛丹伦幸存守卫者最初的精神领袖之一。",al={"法尔班克斯背景故事","大检察官法尔班克斯是谁","法尔班克斯剧情"}},{q="是什么导致了血色十字军和银色黎明的分裂？",a="当法尔班克斯从斯坦索姆回来并报告他在那里目睹的一切时，该组织分裂了。那些相信法尔班克斯并拒绝雷诺狂热行径的人离开了，成立了银色黎明，而雷诺的狂热追随者则留在了血色十字军。",al={"银色黎明的起源","银色黎明为何分裂","法尔班克斯与银色黎明"}},{q="血色十字军为什么要杀死法尔班克斯？",a="血色十字军的领导层将他关于斯坦索姆事件的证词打上恶意亵渎的烙印。十字军处决他是为了掩盖真相。",al={"血色十字军为何杀害法尔班克斯","谁杀害了法尔班克斯","法尔班克斯的处决"}},{q="谁接替法尔班克斯担任了大检察官？",a="在法尔班克斯被处决并秘密囚禁后，怀特迈恩晋升为大检察官，与指挥官雷诺·莫格莱尼一同主持血色修道院的审讯工作。",al={"现任大检察官是谁","法尔班克斯的继任者","谁继任了法尔班克斯"}}},fx={["14cc9219"]={q="大检察官法尔班克斯如今站在哪一边？",a="法尔班克斯如今不再属于任何阵营。他曾是白银之手备受尊崇的牧师，也是高阶领主亚历山德罗斯·莫格莱尼最亲密的知己；然而，他遭到谋杀并死而复生后，失去了理智，也不再效忠旧日阵营。亡灵瘟疫将他吞噬，他又被昔日由他引导的狂热者囚禁起来。任何活物踏入他隐秘墓室，都会遭到他猛烈攻击；他在无尽的痛苦与疯狂中肆意出手。",al={"法尔班克斯的阵营","法尔班克斯有敌意吗","法尔班克斯站在哪边"}},d7d74c1e={q="法尔班克斯为何藏身于血色修道院？",a="在斯坦索姆的伏击中幸存后，法尔班克斯回到血色修道院，公开反对十字军的领袖雷诺·莫格莱尼和赛丹·达索汉。他被指为异端和骗子，随后遭处决，以免他继续发声。十字军接着将他的尸体丢弃在大教堂祭坛后方的一间密室里，把复活的尸身秘密封存起来。",al={"法尔班克斯为何在修道院","法尔班克斯为何藏在密室","法尔班克斯的密室"}},edd0ed20={q="大检察官法尔班克斯曾与谁关系密切？",a="法尔班克斯曾是高阶领主亚历山德罗斯·莫格莱尼——传奇武器灰烬使者的主人——最亲密的顾问与同伴；莫格莱尼与高阶将领阿比迪斯、以及大检察官伊森利恩创立血色十字军时，他也在场。他随亚历山德罗斯前往斯坦索姆，目睹的一切促使他警告其他骑士。这一警告引发了分裂，并促成银色黎明的建立。",al={"法尔班克斯的关系","法尔班克斯与莫格莱尼","法尔班克斯曾效忠谁"}}},fp="25,278,25.381.0,22.551.1,19.526.2,43.243.0,36.317.2,41.222.0,70.264.2,43.163.2,42.213.0"}
P.entries["npc:high-priest-rohan"] = {n="高阶牧师洛汉",s="高阶牧师洛汉是铁炉堡圣光教会的卓越领袖，在Hall of Mysteries内踱步。他监管着全联盟年轻牧师的精神成长，并帮助那些寻求掌控圣光真谛的人。通过他的指引和圣物，他维系着山中王国、暴风城以及遥远盟友之间的精神纽带。",h="高阶牧师洛汉是铁炉堡圣光教会的卓越领袖，在Hall of...",kw={"圣光教会","驱魔香炉","格雷森·沙东布瑞克公爵","hall of mysteries","高阶牧师洛汉","铁炉堡","mystic ward","牧师训练师","洛汉"},ang={["class:Paladin"]="由格雷森·沙东布瑞克公爵派遣的神圣骑士必须拜访洛汉，以换取他著名的驱魔香炉，用以换取对铁炉堡贫困人口的援助。",["class:Priest"]="高阶牧师洛汉提供必要的指导和早期的能力训练，最终会指引你前往暴风城或达纳苏斯的知名导师处，以解锁独特的种族虔诚。",["faction:Alliance"]="通过与Cathedral of Light、Temple of the Moon和塞纳里奥议会的密切合作，洛汉将铁炉堡的教士群体与更广泛的联盟紧密地联系在一起。",["race:Dwarf"]="洛汉体现了矮人对圣光的虔诚，表明了卡兹莫丹的矮人们在秉承泰坦遗产的同时，也拥有深厚的精神信念。"},sec={{t="Hall of Mysteries的牧羊人",b="高阶牧师洛汉在Mystic Ward的Hall of Mysteries里，在安静的石板路上踱步，他是铁炉堡圣光教会最高级别的代表。虽然矮人历来尊崇泰坦，但矮人牧师们已经深深拥抱了圣光的智慧、同情和正义等美德。洛汉是一位对年轻侍僧充满耐心的导师，他教导他们引导圣光魔法所必需的纪律，并磨练他们的意志以对抗绝望。"},{t="联盟之桥",b="洛汉认识到，在联盟各处，精神见解有着多种形式。一旦他指导下的牧师掌握了基础知识，他就会指引他们向外发展——将人类和矮人学生送到暴风城的高阶牧师劳瑞娜那里，或者派遣暗夜精灵弟子前往达纳苏斯的Temple of the Moon，去向女祭司阿兰希雅学习像艾露恩的恩赐这样难以捉摸的奥秘。在首都之外，他还敦促信徒们在任何困难出现的地方提供援助，甚至指引治疗者前往遥远的艾萨拉，去帮助塞纳里奥议会的德鲁伊。"},{t="驱魔香炉",b="除了教学之外，洛汉还保管着对广大联盟牧师和圣骑士兄弟会至关重要的圣物。他拥有的物品中包括一个受过祝福的驱魔香炉，它在多年净化邪恶灵魂的过程中得到了淬炼。当白银之手骑士团和格雷森·沙东布瑞克公爵需要这件器皿来磨练其骑士的圣光召唤时，洛汉会慷慨地交出它——仅要求施舍一点慈善捐款，以补充铁炉堡为城市贫困人口储备的日益减少的食物。"}},faq={{q="我在哪里可以找到高阶牧师洛汉？",a="高阶牧师洛汉位于铁炉堡北侧Mystic Ward内的Hall of Mysteries里。他在圣光图书馆和祭坛之间来回踱步。",al={"洛汉的位置","铁炉堡的牧师训练师在哪里","洛汉地图","hall of mysteries牧师训练师"}},{q="洛汉在铁炉堡担任什么职务？",a="他是铁炉堡的资深牧师训练师，也是卡兹莫丹圣光教会的首席矮人代表。他负责训练新晋牧师，提供精神咨询，并指导修行者前往艾泽拉斯各地进行进一步的深造。",al={"洛汉是谁","洛汉的作用","洛汉背景故事"}},{q="为什么洛汉要派遣牧师前往达纳苏斯或暴风城？",a="洛汉认为精神成长需要从不同的传统中学习。他派遣人类和矮人初学者前往暴风城的Cathedral of Light学习像绝望祷言这样的专业祈祷，并引导暗夜精灵回到达纳苏斯的Temple of the Moon，以便他们能够与艾露恩的恩赐达成共鸣。",al={"洛汉职业任务","绝望祷言洛汉","temple of the moon任务"}},{q="为什么圣骑士会寻找洛汉？",a="由格雷森·沙东布瑞克公爵派遣的圣骑士会拜访洛汉，以获取他那受过祝福的驱魔香炉。洛汉捐赠这件圣物以帮助白银之手骑士团完成他们的仪式，作为回报，他请求他们捐赠少量物资以救济铁炉堡的贫困人口。",al={"圣骑士任务洛汉","驱魔香炉","强调牺牲"}},{q="为什么洛汉要派遣牧师前往艾萨拉？",a="在圣光慈善和服务教义的引导下，洛汉派遣治疗者前往艾萨拉那片荒野崎岖的土地，去帮助那里的塞纳里奥议会的暗夜精灵德鲁伊。",al={"塞纳里奥援助洛汉","洛汉塞纳里奥议会"}},{q="洛汉只训练矮人吗？",a="洛汉指导任何走在牧师道路上的联盟信徒，包括矮人、人类和暗夜精灵。他在将他们送往针对其特定传统的导师处之前，会为他们提供初步的指导。",al={"人类能在洛汉处训练吗","洛汉训练谁"}}},fx={["077c3151"]={q="高阶牧师洛汉是谁？",a="高阶牧师洛汉是常驻铁炉堡的圣光教会最高阶成员。这位德高望重、虔诚的矮人担任山中王国牧师们的主要精神导师，引导新手学习虔诚、治疗与神圣愤怒之道。",al={"洛汉是谁","高阶牧师洛汉","洛汉的背景"}},["940e11c6"]={q="高阶牧师洛汉站在哪一边？",a="洛汉坚定地支持铁炉堡王国、大联盟与圣光教会。他与暴风城的人类教士、达纳苏斯的暗夜精灵密切合作；当有人命危在旦夕时，他甚至会派人援助塞纳里奥议会等中立团体。",al={"洛汉的阵营","洛汉属于联盟吗","洛汉的效忠对象"}},["90c6beb0"]={q="高阶牧师洛汉想做什么？",a="洛汉致力于弘扬圣光美德，并照料有需要的人。他希望培养年轻牧师的智慧与韧性，照顾铁炉堡的贫困居民，并在艾泽拉斯各地无辜者的生命受到苦难威胁时派遣援助。",al={"洛汉想做什么","洛汉的目标","洛汉的动机"}},["88d280c0"]={q="高阶牧师洛汉为何在这里的Hall of Mysteries？",a="Hall of Mysteries是铁炉堡用于神圣研习与奥术沉思的圣所。洛汉在神圣的殿堂中巡视，照看城市的精神福祉，接待前来祈求帮助的人，并亲自教导新晋牧师，再将他们派往更广阔的世界。",al={"洛汉为何在铁炉堡","洛汉为何在这里","洛汉与hall of mysteries"}}},fp="17,395,33.472.0,27.561.0,19.496.0,35.189.0,40.249.0,54.304.0,31.267.0,39.182.0,30.217.0"}
P.entries["npc:high-priestess-laurena"] = {n="高阶牧师劳瑞娜",s="高阶牧师劳瑞娜是一位受人尊敬的人类牧师训练师，驻守在暴风城的Cathedral of Light内的大祭坛后。她教导联盟的新晋牧师关于信仰虔诚和奥术结界的知识。",h="高阶牧师劳瑞娜是一位受人尊敬的人类牧师训练师，驻守在暴风城的Cathedral of Light内的大祭坛后。她教导联盟的新晋牧师关于信仰虔诚和奥术结界的知识。",kw={"奥术反馈","本尼迪塔斯","cathedral of light","绝望祷言","高阶牧师","圣光","劳瑞娜","牧师训练师","暴风城"},ang={["class:Priest"]="高阶牧师劳瑞娜是暴风城主要的牧师导师之一，她引导人类侍僧通过神圣试炼，赐予他们绝望祷言的祝福，并教授打断敌对施法者的方法。",["faction:Alliance"]="她在Cathedral of Light内帮助加强联盟的精神支柱，确保其勇士能够抵御黑暗魔法和亡灵恐怖。",["race:Human"]="对于暴风城的人类来说，劳瑞娜是Cathedral of Light的精神支柱，指引信徒度过动荡时期。"},sec={{t="圣殿的高阶牧师",b="作为圣光教会的一名高阶牧师，劳瑞娜在暴风城信仰的核心——Cathedral of Light那高耸的大厅内担任要职之一，大主教本尼迪塔斯正是教会的领袖。"},{t="照料信徒",b="高阶牧师劳瑞娜驻守在圣殿内部中央祭坛的后方，致力于指导有志成为牧师的人。当有前途的侍僧展现出足够的奉献精神和虔诚时，他们会被引荐给她以深造。劳瑞娜指导他们祈求神圣恩赐（如绝望祷言），并教导他们防御艺术，包括那些旨在将敌人的奥术魔法反弹给施法者的法术。一旦学徒学会了她所能教授的一切，她就会指引他们前往联盟各地的其他牧师大师那里继续深造。"}},faq={{q="我可以在哪里找到高阶牧师劳瑞娜？",a="她站在暴风城Cathedral Square内Cathedral of Light的主祭坛后面。",al={"劳瑞娜的位置","牧师劳瑞娜在哪里","寻找劳瑞娜"}},{q="高阶牧师劳瑞娜教授什么？",a="劳瑞娜是一位牧师训练师。她为人类牧师提供基础指导，并教授诸如绝望祷言之类的特殊种族祈祷，以及奥术反馈之类的防御法术，以抵御敌对施法者。",al={"劳瑞娜的法术","牧师训练师劳瑞娜","劳瑞娜教什么"}},{q="劳瑞娜在来到暴风城之前来自哪里？",a="关于她在暴风城Cathedral of Light任职之前的生活，没有任何记录。",al={"劳瑞娜的背景故事","劳瑞娜来自暴风城吗","劳瑞娜与洛丹伦"}},{q="她是在大主教本尼迪塔斯手下效力吗？",a="是的。大主教本尼迪塔斯是圣光教会的精神领袖，并主持Cathedral of Light，劳瑞娜就在那里担任高阶牧师。",al={"劳瑞娜与本尼迪塔斯","劳瑞娜的上司是谁","本尼迪塔斯劳瑞娜"}},{q="她为什么要把我引荐给其他的牧师训练师？",a="联盟内部不同的文化和种族以独特的方式与神灵沟通。当劳瑞娜教会了学生圣光的基础祈祷后，她会将他们送往其他教派的牧师大师那里——例如铁炉堡的矮人大师或达纳苏斯的暗夜精灵牧师——以拓宽他们的精神视野。",al={"劳瑞娜让我离开","绝望祷言任务","艾露恩的赐福任务"}},{q="劳瑞娜的家人是因为亡灵而丧生的吗？",a="关于她的家人没有任何记录。",al={"劳瑞娜的家人是否过世","劳瑞娜家人遭遇了什么"}}},fp="22,108,33.196.0,20.406.0,40.118.0,39.160.0,45.120.0,43.153.0,48.254.0,42.55.0"}
P.entries["npc:highlord-demitrian"] = {n="德米提恩",s="德米提恩是一位隐居在希利苏斯西北部奇异水晶中的人类隐士。他自称是逐风者桑德兰王子的忠诚仆从，并掌握着唤醒这位沉睡的元素领主所需的深奥知识。持有古老元素束缚的冒险者会来寻找他，以解锁逐风者的力量。",h="德米提恩是一位隐居在希利苏斯西北部奇异水晶中的人类隐士。他自称是逐风者桑德兰王子的忠诚仆从，并掌握着唤醒这位沉睡的元素领主所需的深奥知识。持有古老元素束缚的冒险者会来寻找他，以解锁逐风者的力量。",kw={"水晶谷","德米提恩","希利苏斯","thunderaan","雷霆之怒","复生之瓶","逐风者"},ang={["class:Rogue"]="猎取逐风者传说之刃的潜行者必须在希利苏斯与德米提恩进行交易，以复活这位破碎的王子。",["class:Warrior"]="寻求传说之刃雷霆之怒的战士必须寻找德米提恩，以开启解除束缚并唤醒逐风者的试炼。",["profession:Blacksmithing"]="德米提恩对桑德兰重生提出的要求，需要高超的锻造大师技能，将原始矿石和火焰精华锻造成源质锭。"},sec={{t="水晶谷的隐士",b="德米提恩徘徊在水晶谷的一处废弃营地，与希利苏斯荒凉的废土显得格格不入。虽然他与暮光之锤有着千丝万缕的联系——他正是潜伏在暮光营地废墟中——但德米提恩的首要身份是逐风者桑德兰王子的先驱。除非来访者带着证明逐风者破碎精华的凭证，否则他会对他们表现得冷漠疏离。"},{t="复生之瓶",b="德米提恩的目标完全与桑德兰的复活有关。如果冒险者向他展示了逐风者的桎梏（即从熔火之心的火元素身上夺取的遗物），德米提恩就会提供复生之瓶。他要求获得稀有的元素试剂，包括大量的源质锭和炎魔的精华，以重塑他王子的肉身。"},{t="逐风者的背叛",b="德米提恩的仪式将桑德兰王子召唤到了水晶谷，冒险者必须在那里与重生的逐风者交战。一旦击败了这位元素领主，他们就能回收风吻之刃，并将其交给惊恐的德米提恩，而他会以此为代价唤醒雷霆之怒。"}},faq={{q="我可以在哪里找到德米提恩？",a="他位于希利苏斯的最西北角，站在水晶谷内的暮光营地废墟附近。",al={"德米提恩位置","德米提恩在哪里","德米提恩在希利苏斯的地点"}},{q="为什么德米提恩只给出通用的回复？",a="除非你身上携带至少一半的逐风者的桎梏（这是熔火之心的迦顿男爵和加尔持有的稀有宝藏），否则德米提恩不会提供他的传说任务线。",al={"德米提恩不跟我说话","如何获得德米提恩的任务","德米提恩对话"}},{q="德米提恩与桑德兰王子的关系是什么？",a="德米提恩是桑德兰王子誓死效忠的凡人仆从。他致力于寻找王子被切断的束缚，并让这位元素领主重返物质位面。",al={"德米提恩侍奉谁","德米提恩与桑德兰的联系","德米提恩是暮光之锤成员吗"}},{q="当你把制作复生之瓶的所有材料带给他时会发生什么？",a="德米提恩会进行一场仪式，将桑德兰王子召唤到水晶谷，使逐风者重返物质位面。",al={"召唤桑德兰","德米提恩用复生之瓶做什么","水晶谷召唤"}},{q="德米提恩隶属于暮光之锤教派吗？",a="他与暮光之锤有瓜葛，并居住在他们的营地废墟中，还会怀着敬畏之心谈论古神。不过，他依然宣誓效忠于他的主人——桑德兰王子。",al={"德米提恩是邪教徒吗","德米提恩暮光营地","德米提恩阵营"}},{q="如何从他那里获得雷霆之怒？",a="带给他从熔火之心的迦顿男爵和加尔身上获得的逐风者的桎梏（两半），然后收集他为复生之瓶要求的稀有材料。关于他的仪式会引发什么后果，以及这把武器最终是如何被唤醒的，将在剧透章节中详述。",al={"如何获得雷霆之怒","雷霆之怒任务完成","德米提恩之刃"}}},fp="18,351,26.385.0,21.400.1,26.289.1,36.122.0,48.202.0,54.181.0,65.133.1,56.178.0,36.277.1"}
P.entries["npc:hogger"] = {n="霍格",s="霍格是盘踞在艾尔文森林西南部河爪豺狼人的凶残首领。他比同族更加高大，且异常狂暴，因袭击当地农场和屠杀毫无防备的旅人而臭名昭著。他那暴力的横行霸道使他受到了暴风城治安官的官方悬赏。",h="霍格是盘踞在艾尔文森林西南部河爪豺狼人的凶残首领。他比同族更加高大，且异常狂暴，因袭击当地农场和屠杀毫无防备的旅人而臭名昭著。他那暴力的横行霸道使他受到了暴风城治安官的官方悬赏。",kw={"悬赏","迪菲亚","杜汉","艾尔文","豺狼人","闪金镇","霍格","河爪"},ang={["faction:Alliance"]="霍格的袭击表明暴风城军队的力量捉襟见肘，迫使治安官不得不依赖游荡的冒险者来维持首都附近的秩序。",["race:Human"]="对于暴风城的年轻保卫者来说，对抗霍格是一场早期的烈火试炼，也是对破坏艾尔文森林腹地安宁的威胁的直接回应。"},sec={{t="河爪之灾",b="霍格盘踞在艾尔文森林西南部的霍格山顶，以无与伦比的野蛮统治着当地的河爪豺狼人部族。在第三次战争后的几年里，豺狼人对当地农庄的袭击变得愈发大胆且有组织。在暴力升级的背后隐藏着一个令人不安的联盟：河爪豺狼人开始与迪菲亚潜行者勾结，用纯粹的凶残换取武器、战术指导和魔法支持。为了保卫艾尔文森林的边界并保护贸易路线免受进一步的流血事件，治安官杜汉对霍格的人头悬赏了重金。"}},faq={{q="霍格是谁？",a="霍格是一个体型庞大、极其危险的豺狼人，领导着艾尔文森林西南部的河爪部族。他因袭击附近的农庄而闻名，由于对人类定居点发动了残酷的攻击，暴风城当局已将其列为通缉犯。",al={"霍格背景故事","谁是霍格","河爪领袖"}},{q="为什么霍格会被悬赏？",a="治安官杜汉和暴风城卫兵对霍格发布了正式悬赏，因为他不断升级对乡村农场和旅人的袭击。任何敢于终结他暴行的人，必须将他巨大的爪子带回闪金镇作为证明。",al={"通缉霍格","为什么要杀霍格","霍格悬赏"}},{q="河爪豺狼人是否与迪菲亚潜行者有合作？",a="是的。迪菲亚潜行者一直在与河爪部族勾结，为这些野蛮的豺狼人提供精良的武器、战术指导和神秘力量的支持，以进一步破坏暴风城对该地区的控制。",al={"霍格与迪菲亚","豺狼人与迪菲亚的联系","河爪与迪菲亚"}},{q="霍格在哪里安营扎寨？",a="霍格居住在艾尔文森林西南部的霍格山顶，身边簇拥着忠诚的河爪部族成员，靠近西部荒野的边界。",al={"霍格的位置","霍格在哪里","霍格山"}}},fp="6,170,22.453.0,14.207.0,32.166.0,60.198.0,32.123.0"}
P.entries["npc:holt-thunderhorn"] = {n="浩特·雷角",s="浩特·雷角是一位牛头人猎人训练师，驻扎在雷霆崖这座高耸城市中的猎人高地。他教导新手和老练的追踪大师，提供基本的武技指导，并为日渐成熟的神射手们指引前往莫高雷及更远地区的专业试炼之路。",h="浩特·雷角是一位牛头人猎人训练师，驻扎在雷霆崖这座高耸城市中的猎人高地。他教导新手和老练的追踪大师，提供基本的武技指导，并为日渐成熟的神射手们指引前往莫高雷及更远地区的专业试炼之路。",kw={"浩特·雷角","猎人高地","猎人训练师","莫高雷","雷霆崖"},ang={["class:Hunter"]="浩特·雷角在雷霆崖担任核心导师，提供武器技巧、追踪训练，以及驯服野兽的指引。",["race:Tauren"]="浩特驻扎在猎人高地，体现了牛头人传统的狩猎文化，这种文化在他们于峭壁之上建立永久家园很久以前，就一直养育并保护着游牧部落。"},sec={{t="高地大师",b="浩特·雷角栖身于莫高雷广袤平原上方的猎人高地，作为一名远程战斗、追踪和生存方面经验丰富的导师，为部落效力。正如许多该领域的长者一样，他指引着年轻的牛头人，帮助他们完成从游猎者到新首都纪律严明的守卫者的转变。"}},faq={{q="浩特·雷角在哪里可以找到？",a="浩特·雷角位于雷霆崖——这座位于莫高雷的牛头人首都中，东南方的高地平台——猎人高地上。",al={"浩特·雷角位置","浩特在哪里","雷霆崖猎人训练师"}},{q="浩特·雷角教授什么？",a="他是一位猎人训练师，指导玩家学习基本的射击、荒野生存和野兽驯服技巧，并指引新手进行专业的兽王试炼。",al={"浩特教授什么","浩特·雷角训练师","浩特的能力"}},{q="猎人在雷霆崖扮演什么角色？",a="猎人构成了牛头人社会的传统中坚力量，他们提供食物来源，巡逻领土边界以抵御半人马突袭部队，并通过平衡而虔诚的追踪方式来尊崇大地母亲。",al={"猎人高地用途","牛头人猎人背景"}}},fx={c3f17fe5={q="浩特·雷角是谁？",a="浩特·雷角是一位备受尊敬的牛头人猎人训练师，驻守在雷霆崖的猎人高地。他致力于传授舒哈鲁的荒野技艺，教导年轻猎人射击、生存之道，以及猎人与野兽之间古老的羁绊。",al={"浩特是谁","浩特·雷角的背景","浩特·雷角是谁"}},d59405da={q="浩特·雷角站在哪一边？",a="浩特效力于雷霆崖的牛头人部族，以及由凯恩·血蹄领导的更广大的部落。他会帮助任何忠于部落、希望磨砺本能并尊重草原的猎人。",al={"浩特·雷角的阵营","浩特效忠谁","浩特属于部落吗"}},["03eb281d"]={q="浩特·雷角为何在这里？",a="浩特留在猎人高地，指导新一代的追踪者、神射手和驯兽师。如今牛头人已在莫高雷定居，技艺娴熟的猎人对于维持城市运转、保护台地免受敌对野兽与入侵者侵扰至关重要。",al={"浩特为何在雷霆崖","浩特在这里做什么","浩特·雷角的职责"}}},fp="16,288,18.313.0,36.128.0,33.187.0,43.209.0"}
P.entries["npc:houndmaster-loksey"] = {n="驯犬者洛克希",s="驯犬者洛克希是负责为血色十字军繁育并训练恐怖战犬的军官。他驻扎在血色修道院的图书馆区域，指挥着猎犬群去猎杀亡灵、入侵者和被视为异端的人。他冷酷无情的训练方式让修道院的野兽在整个提瑞斯法林地都臭名昭著。",h="驯犬者洛克希是负责为血色十字军繁育并训练恐怖战犬的军官。他驻扎在血色修道院的图书馆区域，指挥着猎犬群去猎杀亡灵、入侵者和被视为异端的人。他冷酷无情的训练方式让修道院的野兽在整个提瑞斯法林地都臭名昭著。",kw={"图书馆","驯犬者洛克希","猎犬","猎人利奥波德","犬舍","洛克希","血色十字军","血色修道院"},ang={["class:Hunter"]="洛克希代表了一种残酷、激进的野兽训练方法，他迫使凶猛的猎犬服从狂热的意志，而非建立一种相互尊重的纽带。",["race:Undead"]="被遗忘者入侵者必须小心洛克希的猎犬，因为它们经过专门训练，能嗅出腐肉的气味并向十字军的驻军发出警报。"},sec={{t="犬舍主管",b="在血色修道院戒备森严的围墙内，驯犬者洛克希指挥着凶猛的追踪犬和攻击犬的训练。血色十字军依靠这些训练有素的猎犬来嗅出带有瘟疫气息的尸体，发现潜入者，并追击任何从狂热者愤怒下逃离的幸存者。洛克希对守卫图书馆区域的猎犬拥有绝对的控制权，确保他的犬群随时准备将入侵者撕成碎片。"},{t="家族竞争",b="洛克希并不是他家族中唯一为这一事业服务的驯兽师。他的兄弟，猎人利奥波德，担任血色十字军驻圣光之愿礼拜堂的银色黎明使节。利奥波德对他兄弟的评价很低，私下里断言洛克希连自己的猎犬都管不好，更别提代表组织进行高风险的外交活动了。尽管利奥波德对此不屑一顾，但洛克希仍然是修道院内部等级制度中的关键军官。"}},faq={{q="在哪里可以找到驯犬者洛克希？",a="驯犬者洛克希位于提瑞斯法林地东北部的血色修道院图书馆区域内，被他的攻击犬环绕。",al={"洛克希位置","洛克希在哪里","驯犬者洛克希位置"}},{q="洛克希在血色十字军中担任什么角色？",a="他是血色十字军在修道院的首席动物训练师和驯犬者，负责繁育、调教和指挥用于嗅探亡灵并猎杀入侵者的战犬。",al={"洛克希做什么","洛克希工作","驯犬者职责"}},{q="猎人利奥波德和洛克希是什么关系？",a="猎人利奥波德是洛克希的兄弟。利奥波德代表血色十字军驻扎在圣光之愿礼拜堂，并看不起洛克希，声称洛克希无法妥善管理他的猎犬，也无法胜任外交职责。",al={"利奥波德洛克希兄弟","利奥波德是谁","洛克希兄弟"}},{q="为什么血色十字军要使用猎犬？",a="十字军训练凶猛的猎犬通过气味追踪天灾军团和被遗忘者，同时也用于守卫修道院的领地，并将逃跑的敌人撕成碎片。",al={"为什么用狗","血色猎犬用途","十字军军犬"}},{q="洛克希被视为血色修道院的领导者吗？",a="是的，洛克希被公认为是血色修道院军事结构中的关键指挥人物之一，负责管理十字军在图书馆区域内的战犬。",al={"洛克希是首领吗","洛克希军衔","洛克希重要性"}},{q="这些猎犬本身危险吗？",a="是的。经过洛克希的挑选和攻击性训练，修道院的战犬是凶猛的捕食者，能在瞬间将身穿盔甲的入侵者撕碎。",al={"狗强吗","血色猎犬危险","洛克希宠物"}}},fx={["92e01b8b"]={q="驯犬者洛克希是谁？",a="驯犬者洛克希是一名人类队长，也是驻守在血色修道院的四位指挥官之一。他以严酷的纪律闻名，担任犬舍主管，负责繁育、训练并放出十字军凶猛的猎犬，袭击入侵者和疑似感染亡灵污秽之人。",al={"洛克希是谁","驯犬者洛克希的身份","驯犬者洛克希是谁"}},["6cbd929d"]={q="驯犬者洛克希站在哪一边？",a="洛克希坚定效忠血色十字军，是其修道院据点中的一线指挥官。他怀有与十字军相同的狂热，对亡灵以及其狂热教团之外的所有人都充满仇恨；在他看来，任何擅闯他们殿堂的人都只是喂给犬舍的猎物。",al={"洛克希的阵营","驯犬者洛克希与联盟","洛克希效忠谁"}},["1361b0af"]={q="驯犬者洛克希想做什么？",a="洛克希致力于守卫血色修道院，他训练凶残的猎犬群，令它们能够将敌人撕成碎片。他想彻底清除亡灵的踪迹，保护十字军领地免受外人侵扰，并让他的野兽毫不犹豫、毫无怜悯地追捕入侵者。",al={"洛克希的目标","洛克希想做什么","驯犬者洛克希的动机"}},["58572016"]={q="驯犬者洛克希为何在此？",a="洛克希驻扎在修道院的图书馆区，负责看管十字军的犬舍。作为驯犬者，他必须确保猎犬保持警觉、训练有素且凶猛，随时可以放出去巡逻并屠杀入侵者。",al={"洛克希为何在修道院","驯犬者洛克希为何在此","洛克希的目的"}},["264719ea"]={q="驯犬者洛克希为何声名远扬，或令人畏惧？",a="洛克希因他训练有素的猎犬群而令人畏惧。这些野兽能在几分钟内制服受害者，并将其撕成碎片。任何踏入修道院的人都害怕遇上他的犬舍，因为他们知道，在洛克希凶狠的指挥下，这些动物会变成无情的杀戮机器。",al={"洛克希为何令人畏惧","洛克希的声望","驯犬者洛克希为何危险"}}},fp="18,342,21.455.0,14.441.0,38.142.0,51.205.0,34.214.0,40.167.0,55.170.0,38.165.0"}
P.entries["npc:huldar"] = {n="胡达尔",s="胡达尔是一名驻扎在洛克莫丹南部道路旁、靠近湖岸的矮人车夫。他负责将至关重要的爆破火药运往南部的发掘场，但他的运输车队却不断受到当地威胁和黑铁破坏者的骚扰。",h="胡达尔是一名驻扎在洛克莫丹南部道路旁、靠近湖岸的矮人车夫。他负责将至关重要的爆破火药运往南部的发掘场，但他的运输车队却不断受到当地威胁和黑铁破坏者的骚扰。",kw={"爆破火药","车队","黑铁","发掘","胡达尔","洛克莫丹","马车"},ang={["profession:Engineering"]="任何工程师都知道，存放在搁浅的木桶中、暴露在外的粗制爆破火药既珍贵又危险。",["race:Dwarf"]="帮助胡达尔就是直接支持探险者协会的发掘场，确保你的族人拥有挖掘上古泰坦秘密所需的火药。"},sec={{t="危险的火药运输",b="在洛克莫丹运输炸药可不是什么简单的贸易路线。胡达尔受命驾驶装满采矿爆破火药的马车前往南部的发掘场，那里的矮人考古学家和勘探员正急需补给。然而，荒野道路变得越来越危险。随着当地野生生物、穴居人以及潜伏在湖泊南湾附近的黑铁渗透者出没，胡达尔因马车受损而被困，不得不依靠过往的旅行者来保卫剩余的火药桶，并确保这批货物能送达发掘场。"}},faq={{q="胡达尔是谁？",a="胡达尔是一名在洛克莫丹湖的南岸因马车受损而被困的矮人车夫。在补给任务遇到麻烦之前，他负责将爆破火药运往附近的发掘场。",al={"胡达尔是谁","胡达尔 洛克莫丹","马车 矮人"}},{q="胡达尔的马车里装的是什么？",a="他的马车上装载着一桶桶爆破火药。这些炸药是南部发掘场工作的矮人勘探员和考古学家急需的物资。",al={"胡达尔运输什么","胡达尔 马车货物","木桶里是什么"}},{q="为什么胡达尔被困在路上？",a="穿过洛克莫丹南部的道路因敌对野兽、穴居人和黑铁矮人破坏者的存在而变得危险。胡达尔的运输队遭到了伏击，被迫停下来寻求帮助，以确保剩余物资的安全并完成运送。",al={"胡达尔为什么被困","胡达尔 伏击"}},{q="为什么黑铁矮人会盯上他的货物？",a="黑铁氏族积极寻求破坏铁炉堡在洛克莫丹的影响力和历史研究。切断爆破火药的供应不仅会阻碍发掘工作，还会使矮人的行动缺乏防御和工业物资。",al={"黑铁 爆破火药","为什么黑铁攻击胡达尔"}}},fx={ff7033f4={q="胡达尔效忠于哪一方？",a="胡达尔忠于铁炉堡和联盟。他直接为在洛克莫丹活动的矮人勘探者和矿工效力，在领地内运送重要弹药，同时坚定抵御渗透该地区的敌对黑铁氏族。",al={"胡达尔是联盟的吗","胡达尔为谁效力","胡达尔的阵营"}},["9f03f8e3"]={q="胡达尔想做什么？",a="胡达尔想把他的火药货物安全送到矮人挖掘场。黑铁矮人在洛克湖南面的道路上伏击了他的车队，使他需要坚毅的旅行者保护货物并击退破坏者。",al={"胡达尔想做什么","胡达尔的目标","胡达尔需要什么"}},["577cb64e"]={q="胡达尔与谁有关联？",a="胡达尔与驻扎在洛克莫丹的矮人挖掘者有关联。他的队伍负责将重要补给和火药直接运到他们的挖掘场，确保即使黑铁势力的侵袭威胁日益加剧，他们的行动也能继续。",al={"胡达尔为谁工作","胡达尔的人脉","胡达尔为谁运送补给"}}},fp="6,268,21.566.0,14.208.0,26.167.0,32.232.0,50.234.0"}
P.entries["npc:illiyana"] = {n="伊莉亚娜",s="伊莉亚娜是一位驻守在灰谷西南部的古老树妖，致力于保护林地免受古老腐蚀的侵扰。她在艾森娜神殿附近徘徊，号召联盟的勇士们挺身而出，击退那些祸害古老树林的邪恶萨特。她的警惕象征着塞纳留斯的女儿们与暗夜精灵荒野之间持久的羁绊。",h="伊莉亚娜是一位驻守在灰谷西南部的古老树妖，致力于保护林地免受古老腐蚀的侵扰。她在艾森娜神殿附近徘徊，号召联盟的勇士们挺身而出，击退那些祸害古老树林的邪恶萨特。她的警惕象征着塞纳留斯的女儿们与暗夜精灵荒野之间持久的羁绊。",kw={"灰谷","塞纳留斯的树枝","塞纳留斯","树妖","伊莉亚娜","萨特","艾森娜神殿"},ang={["class:Druid"]="德鲁伊们将树妖视为荒野的化身而予以高度尊重，帮助伊莉亚娜维护神圣的林地，直接符合塞纳里奥议会治愈大地的职责。",["faction:Alliance"]="伊莉亚娜是灰谷西南部至关重要的林地盟友，为保障荒野免受入侵邪恶侵害的联盟部队提供庇护和指引。",["race:NightElf"]="对于卡多雷来说，像伊莉亚娜这样的树妖是塞纳留斯的神圣亲眷，是受人尊敬的保护者，她们发出的对抗恶魔萨特的战争号召会得到毫无迟疑的响应。"},sec={{t="森林之女",b="像所有的树妖一样，伊莉亚娜是半神塞纳留斯的女儿之一。她性情平和，却极其保护荒野之地，终日巡逻在灰谷西南部的森林中。随着黑暗力量的蠢蠢欲动和林地在蔓延的腐蚀下饱受摧残，伊莉亚娜守护着神圣的遗物和林地，履行着自然原始神圣之地的监管者职责。"},{t="萨特的威胁",b="伊莉亚娜在该地区最主要的忧虑是萨特那挥之不去的枯萎病。这些扭曲的恶魔生物不断地试图腐蚀林地，威胁着她的树妖姐妹。伊莉亚娜经常征召路过的旅人去击杀这些邪恶的孽物，并取回遗失的神器，包括塞纳留斯的树枝，以确保森林免受恶魔的玷污。"}},faq={{q="伊莉亚娜是谁？",a="伊莉亚娜是一位在灰谷西南部艾森娜神殿附近徘徊的树妖。作为塞纳留斯的女儿，她将自己的一生奉献给了守护荒野和保护她的姐妹免受恶魔力量的侵害。",al={"这个树妖是谁","伊莉亚娜灰谷","伊莉亚娜是什么"}},{q="为什么我与伊莉亚娜交谈时她一直在走动？",a="伊莉亚娜在林地中维持着一条活跃的巡逻路线。与那些原地不动的任务发布者不同，即使在与旅行者交谈时，她也会继续在树林中保持警惕地踱步。",al={"伊莉亚娜走动","为什么她走开了","伊莉亚娜任务走动"}},{q="伊莉亚娜提供什么任务？",a="她号召冒险者猎杀那些威胁该地区的邪恶萨特，并取回像塞纳留斯的树枝这样神圣的遗物，以保护她的树妖同伴。",al={"伊莉亚娜任务","林歌神殿任务"}},{q="伊莉亚娜在哪里？",a="她在灰谷西南部的艾森娜神殿附近巡逻，沿着小路和附近的树林保持监视。",al={"伊莉亚娜位置","哪里找到伊莉亚娜","林歌神殿树妖位置"}},{q="为什么树妖会受到萨特的威胁？",a="萨特是受到恶魔腐蚀而扭曲的古代暗夜精灵，他们以亵渎自然和奴役塞纳留斯的子嗣为乐。树妖代表着森林纯净、未受玷污的美丽，这使她们成为萨特恶意攻击的主要目标。",al={"为什么萨特讨厌树妖","树妖与萨特背景故事"}},{q="伊莉亚娜会帮助部落吗？",a="不会。伊莉亚娜与暗夜精灵及广大的联盟结盟。冒险进入她林地的部落成员会发现她和她的盟友是敌对的。",al={"伊莉亚娜对部落敌对吗","部落可以和伊莉亚娜交谈吗"}}},fx={f493742a={q="伊莉亚娜想做什么？",a="伊莉亚娜致力于保护灰谷以及她的树妖姐妹，使她们免受萨特的腐化影响。她寻求联盟勇士的帮助，猎杀潜伏在附近的邪恶萨特，守卫神圣林地，并协助寻回塞纳留斯的树枝，以净化这片森林。",al={"伊莉亚娜的目标","伊莉亚娜想要什么","伊莉亚娜的目的"}},["925d87c3"]={q="伊莉亚娜为何在艾森娜神殿？",a="伊莉亚娜看守着灰谷西南部的艾森娜神殿。林地之灵和塞纳留斯的女儿们都十分珍视这处圣所。她在这片圣地监视萨特日益蔓延的腐化，并与暗夜精灵和联盟盟友协调防御事宜。",al={"伊莉亚娜为何在此","伊莉亚娜与艾森娜神殿","伊莉亚娜为何在灰谷"}},abbc4abe={q="伊莉亚娜与谁有关联？",a="作为一名树妖，伊莉亚娜是半神塞纳留斯的女儿之一，与她的树妖姐妹（例如莎尔蒂恩）以及林地守护者有着深厚的精神和血脉联系。她也与敬仰艾森娜和塞纳留斯的暗夜精灵关系密切。",al={"伊莉亚娜的关系","伊莉亚娜与塞纳留斯","伊莉亚娜与谁有亲缘关系"}}},fp="8,384,22.345.0,23.388.0,16.218.0,51.198.0,31.163.0,26.114.0,41.230.0,29.146.0"}
P.entries["npc:illiyana-moonblaze"] = {n="艾蒂尔·月火",s="艾蒂尔·月火是一位驻扎在灰谷银翼树林的暗夜精灵补给官。她与银翼要塞并肩作战，为向战歌氏族发起战争的联盟勇士提供补给。",h="艾蒂尔·月火是一位驻扎在灰谷银翼树林的暗夜精灵补给官。她与银翼要塞并肩作战，为向战歌氏族发起战争的联盟勇士提供补给。",kw={"灰谷","补给包","艾蒂尔·月火","银翼要塞","银翼树林","战歌峡谷"},ang={["faction:Alliance"]="对于向南进军战歌峡谷交战边境的联盟战士来说，伊莉亚娜是负责提供武器、护甲和口粮的主要军需官。",["race:NightElf"]="伊莉亚娜保障了银翼要塞的补给，展现了卡多雷如何集结一切力量来保卫灰谷。"},sec={{t="银翼补给官",b="艾蒂尔·月火担任银翼要塞的补给官，驻扎在银翼树林中。她在通往战歌峡谷的小径附近的岗位上，为守卫灰谷南部森林以抵御战歌氏族的守军配备装备。"},{t="前线补给",b="除了管理树林的仓库外，伊莉亚娜还为准备在战歌峡谷与战歌氏族交战的联盟志愿者提供装备。当勇士们在银翼要塞获得声望时，她会以特制口粮、专用药剂和专为林地遭遇战设计的精良武器作为对他们服务的奖励。她还为从前线归来的疲惫战士维护武器和护甲，确保银翼要塞的战争工作物资充足且运转正常。"}},faq={{q="我在哪里可以找到艾蒂尔·月火？",a="她位于灰谷东南部的银翼树林，靠近前往战歌峡谷的集结地和传送门。",al={"艾蒂尔·月火位置","伊莉亚娜在哪里","银翼军需官位置"}},{q="艾蒂尔·月火是银翼要塞的成员吗？",a="她担任银翼补给官，与银翼要塞并肩工作，为与他们并肩作战的联盟勇士提供装备和补给。",al={"艾蒂尔·月火是银翼要塞成员吗","伊莉亚娜职位","伊莉亚娜阵营"}},{q="伊莉亚娜为联盟勇士提供什么？",a="她担任银翼要塞的军需官，为那些在该阵营获得声望的人提供补给包、战场装备、戒指、战袍以及专为战歌峡谷战斗而设计的消耗品。",al={"伊莉亚娜出售什么","战歌峡谷奖励","伊莉亚娜商人"}},{q="她提供装备修理服务吗？",a="是的，除了提供专业的军事装备外，她还为在树林中休息的联盟守卫提供标准的武器和护甲修理服务。",al={"伊莉亚娜修理","银翼修理商人","银翼树林修理"}},{q="她分发什么样的补给包？",a="她通过涉及银翼要塞初级、标准和高级补给包的后勤任务来协助联盟战士，为前线守卫提供必要的战场物资。",al={"银翼要塞补给包","伊莉亚娜任务","战歌峡谷补给包"}}},fx={["4fdd1f70"]={q="艾蒂尔·月火是谁？",a="艾蒂尔·月火是一名驻扎在灰谷银翼树林的暗夜精灵补给官。她与银翼要塞并肩行动，负责为其提供补给，并为在战歌峡谷作战的联盟勇士配备装备和物资。",al={"伊莉亚娜是谁","艾蒂尔·月火的背景","艾蒂尔·月火是谁"}},ebeca23e={q="艾蒂尔·月火效忠于哪一方？",a="艾蒂尔坚定地站在联盟和银翼要塞一方。她全心致力于为灰谷的守卫提供补给，抵御部落在战歌峡谷的入侵。",al={"艾蒂尔·月火的阵营","艾蒂尔·月火是联盟的吗","伊莉亚娜属于什么阵营"}},["4e149737"]={q="艾蒂尔·月火为何身在灰谷？",a="艾蒂尔驻扎在银翼树林，支援与战歌氏族持续进行的战争。她是银翼要塞的主要补给官，为投身战歌峡谷战斗的联盟勇士配备装备和物资。",al={"艾蒂尔·月火为何在此","艾蒂尔·月火与银翼树林","伊莉亚娜为何在灰谷"}},e94ef362={q="艾蒂尔·月火想做什么？",a="艾蒂尔希望增强银翼要塞的实力，以抵御部落。她希望联盟战士坚定作战，将战歌氏族赶出灰谷的古老森林；她还会用自己储备的特制武器、口粮和装备奖励那些在战歌峡谷证明了英勇的人。",al={"伊莉亚娜想要什么","艾蒂尔·月火的目标","伊莉亚娜的目的"}},["0bec8647"]={q="艾蒂尔·月火与谁有关联？",a="艾蒂尔在银翼树林驻守，与保卫灰谷的银翼要塞密切合作，为在战歌峡谷为他们而战的勇士配备装备。",al={"艾蒂尔·月火的关系","伊莉亚娜与谁有关联","伊莉亚娜与银翼要塞"}}},fp="18,212,25.246.0,28.470.0,36.125.0,48.154.0,47.221.0,35.148.0,37.188.0"}
P.entries["npc:ilthalaine"] = {n="Ilthalaine",s="Ilthalaine是一位暗夜精灵卫兵，守卫着泰达希尔神圣的幽影谷林地。他是年轻暗夜精灵踏入世界的第一步时的主要引导者和导师。他警觉且敏锐地感知着荒野，指引新手冒险者在世界之树的枝干间维持大自然的微妙平衡。",h="Ilthalaine是一位暗夜精灵卫兵，守卫着泰达希尔神圣的幽影谷林地。他是年轻暗夜精灵踏入世界的第一步时的主要引导者和导师。他警觉且敏锐地感知着荒野，指引新手冒险者在世界之树的枝干间维持大自然的微妙平衡。",kw={"奥达希尔","大自然的平衡","ilthalaine","卡多雷","任务发布者","幽影谷","徽记","泰达希尔"},ang={["class:Druid"]="对于初出茅庐的德鲁伊来说，Ilthalaine关于猎杀和自然平衡的教导是他们学习塞纳里奥教义的第一堂实践课。",["faction:Alliance"]="他代表了卡多雷沉静而持久的警惕，欢迎新的勇士投身于达纳苏斯乃至整个联盟的麾下。",["race:NightElf"]="Ilthalaine是每位年轻暗夜精灵遇到的第一位导师，他提供了关于守护职责以及他们泰达希尔新家园神圣平衡的基础智慧。"},sec={{t="林地卫士",b="Ilthalaine驻守在幽影谷中心之外，常常是初出茅庐的暗夜精灵踏上旅程时见到的第一张面孔。他观察着林间小径，留意着森林中常人难以察觉的细微变化。他的职责是欢迎归来的族人，并确保所有初醒的保卫者都根植于族人的传统之中，做好准备面对守护泰达希尔所带来的责任。"},{t="大自然的平衡",b="沉重的春雨导致幽影谷内的霜刃豹和蓟野猪数量超出了林地的承载能力。Ilthalaine请求年轻的保卫者们减少它们的数量，以便让林地中的其他生物繁衍生息，维持大自然的平衡。"},{t="职业指引",b="除了在当地野生动物身上考验冒险者的武艺外，Ilthalaine还会引导年轻的精灵选择他们心仪的职业。他会交给每位旅行者一枚职业徽记，并指引他们前往奥达希尔庇护所中的导师处——无论他们选择战士、德鲁伊、潜行者、牧师还是猎人的道路。通过他，每位新手都能了解到他们为卡多雷效力的起点在哪里。"}},faq={{q="Ilthalaine是谁？",a="Ilthalaine是一位位于泰达希尔庇护之所——幽影谷的卡多雷监督者。他是暗夜精灵冒险者接触到的第一位任务发布者，负责向他们介绍各自的职责以及森林的现状。",al={"ilthalaine背景故事","这位暗夜精灵是谁","幽影谷任务发布者"}},{q="Ilthalaine在幽影谷中扮演什么角色？",a="他看守着幽影谷的野生动物，并确保新加入的暗夜精灵理解自然平衡的重要性。他派遣年轻的新兵去进行基础狩猎，并引导他们前往奥达希尔巨树内的各自职业训练师处。",al={"ilthalaine做什么","他为什么在这里","ilthalaine的目标"}},{q="为什么Ilthalaine要求猎杀年轻的霜刃豹和野猪？",a="沉重的春雨使得幽影谷无法支撑日益增长的霜刃豹和蓟野猪种群。Ilthalaine请求进行适度的猎杀以维持大自然的平衡。",al={"大自然的平衡任务","为什么要猎杀霜刃豹","为什么要猎杀野猪"}},{q="他发放的徽记是什么？",a="Ilthalaine会将刻有职业标记的徽记交给新手，指示他们寻找各自的训练师——例如牧师、德鲁伊、战士和潜行者——他们都驻扎在奥达希尔的树根深处。",al={"风化符记","简易符记","绿色符记","密文符记","神圣符记"}},{q="在哪里可以找到Ilthalaine？",a="他站在幽影谷的中央小径上，就在泰达希尔的奥达希尔巨树空心树干南侧。",al={"ilthalaine位置","ilthalaine在哪里","ilthalaine坐标"}},{q="Ilthalaine是隶属于德鲁伊还是哨兵？",a="Ilthalaine在幽影谷担任通用的看护者和卡多雷的代表。虽然他深谙自然之道与和谐的德鲁伊精神，但他代表达纳苏斯的领导层引导各个职业的新手。",al={"他是德鲁伊吗","ilthalaine属于哪个阵营"}}},fx={e95b9493={q="Ilthalaine为何在幽影谷？",a="Ilthalaine驻守幽影谷，迎接初出茅庐的暗夜精灵守卫，并维护泰达希尔神圣苗圃脆弱的平衡。当地野生动物日益焦躁，腐化的迹象也渗入枝叶之间；他仍驻扎在奥达希尔附近，引导新来者，并指挥他们尽早着手治愈和保护这棵世界之树。",al={"ilthalaine为何在此","ilthalaine在幽影谷的目的","ilthalaine为何在泰达希尔"}}},fp="10,368,20.455.0,21.274.0,21.405.0,18.238.0,40.249.0,64.170.0,33.199.0,30.117.0,58.239.0"}
P.entries["npc:innkeeper-allison"] = {n="旅店老板奥里森",s="旅店老板奥里森管理着金罗盘旅店，这是暴风城中最繁忙、位置最中心的旅店之一。旅店位于Trade District的核心地带，正好坐落在银行和拍卖行之间，她为疲惫的旅行者和当地商人提供炉石绑定、清爽的饮料和休憩之所。",h="旅店老板奥里森管理着金罗盘旅店，这是暴风城中最繁忙、位置最中心的旅店之一。旅店位于Trade District的核心地带，正好坐落在银行和拍卖行之间，她为疲惫的旅行者和当地商人提供炉石绑定、清爽的饮料和休憩之所。",kw={"奥里森","金罗盘","炉石","旅店老板奥里森","暴风城","trade district"},ang={["faction:Alliance"]="作为暴风城商业核心区最便利旅店的经营者，奥里森是联盟勇士们从前线战役归来休息并存取战利品时最熟悉的面孔之一。"},sec={{t="Trade District的待客之道",b="金罗盘旅店正处于熙熙攘攘的贸易区拍卖行和主城金库之间，是冒险者抵达暴风城后的中心枢纽。旅店老板奥里森站在一楼的主柜台后，在络绎不绝的商贩、雇佣兵和来访的外交官之间维持着秩序。除了提供住宿和炉石服务外，她还经常参与当地的节日庆典，并为在首都寻求休息的英雄们安排一些零碎的差事。"}},faq={{q="我在哪里可以找到旅店老板奥里森？",a="旅店老板奥里森站在金罗盘旅店一楼的柜台后面。这家旅店位于暴风城的Trade District内，坐落在中央银行和拍卖行之间。",al={"奥里森位置","旅店老板奥里森在哪里","金罗盘旅店老板"}},{q="旅店老板奥里森提供什么服务？",a="她提供标准的旅店老板服务：玩家可以将炉石绑定在金罗盘旅店，购买食物和饮料以供恢复，并且可以在全城的节日庆典期间与她进行互动。",al={"奥里森做什么","奥里森服务","我可以在这里绑定炉石吗"}},{q="旅店老板奥里森提供任务吗？",a="是的，奥里森全年都会参与各种节日庆典，例如节日庆祝活动，并且偶尔会参与到为寻求援助的旅行者提供的跑腿任务中。",al={"奥里森任务","旅店老板奥里森任务"}}},fp="17,221,33.453.0,35.178.0,43.155.0,40.142.0"}
P.entries["npc:innkeeper-farley"] = {n="旅店老板法雷",s="旅店老板法雷经营着位于闪金镇的Lion's Pride Inn，为路过艾尔文森林的旅行者提供食物、住宿和炉石。他深受欢迎且观察入微，经常代收失踪的信件，也会倾听路上冒险者的烦恼。",h="旅店老板法雷经营着位于闪金镇的Lion's Pride Inn，为路过艾尔文森林的旅行者提供食物、住宿和炉石。他深受欢迎且观察入微，经常代收失踪的信件，也会倾听路上冒险者的烦恼。",kw={"艾尔文森林","弗雷德里克·法雷","闪金镇","旅店老板法雷","lion's pride inn","斯塔文"},ang={["faction:Alliance"]="对于从北郡山谷出发的新兵来说，Lion's Pride Inn法雷的柜台往往是他们绑定炉石并购买补给的第一个地方。"},sec={{t="闪金镇的常驻者",b="旅店老板法雷以热情的手腕和敏锐的目光经营着Lion's Pride Inn。前往暴风城、西部荒野和暮色森林的旅行者都会在他的柜台前停下脚步，享用热饭、麦芽酒和床铺。作为王国最繁忙的中转站之一，法雷在此维持着秩序，为所有路过闪金镇的人斟满麦芽酒，端上奶酪。"},{t="信使遗弃的箱子",b="由于闪金镇位于暴风城、西部荒野和暮色森林之间的十字路口，法雷经常能听到许多传闻，也应对过各种奇怪的旅行者。值得一提的是，他曾接待过一名惊恐地冲入夜色的信使，那人丢下了自己的背包。法雷将留下的信件妥善存放在楼上的箱子里——其中包括一封寄给前任教师斯塔文·密斯曼陀的未寄出的信，这封信后来成了调查人员追踪这位堕落导师行踪的关键线索。"}},faq={{q="旅店老板法雷是谁？",a="旅店老板法雷是闪金镇Lion's Pride Inn的店主，为穿行于艾尔文森林的旅行者提供休息之所和补给品。",al={"旅店老板法雷","弗雷德里克·法雷","闪金镇旅店老板是谁"}},{q="法雷关于斯塔文·密斯曼陀知道些什么？",a="法雷记得有一名惊恐的信使曾在深夜逃离Lion's Pride Inn，留下了几件待投递的信件。法雷将这些被遗弃的信件存放在楼上的一个箱子里，其中就有一封寄给斯塔文·密斯曼陀的未寄出的信，调查人员可以取回它。",al={"法雷 斯塔文","斯塔文 信 闪金镇","斯塔文传说 法雷"}},{q="法雷在旅店提供哪些服务？",a="法雷为旅行者绑定炉石，出租房间，并出售各种来自联盟各地的饮料、果汁和奶酪，从奥特兰克冷酪、达拉然奶酪到当地的暴风城奶酪，应有尽有。",al={"lion's pride服务","法雷 食物和饮料","闪金镇炉石"}}},fp="16,203,19.335.0,29.413.1,24.133.0,47.265.0,45.196.0"}
P.entries["npc:innkeeper-firebrew"] = {n="旅店老板洛雷·火酒",s="旅店老板洛雷·火酒在铁炉堡繁华的平民区经营着Stonefire Tavern。作为一名热情好客的主人，无论你是疲惫的登山者还是远道而来的尊贵宾客，他都为你提供丰盛的矮人主食，让旅客在山中得到充分的休憩。",h="旅店老板洛雷·火酒在铁炉堡繁华的平民区经营着Stonefire Tavern。作为一名热情好客的主人，无论你是疲惫的登山者还是远道而来的尊贵宾客，他都为你提供丰盛的矮人主食，让旅客在山中得到充分的休憩。",kw={"平民区","矮人","火酒","炉石","旅店老板","铁炉堡","stonefire tavern"},ang={["faction:Alliance"]="作为正门附近的主要旅店老板，洛雷·火酒为前来拜访国王麦格尼·铜须首都的联盟外来旅客提供了一个中心化的安全休憩之所。",["race:Dwarf"]="对于从卡兹莫丹各地巡逻归来的矮人来说，火酒的旅店提供了家的温暖和一杯可靠的矮人烈性黑啤。"},sec={{t="烈焰之石守护者",b="Stonefire Tavern坐落于平民区的中心环形地带，是旅客从铁炉堡大门进入后通常遇到的第一个避风港。在堆满麦酒桶、烈性黑啤和烤肉的柜台后，洛雷·火酒为那些准备前往丹莫罗雪道或深入矮人王国的冒险者们提供接待服务。他的旅店依然是一个热闹的十字路口，矿工、步枪手和特使们聚集于此，躲避寒冷的隧道，围坐在炉火旁交换故事。"}},faq={{q="我在哪里可以找到旅店老板洛雷·火酒？",a="旅店老板洛雷·火酒位于铁炉堡平民区南缘的Stonefire Tavern内。",al={"火酒位置","旅店老板火酒在哪里","铁炉堡旅店老板"}},{q="火酒卖些什么商品？",a="他提供标准的旅店补给品，主打地道的矮人干粮。旅客可以购买从当地矮人烈性黑啤和蜂蜜酒到进口葡萄酒等各类饮品，以及适合长途旅行的肉类和丰盛餐点。",al={"火酒卖什么","火酒饮料","stonefire tavern食物"}},{q="火酒属于某个矮人酿酒家族吗？",a="他的姓氏是火酒，但其家族关系并未得到证实。",al={"火酒家族","火酒和谁有关系"}},{q="他为旅客提供什么服务？",a="作为一名旅店老板，洛雷·火酒允许联盟的旅行者将炉石绑定在Stonefire Tavern，并提供温暖的床铺供他们在山中休息和恢复。",al={"我可以在这里绑定炉石吗","铁炉堡炉石旅店"}}},fx={["9fc434fc"]={q="旅店老板洛雷·火酒是谁？",a="旅店老板洛雷·火酒是矮人，经营着位于铁炉堡热闹的公共区中的Stonefire Tavern。在这座山中城市里，他是个热情好客的人，照看炉火、供应麦酒，并为当地居民和疲惫的旅人提供食物与住宿。",al={"火酒是谁","旅店老板洛雷·火酒","stonefire tavern旅店老板"}},["3dd110f9"]={q="旅店老板洛雷·火酒支持哪一方？",a="火酒忠于铁炉堡王国，并坚定地支持联盟。他的酒馆向所有寻求庇护、躲避丹莫罗寒风，或长途跋涉艾泽拉斯后想要休息的联盟冒险者开放。",al={"火酒的阵营","火酒与联盟","火酒是联盟的吗"}},e30bdb86={q="旅店老板洛雷·火酒想要什么？",a="火酒专心经营一家热闹而好客的酒馆。他希望Stonefire Tavern炉火旺盛，为客人的酒杯斟满醇厚的矮人佳酿，并确保到访这座大锻炉之城的旅人有温暖的地方休息、绑定炉石。",al={"火酒想要什么","火酒的动机","火酒的目标"}},b21a7171={q="旅店老板洛雷·火酒为什么在这里？",a="火酒管理着公共区的Stonefire Tavern，是进入铁炉堡腹地的旅人最主要的东道主。他守在炉火旁，提供住宿、出售食物和饮品，并为抵达这座首都的冒险者提供温馨可靠的落脚处。",al={"火酒为什么在铁炉堡","火酒为什么在stonefire tavern"}}},fp="18,235,23.540.0,36.117.0,38.230.0,47.78.0,43.178.0"}
P.entries["npc:innkeeper-grosk"] = {n="旅店老板格罗斯克",s="旅店老板格罗斯克经营着位于剃刀岭的旅店，为杜隆塔尔中部的疲惫旅者提供食物、饮品和休息之所。他的旅店位于试炼谷和奥格瑞玛之间繁忙的道路上，是年轻的部落冒险者踏入广阔世界时的主要落脚点。",h="旅店老板格罗斯克经营着位于剃刀岭的旅店，为杜隆塔尔中部的疲惫旅者提供食物、饮品和休息之所。他的旅店位于试炼谷和奥格瑞玛之间繁忙的道路上，是年轻的部落冒险者踏入广阔世界时的主要落脚点。",kw={"杜隆塔尔","格罗斯克","旅店老板","旅店老板格罗斯克","奥格瑞玛","苦工的重担","剃刀岭"},ang={["faction:Horde"]="对于刚经过血统试炼的兽人、巨魔，以及从试炼谷或森金村向北旅行的牛头人来说，格罗斯克的旅店标志着前往奥格瑞玛路上的第一个真正的城镇和炉石绑定点。"},sec={{t="红色荒野中的待客之道",b="剃刀岭是连接杜隆塔尔南部训练场与奥格瑞玛高大城墙的重要十字路口定居点。在这个中转站的中心，站着旅店老板格罗斯克，他是一位兽人，负责为战士、斥候和苦工提供庇护。他的旅店为旅者提供了一个躲避严酷沙漠酷暑的休憩之所，储备着基础补给、丰盛的肉食和清凉的泉水，供任何从坚固木梁下经过的旅人使用。"},{t="苦工的休憩处",b="除了为过往的旅人服务，格罗斯克还协助当地维持杜隆塔尔运转的劳动力。在任务“苦工的重担”中，胆小的苦工乌克尔把食物一路运到了试炼谷，却发现那里并不需要，于是他请求旅者将货物运回剃刀岭格罗斯克的旅店。"}},faq={{q="旅店老板格罗斯克在哪里？",a="旅店老板格罗斯克站在剃刀岭的旅店里，位于杜隆塔尔中心，紧邻通往奥格瑞玛的主干道。",al={"旅店老板格罗斯克位置","格罗斯克在哪里","剃刀岭旅店老板"}},{q="旅店老板格罗斯克提供什么服务？",a="格罗斯克担任旅店老板，部落冒险者可以在此将炉石绑定在剃刀岭。他还出售基础食物、水和肉食，以供旅途中恢复生命值和法力值。",al={"格罗斯克有什么用","格罗斯克商人","我可以在剃刀岭绑定炉石吗"}},{q="旅店老板格罗斯克提供任务吗？",a="他与任务“苦工的重担”有关，接收苦工乌克尔因为害怕杜隆塔尔野兽而不敢独自运回剃刀岭的食物。",al={"旅店老板格罗斯克任务","苦工的重担交还"}}},fx={["490d29ee"]={q="旅店老板格罗斯克是谁？",a="旅店老板格罗斯克是兽人，经营着剃刀岭的酒馆。旅人、步兵和四处游荡的冒险者在前往奥格瑞玛或从那里归来、途经杜隆塔尔时，格罗斯克会为他们提供庇护、补给，以及让疲惫身躯歇息的炉火。",al={"格罗斯克是谁","旅店老板格罗斯克","旅店老板格罗斯克是谁"}},["10a7c15b"]={q="旅店老板格罗斯克支持哪一方？",a="格罗斯克是部落坚定的一员，欢迎兽人、巨魔、牛头人和被遗忘者光临他的店。他确保为酋长萨尔的新领地而战的人们，在杜隆塔尔有可靠的休息和补给据点。",al={"格罗斯克是部落的吗","旅店老板格罗斯克的忠诚归属","旅店老板格罗斯克的阵营"}},["29305f72"]={q="旅店老板格罗斯克想要什么？",a="格罗斯克希望旅店经营顺利，为往来杜隆塔尔干旱平原的旅人提供服务。他交易丰盛的食物和饮品，为四处游历的冒险者绑定炉石，偶尔也照料镇上劳工和卫兵的需求。",al={"格罗斯克想要什么","格罗斯克的动机","旅店老板格罗斯克的目标"}},["7fe37467"]={q="旅店老板格罗斯克为什么在剃刀岭？",a="剃刀岭是连接试炼谷、森金村与首都奥格瑞玛的主要路口和驻军城镇。格罗斯克在此开设酒馆，为杜隆塔尔边境生活的核心地带提供必需的住宿和补给。",al={"格罗斯克为什么在这里","剃刀岭旅店老板的缘由","格罗斯克在剃刀岭的职责"}}},fp="15,319,29.423.0,16.302.0,33.147.0,43.180.0,38.168.0"}
P.entries["npc:innkeeper-gryshka"] = {n="旅店老板格雷什卡",s="旅店老板格雷什卡是一位兽人老板，负责管理奥格瑞玛Valley of Strength内的Broken Tusk旅店。作为迎接通过城门抵达的旅客的主要接待人，她为来访的部落冒险者提供炉石绑定、食物和饮料。她与杜隆塔尔和贫瘠之地的猎人和斥候保持着密切联系，以确保她的旅店供应充足的精选肉块。",h="旅店老板格雷什卡是一位兽人老板，负责管理奥格瑞玛Valley of Strength内的Broken...",kw={"broken tusk","多拉斯","格雷什卡","炉石","旅店老板","奥格瑞玛","valley of strength","扎尔夫"},ang={["faction:Horde"]="对于任何抵达杜隆塔尔的部落旅客来说，格雷什卡在Valley of Strength的旅店通常是绑定炉石和补给的主要枢纽，之后再深入卡利姆多。",["profession:Cooking"]="厨师们会欣赏格雷什卡挑剔的味蕾，因为她不遗余力地从远至贫瘠之地驻扎的猎人那里采购上等肉块。"},sec={{t="Valley of Strength的炉火",b="格雷什卡站在Broken Tusk的柜台后，管理着部落中最繁忙的旅店之一。她的店位于奥格瑞玛Valley of Strength的城门外，是勇士、信使和刚抵达并寻求萨尔麾下庇护的英雄们的第一个休息点。"},{t="对鲜肉的喜好",b="在干旱的峡谷中经营一家热闹的酒馆需要稳定的补给线。格雷什卡以对鲜肉的执着而闻名，她依靠整个部落领地的可靠猎人来供应她的厨房。像十字路口的扎尔夫和杜隆塔尔的Grimtak这样的同伴，经常把他们最好的猎物肉块运回Broken Tusk，以满足她挑剔的烹饪标准。"}},faq={{q="谁是旅店老板格雷什卡？",a="旅店老板格雷什卡是一位兽人旅店老板，在奥格瑞玛Valley of Strength内经营着Broken Tusk旅店。她欢迎部落的旅客，设置炉石绑定，并向疲惫的冒险者出售食物和饮料。",al={"谁是格雷什卡","格雷什卡 奥格瑞玛","旅店老板 broken tusk"}},{q="哪里可以找到旅店老板格雷什卡？",a="她位于Valley of Strength的Broken Tusk旅店内，这是你穿过奥格瑞玛南部主城门后进入的第一个主要区域。",al={"格雷什卡在哪里","broken tusk旅店位置","valley of strength旅店老板"}},{q="格雷什卡从哪里获得她的肉类补给？",a="格雷什卡依靠遍布部落领地的朋友和斥候来补充她的储藏室，包括驻扎在贫瘠之地十字路口的扎尔夫和杜隆塔尔的Grimtak，他们为她送来精选的猎物肉块。",al={"格雷什卡的食物来源","谁给broken tusk供货","扎尔夫送肉"}},{q="格雷什卡提供什么服务？",a="格雷什卡可以将你的炉石绑定到Broken Tusk，这样你就可以直接传送回奥格瑞玛。她还出售各种食物、面包和饮料来恢复生命值和法力值。",al={"我可以在这里绑定炉石吗","broken tusk炉石","格雷什卡出售的物品"}},{q="格雷什卡与双足飞龙管理员有什么联系吗？",a="从贫瘠之地执行飞行任务的旅客通常会直接将包裹交给格雷什卡，然后再被指引去找多拉斯，那位栖息在城市上方台地高处的双足飞龙管理员。",al={"多拉斯任务","双足飞龙管理员 broken tusk","前往奥格瑞玛旅店"}},{q="格雷什卡的性格如何？",a="格雷什卡是一位务实、热情的兽人老板，她喜欢好肉，说话直接，并确保她的旅店货源充足且井然有序，以接待源源不断经过首都的部落勇士。",al={"格雷什卡友好吗","格雷什卡是什么样的人"}}},fx={ad24947b={q="旅店老板格雷什卡支持哪一方？",a="格雷什卡是部落忠诚的女儿。她在奥格瑞玛的力量谷经营酒馆，直接招待为酋长萨尔效力的战士、猎人和旅人，确保他们能在部落的旗帜下休憩并享用丰盛的食物。",al={"格雷什卡的阵营","格雷什卡为谁效力","格雷什卡是部落的吗"}},f36e4eb0={q="旅店老板格雷什卡想要什么？",a="格雷什卡最希望Broken Tusk物资充足、宾客盈门。她对优质肉食有着出了名的大胃口，不断依靠杜隆塔尔和贫瘠之地各处的朋友送来新鲜上等的肉块，满足自己和饥肠辘辘的客人。",al={"格雷什卡想要什么","格雷什卡的目标","格雷什卡在寻找什么"}},edbe4e1f={q="旅店老板格雷什卡为什么在这里？",a="格雷什卡管理着Broken Tusk，这是奥格瑞玛力量谷中心热闹的旅店。她留在此处，为途经首都或从严酷荒野归来的旅人提供款待、食物、烈酒和庇护。",al={"格雷什卡为什么在奥格瑞玛","格雷什卡为什么在broken tusk","格雷什卡的职责"}}},fp="17,404,32.337.0,22.381.0,25.213.0,37.166.0,41.195.0,35.172.0,57.190.0,43.196.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="旅店老板凯达米尔",s="旅店老板凯达米尔管理着泰达希尔多兰纳尔中心旅店的炉火和食宿。他为从幽影谷踏上冒险旅程、探索世界之树广阔枝干的年轻暗夜精灵提供食物、饮品和休憩之所。",h="旅店老板凯达米尔管理着泰达希尔多兰纳尔中心旅店的炉火和食宿。他为从幽影谷踏上冒险旅程、探索世界之树广阔枝干的年轻暗夜精灵提供食物、饮品和休憩之所。",kw={"多兰纳尔","炉石","旅店","旅店老板","凯达米尔","暗夜精灵","泰达希尔"},ang={["race:NightElf"]="对于刚从幽影谷训练场出发的暗夜精灵来说，凯达米尔的旅店通常是他们离开家园后第一个可以绑定炉石的地方。"},sec={{t="多兰纳尔的炉火",b="多兰纳尔是新手离开庇护之所奥达希尔后抵达的主要村庄。旅店老板凯达米尔维护着社区中心的避风港，在泰达希尔的树冠下提供面包、泉水和柔软的床铺。前往达纳苏斯的旅行者、哨兵和年轻的新手们经常在他的柜台前驻足，以休养生息、绑定炉石，并储备穿越枝干旅途所需的口粮。"},{t="城镇补给",b="在高耸的树枝上经营一家旅店需要来自附近定居点和商人的稳定供应线。当地的信使经常会被指引直接前往凯达米尔的办公桌递送货物，这让他直接参与到了维持多兰纳尔定居点顺畅运作的日常贸易和物流工作中。"}},faq={{q="我在哪里可以找到旅店老板凯达米尔？",a="凯达米尔位于多兰纳尔中心的主旅店建筑内，这是泰达希尔枝干上幽影谷以南的第一个主要定居点。",al={"凯达米尔位置","凯达米尔在哪里","多兰纳尔旅店老板位置"}},{q="旅店老板凯达米尔提供什么服务？",a="他担任当地的旅店老板，这意味着你可以将炉石绑定在他的炉火旁，购买水、牛奶、果汁和面包等基本补给品，或者在他的屋檐下休息下线。",al={"凯达米尔售卖商品","凯达米尔卖什么","多兰纳尔旅店食物"}},{q="有哪些任务与旅店老板凯达米尔有关？",a="他是当地信使任务“多兰纳尔的货物”的接收人，负责接收用于维持定居点旅店日常运营和供应的包裹。",al={"凯达米尔任务","多兰纳尔的货物交任务"}}},fx={cc228f0e={q="旅店老板凯达米尔是谁？",a="旅店老板凯达米尔是一位暗夜精灵，经营着多兰纳尔的旅店。旅人往来于幽影谷的林荫空地和泰达希尔更广阔的区域之间时，凯达米尔会为疲惫的冒险者提供安静的炉火、清爽的饮品和补给，助他们穿行于巨大的枝干之间。",al={"凯达米尔是谁","旅店老板凯达米尔的背景"}},["1430db47"]={q="旅店老板凯达米尔支持哪一方？",a="旅店老板凯达米尔忠于达纳苏斯和联盟。他服务于多兰纳尔的暗夜精灵社群，为族人和来访的联盟盟友敞开大门，让他们在泰达希尔的树冠下休息。",al={"凯达米尔的阵营","凯达米尔是联盟的吗"}},ff7bce47={q="旅店老板凯达米尔想要什么？",a="凯达米尔致力于让多兰纳尔的旅店货品充足、宾客盈门。他接收补给、协调本地送货，并确保每位路过的旅人都能获得食物和水，在踏入荒野前找到安全的地方绑定炉石。",al={"凯达米尔的目标","凯达米尔想要什么"}},dbe1a8c8={q="旅店老板凯达米尔为什么在多兰纳尔？",a="多兰纳尔是年轻暗夜精灵结束幽影谷训练后前往的主要路口和聚居地。凯达米尔把村庄旅店设在路旁，为泰达希尔这处重要的交通节点提供庇护和食物。",al={"凯达米尔为什么在这里","凯达米尔与多兰纳尔"}}},fp="18,232,18.432.0,15.310.0,36.150.0,44.187.0,39.141.0"}
P.entries["npc:innkeeper-norman"] = {n="旅店老板诺曼",s="旅店老板诺曼在幽暗城的Trade Quarter主要旅店里照看炉火。作为一名安静且勤勉的被遗忘者，他为部落的旅人们提供休憩之所、炉石绑定服务，以及适合生者与死者各种口味的食物。",h="旅店老板诺曼在幽暗城的Trade Quarter主要旅店里照看炉火。作为一名安静且勤勉的被遗忘者，他为部落的旅人们提供休憩之所、炉石绑定服务，以及适合生者与死者各种口味的食物。",kw={"贝茨","万圣节","炉石","旅店老板","诺曼","trade quarter","幽暗城"},ang={["faction:Horde"]="对于访问幽暗城的生者部落盟友来说，诺曼的旅店是这座令人生畏的地下堡垒中为数不多提供安全休憩与恢复的地方之一。",["race:Undead"]="诺曼为同胞被遗忘者们提供了一个在Trade Quarter中心地带的聚会场所，让他们能在为黑暗女王执行任务的间隙休息一下骸骨。"},sec={{t="下水道里的热情待客",b="旅店老板诺曼位于洛丹伦废墟之下繁华的Trade Quarter，为经过这处被遗忘者堡垒的使者、雇佣兵和冒险者们提供住宿。尽管幽暗城里充斥着潮湿的寒气和炼金药剂的恶臭，但诺曼的旅店依然是旅人们绑定炉石、分享艾泽拉斯各地新闻或为前往瘟疫之地的探险做准备的热闹枢纽。"},{t="节日的怪癖",b="虽然诺曼通常只专注于他售卖补给和管理房间的职责，但随着万圣节的到来，他展现出了更古怪的一面。在节日期间，诺曼会加入节日的狂欢，并要求那些渴望获得幽暗城薄荷糖等节日礼物的冒险者顾客做出一些奇特的举动，比如像小鸡一样咯咯叫。"}},faq={{q="我在哪里可以找到旅店老板诺曼？",a="旅店老板诺曼位于幽暗城Trade Quarter的主要旅店里，就在内环南侧的弯道上。",al={"诺曼位置","幽暗城旅店老板位置","诺曼在哪里"}},{q="旅店老板诺曼提供什么服务？",a="他是幽暗城的主要旅店老板。玩家可以将他们的炉石绑定到他的旅店，购买适合生者与亡灵食用的食物和饮料，或者安全地离线以获得休息状态。",al={"诺曼服务","幽暗城炉石"}},{q="为什么诺曼要求顾客像小鸡一样咯咯叫？",a="在万圣节期间，诺曼会参与传统的节日恶作剧。想要获得特殊节日薄荷糖的冒险者必须放下自尊，像小鸡一样咯咯叫来赢得他的青睐。",al={"小鸡咯咯叫薄荷糖","诺曼小鸡任务"}},{q="诺曼和贝茨旅店老板有关联吗？",a="虽然他们在生前或死后从未直接提及对方，但并没有已知的亲属关系。他们名字的组合是游戏开发者对电影《惊魂记》中旅店老板诺曼·贝茨的一种俏皮致敬。",al={"诺曼·贝茨关联","旅店老板贝茨诺曼"}}},fx={["543a0ebc"]={q="旅店老板诺曼是谁？",a="旅店老板诺曼是一名被遗忘者酒保，照看着幽暗城Trade Quarter里热闹的酒馆。许多亡灵已抛弃生前生活的舒适，而诺曼则招待途经希尔瓦娜斯女士地下堡垒的疲惫旅人、士兵和使节，为他们提供食物、饮品和休息之处。",al={"诺曼是谁","旅店老板诺曼的背景","诺曼与幽暗城"}},bc99de77={q="旅店老板诺曼支持哪一方？",a="诺曼忠于被遗忘者和黑暗女士，因此也为更广大的部落效力。他身处Trade Quarter中心，向来访的兽人、巨魔和牛头人敞开大门，在洛丹伦废墟下为他们提供庇护，同时对自己的亡灵同胞忠心耿耿。",al={"诺曼的阵营","诺曼的忠诚归属","诺曼是部落的吗"}},["58ea57aa"]={q="旅店老板诺曼为什么在这里？",a="诺曼负责幽暗城的主要旅店，驻守在贸易区的中心地带，这里是贸易、旅行和政治交汇之处。即使身处亡灵之中，访客和市民也需要一个聚集之地，以交换传闻、绑定炉石并补充物资；诺曼让酒馆在阴郁的氛围中依然运转顺畅。",al={"诺曼为什么在幽暗城","诺曼 贸易区","诺曼在这里做什么"}}},fp="16,256,25.440.0,22.353.0,34.140.0,44.201.0,52.197.0,37.216.0"}
P.entries["npc:innkeeper-pala"] = {n="旅店老板帕拉",s="旅店老板帕拉经营着猫与萨满旅店，这是一家位于雷霆崖下层的热闹酒馆。她为到访的冒险者提供炉石绑定、冷饮以及在往返莫高雷及更远地区之间休息的场所。",h="旅店老板帕拉经营着猫与萨满旅店，这是一家位于雷霆崖下层的热闹酒馆。她为到访的冒险者提供炉石绑定、冷饮以及在往返莫高雷及更远地区之间休息的场所。",kw={"猫与萨满","炉石","旅店老板","旅店老板帕拉","莫高雷","帕拉","雷霆崖"},ang={["faction:Horde"]="兽人、巨魔和被遗忘者在到访莫高雷时，会发现帕拉的旅店是一个靠近升降梯的舒适行动基地。",["race:Tauren"]="对于从卡利姆多前线返回家园的牛头人来说，帕拉在中央台地高耸的图腾下提供了一张熟悉且受欢迎的面孔。"},sec={{t="下层的热情款待",b="旅店老板帕拉坐在雷霆崖广阔台地的一处下层，在猫与萨满旅店里照看炉火。这家店是旅客走下中央升降梯或从莫高雷广袤平原抵达后的主要聚会点之一。帕拉时刻关注着她的公共休息室，确保疲惫的战士、漫游的德鲁伊和到访的部落盟友都能找到一个可靠的栖身之所、一杯温热的饮品，以及一个远离家乡却倍感亲切的港湾。"}},faq={{q="我在哪里可以找到旅店老板帕拉？",a="帕拉驻扎在猫与萨满旅店里，这家旅店位于雷霆崖的下层，靠近城市的主升降梯。",al={"帕拉位置","帕拉在哪里","旅店老板帕拉地图"}},{q="她为旅行者提供什么服务？",a="像卡利姆多各地的旅店老板一样，帕拉可以将你的炉石绑定在猫与萨满旅店，这样你就能随时回来。她也出售简单的食物和饮料来补充生命值和法力值。",al={"帕拉服务","我可以在雷霆崖绑定炉石吗","帕拉卖什么"}},{q="她的酒馆叫什么名字？",a="她的酒馆名为猫与萨满，专门为穿行于城市下层的源源不断的部落旅行者提供服务。",al={"猫与萨满","雷霆崖下层旅店名称","帕拉旅店名称"}}},fx={["18c94984"]={q="旅店老板帕拉是谁？",a="旅店老板帕拉是一位牛头人旅店老板，在雷霆崖下层高地的“猫与萨满”旅店照料旅行者和疲惫的旅人。她打理炉火、清扫地板，为前来牛头人首都高地的访客提供食物、饮品和休憩之所。",al={"帕拉是谁","旅店老板帕拉","旅店老板帕拉是谁"}},["3afadd2e"]={q="旅店老板帕拉效忠于哪一方？",a="旅店老板帕拉效忠于牛头人部族和凯恩·血蹄大酋长领导下的部落。她热情地驻守在雷霆崖中心，乐于招待牛头人同胞、兽人、巨魔，以及前来城中寻求款待的被遗忘者。",al={"旅店老板帕拉的阵营","旅店老板帕拉效忠哪方","帕拉是部落的吗"}},["0c2271e0"]={q="旅店老板帕拉想要什么？",a="帕拉只想让“猫与萨满”旅店顺利经营下去。她专注于热情待客、供应物资，并为疲惫的旅人提供一个干净、宁静的避风港，让他们在横越卡利姆多的艰苦旅途中绑定炉石、稍作休息。",al={"帕拉想要什么","帕拉的目标","旅店老板帕拉的职责"}},["1c871847"]={q="旅店老板帕拉为什么在这里？",a="雷霆崖广阔的高地上，往来于莫高雷平原的猎人、萨满和使者络绎不绝。旅店老板帕拉驻守在下层高地经营酒馆，确保到来的冒险者和商人随时能找到温暖的炉火和所需物资。",al={"帕拉为什么在这里","帕拉为什么在雷霆崖","旅店老板帕拉的角色"}}},fp="14,243,29.485.0,32.134.0,44.192.0,31.146.0"}
P.entries["npc:interrogator-vishas"] = {n="审讯员韦沙斯",s="审讯员詹姆斯·韦沙斯是血色十字军的折磨大师，驻扎在血色修道院墓地区域的深处。他以尖锐的嗓音和极度的残忍而闻名，他以摧毁俘虏的身心和测试凡人肉体的极限为变态的乐趣。很少有人能在进入他的刑讯室后还能保持身心完整地离开。",h="审讯员詹姆斯·韦沙斯是血色十字军的折磨大师，驻扎在血色修道院墓地区域的深处。他以尖锐的嗓音和极度的残忍而闻名，他以摧毁俘虏的身心和测试凡人肉体的极限为变态的乐趣。很少有人能在进入他的刑讯室后还能保持身心完整地离开。",kw={"墓地","审讯员韦沙斯","詹姆斯·韦沙斯","洛丹米尔湖","南希·韦沙斯","血色修道院","折磨","沃雷尔·森古兹"},ang={["class:Priest"]="目睹韦沙斯援引狂热来美化恐怖的肢解行为，让人冷汗直流，这展示了神圣的目标是如何堕落成扭曲的疯狂的。",["faction:Alliance"]="发现韦沙斯所作所为的联盟英雄们很快意识到，血色十字军已经不再区分天灾军团的怪物和无辜的活人旅行者。",["race:Undead"]="对于被遗忘者来说，韦沙斯体现了活着的狂热信徒那虚伪的恶意，他以侍奉圣光为借口，纯粹出于怨恨而折磨被捕的亡灵。"},sec={{t="大检察官的手术刀",b="在血色修道院阴暗的墓穴和埋葬地中，审讯员韦沙斯负责看管十字军的俘虏。虽然外面的狂热信徒们身穿闪亮的铠甲，举着纯洁的旗帜游行，但韦沙斯展现了他们十字军背后残酷的现实：隐藏在宗教狂热背后的肆意虐待。他不仅将审讯视为一种情报任务，更将其视为一种引以为傲的技艺，沉迷于折磨被遗忘者俘虏、捕获的天灾军团成员，以及任何不幸被贴上异端标签的活人旅行者。"},{t="安静的家庭生活",b="在血淋淋的围裙和刑讯室的尖叫声背后，韦沙斯过着一种离奇的双重家庭生活。在修道院围墙之外，他的家人——包括他的妻子南希·韦沙斯和他的长辈韦沙斯爷爷——安静地居住在奥特兰克山脉洛丹米尔湖东岸的一间偏僻小屋里。韦沙斯甚至会将他从受害者身上获取的恐怖战利品带入他的个人生活中，他曾剥下被遗忘者俘虏沃雷尔·森古兹心爱的婚戒，作为礼物送给南希。"}},faq={{q="审讯员韦沙斯在哪里？",a="审讯员韦沙斯位于提瑞斯法林地的血色修道院墓地区域深处。他监管着一间阴森的刑讯室，里面排列着铁笼和沾满鲜血的刑架。",al={"韦沙斯位置","审讯员韦沙斯在哪里","韦沙斯的房间"}},{q="为什么韦沙斯要折磨他的囚犯？",a="虽然血色十字军以根除天灾军团的腐化和获取情报为由对俘虏进行折磨，但韦沙斯本人却乐于制造痛苦。他对自己施加的残忍行径感到极度的自豪，并将折磨视为一种艺术创作。",al={"为什么韦沙斯折磨人","韦沙斯的动机"}},{q="谁是沃雷尔·森古兹？",a="沃雷尔·森古兹是被韦沙斯关押在修道院墓地中并遭受残酷折磨的一名俘虏。韦沙斯让沃雷尔承受了数周的痛苦，并偷走了他的婚戒，打算将其作为礼物送给自己的妻子。",al={"囚犯沃雷尔·森古兹","笼子里的囚犯是谁"}},{q="韦沙斯的家人住在哪里？",a="他的家人住的地方远离修道院，位于奥特兰克山脉洛丹米尔湖东岸的一间朴素小屋里。他的妻子南希和韦沙斯爷爷安静地居住在那里，似乎与他的暴行毫无瓜葛。",al={"南希·韦沙斯的位置","韦沙斯爷爷","韦沙斯的家庭住址"}},{q="韦沙斯关押了谁？",a="血色十字军将亡灵视为敌人。韦沙斯的囚犯中包括被遗忘者沃雷尔·森古兹，他已经被折磨了数周。",al={"韦沙斯的囚犯","韦沙斯折磨谁","韦沙斯的俘虏沃雷尔"}},{q="韦沙斯的声音和举止是怎样的？",a="韦沙斯因其刺耳的高音、尖锐的笑声，以及每当有机会从不情愿的受害者口中逼问秘密时那种令人不安的兴奋感，而在面对他的人群中臭名昭著。",al={"韦沙斯的声音","韦沙斯的个性"}}},fx={["518fe48c"]={q="审讯员韦沙斯是谁？",al={"韦沙斯是谁","审讯员韦沙斯背景","詹姆斯·韦沙斯是谁"}},cadee917={q="审讯员韦沙斯效忠于哪一方？",a="韦沙斯完全效忠于血色十字军。他通过折磨被怀疑为天灾军团代理人的人、被遗忘者囚犯，以及任何被视为玷污或敌视血色十字军狂热纯洁信条的人，来服务于他们的狂热圣战。",al={"韦沙斯的阵营","韦沙斯为谁效力","韦沙斯 血色十字军"}},e1510cf6={q="审讯员韦沙斯为什么在这里？",a="韦沙斯驻扎在血色修道院墓地的刑讯室，负责审讯在提瑞斯法林地各处抓获的囚犯。他日夜逼取情报、发泄虐待欲，并代表十字军摧毁俘虏的意志，例如沃瑞尔·森加斯。",al={"韦沙斯为什么在墓地","韦沙斯在修道院的职责","韦沙斯在这里做什么"}}},fp="19,348,30.526.0,27.533.1,39.184.0,38.249.0,22.210.0,31.236.0,30.139.0,40.206.0"}
P.entries["npc:islen-waterseer"] = {n="水之先知伊斯伦",s="水之先知伊斯伦是一位受人尊敬的牛头人萨满祭司，她居住在提度斯阶梯的一间安静的渔屋旁，俯瞰着贫瘠之地的东部海域。她与水之灵有着亲密的交流，指导初学者完成与元素沟通所需的试炼。来自部落各地的年轻萨满都会向她寻求智慧，以获得他们的水之图腾。",h="水之先知伊斯伦是一位受人尊敬的牛头人萨满祭司，她居住在提度斯阶梯的一间安静的渔屋旁，俯瞰着贫瘠之地的东部海域。她与水之灵有着亲密的交流，指导初学者完成与元素沟通所需的试炼。来自部落各地的年轻萨满都会向她寻求智慧，以获得他...",kw={"贫瘠之地","call of water","格雷塔·苔蹄","伊斯伦","萨满","提度斯阶梯","water sapta","水之先知"},ang={["class:Shaman"]="伊斯伦是你旅途中的重要导师，她指引你完成与水之灵结合并交流所需的元素仪式，从而获得你的水之图腾。",["faction:Horde"]="伊斯伦驻扎在贫瘠之地的海岸线上，是部落的一个宁静的精神支柱，欢迎来自奥格瑞玛和雷霆崖的旅行者。",["race:Tauren"]="伊斯伦体现了牛头人对大地母亲馈赠的传统敬畏，选择在海边过着隐居生活，以保持与荒野微妙流动的共鸣。"},sec={{t="提度斯阶梯的隐士",b="远离贫瘠之地喧闹的十字路口和营地，水之先知伊斯伦居住在被称为提度斯阶梯的崎岖海岸线上。在这里，干旱的平原在无尽之海的拍打下，水之灵的存在原始而无处不在。伊斯伦不喜欢居住在雷鸣般的大厅或繁华的城市中，她更喜欢这个宁静的前哨站，将她的日子奉献给倾听潮汐的声音，并帮助那些寻求与这种流动元素沟通的萨满。"},{t="水之灵药的主人",b="理解水需要的不仅仅是简单的学习；它需要内心的和谐与灵性的感知。伊斯伦引导寻求者准备水之灵药，这是一种神圣的药剂，可以穿透凡人感官与元素显现之间的帷幕。她的教导提醒萨满，水既是流动和恢复的，也是坚韧和深邃的，任何希望寻求水之帮助的人都必须对其怀有巨大的敬意。"},{t="荒野之中的纽带",b="虽然伊斯伦在海岸过着宁静的生活，但她的精神影响力和联系遍布卡利姆多。她与格雷塔·苔蹄保持着密切而持久的友谊，格雷塔·苔蹄是另一位精通恢复艺术的睿智牛头人。通过这些联系，伊斯伦对水的净化本质的知识触及了贫瘠之地之外的事物，甚至为遭受深度腐蚀的土地提供灵性援助。"}},faq={{q="水之先知伊斯伦是谁？",a="水之先知伊斯伦是一位睿智的牛头人萨满祭司，居住在贫瘠之地提度斯阶梯的海岸边。她与水元素之灵有着罕见且深厚的联系，并担任萨满祭司前往获得水之图腾过程中的精神导师。",al={"水之先知伊斯伦背景故事","伊斯伦是谁","提度斯阶梯牛头人"}},{q="为什么萨满祭司要去找她？",a="在“水之召唤”试炼期间，杜隆塔尔、奥格瑞玛和雷霆崖的训练师会将部落萨满指引至伊斯伦处。她会测试他们对元素的理解，并指导他们制作水之灵药，以便直接感知水元素。",al={"为什么要拜访伊斯伦","水之召唤npc","贫瘠之地海岸萨满任务"}},{q="水之先知伊斯伦在哪里？",a="她坐在提度斯阶梯的一间小渔屋外面，位于贫瘠之地的东部海岸线上，商旅海岸的南边。",al={"伊斯伦位置","水之先知伊斯伦在哪里","找到伊斯伦"}},{q="她提到的水之灵药是什么？",a="水之灵药是一种通过元素组件制作的特殊灵性药剂。饮用它可以使萨满的视力穿透物质位面，见证栖息在神圣泉水和潮汐中的隐藏水之灵。",al={"水之灵药含义","灵药有什么用"}},{q="伊斯伦的朋友格雷塔·苔蹄是谁？",a="格雷塔·苔蹄是一位老友，也是一位从事灵性工艺的同道中人。两人有着持久的友谊，经常就灵性净化和水的恢复本质互相咨询。",al={"格雷塔·苔蹄关系","伊斯伦的朋友"}},{q="伊斯伦属于特定的派系或部落吗？",a="她没有特定的部落。伊斯伦独自生活在海岸边，对部落和联盟的旅行者都很友好，甚至帮助净化费伍德森林中被腐蚀的水域，尽管是部落的萨满训练师派遣他们的兽人、巨魔和牛头人学生前往她那里。",al={"伊斯伦所属阵营","伊斯伦是部落的吗"}}},fx={["6d5841da"]={q="水之先知伊斯伦为什么在这里？",a="伊斯伦居住在无尽之海岸边的提度斯阶梯附近，远离尘嚣，独自过着平静的生活。她在此直接感应潮汐与自然流动，成为部落年轻萨满的精神支柱，帮助他们学会感应难以捉摸的水之灵。",al={"伊斯伦为什么在这里","伊斯伦为什么在海边","水之先知伊斯伦 提度斯阶梯"}}},fp="15,354,25.454.0,27.423.0,22.406.0,23.251.0,33.258.0,33.151.0,38.240.0,37.207.0,49.277.0"}
P.entries["npc:iverron"] = {n="埃沃隆",s="埃沃隆是一位年轻的暗夜精灵，居住在泰达希尔受到庇护的起始树枝——幽影谷中。他被林地里日益狂躁的蛛形生物的毒液所伤，他的困境成为了世界之树内部腐化日益加深的一个早期警示。",h="埃沃隆是一位年轻的暗夜精灵，居住在泰达希尔受到庇护的起始树枝——幽影谷中。他被林地里日益狂躁的蛛形生物的毒液所伤，他的困境成为了世界之树内部腐化日益加深的一个早期警示。",kw={"解毒剂","dentaria","埃沃隆","卡多雷","幽影谷","蜘蛛","泰达希尔","毒液"},ang={["class:Druid"]="在幽影谷修习的德鲁伊将埃沃隆中毒视为自然界遭受深重苦难的一个征兆，这需要利用谷地本身的动植物直接制造出解药。",["profession:Herbalism"]="埃沃隆的存活取决于是否能及时采集到当地幽影谷的植物，这强调了草药知识在维持生命方面至关重要的价值。",["race:NightElf"]="对于初次踏出奥达希尔的新手暗夜精灵来说，埃沃隆的不幸是一个早期教训，让他们了解到泰达希尔的荒野正以何等速度陷入失衡。"},sec={{t="苦涩的叮咬",b="在幽影谷静谧的林冠间漫步时，埃沃隆误入了在谷地筑巢的树林蜘蛛的领地。由于迅速中了它们的剧毒，这位年轻的精灵失去了行动能力，无法独自返回安全地带。他无助的状态凸显出这种曾经与幽影谷和平共处的生物，现在正展现出突然爆发的攻击性。"},{t="孤注一掷",b="埃沃隆的生还寄希望于他的同伴和当地治疗者的敏锐判断，他们需要强效的林地素材——例如风信子蘑菇、月瓣百合和树林蜘蛛的脓液——来调制解毒剂。他在死亡边缘的挣扎，对于幽影谷中所有的年轻卡多雷来说都是一个严酷的提醒：泰达希尔的枝干早已不再是无瑕的避风港。"}},faq={{q="埃沃隆是谁？",a="埃沃隆是一位居住在泰达希尔幽影谷的年轻暗夜精灵。在林地旅行时，他成为了潜伏在树枝间的毒性生物的受害者，需要紧急援助才能生存。",al={"埃沃隆背景故事","埃沃隆是谁","埃沃隆 暗夜精灵"}},{q="埃沃隆是被什么毒伤的？",a="他被栖息在幽影谷丛林中极具攻击性的树林蜘蛛咬伤，遭受了无法通过常规休息来治愈的毒液侵害。",al={"为什么埃沃隆生病了","什么咬了埃沃隆","埃沃隆中毒"}},{q="埃沃隆是如何被治愈的？",a="他通过一种由当地泰达希尔植物（包括风信子蘑菇和月瓣百合）与树林蜘蛛的脓液混合而成的药剂来治疗，从而制成了对症的解毒剂。",al={"治愈埃沃隆","埃沃隆解毒剂","拯救埃沃隆"}},{q="在哪里可以找到埃沃隆？",a="他位于幽影谷，这是泰达希尔树冠上一处隐蔽的起始谷地，新手暗夜精灵们在那里开始他们的训练。",al={"埃沃隆位置","埃沃隆在哪里","找到埃沃隆"}},{q="谁在帮助埃沃隆？",a="埃沃隆派遣冒险者去找他的朋友迪兰妮亚·月光，她会要求他们收集解毒剂的配料，然后在药效流失前赶快送回给他。",al={"谁拯救了埃沃隆","埃沃隆的朋友","dentaria silverglade 埃沃隆"}},{q="为什么幽影谷的蜘蛛如此敌对？",a="幽影谷蜘蛛突然爆发的攻击性是泰达希尔内部蔓延的一种非自然疾病的一部分，这种疾病将本应避世的野兽扭曲成了暴力的掠食者。",al={"为什么蜘蛛会攻击","泰达希尔蜘蛛腐化"}}},fx={["7be6aac6"]={q="埃沃隆效忠于哪一方？",a="埃沃隆是一名普通的暗夜精灵，效忠于自己的族人和联盟。他安稳地生活在泰达希尔幽影谷幽静的枝叶间；遭遇意外时，像亲密朋友迪兰妮亚·月光这样的卡多雷同胞会照料他。",al={"埃沃隆的阵营","埃沃隆是联盟的吗","埃沃隆为谁效力"}},["9c5ce7fc"]={q="埃沃隆想要什么？",a="眼下，埃沃隆只想活下去。他在幽影谷探险时被致命的蜘蛛毒液击倒，如今动弹不得，急需强效解毒剂，否则毒素就会夺去他的性命。",al={"埃沃隆的目标","埃沃隆需要什么","埃沃隆的动机"}},b06694b4={q="埃沃隆为什么在幽影谷？",a="埃沃隆住在幽影谷，这里是泰达希尔一处幽静的新手山谷。他曾进入周围的树林，却遭遇了林地中凶猛的织网蜘蛛。蜘蛛毒液令他不支倒地，如今他身受重伤，躺在森林地面上。",al={"埃沃隆为什么在这里","埃沃隆为何身处幽影谷","埃沃隆出了什么事"}},["61549ef7"]={q="埃沃隆与谁关系密切？",a="埃沃隆与住在幽影谷的迪兰妮亚·月光是好友。他像往常一样没有去看望她，她便请一位路过的冒险者去找他。得知他中毒后，她收集了制作解毒剂的材料来救他的性命。",al={"埃沃隆的人际关系","埃沃隆的朋友是谁","埃沃隆 迪兰妮亚"}}},fp="7,253,13.356.0,18.356.1,15.205.0,22.159.0,21.195.0,27.130.0,23.174.0,45.160.0"}
P.entries["npc:jahan-hawkwing"] = {n="加翰·鹰翼",s="加翰·鹰翼是一位驻扎在贫瘠之地十字路口的牛头人护甲商。他为那些在危机四伏、野兽横行的荒原上冒险的旅行者提供必备的皮革和锁甲装备。",h="加翰·鹰翼是一位驻扎在贫瘠之地十字路口的牛头人护甲商。他为那些在危机四伏、野兽横行的荒原上冒险的旅行者提供必备的皮革和锁甲装备。",kw={"护甲商","一捆兽皮","锁甲","十字路口","加翰·鹰翼","皮甲","牛头人","贫瘠之地"},ang={["faction:Horde"]="加翰驻扎在卡利姆多主要道路的交汇处，确保部落战士和侦察兵全副武装，以抵御半人马的持续袭击和当地野生动物的威胁。",["race:Tauren"]="加翰代表了舒哈鲁人务实、自立的本性，他利用皮革工艺和坚固的材料，为在贫瘠之地的祖先领地上冒险的旅行者提供保护。"},sec={{t="十字路口的护甲商",b="加翰·鹰翼位于繁忙的十字路口枢纽，专门负责满足部落漫游者和守卫者的装备需求。贫瘠之地是一片残酷的旷野，耐用的防护装备往往是能否在半人马、野猪人和野生猛兽的威胁下存活的关键。加翰与当地的制皮匠合作，处理熟化兽皮的交付事宜，以确保他的商店里始终储备着可靠的鞣制皮革和结实的锁甲。"}},faq={{q="加翰·鹰翼是谁？",a="加翰·鹰翼是一位居住在贫瘠之地十字路口的牛头人商人和护甲商。他为过往的冒险者和部落守卫提供皮革和锁甲防护装备。",al={"加翰·鹰翼背景故事","加翰是谁","十字路口护甲商"}},{q="他出售哪些商品？",a="加翰出售成套的基础鞣制皮革和锁甲护甲，包括适合新手战士、猎人和侦察兵穿着的紧身衣、靴子、腰带、护腕和手套。",al={"加翰出售什么","加翰·鹰翼商品列表","加翰护甲"}},{q="他为旅行者提供哪些任务？",a="加翰依赖附近的工匠来供应他的货品。他会请求乐于助人的旅行者运送原材料或加工好的材料，将一捆兽皮送到当地制皮师手中，并等待成品送回。",al={"加翰任务","一捆兽皮任务","十字路口皮革运送"}}},fx={["34a83622"]={q="加翰·鹰翼效忠于哪一方？",a="加翰·鹰翼坚定地站在部落一方，与他的牛头人同胞并肩。他驻守在十字路口，这里是连接卡利姆多中部各处部落领地的重要枢纽，为抵御半人马、野猪人和敌对势力的成员提供必需物资与坚固护甲。",al={"加翰·鹰翼的阵营","加翰·鹰翼是部落的吗","加翰·鹰翼属于联盟还是部落"}},f61d6720={q="加翰·鹰翼为什么在十字路口？",a="加翰·鹰翼在十字路口以经营皮甲和锁甲生意为生。每天都有无数斥候、猎人和旅人经过贫瘠之地这座前哨站，他打造的装备能为他们在严酷荒野中求生提供坚实保障。",al={"加翰·鹰翼为什么在这里","加翰·鹰翼的位置","加翰·鹰翼 十字路口"}}},fp="14,183,25.436.0,22.183.0,24.165.0,38.206.0"}
P.entries["npc:jaina-proudmoore"] = {n="Jaina Proudmoore",s="吉安娜·普罗德摩尔是塞拉摩岛的统治者，也是当今世上最强大的女性人类法师。作为曾经达拉然肯瑞托的明星学员，她带领洛丹伦的幸存者横跨无尽之海，如今致力于在联盟与新部落之间维持脆弱的和平。",h="吉安娜·普罗德摩尔是塞拉摩岛的统治者，也是当今世上最强大的女性人类法师。作为曾经达拉然肯瑞托的明星学员，她带领洛丹伦的幸存者横跨无尽之海，如今致力于在联盟与新部落之间维持脆弱的和平。",kw={"安东尼达斯","阿尔萨斯","尘泥沼泽","吉安娜","肯瑞托","普罗德摩尔","塞拉摩","萨尔"},ang={["class:Mage"]="吉安娜·普罗德摩尔曾亲自师从大法师安东尼达斯，被公认为是当今世上最强大的女性人类法师，代表了达拉然奥术造诣的巅峰。",["faction:Alliance"]="吉安娜为联盟提供了在卡利姆多南部的关键据点，她在效忠暴风城伯瓦尔公爵摄政王与避免与邻近的部落开战的意愿之间寻求平衡。"},sec={{t="前往卡利姆多",b="作为库尔提拉斯的海军上将戴林·普罗德摩尔的女儿，吉安娜在很小的时候就展现出了卓越的奥术天赋，并师从达拉然的大法师安东尼达斯。在第三次战争期间，她与阿尔萨斯·米奈希尔王子一同调查神秘的亡灵瘟疫，亲眼目睹了洛丹伦悲剧性的陷落。在先知麦迪文的警告引导下，她召集了一支人类幸存者远征队，向西航行至被遗忘的卡利姆多大陆。在那里，她的部队与萨尔领导的部落以及暗夜精灵结成了前所未有的联盟，共同屹立在海加尔山之巅，击败了阿克蒙德，粉碎了燃烧军团的入侵。"},{t="塞拉摩的女主人",b="在军团战败后，吉安娜在尘泥沼泽海岸外建立了塞拉摩岛要塞，确立了联盟在卡利姆多南部的核心据点。当她的父亲为了向兽人复仇而率军抵达时，她对外交的承诺经受了极大的考验；吉安娜拒绝支持他的战争，并眼看着萨尔的军队击杀了海军上将，以防止卡利姆多陷入另一场毁灭性的冲突。今天，她作为共存政策的坚定拥护者统治着塞拉摩，与萨尔大酋长紧密合作，同时在当地日益紧张的局势下稳固联盟的存在。"}},faq={{q="吉安娜·普罗德摩尔是谁？",a="吉安娜是塞拉摩岛的统治者，也是当今世上天赋最高的人类法师。她是库尔提拉斯已故海军上将戴林·普罗德摩尔的女儿，也是达拉然大法师安东尼达斯的昔日学徒。",al={"吉安娜是谁","吉安娜·普罗德摩尔背景","塞拉摩领袖"}},{q="为什么吉安娜在卡利姆多，而不是东部王国？",a="在第三次战争中洛丹伦陷落之前，先知麦迪文曾警告吉安娜，要尽可能多地带领人民横跨海洋前往卡利姆多。她的远征队在旅途中幸存下来，在海加尔山并肩作战，最终在尘泥沼泽定居，建立了港口要塞塞拉摩。",al={"为什么吉安娜离开洛丹伦","吉安娜卡利姆多","为什么塞拉摩在这里"}},{q="吉安娜与部落的关系如何？",a="吉安娜与萨尔大酋长之间维持着一种非同寻常且谨慎的友谊。在海加尔山共同对抗燃烧军团之后，两位领袖都在努力维持双方人民之间的和平，尽管双方的强硬派都对此表示强烈反对。",al={"吉安娜和萨尔友好吗","吉安娜和部落","吉安娜讨厌兽人吗"}},{q="吉安娜和阿尔萨斯·米奈希尔王子之间发生了什么？",a="吉安娜和阿尔萨斯曾是关系亲密的恋人。他们共同调查了席卷洛丹伦的瘟疫，但吉安娜对阿尔萨斯变得冷酷无情感到震惊——这一切在斯坦索姆的清洗中达到顶峰，当时吉安娜拒绝参与屠杀那些受感染的平民。",al={"吉安娜和阿尔萨斯","吉安娜爱过阿尔萨斯吗"}}},fp="16,283,18.679.0,21.631.0,29.218.0,57.265.0,44.259.0,55.303.0"}
P.entries["npc:james-halloran"] = {n="詹姆斯·哈洛兰",s="詹姆斯·哈洛兰是一位在湿地工作的人类制皮匠，他为东部大陆各地供应优质毛皮。他以米奈希尔港为基地，靠剥取该地区原生鳄鱼坚韧而珍贵的皮来谋生。他依赖过往的旅行者和附近的贸易渠道来收集原材料，并将成品皮革运往市场。",h="詹姆斯·哈洛兰是一位在湿地工作的人类制皮匠，他为东部大陆各地供应优质毛皮。他以米奈希尔港为基地，靠剥取该地区原生鳄鱼坚韧而珍贵的皮来谋生。他依赖过往的旅行者和附近的贸易渠道来收集原材料，并将成品皮革运往市场。",kw={"鳄鱼","哈洛兰","詹姆斯·哈洛兰","制皮","米奈希尔港","制皮匠","湿地"},ang={["class:Hunter"]="穿行在潮湿沼泽中的猎人们会与哈洛兰有共同语言，因为哈洛兰的生计全靠追踪和猎取湿地中那些极具侵略性的爬行动物捕食者。",["faction:Alliance"]="哈洛兰的贸易有助于维持联盟在崎岖湿地的商业存在，为王国各地的城镇提供宝贵的精制皮革。"},sec={{t="沼泽里的制皮匠",b="詹姆斯·哈洛兰以米奈希尔港为家，依靠城镇外的沼泽谋生。作为一名颇具进取心的制皮匠，哈洛兰意识到这些危险的沼泽蕴藏着一种有利可图的商品：鳄鱼皮。将沼泽爬行动物粗糙的皮转化为高质量的皮革需要稀有的手艺，哈洛兰的成品通过当地的贸易渠道运往艾泽拉斯各地的买家手中。"},{t="毛皮、学徒与日常贸易",b="在靠近沼泽的地方作业总是伴随着持续的危险。哈洛兰无法在照看鞣制缸和处理贸易物流的同时轻松地亲自猎杀每一只野兽。他经常雇佣勇敢的旅行者来处理剥下年轻沼泽野兽的皮这一类粗活，并管理他的工作地点与周边定居点之间的日常运送，以确保他忙碌的制皮生意能有充足的供应。"}},faq={{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是一位在湿地米奈希尔港工作的人类制皮匠。他专门猎杀和剥取该地区本土鳄鱼的皮，将它们坚韧的皮鞣制成销往世界各地的皮革制品。",al={"詹姆斯·哈洛兰","哈洛兰","哈洛兰是谁","湿地制皮匠"}},{q="詹姆斯·哈洛兰在哪里出售他的皮革？",a="哈洛兰将鳄鱼原皮加工成优质皮革，并运往整个艾泽拉斯。他非常依赖途经米奈希尔港的海运贸易，将他的商品分销到海外。",al={"哈洛兰皮革贸易","鳄鱼皮销往何处","哈洛兰的生意"}},{q="为什么哈洛兰需要冒险者去收集幼年鳄鱼皮？",a="鞣制皮革是一项耗时且费力的工作。哈洛兰雇佣旅行冒险者来捕杀当地的沼泽鳄鱼并剥下它们的皮，这样他无需离开工坊就能获得稳定的原材料供应。",al={"为什么要猎杀幼年鳄鱼","幼年鳄鱼皮任务","哈洛兰的鳄鱼皮"}},{q="哈洛兰与米奈希尔港有什么关系？",a="米奈希尔港是该地区主要的贸易和供应枢纽。哈洛兰依赖该港口及其航运路线，将他鞣制好的毛皮出口到遥远的市场，以维持他的制皮生意。",al={"哈洛兰 米奈希尔","哈洛兰的港口联系","哈洛兰住在米奈希尔吗"}},{q="在哪里可以找到詹姆斯·哈洛兰？",a="哈洛兰在米奈希尔港生活和工作，这是位于湿地西海岸的繁忙港口，鳄鱼沼泽就在城镇外面。",al={"哈洛兰的位置","詹姆斯·哈洛兰在哪里","寻找哈洛兰"}},{q="哈洛兰有学徒吗？",a="有。哈洛兰曾派他视如己出的学徒进入沼泽去剥取巨型鳄鱼的皮，但这名年轻人遭到了野兽袭击，失去了一条腿。在学徒康复期间，哈洛兰依靠勇敢的旅行者来收集他生意所需的皮。",al={"哈洛兰的学徒","哈洛兰的学徒职责","谁为哈洛兰工作"}}},fx={["21c95e2f"]={q="詹姆斯·哈洛兰效忠于哪一方？",a="詹姆斯·哈洛兰与联盟结盟。他是一名在湿地工作的人类工匠，与港口城镇米奈希尔港保持联系，向联盟各地供应货物。",al={"哈洛兰是联盟的吗","詹姆斯·哈洛兰的阵营","哈洛兰为谁效力"}},b76d5522={q="詹姆斯·哈洛兰为什么在湿地？",a="哈洛兰以制革和设陷阱为生。湿地的沼泽与水道中遍布鳄鱼，为他提供稳定的皮革来源；他将皮革鞣制后销往各地。",al={"哈洛兰为什么在湿地","詹姆斯·哈洛兰的职责","哈洛兰为什么在这里"}}},fp="14,354,23.426.0,35.394.0,22.229.0,43.205.0,68.243.0,49.210.0,34.143.0,33.260.0"}
P.entries["npc:jannok-breezesong"] = {n="詹诺克·柔歌",s="詹诺克·柔歌是驻扎在泰达希尔多兰纳尔村的一名暗夜精灵潜行者训练师。他为前往世界之树枝桠冒险的年轻卡多雷潜行者提供潜行、狡诈和刃术方面的指导。",h="詹诺克·柔歌是驻扎在泰达希尔多兰纳尔村的一名暗夜精灵潜行者训练师。他为前往世界之树枝桠冒险的年轻卡多雷潜行者提供潜行、狡诈和刃术方面的指导。",kw={"柔歌","多兰纳尔","埃里昂·影语","詹诺克","暗夜精灵","潜行者训练师","泰达希尔"},ang={["class:Rogue"]="对于在泰达希尔开始冒险的年轻暗夜精灵潜行者来说，詹诺克是你前往主城之前在多兰纳尔的关键导师。",["race:NightElf"]="尽管卡多雷文化通常强调哨兵和德鲁伊之道，但像詹诺克这样的训练师为那些偏好潜行、毒药和匕首的人做好准备。"},sec={{t="阴影中的向导",b="詹诺克·柔歌常在多兰纳尔的树荫下休息，他是暗夜精灵新手潜行者的主要导师。与泰达希尔那些纪律严明的哨兵或隐居的德鲁伊不同，詹诺克指引着那些在社会边缘悄然行动的人，教导他们如何潜行于阴影之中、如何从背后发起突袭，以及如何在树枝间隐秘地生存。当潜行者在多兰纳尔完成初步课程后，詹诺克会指引他们前往达纳苏斯，向那里的资深大师寻求进一步的教导。"}},faq={{q="詹诺克·柔歌是谁？",a="詹诺克·柔歌是居住在泰达希尔多兰纳尔的一名暗夜精灵潜行者训练师。他向年轻的卡多雷传授潜行者的基础能力和技巧。",al={"詹诺克是谁","詹诺克·柔歌的角色","多兰纳尔潜行者训练师"}},{q="詹诺克会将进阶的潜行者指引到哪里？",a="当潜行者在多兰纳尔完成初步训练后，詹诺克会指引他们前往达纳苏斯，向位于城中塞纳里奥区的资深潜行者训练师埃里昂·影语寻求进一步的指导。",al={"詹诺克任务","埃里昂·影语任务","多兰纳尔潜行者下一步"}},{q="我在多兰纳尔哪里可以找到詹诺克？",a="詹诺克位于泰达希尔幽影谷外的主要定居点多兰纳尔，就在镇上的训练师凉亭中。",al={"詹诺克位置","詹诺克在哪里","寻找詹诺克·柔歌"}}},fx={f606b9db={q="詹诺克·柔歌效忠于哪一方？",a="詹诺克为达纳苏斯和联盟效力。他是一名驻扎在多兰纳尔村庄的暗夜精灵盗贼训练师，效忠于卡多雷族群和泰达希尔的防卫。",al={"詹诺克·柔歌的阵营","詹诺克为谁效力","詹诺克的效忠对象"}},b07dd258={q="詹诺克·柔歌为什么在这里？",a="詹诺克驻扎在多兰纳尔，训练从幽影谷前来的暗夜精灵新手盗贼。他传授潜行与机敏之道，最终会引导有前途的斥候前往达纳苏斯，拜访埃利恩·影语者等导师。",al={"詹诺克为什么在多兰纳尔","詹诺克·柔歌的职责","詹诺克为什么在这里"}}},fp="17,230,22.506.0,25.156.0,40.221.0,36.137.0"}
P.entries["npc:jasper-fel"] = {n="贾斯伯·菲尔",s="贾斯伯·菲尔是一名在暴风城Old Town的SI:7总部内经营的谨慎供应商。他为特工提供匕首和各种药瓶，时刻警惕着来访者，并告诫他们谨言慎行。他这种秘密交易在暗处支持着王国的隐秘部门。",h="贾斯伯·菲尔是一名在暴风城Old Town的SI:7总部内经营的谨慎供应商。他为特工提供匕首和各种药瓶，时刻警惕着来访者，并告诫他们谨言慎行。他这种秘密交易在暗处支持着王国的隐秘部门。",kw={"匕首","贾斯伯·菲尔","morbent fel","old town","潜行者补给","si:7","暴风城","药瓶"},ang={["class:Rogue"]="贾斯伯·菲尔提供在暴风城执行任务的隐秘特工所必需的药瓶和备用刀刃。",["faction:Alliance"]="菲尔在SI:7总部服务，确保那些在暗影中保卫王国的特工拥有可靠的补给。"},sec={{t="暗影补给",b="贾斯伯·菲尔躲在Old Town内的SI:7营地中，专门服务于特定的客户群体。他并不向城市卫兵兜售制式武器，而是提供执行任务的核心工具：简单的匕首以及配置和涂抹毒药所需的精细药瓶。菲尔在Mathias Shaw的情报部门的严格纪律下运作，冷漠地告诫所有接近的人要注意言辞。在这个专门从事间谍活动和隐秘杀戮的据点里，随意的闲聊很容易让你过早地送命。"}},faq={{q="我在哪里可以找到贾斯伯·菲尔？",a="贾斯伯·菲尔驻扎在SI:7总部内，位于暴风城的Old Town东部。",al={"贾斯伯·菲尔位置","贾斯伯·菲尔在哪里","贾斯伯·菲尔 暴风城"}},{q="贾斯伯·菲尔卖什么？",a="他提供基础匕首和各种等级的空药瓶，这使他成为特工们储备毒药组件时的重要补给点。",al={"贾斯伯·菲尔商人","菲尔卖什么","贾斯伯·菲尔商品"}},{q="贾斯伯·菲尔和Morbent Fel有关系吗？",a="他们拥有相同的姓氏，这引起了人们对他与暮色森林的亡灵法师Morbent Fel之间存在家族联系的猜测，尽管贾斯伯本人对个人私事保持沉默。",al={"贾斯伯·菲尔 morbent fel","贾斯伯·菲尔与morbent的关系","菲尔家族 暮色森林"}},{q="为什么贾斯伯·菲尔警告人们小声说话？",a="他直接在暴风城间谍机构的核心——SI:7内部工作。在一个充满刺客和间谍的组织中，随意的谈话被认为是危险的，菲尔确保来访者对总部保持适当的谨慎。",al={"为什么小声说话","贾斯伯·菲尔警告","祸从口出"}}},fp="10,150,24.329.0,28.97.0,26.84.0,37.95.0,49.143.0"}
P.entries["npc:je-neu-sancrea"] = {n="耶努萨克雷",s="耶努萨克雷是一位暗矛巨魔，也是大地之环的成员，驻扎在灰谷海岸的佐拉姆加前哨站。他感应到海岸深处涌动着黑暗力量，因此指引部落的冒险者去调查盘踞在古老沉没神庙——黑暗深渊中的腐化。",h="耶努萨克雷是一位暗矛巨魔，也是大地之环的成员，驻扎在灰谷海岸的佐拉姆加前哨站。他感应到海岸深处涌动着黑暗力量，因此指引部落的冒险者去调查盘踞在古老沉没神庙——黑暗深渊中的腐化。",kw={"阿库麦尔","黑暗深渊","大地之环","耶努萨克雷","耶努","暮光之锤","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Shaman"]="作为大地之环中杰出的暗矛巨魔成员，耶努代表了萨满的职责，即净化被腐化的元素并恢复卡利姆多水域的平衡。",["faction:Horde"]="耶努是部落玩家在灰谷进入黑暗深渊副本时的主要任务发布者和背景向导。",["race:Troll"]="耶努展示了暗矛巨魔是如何与牛头人和兽人盟友一起，共同拥抱大地之环的灵性道路的。"},sec={{t="海滩上的萨满",b="虽然大多数大地之环的成员致力于维护整个卡利姆多的元素和谐，但耶努萨克雷却一直监视着偏僻而危险的佐拉姆海岸。他驻守在佐拉姆加前哨站，观察着黑暗深渊那座废弃神庙附近出现的黑暗震颤和反常潮汐。尽管受限于大地之环的萨满职责，但他对暗矛巨魔部族和萨尔所领导的部落的忠诚，使他只与部落的勇士们并肩作战。"},{t="深渊之影",b="耶努试图揭开海岸周围蔓延的腐化背后的真正原因。他派遣勇敢的冒险者收集被污染的蓝宝石核心，调查阿奎尼斯男爵这类水元素留下的邪恶残余，并揭露暮光之锤教派的阴险勾当。发生在波涛之下的黑暗仪式不仅威胁着当地元素的平衡，也预示着那些效忠于上古之神的势力即将卷土重来。"}},faq={{q="耶努萨克雷是谁？",a="耶努萨克雷是一位隶属于大地之环的暗矛巨魔萨满。他驻扎在灰谷海岸的佐拉姆加前哨站，负责监视从黑暗深渊中蔓延开来的日益严重的腐化。",al={"耶努是谁","耶努萨克雷背景故事","耶努是什么"}},{q="耶努身为大地之环成员，为什么只接待部落冒险者？",a="虽然大地之环作为一个组织致力于寻求元素平衡而非阵营战争，但耶努个人的情感纽带依然紧系于暗矛巨魔部族和部落。由于他居住在灰谷的一个部落前线军事哨所内，因此他不欢迎联盟的旅行者。",al={"为什么只对部落开放","联盟可以和耶努对话吗","耶努是中立的吗"}},{q="耶努在黑暗深渊中调查什么？",a="耶努正在调查源自黑暗深渊的非自然元素动荡和黑暗魔法。他委派勇士们去回收被腐化的水核，消灭暮光之锤教派的成员，并证实有关古老九头蛇阿库麦尔正效忠于海底邪恶古老主宰的传言。",al={"耶努的任务目标","耶努想要什么","为什么派玩家去黑暗深渊"}},{q="耶努萨克雷在哪里？",a="耶努位于佐拉姆加前哨站，这是一个坚固的部落定居点，位于灰谷最西北部的海岸，就在黑暗深渊南侧的佐拉姆海岸边。",al={"耶努在哪里","耶努萨克雷位置","寻找耶努"}},{q="什么是大地之环？",a="大地之环是一个古老的萨满组织，致力于理解并安抚世间的元素之灵，每当有黑暗力量或混乱实体扰乱自然的元素和谐时，他们便会进行干预。",al={"大地之环背景","什么是大地之环","萨满组织"}},{q="暮光之锤在深渊中构成了什么威胁？",a="暮光之锤教派已经渗透进黑暗深渊，崇拜着野兽阿库麦尔，并进行献给上古之神的仪式。耶努派遣部落冒险者去铲除他们的首领，以阻止其黑暗行径。",al={"黑暗深渊的暮光之锤","灰谷的暮光教派","黑暗深渊里的邪教徒是谁"}}},fx={["1670a3c0"]={q="耶努萨克雷为什么在这里？",a="耶努驻扎在灰谷海岸的佐拉姆加前哨站，观察黑暗深渊附近废墟中涌动的邪恶腐化。大地之环察觉到水域自然平衡遭受了污秽的扰动，因此派他来到这片边境，监视聚集的教徒，并招募经验丰富的部落勇士深入海底搜查。",al={"耶努为何在灰谷","耶努萨克雷为何在佐拉姆加","是什么让耶努萨克雷来到这里"}}},fp="14,300,22.452.0,19.449.1,22.215.0,71.296.0,50.299.0,32.174.0,25.212.0,57.225.0"}
P.entries["npc:jen-shan"] = {n="基沙",s="基沙是一名暗矛巨魔，也是驻扎在杜隆塔尔试炼谷的猎人训练师。她引导兽人和巨魔新手神射手们迈出加入部落荒野征程的第一步。年轻的猎人会被指引到她这里，学习追踪、远程战斗和生存的基础知识。",h="基沙是一名暗矛巨魔，也是驻扎在杜隆塔尔试炼谷的猎人训练师。她引导兽人和巨魔新手神射手们迈出加入部落荒野征程的第一步。年轻的猎人会被指引到她这里，学习追踪、远程战斗和生存的基础知识。",kw={"暗矛","杜隆塔尔","风蚀羊皮纸","刻写的石板","猎人训练师","基沙","巨魔","试炼谷"},ang={["class:Hunter"]="对于年轻的兽人和巨魔猎人来说，基沙是你遇到的第一位导师，她在你走出大兽穴的红色峡谷之前，教授你基础的远程技巧。",["race:Troll"]="基沙代表了暗矛巨魔在追踪和侦察方面享誉盛名的能力，确保年轻的巨魔在这个新的大陆家园中能够继承他们祖先的狩猎传统。"},sec={{t="红沙导师",b="Perched among the weathered encampments of the Valley of Trials, Jen'shan serves as the primary hunter mentor for new recruits proving their worth to the Horde. Together, young orcs and Darkspear trolls arrive clutching inscribed tablets and parchments directing them straight to her side. With keen eyes sharpened by years in the untamed wilderness, she imparts foundational techniques in archery, marksmanship, and wilderness survival, ensuring no novice falls prey to the scorpids and boars prowling the canyon floor."}},faq={{q="基沙是谁？",a="基沙是一位暗矛巨魔猎人训练师，位于杜隆塔尔的试炼谷。她指导部落的新手猎人学习基本的野外知识、追踪和远程武器的使用。",al={"基沙背景故事","基沙是谁","试炼谷猎人训练师"}},{q="哪些任务与基沙有关？",a="新手猎人会通过入门训练任务被派往她那里。年轻的兽人猎人通过上交Etched Tablet被指引到她身边，而年轻的巨魔猎人则携带风蚀羊皮纸来寻找她。",al={"基沙任务","刻写的石板 基沙","风蚀羊皮纸 基沙"}},{q="为什么会有巨魔在兽人的试炼场训练猎人？",a="试炼谷是兽人新兵和流离失所、共享杜隆塔尔的暗矛巨魔共同的试炼场。作为侦察和潜行大师，像基沙这样的巨魔在为部落培养两族的新战士和猎人方面发挥着至关重要的作用。",al={"为什么试炼谷会有巨魔","杜隆塔尔的巨魔训练师"}}},fx={["9968b478"]={q="基沙效忠于哪一方？",a="基沙效忠于部落和她的族人——暗矛部族。她驻扎在试炼谷，与兽人并肩工作，确保新兵无论是巨魔还是兽人，都能为在杜隆塔尔的严酷环境中生存、为大酋长而战做好准备。",al={"基沙 阵营","基沙是部落的吗","基沙 忠诚"}},f50adc74={q="基沙想要什么？",a="基沙希望训练初出茅庐的猎人掌握射击技巧、生存之道，以及在荒野中坚持下去所需的本能。她希望有潜力的年轻斥候尽快磨炼技艺，以便应对徘徊在赤红荒原上的凶猛野兽，并保护初生的部落免受敌人侵害。",al={"基沙 动机","基沙 目标","基沙需要什么"}},ece1555d={q="基沙与谁有关联？",a="基沙属于由森金之子沃金领导的暗矛巨魔。暗矛巨魔与萨尔的兽人共同居于杜隆塔尔，因此她与试炼谷的训练师密切合作，引导两个种族的新兵加入部落。",al={"基沙 关系","基沙与暗矛的关系","基沙为谁效力"}}},fp="8,301,23.520.0,16.198.0,29.199.0,57.280.0"}
P.entries["npc:jennea-cannon"] = {n="詹妮亚·坎农",s="詹妮亚·坎农是一位受人尊敬的人类法师训练师，居住在暴风城法师区的密室中。她负责监督初级施法者的教育，引导他们完成基础学习，并调查当地奥术能量流的异常情况。通过她的任务，她会测试学徒是否具备控制魔法所需的纪律性，以免被魔法吞噬。",h="詹妮亚·坎农是一位受人尊敬的人类法师训练师，居住在暴风城法师区的密室中。她负责监督初级施法者的教育，引导他们完成基础学习，并调查当地奥术能量流的异常情况。通过她的任务，她会测试学徒是否具备控制魔法所需的纪律性，以免被魔法...",kw={"安多玛斯","蓝隐士","詹妮亚·坎农","mage quarter","法师训练师","明镜湖","暴风城","密室"},ang={["class:Mage"]="詹妮亚是联盟法师重要的早期导师，她会指导你的第一次实地调查，并引导你制作正式的法师长袍和法杖。",["faction:Alliance"]="詹妮亚在暴风城法师区的核心区域工作，确保王国的新晋施法者们训练有素，并能安全地为联盟服务。"},sec={{t="密室中的导师",b="詹妮亚·坎农站在密室螺旋走廊的顶端，是进入暴风城的奥术修行者们的主要导师之一。她不仅是向学生灌输法术，更强调谨慎和自我控制。对于路过法师塔的非施法者，她会给予尖锐的警告：未经训练的魔法会灼伤使用者，这是初级施法者在她的指导下很快就会学到的真理。"},{t="实地考察与基础",b="詹妮亚认为魔法理论必须通过现实世界的观察来检验。她经常派遣有前途的学徒走出城墙，让他们去考察艾尔文森林的明镜湖等地，以了解天然水源如何与奥术共鸣相互作用。随着学生们的进步，她会指引他们调查“蓝隐士”旅店的异常情况，或是收集用于制作第一件真正法师装备的各种挥发性试剂，以此考验他们的决心。"},{t="与高阶导师的联系",b="虽然詹妮亚负责早期的教学和本地事务，但她知道何时学生已经超出了她的教学范畴。一旦学徒展现出真正的潜力，她就会引导他们向密室更高层级的安多玛斯大法师寻求指点，甚至会指引他们前往王国边境之外，去寻找隐居的修行者，比如尘泥沼泽深处的塔贝萨。"}},faq={{q="詹妮亚·坎农是谁？",a="她是一位驻扎在暴风城法师区密室中的人类法师训练师，负责指导新晋法师并负责早期的魔法研究。",al={"詹妮亚·坎农","詹妮亚是谁","暴风城法师训练师"}},{q="我在哪里可以找到詹妮亚·坎农？",a="她位于密室中，那是一座螺旋形的奥术塔，坐落于暴风城法师区的中心。",al={"詹妮亚·坎农位置","詹妮亚在哪里","寻找詹妮亚"}},{q="詹妮亚·坎农提供哪些任务？",a="她为联盟法师提供职业任务，包括调查艾尔文森林的明镜湖，查明蓝隐士旅店发生的奇怪事件，以及收集材料来制作初级法师装备。",al={"詹妮亚的任务","詹妮亚·坎农任务线"}},{q="她为什么派法师去明镜湖？",a="她派遣学徒前往艾尔文森林的明镜湖，在瀑布底部取样，以便她进行魔法污染检测。她担心暴风城和艾尔文森林周围魔法流的改变可能正在渗入水源。",al={"为什么去明镜湖","詹妮亚的明镜湖任务"}},{q="詹妮亚·坎农会与非施法者职业互动吗？",a="非施法者可以与她交谈，但她只会提出一个严厉的建议，即在魔法面前要保持谨慎，并警告魔法会灼伤那些缺乏适当训练的人。",al={"非施法者可以和詹妮亚对话吗","詹妮亚对其他职业的态度"}},{q="詹妮亚·坎农向谁汇报？",a="她在密室的层级体系中工作，引导学生直到他们准备好在安多玛斯大法师等高阶人物手下学习。",al={"詹妮亚的上级","密室领导者"}}},fp="13,214,22.306.0,24.331.0,23.277.0,21.120.0,31.120.0,37.195.0,39.205.0,50.123.0,33.133.0"}
P.entries["npc:jergosh-the-invoker"] = {n="祈求者耶戈什",s="祈求者耶戈什是一位奸诈的兽人术士，藏身于奥格瑞玛地下的怒焰裂谷深处。作为灼热之刃邪教徒中的一名高阶头目，他在大酋长的眼皮底下修习恶魔技艺，并密谋对抗部落。",h="祈求者耶戈什是一位奸诈的兽人术士，藏身于奥格瑞玛地下的怒焰裂谷深处。作为灼热之刃邪教徒中的一名高阶头目，他在大酋长的眼皮底下修习恶魔技艺，并密谋对抗部落。",kw={"祈求者","耶戈什","奥格瑞玛","怒焰裂谷","灼热之刃","暗影议会","术士"},ang={["class:Warlock"]="对于术士来说，耶戈什是一位强大的恶魔技艺修行者，他的阴谋威胁着部落。",["faction:Horde"]="在大酋长的王座大厅下方有一个暗影议会的分支机构在蓬勃发展，这是一个部落无法忽视的、令人无法容忍的安全威胁。",["race:Orc"]="耶戈什代表了旧部落挥之不去的毒素——萨尔努力从兽人文化中清除的恶魔之血和魔法的诱惑。"},sec={{t="城下的邪教",b="虽然萨尔不懈努力，带领兽人们走上一条荣耀与萨满之道的道路，但耶戈什却摒弃了这些理想，转而追求原始的恶魔力量。他躲藏在奥格瑞玛地下的怒焰裂谷迷宫中，将追随者聚集在灼热之刃麾下。这是一个与暗影议会残党结盟的阴险教派。耶戈什在部落首都正下方的阴影中运作，试图瓦解新部落所代表的一切。"},{t="恶魔般的野心",b="耶戈什在裂谷中的存在绝非漫无目的的游荡。他的黑暗仪式和危险阴谋最终变得十分猖獗，以至于引起了萨尔本人的直接关注。耶戈什代表了杜隆塔尔内部的一种生存性感染，提醒着部落他们曾拼命想要抛弃的那些黑暗契约。"}},faq={{q="谁是祈求者耶戈什？",a="祈求者耶戈什是一位强大的兽人术士，也是在怒焰裂谷中活动的灼热之刃邪教徒的领袖。他没有追随萨尔的荣耀之路，而是选择了拥抱恶魔魔法。",al={"谁是耶戈什","耶戈什背景故事","耶戈什怒焰裂谷"}},{q="为什么耶戈什要藏在怒焰裂谷里？",a="怒焰裂谷为灼热之刃提供了一个位于奥格瑞玛正下方的隐秘火岩洞穴网络。在那里，耶戈什和他的邪教徒可以修习禁忌的黑暗魔法，并密谋对抗部落而不被察觉。",al={"为什么耶戈什在奥格瑞玛下方","耶戈什所在地背景"}},{q="耶戈什属于哪个阵营？",a="耶戈什是灼热之刃的领袖之一，这是一个与暗影议会有关联，并致力于服务燃烧军团等恶魔利益的邪教组织。",al={"耶戈什阵营","耶戈什是暗影议会的吗","灼热之刃领袖"}},{q="萨尔知道耶戈什就在奥格瑞玛下面吗？",a="是的。耶戈什的阴谋变得十分危险，谣言传到了萨尔耳中，导致这位大酋长派遣值得信赖的冒险者进入裂谷，以消除这个邪教威胁。",al={"萨尔与耶戈什","萨尔知道怒焰裂谷吗"}},{q="为什么耶戈什修习邪能魔法而不是萨满之道？",a="耶戈什自愿背弃了他族人的精神复兴，拒绝了萨满之道的和谐，转而去追逐燃烧军团和黑暗技艺所承诺的令人陶醉的力量。",al={"为什么是术士","耶戈什邪能魔法"}}},fx={["3ff8bf73"]={q="祈求者耶戈什想要什么？",a="耶戈什企图从部落首都内部瓦解部落。他拒绝了萨尔复兴萨满传统的理想，妄图重拾黑暗的恶魔法术，推进暗影议会的邪恶野心。他潜伏在深渊中策划颠覆阴谋，其危险程度足以威胁奥格瑞玛本身的稳定。",al={"耶戈什的目标","耶戈什想要什么","耶戈什 动机"}},["752417a2"]={q="祈求者耶戈什与谁有关联？",a="耶戈什是火刃教徒中的重要领袖。这个地下教团就活动在奥格瑞玛正下方，实际上是更广泛的暗影议会的一支，使耶戈什直接与那些企图让兽人重陷腐化的神秘术士和恶魔崇拜者网络相连。",al={"耶戈什的盟友","耶戈什为谁效力","耶戈什 暗影议会"}},baae249b={q="祈求者耶戈什为何令人畏惧？",a="耶戈什令人畏惧，因为他就在部落领袖脚下施展被禁的邪能魔法。他的黑暗仪式、恶魔召唤，以及对新部落道路的激进反对，构成了威胁生存的内部危机，连大酋长萨尔本人也直接关注并为之担忧。",al={"耶戈什为何令人畏惧","耶戈什危险吗","耶戈什 名声"}}},fp="19,250,23.465.0,17.321.1,27.205.0,40.224.0,36.147.0,46.171.0,57.184.0"}
P.entries["npc:jern-hornhelm"] = {n="吉恩·角盔",s="吉恩·角盔是一位隶属于探险者协会的矮人矿工，驻扎在塞尔萨玛镇。他负责协调该定居点、铁炉堡以及洛克莫丹深处考古挖掘场之间的重要物流和通信工作。冒险者们经常协助他运送采矿补给和进度报告，往返于该区域各地。",h="吉恩·角盔是一位隶属于探险者协会的矮人矿工，驻扎在塞尔萨玛镇。他负责协调该定居点、铁炉堡以及洛克莫丹深处考古挖掘场之间的重要物流和通信工作。冒险者们经常协助他运送采矿补给和进度报告，往返于该区域各地。",kw={"爆破粉","挖掘","探险者协会","基恩萨·铁环","吉恩·角盔","洛克莫丹","矿工","塞尔萨玛"},ang={["faction:Alliance"]="路过洛克莫丹的联盟旅行者会发现吉恩是保障该区域安全和维护矮人基础设施的重要联络点。",["profession:Mining"]="矿工们会欣赏吉恩的贸易背景，以及他在地下物流、爆破和资源运输方面的实际经验。",["race:Dwarf"]="对于矮人来说，协助吉恩能直接推进发掘埋藏在群山深处、属于泰坦的先祖遗产这一神圣使命。"},sec={{t="塞尔萨玛的后勤工作",b="吉恩·角盔驻扎在朴素的塞尔萨玛镇，在整个洛克莫丹的矮人行动中扮演着关键的后勤角色。当矮人学者和外勤小组深入荒野发掘他们的先祖历史时，维持稳定的供应链至关重要。吉恩确保重要的资源、工具和通信能够安全送达至活跃的挖掘场。"},{t="为探险者协会服务",b="作为探险者协会的一员，吉恩架起了外勤考古学家与位于铁炉堡探险者大厅的协会领导层之间的桥梁。像基恩萨·铁环的挖掘场这样地点，非常依赖爆破粉、装备和定期的派遣任务来维持进度。吉恩招募可靠的旅行者穿过布满穴居人的道路，以保证挖掘工作顺利进行。"}},faq={{q="吉恩·角盔是谁？",a="吉恩·角盔是驻扎在洛克莫丹塞尔萨玛的一位矮人矿工兼后勤协调员。他代表探险者协会工作，以保持当地挖掘工作的顺利进行。",al={"吉恩是谁","吉恩·角盔的身份","塞尔萨玛矮人吉恩"}},{q="我可以在哪里找到吉恩·角盔？",a="他位于洛克莫丹中心地带，站在塞尔萨玛镇主干道旁边的户外。",al={"吉恩·角盔的位置","吉恩在哪里","吉恩·角盔地图"}},{q="吉恩·角盔属于哪个阵营？",a="吉恩隶属于联盟，并专门代表矮人的探险者协会，负责管理人员和采矿物资的调度。",al={"吉恩·角盔所属阵营","吉恩为谁工作","吉恩是探险者协会的吗"}},{q="为什么吉恩需要将爆破粉送到挖掘场？",a="在多山地形进行的考古挖掘需要通过受控爆破来炸开坚硬的岩壁。吉恩负责协调将特制的爆破粉运送到勘察员基恩萨·铁环的挖掘场，以便团队能够挖掘湖泊东侧的古代遗迹。",al={"关于铁环的爆破粉知识","为什么挖掘场需要爆破粉","洛克莫丹的爆破粉"}},{q="吉恩·角盔与铁炉堡有什么联系？",a="吉恩是洛克莫丹偏远挖掘场与铁炉堡探险者大厅中探险者协会高层之间的重要通信纽带，经常将实地的进度报告传回首都。",al={"吉恩·角盔与铁炉堡","向铁炉堡汇报的吉恩"}},{q="洛克莫丹的挖掘场面临着什么问题？",a="穴居人一直在骚扰基恩萨·铁环的挖掘场，阻碍了其进度，补给线也处于危险之中：一批运往该地的爆破粉遭到了黑铁矮人的伏击，因此吉恩需要武装的冒险者来护送物资。",al={"铁环挖掘场的问题","洛克莫丹挖掘的危险","为什么吉恩需要帮助"}}},fx={["1cf890d8"]={q="吉恩·角盔为什么在塞尔萨玛？",a="吉恩·角盔驻扎在塞尔萨玛，负责管理洛克莫丹各处考古挖掘点的后勤工作。他为探险者协会提供支持，协调铁炉堡与偏远挖掘点（例如铁环挖掘场）之间的重要物资、报告和爆破材料，确保协会的行动有资金和装备保障。",al={"吉恩·角盔为何在此","吉恩·角盔在洛克莫丹的职责","吉恩为何在塞尔萨玛"}}},fp="13,350,22.390.0,29.391.0,21.187.0,31.113.0,42.148.0,58.270.0,48.234.0,53.252.0"}
P.entries["npc:jitters"] = {n="基特斯",s="基特斯是一个战战兢兢、深居简出的由于，躲藏在暮色森林西部乌鸦岭的废墟中。他被持续不断的偏执和恐惧所吞噬，独自在暮色森林危险的西部边缘生存，依靠过往的冒险者提供援助，同时注视着不断逼近的阴影。",h="基特斯是一个战战兢兢、深居简出的由于，躲藏在暮色森林西部乌鸦岭的废墟中。他被持续不断的偏执和恐惧所吞噬，独自在暮色森林危险的西部边缘生存，依靠过往的冒险者提供援助，同时注视着不断逼近的阴影。",kw={"书记员达尔塔","黑暗骑士","暮色森林","基特斯","乌鸦岭","罗兰之墓","艾露恩之镰","斯温·约根","狼人"},ang={["class:Rogue"]="基特斯有着躲避危险的敏锐直觉，但这并没能让他免于在暮色森林中遭受恐怖和孤独的折磨。",["faction:Alliance"]="基特斯代表了暮色森林悲剧的人性一面，当守夜人努力保护其人民时，他却生活在恐惧之中。"},sec={{t="一个受惊的隐士",b="基特斯被发现时正缩在乌鸦岭破败的屋舍中瑟瑟发抖，他生活在对潜伏在暮色森林西部小径上的掠食者的无尽恐惧中。他依靠过往的冒险者提供简单的食物，在渴望食物的同时，还要惊恐地注视着不断逼近的阴影。他胆小的举止和为了躲避突如其来的危险而迅速跳开的异样本能，让他很久以前就赢得了这个绰号，但他疯狂的偏执源于他亲眼目睹的恐怖遭遇。"},{t="罗兰之墓的觉醒",b="基特斯最初隶属于进入暮色森林的迪菲亚潜行者。当他在名为罗兰之墓的矿井中挖掘时，他发现了从岩石中突出的艾露恩之镰。这件神器将凶残嗜血的狼人释放到了树林中。基特斯惊恐地看着他的同伴被撕成碎片，最后勉强逃脱了这场屠杀，保住了性命。"},{t="逃亡与农场",b="逃离矿井后，基特斯撤退到夜色镇，从书记员达尔塔那里买了一本空白书籍，在躲藏于Scarlet Raven Tavern期间狂热地记录着这场噩梦。惊慌失措之下，他在约根农场的一个谷仓里避难。在那里，他目睹了身披黑袍的黑暗骑士为了寻找艾露恩之镰而屠杀了斯温·约根的家人。由于害怕被责备或被发现，基特斯将他的日记页埋在土里，随后逃往乌鸦岭，在沉重的罪恶感和永无止境的恐惧追逐下生活。"}},faq={{q="基特斯是谁？",a="基特斯是一个生活在乌鸦岭废墟中的惊恐的人类。他饥肠辘辘、孤立无援，并被他在暮色森林的经历所折磨。",al={"他是谁","基特斯背景","基特斯背景故事"}},{q="他为什么叫基特斯？",a="他的绰号源于他谨慎的性格，特别是他面对攻击时退缩以及从突如其来的陷阱中跳开的本能习惯。他在暮色森林中长期的与世隔绝和极度恐惧，只会让他的神经过敏变得更加严重。",al={"为什么叫基特斯","名字由来","基特斯名字起源"}},{q="狼人在暮色森林构成了什么威胁？",a="狼人在暮色森林的树林和道路上潜行，威胁着旅行者和孤立的定居点。",al={"暮色森林狼人威胁","基特斯附近的野兽","暮色森林狼人危险"}},{q="斯温·约根的家人发生了什么事？",a="斯温·约根的家人在他们的农场被谋杀，这使他决心查明谁该对此负责。",al={"斯温农场大屠杀","谁杀了斯温一家","约根农场谋杀案"}},{q="基特斯如何能帮助斯温·约根的调查？",a="基特斯的日记记录了他在暮色森林的经历，可能有助于斯温调查他家人遭遇的不测。",al={"基特斯与斯温的调查","基特斯如何帮助斯温","基特斯的暮色森林记录"}},{q="什么是基特斯的日记？",a="他的日记记录了他在暮色森林的经历，是围绕乌鸦岭和斯温·约根家人所展开的调查的一部分。",al={"基特斯日记","基特斯完整的日记","达尔塔的书"}}},fx={["9934be9b"]={q="基特斯效忠于哪一方？",a="基特斯是个受惊又饥饿的幸存者，藏身于乌鸦岭。他那些令人不安的遭遇让他与世隔绝，内心深受震撼。",al={"基特斯 阵营","基特斯是邪恶的吗","基特斯为谁做事","基特斯 忠诚"}},["3395ed32"]={q="基特斯想要什么？",a="基特斯想要食物和安全。他的饥饿让他遇上了调查乌鸦岭周边麻烦的冒险者。",al={"基特斯需要什么","基特斯 动机","基特斯为何让你去"}},af0d9be3={q="基特斯为什么在乌鸦岭？",a="乌鸦岭废弃的建筑为基特斯提供了藏身之处，但这里给不了他多少安慰或保护。",al={"基特斯为何在乌鸦岭","基特斯如何来到这里","基特斯为何躲在这里"}},b49992e9={q="基特斯与谁有关联？",a="他的故事与斯温·约根的调查，以及保存在斯温日记中的记述交织在一起。",al={"基特斯 关系","基特斯与谁有关联","基特斯 迪菲亚"}}},fp="7,282,16.468.0,30.388.1,24.493.1,15.132.1,25.244.0,43.88.1,38.108.1,49.111.1,25.132.1"}
P.entries["npc:jocaste"] = {n="祖卡斯特",s="祖卡斯特是一位暗夜精灵猎人训练师，居住在达纳苏斯翠绿的塞纳里奥区。她与塞纳里奥议会并肩工作，指导从泰达希尔荒野来到这里的年轻暗夜精灵射手和兽王猎人。",h="祖卡斯特是一位暗夜精灵猎人训练师，居住在达纳苏斯翠绿的塞纳里奥区。她与塞纳里奥议会并肩工作，指导从泰达希尔荒野来到这里的年轻暗夜精灵射手和兽王猎人。",kw={"塞纳里奥区","达纳苏斯","猎人训练师","祖卡斯特","暗夜精灵猎人","泰达希尔"},ang={["class:Hunter"]="对于初次踏入达纳苏斯的暗夜精灵猎人来说，祖卡斯特是一位关键的导师，她能磨练你的战斗技巧，并帮助你巩固与动物伙伴之间的羁绊。",["race:NightElf"]="祖卡斯特扎根于塞纳里奥区，反映了暗夜精灵游侠、泰达希尔的野兽与塞纳里奥议会教义之间紧密的和谐关系。"},sec={{t="塞纳里奥区的导师",b="祖卡斯特驻扎在达纳苏斯塞纳里奥区静谧的树林中，担任暗夜精灵猎人的教官。当新手追踪者结束在幽影谷的初步训练来到这座首府城市时，祖卡斯特会引导他们成长为经验丰富的生存专家。她传授射击技巧、荒野生存技能，以及猎人与卡利姆多野兽之间神圣的羁绊。"}},faq={{q="祖卡斯特是谁？",a="祖卡斯特是一位位于达纳苏斯城塞纳里奥区内的暗夜精灵猎人训练师，为猎人们提供指导和建议。",al={"祖卡斯特背景故事","祖卡斯特是谁","达纳苏斯祖卡斯特"}},{q="在哪里可以找到祖卡斯特？",a="她位于达纳苏斯西北部的塞纳里奥区，在泰达希尔的枝干上，处于树木与亭台之间。",al={"祖卡斯特位置","祖卡斯特在哪里","祖卡斯特坐标"}},{q="她对年轻猎人有什么作用？",a="来到达纳苏斯的猎人们会寻找她，通过“猎人之道”等任务来精进自己的学识，并学习如何正确地驯服和驾驭野兽。",al={"祖卡斯特任务","猎人之道祖卡斯特","training the beast"}},{q="祖卡斯特隶属于塞纳里奥议会吗？",a="是的。尽管她训练的是猎人而非德鲁伊，但她在塞纳里奥区内开展工作，并明确欢迎来访的猎人进入塞纳里奥议会的领地。",al={"祖卡斯特是塞纳里奥议会的吗","祖卡斯特阵营"}}},fx={["42c501de"]={q="祖卡斯特效忠于哪一方？",a="祖卡斯特坚定地支持达纳苏斯、暗夜精灵以及更广泛的联盟。她驻扎在塞纳里奥区，与塞纳里奥议会成员为伍，同样致力于保护自然，并引导那些与荒野和谐共处的人们。",al={"祖卡斯特 阵营","祖卡斯特为谁效力","祖卡斯特 忠诚"}},["05567dfb"]={q="祖卡斯特想要什么？",a="祖卡斯特致力于传授狩猎传统。她希望培养达纳苏斯的年轻猎人，确保他们掌握纪律、射术，以及驯服并指挥野兽所需的精神纽带，从而为自然和族人效力。",al={"祖卡斯特 动机","祖卡斯特的目标是什么","祖卡斯特的目的"}},["1febd3fe"]={q="祖卡斯特为什么在达纳苏斯？",a="祖卡斯特居住在塞纳里奥区，为来访首都的猎人提供智慧与训练。在泰达希尔的古树之间，她为初出茅庐的斥候和经验丰富的荒野追猎者提供重要指导。",al={"祖卡斯特为何在达纳苏斯","祖卡斯特为何在塞纳里奥区"}}},fp="7,230,23.420.0,15.171.0,25.139.0,42.163.0,47.171.0"}
P.entries["npc:john-j-keeshan"] = {n="John J. Keeshan",s="John J. Keeshan下士是一名暴风城军队的人类士兵，曾与赤脊山的黑石兽人作战。他在石堡周边的战斗中被俘，随后被当作战俘拖入了撕裂者之石的深处。",h="John J.",kw={"john j keeshan","keeshan","失踪","撕裂者之石","石堡"},ang={["class:Warrior"]="对于战士们来说，Keeshan是赤脊山前线危险的冷酷证明，即便是身经百战的士兵也可能被黑石氏族压制并拖走。",["faction:Alliance"]="Keeshan代表了联盟在赤脊山与黑石兽人作战时所付出的巨大代价，他是一名在为暴风城守住阵线时被俘的士兵。"},sec={{t="赤脊山的士兵",b="John J. Keeshan是暴风城军队的一名下士，在黑石兽人向湖畔镇及其守军施压时，他被派驻到了赤脊山。当石堡要塞周边的战斗爆发时，Keeshan与其他士兵并肩作战，为王国守住阵线。"},{t="囚禁于撕裂者之石",b="当黑石氏族从燃烧平原向北推进进入赤脊山时，Keeshan是守卫石堡要塞的防线之一。由于兽人的攻势过于猛烈，他没能在战场上阵亡，而是被活捉了。黑石入侵者将他作为俘虏拖进了撕裂者之石的深处，这位老兵从此被关押在敌后，直到联盟救援小队杀入阵中将他解救出来。"}},faq={{q="John J. Keeshan是谁？",a="John J. Keeshan是暴风城军队的一名下士，曾与赤脊山的黑石兽人作战。在围绕石堡要塞的战斗中，他被俘并被拖到了撕裂者之石。",al={"keeshan背景故事","keeshan是谁","基沙恩下士"}},{q="为什么Keeshan会被关押在撕裂者之石？",a="在与石堡要塞周边的黑石氏族作战时，Keeshan寡不敌众，被兽人活捉，并被拖回了他们位于撕裂者之石洞穴内的营地。",al={"为什么keeshan会被俘","撕裂者之石的囚犯","keeshan是如何被俘的"}}},fp="15,241,21.304.0,26.444.1,23.198.0,43.192.0"}
P.entries["npc:jonathan-carevin"] = {n="乔纳森·卡尔文",s="乔纳森·卡尔文是一位居住在夜色镇的坚毅人类猎人，致力于铲除困扰暮色森林的黑暗。与防御性的守夜人不同，他和他的家人主动猎杀亡灵、狼人以及任何潜伏在阴暗树冠下的异端威胁。",h="乔纳森·卡尔文是一位居住在夜色镇的坚毅人类猎人，致力于铲除困扰暮色森林的黑暗。与防御性的守夜人不同，他和他的家人主动猎杀亡灵、狼人以及任何潜伏在阴暗树冠下的异端威胁。",kw={"卡洛尔","卡尔文家族","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","亡灵","狼人"},ang={["class:Hunter"]="猎人们在卡尔文对暮色森林夜行掠食者的主动追踪和有条不紊的猎杀行动中找到了共鸣。",["class:Paladin"]="卡尔文的热忱以及他为了对抗恶魔和亡灵腐化而祈求圣光的行为，与圣骑士的神圣誓言产生了深刻的共鸣。",["faction:Alliance"]="对于那些试图稳定暮色森林局势的联盟勇士来说，乔纳森·卡尔文针对暴风城因忽视而放任不管的超自然威胁，提供了精准的打击。"},sec={{t="卡尔文十字军",b="虽然夜色镇依靠守夜人巡逻道路并守护城镇，但乔纳森·卡尔文认为仅仅建立防御圈是不够的。他和他的家人以及像卡洛尔这样的盟友并肩作战，主动出击。他积极针对在暮色森林游荡的邪恶怪物，在圣光的指引下，开启了一场个人的圣战，旨在从该地区清除所有的恶魔、亡灵和异端。"},{t="狼人的阴影",b="乔纳森的警惕不仅限于蹒跚的骷髅和食尸鬼。他密切关注着那些潜伏在森林深处、被称为狼人的野蛮狼形野兽。他深知这些生物对这个本已深陷围困的定居点构成的危险，因此统筹调查这些生物神秘出现的原因，试图揭开这些邪恶掠食者的起源，并终结它们的夜间游荡。"}},faq={{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是一位住在暮色森林夜色镇的冷酷猎人。他带领卡尔文家族积极抗击着困扰森林的邪恶怪物。",al={"乔纳森·卡尔文是谁","乔纳森·卡尔文背景故事","卡尔文夜色镇"}},{q="他与守夜人有何不同？",a="虽然守夜人的主要工作是守卫夜色镇的边界并保持道路畅通，但乔纳森和他的支持者们会主动追踪并猎杀亡灵和其他憎恶，从源头上根除它们。",al={"他是守夜人吗","卡尔文与守夜人"}},{q="他与哪些威胁作斗争？",a="乔纳森积极猎杀亡灵、贪婪的狼群、恶魔，以及任何为这些邪恶憎恶提供庇护或帮助的人。",al={"卡尔文猎杀什么","卡尔文的目标"}},{q="乔纳森与血色十字军有关联吗？",a="他那严苛的言辞、对圣光的狂热虔诚，以及对腐化零容忍的严格态度都与血色十字军的信仰如出一辙，但官方层面他是在夜色镇与他的家人独立行动。",al={"卡尔文血色十字军","卡尔文是血色十字军吗"}},{q="谁协助乔纳森执行他的任务？",a="除了他的直系亲属外，乔纳森还得到了像卡洛尔这样志同道合的战士的直接协助，卡洛尔帮助他追踪穿越森林的怪物入侵。",al={"卡尔文的盟友","谁帮助卡尔文"}},{q="他与狼人有什么关联？",a="乔纳森视狼人为恐吓暮色森林人民的非自然威胁，并委托旅行者去揭开它们在荒野中突然出现的原因。",al={"卡尔文与狼人","为什么卡尔文痛恨狼人"}}},fx={["8aa9d9d7"]={q="乔纳森·卡尔文想要什么？",al={"乔纳森·卡尔文的目标","卡尔文的目标是什么","卡尔文的使命"}},["24497d50"]={q="乔纳森·卡尔文为什么在夜色镇？",a="夜色镇处于一片阴影笼罩的土地前线，这里遍布食尸鬼、骷髅和更可怕的怪物。乔纳森·卡尔文和他的家人将坚守此地视为自己的使命，组织对亡灵的袭击，并召集愿意拿起武器、对抗潜伏在暮色森林幽暗枝桠下的恐怖之物的能干冒险者。",al={"卡尔文为何在夜色镇","乔纳森·卡尔文为何在此","卡尔文在暮色森林的缘由"}}},fp="16,277,19.410.0,24.412.1,24.160.0,40.231.0,27.137.0,48.203.0,36.171.0,37.170.0"}
P.entries["npc:jorah-annison"] = {n="约拉·安尼森",s="约拉·安尼森是一位驻扎在幽暗城法师区的被遗忘者制图师。虽然他的职业是与地图和地理打交道，但对于那些在艾泽拉斯寻找晦涩且散佚知识的旅行施法者来说，他的专业知识极其宝贵。",h="约拉·安尼森是一位驻扎在幽暗城法师区的被遗忘者制图师。虽然他的职业是与地图和地理打交道，但对于那些在艾泽拉斯寻找晦涩且散佚知识的旅行施法者来说，他的专业知识极其宝贵。",kw={"安尼森","制图师","约拉","magic quarter","地图","秘法会之书","幽暗城","术士"},ang={["class:Warlock"]="约拉是部落术士收集《秘法会之书》的重要联系人，他提供了在世界各地寻回丢失书页的关键坐标。",["faction:Horde"]="通过他的制图专业知识，约拉协助部落的冒险者探索陌生的大陆并找回珍贵的遗物。",["race:Undead"]="作为幽暗城的市民，约拉展现了诸如制图学之类的被遗忘者智力追求是如何为他的人民的广泛生存提供服务的。"},sec={{t="黑暗之地的学者",b="约拉·安尼森栖身于幽暗城法师区的炼金蒸汽和奥术回响之中，以此为业进行制图。然而地图让他感到厌烦：约拉宁愿用店里所有的地图去换一本好书。他对于古籍的了解比几乎任何人都多，这种学者的品味也让他与那些前来寻访他的术士们产生了共鸣。"},{t="秘法会的踪迹",b="约拉对这片土地的了解远超洛丹伦废墟。那些寻求难以捉摸的《秘法会之书》的术士经常被指引去寻找他，以发掘那些古籍和黑暗教派残余可能被埋藏的地方，从而架起了历史知识与遥远地理之间的桥梁。"}},faq={{q="约拉·安尼森是谁？",a="约拉·安尼森是一位亡灵制图师，居住在幽暗城的法师区，为部落的旅行者提供地理知识和历史地点方面的帮助。",al={"约拉·安尼森是谁","约拉是谁","幽暗城制图师"}},{q="我在哪里可以找到约拉·安尼森？",a="他位于幽暗城的法师区。幽暗城是被遗忘者的地下都城，坐落在洛丹伦废墟之下。",al={"约拉·安尼森位置","约拉·安尼森在哪里","寻找约拉"}},{q="为什么术士需要与他交谈？",a="斯坦哈德·法尔杉会将那些寻求古老的《秘法会之书》的术士派往约拉处，因为约拉对古籍的了解超过斯坦哈德认识的任何人。约拉会指引他们找到这本书丢失的另一半，据传其一半在千针石林的半人马手中，另一半则在南海镇以西的海岸运输途中遗失了。",al={"约拉术士任务","秘法会之书约拉","为什么要找约拉"}},{q="约拉·安尼森属于哪个阵营？",a="他是被遗忘者的一员，效忠于部落，在他的都城内为同胞服务。",al={"约拉是部落吗","约拉·安尼森阵营"}},{q="约拉·安尼森会直接向玩家出售地图吗？",a="约拉的主要职能是作为关于被遗忘地标的顾问和任务联系人，而不是作为一名活跃的商品商人。",al={"约拉卖地图吗","约拉商人"}},{q="约拉·安尼森会出现在幽暗城之外吗？",a="虽然他的地图绘制和任务引导涉及贫瘠之地等遥远的地点，但约拉本人始终驻扎在幽暗城的法师区。",al={"贫瘠之地的约拉","幽暗城外的约拉"}}},fp="13,263,27.341.0,17.292.0,21.169.0,31.134.0,39.296.0,42.107.0,49.123.0,50.157.0"}
P.entries["npc:jordan-stilwell"] = {n="乔丹·斯迪威尔",s="乔丹·斯迪威尔是一位技术精湛的人类武器锻造师，驻扎在丹莫罗的铁炉堡大门外。虽然他原本注定要成为一名圣光的圣骑士，但他追随父亲的技艺，成为了一名工匠，其作品为整个联盟的圣骑士提供服务。他最著名的成就便是为了纪念老友博什·维里甘而锻造了维里甘之拳。",h="乔丹·斯迪威尔是一位技术精湛的人类武器锻造师，驻扎在丹莫罗的铁炉堡大门外。虽然他原本注定要成为一名圣光的圣骑士，但他追随父亲的技艺，成为了一名工匠，其作品为整个联盟的圣骑士提供服务。他最著名的成就便是为了纪念老友博什·维...",kw={"白洛尔·石手","博什·维里甘","达芙妮·斯迪威尔","丹莫罗","铁炉堡","乔丹·斯迪威尔","影牙城堡","勇气之书","维里甘之拳"},ang={["class:Paladin"]="乔丹·斯迪威尔是圣骑士早期试炼中的关键人物，他会委托他们搜寻艾泽拉斯各地，寻找稀有组件来锻造他们标志性的战锤——维里甘之拳。",["faction:Alliance"]="在逃离银松森林阿鲁高的狼人恐怖统治后，乔丹在丹莫罗的矮人中找到了避难所，现在他直接为联盟的勇士们提供自己的技艺。",["profession:Blacksmithing"]="在矮人白洛尔·石手的训练下，并挥舞着从父亲那里继承的附魔锻造锤，乔丹代表了凡人圣光金属加工技术的巅峰。"},sec={{t="铁砧的召唤",b="虽然乔丹·斯迪威尔本应遵守神圣誓言，成为圣光教会的一名圣骑士，但他最终选择了锻造之路。他追随父亲的脚步，拿起了父亲那把附魔的锻造锤。乔丹在矮人铁匠白洛尔·石手的指导下磨练自己的技艺。尽管他放弃了成为圣职战斗人员的重任，但乔丹依然对圣光怀有深厚的信仰，将自己非凡的工艺贡献给那些以圣光之名战斗的勇士们。"},{t="逃离银松",b="早在前往丹莫罗那寒冷刺骨的地方开店之前，乔丹曾在银松森林的席瓦莱恩男爵的城堡中担任铁匠。当大法师阿鲁高将野性的狼人释放到要塞中，将其变成了被称为影牙城堡的诅咒堡垒时，乔丹成功逃离了那场血腥屠杀。他被迫放弃了自己的锻炉和曾经的家，最终在丹莫罗的矮人中找到了避难所。"},{t="锻造维里甘之拳",b="乔丹将锻炉设在铁炉堡大门附近的户外，比起山内大熔炉那令人窒息的热浪，他更偏爱那清爽的高山空气。当圣光教会将值得托付的圣骑士派往他这里时，乔丹会委托他们从世界各地收集稀有材料，以打造一把传奇的双手法锤。这把武器以他老友博什·维里甘的名字命名为“维里甘之拳”，象征着虔诚的信仰与精湛的钢铁技艺之间永恒的纽带。"}},faq={{q="谁是乔丹·斯迪威尔？",a="乔丹·斯迪威尔是一位人类锻造大师，在丹莫罗的铁炉堡大门外工作。他为圣光教会的圣骑士打造神圣的装备，其中最著名的是传奇战锤维里甘之拳。",al={"谁是乔丹·斯迪威尔","乔丹·斯迪威尔背景故事","铁炉堡外面的铁匠是谁"}},{q="为什么乔丹·斯迪威尔要在雪地里的户外工作，而不是在铁炉堡里面？",a="据暴风城的达索瑞恩·拉尔所说，乔丹更喜欢在丹莫罗清爽凉爽的山间空气中工作，而不是铁炉堡内部那令人窒息的大熔炉环境。",al={"为什么乔丹在铁炉堡外面","为什么在丹莫罗工作","为什么他在雪地里"}},{q="乔丹·斯迪威尔与影牙城堡有什么联系？",a="乔丹曾是驻扎在银松森林席瓦莱恩男爵庄园的军械师和铁匠。在灾难性的起义期间，当大法师阿鲁高和他的野性狼人屠杀了守军并夺取了堡垒时，他在那时或之前成功逃离了城堡。",al={"乔丹·斯迪威尔影牙城堡","乔丹·斯迪威尔银松森林","他住在焚木村吗"}},{q="什么是维里甘之拳？",a="维里甘之拳是一把强大的双手圣锤，由乔丹·斯迪威尔为联盟圣骑士锻造。它的命名是为了纪念乔丹的老友博什·维里甘。",al={"维里甘之拳","维里甘战锤","维里甘是谁"}},{q="谁训练了乔丹·斯迪威尔的锻造技术？",a="乔丹从父亲那里继承了技艺和一把附魔锻造锤，随后在矮人铁匠白洛尔·石手的指导下精进了自己的专业技术。",al={"谁训练了乔丹·斯迪威尔","乔丹·斯迪威尔的老师","他在哪里学的锻造"}},{q="谁是乔丹·斯迪威尔的妻子？",a="乔丹的妻子是达芙妮·斯迪威尔。多年来，这对夫妇为圣光教会提供了巨大的帮助，两人都被尊为信仰深厚的虔诚仆人。",al={"乔丹·斯迪威尔的妻子","达芙妮·斯迪威尔的丈夫","达芙妮·斯迪威尔"}}},fx={["49deb919"]={q="乔丹·斯迪威尔效忠哪一方？",a="乔丹坚定地效忠联盟与圣光教会。尽管他住在丹莫罗的矮人中间，并在铁炉堡外经营自己的生意，但他仍与暴风城的圣骑士保持着密切联系，专心打造武器，帮助信徒对抗威胁这个王国的黑暗。",al={"乔丹·斯迪威尔的阵营","乔丹·斯迪威尔是联盟的吗","乔丹·斯迪威尔的效忠对象"}},dd0bfe26={q="乔丹·斯迪威尔想要什么？",a="乔丹想为值得托付的圣骑士锻造一件非凡武器，以此纪念他的老友博什·维里甘。要打造神圣战锤维里甘之拳，他需要收集艾泽拉斯各地的稀有材料：恩师白洛尔·石手提供的精炼矿石、白石橡木、净化过的科尔宝石，以及他父亲遗失的铁匠锤。",al={"乔丹·斯迪威尔需要什么","乔丹·斯迪威尔的目标","乔丹·斯迪威尔的目的"}},["3def62e7"]={q="乔丹·斯迪威尔为何出名？",a="乔丹以出色的武器锻造技艺闻名，他对圣光的虔诚与炉边技艺不相上下。他原本注定要成为一名圣骑士，却选择追随父亲的脚步。他和妻子达芙妮曾大力帮助圣光教会，因此教会至今仍将他视为最忠诚的信徒之一。",al={"乔丹·斯迪威尔有名吗","乔丹·斯迪威尔的名望","乔丹·斯迪威尔为何出名"}}},fp="15,358,22.527.0,22.418.0,22.491.1,23.230.0,78.181.0,56.266.0,23.160.0,45.178.0,30.192.0"}
P.entries["npc:jorgen"] = {n="乔贞",s="乔贞是一位住在暴风城的谨慎人类情报员，藏身于英雄谷内侧靠水的地方。尽管他的位置低调且偏僻，但他与首都里的显赫人物牵扯甚深，其中包括埃林·提亚斯和德拉维主教。",h="乔贞是一位住在暴风城的谨慎人类情报员，藏身于英雄谷内侧靠水的地方。尽管他的位置低调且偏僻，但他与首都里的显赫人物牵扯甚深，其中包括埃林·提亚斯和德拉维主教。",kw={"德拉维主教","埃林·提亚斯","情报员","乔贞","失踪外交官","暴风城","英雄谷"},ang={["class:Rogue"]="乔贞代表了在暴风城洁白大理石之下蓬勃发展的街头耳目网络，与通过Trias' Cheese运作的秘密行动联系紧密。",["faction:Alliance"]="当暴风城的官方渠道遇到官僚阻碍时，像乔贞这样可靠的街头情报员对于追踪威胁王国的危机至关重要。"},sec={{t="水边的眼线",b="乔贞位于暴风城那宏伟入口右侧的水边，远离城中熙熙攘攘的干道，行事低调。当上方桥梁上的英雄雕像俯瞰众生时，乔贞却在下方的阴影中监视着往来的人群，作为那些需要获取非公开信息的人的静默联络人。"},{t="错综复杂的往事",b="乔贞的谨慎并非偶然。他与奶酪商人兼情报搜集者埃林·提亚斯，以及Cathedral of Light的德拉维主教有着一段并不轻松的过去。当敏感的调查任务出现——比如查清一名被派往塞拉摩的外交官的失踪案时——乔贞是少数几个能为调查者指出正确方向的当地联络人之一，前提是调查者知道如何接近他。"}},faq={{q="我能在哪里找到乔贞？",a="乔贞位于暴风城的英雄谷内。从艾尔文森林进入城门后，径直前往主桥右侧的水边即可找到他。",al={"乔贞位置","乔贞在哪里","寻找乔贞"}},{q="乔贞与暴风城的哪些人有关联？",a="乔贞与Trade District里著名的奶酪商，同时拥有秘密人脉的埃林·提亚斯，以及Cathedral of Light的德拉维主教有着一段充满故事的往事。",al={"乔贞关系网","乔贞关联","乔贞认识谁"}},{q="乔贞在失踪外交官的调查中扮演什么角色？",a="在寻找失踪特使期间，德拉维主教带着一封信将调查者引荐给他的老友乔贞。乔贞勉强同意提供帮助，让调查者发誓保守秘密，并将他们指引向Trias' Cheese，交给埃林·提亚斯一封密封的信件。",al={"乔贞失踪外交官","乔贞任务"}},{q="乔贞隶属于暴风城卫兵吗？",a="不。乔贞独立行动，躲开运河边那些官方卫兵的巡逻路线，以便在无人窥探的情况下进行秘密谈话。",al={"乔贞是卫兵吗","乔贞阵营"}}},fp="6,147,17.253.0,17.378.1,24.172.0,40.157.0,72.245.0,51.138.0"}
P.entries["npc:josef-gregorian"] = {n="乔瑟夫·格里高利",s="乔瑟夫·格里高利是一位被遗忘者裁缝训练师，在幽暗城的Magic Quarter工作。他指导那些渴望编织附魔布料的部落裁缝，提供专业知识并指导他们制作专业服饰。",h="乔瑟夫·格里高利是一位被遗忘者裁缝训练师，在幽暗城的Magic Quarter工作。他指导那些渴望编织附魔布料的部落裁缝，提供专业知识并指导他们制作专业服饰。",kw={"收集材料","乔瑟夫·格里高利","magic quarter","魔焰长袍","裁缝训练师","幽暗城"},ang={["profession:Tailoring"]="对于部落的布甲制造者来说，乔瑟夫·格里高利是洛丹伦的重要联络人，他为裁缝提供指导，并为带给他材料的年轻法师缝制长袍。",["race:Undead"]="格里高利证明了尽管经历了死亡与复生，人类精湛的裁缝技艺在洛丹伦陷落后依然存续，并服务于新的被遗忘者社会。"},sec={{t="Magic Quarter的编织者",b="在Magic Quarter昏暗的炼金灯火与潮湿拱顶之间，乔瑟夫·格里高利为被遗忘者及其部落盟友维持着精湛的裁缝工艺。虽然这座地下王国的日子变得寒冷，但对于那些通过编织纤维来引导原始能量的术士、法师和牧师来说，布料制作依然至关重要。格里高利是首都里一位可靠的导师，他准备好教授基础图样，并为那些带着合适材料来找他的年轻法师缝制第一件长袍。"}},faq={{q="我在哪里可以找到乔瑟夫·格里高利？",a="乔瑟夫·格里高利位于幽暗城的Magic Quarter，在那里与城市的施法者和学者们一同钻研并教授裁缝工艺。",al={"乔瑟夫·格里高利位置","格里高利在哪里","幽暗城裁缝训练师"}},{q="乔瑟夫·格里高利在幽暗城担任什么职责？",a="他是一位裁缝训练师，向部落工匠教授缝纫配方和技巧。他还负责为安娜斯塔西娅·哈特威尔派来的年轻法师缝制第一件长袍。",al={"乔瑟夫·格里高利做什么","乔瑟夫·格里高利训练师","幽暗城裁缝"}},{q="乔瑟夫·格里高利提供什么任务？",a="格里高利参与了一条法师任务线：安娜斯塔西娅·哈特威尔会将年轻的法师派往他那里，带上在银松森林采集的亚麻布和达拉然法力宝石（收集材料），他会为他们缝制一套魔焰长袍（魔焰长袍）。",al={"乔瑟夫·格里高利任务","幽暗城长袍任务"}}},fx={d179720d={q="乔瑟夫·格里高利是谁？",a="乔瑟夫·格里高利是一名亡灵工匠，在幽暗城的魔法区担任裁缝训练师。和许多被遗忘者工匠一样，他保留了生前精湛的技艺，将自己对丝线、布料和附魔衣物的知识用于服务希尔瓦娜斯女王的子民及其部落盟友。",al={"乔瑟夫·格里高利是谁","乔瑟夫·格里高利的背景","裁缝乔瑟夫·格里高利是谁"}},["057f78ac"]={q="乔瑟夫·格里高利效忠哪一方？",a="他效忠被遗忘者与部落。他驻守在幽暗城深处，只向为黑暗女王与部落效力的人传授裁缝知识、图样和行业经验。",al={"乔瑟夫·格里高利的阵营","乔瑟夫·格里高利是部落的吗","乔瑟夫·格里高利为谁效力"}},["3b87a245"]={q="乔瑟夫·格里高利为什么在幽暗城？",a="乔瑟夫留在幽暗城，继续钻研并传授裁缝技艺。他在魔法区的施法者与学者之间开设工坊，为前往东西瘟疫之地及更远地区的冒险者织造长袍、附魔衣物和布甲。",al={"乔瑟夫·格里高利为何在此","是什么让乔瑟夫·格里高利来到幽暗城","乔瑟夫为何在魔法区"}}},fp="15,238,27.506.0,33.148.0,54.169.0,39.241.0"}
P.entries["npc:kaal-soulreaper"] = {n="卡尔·噬灵",s="卡尔·噬灵是一位驻扎在幽暗城Magic Quarter深处的兽人术士训练师。尽管他居住在被遗忘者之中，但他与部落各地的黑暗技艺修行者保持着密切的联系，经常指引学徒前往远方的导师处进修。",h="卡尔·噬灵是一位驻扎在幽暗城Magic Quarter深处的兽人术士训练师。尽管他居住在被遗忘者之中，但他与部落各地的黑暗技艺修行者保持着密切的联系，经常指引学徒前往远方的导师处进修。",kw={"恶魔学","地狱战马","卡尔·噬灵","magic quarter","梅纳拉·沃伦德","幽暗城","术士训练师"},ang={["class:Warlock"]="卡尔·噬灵提供恶魔技艺的基本训练，并让雄心勃勃的术士走上制作奥拉希尔之球和召唤地狱战马所需的道路。",["race:Orc"]="与大断崖中隐藏的集会所不同，卡尔在被遗忘者的首都中公开活动，远离奥格瑞玛萨满领导层的监视。"},sec={{t="阴影中的修行者",b="虽然萨尔领导的部落在奥格瑞玛严格监管和监控邪能魔法，但像卡尔·噬灵这样的修行者却能在洛丹伦的地下圣所中找到充足的避难所。卡尔居住在幽暗城的Magic Quarter，他与渴望学习的部落术士分享他对恶魔实体和诅咒的精通。除了基础指导外，他还担任寻求更强大力量的修行者的重要联络人，将雄心勃勃的学生指引到无尽之海彼岸，寻找贫瘠之地的梅纳拉·沃伦德等导师。"}},faq={{q="卡尔·噬灵是谁？",a="卡尔·噬灵是一位居住在幽暗城Magic Quarter的兽人术士训练师。他教授术士法术，并为寻求专业黑暗神器和仪式的修行者提供指导。",al={"卡尔是谁","卡尔·噬灵背景故事","卡尔在幽暗城"}},{q="为什么一位兽人术士会住在幽暗城？",a="在大酋长萨尔的领导下，术士在兽人社会中面临着沉重的怀疑和审视。幽暗城为与被遗忘者一起研究暗影魔法和恶魔学提供了更加宽容的环境。",al={"为什么兽人在幽暗城","为什么卡尔在幽暗城"}},{q="卡尔·噬灵将他的学徒送到哪里？",a="当他的学生达到足够的熟练程度时，卡尔会指引他们穿越无尽之海前往贫瘠之地，在梅纳拉·沃伦德门下学习，或者将他们介绍给其他著名的部落术士。",al={"卡尔的任务","卡尔把玩家推荐给谁"}}},fx={["17865f78"]={q="卡尔·噬灵效忠哪一方？",a="卡尔·噬灵坚定地效忠部落。虽然他是一名居住在幽暗城、与被遗忘者为邻的兽人，却训练那些宣誓效忠部落事业的术士。他与卡利姆多和东部王国的其他部落施法者保持直接联系，包括贫瘠之地和棘齿城的术士，确保施展黑暗魔法的人也能将邪能用于援助盟友。",al={"卡尔·噬灵的阵营","卡尔·噬灵为谁效力","卡尔·噬灵是部落的吗"}},["78b7a2d4"]={q="卡尔·噬灵想要什么？",a="卡尔想引导有志成为术士的人踏上掌握恶魔力量的险途。他不愿让缺乏经验的施法者屈服于扭曲虚空的腐化力量，因此会确保他们学会召唤并束缚恶魔（例如邪能战马）所需的仪式，并指引有潜力的学徒向梅纳拉·沃伦德这样的高手学习，精进技艺。",al={"卡尔·噬灵的动机","卡尔·噬灵的目标","卡尔·噬灵在做什么"}},["0c3c6935"]={q="卡尔·噬灵与谁有联系？",a="卡尔与各地的术士导师保持密切联系。他常将有能力的施法者引荐到贫瘠之地的梅纳拉·沃伦德那里，接受专门训练、学习高阶仪式，并获取奥拉希尔之球之类的神器。",al={"卡尔·噬灵的人脉","卡尔·噬灵与谁共事","卡尔·噬灵的盟友"}}},fp="15,279,29.516.0,23.195.0,46.201.0,48.185.0"}
P.entries["npc:kadrak"] = {n="卡德拉克",s="卡德拉克是一位经验丰富的兽人指挥官，驻扎在位于贫瘠之地与灰谷交界处的莫尔杉壁垒。他的任务是守卫北部边境，并负责协调进入这片争夺激烈的森林的补给和增援部队。对于那些穿过干旱平原的部落冒险者来说，卡德拉克是他们踏入与暗夜精灵进行长期斗争的前哨站。",h="卡德拉克是一位经验丰富的兽人指挥官，驻扎在位于贫瘠之地与灰谷交界处的莫尔杉壁垒。他的任务是守卫北部边境，并负责协调进入这片争夺激烈的森林的补给和增援部队。对于那些穿过干旱平原的部落冒险者来说，卡德拉克是他们踏入与暗夜精灵...",kw={"灰谷","贫瘠之地","卡德拉克","莫尔杉壁垒","兽人","壁垒","碎木岗哨","战歌"},ang={["class:Warrior"]="卡德拉克体现了前线的纪律，依靠精钢与武力在坚固的咽喉要地抵御敌对的森林势力和游击突袭。",["faction:Alliance"]="对于试图从灰谷突入贫瘠之地的联盟军队来说，卡德拉克和他的壁垒是守卫部落心脏地带的一道坚固路障。",["faction:Horde"]="卡德拉克是你投身灰谷战役的切入点，他指挥着向北进发的勇士们，去保卫伐木作业并开辟部落的疆土。",["race:Orc"]="作为一名捍卫战歌氏族领土扩张事业的坚定老兵，卡德拉克代表了兽人在灰谷边境绝不屈服的决心。"},sec={{t="壁垒守护者",b="卡德拉克站在莫尔杉壁垒坚固的木制防御工事之上，监视着连接贫瘠之地与灰谷的主要路线。这条边境线险象环生：南部是部落宣称拥有的被烈日灼烤的平原，北部则是暗夜精灵誓死捍卫的古老森林。卡德拉克确保防线固若金汤，以抵御哨兵和敌对森林生物的侵袭。"},{t="前线后勤",b="除了坚守防线，卡德拉克还负责管理贫瘠之地与森林深处伐木场之间的重要军事情报。他接收来自战歌氏族的信使送来的关键战报，并协调物资和新鲜血液向碎木岗哨这样的据点输送。向他汇报的人会立即被指派到领土战争的核心地带。"}},faq={{q="卡德拉克是谁？",a="卡德拉克是一位驻扎在莫尔杉壁垒的兽人军官。他负责边境安全，并指挥往返于贫瘠之地与灰谷战区的部落军队。",al={"卡德拉克的身份","墙边的兽人是谁","莫尔杉壁垒指挥官"}},{q="在哪里可以找到卡德拉克？",a="卡德拉克站在莫尔杉壁垒，那是位于贫瘠之地最北端的坚固木制防线，标志着通往灰谷的边界。",al={"卡德拉克的位置","找到卡德拉克","卡德拉克在哪里"}},{q="卡德拉克在部落中扮演什么角色？",a="他指挥着边境的防线，从侦察兵那里收集军事情报，并为前往北部增援碎木岗哨等据点的部落旅行者提供简报。",al={"卡德拉克的职责","卡德拉克做什么","卡德拉克的角色"}},{q="为什么莫尔杉壁垒戒备森严？",a="这座壁垒保护着贫瘠之地和杜隆塔尔的北部入口，防止暗夜精灵因部落在灰谷的伐木行动而发起的报复性入侵。",al={"为什么莫尔杉壁垒要设防","壁垒的目的","为什么要守卫灰谷边境"}},{q="卡德拉克会提供或完成哪些任务？",a="卡德拉克接收从贫瘠之地送来的报告，并派遣冒险者去执行有关战歌侦察报告以及在森林边境建立更稳固部落据点的任务。",al={"卡德拉克的任务","向卡德拉克汇报","战歌报告"}},{q="卡德拉克与其他著名的部落人物有联系吗？",a="卡德拉克与在灰谷行动的战歌氏族保持定期联络，并在壁垒处接收他们的侦察报告。",al={"卡德拉克的关系网"}}},fx={e1636f20={q="卡德拉克效忠哪一方？",a="卡德拉克是部落忠诚的战士。他驻守在贫瘠之地与争夺中的灰谷森林之间崎岖的边境，奉酋长之命行事，致力于维护兽人的利益，并抵御暗夜精灵的侵袭，保卫部落哨站。",al={"卡德拉克的阵营","卡德拉克是部落的吗","卡德拉克为谁效力"}},["4dfee007"]={q="卡德拉克想要什么？",a="卡德拉克的目标是守住贫瘠之地的北部边境，并将部落势力进一步推进灰谷。面对暗夜精灵的顽强抵抗，他希望招募能干的部落勇士传递报告、支援陷入困境的斥候，并保护莫尔杉壁垒一带的重要补给线。",al={"卡德拉克的目标是什么","卡德拉克的动机","卡德拉克需要什么"}},["86a4d862"]={q="卡德拉克为什么在莫尔杉壁垒？",a="卡德拉克驻守莫尔杉壁垒，因为这里是守卫贫瘠之地、抵御灰谷敌对森林的关键要冲。随着与暗夜精灵的冲突加剧，他负责协调防御、监视敌方动向，并派遣斥候增援北方的战歌哨站。",al={"卡德拉克为何在壁垒","卡德拉克在此处的缘由","卡德拉克为何驻扎在此"}}},fp="6,379,23.447.0,19.406.0,14.173.0,26.155.0,35.187.0,45.165.0,44.190.0,53.142.0"}
P.entries["npc:kaela-shadowspear"] = {n="凯拉·影矛",s="凯拉·影矛是一名驻扎在石爪山脉狂风峭壁西南方的暗夜精灵哨兵。她坐镇在一座小型哨站，与同伴哨兵协调，监视荒野中不断升级的紧张局势和区域动荡。她依靠勇敢的旅行者去侦察危险的领地，并查明是什么腐蚀了这片土地的古老守护者。",h="凯拉·影矛是一名驻扎在石爪山脉狂风峭壁西南方的暗夜精灵哨兵。她坐镇在一座小型哨站，与同伴哨兵协调，监视荒野中不断升级的紧张局势和区域动荡。她依靠勇敢的旅行者去侦察危险的领地，并查明是什么腐蚀了这片土地的古老守护者。",kw={"远古守护者","凯拉","尘链","哨兵","影矛","灵魂","石爪山脉","塞恩希尔","狂风峭壁"},ang={["class:Druid"]="德鲁伊们会与凯拉产生共鸣，共同努力查明是什么腐化了焦炭谷的远古守护者，并平息受扰自然之灵的痛苦。",["faction:Alliance"]="凯拉·影矛是联盟冒险者进入石爪山脉纷争地带时的关键联络点，负责在各个遥远的哨站之间协调情报。",["race:NightElf"]="对于暗夜精灵来说，凯拉代表了对圣地的坚定捍卫，她致力于安抚愤怒的灵魂，并守护卡利姆多受人尊崇的远古守护者。"},sec={{t="边境的斥候",b="Positioned just southwest of the industrial devastation of Windshear Crag, Kaela Shadowspear keeps a watchful vigil over the surrounding passes. The Stonetalon Mountains are fraught with danger as the Horde encroaches and goblin operations exploit the land's natural bounty. Operating alongside the gnome Gaxim Rustfizzle, Kaela acts as an essential forward liaison for the night elves, tracking threats that push deeper into ancestral territory."},{t="治愈大地",b="石爪山脉的动荡远不止领土冲突那么简单。对自然的暴力破坏激怒了元素，并伤害了森林的古老守护者。凯拉不知疲倦地派遣冒险者去对抗狂暴的元素之灵，并查明是什么腐蚀了这些受伤的远古守护者——那些曾经守护焦炭谷的树人。她正努力在土地受到不可挽回的创伤之前恢复和平。"}},faq={{q="凯拉·影矛是谁？",a="凯拉·影矛是一名位于石爪山脉狂风峭壁西南方边境营地的暗夜精灵任务发布者。她负责监督区域侦察，并协助保护当地的野生动物和灵魂。",al={"凯拉是谁","凯拉·影矛的身份","凯拉npc"}},{q="在哪里可以找到凯拉·影矛？",a="她位于石爪山脉狂风峭壁西南方路边的一个小型联盟营地中，与侏儒工程师加克希姆·尘链共享该营地。",al={"凯拉·影矛的位置","凯拉在哪里","凯拉的石爪山脉营地"}},{q="凯拉向谁汇报？",a="凯拉与哨兵塞恩希尔密切协作，定期发送和接收关于石爪山脉各地敌军动向和当地威胁的情报更新。",al={"凯拉向谁汇报","凯拉与塞恩希尔","凯拉的指挥官"}},{q="为什么凯拉担心元素？",a="当风险投资公司放火烧焦了焦炭谷并用他们的机器进行破坏时，他们释放了燃烧的灵魂——火焰、岩石与愤怒的元素——现在这些元素正徘徊在焦炭谷中。凯拉希望削减它们的数量，以便大地能够恢复。",al={"狂怒的灵魂任务","灵魂为什么愤怒","凯拉的元素之灵"}},{q="狂风峭壁附近的远古守护者发生了什么事？",a="守护焦炭谷的树人曾帮助击退了风险投资公司，但此后它们变得腐化堕落。加克希姆怀疑是地精的武器导致了这一切，所以凯拉请求旅行者从受伤的树人身上带回一块被腐蚀的弹片供他研究。",al={"受伤的远古守护者任务","凯拉的远古守护者","石爪山脉受伤的远古守护者"}},{q="为什么一个侏儒和凯拉驻扎在一起？",a="凯拉与联盟侏儒加克希姆·尘链共用同一个营地。凯拉专注于荒野的精神和战术平衡，而加克希姆则致力于对抗附近敌对的地精机器和行动。",al={"加克希姆·尘链与凯拉","为什么加克希姆和凯拉在一起","侏儒与暗夜精灵营地"}}},fx={e879ebe3={q="凯拉·影矛效忠哪一方？",a="凯拉坚定地支持暗夜精灵与联盟。她驻扎在石爪山脉，为达纳苏斯和哨兵指挥部效力，并与联盟斥候密切合作，保卫这片土地免受敌人侵袭。",al={"凯拉·影矛的阵营","凯拉·影矛是联盟的吗","凯拉·影矛的效忠对象"}},["6c46a0c6"]={q="凯拉·影矛想要什么？",a="凯拉的目标是保护石爪山脉免遭破坏。她想削弱风险投资公司释放的狂怒元素灵，查明是什么腐化了焦炭谷受伤的古树，并及时向指挥官通报当地的威胁。",al={"凯拉·影矛的目标","凯拉想要什么","凯拉的目标"}},bb8cec73={q="凯拉·影矛为什么在这里？",a="凯拉以哨兵斥候的身份部署在狂风峭壁西南方。她从这座前哨监视石爪山脉各处的异动，尤其关注当地灵魂遭到腐化的情况，以及附近古树所处的困境。",al={"凯拉·影矛为何在石爪山脉","凯拉·影矛的使命","凯拉为何在此"}}},fp="17,363,23.446.0,16.417.0,25.216.0,37.179.0,25.158.0,44.235.0,54.268.0,36.230.0"}
P.entries["npc:kali-remik"] = {n="卡利·雷米克",s="卡利·雷米克是一位暗矛巨魔猎人，她将自己的时间用于为游历部落腹地的旅人们提供指引。她熟悉杜隆塔尔的追踪和生存之道，并会引导年轻的猎人前往剃刀岭寻找索塔尔，学习驯服野兽。",h="卡利·雷米克是一位暗矛巨魔猎人，她将自己的时间用于为游历部落腹地的旅人们提供指引。她熟悉杜隆塔尔的追踪和生存之道，并会引导年轻的猎人前往剃刀岭寻找索塔尔，学习驯服野兽。",kw={"暗矛","杜隆塔尔","卡利·雷米克","森金村","猎人之路","追踪者","valley of spirits"},ang={["class:Hunter"]="对于年轻的兽人和巨魔神射手来说，卡利就像一块垫脚石，她能识别出你何时已经超出了村庄训练的水平，并派遣你前往剃刀岭寻找索塔尔。",["race:Troll"]="作为暗矛部族的成员，卡利时刻守护着她的族人，他们在杜隆塔尔海岸重建家园，并在奥格瑞玛的暗影裂口定居。"},sec={{t="狩猎指南",b="卡利·雷米克是一位经验丰富的丛林巨魔追踪者，对杜隆塔尔的荒凉旷野和部落的繁华中心了如指掌。在像森金村这样的沿海定居点，她看护着刚走出试炼谷、迈出人生第一步的年轻斥候。她能洞察新手何时已经超越了当地的训练水平，并及时介入，引导那些有前途的神射手前往剃刀岭寻找索塔尔，开启他们的兽王之路，确保部落边境的队伍时刻保持敏锐与纪律。"}},faq={{q="卡利·雷米克是谁？",a="卡利·雷米克是一位暗矛巨魔斥候和任务发布者。她协助指引初出茅庐的部落冒险者，特别是那些准备在当地哨所以外进一步提升训练的猎人。",al={"卡利·雷米克背景故事","谁是卡利·雷米克","卡利·雷米克npc"}},{q="在哪里可以找到卡利·雷米克？",a="她通常在杜隆塔尔帮助她的族人，尤其是在森金村附近。",al={"卡利·雷米克在哪里","卡利·雷米克位置","寻找卡利·雷米克"}},{q="她为猎人提供什么指导？",a="通过“猎人之路”任务，卡利引导那些证明了自己的基本技能的年轻兽人和巨魔猎人前往剃刀岭，在那里，索塔尔会指引他们走上驯服属于自己的野兽同伴的道路。",al={"猎人之路任务","卡利·雷米克猎人任务","卡利教导什么"}}},fx={f072d80b={q="卡利·雷米克效忠哪一方？",a="卡利·雷米克忠于暗矛部族，并坚定地支持萨尔的部落。她帮助自己的族人与盟友，引导年轻的荒野斥候和神射手接受适当训练，为他们的新家园效力。",al={"卡利·雷米克的阵营","卡利·雷米克为谁效力","卡利·雷米克是部落的吗"}},bd47d9e0={q="卡利·雷米克为什么在森金村？",a="卡利·雷米克留在森金村，守望着暗矛部族新兴的守卫者。在这片沿海浅滩，她帮助从往来的兽人和巨魔中发掘有潜力的年轻猎手，并指引他们去找能够磨练其生存技能的导师。",al={"卡利·雷米克为什么在这里","卡利·雷米克在森金村的职责","卡利·雷米克为何来到这里"}},a3912784={q="卡利·雷米克想要什么？",a="卡利·雷米克希望杜隆塔尔能由本领过硬的斥候和潜行者守护。她会寻找有志成为猎手的人，确保他们不会毫无准备地四处游荡，并为他们指明正确的道路，让他们找到能够传授荒野生存之道的训练师。",al={"卡利·雷米克想要什么","卡利·雷米克的动机","卡利·雷米克的目标是什么"}},["528bbb7d"]={q="卡利·雷米克与谁关系密切？",a="她与森金村的暗矛巨魔关系密切，并与杜隆塔尔的猎人训练师协同工作。她的职责将她与部落更广泛的生存网络联系在一起，确保新兵能在部落的领地内找到经验丰富的导师。",al={"卡利·雷米克与谁关系密切","卡利·雷米克的关系网","卡利·雷米克的盟友"}}},fp="10,259,20.489.0,18.173.0,30.78.0,40.206.0"}
P.entries["npc:kaltunk"] = {n="卡尔图克",s="卡尔图克是驻扎在杜隆塔尔试炼谷中心的一位兽人监工。对于踏入这个世界的年轻兽人来说，他是他们接触到的第一个人。他的职责是欢迎这些有抱负的勇士，并指引他们去完成为部落效力的初步任务。",h="卡尔图克是驻扎在杜隆塔尔试炼谷中心的一位兽人监工。对于踏入这个世界的年轻兽人来说，他是他们接触到的第一个人。他的职责是欢迎这些有抱负的勇士，并指引他们去完成为部落效力的初步任务。",kw={"杜隆塔尔","高内克","卡尔图克","兽人新手","试炼谷","你在世界中的位置"},ang={["faction:Horde"]="卡尔图克帮助维护在杜隆塔尔严酷的试炼场中保持秩序所需的实际纪律。",["race:Orc"]="对于每一个踏入卡利姆多的兽人来说，卡尔图克的生硬指令是他们开始赢得荣誉时听到的第一句话。"},sec={{t="第一步",b="卡尔图克站在试炼谷炎热的阳光下，注视着那些刚来到这里，希望能证明自己有资格加入部落的年轻人。当其他训练师和长者布置艰苦的试炼和狩猎仪式时，卡尔图克确保没有新兵在红色的尘土中漫无目的地徘徊。他发布直接的命令，指引新来者直接去找高内克，走上纪律之道。"},{t="山谷守卫者",b="试炼谷并非一个轻松的试炼场；它之所以被选中，就是为了磨练每一个走在峡谷底部的年轻人的力量和韧性。卡尔图克体现了这种粗犷的实用主义。他不会发表什么宏大的演说，也不会溺爱他人，而是期望每个兽人都能迅速找到自己在世界中的位置，并为大酋长分担重任。"}},faq={{q="卡尔图克是谁？",a="卡尔图克是驻扎在试炼谷的一位兽人监工。他是刚觉醒的兽人冒险者遇到的第一个人，负责指引他们找到导师并开始训练。",al={"卡尔图克职责","这个兽人是谁","卡尔图克npc"}},{q="卡尔图克为新冒险者做些什么？",a="他给新兵布置初步任务，指引他们去山谷里的其他地方找高内克谈话，以便他们开始真正的训练。",al={"卡尔图克任务","卡尔图克想要什么","试炼谷第一个任务"}},{q="我在哪里可以找到卡尔图克？",a="他就站在试炼谷中心训练帐篷和篝火附近，那是位于杜隆塔尔南部的一个与世隔绝的新手区。",al={"卡尔图克位置","寻找卡尔图克","卡尔图克在哪里"}},{q="他为什么驻扎在试炼谷？",a="他作为一名迎宾监工，确保新来的兽人新兵能够有组织地、迅速地踏上为萨尔的部落效力的道路。",al={"卡尔图克为什么在这里","卡尔图克目的"}}},fx={["7b0fd1f8"]={q="卡尔图克站在哪一边？",a="卡尔图克为部落效力，坚定服从大酋长萨尔的权威。他驻扎在试炼谷，专门迎接新来的兽人，并引导他们迈出为杜隆塔尔这个新国家效力的第一步。",al={"卡尔图克的阵营","卡尔图克为谁效力","卡尔图克是部落成员吗"}},["5cbb3fad"]={q="卡尔图克想要什么？",a="卡尔图克希望你向部落证明自己的价值。他确保未经考验的新来者不会无所事事，立即指引你去找高内克和试炼谷的监管者，让你尽快开始训练并为杜隆塔尔效力。",al={"卡尔图克需要什么","卡尔图克的目标","卡尔图克的动机"}}},fp="7,304,14.402.0,20.339.0,15.207.0,41.135.0,25.139.0,44.142.0"}
P.entries["npc:kam-deepfury"] = {n="卡姆·深怒",s="卡姆·深怒是一名臭名昭著的黑铁矮人破坏者，被关押在暴风城监狱深处。与监狱中大多数囚犯不同，他并不效忠于迪菲亚潜行者，他因策划了遥远北方萨多尔大桥上的一场毁灭性爆炸而被捕。",h="卡姆·深怒是一名臭名昭著的黑铁矮人破坏者，被关押在暴风城监狱深处。与监狱中大多数囚犯不同，他并不效忠于迪菲亚潜行者，他因策划了遥远北方萨多尔大桥上的一场毁灭性爆炸而被捕。",kw={"黑铁矮人","深怒","丹莫德","加玛森","卡姆·深怒","长须","暴风城监狱","暴风城","萨多尔大桥"},ang={["faction:Alliance"]="虽然暴风城大多数人的目光都聚焦在迪菲亚起义上，但深怒提醒着人们，更广泛的黑铁威胁正笼罩着联盟的北方边境。",["race:Dwarf"]="对于铁炉堡的矮人来说，卡姆·深怒是一个死敌，他的破坏活动切断了萨多尔大桥，并杀害了布莱德·长须的亲人。为这份损失复仇关乎个人的荣誉。"},sec={{t="远离家乡的破坏者",b="虽然监狱里挤满了心怀不满的石匠工会成员和迪菲亚叛军，但卡姆·深怒却是个异类。深怒是一名狡猾且暴力的黑铁矮人，他在策划了一场破坏北方关键基础设施的行动后被捕，并被带到了暴风城。他被锁在监狱深处的牢房里，虽然与黑石山下的族人隔绝，但他对联盟的敌意与走廊里任何一个叛乱暴徒毫无二致。"},{t="萨多尔大桥破坏案",b="Alliance intelligence stationed at Dun Modr, near the northern border of the Wetlands, identified Deepfury as the chief architect behind the explosion that shattered the Thandol Span. The blast severed one of the massive stone bridges linking the Wetlands to the Arathi Highlands. Beyond crippling a critical trade and military route for Ironforge and the Alliance, the sabotage claimed the life of a kin of the dwarf commander Longbraid the Grim."},{t="算一笔旧账",b="这名黑铁矮人叛乱分子没能长期逃脱惩罚，尽管在暴风城的监禁为他提供了躲避受害者亲属的临时庇护。在湿地，莫特雷·加玛森和悲痛欲绝的布莱德·长须一直在寻找愿意潜入暴乱监狱并割下深怒首级的雇佣兵，以了结这桩发生在数百英里外北方的血海深仇。"}},faq={{q="谁是卡姆·深怒？",a="卡姆·深怒是一名被关押在暴风城监狱里的精英黑铁矮人囚犯。他因策划了北方萨多尔大桥的破坏活动而闻名，与和他关在一起的迪菲亚叛军没有任何关联。",al={"卡姆·深怒是谁","卡姆·深怒背景故事","监狱里的矮人是谁"}},{q="为什么一名黑铁矮人会被关在暴风城监狱里？",a="深怒在协调了一次炸毁萨多尔大桥的袭击后被捕，那次袭击造成了矮人守卫死亡，并切断了湿地与阿拉希之间的一条重要陆路通道。他被送往暴风城的高安全级别监狱等待审判。",al={"他为什么在暴风城监狱","卡姆·深怒做了什么","他为什么被监禁"}},{q="卡姆·深怒是迪菲亚潜行者的一员吗？",a="不是。尽管他在监狱中与发动起义的迪菲亚潜行者关在一起，但深怒属于敌对的黑铁氏族。他的行为完全是基于其氏族针对联盟和铁炉堡的侵略议程。",al={"他是迪菲亚成员吗","卡姆·深怒与迪菲亚","深怒是否与范克里夫合作"}},{q="是谁想要卡姆·深怒死？",a="莫特雷·加玛森和驻扎在丹莫德的铁炉堡矮人部队想要他死。布莱德·长须在深怒炸毁萨多尔大桥的事件中失去了一位亲人，这促使他们向暴风城的冒险者传话，要求取下他的首级。",al={"谁发布了卡姆·深怒的任务","谁想要深怒死"}},{q="卡姆·深怒是在哪里犯下的罪行？",a="深怒是在萨多尔大桥组织的破坏活动，那是连接湿地与阿拉希高地的巨大桥梁群，位于暴风城遥远的北方。",al={"桥是在哪里被炸毁的","深怒炸桥事件","萨多尔大桥袭击"}},{q="在暴风城监狱里哪里可以找到卡姆·深怒？",a="卡姆·深怒被关押在暴风城监狱的牢房区，位于暴风城运河区下方。",al={"深怒在监狱的什么位置","卡姆·深怒位置"}}},fx={["1bde1b20"]={q="卡姆·深怒与谁结盟？",a="卡姆·深怒属于敌对的黑铁矮人氏族。尽管他与叛乱的扒手和囚犯一同关押在暴风城监狱，但他与迪菲亚潜行者毫无瓜葛。他完全效忠于自己那个行踪诡秘的氏族，为了深入袭击联盟控制的领土，他远离故土，来到北方活动。",al={"卡姆·深怒的关系","卡姆·深怒为谁做事","卡姆·深怒的阵营"}},["45416a5d"]={q="卡姆·深怒为何恶名昭著？",a="卡姆·深怒策划了萨多尔大桥上一座巨型石桥的灾难性爆炸，因此声名狼藉。这场暴力破坏不仅切断了湿地与阿拉希高地之间的重要通道，还夺去了布莱德·长须的一位矮人族人的性命。",al={"卡姆·深怒的名声","卡姆·深怒为何令人畏惧","卡姆·深怒做了什么"}}},fp="12,301,24.459.0,25.447.0,17.404.1,20.226.0,58.266.0,47.242.0,28.238.0,40.154.0,52.125.0"}
P.entries["npc:kanati-greycloud"] = {n="卡纳提·灰云",s="卡纳提·灰云是一位驻扎在千针石林白沙岗哨的牛头人猎人。他与他的猎友们一道，在忍受当地加拉克半人马不断挑衅的同时，尽可能地组织防御。",h="卡纳提·灰云是一位驻扎在千针石林白沙岗哨的牛头人猎人。他与他的猎友们一道，在忍受当地加拉克半人马不断挑衅的同时，尽可能地组织防御。",kw={"暗杀阴谋","半人马","加拉克","灰云","卡纳提","千针石林","白沙岗哨"},ang={["faction:Horde"]="白沙岗哨是俯瞰针林峡谷的关键制高点；确保卡纳提活着，就能保证部落侦察兵能持续监视半人马的军队动向。",["race:Tauren"]="对于穿越千针石林的牛头人来说，协助白沙岗哨的卡纳提，是对部落族人抵御其古老而苦涩的敌人——半人马的重要保卫行动。"},sec={{t="危险的栖木",b="卡纳提·灰云在千针石林西部高耸的砂岩尖塔顶端——白沙岗哨安营扎寨。虽然峡谷中猎物丰富、视野开阔，但它被加拉克半人马团团围住，这些半人马战团在下方那片干旱的平原上争夺着每一寸土地。卡纳提与其他牛头人猎人一起，监视着下方的峡谷，努力保护岗哨免受周围掠夺者残酷的侵袭。"},{t="半人马伏击",b="加拉克半人马不仅仅是想孤立白沙岗哨；他们意图彻底消灭这里的守军。半人马营地之间传递的信使携带明确的指令，旨在暗杀卡纳提和他的同伴。当加拉克突袭队冲上台地屠杀岗哨的猎人时，拦截这些行军命令并与卡纳提并肩作战，便成了来访旅客的职责所在。"}},faq={{q="卡纳提·灰云是谁？",a="卡纳提·灰云是一位常驻在千针石林西部白沙岗哨的牛头人猎人，他在那里设立营地，并防御当地掠食性威胁的侵扰。",al={"卡纳提是谁","卡纳提·灰云背景故事","白沙岗哨牛头人"}},{q="我在哪里能找到卡纳提·灰云？",a="卡纳提位于白沙岗哨，这是一个位于千针石林西部北部悬崖沿线的高处牛头人营地。",al={"卡纳提位置","卡纳提在哪里","灰云在哪里"}},{q="为什么加拉克半人马试图杀他？",a="加拉克半人马寻求对千针石林峡谷的绝对统治，并积极针对部落的岗哨。拦截到的命令揭示了一个半人马的协同阴谋，旨在暗杀卡纳提并瓦解岗哨的防御。",al={"为什么半人马攻击卡纳提","加拉克暗杀阴谋","为什么要保护卡纳提"}}},fx={["35c73e38"]={q="卡纳提·灰云站在哪一边？",a="卡纳提·灰云是一名效忠部落的牛头人猎人。他欢迎到访白沙岗哨的部落旅人，并依靠他们帮助营地抵御敌对势力的威胁。",al={"卡纳提的阵营","卡纳提是部落成员吗","卡纳提属于联盟还是部落"}},cf857b32={q="卡纳提·灰云想要什么？",a="卡纳提只希望自己的狩猎营地能安宁无事，并确保同伴们平安。当地的加拉克半人马企图赶走或屠杀所有闯入者，因此他最关心的是抵御他们的暗杀行动。",al={"卡纳提需要什么","卡纳提·灰云的目标","为什么要帮助卡纳提"}},["10a1bee5"]={q="卡纳提·灰云为什么在这里？",a="卡纳提和同伴们在白沙岗哨建立了一个狩猎营地，打算猎取千针石林的猎物。不幸的是，他们在峡谷中扎营，正好进入了敌对的加拉克半人马争夺的领地。",al={"卡纳提为什么在白沙岗哨","卡纳提在这里做什么","卡纳提·灰云的目的"}}},fp="16,218,18.433.0,14.426.1,24.160.0,34.146.0,45.224.0"}
P.entries["npc:kaplak"] = {n="卡普拉克",s="卡普拉克是一位兽人潜行者训练师，驻扎在杜隆塔尔中部的剃刀岭。他教导年轻的兽人和巨魔学习潜行、诡计和刀剑的艺术，让他们在前往奥格瑞玛之前做好为部落效力的准备。",h="卡普拉克是一位兽人潜行者训练师，驻扎在杜隆塔尔中部的剃刀岭。他教导年轻的兽人和巨魔学习潜行、诡计和刀剑的艺术，让他们在前往奥格瑞玛之前做好为部落效力的准备。",kw={"杜隆塔尔","卡普拉克","兽人","奥格瑞玛","剃刀岭","潜行者训练师","潜行","瑟佐克"},ang={["class:Rogue"]="对于离开试炼谷的年轻兽人和巨魔潜行者，卡普拉克会提供早期的专业训练，并将他们引向在奥格瑞玛运作的秘密网络。",["faction:Horde"]="卡普拉克默默地确保部落拥有技术娴熟的侦察兵、间谍和刺客，他们能够保卫杜隆塔尔并在常规战线之外执行任务。"},sec={{t="阴影中的导师",b="卡普拉克隐藏在剃刀岭的定居点中，担任着从试炼谷走出的新晋部落潜行者的启蒙导师。在崇尚正面交锋和冲锋陷阵的传统兽人文化中，卡普拉克传授的是生存所必需的更冷静、更低调的技能：隐秘跟踪、开锁以及从背后发动致命一击。当他的学生们在杜隆塔尔尘土飞扬的红色峡谷中结束学业后，他会指引他们前往北方的首都奥格瑞玛，在更资深的工会成员那里深造技艺。"}},faq={{q="卡普拉克是谁？",a="卡普拉克是一位驻扎在杜隆塔尔剃刀岭的兽人潜行者训练师。他负责训练那些刚离开试炼谷的兽人和巨魔新手潜行者，在将他们送往奥格瑞玛的高级训练师那里之前，传授给他们早期的潜行者技能。",al={"卡普拉克是谁","卡普拉克背景故事","剃刀岭的卡普拉克"}},{q="卡普拉克在哪里？",a="卡普拉克位于杜隆塔尔的中心定居点剃刀岭，通常与其他职业训练师一起待在当地的军营内或附近。",al={"卡普拉克在哪里","卡普拉克位置","寻找卡普拉克"}},{q="卡普拉克提供什么任务？",a="卡普拉克在潜行者冒险者成长过程中为他们提供帮助，引导他们去寻找高级训练师，或指派任务，例如让他们去寻找奥格瑞玛的瑟佐克。",al={"卡普拉克的任务","卡普拉克发布的任务"}}},fx={c5a92913={q="卡普拉克站在哪一边？",a="卡普拉克效忠部落，为杜隆塔尔的兽人效力。他驻扎在剃刀岭，指导萨尔的领地中初出茅庐的潜行者和斥候，磨练他们的本领，使他们能够保护兽人领地免遭半人马袭击、库尔提拉斯渗透者以及其他威胁这个新兴国家的势力侵扰。",al={"卡普拉克的阵营","卡普拉克属于联盟还是部落","卡普拉克为谁效力"}},d6e62700={q="卡普拉克为什么在剃刀岭？",a="卡普拉克驻扎在剃刀岭，训练年轻的兽人和巨魔，让他们学习潜行、下毒和伏击等隐秘技艺。新兵从试炼谷出发后，他会磨练他们的盗贼技艺，再将合格的斥候派往首都奥格瑞玛。",al={"卡普拉克为什么在这里","卡普拉克在杜隆塔尔的目的","卡普拉克在剃刀岭做什么"}},["044206c1"]={q="卡普拉克想要什么？",a="卡普拉克希望壮大部落盗贼的队伍。他在新来的新兵中寻觅狡黠、纪律严明且刀法迅捷的人；等有潜力的斥候完成初步训练后，他会指引他们去奥格瑞玛拜访瑟祖克等资深导师。",al={"卡普拉克的动机","卡普拉克的目标","卡普拉克需要什么"}}},fp="6,241,23.544.0,14.236.0,26.156.0,30.161.0"}
P.entries["npc:karang-amakkar"] = {n="卡拉恩·阿玛卡",s="卡拉恩·阿玛卡是一位兽人侦察兵，驻扎在灰谷岩石海岸边的佐拉姆加前哨站。他在部落领地的边缘地带活动，专注于遏制那些威胁到前哨站补给线和边界的暴力熊怪部落。穿越该前哨站的冒险者们依靠他提供的当地情报，在森林危险的局势中穿行。",h="卡拉恩·阿玛卡是一位兽人侦察兵，驻扎在灰谷岩石海岸边的佐拉姆加前哨站。他在部落领地的边缘地带活动，专注于遏制那些威胁到前哨站补给线和边界的暴力熊怪部落。穿越该前哨站的冒险者们依靠他提供的当地情报，在森林危险的局势中穿行。",kw={"灰谷","刺毛部族","熊怪","卡拉恩·阿玛卡","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="卡拉恩·阿玛卡为那些在灰谷西部地带闯荡的部落旅行者提供重要援助，发布任务以击退包围佐拉姆加前哨站的敌对生物。",["race:Orc"]="卡拉恩驻扎在远离杜隆塔尔的偏远前哨站，体现了兽人哨兵坚守危险边境的坚毅决心。"},sec={{t="在灰谷海岸",b="卡拉恩·阿玛卡身处佐拉姆海岸的佐拉姆加前哨站，在部落最脆弱的边境前哨之一为部落服务。这座营地面临着来自海洋、暗夜精灵以及内陆野生猛兽的持续压力。卡拉恩密切监视着东面道路周围敌对的原住民群体，以确保部落的信使和侦察小队不会被领土意识强烈的原住民部落伏击。"},{t="对付熊怪",b="卡拉恩将大部分注意力集中在古老森林中的原生熊怪种群上，尤其是刺毛部族。腐蚀和原始的敌意让这些熊怪陷入疯狂，卡拉恩指派有能力的战士去猎杀它们的领袖并清剿巢穴，以免这些部落组织起对佐拉姆加的袭击。"}},faq={{q="卡拉恩·阿玛卡是谁？",a="卡拉恩·阿玛卡是一位驻扎在灰谷海岸佐拉姆加前哨站的兽人任务发布者。他代表部落管理区域威胁，尤其是敌对的熊怪氏族。",al={"卡拉恩","卡拉恩是谁","卡拉恩·阿玛卡背景故事"}},{q="我在哪里可以找到卡拉恩·阿玛卡？",a="他位于灰谷西北岸，佐拉姆海岸边的佐拉姆加前哨站内。",al={"卡拉恩位置","卡拉恩·阿玛卡在哪里","卡拉恩·阿玛卡坐标"}},{q="卡拉恩·阿玛卡提供什么任务？",a="卡拉恩指派部落的冒险者对抗附近好战的熊怪部落，并指挥对刺毛部族之王的打击行动。",al={"卡拉恩任务","卡拉恩的任务","卡拉恩想要什么"}},{q="为什么卡拉恩担心熊怪？",a="灰谷的熊怪变得越来越野蛮和堕落，它们袭击旅行者，并威胁要切断佐拉姆加前哨站与该地区其他部落据点的联系。",al={"为什么要杀熊怪","灰谷熊怪威胁","刺毛部族威胁"}},{q="卡拉恩·阿玛卡和学徒阿玛卡有关系吗？",a="虽然他们有相同的氏族名或家族姓氏，但卡拉恩和学徒阿玛卡之间是否确有亲属关系尚无法证实。",al={"阿玛卡家族","学徒阿玛卡亲属关系","卡拉恩家族"}},{q="卡拉恩会直接与暗夜精灵作战吗？",a="卡拉恩在佐拉姆加的职责主要集中在领土防御和应对像刺毛熊怪这样的野外威胁上，针对暗夜精灵的公开军事行动则留给部落的其他指挥官。",al={"卡拉恩与暗夜精灵","卡拉恩阵营"}}},fx={b0298d21={q="卡拉恩·阿玛卡站在哪一边？",a="卡拉恩·阿玛卡效忠部落，在灰谷茂密的森林中直接为部落效力。他与其他兽人一同驻扎在海岸边的佐拉姆加前哨站，致力于保护部落哨站并平息当地的威胁，例如敌对的熊怪。",al={"卡拉恩·阿玛卡的阵营","卡拉恩是部落成员吗","卡拉恩的效忠对象"}},["481f1d87"]={q="卡拉恩·阿玛卡想要什么？",a="卡拉恩想要平息灰谷那些威胁部落立足之地的危险土著部族。他积极寻找能干的冒险者，击溃凶恶的熊怪，尤其是污木部族及其首领，以免他们袭击附近的营地。",al={"卡拉恩·阿玛卡的目标","卡拉恩想要什么","卡拉恩的动机"}},["7b1509e6"]={q="卡拉恩·阿玛卡为什么在灰谷？",a="卡拉恩驻扎在灰谷，支援部落在这片危机四伏的领土上扩张并巩固防御。他坐镇佐拉姆加前哨站，监视荒野，并指挥战士消灭威胁部落在佐拉姆海岸一带据点的敌对野兽部族。",al={"卡拉恩为什么在这里","卡拉恩·阿玛卡在灰谷的目的","卡拉恩为什么在佐拉姆加"}}},fp="14,367,25.418.0,25.342.0,22.190.0,32.102.0,37.135.0,41.190.0,46.136.0,43.210.0"}
P.entries["npc:kargal-battlescar"] = {n="卡加尔·战痕",s="卡加尔·战痕是一位驻守在贫瘠之地东部边界前沿哨所的兽人老兵。他负责守卫从杜隆塔尔通往此地的路口，评估新兵并指引有能力的战士深入这片领地，以加强部落的防御。",h="卡加尔·战痕是一位驻守在贫瘠之地东部边界前沿哨所的兽人老兵。他负责守卫从杜隆塔尔通往此地的路口，评估新兵并指引有能力的战士深入这片领地，以加强部落的防御。",kw={"贫瘠之地","战痕","征召","十字路口","杜隆塔尔","前沿哨所","卡加尔"},ang={["class:Warrior"]="作为一名久经沙场、身上布满战斗伤痕的老兵，卡加尔展现了部落前线战士在蛮荒边境所需的坚韧不拔。",["faction:Horde"]="对于刚离开杜隆塔尔的部落新冒险者而言，卡加尔·战痕是他们接触卡利姆多更广泛军事斗争的引路人，他为贫瘠之地各处酝酿的冲突集结着新兵。"},sec={{t="边界哨兵",b="卡加尔·战痕在前沿哨所守望，监视着将杜隆塔尔荒凉的红色平原与贫瘠之地广袤草原分隔开来的战略关口。当旅人和新晋冒险者跨过横跨怒水河的桥梁时，卡加尔会确保他们明白，在试炼谷受训的安逸日子已经结束了。贫瘠之地是一片充满纷争与危险的旷野，深受狂暴的野生动物、半人马突袭队和野猪人部族的困扰。卡加尔会检查过往的路人，将愿意服役的新兵征召入伍，并派他们前往十字路口，协助当地指挥官守卫边疆。"}},faq={{q="卡加尔·战痕是谁？",a="卡加尔·战痕是一位兽人战士，也是驻守在前沿哨所的前哨指挥官，该哨所位于从杜隆塔尔进入贫瘠之地的东部道路上。",al={"卡加尔·战痕","卡加尔","卡加尔是谁"}},{q="前沿哨所的目的是什么？",a="前沿哨所作为贫瘠之地的预警站和前线防御工事，用于应对杜隆塔尔边界和怒水河沿岸出现的威胁。",al={"前沿哨所的目的","为何要设立前沿哨所","这个哨所是什么"}},{q="卡加尔把新兵派往哪里？",a="卡加尔征召经过哨所的旅人，并指引他们沿着主路向西前往贫瘠之地的军事中心——十字路口。",al={"卡加尔任务目的地","卡加尔之后去哪","卡加尔把你派往何处"}}},fx={["81d05e56"]={q="卡加尔·战痕站在哪一边？",a="卡加尔·战痕坚定地站在部落一边。他守卫着贫瘠之地的东部边境，也就是杜隆塔尔与开阔平原的交界处，确保新来的新兵和旅人能在大酋长的旗帜下安全通过。",al={"卡加尔·战痕的阵营","卡加尔是部落成员吗"}},ffbc81ca={q="卡加尔·战痕想要什么？",a="卡加尔希望有能干的战士守卫边境，并支援十字路口不断壮大的聚居地。他指引从杜隆塔尔抵达的新征召兵加入防卫，抵御徘徊在平原一带的威胁。",al={"卡加尔·战痕的目标","卡加尔想要什么"}},e589e5e9={q="卡加尔·战痕为什么驻扎在这里？",a="卡加尔负责管理前沿哨所。这座设防的入口横跨怒水河，连接杜隆塔尔与贫瘠之地。他驻扎在此迎接一路向西的新征召兵，并指引他们前往部落最需要他们的地方。",al={"卡加尔为什么在前沿哨所","卡加尔·战痕驻扎此地的目的"}}},fp="17,276,22.656.0,25.157.0,42.171.0,36.161.0"}
P.entries["npc:karos-razok"] = {n="卡洛斯·拉佐克",s="卡洛斯·拉佐克是驻守在银松森林瑟伯切尔的被遗忘者蝙蝠管理员。他负责管理连接这个陷入争夺的前哨站与幽暗城及其他部落据点的亡灵飞行坐骑巢穴。",h="卡洛斯·拉佐克是驻守在银松森林瑟伯切尔的被遗忘者蝙蝠管理员。他负责管理连接这个陷入争夺的前哨站与幽暗城及其他部落据点的亡灵飞行坐骑巢穴。",kw={"蝙蝠管理员","飞行管理员","卡洛斯·拉佐克","瑟伯切尔","银松森林","幽暗城"},ang={["faction:Horde"]="对于向南前往希尔斯布莱德丘陵的部落旅行者来说，拉佐克的蝙蝠巢穴是洛丹伦西缘不可或缺的中转站。",["race:Undead"]="卡洛斯·拉佐克是你返回幽暗城的生命线，确保了银松森林的前线战事依然牢牢地与希尔瓦娜斯女王的首都紧密相连。"},sec={{t="瑟伯切尔的驭兽者",b="卡洛斯·拉佐克站在瑟伯切尔墓穴上方的木制平台上，照料着对被遗忘者通讯至关重要的骷髅蝙蝠。由于银松森林遍布月怒狼人、流亡的达拉然法师以及安伯米尔的人类残余势力，沿北部道路的陆路旅行危机四伏。拉佐克确保了信使、新兵和重要物资能够从受诅咒的林冠上方通行，使这条前线与提瑞斯法林地的首都保持直接联系。"}},faq={{q="卡洛斯·拉佐克是谁？",a="卡洛斯·拉佐克是驻守在银松森林瑟伯切尔的被遗忘者飞行管理员。他管理着一群受过训练的吸血蝙蝠，这些蝙蝠被部落冒险者和信使用于往返于洛丹伦各地。",al={"卡洛斯·拉佐克的作用","瑟伯切尔的飞行管理员是谁","瑟伯切尔蝙蝠管理员"}},{q="卡洛斯·拉佐克可以将旅行者送往何处？",a="拉佐克将瑟伯切尔与提瑞斯法林地的幽暗城以及希尔斯布莱德丘陵的塔伦米尔直接相连，从而促进了洛丹伦北部的快速交通。",al={"瑟伯切尔飞行航线","瑟伯切尔的蝙蝠飞往哪里","从瑟伯切尔出发的飞行路线"}},{q="拉佐克负责照料什么生物？",a="他负责照料大型骷髅飞行蝙蝠。这些亡灵野兽是耐劳且不知疲倦的飞行者，适应了洛丹伦被枯萎病侵蚀的天空，因其安静和耐力而深受被遗忘者的青睐。",al={"拉佐克有什么坐骑","被遗忘者飞行野兽","瑟伯切尔的飞行坐骑是什么"}},{q="为什么瑟伯切尔需要一名飞行管理员？",a="银松森林的道路上挤满了敌对势力，从焚木村的狼人诅咒到安伯米尔的人类巫师，不一而足。拉佐克提供了一条空中生命线，使被遗忘者能够在无需担心公路伏击的情况下为这个前哨基地提供补给。",al={"为什么需要瑟伯切尔蝙蝠管理员","瑟伯切尔旅行的重要性"}}},fx={db08745b={q="卡洛斯·拉佐克站在哪一边？",a="卡洛斯·拉佐克为被遗忘者和部落效力。他驻扎在银松森林，效忠希尔瓦娜斯·风行者女王和幽暗城，协助往来于该地区的被遗忘者信使、斥候和冒险者。",al={"卡洛斯·拉佐克的阵营","卡洛斯·拉佐克为谁效力","卡洛斯·拉佐克属于部落吗"}},["6a9fc34a"]={q="卡洛斯·拉佐克想要什么？",a="卡洛斯只想让天际保持畅通，确保被遗忘者的空中交通顺利运行。他负责管理瑟伯切尔的栖巢，确保补给、讯息和增援能够稳定地往来于银松森林与部落的其他据点之间。",al={"卡洛斯·拉佐克的目标","卡洛斯·拉佐克做什么","卡洛斯·拉佐克的动机"}}},fp="11,227,31.485.0,19.205.0,37.171.0,33.190.0,50.245.0"}
P.entries["npc:katie-hunter"] = {n="凯蒂·亨特",s="凯蒂·亨特是一位驻扎在艾尔文森林东部的东谷伐木场马厩的驯马师。她为暴风城的市民和联盟值得信赖的勇士提供训练有素的骑乘马匹和战马。她与兰道尔·亨特一同确保旅行者和士兵拥有可靠的坐骑，以便在王国的道路上通行。",h="凯蒂·亨特是一位驻扎在艾尔文森林东部的东谷伐木场马厩的驯马师。她为暴风城的市民和联盟值得信赖的勇士提供训练有素的骑乘马匹和战马。她与兰道尔·亨特一同确保旅行者和士兵拥有可靠的坐骑，以便在王国的道路上通行。",kw={"东谷","艾尔文森林","坐骑商人","凯蒂·亨特","伐木场","坐骑","马厩","暴风城"},ang={["faction:Alliance"]="在暴风城宫廷中获得高声望和尊重的同盟种族，可以获得骑乘凯蒂珍贵战马投入战斗的特权。",["race:Human"]="对于人类旅行者来说，凯蒂的马厩是成长的必经之路，一旦你掌握了基础的骑术，就可以购买经典的暴风城马匹。"},sec={{t="东谷马厩",b="凯蒂·亨特身处东谷伐木场安静的林间空地中，负责管理艾尔文森林内为有抱负的骑手准备的王国主要马匹存货。当伐木工人们为暴风城的重建采伐木材时，凯蒂则照料着马厩，培育着各种可靠的品种，包括花马、母马和迅捷的战马。她的马匹代表了王国传统的马术风格，能为勇闯艾泽拉斯南部危险道路的旅者提供忠实的伙伴。"}},faq={{q="凯蒂·亨特是谁？",a="凯蒂·亨特是暴风城王国的驯马师和坐骑商人，位于艾尔文森林东谷伐木场的马厩。",al={"凯蒂·亨特 艾尔文","谁是凯蒂·亨特","凯蒂·亨特 坐骑商人"}},{q="在哪里可以找到凯蒂·亨特？",a="她位于东谷伐木场的北部区域，在艾尔文森林东部的骑术训练师兰道尔·亨特附近照料着畜栏和马厩。",al={"凯蒂·亨特 位置","凯蒂·亨特在哪里","寻找凯蒂·亨特"}},{q="非人类种族可以从她那里购买马匹吗？",a="可以，但前提是他们必须在暴风城王国达到崇拜声望。人类冒险者则无需任何特殊声望即可购买她的马匹。",al={"矮人购买马匹","暗夜精灵马匹坐骑","暴风城声望坐骑"}},{q="她出售哪些马匹？",a="凯蒂提供标准的骑乘马——包括花马、棕马和栗色马品种——以及迅捷的装甲战马，例如迅捷褐色马、迅捷棕马和迅捷白马。",al={"凯蒂出售什么坐骑","凯蒂·亨特马匹种类"}}},fp="12,204,19.311.0,20.120.0,30.164.0,35.137.0,26.186.0"}
P.entries["npc:katrana-prestor"] = {n="女伯爵卡特拉娜·普瑞斯托",s="女伯爵卡特拉娜·普瑞斯托是暴风城的一位贵族女性，也是朝廷中最具影响力的人物之一。随着瓦里安国王失踪，她以值得信赖的顾问身份，站在了Stormwind Keep中的小国王安度因和伯瓦尔·弗塔根公爵身旁。",h="女伯爵卡特拉娜·普瑞斯托是暴风城的一位贵族女性，也是朝廷中最具影响力的人物之一。随着瓦里安国王失踪，她以值得信赖的顾问身份，站在了Stormwind Keep中的小国王安度因和伯瓦尔·弗塔根公爵身旁。",kw={"卡特拉娜","普瑞斯托","卡特拉娜·普瑞斯托","普瑞斯托女伯爵","顾问","stormwind keep","朝廷"},sec={{t="朝廷之声",b="女伯爵普瑞斯托数年前来到朝廷，并迅速成为最受信任的人物之一。暴风城的贵族们争相寻求她的青睐，而她的建议左右着许多以年轻国王名义做出的决策，此时正由伯瓦尔·弗塔根公爵担任摄政王。前来Stormwind Keep请求士兵或援助的请愿者们常发现，她的意见与摄政王的意见分量相当。"}},faq={{q="女伯爵卡特拉娜·普瑞斯托是谁？",a="女伯爵卡特拉娜·普瑞斯托是一位暴风城的贵族女性，也是朝廷中值得信赖的顾问。随着瓦里安国王失踪，她站在Stormwind Keep里小国王安度因和伯瓦尔·弗塔根公爵的身边，她在贵族中拥有极高的话语权。",al={"卡特拉娜·普瑞斯托是谁","普瑞斯托女伯爵是谁","卡特拉娜·普瑞斯托背景故事"}},{q="她为什么担任国王的顾问？",a="瓦里安国王的失踪使他年幼的儿子安度因登上了王位，并由伯瓦尔·弗塔根公爵担任摄政王。普瑞斯托女伯爵作为顾问坐在他们身边。朝廷的许多决策，包括暴风城如何回应其边远领地的援助请求，都要经过她的建议。",al={"普瑞斯托为什么在朝廷","卡特拉娜做什么"}},{q="我在哪里能找到普瑞斯托女伯爵？",a="她通常在Stormwind Keep的王座大厅里，站在伯瓦尔·弗塔根公爵和年轻的安度因国王附近。",al={"卡特拉娜·普瑞斯托在哪里","卡特拉娜·普瑞斯托位置"}}},fp="20,232,18.402.0,28.243.0,29.296.0,30.125.0"}
P.entries["npc:kaymard-copperpinch"] = {n="凯玛德·考伯宾奇",s="凯玛德·考伯宾奇是一位地精商人，在冬幕节期间代表烟林牧场驻扎在奥格瑞玛。他待在Valley of Strength，兜售节日商品并引导旅行者寻找节日欢乐和丢失的节日补给。他的生意兴隆，为部落主城带来了季节性的欢乐——以及地精的商业精神。",h="凯玛德·考伯宾奇是一位地精商人，在冬幕节期间代表烟林牧场驻扎在奥格瑞玛。他待在Valley of...",kw={"考伯宾奇","地精","凯玛德","梅森","奥格瑞玛","烟林牧场","valley of strength","冬幕节"},ang={["faction:Horde"]="对部落来说，凯玛德代表了奥格瑞玛冬幕节的商业一面，在传统的冬季庆祝活动和地精创业精神之间取得了平衡。",["profession:Cooking"]="凯玛德和他的烟林牧场同僚提供烘焙传统节日美食所需的食谱和特色配料。"},sec={{t="地精的冬幕节",b="每当冬幕节到来时，烟林牧场就会在奥格瑞玛繁华的Valley of Strength开设摊位，由进取心十足的凯玛德·考伯宾奇坐镇。当冬天爷爷在附近接见访客时，凯玛德会确保这个节日保持盈利。他出售高端零食、节日包装纸和节日必需品，体现了地精的观点：没有热闹的金币交易，任何盛大的文化节日都是不完整的。"},{t="节日麻烦",b="除了兜售节日商品外，凯玛德经常作为烟林牧场节日事故的联系人。从被盗的节日甜点运输，到驯鹿梅森的离奇失踪，凯玛德总是急切地招募部落冒险者来解决雪地里的麻烦，保证节日顺利进行。"}},faq={{q="凯玛德·考伯宾奇是谁？",a="凯玛德·考伯宾奇是一位隶属于烟林牧场的地精商人。在冬幕节期间，他在奥格瑞玛的Valley of Strength开展业务，出售优质的季节性商品，并为路人提供节日任务。",al={"凯玛德是谁","凯玛德·考伯宾奇背景故事","凯玛德做什么"}},{q="什么是烟林牧场？",a="烟林牧场是一个供应商联盟，负责处理艾泽拉斯各地冬幕节的食物、零食和季节性商品。他们为部落和联盟提供节日用品，同时赚取可观的利润。",al={"什么是烟林牧场","他为谁工作","烟林牧场背景故事"}},{q="我在哪里可以找到凯玛德·考伯宾奇？",a="他站在奥格瑞玛的Valley of Strength，就在冬幕节期间冬天爷爷所在的中央节日展示区附近。",al={"凯玛德位置","凯玛德·考伯宾奇在哪里","他在奥格瑞玛的哪里"}},{q="他为什么在节日期间寻求冒险者的帮助？",a="烟林牧场在冬幕节期间经常遇到后勤灾难，包括节日糖果被盗和他们珍贵的驯鹿梅森被绑架。凯玛德雇佣愿意帮忙的冒险者来收回资产，守护这一季的利润。",al={"凯玛德任务","冬幕节零食任务","部落梅森任务"}}},fx={["10a0163d"]={q="凯玛德·考伯宾奇效忠于哪一方？",a="凯玛德只为烟林牧场工作，那是一家地精商业企业。虽然他会在冬幕节期间把节日商铺设在奥格瑞玛中心，为部落顾客服务，但他真正效忠的是公司，并一心追求正当利润，而非部落的政治。",al={"凯玛德·考伯宾奇的阵营","凯玛德是部落的吗","凯玛德为谁工作"}},["699a38fb"]={q="凯玛德·考伯宾奇为什么在这里？",a="凯玛德在奥格瑞玛的力量谷开设了商铺，以庆祝冬幕节。每逢节日季，烟林牧场都会派遣商人前往各大主城，向欢庆节日的居民出售点心、包装纸、配方和时令特色商品。",al={"凯玛德为什么在奥格瑞玛","凯玛德在这里做什么","凯玛德在奥格瑞玛的目的"}}},fp="19,352,22.459.0,21.345.0,27.228.0,27.234.0,37.172.0,57.259.0"}
P.entries["npc:keeper-albagorm"] = {n="守护者奥巴格姆",s="守护者奥巴格姆是一位驻扎在宁静的石爪峰庇护所的丛林守护者。他深感石爪山脉南部地区遭受破坏的忧虑，于是征召旅行者来帮助治愈焦炭谷那片被烧焦的荒野。",h="守护者奥巴格姆是一位驻扎在宁静的石爪峰庇护所的丛林守护者。他深感石爪山脉南部地区遭受破坏的忧虑，于是征召旅行者来帮助治愈焦炭谷那片被烧焦的荒野。",kw={"塞纳留斯","焦炭谷","守护者奥巴格姆","丛林守护者","石爪山脉","石爪峰"},ang={["class:Druid"]="作为一名丛林守护者，奥巴格姆与塞纳里奥血统有着直接的联系，这使得他净化焦炭谷的努力对德鲁伊而言具有深刻的个人意义。",["faction:Alliance"]="奥巴格姆为在石爪峰暗夜精灵圣所中穿行的联盟部队提供庇护和指引。"},sec={{t="峰顶的守护者",b="守护者奥巴格姆栖身于石爪峰宁静的枝叶间，守护着卡利姆多的一处暗夜精灵圣所。作为塞纳留斯的众多子嗣之一，他敏锐地感知着自然世界的痛苦。他的注意力投向南方的焦炭谷，那里烟雾缭绕的废墟曾被一支贪婪的工业化机械军队付之一炬，如今又被血怒鹰身人占据，阻碍着植被的再生。奥巴格姆在他的圣所中不懈努力，试图阻止腐蚀的蔓延，并恢复这片受损森林的平衡。"}},faq={{q="守护者奥巴格姆是谁？",a="他是一位丛林守护者——塞纳留斯的半神子嗣之一——驻扎在石爪山脉的石爪峰。他是暗夜精灵和卡利姆多自然守护者的盟友。",al={"守护者奥巴格姆","奥巴格姆是谁","石爪山脉的奥巴格姆"}},{q="我在哪里可以找到守护者奥巴格姆？",a="他居住在石爪峰，这是一个位于石爪山脉西北角的联盟阵营德鲁伊避难所。",al={"守护者奥巴格姆的位置","奥巴格姆在哪里","奥巴格姆坐标"}},{q="守护者奥巴格姆需要什么帮助？",a="奥巴格姆试图修复焦炭谷遭受的破坏。他派遣有能力的冒险者进入那片充斥着灰烬的盆地，净化受损的土地，并驱逐那些阻碍自然重生的血怒鹰身人。",al={"守护者奥巴格姆的任务","奥巴格姆需要什么","收复焦炭谷"}}},fx={["23205c35"]={q="守护者奥巴格姆效忠于哪一方？",a="守护者奥巴格姆与暗夜精灵以及石爪峰的塞纳里奥德鲁伊并肩，为联盟勇士提供建议和指引。和所有塞纳留斯之子一样，他更深层的忠诚属于自然的平衡，并寻找愿意帮助治愈卡利姆多创伤土地的盟友。",al={"守护者奥巴格姆的阵营","奥巴格姆属于联盟还是部落","奥巴格姆友好吗"}},["28024e4a"]={q="守护者奥巴格姆为什么在石爪峰？",a="守护者奥巴格姆守望着石爪峰的圣所——这处重要的自然堡垒隐于高山之巅。他从这片庇护之地观察蔓延于周边地区的腐化与破坏，并指引值得信赖的旅人抵御污秽，修复附近焦炭谷遭受的创伤。",al={"奥巴格姆为什么在石爪峰","奥巴格姆在石爪峰的目的","守护者奥巴格姆的职责"}},["7aa8d5e1"]={q="守护者奥巴格姆与谁关系密切？",a="作为一名林地守护者，奥巴格姆是备受敬仰的塞纳留斯之子之一，他的神圣血脉将他直接与月之半神及自然法则联系在一起。在石爪山脉，他与当地的暗夜精灵哨兵以及驻守山巅的塞纳里奥守护者并肩而立。",al={"守护者奥巴格姆的关系","奥巴格姆的人际关系","奥巴格姆听命于谁"}}},fp="15,260,22.526.0,23.205.0,33.134.0,41.213.0"}
P.entries["npc:keeper-bel-dugur"] = {n="看守者贝尔杜加",s="看守者贝尔杜加是一位居住在幽暗城Apothecarium深处的博学被遗忘者。他通过委托探险队从艾泽拉斯各地回收黑暗典籍和魔法神器来服务他的人民。",h="看守者贝尔杜加是一位居住在幽暗城Apothecarium深处的博学被遗忘者。他通过委托探险队从艾泽拉斯各地回收黑暗典籍和魔法神器来服务他的人民。",kw={"apothecarium","贝尔杜加","看守者贝尔杜加","影牙城堡","乌尔之书","幽暗城"},ang={["class:Warlock"]="术士经常会接到贝尔杜加的请求，因为他的兴趣主要集中在危险的魔典、异界召唤和黑暗神秘学上。",["race:Undead"]="贝尔杜加看起来就像其他寻求禁忌知识以增强王国实力的博学被遗忘者一样，但他的真实抱负并不在于女妖之王的生存事业。"},sec={{t="黑暗圣物的收藏家",b="看守者贝尔杜加身处Apothecarium的研究员和培养皿之间，他派遣冒险者去艾泽拉斯各地找回危险的奥术和神秘圣物。他最感兴趣的物品之一是《乌尔之书》，这是一本关于被锁在影牙城堡内的异次元生物的传奇论著。虽然幽暗城中的许多人寻求魔法知识是为了治愈或利用亡灵的状况，但贝尔杜加所策划的收购似乎是为了发掘古老而禁忌的力量。"},{t="隐藏的忠诚",b="在他作为幽暗城研究员的平静外表下，隐藏着对世界末日教派暮光之锤的秘密忠诚。贝尔杜加布置的任务和研究课题悄悄地推进了该教派深奥的议程，在皇家药剂师学会和希尔瓦娜斯女王毫无察觉的情况下，获取了召唤术和虚空魔法的基础魔典。"}},faq={{q="在哪里可以找到看守者贝尔杜加？",a="看守者贝尔杜加位于幽暗城南部内环的炼金区域，即Apothecarium。",al={"看守者贝尔杜加位置","贝尔杜加在哪里","贝尔杜加地图"}},{q="为什么贝尔杜加想要《乌尔之书》？",a="《乌尔之书》包含了达拉然法师乌尔关于其他维度和野性狼人的基础研究。贝尔杜加试图利用这些禁忌的召唤原则，为他真正的主子服务，达成其黑暗阴谋。",al={"为什么需要乌尔之书","贝尔杜加如何处理乌尔之书"}},{q="看守者贝尔杜加效忠于希尔瓦娜斯女王吗？",a="表面上，他是被遗忘者的档案管理员和研究员，但他调查中流露出的细微暗示表明他的忠诚可能另有所属。",al={"贝尔杜加是邪恶的吗","贝尔杜加阵营","贝尔杜加侍奉谁"}},{q="他还给冒险者什么任务？",a="除了影牙城堡的《乌尔之书》外，贝尔杜加还指引旅行者寻找被遗忘的传说和禁忌的典籍，包括与古老仪式和禁忌知识相关的黑暗论著。",al={"贝尔杜加任务","看守者贝尔杜加任务"}}},fx={f8b2616f={q="看守者贝尔杜加是谁？",a="看守者贝尔杜加是一名驻扎在幽暗城药剂区的被遗忘者学者。表面上，他是一名沉默的档案管理员，为皇家药剂师协会收集晦涩典籍和失落的传说；实际上，他追求的秘学知识远远超出了普通药剂学的范畴，且十分危险。",al={"贝尔杜加是谁","看守者贝尔杜加的背景","看守者贝尔杜加是谁"}},["3453eee6"]={q="看守者贝尔杜加想要什么？",a="贝尔杜加寻找禁忌的奥术典籍、神秘学秘闻和黑暗力量遗物。他会派遣冒险者从影牙城堡取回《乌尔之书》等危险典籍，以及其他隐秘文献，以解开危险的古老魔法。",al={"贝尔杜加想要什么","看守者贝尔杜加的动机","贝尔杜加的目标"}},["43763d0f"]={q="看守者贝尔杜加为什么在幽暗城？",a="贝尔杜加住在幽暗城的药剂区，这里很适合那些想要避开窥探、钻研黑暗学识的人。从被遗忘者首都的安全之处，他指引流浪者前往世界上的危险角落，为自己的收藏寻回失落的文献。",al={"贝尔杜加为什么在幽暗城","看守者贝尔杜加为什么在这里","贝尔杜加为何身处此地"}},["5a26a87f"]={q="看守者贝尔杜加与谁关系密切？",a="除了在药剂区为被遗忘者效力之外，围绕他禁忌研究的一些细微线索和对话还暗示，他可能与隐秘的暮光之锤教派有关。该教派觊觎足以撼动世界的力量和末日秘闻。",al={"看守者贝尔杜加的人际关系","贝尔杜加为谁工作","贝尔杜加与暮光之锤"}}},fp="16,211,26.501.0,16.349.2,34.129.0,39.227.1,43.155.2,42.181.0"}
P.entries["npc:keeper-bel-varil"] = {n="看守者贝瓦里尔",s="看守者贝瓦里尔是一名被遗忘者看护者和研究员，驻扎在希尔斯布莱德丘陵的塔伦米尔。他与沃丁·虚光密切合作，指引部落冒险者从周边地区收集魔法遗物和束缚材料，以推进他们的神秘学研究。",h="看守者贝瓦里尔是一名被遗忘者看护者和研究员，驻扎在希尔斯布莱德丘陵的塔伦米尔。他与沃丁·虚光密切合作，指引部落冒险者从周边地区收集魔法遗物和束缚材料，以推进他们的神秘学研究。",kw={"贝瓦里尔","束缚护腕","希尔斯布莱德丘陵","看守者贝瓦里尔","石质徽记","塔伦米尔","沃丁·虚光"},ang={["faction:Horde"]="对于在希尔斯布莱德丘陵战斗的部落勇士，贝瓦里尔会以奖励回报那些制服元素威胁并找回束缚护符的人。",["race:Undead"]="贝瓦里尔的工作反映了被遗忘者对奥术掌控和足智多谋的追求，通过对地区遗物的仔细研究来巩固在洛丹伦的优势。"},sec={{t="塔伦米尔的研究",b="在饱受围困的塔伦米尔村，看守者贝瓦里尔默默支持着被遗忘者的魔法与炼金研究。当皇家药剂师和士兵忙于应付路那头的南海镇联盟驻军时，贝瓦里尔专注于实用巫术，派遣过客去回收附近元素和附魔威胁身上的石质徽记和束缚护腕。"}},faq={{q="看守者贝瓦里尔是谁？",a="看守者贝瓦里尔是一名驻扎在希尔斯布莱德丘陵塔伦米尔的被遗忘者学者。他协助同为研究员的沃丁·虚光检查在这片争议领土上发现的魔法神器和试剂。",al={"看守者贝瓦里尔","贝瓦里尔是谁","贝瓦里尔 塔伦米尔"}},{q="在哪里可以找到看守者贝瓦里尔？",a="他站在希尔斯布莱德丘陵北部的被遗忘者定居点塔伦米尔。",al={"贝瓦里尔位置","看守者贝瓦里尔在哪里","寻找看守者贝瓦里尔"}},{q="看守者贝瓦里尔提供什么任务？",a="他招募部落冒险者收集石质徽记和束缚护腕等魔法残余物，帮助他的圈子理解并操纵元素力量。",al={"贝瓦里尔的任务","看守者贝瓦里尔的工作"}}},fx={["07ee922c"]={q="看守者贝瓦里尔效忠于哪一方？",a="看守者贝瓦里尔效忠于被遗忘者和更广大的部落。他驻扎在塔伦米尔，与不死族同胞并肩守卫希尔斯布莱德丘陵，抵御联盟的侵扰，并协助同为被遗忘者的同僚开展战略研究。",al={"贝瓦里尔的阵营","贝瓦里尔是部落的吗","贝瓦里尔效忠于谁"}},["19ba277e"]={q="看守者贝瓦里尔想要什么？",a="贝瓦里尔寻找神秘材料和神器，以协助专门的奥术研究。为了帮助沃尔丁·虚凝在塔伦米尔的工作，他会招募旅人从周边地区的元素生物和遗迹中取回附魔遗物，例如石质符记和束缚护腕。",al={"贝瓦里尔的目标","贝瓦里尔需要什么","为什么要帮助贝瓦里尔"}},["4541a85d"]={q="看守者贝瓦里尔为什么驻扎在塔伦米尔？",a="看守者贝瓦里尔继续驻扎在塔伦米尔，以维护被遗忘者在希尔斯布莱德丘陵的领土和奥术利益。他与沃尔丁·虚凝等研究者协作，协调收集所需的魔法物资，巩固他们对抗附近敌人的据点。",al={"贝瓦里尔为什么在塔伦米尔","贝瓦里尔在希尔斯布莱德的目的","看守者贝瓦里尔为什么在这里"}},b0435467={q="看守者贝瓦里尔与谁关系密切？",a="看守者贝瓦里尔与另一位驻扎在塔伦米尔的被遗忘者学者沃尔丁·虚凝密切合作。贝瓦里尔担任助手和协调者，组织冒险者收集沃尔丁持续研究所需的特定材料和符记。",al={"贝瓦里尔的同伴","贝瓦里尔为谁工作","贝瓦里尔的人际关系"}}},fp="16,289,20.386.0,24.217.0,34.109.0,39.164.0"}
P.entries["npc:keldran"] = {n="科尔丹",s="科尔丹是一名驻扎在奥格瑞玛Valley of Spirits以北的兽人特工。他致力于为最终与联盟的外交铺平道路，协调针对恶魔残党的秘密打击，以证明现代部落已真正摒弃了燃烧军团。",h="科尔丹是一名驻扎在奥格瑞玛Valley of Spirits以北的兽人特工。他致力于为最终与联盟的外交铺平道路，协调针对恶魔残党的秘密打击，以证明现代部落已真正摒弃了燃烧军团。",kw={"联盟关系","火刃氏族","凄凉之地","科尔丹","玛乌林·碎骨","奥格瑞玛","塔卡塔·钢刃","valley of spirits"},ang={["class:Warlock"]="科尔丹针对火刃氏族的秘密战争强调了部落领导层是多么迫切地希望远离不受控制的恶魔腐蚀。",["faction:Horde"]="科尔丹代表了部落中那些具有前瞻性的部分，他们认识到如果要确保在卡利姆多实现持久和平，就必须摆脱恶魔带来的恶名。"},sec={{t="外交远征",b="当萨尔在智慧谷执政时，科尔丹在城市的红岩露台上工作，试图解决一场挥之不去的外交灾难。联盟仍然将所有兽人视为嗜血的恶魔傀儡，这种声誉在第一次战争期间就已根深蒂固。科尔丹确信连萨尔也对无休止的冲突感到厌倦，他认为只要卡利姆多还存在崇拜恶魔的邪教，真正的和平谈判就永远不会发生。在没有大酋长正式授权的情况下，他主动采取行动，指挥可信赖的代理人前往遥远的威胁地带，试图一劳永逸地清除恶魔的污点。"},{t="凄凉之地的战争",b="为了向联盟证明自己的观点，科尔丹将目标对准了凄凉之地的残酷荒原。他派遣塔卡塔·钢刃和玛乌林·碎骨前往那里，领导针对恶魔入侵的行动，并特别强调要消灭火刃氏族的邪教徒。通过铲除这些恶魔的追随者并将切实证据带回奥格瑞玛，科尔丹希望无可辩驳地证明，新的部落和人类与暗夜精灵一样，都是燃烧军团的敌人。"}},faq={{q="科尔丹是谁？",a="科尔丹是一位位于奥格瑞玛Valley of Spirits以北的兽人，他组织力量清除恶魔的影响，并为与联盟建立外交关系开辟道路。",al={"科尔丹是谁","科尔丹背景故事","科尔丹npc"}},{q="为什么科尔丹关心与联盟的关系？",a="科尔丹认为萨尔已经对与联盟的持续战争感到厌倦。他知道，只要联盟认为部落仍然与燃烧军团勾结，和平谈判就不可能实现。",al={"为什么建立联盟关系","科尔丹的动机","他为什么想要和平"}},{q="科尔丹是在执行萨尔的正式命令吗？",a="不。科尔丹的行动缺乏大酋长萨尔的正式授权，他选择独立行动，以洗清部落的污名并为未来的和平奠定基础。",al={"萨尔派遣了科尔丹吗","萨尔给科尔丹的命令","科尔丹是否获得授权"}},{q="科尔丹在凄凉之地做什么？",a="他派遣塔卡塔·钢刃和玛乌林·碎骨前往凄凉之地，以清除当地的恶魔势力，并果断根除火刃氏族邪教的存在。",al={"凄凉之地行动","为什么是凄凉之地","科尔丹与火刃氏族"}}},fx={b49902f3={q="科尔丹与谁并肩行动？",a="科尔丹与认同他和平愿景的部落忠诚干员并肩行动。为了执行针对凄凉之地恶魔崇拜者的策略，他依靠塔卡塔·钢刃和玛乌林·碎骨，指挥他们打击恶魔威胁，将火刃氏族逐出该地区。",al={"科尔丹的盟友","科尔丹与谁合作","科尔丹的同伴"}}},fp="7,277,20.591.0,19.487.1,15.181.0,56.212.0,49.177.0,34.166.0"}
P.entries["npc:kelm-hargunth"] = {n="凯尔姆·哈古斯",s="凯尔姆·哈古斯是战歌氏族的主要补给官和军需官，驻扎在贫瘠之地北界的莫尔杉营地。他负责为那些在战歌峡谷的纷争林地中对抗暗夜精灵的部落勇士提供装备。通过他的补给包和物资，他确保了前线的战争行动能够得到充分的补给。",h="凯尔姆·哈古斯是战歌氏族的主要补给官和军需官，驻扎在贫瘠之地北界的莫尔杉营地。他负责为那些在战歌峡谷的纷争林地中对抗暗夜精灵的部落勇士提供装备。通过他的补给包和物资，他确保了前线的战争行动能够得到充分的补给。",kw={"贫瘠之地","补给包","凯尔姆·哈古斯","莫尔杉营地","pvp商人","军需官","战歌峡谷","战歌氏族"},ang={["class:Warrior"]="前线战士非常依赖哈古斯提供的坚固板甲护腿、重型刀剑和作战口粮，以坚守防线对抗联盟。",["faction:Horde"]="凯尔姆·哈古斯为任何愿意在战歌峡谷拿起武器对抗暗夜精灵的部落士兵提供战争工具。",["race:Orc"]="对兽人而言，哈古斯通过确保战歌氏族的武器装备和口粮供应，使格罗姆·地狱咆哮在灰谷的遗产得以延续。"},sec={{t="莫尔杉军需官",b="凯尔姆·哈古斯伫立在俯瞰灰谷的土制壁垒上，负责监管战歌氏族在莫尔杉营地的后勤运作。当斥候和劫掠者在监狱外进行小规模冲突时，哈古斯管理着维持这场持久边境战争所需的武器、盔甲和口粮的流动。对他而言，对抗银翼要塞的胜利既取决于源源不断的补给，也取决于纯粹的战斗怒火。"},{t="支援前线",b="哈古斯将特种补给分发给在峡谷中证明了自身英勇的战士。从装满战地绷带和铁制口粮的定制补给包，到印有战歌氏族深红色徽记的大师级武器，他的库存严格留给那些为了部落在北部茂密林地的领土野心而流血牺牲的人。"}},faq={{q="凯尔姆·哈古斯是谁？",a="凯尔姆·哈古斯是一位代表战歌氏族的兽人补给官。他驻扎在贫瘠之地北部的莫尔杉营地，负责为在战歌峡谷作战的部落士兵分发武器、盔甲和作战物资。",al={"凯尔姆·哈古斯","凯尔姆是谁","莫尔杉商人","战歌商人"}},{q="凯尔姆·哈古斯在哪里？",a="他驻扎在莫尔杉营地，该营地位于贫瘠之地的最北端，紧邻通往灰谷的壁垒分界线。",al={"凯尔姆位置","凯尔姆·哈古斯在哪里","莫尔杉补给官位置"}},{q="凯尔姆·哈古斯效力于哪个阵营？",a="他效力于战歌氏族，这是部落的一支先锋部队，致力于在灰谷南部开采木材并从暗夜精灵手中夺取领土。",al={"凯尔姆阵营","战歌氏族军需官","凯尔姆为谁工作"}},{q="凯尔姆提供的补给包是什么？",a="哈古斯向前线战士发放初级、标准和高级补给包。这些补给包内含必要的战地杂物、绷带和口粮，以维持部落战斗人员在峡谷中的持续作战能力。",al={"氏族补给包","凯尔姆补给包","战歌补给包"}},{q="为什么莫尔杉营地对战歌氏族如此重要？",a="莫尔杉营地充当了贫瘠之地和灰谷之间的防御性集结地和检查站，使战歌氏族能够将补给、增援部队和采伐的木材安全地运送到部落领地。",al={"为什么要莫尔杉营地","莫尔杉用途","营地背景"}},{q="凯尔姆·哈古斯提供什么样的装备？",a="他为久经考验的战士提供战歌战袍，以及诸如斥候之刃和军团士兵之剑等特种武器、定制盔甲套装、戒指，以及旨在用于近距离冲突的战场药剂。",al={"凯尔姆pvp装备","战歌奖励","凯尔姆卖什么"}}},fx={["1810d113"]={q="凯尔姆·哈古斯为什么驻扎在莫尔杉营地？",a="凯尔姆·哈古斯是战歌氏族的补给官，驻守在灰谷边境的莫尔杉营地。他确保前往战歌峡谷的部落勇士装备齐全，能够与银翼要塞交战，并夺取重要的木材和领土。",al={"凯尔姆·哈古斯为什么在这里","凯尔姆·哈古斯的职责","凯尔姆为什么在莫尔杉营地"}},c16a55e1={q="凯尔姆·哈古斯想要什么？",a="凯尔姆只求部落在战歌峡谷彻底战胜暗夜精灵。作为战歌斥候的军需官，他要求你在战场上证明自己的勇气，并向那些重创联盟的勇士提供武器、补给和关怀包裹。",al={"凯尔姆·哈古斯想要什么","凯尔姆·哈古斯的目标","凯尔姆想要什么"}},bced0f9b={q="凯尔姆·哈古斯隶属于谁？",a="凯尔姆直接听命于战歌斥候——这支部落先锋正在灰谷的茂密森林中与敌人争夺控制权。他以战歌氏族和整个部落的名义行事，与守卫莫尔杉营地的前线部队紧密协作。",al={"凯尔姆·哈古斯的隶属关系","凯尔姆·哈古斯为谁效力","凯尔姆·哈古斯的阵营"}}},fp="13,368,25.422.0,19.376.0,21.229.0,31.145.0,38.150.0,39.217.0,54.220.0,45.216.0"}
P.entries["npc:kerlonian-evershade"] = {n="克罗尼亚·恒影",s="克罗尼亚·恒影是一位暗夜精灵利爪德鲁伊，正在黑海岸的古树之林中休整。他刚从翡翠梦境的长眠中苏醒，需要帮助穿越被腐蚀的荒野，以到达安全的迈斯特拉岗哨。",h="克罗尼亚·恒影是一位暗夜精灵利爪德鲁伊，正在黑海岸的古树之林中休整。他刚从翡翠梦境的长眠中苏醒，需要帮助穿越被腐蚀的荒野，以到达安全的迈斯特拉岗哨。",kw={"黑海岸","利爪德鲁伊","翡翠梦境","恒影","古树之林","克罗尼亚","觉醒的沉睡者"},ang={["class:Druid"]="德鲁伊冒险者会对克罗尼亚的困境感同身受，因为塞纳里奥议会的所有门徒都必须面对与翡翠梦境深度沟通所带来的沉重代价。",["race:NightElf"]="对于暗夜精灵旅行者来说，引导克罗尼亚意味着保护他们的一位古老捍卫者，他刚刚回到一个自第三次战争以来已经发生巨大变化的世界。"},sec={{t="在黑海岸苏醒",b="克罗尼亚·恒影属于利爪德鲁伊，他们是熊图腾的追随者，在兽穴中沉睡并与翡翠梦境沟通了数个世纪。利爪德鲁伊在第三次战争期间被唤醒。克罗尼亚在古树之林的古树下被发现，他仍未从长期休息带来的超自然困倦中摆脱。他当前最紧迫的任务是安全穿过黑海岸麻烦不断的森林，前往灰谷边境的迈斯特拉岗哨。"},{t="危险的旅程",b="离开古树之林的道路并不安全。黑木熊怪在暮光谷徘徊，而黑岸邪教徒则潜伏在通往灰谷的路上。由于睡眠导致身体虚弱，加上突如其来的疲劳，克罗尼亚需要依靠联盟的同情者来保护他，护送他南下，与他的暗夜精灵同胞会合。"}},faq={{q="克罗尼亚·恒影是谁？",a="克罗尼亚·恒影是一位驻扎在黑海岸古树之林附近的暗夜精灵利爪德鲁伊。他最近从翡翠梦境中苏醒，需要协助才能安全穿过森林。",al={"克罗尼亚是谁","克罗尼亚·恒影背景故事","古树之林的德鲁伊"}},{q="为什么克罗尼亚走着走着会睡着？",a="像许多在兽穴中沉睡了几个世纪的利爪德鲁伊一样，克罗尼亚仍受着翡翠梦境留下的昏沉状态困扰。他的身心尚未完全适应清醒的现实，从而导致他会突然陷入困倦。",al={"为什么克罗尼亚在睡觉","觉醒的沉睡者任务 德鲁伊","克罗尼亚困倦"}},{q="他要去哪里？",a="他寻求安全穿过南部前往迈斯特拉岗哨，这是一个位于黑海岸和灰谷边境的暗夜精灵前哨站，他可以在那里安全地休养。",al={"克罗尼亚的目的地","克罗尼亚去哪里","古树之林护送目的地"}},{q="什么是利爪德鲁伊？",a="利爪德鲁伊是能够变身为巨熊的暗夜精灵德鲁伊。他们引导力量、坚韧和野性之威，传统上守护着兽穴和暗夜精灵领地，同时在翡翠梦境中度过漫长的睡眠岁月。",al={"什么是利爪德鲁伊","利爪德鲁伊背景故事"}}},fx={["62482562"]={q="克罗尼亚·恒影属于哪一方？",a="克罗尼亚是与塞纳里奥议会以及联盟麾下达纳苏斯暗夜精灵结盟的利爪德鲁伊。他一心侍奉自然与翡翠梦境，也牵挂着那些守护卡利姆多古老林地的德鲁伊同袍。",al={"克罗尼亚的阵营","克罗尼亚是联盟成员吗","克罗尼亚·恒影属于哪一方"}},["9e991c8a"]={q="克罗尼亚·恒影想要什么？",a="克罗尼亚刚从翡翠梦境的漫长沉眠中醒来，只盼着平安回到迈斯特拉岗哨，与暗夜精灵同伴团聚。他深度入定后仍昏昏沉沉，穿越黑海岸也变得危机四伏。",al={"克罗尼亚的目标","克罗尼亚·恒影想要什么","克罗尼亚的目的"}},["4cb7152a"]={q="克罗尼亚·恒影为何在这里？",a="克罗尼亚前往迈斯特拉岗哨拜访利拉迪斯·月河途中，在古树之林停下小憩。他从翡翠梦境醒来后仍睡意未消，因此请求别人帮忙安全抵达目的地。",al={"克罗尼亚为何在黑海岸","克罗尼亚与古树之林","克罗尼亚为何在这里沉睡"}},["0418b012"]={q="克罗尼亚·恒影隶属于谁？",a="克罗尼亚属于利爪德鲁伊，这是塞纳里奥议会下属的一个教派，信奉熊灵并肩负守护荒野的职责。他也与驻扎在灰谷边境迈斯特拉岗哨的暗夜精灵有着亲族情谊，并共同承担守卫的职责。",al={"克罗尼亚所属教派","克罗尼亚的关系","克罗尼亚为谁效力"}}},fp="19,262,22.522.0,21.367.0,27.204.0,45.243.0,25.154.0,28.229.0"}
P.entries["npc:kernobee"] = {n="克努比",s="克努比是一名地精工程师，被困在诺莫瑞根深处破败的大厅中。在偶然发现了有关黑铁矮人蓄意破坏的危险秘密后，他遭到了俘虏，被打昏在地，并被丢弃在宿舍区的穴居人之中自生自灭。",h="克努比是一名地精工程师，被困在诺莫瑞根深处破败的大厅中。在偶然发现了有关黑铁矮人蓄意破坏的危险秘密后，他遭到了俘虏，被打昏在地，并被丢弃在宿舍区的穴居人之中自生自灭。",kw={"黑铁矮人","宿舍区","诺莫瑞根","克努比","棘齿城","超级钻机","廷克维兹"},ang={["profession:Engineering"]="工程师们一定能体会到，当涉及到竞争对手的蓝图时，像黑铁钻机这样的实验性地下机械是有多么危险。",["race:Gnome"]="对于那些为夺回家园而战的侏儒来说，克努比带来的情报是一个令人震惊的证据，证明了他们的灾难是黑铁矮人在阴影中从中作梗导致的。"},sec={{t="致命的发现",b="在陷落的侏儒之城进行交易或搜寻物资时，克努比发现了一个惊人的秘密：黑铁矮人直接参与了在城市下方挖掘的巨型超级钻机的建造与运作。他意识到这条情报价值连城且极其危险，于是试图立即逃往棘齿城，将消息传达给他的同伙廷克维兹。不幸的是，黑铁矮人在他逃脱之前抓住了他。"},{t="丢给穴居人",b="俘虏们并没有直接杀掉他，而是将克努比打昏，扔进了宿舍走廊对面Clean Zone旁的一间小房间里。被困在野蛮的穴居人和辐射尘埃之中，这位饱受摧残的地精只能完全依赖路过的冒险者来救醒他，并保护他直到他抵达安全地带。"}},faq={{q="克努比是谁？",a="克努比是一名地精特工，在诺莫瑞根的宿舍区被发现时处于昏迷状态。他与棘齿城的廷克维兹密切合作，在进入遗迹后遭到了伏击。",al={"这个地精是谁","克努比背景故事","关于克努比"}},{q="为什么克努比会被关在诺莫瑞根？",a="克努比发现黑铁部族正在秘密协助建造城市地下的超级钻机。为了掩盖他们的存在和破坏行为，黑铁矮人将他击昏并扔进宿舍区让他自生自灭。",al={"他为什么在这里","黑铁矮人为什么要抓他","为什么在宿舍区"}},{q="克努比向谁汇报？",a="他向廷克维兹汇报，这是一名驻扎在贫瘠之地中立港口城镇棘齿城的地精工程师。",al={"廷克维兹是谁","他要去哪里","棘齿城关联"}},{q="克努比在诺莫瑞根的什么位置？",a="他昏倒在宿舍区下层的一个侧边小房间里，位于Clean Zone的正对面，西侧。",al={"克努比位置","克努比在哪里","寻找克努比"}}},fx={["3c758521"]={q="克努比属于哪一方？",a="克努比隶属于热砂港，在中立港口棘齿城听命于技师维兹维克。他不为联盟或部落效力，而是为地精做事——在诺莫瑞根发现黑铁矮人的阴谋后，他便与这些潜伏者针锋相对。",al={"克努比属于联盟还是部落","克努比的阵营","克努比为谁效力"}},b63dca8d={q="克努比想要什么？",a="克努比只想活着逃出诺莫瑞根。他发现黑铁矮人参与建造了那台巨型超级钻机后，急需离开宿舍，逃出这座遭辐射污染的城市，好把发现报告给棘齿城的技师维兹维克。",al={"克努比打算做什么","克努比的目标","为何帮助克努比"}}},fp="8,253,18.470.0,19.335.0,16.180.0,42.247.0,28.119.0,40.149.0"}
P.entries["npc:keryn-sylvius"] = {n="科瑞恩·塞尔留斯",s="科瑞恩·塞尔留斯是一位人类潜行者训练师，驻扎在闪金镇Lion's Pride Inn的二楼。她藏身于旅店的Reading Room中，向初出茅庐的无赖们传授潜行和刃术的基础知识，同时也是暴风城情报部门的一名安静的联络人。",h="科瑞恩·塞尔留斯是一位人类潜行者训练师，驻扎在闪金镇Lion's Pride Inn的二楼。她藏身于旅店的Reading Room中，向初出茅庐的无赖们传授潜行和刃术的基础知识，同时也是暴风城情报部门的一名安静的联络人。",kw={"艾尔文森林","闪金镇","科瑞恩·塞尔留斯","lion's pride inn","潜行者训练师","军情七处"},ang={["class:Rogue"]="塞尔留斯是游荡在艾尔文森林中的潜行者新手的首要导师，最终会将他们引向位于暴风城的军情七处总部。",["faction:Alliance"]="她驻守在闪金镇十字路口的上方，帮助联盟在艾尔文森林的主要通道上保持警惕的目光。"},sec={{t="闪金镇中安静的存在",b="当Lion's Pride Inn的一楼挤满了喧闹的旅客和疲惫的城镇守卫时，科瑞恩·塞尔留斯却一直待在楼上安静的Reading Room里。她外表看上去并不起眼，却在默默观察着源源不断的道路流言，并担任着在艾尔文森林磨练技艺的潜行者们的当地导师。当有潜力的特工不再满足于当地的小偷小摸和路边诡计后，塞尔留斯会悄悄地指引他们前往暴风城，与军情七处取得联系。"}},faq={{q="我能在哪里找到科瑞恩·塞尔留斯？",a="她位于闪金镇Lion's Pride Inn的二楼，隐居在小小的Reading Room里。",al={"科瑞恩·塞尔留斯位置","科瑞恩在哪里","闪金镇潜行者训练师位置"}},{q="她提供什么服务？",a="科瑞恩·塞尔留斯是一位潜行者训练师，她传授新的技能，重置天赋专精，并为进阶中的潜行者提供指导。",al={"科瑞恩做什么的","她能训练我吗","科瑞恩·塞尔留斯职责"}},{q="她与军情七处有什么联系？",a="塞尔留斯是暴风城秘密情报网络的前期联络点，一旦有潜行者证明了自己的能力，她便会指引他们前往Old Town寻找马迪亚斯·肖尔大师和军情七处。",al={"科瑞恩 军情七处","她是军情七处成员吗","她为暴风城工作吗"}}},fp="13,230,29.379.0,31.104.0,29.114.0,38.171.0"}
P.entries["npc:khelden-bremen"] = {n="凯尔登·布雷门",s="凯尔登·布雷门是一位人类法师，驻守在艾尔文森林北郡修道院的二楼。他负责指导初出茅庐、为暴风城效力的奥术施法者进行最初的训练。",h="凯尔登·布雷门是一位人类法师，驻守在艾尔文森林北郡修道院的二楼。他负责指导初出茅庐、为暴风城效力的奥术施法者进行最初的训练。",kw={"奥术","艾尔文森林","雕文信件","凯尔登·布雷门","法师训练师","北郡修道院"},ang={["class:Mage"]="对于人类法师来说，凯尔登·布雷门代表了在继续前往暴风城的高塔进行进阶训练之前，迈向奥术学术的第一步。"},sec={{t="奥术导师",b="凯尔登·布雷门身处北郡修道院宁静的石墙之内，是人类新手法师的主要导师。当底层的神职人员和守卫们忙于武技和精神追求时，布雷门在楼上保持着安静的研究环境。在这里，他引导新手学习纪律、专注力以及在踏入艾尔文森林并最终前往暴风城的Mage Quarter之前，安全编织原始魔法能量所需的基本技巧。"}},faq={{q="凯尔登·布雷门是谁？",a="凯尔登·布雷门是艾尔文森林北郡修道院的常驻法师训练师。他指导刚觉醒的法师学习他们的第一个法术和基础的奥术研究。",al={"凯尔登是谁","布雷门","北郡法师训练师"}},{q="我能在哪里找到凯尔登·布雷门？",a="他位于北郡修道院的二楼。进入修道院，走上左侧第二个房间里的楼梯即可找到。",al={"凯尔登在哪里","凯尔登·布雷门位置","北郡法师训练师位置"}},{q="他对新冒险者扮演什么角色？",a="有抱负的人类法师在到达北郡时会被指引去找凯尔登，他们通常带着一封介绍信——雕文信件。他教授基本的一级法术，并帮助新手掌握他们的魔法天赋。",al={"凯尔登做什么","布雷门任务","雕文信件接收人"}}},fp="14,158,19.315.0,22.136.0,32.129.0,43.188.0"}
P.entries["npc:kil-hala"] = {n="基尔哈拉",s="基尔哈拉是一名丛林巨魔裁缝训练师，驻扎在贫瘠之地的十字路口。他擅长处理日常布料和奇异的编织材料，并为希望精进针线活的部落工匠提供指导。除了普通的丝线之外，他还为那些从灰谷的“欢笑姐妹”那里带来头发的年轻部落法师编织虚空花边长袍。",h="基尔哈拉是一名丛林巨魔裁缝训练师，驻扎在贫瘠之地的十字路口。他擅长处理日常布料和奇异的编织材料，并为希望精进针线活的部落工匠提供指导。除了普通的丝线之外，他还为那些从灰谷的“欢笑姐妹”那里带来头发的年轻部落法师编织虚空花...",kw={"贫瘠之地","十字路口","基尔哈拉","欢笑姐妹","虚空花边","裁缝","训练师"},ang={["faction:Horde"]="基尔哈拉在十字路口提供纺织品和贸易工艺训练，帮助装备那些在贫瘠之地开辟立足点的战团和旅客。",["profession:Tailoring"]="基尔哈拉是游历卡利姆多的部落裁缝学徒的重要一站，他教授制作工艺并提供编织奇异魔法长袍的任务。"},sec={{t="贫瘠之地的裁缝",b="基尔哈拉位于十字路口这个繁忙的中心地带，为往来的旅客和部落新兵提供他的裁缝技艺。虽然他的大部分工艺涉及常见的纺织布卷和适合干燥平原生活的服装，但他对稀有的魔法织物也颇有研究。作为对法师迪诺的人情回报，他会为那些带来“欢笑姐妹”（灰谷森林中的树妖）头发的年轻法师制作虚空花边长袍。"}},faq={{q="基尔哈拉是谁？",a="基尔哈拉是一名暗矛巨魔，也是位于贫瘠之地十字路口的裁缝训练师。他协助部落的贸易工匠学习布料编织和服装制作的基础知识。",al={"基尔哈拉身份","基尔哈拉是谁","十字路口裁缝"}},{q="我在哪里可以找到基尔哈拉？",a="他位于贫瘠之地的中心定居点十字路口，与其他部落贸易训练师在一起。",al={"基尔哈拉位置","基尔哈拉在哪里","基尔哈拉地点"}},{q="基尔哈拉会给裁缝什么任务？",a="他自己并不直接指派裁缝任务。由迪诺派遣的年轻部落法师会带给他来自“欢笑姐妹”的头发，这些树妖栖息在灰谷的林中树居附近，基尔哈拉会将这些头发为他们编织成虚空花边长袍。",al={"基尔哈拉任务","欢笑姐妹任务","虚空花边长袍"}}},fx={["5b372e18"]={q="基尔哈拉属于哪一方？",a="基尔哈拉忠于部落和自己的暗矛巨魔同胞。他驻扎在十字路口的中心，担任裁缝训练师，帮助那些穿行卡利姆多的旅人、战士和立志成为工匠的人装备自己。",al={"基尔哈拉属于部落还是联盟","基尔哈拉的阵营","基尔哈拉为谁效力"}},d6c7e4b6={q="基尔哈拉想要什么？",a="基尔哈拉希望与部落同胞分享编织和布料加工的专长。他训练有志成为裁缝的人，也应法师迪诺之请，为那些带来欢笑姐妹之发的年轻法师编织精美的虚空丝绸长袍。",al={"基尔哈拉的目标","基尔哈拉的目的","基尔哈拉需要什么"}},["218c0279"]={q="基尔哈拉为何在这里？",a="基尔哈拉住在十字路口，这里是连接杜隆塔尔、莫高雷和北方荒野的重要枢纽。他驻扎于此，便能为络绎不绝、穿行贫瘠之地的部落冒险者提供针线技艺和指导。",al={"基尔哈拉为何在十字路口","基尔哈拉为何在贫瘠之地","基尔哈拉在此地的原因"}}},fp="8,364,21.428.0,16.189.0,26.124.0,41.228.0"}
P.entries["npc:kin-weelay"] = {n="肯维雷",s="肯维雷是一位著名的暗矛巨魔巫医，驻扎在荆棘谷的格罗姆高营地。他是直接从奥格瑞玛被派往此地的，旨在为丛林中的部落先遣队提供神秘的援助与指引。他在灵性方面的专长对于解开黑暗巫毒并协助营救年轻的耶尼库至关重要。",h="肯维雷是一位著名的暗矛巨魔巫医，驻扎在荆棘谷的格罗姆高营地。他是直接从奥格瑞玛被派往此地的，旨在为丛林中的部落先遣队提供神秘的援助与指引。他在灵性方面的专长对于解开黑暗巫毒并协助营救年轻的耶尼库至关重要。",kw={"暗矛","格罗姆高","肯维雷","心灵之眼","荆棘谷","巫医","耶尼库"},ang={["faction:Horde"]="肯维雷向部落的战争努力展示了巨魔灵性主义的价值，为纯粹力量无法破解的威胁提供了魔法反制策略。",["race:Troll"]="对于暗矛巨魔来说，肯维雷代表了部族中最受尊崇的灵性权威之一，致力于消除他们丛林同胞所遭受的残酷诅咒。"},sec={{t="暗矛巫毒大师",b="肯维雷在暗矛巨魔中被公认为最强大的传统巫术修行者之一，他对灵魂、妖术和灵魂魔法有着极其深厚的造诣。当出现涉及先祖之灵或敌对巨魔附魔的棘手事务时，荆棘谷的部落斥候都会向他寻求帮助，以揭开那些魔法面纱。"},{t="格罗姆高任务",b="肯维雷是专门从奥格瑞玛尘土飞扬的街道上被派往南方，以支援格罗姆高营地的尼姆布亚。他的目的不仅仅是提供简单的军事支持；他还专注于打破施加在耶尼库身上的邪恶禁锢，耶尼库是沃金酋长所信任的血脉中被绑架的儿子。为了解除这种黑暗巫术，肯维雷正在寻找强大的试剂——最重要的是心灵之眼——以打造一颗能够释放被俘灵魂的灵魂宝石。"}},faq={{q="肯维雷是谁？",a="肯维雷是一位受人尊敬的暗矛巨魔巫医，驻扎在北荆棘谷的格罗姆高营地。他以精通灵性魔法和灵魂魔法而闻名，是被部落领导层从奥格瑞玛派来的。",al={"肯维雷背景故事","肯维雷是谁","格罗姆高巫医"}},{q="肯维雷为什么在荆棘谷？",a="他被派往格罗姆高营地是为了向尼姆布亚和当地的暗矛远征队贡献他的神秘才华，特别是为了寻找并从敌对的丛林巨魔手中救回年轻的耶尼库。",al={"为什么肯维雷在格罗姆高","肯维雷的目的"}},{q="肯维雷试图制造什么？",a="肯维雷试图获得一种被称为心灵之眼的遗物。他打算用他的巫术将其炼制成一颗灵魂宝石，用以捕获并安全保存耶尼库的灵魂，从而切断控制这个男孩的黑暗力量。",al={"肯维雷 心灵之眼","肯维雷制造什么"}},{q="肯维雷来自哪里？",a="他从奥格瑞玛出发，自暗矛部族加入部落并在回音群岛定居以来，那里一直保持着紧密的联系和强大的势力。",al={"肯维雷背景","肯维雷来自哪里"}},{q="他如何看待荆棘谷的其他巨魔部族？",a="他将敌对的丛林部族，如血顶巨魔和裂颅者，视为陷入暴力腐化仪式中的危险对手。他积极运用自己的巫术来对抗他们的妖术，并救回被窃取的暗矛族人。",al={"肯维雷与其他巨魔","肯维雷和血顶巨魔"}},{q="肯维雷研究什么样的物品？",a="肯维雷调查具有自然或妖术共鸣的当地奇物，包括神秘的歌唱水晶和敌对丛林巨魔佩戴的骨质项链，研究它们的巫毒以制定反制措施。",al={"肯维雷物品","歌唱水晶 肯维雷"}}},fp="10,308,26.324.0,23.444.1,18.227.0,40.201.0,36.222.0,32.146.0,57.216.0,41.219.0"}
P.entries["npc:kindal-moonweaver"] = {n="辛达尔·月纹",s="辛达尔·月纹是一位暗夜精灵，她隐居在菲拉斯崎岖山脉中一处隐蔽的角落，就在恐怖图腾营地以北。她对荒野中虐待野生动物的行为深感不安，因此时刻注视着下方具有侵略性的牛头人部族，并寻求帮助以解救被囚禁的野兽。她是耶尔卡·月纹的亲族，共同肩负着保卫森林中无辜生灵的使命。",h="辛达尔·月纹是一位暗夜精灵，她隐居在菲拉斯崎岖山脉中一处隐蔽的角落，就在恐怖图腾营地以北。她对荒野中虐待野生动物的行为深感不安，因此时刻注视着下方具有侵略性的牛头人部族，并寻求帮助以解救被囚禁的野兽。她是耶尔卡·月纹的亲...",kw={"厄运之槌","菲拉斯","所有生物的自由","恐怖图腾营地","秘道","耶尔卡·月纹","辛达尔·月纹"},ang={["class:Druid"]="德鲁伊会发现他们与辛达尔在保护森林生命和从残酷铁笼中解放自然之灵方面的专一奉献有着共同语言。",["class:Hunter"]="熟悉卡利姆多野兽的猎人们，能够尊重辛达尔保护野生幼崽并惩罚那些为运动或恶意而捕猎者的努力。",["race:NightElf"]="辛达尔体现了卡多雷对自然世界传统的忠诚，作为一个与世隔绝的守护者，保护着那些受到外部入侵者威胁的野兽。"},sec={{t="悬崖上的守望者",b="辛达尔·月纹栖身于厄运之槌以东，一处被树木半遮掩的狭窄蜿蜒山路上，秘密监视着下方的山谷。虽然菲拉斯的大部分地区都在部落、羽月要塞的暗夜精灵以及埃雷萨拉斯的古老废墟之间争夺，但辛达尔关注的是更局部、更迫切的残暴行径。在下方的山谷里，恐怖图腾部族经营着一个设防的营地，以非正当的理由捕获并圈禁当地的动物。从她隐蔽的监视点，辛达尔时刻留意着那些愿意闯入敌营并消除其中苦难的人。"},{t="对荒野的怜悯",b="辛达尔最关心的是菲拉斯的神圣平衡以及那些无法反抗残暴捕获者的温顺生物。她与亲族耶尔卡·月纹一道，致力于解放被关在笼子里的野兽，并照看因暴力盗猎而流离失所的幼崽。她并未参与宏大的领土战争，而是专注于怜悯之举：解救被囚禁的小精龙，并为一只孤儿小精龙寻找归宿。"}},faq={{q="辛达尔·月纹在哪里？",a="辛达尔藏身于菲拉斯北部的悬崖边，就在厄运之槌以东、恐怖图腾营地的上方。你可以通过找到一条隐藏的狭窄山路到达那里，这条山路在树丛后蜿蜒向上。",al={"辛达尔·月纹位置","如何找到辛达尔","辛达尔在哪里"}},{q="辛达尔·月纹是谁？",a="她是一位致力于菲拉斯动物福利和自然保护的隐居暗夜精灵。她监视着恐怖图腾营地，以阻止他们对当地野生动物的捕获。",al={"辛达尔背景故事","谁是辛达尔"}},{q="辛达尔在菲拉斯的目标是什么？",a="辛达尔想要解救附近恐怖图腾营地笼中被囚禁的生物，并确保孤儿荒野野兽得到营救，获得安全的庇护所。",al={"辛达尔任务目的","辛达尔为什么在这里"}},{q="辛达尔·月纹和耶尔卡·月纹有亲戚关系吗？",a="是的，辛达尔是耶尔卡·月纹的亲族。两人都拥有月纹这个姓氏，并协作在菲拉斯营救受到虐待和流离失所的林地生物。",al={"耶尔卡·月纹关系","辛达尔和耶尔卡"}},{q="辛达尔为什么要对抗恐怖图腾？",a="占据她山顶下方营地的恐怖图腾氏族正在捕获并囚禁菲拉斯的野生野兽。辛达尔致力于将这些生物从囚禁中解放出来，并惩罚那些捕获者。",al={"辛达尔恐怖图腾","恐怖图腾营地辛达尔"}},{q="辛达尔·月纹会为双方阵营提供任务吗？",a="不会。辛达尔的任务只提供给联盟，她会招募冒险者从恐怖图腾手中解救被囚禁的生物。",al={"辛达尔对部落友好吗","部落可以和辛达尔对话吗"}}},fp="17,391,26.598.0,23.447.0,35.210.0,25.182.0,33.174.0,51.175.0,37.191.0,53.131.0"}
P.entries["npc:kirge-sternhorn"] = {n="基尔格·锐角",s="基尔格·锐角是一位驻扎在贫瘠之地崎岖边境的牛头人。作为卡利姆多中部旅行者的稳固指引，他将初出茅庐的部落冒险者指引向北，前往十字路口这一重要的据点。",h="基尔格·锐角是一位驻扎在贫瘠之地崎岖边境的牛头人。作为卡利姆多中部旅行者的稳固指引，他将初出茅庐的部落冒险者指引向北，前往十字路口这一重要的据点。",kw={"贫瘠之地","十字路口","基尔格","南贫瘠之地","锐角","陶拉祖","牛头人"},ang={["faction:Horde"]="对于从南部地区走来的旅行者，基尔格充当了一个早期的路标，将他们指引向位于十字路口的更大的部落社区。",["race:Tauren"]="基尔格代表了舒哈鲁人沉稳好客的精神，引导着部落同胞和盟友穿过他们这片被视为新家园的严酷边境。"},sec={{t="贫瘠之地的旅者",b="贫瘠之地广袤且被太阳炙烤的平原对刚到来的漫游者来说是一项艰巨的挑战，而基尔格·锐角正是他们沿途的一位得力向导。他驻扎在中央道路的南侧，守护着往返于南部营地与卡利姆多腹地之间的旅行者。了解这里潜伏的野猪人掠夺者和漫游在草原上的凶猛野兽带来的危险，基尔格确保年轻的冒险者们能够站稳脚跟，并前往北方寻找集结在那里的更大规模的部落势力。"}},faq={{q="基尔格·锐角是谁？",a="基尔格·锐角是一位驻扎在贫瘠之地南部地带的牛头人漫游者和向导，他为在尘土飞扬的平原上穿行的部落旅行者提供帮助。",al={"基尔格·锐角背景故事","基尔格是谁","基尔格npc"}},{q="基尔格将旅行者派往何处？",a="基尔格将旅行者指引向北前往十字路口。那是贫瘠之地的中心枢纽，部落军队在那里协调整个地区的防御与探索工作。",al={"基尔格任务","前往十字路口基尔格","基尔格把你派去哪"}},{q="基尔格·锐角效忠于哪个阵营？",a="基尔格忠诚于部落及其牛头人同胞，为所有在该地区旅行的部落成员提供指引和援助。",al={"基尔格是部落的吗","基尔格的效忠"}}},fp="15,248,25.483.0,23.150.0,32.161.0,40.146.0"}
P.entries["npc:klannoc-macleod"] = {n="克兰诺克·马克雷德",s="克兰诺克·马克雷德是一位居住在勇士岛的强悍人类战士，勇士岛位于贫瘠之地的东海岸外。他以武艺仲裁者的身份而闻名，会考验那些来自联盟和部落、寻求精通战斗姿态的勇士。那些赢得他尊重的人会被指引去往更远的内陆，接受更艰巨的力量试炼。",h="克兰诺克·马克雷德是一位居住在勇士岛的强悍人类战士，勇士岛位于贫瘠之地的东海岸外。他以武艺仲裁者的身份而闻名，会考验那些来自联盟和部落、寻求精通战斗姿态的勇士。那些赢得他尊重的人会被指引去往更远的内陆，接受更艰巨的力量试...",kw={"贫瘠之地","狂暴","勇士岛","岛民","克兰诺克","马克雷德","混战试炼","战士"},ang={["class:Warrior"]="克兰诺克·马克雷德是战士旅程中的关键人物，他在混战试炼中测试你的耐力和凶猛，随后指引你迈向精通狂暴姿态的道路。",["faction:Alliance"]="联盟战士必须深入卡利姆多位于贫瘠之地海岸外的水域，才能找到克兰诺克，并在勇士岛上证明他们的战斗准备度。",["faction:Horde"]="尽管他是人类，但克兰诺克对阵营对立漠不关心，欢迎前来他的孤岛寻求试炼与荣耀的部落战士。"},sec={{t="勇士岛的主宰",b="克兰诺克·马克雷德隐居在贫瘠之地商旅海岸外的勇士岛上，为经验丰富的战士监管着一个残酷的试炼场。尽管他是人类，但克兰诺克不受联盟和部落之间常见的政治纷争影响，他只通过勇士的勇气、剑术和在战火中的决心来评判参赛者。"},{t="混战试炼",b="被指引至勇士岛的战士们必须经受马克雷德的试炼：混战试炼。在克兰诺克的注视下，参赛者需踏上一块凸起的铁格栅，忍受一波又一波渴望战斗的挑战者的攻击。那些能抵挡住猛攻并击败他所选冠军的人，将赢得他的认可，证明自己具备了进行狂暴姿态训练所需的性情。"}},faq={{q="克兰诺克·马克雷德是谁？",a="克兰诺克·马克雷德是一位居住在勇士岛上的资深人类战士，该岛就在贫瘠之地海岸外。他担任着战士们的导师和试炼大师，帮助他们测试极限并解锁新的技巧。",al={"克兰诺克是谁","克兰诺克·马克雷德背景故事","勇士岛的人"}},{q="我在哪里可以找到克兰诺克·马克雷德？",a="克兰诺克位于勇士岛上，这是一座位于贫瘠之地东海岸外的岩石岛屿，位于商旅海岸和棘齿城的东南方。你必须游过开阔的水域才能到达他的营地。",al={"克兰诺克位置","勇士岛在哪里","如何前往克兰诺克处"}},{q="为什么人类会和勇士岛上的部落玩家交谈？",a="克兰诺克游离于传统的联盟和部落冲突之外。作为一名独立的战斗大师，他只关心武术纪律和战士精神，乐意考验任何带着合适推荐信前来的挑战者。",al={"克兰诺克对部落敌对吗","为什么克兰诺克是中立的","部落 克兰诺克"}},{q="什么是混战试炼？",a="混战试炼是勇士岛上举行的一场耐力试炼。战士必须站在克兰诺克的战斗平台上，击败一波波挑战者，最后还要与“大个子”威利战斗，以证明他们具备了学习高级战士技巧所需的凶猛劲头。",al={"混战试炼任务","勇士岛试炼","克兰诺克试炼"}},{q="为什么要将战士派往克兰诺克·马克雷德那里？",a="艾泽拉斯各地的战士训练师会将他们最有前途的学生推荐给克兰诺克进行武力坚韧度试炼，这对于准备学习狂暴姿态的专注力量至关重要。",al={"勇士岛战士任务","为什么拜访克兰诺克","狂暴姿态任务"}},{q="混战试炼结束后，克兰诺克会将你派往何处？",a="在混战试炼中证明了自己的实力后，克兰诺克会指引战士们向北前往塔伦米尔附近的奥特兰克山脉，寻找捕风者巴斯拉以寻求进一步的指导。",al={"克兰诺克之后","捕风者任务","捕风者是谁"}}},fx={bf19a78f={q="克兰诺克·马克雷德想要什么？",a="克兰诺克负责监督勇士岛上的战斗试炼，只招收有本事参加斗殴赛的斗士。他不在意阵营或出身，只要求前来求教的人先在艰苦的战斗中证明自己的实力和耐力，然后才会指引他们接受更高阶的武技训练。",al={"克兰诺克·马克雷德想要什么","克兰诺克想要什么","克兰诺克的目的"}}},fp="15,346,25.330.0,10.352.0,23.214.0,33.185.0,54.232.0,19.252.0,37.191.0,46.174.1"}
P.entries["npc:kor-ghan"] = {n="考格汉",s="考格汉是一名暗矛丛林巨魔，他徘徊在奥格瑞玛大断崖那阴暗的洞穴中。他站在雷库尔的毒药店外，寻求帮助以调制应对野生剧毒掠食者的解毒剂。",h="考格汉是一名暗矛丛林巨魔，他徘徊在奥格瑞玛大断崖那阴暗的洞穴中。他站在雷库尔的毒药店外，寻求帮助以调制应对野生剧毒掠食者的解毒剂。",kw={"解毒剂","cleft of shadow","考格汉","奥格瑞玛","雷库尔的毒药","蝎虫毒素","森金村"},ang={["class:Rogue"]="考格汉就站在大断崖雷库尔的毒药店外，对于那些为了试剂和毒药而来到奥格瑞玛腹地的潜行者来说，他是一个熟悉的身影。",["race:Troll"]="像许多离开森金村的暗矛族人一样，考格汉将他对杜隆塔尔野外危险的实际知识运用在了部落这座防御森严的首都之中。"},sec={{t="阴影中的巨魔",b="考格汉站在大断崖那幽深的洞穴中，雷库尔的毒药店前，密切关注着各种药物和毒素。他从这座主城派遣冒险者前往红色峡谷，从杜隆塔尔的蝎虫身上收集毒素成分，以备制备关键的解毒剂。"}},faq={{q="考格汉是谁？",a="考格汉是一名位于奥格瑞玛大断崖的暗矛巨魔，站在雷库尔的毒药店外。",al={"考格汉","考格汉是谁","考格汉npc"}},{q="我在哪里能找到考格汉？",a="他位于奥格瑞玛中心下方的地底大断崖中，驻守在雷库尔的毒药店正前方。",al={"考格汉位置","考格汉在哪里","寻找考格汉"}},{q="考格汉需要什么帮助？",a="他招募旅者从徘徊在奥格瑞玛入口附近的毒尾蝎虫身上收集毒囊，以帮助配制解毒剂。",al={"考格汉任务","寻找解毒剂任务","考格汉毒素"}},{q="考格汉以前在杜隆塔尔出现过吗？",a="他本人没有。考格汉一直守在奥格瑞玛的毒药供货商附近，但他派遣冒险者进入杜隆塔尔，从城市入口附近的毒尾蝎虫身上收集毒囊。",al={"考格汉森金","考格汉旧位置"}}},fx={["041d8a17"]={q="考格汉为什么会在这里？",a="考格汉在暗影裂口阴森深处、雷库尔的毒药店外安顿下来。他混迹于城中的盗贼行当从业者和炼金师之间，向那些调制危险混合物的人寻求专门援助和致命毒剂。",al={"考格汉为什么在奥格瑞玛","考格汉为什么在暗影裂口","考格汉为何来到这里"}},["8434b88c"]={q="考格汉属于哪一方？",a="考格汉效忠部落。他是一名暗矛丛林巨魔，居住在奥格瑞玛深处的暗影裂口，坚定地支持自己的族人，以及他们在大酋长萨尔领导下共同建立的新家园。",al={"考格汉的阵营","考格汉是部落成员吗","考格汉属于联盟还是部落"}}},fp="8,246,22.296.0,16.113.0,26.125.0,34.138.0,35.197.0"}
P.entries["npc:korran"] = {n="科兰",s="科兰是一名驻扎在贫瘠之地十字路口的暗矛巨魔研究员。他效力于奥格瑞玛的贝尔戈洛姆·石槌，负责监视这片灌木丛生之地发生的异常事件，并研究正在涌现的虫族异种蝎威胁。",h="科兰是一名驻扎在贫瘠之地十字路口的暗矛巨魔研究员。他效力于奥格瑞玛的贝尔戈洛姆·石槌，负责监视这片灌木丛生之地发生的异常事件，并研究正在涌现的虫族异种蝎威胁。",kw={"贫瘠之地","贝尔戈洛姆·石槌","十字路口","搜集虫卵","巨人旷野","科兰","异种蝎"},ang={["faction:Horde"]="科兰代表了部落在卡利姆多变幻的生态中保持警惕的眼睛，确保像异种蝎这样的新威胁不会在奥格瑞玛巩固边界时对其造成突袭。",["race:Troll"]="作为一名暗矛巨魔，科兰将敏锐的侦察和生存本能带到了干旱的贫瘠之地，并运用实用的狡黠来剖析这些陌生的外星野兽。"},sec={{t="十字路口的斥候",b="虽然十字路口的大多数人都忙于应付富有攻击性的野猪人和当地的半人马氏族，但科兰却时刻关注着那些更细微、更隐蔽的威胁。这名巨魔斥候奉奥格瑞玛的贝尔戈洛姆·石槌之命驻扎于此，观察着这片土地的变化，并为部落的领导层协调情报收集工作。"},{t="异种蝎入侵",b="科兰目前的主要关注点已经转向了南部的巨人旷野，被称为异种蝎的奇怪虫族生物已开始在那里的地下掘洞。由于它们极具攻击性的天性和迅速的扩张而感到不安，他招募路过的冒险者使用他的爪状工具挖掘出完整的虫卵，试图破译这些虫群的起源，以及它们对年轻的部落构成了怎样的危险。"}},faq={{q="科兰是谁？",a="科兰是一名驻扎在贫瘠之地十字路口的暗矛巨魔。他担任观察员和研究员，向奥格瑞玛的贝尔戈洛姆·石槌汇报情况。",al={"科兰是谁","巨魔科兰","十字路口的巨魔"}},{q="科兰在贫瘠之地调查什么？",a="他正在调查出现在南贫瘠之地巨人旷野的奇怪、富有攻击性的虫族生物——异种蝎，以及据报在更南边的千针石林出现的类似虫群。",al={"科兰研究什么","科兰的研究","巨人旷野的昆虫"}},{q="科兰为谁工作？",a="科兰效力于贝尔戈洛姆·石槌，这是一位驻扎在奥格瑞玛Valley of Honor的资深战士，他负责为部落监视卡利姆多各地不断涌现的威胁。",al={"谁派出的科兰","科兰的上级","贝尔戈洛姆·石槌"}},{q="科兰为什么需要异种蝎卵？",a="他需要完整的虫卵来研究异种蝎虫群的生命周期和起源。通过研究早期的样本，科兰希望能了解这些生物的本质，并确定它们对部落领土构成了多大的威胁。",al={"为什么需要异种蝎卵","搜集虫卵任务","科兰的爪状工具"}}},fx={b07b8377={q="科兰效忠哪一方？",a="科兰是驻扎在十字路口的部落忠诚斥候。他直接向奥格瑞玛的重要军官贝尔戈洛姆·石槌汇报，让酋长及时获知贫瘠之地各处的异常动向。",al={"科兰所属阵营","科兰是部落吗","科兰的效忠对象"}}},fp="6,229,25.335.0,22.389.0,14.158.0,44.220.0,25.157.0,35.226.0"}
P.entries["npc:kravel-koalbeard"] = {n="克拉维尔·浓须",s="克拉维尔·浓须是一位在闪光平原的沙漠赛道常驻的狡猾矮人企业家和骗子。他并不是因为热爱这项运动而欢呼，而是将地精与侏儒之间激烈的赛车竞争视为填满自己腰包的绝佳机会。从搜寻零散的机器零件，到通过勒索和酒精操纵比赛结果，克拉维尔总是在寻找下一个赚钱的门路。",h="克拉维尔·浓须是一位在闪光平原的沙漠赛道常驻的狡猾矮人企业家和骗子。他并不是因为热爱这项运动而欢呼，而是将地精与侏儒之间激烈的赛车竞争视为填满自己腰包的绝佳机会。从搜寻零散的机器零件，到通过勒索和酒精操纵比赛结果，克拉维...",kw={"勒索","浓须","克拉维尔","沙漠赛道","火箭车","破坏","闪光平原","千针石林"},ang={["class:Rogue"]="潜行者们会发现克拉维尔的生意非常熟悉：偷窃、破坏、勒索，以及在阴影中操纵那些贪婪的目标。",["race:Dwarf"]="与铁炉堡那些诚实的矿工、勘探员和登山者不同，克拉维尔是一个厚颜无耻的无赖和骗子，他让传统的矮人价值观蒙羞。",["race:Gnome"]="侏儒们在克拉维尔身边时应该密切留意自己的饮料和蓝图，因为他不仅热衷于破坏侏儒的机器，也同样急于给侏儒飞行员下药。"},sec={{t="平原上的骗子",b="虽然沙漠赛道的大多数观众和工作人员都沉迷于机械竞争和火箭引擎的轰鸣声中，但克拉维尔·浓须的目光却紧盯着每个人的钱袋。他是一个机会主义者，在赛道营地的尘土中运作，总是急于提供那些动机不纯的合同和帮助。在克拉维尔眼中，侏儒工程师与地精工程师之间的高风险冲突并非一场令人振奋的比赛，而是敲诈、破坏和盗窃的肥沃土壤。"},{t="操纵赛道",b="克拉维尔的行动远不止在盐碱地上捡拾废弃的垃圾。为了操纵赔率并确保结果对自己有利，克拉维尔常常派遣乐意效劳的冒险者去执行非法任务——散布谣言、策划勒索，甚至在对决前灌醉维修团队。无论是用烈酒诱惑地精技师，还是偷偷给侏儒飞行员灌下强效酒，只要能在比赛日填满自己的腰包，克拉维尔不惜使用任何卑鄙手段。"}},faq={{q="克拉维尔·浓须是谁？",a="克拉维尔·浓须是一位常驻在闪光平原沙漠赛道的矮人阴谋家和机会主义者。他利用侏儒与地精之间的竞争，通过打捞垃圾、操纵比赛和敲诈勒索来中饱私囊。",al={"克拉维尔是谁","克拉维尔·浓须的身份","沙漠赛道的矮人"}},{q="克拉维尔·浓须在沙漠赛道做什么？",a="克拉维尔雇佣旅行者在赛道周围跑腿，执行一些见不得人的勾当。他的计划包括收集火箭车零件、挖掘勒索素材，并通过灌醉维修技师和飞行员来破坏车队，从而影响比赛结果。",al={"克拉维尔的目的","克拉维尔想要什么","克拉维尔的阴谋"}},{q="为什么克拉维尔要灌醉参赛人员？",a="克拉维尔在火箭车比赛的结果上下了重注。通过在比赛开始前让侏儒或地精醉倒，他操纵比赛以确保结果能为他带来最大的利润。",al={"灌醉侏儒任务","灌醉地精","克拉维尔的破坏行为"}},{q="在哪里可以找到克拉维尔·浓须？",a="他位于千针石林的闪光平原，就徘徊在沙漠赛道繁忙的维修站营地附近。",al={"克拉维尔的位置","在哪里找到克拉维尔","克拉维尔千针石林"}},{q="克拉维尔在千针石林之外有关系吗？",a="有。他那些肮脏的交易涉及地精港口棘齿城和藏宝海湾的联系人，包括与棘齿城的码头管理员迪兹维格的往来、散布谣言者，以及来自荆棘谷的异域美酒。",al={"克拉维尔藏宝海湾","克拉维尔的关系网"}},{q="克拉维尔会同时与联盟和部落合作吗？",a="像许多在沙漠赛道这种中立场所活动的人物一样，克拉维尔更看重金币而非阵营忠诚。他很乐意雇佣联盟和部落的冒险者来执行他的计划。",al={"克拉维尔只为联盟服务吗","部落可以和克拉维尔交谈吗"}}},fx={["33aea695"]={q="克拉维尔·浓须想要什么？",a="克拉维尔一心只想着利润和私利。在闪光平原，他想通过各种手段填满自己的腰包，从运送零件、兜售人情到策划敲诈勒索，无所不用其极。他最大胆的野心是操纵沙漠赛道的比赛结果，计划通过让维修团队和车手酩酊大醉来破坏并操控比赛。",al={"克拉维尔想要什么","克拉维尔·浓须的目标","克拉维尔的动机"}},["97572808"]={q="克拉维尔·浓须为什么会在千针石林？",a="闪光平原的沙漠赛道是个无法无天的地方，充斥着高额赌博、激烈竞争和鲁莽工程，因此成了骗子觅食的绝佳场所。克拉维尔在互相较劲的侏儒和地精旁边扎营，因为他们对击败彼此的执念让他们对投机者视而不见，也很容易落入他的圈套。",al={"克拉维尔为什么在这里","克拉维尔为什么在沙漠赛道","克拉维尔与闪光平原"}}},fp="16,424,25.509.0,17.494.1,24.220.0,52.252.0,45.208.0,36.127.0,47.201.0,46.215.0"}
P.entries["npc:kreldig-ungor"] = {n="克雷迪格·安戈尔",s="克雷迪格·安戈尔是一位有进取心的矮人特工，代表Reclaimers Inc.，驻扎在凄凉之地尼耶尔前哨站的高处岩壁间。他的任务是管理这片贫瘠荒原上的实地行动，并雇佣联盟冒险者回收丢失的货物，获取当地珍贵的试剂。他的打捞与回收合同使他成为了穿行于这片险恶之地的旅行者的核心联系人。",h="克雷迪格·安戈尔是一位有进取心的矮人特工，代表Reclaimers...",kw={"联盟","凄凉之地","矮人","卡尼托尔沉船","克雷迪格·安戈尔","尼耶尔前哨站","reclaimers inc","打捞"},ang={["faction:Alliance"]="克雷迪格驻扎在尼耶尔前哨站，完全依赖联盟的旅行者来维持他在这个险恶地区进行的打捞合同。",["race:Dwarf"]="克雷迪格展现了矮人对崎岖边境探索的经典渴望和商业抱负，在远离山中大厅的地方建立了据点。"},sec={{t="荒原上的外勤特工",b="尼耶尔前哨站为联盟在凄凉之地的枯萎峡谷中提供了一处难得的避难所，使其成为像克雷迪格·安戈尔这样的商业投机者理想的立足点。作为Reclaimers Inc.的代表，克雷迪格远离了卡兹莫丹的安全区域，冒险进入了一片由半人马氏族、恶魔和部落争夺的荒凉原野。在他人眼中，这里只有废墟和灰烬，但在克雷迪格眼中，这里却充满着尚未开发的利润和等待回收的失落资产。"},{t="卡尼托尔契约",b="将克雷迪格带到凄凉之地的主要项目与卡尼托尔的失事船只有关，该船在险恶的西海岸遇难。卡尼托尔的货物中装有珍贵的物品，克雷迪格正在精心安排寻找残骸并取回散落货物的行动，以免被拾荒者或沿海的海巨人捷足先登。"},{t="收割当地试剂",b="除了海上打捞，克雷迪格还负责为Reclaimers Inc.采购凄凉之地奇异的生物和矿物宝藏。恶劣的环境孕育了独特的动植物，其部位在东部王国的炼金术师和工程师中卖价很高。愿意在荒原上与掠食者抗争的冒险者可以在克雷迪格的账簿下获得稳定的报酬。"}},faq={{q="克雷迪格·安戈尔是谁？",a="克雷迪格·安戈尔是一位与Reclaimers Inc.有关联的矮人特工，驻扎在凄凉之地的联盟前哨站尼耶尔前哨站。他负责协调该区域内的打捞任务和样本采集工作。",al={"克雷迪格·安戈尔背景故事","克雷迪格是谁","克雷迪格·安戈尔"}},{q="Reclaimers Inc.是什么？",a="Reclaimers Inc.是一家致力于在危险的前沿地带进行货物打捞、残骸回收和稀有试剂采集以获取利润的企业。",al={"reclaimers inc","reclaimers inc是什么","reclaimers业务"}},{q="在哪里可以找到克雷迪格·安戈尔？",a="他位于尼耶尔前哨站的联盟定居点，高踞于凄凉之地东北部的岩石山脉之中。",al={"克雷迪格·安戈尔位置","克雷迪格在哪里","寻找克雷迪格·安戈尔"}},{q="克雷迪格想对卡尼托尔的沉船做什么？",a="一艘载有卡尼托尔贵重物品的船只在凄凉之地海岸遇难。克雷迪格雇佣冒险者定位沉船并取回丢失的货物，以免其被拾荒者搜刮或摧毁。",al={"卡尼托尔沉船","克雷迪格卡尼托尔","凄凉之地沉船"}},{q="为什么克雷迪格要在凄凉之地收集试剂？",a="凄凉之地的恶劣环境孕育了稀有的生物和独特的天然化合物。克雷迪格收集这些样本，以供应联盟各大城市的炼金术师、技师和买家。",al={"reclaimers inc的试剂","凄凉之地试剂","为什么要收集试剂"}},{q="克雷迪格是为铁炉堡工作还是为私营企业工作？",a="虽然他在联盟前哨站工作，并且只雇佣联盟的旅行者，但克雷迪格代表的是Reclaimers Inc.，这是一家追求打捞和贸易的商业企业，而非执行官方的皇室军事目标。",al={"克雷迪格联盟还是私营","reclaimers inc与铁炉堡"}}},fx={ad7684ca={q="克雷迪格·安戈尔为什么驻扎在尼耶尔前哨站？",a="克雷迪格·安戈尔在尼耶尔前哨站的高处开设据点，以便在凄凉之地崎岖广袤的土地上为“回收者公司”开展业务。在这座设防的联盟避难所中，他相对安全地管理着废品回收和物资采购，还以此为基地，雇用强悍的冒险者深入险恶的荒地执行任务。",al={"克雷迪格·安戈尔为什么在这里","克雷迪格·安戈尔与尼耶尔前哨站","克雷迪格为什么在凄凉之地"}}},fp="13,399,25.429.0,21.323.0,25.373.0,21.203.0,24.163.0,33.120.0,51.197.0,47.195.0,56.219.0"}
P.entries["npc:krolg"] = {n="克罗格",s="克罗格是一只未受腐蚀的熊怪，居住在灰谷密斯特拉湖以南的一间与世隔绝的小屋里。他曾是刺枝部落的一员，但因族人沉沦于恶魔的疯狂而被驱逐。他只愿意与那些在他看来是同族（熊怪形态）的人交谈。",h="克罗格是一只未受腐蚀的熊怪，居住在灰谷密斯特拉湖以南的一间与世隔绝的小屋里。他曾是刺枝部落的一员，但因族人沉沦于恶魔的疯狂而被驱逐。他只愿意与那些在他看来是同族（熊怪形态）的人交谈。",kw={"灰谷的熊怪","穆格特酋长","达图尔的变形魔棒","刺枝部落","克罗格","克罗格的小屋","密斯特拉湖","莱恩的净化"},ang={["class:Druid"]="对于那些试图恢复灰谷平衡的德鲁伊来说，在这片被污染的野生生物横行的土地上，克罗格提供了一个极其宝贵且清醒的声音。",["faction:Alliance"]="协助莱恩·狼行者的联盟侦察兵依靠克罗格来瓦解敌对的刺枝熊怪的领导层。",["race:NightElf"]="对于阿斯特兰纳的暗夜精灵来说，在恶魔腐蚀摧毁部落之前，克罗格是他们与熊怪曾经古老盟友关系的苦涩回忆。"},sec={{t="依然清醒的心智",b="虽然灰谷的大多数刺枝熊怪都屈服于燃烧军团留下的恶魔污染，但克罗格依然保持着清醒，未受疯狂的影响。他居住在密斯特拉湖以南的一处隐蔽住所，警惕地守护着森林。在亲眼目睹了他的族人陷入毫无理智的暴力之后，他拒绝以真面目与外来者接触，只与那些看起来是同类的人交谈。"},{t="达图尔的遗产",b="通过达图尔的变形魔棒的魔法，联盟的旅行者可以伪装成熊怪。当克罗格看到看似友善的同族时，他会敞开心扉，揭示净化这片土地的关键信息。他会指引英雄们对抗兰·血牙及其守卫，这些被腐蚀并充满仇恨的家伙正威胁着森林。"}},faq={{q="为什么克罗格不跟我说话？",a="克罗格对外来者深感怀疑，并对森林中肆虐的暴力混乱感到恐惧。除非你在“莱恩的净化”任务线期间使用了达图尔的变形魔棒变身为熊怪，否则他完全不会理睬你。",al={"克罗格不说话","无法与克罗格交谈","为什么克罗格保持沉默"}},{q="在哪里可以找到克罗格？",a="他住在灰谷中南部密斯特拉湖以南的一个小住所里，被称为克罗格的小屋。",al={"克罗格的位置","克罗格在哪里","克罗格的小屋"}},{q="克罗格属于哪个部落？",a="克罗格最初是刺枝部落的一员。与他那些陷入腐蚀和恶魔狂乱的族人不同，他保持了理智，因此被部落驱逐。",al={"克罗格的部落","克罗格是刺枝部落的吗"}},{q="克罗格会对玩家怀有敌意吗？",a="如果不使用变形效果，克罗格会攻击靠近他的外来者。冒险者在接近他之前必须使用达图尔的变形魔棒。",al={"克罗格会攻击吗","克罗格是敌人吗"}},{q="为什么克罗格想要兰·血牙死？",a="克罗格认为兰·血牙是个权力欲极强且因腐蚀而变得更强大的家伙。尽管克罗格将族人受苦的责任归咎于暗夜精灵，但他绝不会让兰去威胁他们的孩子或森林里的其他生物。",al={"克罗格与兰·血牙","为什么要杀兰·血牙"}},{q="达图尔是谁？为什么他的魔棒能让冒险者与克罗格交谈？",a="达图尔是一位已故的邪恶法师，他创造了这根附魔的变形魔棒，让持有者可以化身为熊怪。在“莱恩的净化”任务中，冒险者找回了魔棒丢失的碎片并将其重铸，从而能够接近克罗格。",al={"谁是达图尔","达图尔的魔棒背景"}}},fx={["4c25d8d9"]={q="克罗格是谁？",a="克罗格是一名未受腐化的熊怪，独自流亡于灰谷密斯特拉湖以南。他曾是污林部族的一员，却抵御住了席卷族人的黑暗腐化。如今他独居在简陋的小屋里，保持着清醒和智慧，同时哀悼族人的变化；若有外来者伪装成熊怪前来，他也愿意提供帮助。",al={"克罗格是谁","克罗格的身份","克罗格小屋旁的熊怪是谁"}},["19bbdb38"]={q="克罗格效忠哪一方？",a="克罗格没有效忠联盟或部落；他独自生活，是这片区域仅存的少数神智清醒、未受腐化的熊怪之一。不过，他只愿意接待使用达图尔变形魔棒伪装成熊怪同类前来的联盟冒险者，并向他们提供指引和仪式知识，帮助他们对抗遭到腐化的污林部族。",al={"克罗格属于联盟还是部落","克罗格所属阵营","克罗格站在哪一方"}},["39fdb4f1"]={q="克罗格想要什么？",a="克罗格希望终结摧毁他昔日族人的疯狂。他要求变形后的冒险者杀死拉恩·血牙和他的守卫，因为他们身上的腐化威胁着暗夜精灵和森林中的其他生灵。",al={"克罗格想要什么","克罗格的动机","克罗格的目标"}},["640007b0"]={q="克罗格为什么会在这里？",a="克罗格被逐出部族后，定居在密斯特拉湖以南。他是少数没有受到腐化影响、未被扭曲成污林熊怪的熊怪之一。独自生活让他远离那些发狂的昔日兄弟，同时也能密切留意他们的领地。",al={"克罗格为什么在这里","克罗格为什么离开污林","克罗格为什么住在密斯特拉湖附近"}}},fp="5,258,15.439.0,15.374.1,27.256.0,25.113.0,32.180.0,28.158.0,40.214.1,60.241.0"}
P.entries["npc:krom-stoutarm"] = {n="克罗姆·粗臂",s="克罗姆·粗臂是一名矮人学者兼术士，他位于铁炉堡Hall of Explorers的图书馆深处。与大多数只专注于古代石料和泰坦遗物的同族不同，克罗姆研究的是更为黑暗的奥术文本和恶魔仪式。对于那些在卡利姆多和东部王国寻求深奥知识的联盟术士来说，他是不可或缺的联系人。",h="克罗姆·粗臂是一名矮人学者兼术士，他位于铁炉堡Hall of...",kw={"hall of explorers","铁炉堡","克罗姆·粗臂","图书馆","粗臂","卡巴尔之书","术士"},ang={["class:Warlock"]="联盟术士在追求黑暗契约时必须咨询克罗姆，尤其是在完成组装《卡巴尔之书》这一危险任务的过程中。",["faction:Alliance"]="克罗姆为联盟的秘密修行者在铁炉堡雄伟的山脉堡垒内提供了一个安全的知识避风港。",["race:Dwarf"]="矮人通常对邪能艺术嗤之以鼻，这使得克罗姆在Hall of Explorers受人尊崇的书架之间所处的位置显得格外离奇。"},sec={{t="大厅中更为黑暗的一角",b="Hall of Explorers通常以那些痴迷于镐、铲和泰坦文物的矮人考古学家而闻名。克罗姆·粗臂在他们之中显得格格不入。他潜伏在堆满巨著的图书馆里，钻研着神秘学知识和恶魔召唤者的契约仪式。他在铁炉堡的存在证明了，尽管术士艺术被广泛排斥，但研究禁忌法术的学者修行者仍然在山中之城的殿堂内活动。"},{t="卡巴尔之书",b="当联盟术士寻求束缚强大的恶魔仆从（如地狱猎犬）时，他们的旅程不可避免地会与克罗姆产生交集。由于掌握着零散的神秘学典籍知识，他会指引有抱负的召唤者远渡重洋——包括深入千针石林半人马的危险领地——去寻回臭名昭著的《卡巴尔之书》的残页和碎片。"}},faq={{q="我在哪里可以找到克罗姆·粗臂？",a="克罗姆·粗臂位于矮人主城铁炉堡的Hall of Explorers图书馆侧厅内。",al={"克罗姆·粗臂位置","克罗姆·粗臂在哪里","铁炉堡的克罗姆·粗臂"}},{q="克罗姆·粗臂对玩家有什么作用？",a="克罗姆是联盟术士追求职业核心恶魔仪式的重要任务联系人，尤其是在指导他们完成《卡巴尔之书》的收集任务方面。",al={"克罗姆做什么","克罗姆·粗臂的用途","克罗姆·粗臂任务"}},{q="克罗姆·粗臂和其他粗臂族人有关系吗？",a="有几位矮人都拥有粗臂这个姓氏，但克罗姆与其他粗臂之间的亲缘关系尚未得到证实。",al={"克罗姆的亲属","与斯登·粗臂的关系"}},{q="为什么一名术士被允许进入Hall of Explorers？",a="克罗姆是一位铁炉堡矮人，曾作为挖掘工在奥达曼工作过。如今，他是一位四处游历的术士，大部分时间都在图书馆里搜集古代文献，且目前无人知晓有人曾将他驱逐出去。",al={"为什么克罗姆在hall of explorers","铁炉堡是否允许术士"}},{q="为什么克罗姆与贫瘠之地有关？",a="克罗姆对《卡巴尔之书》的搜寻终点在贫瘠之地。当术士从千针石林的半人马手中以及南海镇西海岸丢失的货船上找回这本书的两个残页后，他会将翻修过的书籍寄给棘齿城的斯坦哈德·法尔杉。",al={"克罗姆·粗臂与贫瘠之地","为什么克罗姆的任务涉及贫瘠之地"}},{q="克罗姆·粗臂能教授法术吗？",a="克罗姆是一位学术型的任务发布者，而不是标准的职业训练师。他引导术士完成特定的仪式考验，而非教授日常的法术书。",al={"克罗姆能训练我吗","克罗姆术士训练师"}}},fx={["6ca19015"]={q="克罗姆·粗臂是谁？",a="克罗姆·粗臂是一名矮人术士，在铁炉堡探险者大厅的图书馆中研究黑暗传说。许多研习邪能之术的人会躲进阴暗的地下室和偏僻的秘会场所，而克罗姆则公开活动于探险者协会的学者和发掘者之间，钻研古代遗物、晦涩奥术和神秘典籍。",al={"克罗姆是谁","克罗姆·粗臂的背景","克罗姆·粗臂是谁"}},["23fb54c2"]={q="克罗姆·粗臂效忠哪一方？",a="克罗姆·粗臂效忠铁炉堡和联盟。虽然他研习的术士之术令许多族人心生猜疑和不安，但他仍是探险者大厅中受人尊敬的学者，只将自己的秘传专长和奥术知识用于协助联盟勇士完成使命。",al={"克罗姆·粗臂所属阵营","克罗姆·粗臂属于联盟还是部落","克罗姆效忠谁"}}},fp="13,374,27.471.0,21.369.0,31.110.0,46.181.0,44.113.0,56.225.0,37.249.0,32.162.0"}
P.entries["npc:krusk"] = {n="克鲁斯克",s="克鲁斯克是一名驻扎在希尔斯布莱德丘陵塔伦米尔的兽人斥候。他直接奉大酋长萨尔之命，负责调查辛迪加并从敦霍尔德城堡的废墟中找回遗物。在最初的渗透行动遭遇伏击后，他目前正负责协调侦察与营救工作。",h="克鲁斯克是一名驻扎在希尔斯布莱德丘陵塔伦米尔的兽人斥候。他直接奉大酋长萨尔之命，负责调查辛迪加并从敦霍尔德城堡的废墟中找回遗物。在最初的渗透行动遭遇伏击后，他目前正负责协调侦察与营救工作。",kw={"德鲁尔","敦霍尔德城堡","戈尔迪尔","希尔斯布莱德","克鲁斯克","辛迪加","塔伦米尔","萨尔","托格索尔"},ang={["faction:Horde"]="克鲁斯克代表了大酋长萨尔在洛丹伦的直接利益，专注于保障敦霍尔德的历史不被破坏，并确保没有被俘的兽人落入辛迪加之手。",["race:Orc"]="帮助克鲁斯克营救他的斥候同伴触及了兽人收容所的荣誉与痛苦历史，特别是萨尔打破他族人枷锁的那座堡垒。"},sec={{t="失败的任务",b="当大酋长萨尔将目光重新投向敦霍尔德城堡的废墟时，他派遣了克鲁斯克和一支小型的突击队去侦察辛迪加的动向，并找回与这座堡垒那段严酷往事有关的遗物。然而，这些人类歹徒比预想中更根深蒂固，配合也更为严密。敦霍尔德那摇摇欲坠的墙壁内发生的一场伏击压制了兽人斥候小队。克鲁斯克设法杀出重围，但他的同伴们却被俘虏了：德鲁尔和托格索尔被关押在废墟之内，而探险队的领队戈尔迪尔则被转移到了辛迪加的另一个据点。克鲁斯克在塔伦米尔重整旗鼓，现在正指引部落的冒险者们进攻敦霍尔德，找回丢失的物品，并营救他那些被困的同伴。"},{t="密切关注辛迪加",b="除了营救他的斥候之外，克鲁斯克依然专注于瓦解辛迪加在希尔斯布莱德的势力。奥特兰克的堕落贵族是一个不稳定的威胁，他们以敦霍尔德城堡为据点，策划针对部落哨所和他们曾经的联盟同胞的阴谋。克鲁斯克在塔伦米尔开展工作，追踪辛迪加领导人（例如奥里登·佩罗诺尔德领主）的动向，希望能在他们威胁到部落在洛丹伦那摇摇欲坠的立足点之前，斩断他们的领导层。"}},faq={{q="克鲁斯克是谁？",a="克鲁斯克是大酋长萨尔派往塔伦米尔的兽人斥候。他的任务是调查敦霍尔德城堡废墟周边的辛迪加行动，并找回历史遗物。",al={"克鲁斯克","克鲁斯克是谁","克鲁斯克 塔伦米尔"}},{q="克鲁斯克的小队遭遇了什么？",a="克鲁斯克和他的小队在敦霍尔德城堡内遭到了辛迪加的伏击。虽然克鲁斯克成功逃脱，但德鲁尔和托格索尔被囚禁在荒废的堡垒中，而探险队领队戈尔迪尔则被带到了辛迪加的另一个据点。",al={"克鲁斯克的小队","克鲁斯克遭遇了什么","敦霍尔德伏击"}},{q="部落为何对敦霍尔德城堡感兴趣？",a="对于大酋长萨尔来说，敦霍尔德具有深远的个人和历史意义。他在那里被埃德拉斯·布莱克摩尔当作角斗士囚禁抚养长大，后来他领导了夷平这座城堡的兽人起义。",al={"为何要敦霍尔德","萨尔 敦霍尔德","敦霍尔德遗物"}},{q="我在哪里可以找到克鲁斯克？",a="克鲁斯克驻扎在希尔斯布莱德丘陵北部的部落定居点——塔伦米尔的户外。",al={"克鲁斯克位置","克鲁斯克在哪里"}}},fx={["86db3c10"]={q="克鲁斯克效忠哪一方？",a="克鲁斯克是部落忠诚的行动人员。他直接奉酋长萨尔之命，在塔伦米尔开展行动，维护奥格瑞玛在希尔斯布莱德丘陵的战略利益。",al={"克鲁斯克所属阵营","克鲁斯克是部落吗","克鲁斯克效忠谁"}},["943a1bb4"]={q="克鲁斯克想要什么？",a="克鲁斯克需要能干的勇士从敦霍尔德城堡遗迹中的迪菲亚兄弟会手中救出被俘的同伴——戈尔迪尔、德鲁尔和托格萨尔。他还想查明迪菲亚兄弟会的活动，并找回一件与敦霍尔德历史有关的重要物品。",al={"克鲁斯克需要什么","克鲁斯克的目标","克鲁斯克在寻找什么"}},["2e7680ba"]={q="克鲁斯克为什么会在塔伦米尔？",a="酋长萨尔亲自派克鲁斯克和他的小队前往希尔斯布莱德，调查敦霍尔德城堡周边迪菲亚兄弟会的活动。一次伏击使他的斥候遭到囚禁，克鲁斯克于是撤退到塔伦米尔重整队伍，并招募援手完成任务。",al={"克鲁斯克为什么在希尔斯布莱德","克鲁斯克为何在塔伦米尔","萨尔为什么派克鲁斯克"}},fe85a88a={q="克鲁斯克与谁有关联？",a="克鲁斯克听命于酋长萨尔。萨尔派他前往希尔斯布莱德，加入由戈尔迪尔率领的远征队，与兽人同伴德鲁尔和托格萨尔并肩行动。他在塔伦米尔与当地部落驻军协同开展工作。",al={"克鲁斯克的同伴","克鲁斯克的盟友","克鲁斯克与谁共事"}}},fp="5,305,20.716.0,21.475.0,13.182.0,31.231.0,46.200.0,23.99.0"}
P.entries["npc:kuray-bin"] = {n="库莱比",s="库莱比是一名暗矛巨魔侦察兵，驻扎在灰谷碎木岗哨外的一个哨所。他负责监视周围森林中的小径，以防暗夜精灵侦察兵潜入部落营地。",h="库莱比是一名暗矛巨魔侦察兵，驻扎在灰谷碎木岗哨外的一个哨所。他负责监视周围森林中的小径，以防暗夜精灵侦察兵潜入部落营地。",kw={"灰谷斥候","暗矛","库莱比","银翼要塞","碎木岗哨"},ang={["faction:Horde"]="库莱比代表了确保碎木岗哨不被暗夜精灵游击队包围和攻陷所必需的前线警惕性。",["race:Troll"]="像许多为部落效力的暗矛侦察兵一样，库莱比利用他丛林追踪的本能来发现那些别人眼中只有树木的地方所潜藏的暗夜精灵渗透者。"},sec={{t="注视森林边缘",b="库莱比位于碎木岗哨外，负责警惕联盟对灰谷深处森林的渗透。银翼要塞不断在周边的树冠层巡逻，派遣敏捷的斥候越过边界，收集有关部落伐木作业和防御的情报。库莱比深知如果不加监视，这些斥候很快就会变成伏击部队，因此他会指派有能力的部落战士在他们向银翼哨站汇报之前将其猎杀。"}},faq={{q="库莱比是谁？",a="库莱比是一名驻扎在灰谷碎木岗哨外的暗矛巨魔守望者。他会指派部落冒险者清理潜伏在周围林地中的敌对暗夜精灵侦察兵。",al={"库莱比","库莱比是谁","碎木岗哨巨魔侦察兵"}},{q="我在哪里能找到库莱比？",a="他位于碎木岗哨大门外，负责守卫灰谷中东部的道路入口。",al={"库莱比位置","库莱比在哪里"}},{q="为什么库莱比想要消灭银翼斥候？",a="这些斥候是渗透到碎木岗哨附近的银翼要塞成员。库莱比希望在他们收集到部落阵地的战术情报或协调突袭之前将其消灭。",al={"为什么要杀斥候","灰谷斥候任务背景"}},{q="库莱比还提供其他任务吗？",a="不提供。他在哨所外围的唯一职责就是负责针对难以捉摸的暗夜精灵斥候进行反侦察。",al={"库莱比的任务","库莱比的工作"}}},fx={["65134a3b"]={q="库莱比效忠哪一方？",a="库莱比为部落效力。他驻扎在碎木岗哨外，负责保护这处定居点免遭联盟侵袭，并监视灰谷有争议的边境。",al={"库莱比所属阵营","库莱比效忠谁","库莱比是部落吗"}},bfddbb0e={q="库莱比为什么驻扎在灰谷？",a="库莱比在碎木岗哨外的一处哨站值守，监视敌方动向。暗夜精灵斥候深入部落领地，他的职责是在威胁袭击定居点之前发现它们。",al={"库莱比为什么在这里","库莱比在灰谷的职责","库莱比为什么在碎木岗哨"}},["189aca6f"]={q="库莱比与谁有关联？",a="库莱比直接隶属于碎木岗哨的部落驻军。作为一名丛林巨魔哨兵，他与兽人及其他守卫协同作战，守住这处位于灰谷、岌岌可危的据点，对抗暗夜精灵。",al={"库莱比的关系","库莱比的盟友","库莱比与谁共事"}}},fp="9,211,23.485.0,17.191.0,27.126.0,55.211.0,37.117.0"}
P.entries["npc:kzan-thornslash"] = {n="克赞·荆条",s="克赞·荆条是一名兽人武器商人，驻扎在杜隆塔尔的试炼谷。他为开始在部落旗下受训的新兵提供基本的入门武器和补给。",h="克赞·荆条是一名兽人武器商人，驻扎在杜隆塔尔的试炼谷。他为开始在部落旗下受训的新兵提供基本的入门武器和补给。",kw={"杜隆塔尔","部落","克赞","兽人","荆条","试炼谷","武器商","武器"},ang={["class:Warrior"]="对于那些起步时手持残破刀剑的年轻战士，克赞提供各种钝器和利刃供选择，以适应不同的战斗流派。",["faction:Horde"]="为萨尔新生的军队提供补给是从最底层开始的，像克赞这样的商人确保每一双有能力的手都能为部落挥舞钢铁。"},sec={{t="新兵护甲商",b="克赞·荆条位于试炼谷尘土飞扬的红色峡谷中，是那些刚刚踏上部落战士之路的年轻兽人和暗矛巨魔的主要武器供应商。克赞提供各种基础装备——从粗糙的手斧和短剑到棍棒和法杖应有尽有——确保初出茅庐的试炼者拥有足够的武装来面对当地的野生生物和区域危险。"}},faq={{q="克赞·荆条是谁？",a="克赞·荆条是一名驻扎在试炼谷的兽人商人。他的职责是为部落新兵提供适合他们最初战斗试炼的标准武器。",al={"克赞·荆条","克赞是谁","试炼谷武器商"}},{q="我在哪里可以找到克赞·荆条？",a="他位于大兽穴内，那是杜隆塔尔西南部试炼谷中的一个洞穴，初出茅庐的冒险者和他们的训练导师们就聚集在那里。",al={"克赞位置","克赞·荆条在哪里","克赞·荆条地图"}},{q="克赞出售什么样的装备？",a="克赞提供基础的入门武器，包括斧头、剑、匕首、法杖和钝器，供那些在获得锻造或搜寻来的装备前需要可靠铁器的训练者使用。",al={"克赞卖什么","克赞物品","克赞武器"}}},fx={c4565150={q="克赞·荆条想要什么？",a="克赞·荆条一边维持自己在杜隆塔尔的生意，一边为新兵提供所需的武器。他通过与年轻战士交易，确保部落初生的守卫者都能得到基本武器，保卫他们新定居的土地。",al={"克赞想要什么","克赞·荆条的动机","克赞·荆条的目标"}},feb30cb2={q="克赞·荆条效忠哪一方？",a="克赞·荆条坚定地站在部落一方。他在试炼谷活动，听命于奥格瑞玛和萨尔的新兴国度，为来到杜隆塔尔、证明自身力量与忠诚的年轻兽人和巨魔提供装备。",al={"克赞·荆条所属阵营","克赞效忠谁","克赞是部落吗"}},["1bbcac80"]={q="克赞·荆条为什么会在试炼谷？",a="克赞留在试炼谷，为即将踏上初次试炼的新人和战士提供武器。在这片恶劣干燥、遍布石爪怪、野猪和邪恶魔仆的试炼场上，未经考验的战士需要可靠的钢铁武器、棍棒和利刃才能活下来。",al={"克赞·荆条为什么在这里","克赞在试炼谷的职责","克赞做什么"}}},fp="15,199,23.424.0,23.172.0,33.152.0,38.176.0"}
P.entries["npc:lady-anacondra"] = {n="安娜科德拉",s="安娜科德拉是领导哀嚎洞穴中尖牙德鲁伊的尖牙领主之一。她曾是追随纳拉雷克斯致力于治愈贫瘠之地的暗夜精灵德鲁伊之一，但在她导师的翡翠梦境联结转变为噩梦时，她迷失了自我。她的心智崩溃，将原本的忠诚扭曲为一种重塑大地以契合那个扭曲梦境的执念。",h="安娜科德拉是领导哀嚎洞穴中尖牙德鲁伊的尖牙领主之一。她曾是追随纳拉雷克斯致力于治愈贫瘠之地的暗夜精灵德鲁伊之一，但在她导师的翡翠梦境联结转变为噩梦时，她迷失了自我。她的心智崩溃，将原本的忠诚扭曲为一种重塑大地以契合那个扭...",kw={"安娜科德拉","贫瘠之地","尖牙德鲁伊","尖牙领主","安娜科德拉宝石","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="对于塞纳里奥德鲁伊来说，安娜科德拉是一个令人警醒的悲剧：一位诚挚的门徒，她治愈大地的热忱使她容易受到噩梦的侵袭，将她的联结扭曲成了疯狂。",["faction:Horde"]="部落绝不能允许安娜科德拉和尖牙领主们威胁贫瘠之地脆弱的生命线，因此除掉她对于确保十字路口及附近绿洲的安全至关重要。",["race:NightElf"]="看到一位卡多雷血统的姐妹为了追求扭曲的毒蛇之梦而抛弃了她的遗产和形体，这让人清醒地意识到潜伏在翡翠梦境中的危险。"},sec={{t="从门徒到毒蛇",b="在采用毒蛇头衔之前，安娜科德拉曾是纳拉雷克斯的一名德鲁伊。当长者德鲁伊纳拉雷克斯构想通过翡翠梦境来引出贫瘠之地的地下泉水时，她跟随他进入了洞穴。然而，她的忠诚最终导致了她的堕落。当纳拉雷克斯的心智被黑暗幻象所攫取时，噩梦从梦境领域渗透出来，感染了他的门徒，摧毁了她的理智，并将她的沉思重塑为一种冰冷、爬行动物般的执念。"},{t="深处的尖牙领主",b="现在自称为安娜科德拉的她，守卫在哀嚎洞穴最初的地下甬道中。和她的其他尖牙领主同僚一样，她放弃了塞纳里奥议会的传统教义，转而信奉毒蛇的邪恶姿态。她引导闪电、自然魔法和沉睡法术，执行着纳拉雷克斯那扭曲的沉睡，并致力于将噩梦的腐蚀蔓延到上方贫瘠的土地上。"}},faq={{q="安娜科德拉最初是谁？",a="她最初是跟随纳拉雷克斯治愈贫瘠之地任务的暗夜精灵德鲁伊之一，在噩梦腐蚀他的门徒之前。",al={"安娜科德拉原名"}},{q="她为什么背叛了塞纳里奥议会？",a="当纳拉雷克斯试图联结贫瘠之地地下的翡翠梦境时，他的思想被噩梦所淹没。同样的噩梦感染了追随者的心智，腐蚀了她并驱使她侍奉那个扭曲的梦境。",al={"为什么安娜科德拉是邪恶的","她是如何成为尖牙德鲁伊的"}},{q="她在哀嚎洞穴中的角色是什么？",a="她是领导尖牙德鲁伊的四位尖牙领主之一。她守卫着洞穴的上层区域，确保纳拉雷克斯保持在他那被腐蚀的沉睡之中，同时尖牙德鲁伊们试图重塑大地以契合他们扭曲的梦境。",al={"安娜科德拉做什么","安娜科德拉的目的","为什么击杀安娜科德拉"}},{q="在洞穴里哪里能找到她？",a="安娜科德拉在哀嚎洞穴入口附近的第一个大型洞穴网络中游荡。她在洞穴的迅猛龙和毒蛇之间巡逻，经常在几个休息点之间移动。",al={"安娜科德拉位置","安娜科德拉在哪里","安娜科德拉刷新"}},{q="为了塞纳里奥议会，要从她身上获取什么物品？",a="她携带着安娜科德拉宝石。杀死她并取回宝石是雷霆崖的德鲁伊纳拉·野鬃的要求，目的是打破尖牙领主对贫瘠之地的控制。",al={"安娜科德拉宝石","尖牙德鲁伊领袖安娜科德拉","安娜科德拉任务物品"}},{q="她在战斗中使用什么力量？",a="她利用自然魔法，用灼热的闪电从远处攻击敌人，并施放魔法沉睡来瘫痪入侵者，同时她的爬行动物盟友发起进攻。",al={"安娜科德拉技能","安娜科德拉法术","安娜科德拉攻击"}}},fx={["1a1ef870"]={q="安娜科德拉效忠于哪一方？",a="安娜科德拉与尖牙德鲁伊站在一起，早已背弃了对塞纳里奥议会的忠诚。她的主人纳拉雷克斯被笼罩其身的翡翠梦魇腐化后，她也随之堕落，如今反抗昔日同胞，守护着哀嚎洞穴中滋长的疯狂。",al={"安娜科德拉的阵营","安娜科德拉效忠于谁","安娜科德拉的忠诚对象"}},ec4c22d8={q="安娜科德拉想要什么？",a="安娜科德拉的心智也遭到腐化，她想要重塑这片土地，让它符合尖牙德鲁伊扭曲的梦境。她守护着哀嚎洞穴中滋长的梦魇，并与其他尖牙领主一同将其传播开来。",al={"安娜科德拉想做什么","安娜科德拉的目标","安娜科德拉的动机"}},f4df78aa={q="安娜科德拉为何在此？",a="她曾是追随暗夜精灵德鲁伊纳拉雷克斯的德鲁伊之一，陪他执行恢复贫瘠之地的任务。她随他进入哀嚎洞穴，探寻地下泉水，却在他的梦境变成梦魇后被困于此，并遭到扭曲。",al={"安娜科德拉为何在哀嚎洞穴","安娜科德拉如何来到这里","安娜科德拉在贫瘠之地的任务"}},["6f9b72fe"]={q="安娜科德拉与谁有联系？",a="安娜科德拉与纳拉雷克斯关系密切。在梦魇摧毁她的心智之前，她曾是这位强大德鲁伊的侍僧。她也与其他尖牙领主——例如科布拉恩和瑟芬迪斯——结为一体，与他们一同统治着扭曲的尖牙德鲁伊教派。",al={"安娜科德拉的主人是谁","安娜科德拉与纳拉雷克斯的关系","谁领导安娜科德拉"}}},fp="14,375,24.489.0,22.419.0,34.149.0,45.232.0,40.246.0,42.196.0,52.169.0,37.176.0"}
P.entries["npc:lady-sarevess"] = {n="萨利维丝",s="萨利维丝是一位扭曲的娜迦女巫，居住在黑暗深渊被洪水淹没的废墟中，并在那里沉迷于黑暗巫术。",h="萨利维丝是一位扭曲的娜迦女巫，居住在黑暗深渊被洪水淹没的废墟中，并在那里沉迷于黑暗巫术。",kw={"阿库麦尔","黑暗深渊","萨利维丝","娜迦","pool of ask'ar","海女巫","暮光之锤"},ang={["class:Mage"]="萨利维丝展示了高等精灵的魔法实践如何在几个世纪的海洋腐化下退化为原始、混乱的闪电和潮汐巫术。",["race:NightElf"]="萨利维丝居住的废墟曾经是一座艾露恩的神庙。看到她那扭曲的娜迦同类玷污Pool of Ask'ar的圣水，令人痛苦地回想起大分裂。"},sec={{t="深渊中的洞穴",b="萨利维丝在Pool of Ask'ar的这座废弃神庙的被淹没洞穴中进行她的仪式。她是一位极其扭曲的施法者，沉迷于黑暗魔法，而同样出没于沉没的神庙的暮光之锤邪教徒则在洞穴更深处进行他们自己的崇拜活动。"},{t="潮汐巫术",b="就像深海中的海女巫一样，萨利维丝能够掌控元素涌流和噼啪作响的闪电弧。她在忠诚的娜迦哨兵和召唤出的水元素的簇拥下，誓死保卫着她的圣殿，抵御任何威胁她黑暗行径的入侵者。"}},faq={{q="萨利维丝是谁？",a="萨利维丝是一位娜迦施法者，她已经在黑暗深渊内的地下Pool of Ask'ar安家。她是一位极其扭曲的施法者，沉迷于黑暗魔法。",al={"萨利维丝是谁","萨利维丝背景故事","萨利维丝背景"}},{q="萨利维丝在哪里可以找到？",a="她的巢穴位于Pool of Ask'ar，那是一处位于灰谷海岸边的黑暗深渊神庙建筑群前部区域的被淹没的洞室。",al={"萨利维丝位置","萨利维丝在哪里","pool of ask'ar"}},{q="萨利维丝掌握着什么力量？",a="沿袭了娜迦海女巫的传统，萨利维丝运用强大的水系和元素魔法，特别是狂暴的叉状闪电，来击倒任何进入她洞穴的人。",al={"萨利维丝魔法","萨利维丝技能"}}},fx={["75d3f337"]={q="萨利维丝效忠于哪一方？",a="萨利维丝效忠于自己的娜迦同族，而非联盟或部落。她是一名极其邪恶的施法者，栖身于黑暗深渊中被水淹没的阿斯卡之池，并会凶狠地抵御任何闯入者，守护自己的洞窟。",al={"萨利维丝的阵营","萨利维丝效忠于谁","萨利维丝的忠诚对象"}},["67d48548"]={q="萨利维丝想要什么？",a="萨利维丝想要精进自己对扭曲魔法的掌控。她在黑暗深渊深处被水淹没的洞窟中举行黑暗仪式，并击倒任何胆敢打扰她行事的闯入者。",al={"萨利维丝在做什么","萨利维丝的目标","萨利维丝的目的"}},["6008d570"]={q="萨利维丝为何在黑暗深渊？",a="萨利维丝将阿斯卡之池据为巢穴。这是一处位于黑暗深渊废墟神殿中的水淹洞窟。她在那里钻研黑暗魔法，由娜迦哨兵和召唤来的水元素守卫。",al={"萨利维丝为何在黑暗深渊","萨利维丝为何在此"}},d8505f38={q="萨利维丝与谁有联系？",a="萨利维丝与盘踞在黑暗深渊水淹废墟中的娜迦有关。她在洞窟中指挥忠诚的娜迦哨兵和召唤来的水元素。暮光之锤教徒也出没于这座沉没的神庙，但他们在洞穴更深处进行自己的崇拜仪式。",al={"萨利维丝的盟友","萨利维丝与谁共事","萨利维丝与暮光之锤"}}},fp="13,134,21.274.0,20.262.0,21.188.0,33.156.0,39.192.0"}
P.entries["npc:laird"] = {n="莱尔德",s="莱尔德是一位暗夜精灵鱼类商贩，位于奥伯丁的海滨旅店中。他在黑海岸被迷雾笼罩的海岸线上工作，为那些在崎岖海岸冒险的旅行者和渔夫提供贸易商品和烹饪配方。",h="莱尔德是一位暗夜精灵鱼类商贩，位于奥伯丁的海滨旅店中。他在黑海岸被迷雾笼罩的海岸线上工作，为那些在崎岖海岸冒险的旅行者和渔夫提供贸易商品和烹饪配方。",kw={"奥伯丁","黑海岸","狂鱼肉片","鱼类商贩","莱尔德","娜萨·影歌"},ang={["profession:Cooking"]="前往黑海岸的美食旅行者经常寻找莱尔德，以获取他关于如何正确处理并烹饪卡利姆多水域特有的狂暴狂鱼的食谱。",["race:NightElf"]="莱尔德代表了那些在大陆沿岸扎根，以支持卡利姆多日益增长的沿海网络的普通暗夜精灵商人。"},sec={{t="港口商人",b="莱尔德位于奥伯丁繁忙的旅店内，向水手、当地居民和旅途中的冒险者出售鲜鱼和补给品。与泰达希尔平静的海岸相比，黑海岸的水域以动荡和危险著称，但莱尔德深知风险与回报并存。对于敢于在迷雾弥漫的海滩上垂钓的垂钓者来说，当地的渔获能带来丰厚的利润。"},{t="水上的纽带",b="莱尔德与海峡对岸泰达希尔的渔业运作保持着密切联系。他是鲁瑟兰村的岛屿枝干与大陆港口之间快递业务的重要联络人，接收来自同行渔夫娜萨·影歌的货物，确保沿海商业路线的畅通。"}},faq={{q="我在哪里可以找到莱尔德？",a="莱尔德位于奥伯丁旅店的底楼室内，这是黑海岸沿岸主要的联盟定居点。",al={"莱尔德位置","莱尔德在哪里","莱尔德 奥伯丁"}},{q="莱尔德卖什么？",a="他出售各种捕获的鱼类和烹饪材料，以及制作狂鱼肉片的烹饪指南。",al={"莱尔德商人","莱尔德卖什么","莱尔德商品"}},{q="哪些任务与莱尔德有关？",a="在任务“飞往奥伯丁”中，莱尔德是来自鲁瑟兰村的娜萨·影歌所寄送货物的接收人，此后他会请求冒险者将消息带回海对岸。",al={"莱尔德任务","奥伯丁捕鱼任务"}},{q="为什么莱尔德认为尽管有危险，在黑海岸捕鱼仍然值得？",a="莱尔德指出，虽然黑海岸雾气缭绕的海岸线比泰达希尔宁静的水域隐藏着更多的危险，但丰富且充满异国情调的海洋生物使得这门生意对于有进取心的渔夫来说利润丰厚得多。",al={"莱尔德闲聊","黑海岸适合钓鱼吗"}}},fx={["47d7af55"]={q="莱尔德是谁？",a="莱尔德是暗夜精灵渔夫兼鱼贩，靠在黑海岸谋生。他住在奥伯丁热闹的旅店里，与往来旅客以及在海岸迷雾笼罩的水域捕鱼的人做生意，为过路者提供烹饪食谱和鲜鱼。",al={"莱尔德是谁","奥伯丁的莱尔德","莱尔德的身份"}},f4a4a12e={q="莱尔德效忠于哪一方？",a="莱尔德与暗夜精灵和联盟结盟。他安居在奥伯丁，欢迎联盟冒险者和当地渔夫到旅店休息、选购货物。",al={"莱尔德的阵营","莱尔德属于联盟吗","莱尔德效忠于谁"}},["90f5a883"]={q="莱尔德为何在此？",a="莱尔德留在奥伯丁旅店，收购并出售沿岸渔获。尽管黑海岸的海岸线潜藏着泰达希尔所没有的危险，他也明白，敢于冒险的渔夫能从当地水域赚取丰厚利润，因此这里是开展生意的绝佳地点。",al={"莱尔德为何在奥伯丁","莱尔德在黑海岸的目的"}},d47e4f81={q="莱尔德想要什么？",a="莱尔德希望沿海渔业生意兴旺。尽管黑海岸的海岸危机四伏，他仍鼓励当地人出海捕鱼，也乐于为饥肠辘辘的旅客提供海鲜和烹饪食谱。",al={"莱尔德想要什么","莱尔德的目标","莱尔德的动机"}}},fp="5,224,17.404.0,21.323.0,23.128.0,21.123.0,26.193.0,72.215.0"}
P.entries["npc:lakota-windsong"] = {n="拉克塔·风歌",s="拉克塔·风歌是一位年轻的牛头人，被囚禁在千针石林的黑云峰峭壁之上。在拒绝了阿纳克·图腾的求婚后，她被强行掳走，目前正等待着脱离恐怖图腾部族的魔掌。",h="拉克塔·风歌是一位年轻的牛头人，被囚禁在千针石林的黑云峰峭壁之上。在拒绝了阿纳克·图腾的求婚后，她被强行掳走，目前正等待着脱离恐怖图腾部族的魔掌。",kw={"阿纳克·图腾","黑云峰","终获自由","乱风岗","拉克塔·风歌","萨利亚","千针石林"},ang={["faction:Horde"]="解救拉克塔是对恐怖图腾在千针石林统治地位的一次打击，也为在乱风岗休整的旅人们保障了通行安全。",["race:Tauren"]="拉克塔的遭遇鲜明地提醒了人们，恐怖图腾内部滋生的背叛行径，他们对凯恩·血蹄领导地位的公然违抗经常演变成暴力冲突。"},sec={{t="致命的求婚",b="第三次战争后不久，拉克塔·风歌遭到了阿纳克·图腾的纠缠。因为不愿加入他的部族，也不愿接受他的求婚，她拒绝了他的提议。阿纳克不接受任何拒绝；他在夜色的掩护下潜回，在拉克塔的兄弟试图干预时将其杀害，并将她掳到了千针石林的险峻高处。她被囚禁在黑云峰峡谷底部的上方，在严密的看守下身陷囹圄，而阿纳克仍执意要让她成为自己的新娘。"},{t="安全撤离",b="在阴险狡诈的恐怖图腾强盗的包围下，拉克塔无法独自杀出重围。只有勇敢的护送者才能引领她穿过吊桥，沿着蜿蜒的小径下到下方的峡谷盆地。一旦脱离黑云峰，拉克塔便会逃往安全的乱风岗，将她获救的消息带给萨利亚和驻扎在那里的守卫者们。"}},faq={{q="为什么拉克塔·风歌被囚禁在黑云峰？",a="她拒绝了阿纳克·图腾的求婚。阿纳克没有接受她的拒绝，反而杀害了她的兄弟并掳走了拉克塔，将她拖到了恐怖图腾在黑云峰的据点，企图以此强迫她就范。",al={"为什么拉克塔被俘","谁绑架了拉克塔","为什么拉克塔在黑云峰"}},{q="拉克塔获救后会去哪里？",a="在安全到达黑云峰底部后，拉克塔会前往乱风岗，在那里她可以在部落守卫者中寻求庇护，并向萨利亚报告她的遭遇。",al={"拉克塔逃往何处","护送后她去哪里","拉克塔的目的地"}},{q="阿纳克·图腾是谁？",a="阿纳克是阴险狡诈的恐怖图腾氏族的一名暴力战士，他在拉克塔拒绝嫁给他时杀害了她的兄弟并掳走了她。",al={"阿纳克是谁","谁绑架了她","阿纳克背景故事"}}},fx={e2861ac8={q="拉克塔·风歌是谁？",a="拉克塔·风歌是一名被囚禁在黑云峰顶的女性牛头人。阿纳克·恐怖图腾向她求婚时，拉克塔拒绝了他。阿纳克因遭到拒绝而勃然大怒，杀害了她的兄弟，并将她掳到千针石林的恐怖图腾据点，企图强迫她成婚。",al={"拉克塔·风歌是谁","拉克塔是谁","拉克塔的身份"}},["412850e2"]={q="拉克塔·风歌效忠于哪一方？",a="拉克塔与部落中爱好和平的牛头人站在一起，并指望乱风岗的勇士保护自己。她对恐怖图腾氏族深怀仇恨，因为他们残忍地杀害了她的兄弟并绑架了她。",al={"拉克塔·风歌的阵营","拉克塔属于部落吗","拉克塔的效忠对象"}},["2c16a924"]={q="拉克塔·风歌想要什么？",a="拉克塔只想逃离黑云峰，远离恐怖图腾强盗，抵达安全之处。她的兄弟为保护她而丧命，如今她只能指望有人勇敢地突破看守，护送她沿着蜿蜒小路安全抵达乱风岗。",al={"拉克塔·风歌的目标","拉克塔需要什么","拉克塔的愿望"}},["3261173c"]={q="拉克塔·风歌与谁有联系？",a="拉克塔的兄弟曾拼死保护她，却在试图抵挡阿纳克·恐怖图腾时丧命。她也信任萨利亚和驻守乱风岗的守卫。",al={"拉克塔的家人","拉克塔的关系","拉克塔与谁有亲属关系"}}},fp="15,245,18.504.0,17.388.1,56.226.0,41.187.1,23.139.0"}
P.entries["npc:lanka-farshot"] = {n="兰卡·远箭",s="兰卡·远箭是一位驻扎在红云台地纳拉其营地的牛头人猎人训练师。他指导新手牛头人猎人迈出追踪、射击和在莫高雷平原生存的第一步。",h="兰卡·远箭是一位驻扎在红云台地纳拉其营地的牛头人猎人训练师。他指导新手牛头人猎人迈出追踪、射击和在莫高雷平原生存的第一步。",kw={"纳拉其营地","猎人训练师","兰卡·远箭","莫高雷","红云台地","牛头人猎人"},ang={["class:Hunter"]="对于在莫高雷开始训练的牛头人猎人来说，兰卡·远箭是他们遇到的第一位导师，他教授基础的射击技巧和荒野生存技能。",["race:Tauren"]="兰卡体现了传统的牛头人狩猎哲学，将射击和追踪视为保护部落以及与平原和谐共处的重要职责。"},sec={{t="红云台地的导师",b="兰卡·远箭守望着纳拉其营地，迎接每一位踏上猎人之路的新手牛头人。新兵们到达时会带着一张风化便笺，指引他们寻求他的建议。在他的悉心教导下，学徒们学习远程战斗、追踪猎物以及尊重徘徊在莫高雷草地上的野生野兽的基本知识。他的教导确保了每一位年轻的猎人都能成为部落称职的斥候和补给者。"}},faq={{q="兰卡·远箭是谁？",a="兰卡·远箭是驻扎在莫高雷红云台地纳拉其营地的牛头人猎人训练师。他为刚刚开始旅程的年轻猎人提供初步的训练和指导。",al={"兰卡是谁","兰卡·远箭npc","纳拉其营地猎人"}},{q="兰卡·远箭提供什么任务？",a="兰卡会接收那些在到达纳拉其营地时通过风化便笺被指引到他这里的年轻牛头人猎人，并引导他们学习猎人职业的基础知识，从而踏上猎人之道。",al={"兰卡·远箭任务","纳拉其营地猎人任务"}},{q="兰卡·远箭和米希·远箭有亲戚关系吗？",a="尽管拥有相同的姓氏，但没有证据表明兰卡·远箭与地精米希·远箭有亲戚关系。",al={"兰卡和米希有关系吗","米希·远箭关系"}}},fx={["3509322d"]={q="兰卡·远箭效忠于哪一方？",a="兰卡·远箭忠于牛头人部族和部落。他驻守在安全的纳拉其营地，为族人效力，指导年轻的牛头人猎人学习生存之道，并为凯恩·血蹄大酋长领导下团结一致的部族贡献力量。",al={"兰卡·远箭的阵营","兰卡·远箭效忠于谁","兰卡属于部落吗"}},fd40a21a={q="兰卡·远箭为何在纳拉其营地？",a="兰卡住在纳拉其营地，指导刚开始在红云台地接受试炼的新手猎人。莫高雷的平原要求猎人感官敏锐、瞄准稳定，兰卡随时准备将追踪和射术的基本技艺传授给下一代。",al={"兰卡为何在此","兰卡·远箭在此的目的","是什么让兰卡来到纳拉其营地"}},["2df75887"]={q="兰卡·远箭想要什么？",a="兰卡希望每一位有志成为猎人的牛头人都能掌握荒野之道。他希望你尊重猎物、磨练射术，并传承养活和守护族人所必需的光荣传统，守卫草原。",al={"兰卡·远箭的目标","兰卡想做什么","兰卡·远箭的目的"}}},fp="13,220,28.441.0,21.186.0,37.182.0,42.113.0"}
P.entries["npc:lar-prowltusk"] = {n="拉尔·猎齿",s="拉尔·猎齿是一名暗矛巨魔哨兵，驻扎在杜隆塔尔森金村的西南方。他从边境的哨位上监视着威胁这个年轻巨魔定居点的敌人，并引导冒险者挫败附近敌人的进攻。",h="拉尔·猎齿是一名暗矛巨魔哨兵，驻扎在杜隆塔尔森金村的西南方。他从边境的哨位上监视着威胁这个年轻巨魔定居点的敌人，并引导冒险者挫败附近敌人的进攻。",kw={"暗矛","杜隆塔尔","考尔克","拉尔·猎齿","北卫","森金村","巨魔"},ang={["faction:Horde"]="拉尔·猎齿代表了部落在他们初建的首都后院之外，努力确保杜隆塔尔边境免受外部威胁的斗争。",["race:Troll"]="对于暗矛部族来说，像拉尔·猎齿这样的斥候对于保护部族在杜隆塔尔脆弱的新家园免受激进的半人马氏族和入侵的人类部队侵害至关重要。"},sec={{t="海岸守望者",b="拉尔·猎齿位于森金村西南方崎岖的杜隆塔尔海岸线上，是暗矛部族的前哨之一。巨魔们在逃离沉没的群岛后仍在努力建立永久家园，而森金村正面临敌对邻居不断的袭扰。拉尔负责协调斥候和战士，监视海岸动向并遏制敌对势力的侵略——特别是考尔克半人马——以确保这个脆弱的定居点有喘息的空间。"}},faq={{q="拉尔·猎齿是谁？",a="拉尔·猎齿是一名暗矛巨魔任务发布者，驻扎在杜隆塔尔森金村的西南方。他通过招募有能力的部落旅者打击区域威胁，防止其到达村庄核心，从而帮助守卫定居点的外围。",al={"拉尔·猎齿","拉尔·猎齿是谁","拉尔·猎齿 杜隆塔尔"}},{q="拉尔·猎齿关注哪些威胁？",a="拉尔专注于威胁杜隆塔尔南部的边境危险，特别是那些侵入巨魔领地的掠夺成性的考尔克半人马部族。",al={"拉尔·猎齿 任务","拉尔·猎齿想要什么"}},{q="在哪里可以找到拉尔·猎齿？",a="他位于杜隆塔尔南部，在森金村西南方的小径上进行守望。",al={"拉尔·猎齿位置","拉尔·猎齿在哪里"}}},fx={["7aeb1fbe"]={q="拉尔·猎齿效忠于哪一方？",a="拉尔·猎齿效忠于暗矛部族和部落。他驻守在森金村西南方杜隆塔尔险峻的海岸线上，负责保卫族人的新家园，警惕不断逼近、威胁暗矛巨魔及其兽人盟友安全的敌人。",al={"拉尔·猎齿阵营","拉尔·猎齿为谁效力","拉尔·猎齿属于部落还是联盟"}},ffd46d6a={q="拉尔·猎齿为什么在这里？",a="你会发现拉尔·猎齿在森金村西南方巡逻，守护暗矛定居点免受当地威胁。杜隆塔尔南部不断受到咄咄逼人的邻居侵扰，拉尔驻守在荒野海岸附近，帮助指挥守军抵御这些威胁，避免村庄遭到袭击。",al={"拉尔·猎齿为什么在杜隆塔尔","拉尔·猎齿所在位置的原因","拉尔为什么在森金村西南方"}},["9e56c7c1"]={q="拉尔·猎齿与谁关系密切？",a="拉尔·猎齿与森金村的巨魔定居点关系密切。他与村庄守卫以及四处游历的部落冒险者协同合作，守护巨魔的领地。",al={"拉尔·猎齿的盟友","拉尔·猎齿的人际关系","拉尔·猎齿的配偶"}}},fp="13,259,20.505.0,21.249.0,41.136.0,33.94.0"}
P.entries["npc:laris-geardawdle"] = {n="拉里斯·空轮",s="拉里斯·空轮是一位古怪的侏儒研究员，常驻于铁炉堡的探险者大厅图书馆。他将自己的学术生涯致力于研究艾泽拉斯各地软泥怪的奇特本质和起源。愿意收集有毒黏液样本的冒险者会发现他是一位热情，尽管有些精神失常的雇主。",h="拉里斯·空轮是一位古怪的侏儒研究员，常驻于铁炉堡的探险者大厅图书馆。他将自己的学术生涯致力于研究艾泽拉斯各地软泥怪的奇特本质和起源。愿意收集有毒黏液样本的冒险者会发现他是一位热情，尽管有些精神失常的雇主。",kw={"侏儒","hall of explorers","铁炉堡","拉里斯·空轮","图书馆","软泥怪","黏液"},ang={["faction:Alliance"]="驻扎在探险者大厅内，拉里斯在联盟赞助的学术研究框架下工作，为探险者协会的历史挖掘工作增添了古怪的自然科学研究。",["race:Gnome"]="拉里斯体现了侏儒那种典型的、在他人忽略之处寻求知识的驱动力，即使这意味着要将双手伸进臭气熏天的沼泽泥潭中也在所不惜。"},sec={{t="软泥怪学者",b="在探险者大厅高耸的书架和古老遗物之间，拉里斯·空轮从事着一门相当不起眼的自然哲学研究：软泥怪的起源。当他的矮人同事们埋头钻研泰坦碑文和古代石刻时，拉里斯却深信艾泽拉斯那些邪恶、胶状的恐怖生物蕴含着迷人的炼金术和生物学秘密。他指派四处游历的探险者从世界各地的偏远角落收集腐蚀性的样本，急于验证他关于这些毫无心智的恶意水洼是如何获得生命的奇怪假设。"}},faq={{q="拉里斯·空轮是谁？",a="拉里斯·空轮是一位居住在铁炉堡探险者大厅图书馆内的侏儒研究员。他将非传统的学术焦点集中在软泥怪、黏液以及它们自然生成的奇特机制上。",al={"拉里斯","空轮","拉里斯是谁"}},{q="我在哪里可以找到拉里斯·空轮？",a="他位于铁炉堡的北翼，探险者大厅之内，具体来说是在图书馆安静的角落里。",al={"拉里斯的位置","拉里斯在哪里","找到拉里斯·空轮"}},{q="他为什么要研究软泥怪？",a="拉里斯拥有一颗敏锐而古怪的科学头脑，并对活体黏液的本质和创造提出了独特的理论。他相信通过分析不同软泥怪产生的腐蚀性残留物，将能更深入地了解这些奇特生物是如何形成和复制的。",al={"为什么要研究软泥怪","拉里斯的黏液研究","软泥怪研究"}},{q="他为冒险者提供了什么任务？",a="拉里斯招募勇敢的旅行者前往险恶之地收集纯净的软泥怪样本。通过他的任务“软泥怪的样本”，他会提供空的软泥容器，并要求冒险者从他们在费伍德森林击杀的软泥怪身上采集样本，随后还会派遣他们去寻找纯净、未受污染的样本。",al={"拉里斯的任务","软泥怪的样本"}}},fx={a960bc4a={q="拉里斯·空轮效忠于哪一方？",a="拉里斯·空轮坚定地支持联盟和诺莫瑞根流亡者。他与矮人学者和研究人员一同在铁炉堡的Hall of Explorers工作，凭借敏锐的头脑和离奇的生物学理论，推动联盟对世界各地奇异现象的认知与研究。",al={"拉里斯·空轮阵营","拉里斯·空轮与联盟","拉里斯·空轮是否友好"}},["114e8ed2"]={q="拉里斯·空轮为什么在铁炉堡？",a="诺莫瑞根沦陷后，许多侏儒在铁炉堡的矮人盟友那里寻求庇护。拉里斯·空轮把Hall of Explorers内的图书馆当作家，那里是理想的避难之所，让他能专心进行离奇的学术研究，并利用丰富的历史与自然档案，整理关于软泥怪起源的理论。",al={"拉里斯·空轮为什么在这里","拉里斯·空轮与hall of explorers","拉里斯为什么在铁炉堡"}}},fp="16,316,16.558.0,24.220.0,34.139.0,25.279.0,37.309.0"}
P.entries["npc:lars"] = {n="拉尔斯",s="拉尔斯是一名四面楚歌的人类幸存者，在暮色森林的荒野中露营。他和他的同伴斯温·约根一起，在寂静河岸的北缘艰难地坚守阵地，抵御着徘徊在森林中的恐怖生物。",h="拉尔斯是一名四面楚歌的人类幸存者，在暮色森林的荒野中露营。他和他的同伴斯温·约根一起，在寂静河岸的北缘艰难地坚守阵地，抵御着徘徊在森林中的恐怖生物。",kw={"营地","暮色森林","寂静河岸","拉尔斯","斯温·约根","狼","狼群在后"},ang={["faction:Alliance"]="拉尔斯是一名饱受折磨的人类平民，在城镇守卫的保护范围之外艰难求生，他很高兴能有愿意帮他斩杀盘旋在营地周围的狼群的联盟勇士。"},sec={{t="岌岌可危的营地",b="拉尔斯栖身于寂静河岸北缘的一个简陋营地里，远离夜色镇那尚存疑问的安全地带，勉强维持着岌岌可危的生存。暮色森林在最好的时候也充满了危险，更何况周围的树林里爬满了凶猛的野兽、无情的亡灵和潜行的狼人。拉尔斯紧跟在斯温·约根身边，只求在这片日益险恶的荒野中活下去。"},{t="来自荒野的威胁",b="想要在营地生存下去，必须时刻警惕当地的掠食者。拉尔斯发现自己正饱受成群结队的饥饿恐狼的袭扰，这些野兽在他营地的火光周围阴影中徘徊。因为无法放下戒备或独自将其击退，他只能指望有能力的旅行者来消灭这些饥肠辘辘的掠食者，以免他的小营地被完全淹没。"}},faq={{q="拉尔斯是谁？",a="拉尔斯是一名在暮色森林荒野中露营的人类幸存者。他和他的朋友兼同伴斯温·约根一起生活在寂静河岸的北界，竭尽所能地在森林的恐怖中求生。",al={"拉尔斯 暮色森林","拉尔斯是谁","拉尔斯 npc"}},{q="拉尔斯在哪里？",a="拉尔斯驻扎在寂静河岸北缘的一个小型荒野营地，位于暮色森林西部。",al={"拉尔斯在哪里","拉尔斯 位置","拉尔斯 营地"}},{q="拉尔斯面临什么问题？",a="拉尔斯和斯温不断受到潜伏在附近树林中的贪婪狼群和掠食者的骚扰。通过任务“狼群在后”，拉尔斯请求路过的冒险者在这些野兽撕碎他的营地之前将它们猎杀。",al={"拉尔斯 任务","狼群在后 任务","为什么拉尔斯需要帮助"}},{q="拉尔斯与斯温·约根是什么关系？",a="拉尔斯和斯温·约根是在荒野中共同生存的同伴。斯温在该地区有着属于他自己的黑暗往事和宿怨，而拉尔斯则帮忙维护他们这个简陋且与世隔绝的前哨站。",al={"拉尔斯和斯温","斯温与拉尔斯的关系"}}},fx={["05f5e77d"]={q="拉尔斯效忠于哪一方？",a="拉尔斯是一名独立的人类幸存者，支持联盟。他并未直接为夜色镇守卫或暴风城军队效力，只是与同伴斯温·约根一起，努力在暮色森林的险境中生存下去。",al={"拉尔斯阵营","拉尔斯是否属于联盟","拉尔斯为谁效力"}},["2eb2df94"]={q="拉尔斯为什么在暮色森林扎营？",a="拉尔斯在寂静河岸北缘一处崎岖的营地避难。他与斯温·约根结伴留在那里，日复一日地设法在黑暗的森林中生存，抵御逐渐逼近的掠食者和森林中的恐怖生物。",al={"拉尔斯为什么在这里","拉尔斯在暮色森林的原因","拉尔斯为什么来到这里"}}},fp="4,232,18.391.0,21.358.0,12.212.0,24.118.0,28.233.0,43.188.0"}
P.entries["npc:laurna-morninglight"] = {n="劳尔娜·晨光",s="劳尔娜·晨光是一位暗夜精灵牧师训练师，居住在泰达希尔宁静的多兰纳尔定居点。她致力于The Sisterhood of Elune，引导从幽影谷走出的新晋侍僧学习月神的神圣仪式和治愈恩典。她的教诲帮助年轻的暗夜精灵牧师做好准备，以应对日益威胁着世界之树枝叶的危机。",h="劳尔娜·晨光是一位暗夜精灵牧师训练师，居住在泰达希尔宁静的多兰纳尔定居点。她致力于The Sisterhood of...",kw={"多兰纳尔","艾露恩","卡多雷","劳尔娜","晨光","牧师训练师","the sisterhood of elune","泰达希尔"},ang={["class:Priest"]="对于从幽影谷走出来的暗夜精灵牧师来说，劳尔娜·晨光是你们在新手谷之外的第一位重要导师，她将教授基础法术并引导你们对艾露恩的早期虔诚。",["race:NightElf"]="劳尔娜体现了卡多雷对月神的传统虔诚，她提醒冒险者们，泰达希尔的牧师之道源自艾露恩，而非圣光。"},sec={{t="多兰纳尔的向导",b="劳尔娜·晨光坐落在多兰纳尔的枝叶间，她是为那些完成了幽影谷初步仪式的年轻牧师提供指导的主要导师之一。随着新的入行者踏入泰达希尔更广阔的天地，她会指导他们加深与艾露恩的交流，在治愈之光与抵御日益凶恶的荒野所需的防御仪式之间取得平衡。"},{t="对月神的虔诚",b="卡多雷的牧师之道与人类和矮人所崇拜的抽象圣光不同，它与对艾露恩的信仰紧密相连。劳尔娜会指派学生进行精神历练，例如获取神圣长袍和治愈一名受伤的哨兵。通过这些传统，侍僧们明白他们的力量是月亮母亲直接赐予的礼物，旨在保护和救治卡多雷人民。"}},faq={{q="我在哪里可以找到劳尔娜·晨光？",a="劳尔娜·晨光驻扎在多兰纳尔村，位于泰达希尔中部，就在离幽影谷不远的路上。",al={"劳尔娜位置","劳尔娜在哪里","多兰纳尔牧师训练师"}},{q="劳尔娜·晨光有什么作用？",a="她是暗夜精灵角色的牧师训练师。她教授新法术，提升已知技能的等级，并提供职业特定仪式的早期指导。",al={"她做什么","劳尔娜职责","劳尔娜牧师训练师"}},{q="她提供什么样的任务？",a="她会开启新晋牧师的职业任务，引导他们去援助受伤的盟友，并通过仪式法衣和祈祷寻求艾露恩的神圣眷顾。",al={"劳尔娜任务","多兰纳尔牧师任务"}},{q="她会训练其他种族吗？",a="虽然她的文化根源于The Sisterhood of Elune，但联盟的牧师训练师会指导任何前来寻求精神修行的盟友牧师。",al={"人类可以在这里训练吗","任何种族牧师训练师"}},{q="她隶属于Temple of the Moon吗？",a="是的，作为一名卡多雷女祭司，她的誓言和魔法完全奉献给女神艾露恩，以及由达纳苏斯的Temple of the Moon所监管的更广泛的传统。",al={"她是否属于the sisterhood of elune","劳尔娜temple of the moon"}},{q="她和其他暗夜精灵有家族关系吗？",a="在泰达希尔的卡多雷中，没有已知的劳尔娜亲属。",al={"晨光家族","劳尔娜亲属"}}},fx={["3c87933c"]={q="劳尔娜·晨光是谁？",a="劳尔娜·晨光是一位居住在多兰纳尔的暗夜精灵女祭司和导师。她虔诚地崇拜艾露恩，引导刚踏上泰达希尔的年轻侍僧和新晋信徒，教他们引导女神宁静的光辉，并祈求神圣庇护。",al={"劳尔娜·晨光是谁","劳尔娜是谁","劳尔娜·晨光的背景"}},["5c82db11"]={q="劳尔娜·晨光效忠于哪一方？",a="她坚定地效忠于达纳苏斯的暗夜精灵、The Sisterhood of Elune以及联盟。作为月亮女神的侍僧，她一心守护族人，并引导泰达希尔上的卡多雷维系心灵上的安宁。",al={"劳尔娜·晨光阵营","劳尔娜·晨光为谁效力","劳尔娜·晨光与联盟"}},["6a7a4981"]={q="劳尔娜·晨光想要什么？",a="她最热衷于教导新手牧师艾露恩之道。她希望有潜力的侍僧培养与神明的联系，精通治疗祷言，并运用神圣的衣袍帮助泰达希尔枝干间的同胞。",al={"劳尔娜·晨光的动机","劳尔娜·晨光的职责"}},["65cf8731"]={q="劳尔娜·晨光为什么在多兰纳尔？",a="多兰纳尔是年轻冒险者离开幽影谷隐秘林地后，最主要的交通要道和集结地。劳尔娜驻守于此，确保逐渐成长的牧师在泰达希尔承担更重要的职责时，能得到适当的指引、教导和神圣仪式。",al={"劳尔娜为什么在多兰纳尔","劳尔娜·晨光为什么在这里"}}},fp="19,383,19.397.0,28.400.0,37.141.0,33.165.0,35.158.0,27.162.0,46.168.0,52.66.0"}
P.entries["npc:lelanai"] = {n="莱兰奈",s="莱兰奈是一名居住在达纳苏斯塞纳里奥区的暗夜精灵坐骑训练师。她向有资格的骑手提供暗夜精灵的凶猛豹坐骑，为她的族人和达纳苏斯值得信赖的盟友提供标准的夜刃豹和迅捷的战斗猛兽。",h="莱兰奈是一名居住在达纳苏斯塞纳里奥区的暗夜精灵坐骑训练师。她向有资格的骑手提供暗夜精灵的凶猛豹坐骑，为她的族人和达纳苏斯值得信赖的盟友提供标准的夜刃豹和迅捷的战斗猛兽。",kw={"塞纳里奥区","达纳苏斯","霜刃豹","贾萨姆","莱兰奈","坐骑商人","夜刃豹"},ang={["faction:Alliance"]="在达纳苏斯声望达到崇拜的联盟英雄可以寻找莱兰奈，骑着这些标志性的豹坐骑与卡多雷盟友并肩作战。",["race:NightElf"]="对于暗夜精灵来说，拜访莱兰奈是获得他们传统猫科坐骑的必经之路。"},sec={{t="塞纳里奥区的繁育者",b="莱兰奈驻守在达纳苏斯塞纳里奥区参天大树下的骑术训练师贾萨姆身边，照料着卡利姆多培育出的最优秀的猫科动物。暗夜精灵与北方森林的这些凶猛捕食者有着深厚的羁绊，他们训练夜刃豹和霜刃豹，让哨兵和斥候能以捕食者般的优雅穿梭于崎岖的地形。莱兰奈是这座首都中这些备受尊崇的坐骑的主要提供者。"},{t="超越种族的羁绊",b="虽然夜刃豹坐骑可以自由提供给任何具备相应技巧的暗夜精灵，但外族人面临着严格得多的门槛。考虑到这些猫科动物的神圣本性以及卡多雷天生的疏离感，除非冒险者在达纳苏斯城赢得了最高程度的尊重和声望，否则莱兰奈不会将这些野兽托付给非暗夜精灵。"}},faq={{q="我在哪里可以找到莱兰奈？",a="莱兰奈位于达纳苏斯的塞纳里奥区，就站在虎骑术训练师贾萨姆旁边。",al={"莱兰奈位置","莱兰奈在哪里","莱兰奈地图"}},{q="莱兰奈出售什么？",a="她出售各种霜刃豹和夜刃豹坐骑的缰绳，包括供老练骑手使用的迅捷装甲品种。",al={"莱兰奈的商品","她有什么坐骑","暗夜精灵坐骑"}},{q="非暗夜精灵可以从莱兰奈那里购买坐骑吗？",a="可以，但前提是他们必须通过在达纳苏斯达到崇拜声望来证明其非凡的忠诚。否则，她会拒绝向外族人出售她的野兽。",al={"人类可以买豹坐骑吗","矮人可以骑夜刃豹吗","豹坐骑需要的声望"}},{q="部落玩家可以与莱兰奈互动吗？",a="不可以。莱兰奈效忠于联盟的达纳苏斯阵营。部落成员会被她和附近的区守卫视为敌对入侵者。",al={"部落可以买豹坐骑吗","莱兰奈对部落友好吗"}}},fx={["8575cac4"]={q="莱兰奈是谁？",a="莱兰奈是一位居住在达纳苏斯的暗夜精灵坐骑饲养者和商人。她驻守在绿意盎然的塞纳里奥区，照料为卡多雷培育的威武剑齿虎，并将它们交给值得信赖、能够驾驭这些凶猛猫科猛兽的勇士。",al={"莱兰奈是谁","莱兰奈的身份","莱兰奈的背景"}},["4b3049f5"]={q="莱兰奈效忠于哪一方？",a="莱兰奈效忠于达纳苏斯和更广大的联盟。她乐于将训练有素的剑齿虎托付给同胞，但只有当其他联盟成员在族人中赢得最高声望与信任时，她才会考虑把坐骑交给他们。",al={"莱兰奈阵营","莱兰奈是否属于联盟","莱兰奈为谁效力"}},["18fb2d04"]={q="莱兰奈为什么在达纳苏斯？",a="她与骑术训练师Jartsam一同居住在达纳苏斯的塞纳里奥区。在泰达希尔宁静的枝干间，她饲养并照料霜刃豹和夜刃豹坐骑，这些坐骑对卡多雷哨兵和旅行者都至关重要。",al={"莱兰奈为什么在达纳苏斯","莱兰奈在塞纳里奥区的职责","莱兰奈为什么在这里"}},["14c3da8f"]={q="莱兰奈想要什么？",a="莱兰奈希望自己珍爱的夜刃豹和霜刃豹坐骑都能找到合适的骑手。她坚持要求所有想骑乘这些猛兽的人都接受过适当训练，并且真正忠于达纳苏斯、尊敬达纳苏斯。",al={"莱兰奈想要什么","莱兰奈的目标","莱兰奈的动机"}},ec77c23e={q="莱兰奈与谁关系密切？",a="莱兰奈与塞纳里奥区的暗夜精灵骑术教官Jartsam密切合作。Jartsam教有志成为骑手的人掌握骑乘猛虎的技巧，莱兰奈则提供与他们建立羁绊、可载他们驰骋卡利姆多的剑齿虎。",al={"莱兰奈的人际关系","莱兰奈与谁共事","莱兰奈与jartsam"}}},fp="7,257,31.437.0,20.352.0,25.112.0,23.126.0,44.160.0,40.150.0"}
P.entries["npc:lieutenant-farren-orinelle"] = {n="法尔林·奥里涅尔中尉",s="法尔林·奥里涅尔中尉是暴风城军队的一名军官，目前驻扎在希尔斯布莱德丘陵的南海镇旅店。由于对这次边境派遣深感不满，他大部分时间都在喝酒，并将职责外包给过路的旅人。他主要的军事任务是处理沿海地区不断侵扰的鱼人，但他急切地将这桩苦差事派发给别人，希望能以此确保调回南方。",h="法尔林·奥里涅尔中尉是暴风城军队的一名军官，目前驻扎在希尔斯布莱德丘陵的南海镇旅店。由于对这次边境派遣深感不满，他大部分时间都在喝酒，并将职责外包给过路的旅人。他主要的军事任务是处理沿海地区不断侵扰的鱼人，但他急切地将这...",kw={"法尔林","希尔斯布莱德","治安官雷德帕斯","鱼人","奥里涅尔","调职","南海镇","暴风城"},ang={["faction:Alliance"]="对于联盟的勇士来说，奥里涅尔代表了那些身处孤立的北方哨所、心怀不满的南方军队，他愿意为任何帮他分担职责的人提供金钱和赞赏。",["race:Human"]="作为一名远离艾尔文森林的暴风城士兵，奥里涅尔对北方边境任务的蔑视，凸显了舒适的首都生活与艰苦的海外部署之间的鸿沟。"},sec={{t="南海镇的流放",b="法尔林·奥里涅尔中尉并非自愿来到南海镇。他被从暴风城远远地调离，这位中尉觉得希尔斯布莱德潮湿且局势动荡的海岸远不如首都的文明舒适。奥里涅尔并没有去巡逻田野或与他的指挥官治安官雷德帕斯协调防御工作，而是几乎常驻在南海镇的旅店里。他整日消沉、饮酒，幻想着能收到一纸正式的调令，让他重返南方。"},{t="外包职责",b="尽管他在酒馆里坐得很舒服，但奥里涅尔仍需听命于治安官雷德帕斯。雷德帕斯指派他清理在附近海岸泛滥的鱼人。由于不愿弄脏自己的靴子，奥里涅尔选择依赖路过的冒险者去扑杀这些生物并收集证明。他希望向长官提交这些切实的结果，以证明他的职责已完成，从而加快他最终回到暴风城的进程。"}},faq={{q="谁是法尔林·奥里涅尔中尉？",a="他是驻扎在希尔斯布莱德丘陵的南海镇的一名暴风城军队军官。他整天在南海镇旅店里喝酒，抱怨着自己的驻地。",al={"法尔林·奥里涅尔","奥里涅尔是谁","南海镇中尉"}},{q="他为什么在南海镇？",a="他从暴风城被调往北方，以加强当地驻军并支援治安官雷德帕斯。他非常讨厌这个任务，渴望回到家乡。",al={"为什么法尔林在南海镇","奥里涅尔调职"}},{q="他的正式任务是什么？",a="治安官雷德帕斯命令他处理在希尔斯布莱德海岸肆虐的敌对鱼人，尽管奥里涅尔更愿意付钱让路过的雇佣兵代他作战。",al={"法尔林的职责","奥里涅尔的任务","法尔林的鱼人任务"}},{q="他会离开南海镇旅店吗？",a="不会。奥里涅尔几乎所有时间都待在旅店的吧台旁，不愿去面对外面泥泞的海滩或敌对势力。",al={"在哪里能找到法尔林","法尔林的位置","奥里涅尔的旅店"}},{q="法尔林的最终目标是什么？",a="他最大的心愿就是获得一份正式的调令，返回暴风城，远离洛丹伦海岸的危险与荒凉。",al={"法尔林想要什么","重新分配"}},{q="谁是奥里涅尔的指挥官？",a="他向治安官雷德帕斯汇报工作，后者指挥着保卫南海镇的联盟军事分队。",al={"法尔林的上级","法尔林的老板","谁指挥法尔林"}}},fx={["7d023078"]={q="法尔林·奥里涅尔中尉效忠于哪一方？",a="奥里涅尔中尉为联盟效力，直接听命于暴风城军方。尽管他厌恶自己目前在希尔斯布莱德丘陵的差事，但他受治安官雷德帕斯指挥，负责协助南海镇守军抵御当地的恐怖威胁和部落的侵袭。",al={"奥里涅尔的阵营","法尔林·奥里涅尔与联盟","法尔林为谁效力"}}},fp="26,423,19.515.0,16.458.0,34.183.0,24.167.0,32.172.0,38.136.0,31.143.0,28.98.0"}
P.entries["npc:lieutenant-haggerdin"] = {n="哈格丁中尉",s="哈格丁中尉是一位驻扎在奥特兰克山脉海岬的矮人军官。他守卫着通往奥特兰克山谷的要塞大门，担任雷矛卫队的主要招募和联络官。他负责评估有志向的联盟勇士，并嘉奖那些在对抗霜狼氏族的战斗中展现出英勇表现的人。",h="哈格丁中尉是一位驻扎在奥特兰克山脉海岬的矮人军官。他守卫着通往奥特兰克山谷的要塞大门，担任雷矛卫队的主要招募和联络官。他负责评估有志向的联盟勇士，并嘉奖那些在对抗霜狼氏族的战斗中展现出英勇表现的人。",kw={"奥特兰克","矮人","霜狼","哈格丁","海岬","铁炉堡","中尉","试炼场","雷矛"},ang={["faction:Alliance"]="哈格丁中尉是你奥特兰克山谷外的主要联络人，负责提供你在与霜狼氏族交战时所获得的凭证和官方荣誉。",["faction:Horde"]="作为守卫联盟通往奥特兰克山谷传送门的坚定哨兵，哈格丁负责指挥前往粉碎霜狼兽人的增援部队。",["race:Dwarf"]="作为雷矛部族的一名骄傲的军官，哈格丁体现了铁炉堡在奥特兰克白雪皑皑的峭壁中发掘泰坦遗产的坚定决心。"},sec={{t="海岬看门人",b="哈格丁中尉坐镇在希尔斯布莱德丘陵上方白雪皑皑的海岬高处，负责监管联盟在奥特兰克山谷持续进行的战役的集结点。巨大的木门旁飘扬着矮人的旗帜，新兵和老兵在他的注视下集结，准备投入这片严寒的战区。"},{t="雷矛卫队的代言人",b="哈格丁服务于雷矛远征军，确保只有经过考验的战士才能代表铁炉堡和大联盟进入山谷。通过“试炼场”之类的挑战，他会指派新兵去回收旗帜和遗物，并在士兵提升雷矛卫队军衔时授予正式的嘉奖、徽章和军衔认可。"}},faq={{q="哈格丁中尉是谁？",a="哈格丁中尉是一位代表雷矛卫队的矮人军官。他驻扎在奥特兰克山脉海岬处的奥特兰克山谷入口，负责监管联盟的招募工作并授予战场荣誉。",al={"哈格丁","哈格丁是谁","奥特兰克哈格丁中尉"}},{q="我在哪里可以找到哈格丁中尉？",a="他位于北奥特兰克山脉的海岬，就站在通往奥特兰克山谷的传送门和大门外。",al={"哈格丁位置","哈格丁中尉在哪里","奥特兰克山谷联盟入口"}},{q="哈格丁在雷矛卫队中扮演什么角色？",a="他担任前线联络官和军需官，管理包括“试炼场”在内的招募试炼，并随着联盟战士在雷矛卫队中声望的提升，为他们提供更高的军衔和徽章。",al={"哈格丁做什么","哈格丁任务","雷矛卫队军官"}},{q="联盟为什么要在大奥特兰克山谷作战？",a="雷矛远征军进入山谷是为了发掘古代遗物和矮人历史，但他们的到来引发了与当地霜狼兽人及其部落盟友之间激烈的领土冲突。",al={"为什么去奥特兰克山谷","雷矛远征军目标","奥特兰克冲突"}},{q="部落玩家可以与哈格丁中尉互动吗？",a="不可以。哈格丁中尉是一位现役的联盟军官，他会攻击任何胆敢靠近海岬大门的部落勇士。",al={"哈格丁是否敌视部落","部落哈格丁","部落可以和哈格丁对话吗"}},{q="“试炼场”试炼是什么？",a="“试炼场”是哈格丁交给有志向的联盟士兵的一项入门任务，旨在他们在全力投入奥特兰克山谷的战争之前，验证他们的能力和决心。",al={"试炼场任务","奥特兰克试炼场","哈格丁试炼场"}}},fx={["9b7a183a"]={q="哈格丁中尉效忠于谁？",a="哈格丁直接隶属于雷矛卫队。雷矛卫队是铁炉堡雷矛远征军的军事力量，由范达尔·雷矛将军率领。他担任军官，负责联络经由奥特兰克山脉抵达的联盟新兵与深入奥特兰克山谷作战的团部。",al={"哈格丁的效忠对象","哈格丁与雷矛卫队","哈格丁效力于谁"}},["1d45d886"]={q="哈格丁中尉效忠于哪一方？",a="哈格丁中尉完全效忠于联盟，具体来说，他隶属于雷矛卫队。他在靠近奥特兰克山谷的丘陵北缘执行任务，担任军官和征召员，协助集结联盟部队对抗霜狼兽人。",al={"哈格丁的阵营","哈格丁是否属于联盟","哈格丁的效忠对象"}},["5fb68a23"]={q="哈格丁中尉想要什么？",a="哈格丁希望有能力的联盟勇士能壮大奥特兰克山谷中雷矛卫队的队伍。他会考验新兵，确保他们能够在冰冷的荒野中生存；随着老兵战功日增，他会授予他们军衔和徽记。他还希望铲除冬斧巨魔勇士科尔拉克等威胁。",al={"哈格丁想要什么","哈格丁的目标","哈格丁的职责"}},["96f37aaa"]={q="哈格丁中尉为什么在奥特兰克丘陵？",a="哈格丁中尉驻守在俯瞰奥特兰克山谷入口的岬角，负责组织并审核前来增援的联盟部队。雷矛远征队与霜狼氏族之间的战斗仍在持续，急需不断增援，因此他驻守在集结地，招募并嘉奖愿意在雪地中奋战的人。",al={"哈格丁为什么在这里","哈格丁为什么在奥特兰克","哈格丁的驻守地点"}}},fp="20,345,26.335.0,28.362.0,28.224.0,38.145.0,53.231.0,47.211.0,53.126.0,34.195.0"}
P.entries["npc:lieutenant-lisande"] = {n="利山德中尉",s="利山德中尉是银色黎明派驻在雷霆崖高耸台地上的使节。作为一名在牛头人领地公开活动的平民，她担任着联络员的角色，以应对天灾军团这一共同的生存威胁。",h="利山德中尉是银色黎明派驻在雷霆崖高耸台地上的使节。作为一名在牛头人领地公开活动的平民，她担任着联络员的角色，以应对天灾军团这一共同的生存威胁。",kw={"银色黎明","利山德中尉","利山德","莫高雷","天灾军团","天灾入侵","雷霆崖"},ang={["faction:Horde"]="利山德的存在提醒着人们，对抗天灾军团的战争需要务实精神，有时也需要与中立的人类组织进行合作。",["race:Tauren"]="虽然利山德是个外来者，但牛头人尊重银色黎明为净化土地、消除亡灵邪恶腐蚀所做出的贡献。"},sec={{t="不同寻常的使者",b="虽然在风吹拂过的雷霆崖高地上很少见到人类的面孔，但银色黎明的宗旨超越了传统的阵营敌对。利山德中尉效力于该圣教组织，密切关注着巫妖王腐蚀的迹象，即使在遥远的卡利姆多也是如此。当下方的平原上出现亡灵活动的迹象时，她会召集勇敢的部落勇士出征，在威胁玷污这片神圣土地之前探查并消灭它们。"}},faq={{q="为什么会有个人类站在雷霆崖？",a="利山德代表的是银色黎明，这是一个只致力于消灭天灾军团的中立组织。因为银色黎明欢迎联盟和部落的种族加入其行列，所以其联络员被允许以外交身份进入各主城，以协调对抗亡灵的防御工作。",al={"雷霆崖的人类","利山德为什么在这里","她有敌意吗"}},{q="银色黎明对莫高雷有什么企图？",a="巫妖王的触手威胁着艾泽拉斯的每一个角落，而不仅仅是东部王国。利山德监控着任何威胁莫高雷和平的死灵活动或入侵的天灾军团部队的迹象，确保当地的守卫者对危险保持警惕。",al={"莫高雷的天灾军团","为什么在雷霆崖","牛头人领地的亡灵"}},{q="利山德中尉会提供什么任务？",a="利山德引导冒险者们下到台地去调查周边地区出现的天灾军团入侵迹象，并要求他们回来汇报，以便银色黎明能够评估威胁的规模。",al={"利山德任务","利山德做什么","调查任务"}}},fx={["986453a4"]={q="利山德中尉是谁？",a="利山德中尉是银色黎明的一名军官。尽管她是身处部落领地腹地的人类，却公开驻守在雷霆崖，号召勇敢的守卫者抵御威胁所有生灵的祸患。",al={"利山德是谁","利山德中尉身份","利山德中尉是谁"}},b5328b2a={q="利山德中尉属于哪一方？",a="利山德效忠的是银色黎明，而非联盟。银色黎明是一个中立组织，全心致力于对抗天灾军团，因此她能够与牛头人和部落英雄并肩作战，不受阵营敌意影响。",al={"利山德属于联盟还是部落","利山德效力于谁","利山德是联盟成员吗"}},["9158bc2a"]={q="利山德中尉想要什么？",a="利山德希望警觉的冒险者调查并迎击逼近雷霆崖周边土地的天灾军团。她的目标是在亡灵威胁席卷莫高雷平原之前遏止它。",al={"利山德想要什么","利山德的目标","利山德为何需要帮助"}},["0fde76ad"]={q="利山德中尉效忠于谁？",a="她直接隶属于银色黎明。这个独立组织由来自不同种族的圣骑士、法师和斥候组成，无论亡灵威胁出现在哪里，都会与天灾军团作战。",al={"利山德的阵营","利山德与谁合作","利山德的关系"}}},fp="18,223,17.412.0,41.280.0,46.253.0,44.211.0"}
P.entries["npc:lieutenant-nevell"] = {n="奈维尔中尉",s="奈维尔中尉是银色黎明的一名军官，驻扎在丹莫罗的铁炉堡大门外。作为抵御天灾军团蔓延黑暗的堡垒，他负责协调当地的防御力量，并向抵达的冒险者发出警告，提醒他们注意在矮人王国边境徘徊的亡灵威胁。",h="奈维尔中尉是银色黎明的一名军官，驻扎在丹莫罗的铁炉堡大门外。作为抵御天灾军团蔓延黑暗的堡垒，他负责协调当地的防御力量，并向抵达的冒险者发出警告，提醒他们注意在矮人王国边境徘徊的亡灵威胁。",kw={"银色黎明","丹莫罗","铁炉堡","奈维尔中尉","奈维尔","天灾军团"},ang={["faction:Alliance"]="对于前往铁炉堡的联盟勇士来说，奈维尔的存在提醒着他们：对抗天灾军团的战争不仅仅局限于北方。",["race:Dwarf"]="矮人们很感激银色黎明在他们山中家园外的守望，因为他们知道，即使在丹莫罗冰冷的斜坡上，也需要对死灵法术保持警惕。"},sec={{t="风雪中的守望",b="虽然银色黎明因在破碎的洛丹伦瘟疫之地坚守防线而闻名，但他们的警惕触角已延伸至遥远的南方。奈维尔中尉驻扎在铁炉堡外凛冽的寒风中，代表着该组织对死灵入侵的积极防御。当丹莫罗的山道中出现天灾军团的活动迹象时，奈维尔会引导新兵和有能力的冒险者前往前线，以确保铁炉堡冰雪覆盖的家园门前安然无恙。"}},faq={{q="奈维尔中尉是谁？",a="奈维尔中尉是银色黎明的一名军官，驻扎在丹莫罗的铁炉堡附近。他的任务是集结当地的防御力量，并调查任何侵犯矮人王国的亡灵天灾迹象。",al={"奈维尔的角色","奈维尔是谁","奈维尔中尉"}},{q="为什么银色黎明会出现在铁炉堡外？",a="尽管银色黎明的主要基地位于洛丹伦，但他们时刻监视着整个大陆，防范亡灵入侵。如果巫妖王试图深入盟友领地（如丹莫罗）进行打击，像奈维尔这样的军官就会被派遣前往，以协调城市防御并侦察敌人的动向。",al={"银色黎明在丹莫罗","银色黎明铁炉堡"}},{q="奈维尔中尉要求冒险者做什么？",a="奈维尔委托有能力的英雄们冒险走出铁炉堡大门，去侦察并击退附近的天灾军团部队，在亡灵于山口建立据点之前将其威胁消灭。",al={"奈维尔的任务","调查天灾军团"}}},fx={["4853a4a6"]={q="奈维尔中尉属于哪一方？",a="奈维尔中尉效力于银色黎明，这是一个致力于保护艾泽拉斯免受天灾军团侵害的中立组织。尽管他是人类，却驻守在铁炉堡大门外，作为对抗亡灵威胁者的盟友，与矮人协同组织防御，而非直接效力于联盟军队。",al={"奈维尔中尉的阵营","奈维尔中尉为谁而战","奈维尔属于银色黎明吗"}},["5e43a7a7"]={q="奈维尔中尉效忠于谁？",a="奈维尔直接听命于银色黎明的领导层。他驻扎在丹莫罗的山坡上，担任该组织与铁炉堡守卫者之间的联络人，召集当地冒险者和山地守卫，共同应对该地区任何潜伏的天灾威胁。",al={"奈维尔的关系","奈维尔中尉与银色黎明的关系","奈维尔听命于谁"}}},fp="17,292,19.476.0,25.208.0,41.278.0,50.205.0"}
P.entries["npc:lieutenant-orrin"] = {n="奥林中尉",s="奥林中尉是银色黎明的一名军官，驻守在暴风城的城门处。他站在英雄谷，负责协调当地的防御以抵御天灾军团的入侵，并指导新兵调查首都墙外的亡灵威胁。",h="奥林中尉是银色黎明的一名军官，驻守在暴风城的城门处。他站在英雄谷，负责协调当地的防御以抵御天灾军团的入侵，并指导新兵调查首都墙外的亡灵威胁。",kw={"银色黎明","奥林中尉","死灵水晶","奥林","天灾军团","暴风城","亡灵","英雄谷"},ang={["class:Paladin"]="秉持圣光的圣骑士们往往会与银色黎明肃清亡灵的努力产生共鸣。",["faction:Alliance"]="对于回到首都的联盟勇士来说，奥林是一个严峻的提醒：即使是南方的腹地也并非完全不受巫妖王魔爪的威胁。"},sec={{t="城门的哨兵",b="虽然银色黎明以在北方的废墟中坚守前线而闻名，但他们的力量也延伸到了南方，以保卫像暴风城这样的重要据点。奥林中尉站在英雄谷的高大雕像旁，注视着道路，寻找任何腐化的迹象。当首都外出现死灵魔法的骚动时，他的职责是发出警报并召集冒险者，在邪恶势力威胁到民众之前采取行动。"},{t="注视着不死者",b="奥林是这个独立组织与南方王国志愿者之间的主要联络人。当城门外出现天灾军团的踪迹时，他会召集有能力的侦察兵，派他们去搜集情报并获取危险的文物，例如破裂的死灵水晶，以更好地了解并抵御亡灵的威胁。"}},faq={{q="奥林中尉是谁？",a="奥林中尉是一名服务于银色黎明的人类军官。他驻扎在暴风城入口处的英雄谷，负责在天灾军团威胁周边土地时协调防御并招募侦察兵。",al={"奥林是谁","奥林中尉背景故事","那个银色黎明军官是谁"}},{q="为什么银色黎明会出现在暴风城？",a="尽管银色黎明主要在瘟疫之地与天灾军团交战，但他们也在联盟和部落的主要枢纽城市维持着哨所和联络处。像奥林这样的军官驻扎在首都的城门处，监视着死灵入侵，并招募有能力的战士来阻止亡灵的蔓延。",al={"为什么银色黎明在暴风城","银色黎明暴风城","银色黎明在这里做什么"}},{q="奥林中尉会让冒险者做什么？",a="奥林指导新兵去侦察暴风城外围，调查天灾军团的活动迹象，并回收像破裂的死灵水晶这样的文物，以研究入侵背后的邪恶魔法。",al={"奥林的任务","调查暴风城的天灾","奥林想要什么"}}},fp="16,223,23.352.0,20.332.0,24.213.0,41.210.0,49.245.0"}
P.entries["npc:loganaar"] = {n="洛甘纳尔",s="洛甘纳尔是一位居住在月光林地永夜港的暗夜精灵德鲁伊导师。他致力于指导来自联盟和部落的入门者，引导年轻的德鲁伊与自然协调，并为迎接翡翠梦境的召唤做好准备。",h="洛甘纳尔是一位居住在月光林地永夜港的暗夜精灵德鲁伊导师。他致力于指导来自联盟和部落的入门者，引导年轻的德鲁伊与自然协调，并为迎接翡翠梦境的召唤做好准备。",kw={"塞纳里奥议会","德鲁伊训练师","翡翠梦境","洛甘纳尔","月光林地","永夜港"},ang={["class:Druid"]="对于来自达纳苏斯和雷霆崖的德鲁伊来说，洛甘纳尔是他们在传送至月光林地后最早见到的导师之一，他提供进阶训练和精神指引。",["race:NightElf"]="洛甘纳尔体现了卡多雷德鲁伊的古老传统，他们曾在玛法里奥·怒风的领导下，花费数千年的时间与自然交流并进入翡翠梦境。"},sec={{t="神圣技艺的守护者",b="洛甘纳尔身处永夜港宁静的枝桠间，是前往月光林地的新晋德鲁伊的主要导师。无论入门者来自达纳苏斯还是雷霆崖，洛甘纳尔都会为他们提供关于平衡、变形术以及对自然尊崇的指导。他提醒学生，即使身处冰冷的岩石和陌生的土地，真正的宁静也必须从内心寻得。他还作为向导，欢迎那些深入探索塞纳里奥议会事务的人，将有前途的学生派遣给安戈洛环形山的漫游者，如托尔瓦·寻路者，或引导他们深入参与古老的林地仪式。"},{t="梦境的召唤",b="除了基础的法术，洛甘纳尔还让学生们为卡利姆多传统守护者共同的终极命运做好准备：翡翠梦境的长眠。他指导入门者了解艾泽拉斯原始灵魂领域与清醒世界之间的神圣联系，提醒他们，真正的精通终有一天需要长达数世纪的冬眠，以便在半神的指引下，行走于自然最纯净、未受玷污的形态之中。"}},faq={{q="洛甘纳尔是谁？",a="洛甘纳尔是一位常驻于月光林地中心定居点——永夜港的暗夜精灵德鲁伊训练师。他欢迎所有背景的德鲁伊前来训练技艺，并引导他们深入了解塞纳里奥议会的传统。",al={"洛甘纳尔 npc","洛甘纳尔是谁","洛甘纳尔背景故事"}},{q="洛甘纳尔会训练部落德鲁伊吗？",a="是的。月光林地是由塞纳里奥议会监管的神圣中立之地。作为议会的一员，洛甘纳尔搁置了联盟与部落之间的冲突，指导牛头人和暗夜精灵德鲁伊。",al={"牛头人可以在洛甘纳尔处训练吗","洛甘纳尔 部落","月光林地德鲁伊训练师 部落"}},{q="洛甘纳尔关于翡翠梦境教导了什么？",a="洛甘纳尔教导说，每一位真正的德鲁伊最终都会感受到翡翠梦境的召唤。他解释说，在长期的深度冬眠中漫步于其未受腐蚀的形态间，正是德鲁伊接受最终训练的地方。",al={"洛甘纳尔 梦境","翡翠梦境 语录"}},{q="洛甘纳尔会将经验丰富的德鲁伊派遣到哪里？",a="随着德鲁伊经验的增长，洛甘纳尔会指引他们前往各地，观察并修复艾泽拉斯原始的生态系统。在他的任务中，他会派遣经验丰富的弟子去协助安戈洛环形山荒野中的博物学家，例如托尔瓦·寻路者。",al={"洛甘纳尔 任务","托尔瓦·寻路者 任务 洛甘纳尔"}}},fp="8,261,24.626.0,21.439.0,16.225.0,33.211.0,49.225.0,41.245.0"}
P.entries["npc:lomac-gearstrip"] = {n="洛玛克·链带",s="洛玛克·链带是一位雄心勃勃的侏儒发明家，居住在铁炉堡的Tinker Town。他因研制出毁灭性的NG-5炸药而闻名，并与活跃在卡利姆多各地的侏儒研究员保持联络。",h="洛玛克·链带是一位雄心勃勃的侏儒发明家，居住在铁炉堡的Tinker Town。他因研制出毁灭性的NG-5炸药而闻名，并与活跃在卡利姆多各地的侏儒研究员保持联络。",kw={"一位老同事","侏儒工程师","笨拙+化学=乐趣","铁炉堡","洛玛克·链带","ng-5炸药","石爪山脉","tinker town"},ang={["faction:Alliance"]="在铁炉堡和卡利姆多远征前哨之间往来的联盟特工经常代表洛玛克处理敏感的军械和易挥发的配方。",["profession:Engineering"]="洛玛克的NG-5炸药代表了侏儒烟火工程的最前沿，为那些对高威力爆破化合物感兴趣的修补匠提供了灵感。",["race:Gnome"]="洛玛克体现了Tinker Town侏儒们坚韧不拔的精神，即使在远离诺莫瑞根的流亡生活中，依然坚持进行高风险的技术研究。"},sec={{t="Tinker Town的火花",b="在铁炉堡Tinker Town齿轮碰撞和管道嘶鸣的声音中，洛玛克·链带钻研着侏儒军械的精髓。像许多逃离诺莫瑞根悲剧的流亡侏儒一样，洛玛克已将他的修补匠作业直接融入了这座矮人首都。他的工作室专注于制造易挥发的化学混合物和特种弹药，旨在攻克防御森严的敌方据点。"},{t="NG-5炸药",b="洛玛克对现代战斗工程最引以为傲的贡献就是NG-5炸药。为了达到最大的破坏力，这种化合物需要精确的处理和稀有的化学试剂。为了在实地改进和部署这些危险的发明，洛玛克与驻扎在遥远战区的旧同事保持联系，并跨越无尽之海交换技术指令和危险物资。"}},faq={{q="我在哪里可以找到洛玛克·链带？",a="洛玛克·链带居住在铁炉堡这座山中城市东部的侏儒区，即Tinker Town。",al={"洛玛克·链带位置","洛玛克在哪里","寻找洛玛克·链带"}},{q="洛玛克·链带因发明了什么而闻名？",a="洛玛克最广为人知的身份是NG-5炸药的创造者，这是一种强效军械配方，旨在为侏儒的事业提供毁灭性的火力。",al={"洛玛克制作了什么","洛玛克的发明","ng-5炸药创造者"}},{q="洛玛克为什么要与卡利姆多的联络人打交道？",a="洛玛克与在石爪山脉等边境地区工作的前研究同僚保持联系，协调危险化学成分的采购，并在实战中测试他的高威力炸药。",al={"洛玛克 石爪山脉","为什么要去石爪山脉的任务","洛玛克的同事"}},{q="洛玛克会为冒险者提供什么样的任务？",a="洛玛克委托值得信赖的联盟信使在铁炉堡和驻扎在海外的研究员之间运输采购订单和易挥发的化学试剂，这些任务通常涉及他的NG-5炸药实验。",al={"洛玛克的任务","笨拙与化学的乐趣","一位老同事任务"}},{q="与洛玛克有关的采购订单收据是什么？",a="洛玛克编写了采购订单收据，这是一种用于组织和记录修补匠之间特种设备和危险化学试剂运输的清单。",al={"采购订单收据","洛玛克的收据"}},{q="洛玛克属于诺莫瑞根的流亡者吗？",a="是的。和Tinker Town的其他居民一样，洛玛克是流离失所的诺莫瑞根社区的一员，在铁炉堡矮人的庇护下生活，同时继续他的工程工作。",al={"洛玛克来自诺莫瑞根吗","洛玛克的阵营"}}},fx={e46167fb={q="洛玛克·链带是谁？",a="洛玛克·链带是一位雄心勃勃的侏儒发明家和技师，在铁炉堡这座矮人要塞内的Tinker Town活动。他一心投入危险的实验和化学工程，以研发强力军火闻名，例如NG-5炸药。尽管无尽之海相隔遥远，他仍在远至卡利姆多的地方维持联系和商业往来，以获取所需的稀有材料并进行实地测试。",al={"洛玛克是谁","链带是谁","洛玛克·链带的背景"}},["6618560a"]={q="洛玛克·链带想要什么？",a="洛玛克·链带一心投入他的爆炸物工程项目，尤其致力于改进得意之作NG-5炸药。为了继续进行化学试验，他需要信使、易爆化合物，以及使用他的混合物进行的实地测试。他依靠各地的旅行者和老相识帮忙完成采购订单，并取得完善危险发明所需的稀有试剂。",al={"洛玛克想要什么","洛玛克·链带的目标","洛玛克为何需要帮助"}},ca50cdb6={q="洛玛克·链带与谁有联系？",a="洛玛克与远方的伙伴和同行技师保持联系，其中包括一位在海外的老同事，能协助处理订单和专项测试。他在Tinker Town工作，与诺莫瑞根流亡者和铁炉堡的工匠都相处融洽，并指派信使和冒险者往来奔走，联络他在东部王国的工作台与卡利姆多的测试场。",al={"洛玛克与谁合作","洛玛克·链带的伙伴","洛玛克的老同事"}}},fp="15,212,22.406.0,18.398.0,33.125.0,45.148.0,46.240.0,51.206.0,49.169.0,47.196.0"}
P.entries["npc:longbraid-the-grim"] = {n="布莱德·长须",s="布莱德·长须是一位驻扎在湿地北部沦陷的丹莫德要塞外的铁炉堡矮人指挥官。他为失去兄弟和萨多尔大桥被攻占而感到悲痛，并协调幸存的矮人部队抵抗入侵的黑铁氏族。",h="布莱德·长须是一位驻扎在湿地北部沦陷的丹莫德要塞外的铁炉堡矮人指挥官。他为失去兄弟和萨多尔大桥被攻占而感到悲痛，并协调幸存的矮人部队抵抗入侵的黑铁氏族。",kw={"黑铁矮人","丹莫德","布莱德","萨多尔大桥","冷酷者","湿地","维尔加"},ang={["faction:Alliance"]="布莱德坚守着卡兹莫丹北门的防线，努力重新打通穿过萨多尔大桥进入阿拉希的关键陆路。",["race:Dwarf"]="对于铁炉堡的矮人来说，布莱德是他们与背信弃义的黑铁矮人表亲之间激烈且持久的血海深仇的化身，因为黑铁矮人直接攻击了他们的北部门户。"},sec={{t="痛苦的守望",b="布莱德·长须驻扎在通往阿拉希高地的大桥旁，在黑铁氏族占领丹莫德后，他集结了幸存的矮人守军。那场突袭摧毁了地区的防守力量，并导致布莱德的亲兄弟在萨多尔大桥的围攻中丧生。背负着悲伤与仇恨，布莱德拒绝放弃这条北部边界，指导旅行者和幸存的山地巡逻队员进行外科手术式的打击，以遏制黑铁氏族的推进。"},{t="坚守防线",b="除了守卫通往大桥的通路外，布莱德还负责湿地各处的广泛矮人行动。他派遣了关键的士兵护送勘察员维尔加进入沼泽地，并孜孜不倦地努力收复失陷的丹莫德要塞，誓要对黑铁破坏者进行报复。"}},faq={{q="谁是布莱德·长须？",a="布莱德·长须是一位驻扎在湿地北部丹莫德外的矮人指挥官。他领导当地的联盟抵抗力量，对抗占领了该地区的黑铁矮人。",al={"布莱德是谁","布莱德的身份","丹莫德矮人"}},{q="为什么布莱德被称为“冷酷者”？",a="在他的兄弟于黑铁氏族对萨多尔大桥的毁灭性袭击中丧生后，他变得性格冷酷。从那以后，他一直被为死去的亲人复仇的渴望所吞噬。",al={"为什么他被称为冷酷者","布莱德的兄弟","布莱德的背景故事"}},{q="丹莫德发生了什么事？",a="丹莫德被黑铁氏族攻陷并占领，他们伏击了矮人守军，并企图切断萨多尔大桥，从而阻断了湿地与阿拉希高地之间的主要通道。",al={"丹莫德的陷落","大桥发生了什么","萨多尔大桥遇袭"}},{q="布莱德与勘察员维尔加有什么关系？",a="当矮人挖掘队深入危险的湿地时，布莱德指派他手下的士兵去护送和保护勘察员维尔加。",al={"维尔加与布莱德","梅林的书信"}}},fx={d54d2b61={q="布莱德·长须属于哪一方？",a="布莱德·长须效忠于铁炉堡和联盟。他驻守在湿地北部，指挥矮人部队，试图抵挡占据丹莫德并破坏萨多尔大桥的黑铁氏族。",al={"布莱德的阵营","布莱德效力于谁","布莱德与联盟的关系"}},["40b05609"]={q="布莱德·长须想要什么？",a="布莱德渴望向黑铁矮人复仇。他们攻陷丹莫德，并在袭击萨多尔大桥时杀害了他的兄弟。他希望击溃他们的部队，为铁炉堡守住北部边境。",al={"布莱德·长须的目标","布莱德想要什么","布莱德的动机"}},["0c91256b"]={q="布莱德·长须为何在这里？",a="布莱德在湿地最北端的丹莫德郊外扎营，负责监视废墟并协调防御。黑铁矮人残暴入侵，摧毁了城镇和大桥；此后他一直留在前线，指挥反击逼近的敌人。",al={"布莱德为何在湿地","布莱德为何在丹莫德郊外","布莱德在此处的原因"}}},fp="18,280,14.492.0,16.312.0,26.184.0,35.189.0,26.205.0,53.161.0"}
P.entries["npc:loramus-thalipedes"] = {n="洛拉姆斯·萨里比迪斯",s="洛拉姆斯·萨里比迪斯是一位隐居的暗夜精灵恶魔猎手，居住在艾萨拉海岸外的一座偏远岛屿上。在忠诚的邪犬簇拥下，他将自己的一生奉献给了消灭亵渎者拉泽莱克的事业，引导经验丰富的勇士们通过仪式来击败这位恐惧魔王。",h="洛拉姆斯·萨里比迪斯是一位隐居的暗夜精灵恶魔猎手，居住在艾萨拉海岸外的一座偏远岛屿上。在忠诚的邪犬簇拥下，他将自己的一生奉献给了消灭亵渎者拉泽莱克的事业，引导经验丰富的勇士们通过仪式来击败这位恐惧魔王。",kw={"艾萨拉","恶魔猎手","邪能克星","邪犬","赫塔拉的巢穴","洛拉姆斯","拉泽莱克","萨里比迪斯"},ang={["class:Warlock"]="术士们会认出他所控制的邪犬是恶魔奴役能力的卓越证明，尽管洛拉姆斯束缚恶魔的目的仅仅是为了屠戮它们的同类。",["race:NightElf"]="暗夜精灵传统上对恶魔猎手怀有极大的恐惧和不信任，视他们仪式化的自我残缺和恶魔契约为一种不可原谅的道路，就像伊利丹的背叛一样。"},sec={{t="群岛的盲眼猎手",b="洛拉姆斯·萨里比迪斯伫立在赫塔拉的巢穴东南方一座孤零零且饱受风暴侵袭的岛屿上，与他的同胞们截然不同。他是一名恶魔猎手——一个为了获得幽灵视觉而经历了痛苦的自残仪式以致双目失明的流放者。在三头名为雷塔夫、沙希亚和扎曼的巨型邪犬的环绕下，洛拉姆斯注视着艾泽拉斯各地恶魔腐化的隐秘潮流，同时对破碎的艾萨拉遗迹保持着警惕。"},{t="横跨大陆的复仇",b="洛拉姆斯的执念横跨海洋，指向了诅咒之地，全部集中在恐惧魔王亵渎者拉泽莱克身上。由于深知常规的钢铁无法彻底终结狡猾的恶魔，洛拉姆斯引导旅行者们完成古老的仪式，要求他们收集艾萨拉之晶和恶魔的真名，以便锻造出对抗他的邪能克星武器。通过这些深奥的准备工作，他试图剥去拉泽莱克的防护，束缚住恶魔的真名，从而一劳永逸地结束这场宿怨。"}},faq={{q="洛拉姆斯·萨里比迪斯是谁？",a="洛拉姆斯·萨里比迪斯是一位居住在艾萨拉海岸外一座孤岛上的暗夜精灵恶魔猎手。他致力于挫败强大的恶魔，尤其是恐惧魔王亵渎者拉泽莱克。",al={"洛拉姆斯的身份","艾萨拉的恶魔猎手是谁","洛拉姆斯是谁"}},{q="为什么洛拉姆斯蒙着眼睛？",a="和其他恶魔猎手一样，洛拉姆斯放弃了自己的双眼。作为交换，这个仪式赋予了他侦测恶魔能量所需的幽灵视觉，这比普通凡人的视力更为重要。",al={"为什么洛拉姆斯没有眼睛","洛拉姆斯盲眼","恶魔猎手眼罩"}},{q="为什么有邪犬在守护他？",a="洛拉姆斯已经驯服并束缚了三头强大的邪犬——雷塔夫、沙希亚和扎曼——将它们原本的捕食本能转向服务于他的恶魔狩猎，而非燃烧军团。",al={"洛拉姆斯的邪犬","为什么洛拉姆斯会有恶魔","雷塔夫 沙希亚 扎曼"}},{q="他与诅咒之地有什么联系？",a="他策划了屠杀统治诅咒之地高地的恐惧魔王亵渎者拉泽莱克的行动。洛拉姆斯提供了洞穿拉泽莱克防御所需的关键知识、仪式和武器。",al={"洛拉姆斯与诅咒之地","拉泽莱克任务","他为什么关心诅咒之地"}}},fp="18,274,29.456.0,28.498.1,26.193.0,27.176.0,37.189.0,44.216.0"}
P.entries["npc:lord-arkkoroc"] = {n="亚考罗克",s="亚考罗克是一位古老而高大的海巨人，栖息在艾萨拉崎岖海岸边那座残破的亚考兰神殿中。恶魔猎手洛拉姆斯·萨里比迪斯称他为一位次级神灵，他统治着周围的水域，并指挥着那些被他视为子嗣的较小的海巨人。",h="亚考罗克是一位古老而高大的海巨人，栖息在艾萨拉崎岖海岸边那座残破的亚考兰神殿中。恶魔猎手洛拉姆斯·萨里比迪斯称他为一位次级神灵，他统治着周围的水域，并指挥着那些被他视为子嗣的较小的海巨人。",kw={"亚考兰","亚考罗克","艾萨拉","赫塔拉","洛拉姆斯","海巨人"},ang={["race:NightElf"]="亚考兰神殿的废墟矗立在曾经的上层精灵领地上，如今，一个古老的海洋实体在这里统治着古卡利姆多陨落的辉煌。"},sec={{t="沉没海岸之主",b="亚考罗克蜷缩在被盐碱覆盖的亚考兰神殿废墟中，他绝非普通的海巨人。对于像洛拉姆斯·萨里比迪斯这样的隐士来说，这个巨大的存在被视为一位次级神灵，其神圣的意志影响着周围的水域。他的子嗣们在圣地周围的礁石和浅滩巡逻，维护着他对艾萨拉波涛汹涌的海岸所实施的静默统治。"},{t="对深渊的复仇",b="尽管拥有巨大的神力，亚考罗克却在潮汐之下遭受了个人损失。一头名为赫塔拉的可怕多头海德拉在悬崖边猎杀了他的许多子嗣。由于无法或不愿亲自猎杀这头野兽，亚考罗克便与那些足够强大、能将他子嗣杀手的头颅带到他面前的游荡冒险者交换宝贵的知识和奥术援助。"}},faq={{q="谁是亚考罗克？",a="亚考罗克是一位巨大的海巨人，居住在艾萨拉的亚考兰神殿中。他被尊为海洋的次级神灵，并统治着一群被他视为子嗣的海巨人。",al={"谁是亚考罗克","亚考罗克背景故事","神殿海巨人"}},{q="我在哪里可以找到亚考罗克？",a="你可以在艾萨拉东部海岸线和岩礁上的亚考兰神殿废墟中找到他。",al={"亚考罗克位置","亚考罗克在哪里","寻找亚考罗克"}},{q="为什么洛拉姆斯·萨里比迪斯会派冒险者去找亚考罗克？",a="洛拉姆斯·萨里比迪斯指引旅行者去找亚考罗克，以寻求关于一个强大恶魔的奥术洞见。作为一位次级海洋神灵，亚考罗克掌握着古老的知识，但他要求冒险者在获得他的秘密之前必须杀死海德拉赫塔拉。",al={"洛拉姆斯与亚考罗克任务","野兽的名字"}},{q="为什么亚考罗克对海德拉赫塔拉感到愤怒？",a="野蛮的海洋野兽赫塔拉屠杀了几个在海岸线上巡逻的亚考罗克的子嗣。为了给被杀的亲族复仇，这位海巨人要求得到她的头颅。",al={"为什么要杀赫塔拉","亚考罗克与海德拉的恩怨"}}},fp="13,294,24.378.0,26.398.1,21.195.0,31.129.0,57.247.0,45.170.0"}
P.entries["npc:lord-baurles-k-wishock"] = {n="鲍雷斯·维沙克公爵",s="鲍雷斯·维沙克公爵是一位居住在Stormwind Keep之Petitioner's Chamber的贵族。他因未付账单和贪杯而闻名于酒保之间，且他在城中的贫民窟意外发现了比单纯酗酒更黑暗的交易。",h="鲍雷斯·维沙克公爵是一位居住在Stormwind Keep之Petitioner's Chamber的贵族。他因未付账单和贪杯而闻名于酒保之间，且他在城中的贫民窟意外发现了比单纯酗酒更黑暗的交易。",kw={"鲍雷斯","贵族议会","petitioner's chamber","slaughtered lamb","stormwind keep","维沙克","加尔德斯"},ang={["class:Warlock"]="维沙克对Slaughtered Lamb的多事调查对暴风城的暗影集会构成了直接威胁，这使得让他悄无声息地死去成为了术士们的首要任务。",["race:Human"]="他在Petitioner's Chamber的存在反映了少年国王安度因统治初期，贵族议会那种颓废、自私的声誉。"},sec={{t="一位贵族危险的好奇心",b="鲍雷斯·维沙克公爵在Stormwind Keep内的请愿者和政要中周旋，是颇具影响力的贵族议会成员。尽管地位显赫，维沙克却养成了频繁光顾Mage Quarter廉价酒吧的习惯，特别是Slaughtered Lamb，而且常常留下大笔未付的酒钱。然而，在喝酒时，他听说了地板下方的地窖里有术士集会正在进行邪恶仪式。维沙克决心关闭这家酒馆，开始向其他贵族请愿，要求进行正式调查——却没意识到，在暴风城揭露恶魔邪教的行为很少能善终。"},{t="一杯毒酒",b="维沙克的游说活动使他直接成为了城中隐藏术士们的目标。为了避免王室的审查或对他们地下据点的清查，黑爪加尔德斯策划了对这位贵族的悄然清除。利用维沙克对高档陈年佳酿的嗜好，邪教徒准备了一种伪装成美酒的致命混合物，并安排了一名受雇的冒险者在Keep守卫的眼皮底下将这杯致命的饮料送达。"}},faq={{q="谁是鲍雷斯·维沙克公爵？",a="鲍雷斯·维沙克公爵是一位隶属于贵族议会的贵族。他整日待在Stormwind Keep内的Petitioner's Chamber中，不过他在Mage Quarter因欠下大笔酒钱未付而臭名昭著。",al={"鲍雷斯 维沙克","谁是维沙克","贵族请愿者"}},{q="在哪里可以找到维沙克公爵？",a="他位于Stormwind Keep东侧的Petitioner's Chamber内，周围环绕着其他等待王室接见的朝臣、外交官和请愿者。",al={"维沙克位置","维沙克在哪里","找到维沙克公爵"}},{q="为什么Slaughtered Lamb下方的术士想要杀掉他？",a="在Slaughtered Lamb深夜饮酒期间，维沙克得知有一群术士在酒馆下方活动。他开始游说贵族议会发起正式调查并关闭该场所，这威胁到了要暴露他们的秘密行动。",al={"为什么要杀维沙克","加尔德斯 维沙克","为什么要毒杀维沙克"}},{q="他是如何被暗杀的？",a="黑爪加尔德斯调制了一种致命的毒药，并将其伪装成一种精致的饮料。由于了解维沙克对名酒和免费饮料的偏好，一名代理人将那桶下了毒的酒直接送到了他在Stormwind Keep的住所。",al={"维沙克怎么死的","维沙克中毒","贵族佳酿"}}},fp="23,227,32.527.0,14.403.1,31.197.0,32.173.0,63.232.1,23.238.1"}
P.entries["npc:lord-cobrahn"] = {n="考布莱恩",s="考布莱恩是潜伏在哀嚎洞穴深处的被腐化的尖牙德鲁伊的四位领袖之一。他曾是纳拉雷克斯高尚教团中的一名暗夜精灵德鲁伊，该教团旨在治愈贫瘠之地。后来，他屈服于感染了洞穴泉水的梦魇。考布莱恩化身为致命的毒蛇，如今统领着成群的变异蛇，守卫着这座扭曲的迷宫。",h="考布莱恩是潜伏在哀嚎洞穴深处的被腐化的尖牙德鲁伊的四位领袖之一。他曾是纳拉雷克斯高尚教团中的一名暗夜精灵德鲁伊，该教团旨在治愈贫瘠之地。后来，他屈服于感染了洞穴泉水的梦魇。考布莱恩化身为致命的毒蛇，如今统领着成群的变异蛇...",kw={"考布莱恩","变异蟒","尖牙德鲁伊","尖牙领主","考布莱恩宝石","哀嚎洞穴"},ang={["class:Druid"]="考布莱恩是一个严峻的警示，提醒人们当德鲁伊变形术与梦魇而非自然平衡相连时，会变得多么扭曲。",["faction:Horde"]="部落冒险者寻找考布莱恩，是为了终结蔓延至贫瘠之地的邪恶腐化，并保护卡利姆多平原脆弱的生态系统。",["race:NightElf"]="对于暗夜精灵来说，考布莱恩的堕落是一场悲剧，他们看到塞纳里奥议会的一位技艺精湛的兄弟抛弃了传承，转而在地底深处率领怪物。"},sec={{t="被腐化的德鲁伊",b="在堕落之前，考布莱恩是追随纳拉雷克斯的高尚德鲁伊之一。当纳拉雷克斯冒险进入贫瘠之地地下的哀嚎洞穴，希望能引出其中的地下泉水，让贫瘠的荒地重现生机时，考布莱恩便随行在侧。然而，当纳拉雷克斯与翡翠梦境的沟通堕落为扭曲的梦魇时，考布莱恩和他的兄弟们也随之精神崩溃。"},{t="蛇之拥抱",b="梦魇并没有让他引导塞纳里奥传统的图腾野兽，而是将考布莱恩的变形能力扭曲成了某种掠食性的爬行动物形态。他现在掌握着一种致命的毒蛇形态，并在战斗中将其释放出来。在毒性变异蟒的簇拥下，他挥舞着右手上凶狠的利爪，镇守着他所在的洞穴区域，暴力清除任何试图打破梦魇对洞穴控制的人。"}},faq={{q="考布莱恩在堕落前是谁？",a="在被梦魇侵蚀之前，考布莱恩是纳拉雷克斯高尚教团中的一名暗夜精灵德鲁伊，该教团曾进入哀嚎洞穴，希望利用那里的泉水来治愈贫瘠之地。",al={"考布莱恩的真名","考布莱恩是谁"}},{q="为什么他被称为考布莱恩？",a="没有记载解释过这个名字，但它很适合他。在哀嚎洞穴中被梦魇扭曲后，他化身为致命的毒蛇，身边围绕着变异蟒，而他的尖牙领主同伴安娜科德拉、派萨斯和瑟芬迪斯也有着类似蛇类的名字。",al={"为什么要找考布莱恩","考布莱恩名字含义"}},{q="在哪里可以找到考布莱恩？",a="考布莱恩居住在哀嚎洞穴的深处，这是一个位于贫瘠之地中部的地下扭曲网络，周围环绕着变异蟒和其他被梦魇腐化的野兽。",al={"考布莱恩位置","考布莱恩在哪里","考布莱恩所在的房间"}},{q="冒险者为什么要击败他？",a="他是领导尖牙德鲁伊的主要尖牙领主之一。他携带着考布莱恩宝石，雷霆崖的德鲁伊纳拉·野鬃正试图寻找它，以打破尖牙领主对贫瘠之地的控制。",al={"为什么要杀考布莱恩","尖牙领主考布莱恩"}},{q="他有什么独特的生理特征？",a="与普通的暗夜精灵不同，考布莱恩的身材明显更高大，右手长有锋利的利爪，并且在战斗中可以完全变形成一条巨大的毒蛇。",al={"考布莱恩长什么样","考布莱恩的外观"}},{q="他与其他尖牙德鲁伊有什么联系？",a="考布莱恩与安娜科德拉及其族人是四位主要的尖牙领主之一。他们曾是纳拉雷克斯高尚教团的德鲁伊，随纳拉雷克斯进入洞穴，并共同堕落于梦魇的扭曲腐化之中。",al={"尖牙德鲁伊领袖","考布莱恩与安娜科德拉"}}},fx={["7ca4c072"]={q="考布莱恩为什么会在这里？",a="他最初与纳拉雷克斯一同进入哀嚎洞穴，打算汲取地下水脉的力量，让贫瘠之地恢复为郁郁葱葱的乐土。纳拉雷克斯与翡翠梦境的联系扭曲成噩梦后，能量毒害了弟子们的心智。考布莱恩彻底屈服于腐化，留在洞穴中守护沉睡的大德鲁伊，并孕育噩梦中有毒的生物。",al={"考布莱恩为什么在哀嚎洞穴","考布莱恩为何来到这里"}},ffd3d503={q="考布莱恩是谁？",a="考布莱恩是潜伏在哀嚎洞穴深处的尖牙德鲁伊四名堕落首领之一。他曾是纳拉雷克斯高贵教团中的一名暗夜精灵德鲁伊。该教团曾希望治愈贫瘠之地，但他最终屈服于吞噬洞穴的黑暗梦魇。受到腐化扭曲后，他如今操纵剧毒魔法，并化身为巨大的蛇形猛兽。",al={"考布莱恩是谁","考布莱恩的背景","jarlaxla"}},["3feb6d50"]={q="考布莱恩属于哪一方？",a="考布莱恩效力于尖牙德鲁伊和在哀嚎洞穴中蔓延的梦魇。他已与塞纳里奥议会和暗夜精灵彻底决裂，与纳拉雷克斯堕落的弟子并肩而立，对抗任何胆敢进入洞穴净化腐化的人。",al={"考布莱恩的阵营","考布莱恩效力于谁","考布莱恩的效忠对象"}}},fp="12,372,17.380.0,21.427.0,43.169.0,30.258.0,32.184.0,38.209.0,44.186.0,55.227.0"}
P.entries["npc:lord-ello-ebonlocke"] = {n="艾尔罗·埃伯洛克公爵",s="艾尔罗·埃伯洛克公爵是夜色镇的镇长，也是该镇管理委员会的领导人，他在夜色镇市政厅办公。在这片被黑暗与恐怖生物笼罩的土地上，尽管几乎没有得到来自暴风城的援助，他依然每天都在努力维持秩序并保护他那处于围城之中的市民们。",h="艾尔罗·埃伯洛克公爵是夜色镇的镇长，也是该镇管理委员会的领导人，他在夜色镇市政厅办公。在这片被黑暗与恐怖生物笼罩的土地上，尽管几乎没有得到来自暴风城的援助，他依然每天都在努力维持秩序并保护他那处于围城之中的市民们。",kw={"亚伯克隆比","阿尔泰娅","委员会","夜色镇","暮色森林","埃伯洛克","艾尔罗","湖畔镇","镇长"},ang={["faction:Alliance"]="埃伯洛克公爵代表了联盟被遗忘的边陲地带，在这里，孤立无援的镇长必须在没有帝国援助的情况下，带领人民在噩梦般的环境中生存下去。",["race:Human"]="对于从暴风城前往此处的人类来说，与埃伯洛克公爵交谈是一种令人清醒的提醒，让他们意识到南部省份已经沦落到何种破败和被遗弃的境地。"},sec={{t="饱受困扰的镇长",b="艾尔罗·埃伯洛克公爵坐在昏暗的夜色镇市政厅里，肩负着治理这一处濒临毁灭的定居点的沉重负担。夜色镇曾是被称为“大汉姆雷特”的繁荣乡村避难所的一部分，但如今，它被永恒的阴影所笼罩，并遭到贪婪的食尸鬼、骸骨憎恶和凶猛野兽的围攻。艾尔罗主持着夜色镇委员会，在几乎不可能的情况下竭力维持着文明残余的运作，而暴风城却对他们的困境视而不见。"},{t="分裂的边境",b="由于暴风城的卫戍部队拒绝为边境地区抽调士兵，夜色镇几乎完全依赖当地的民兵组织，比如由他的亲属阿尔泰娅·埃伯洛克指挥的守夜人。当湖畔镇的所罗门镇长等邻近地区的领导人请求增援以对抗黑石兽人时，埃伯洛克公爵必须做出痛苦的选择。正如他郑重地向来自赤脊山的信使解释的那样，夜色镇无法抽调哪怕一名守卫：将卫兵派到林边空地之外，意味着他们的家园将瞬间被周围的邪恶势力踏平。"},{t="对隐士阴谋的无知",b="除了巡视道路之外，埃伯洛克公爵经常依靠四处游历的冒险者来处理林地周边的特殊事务。出于协助暮色森林所有居民的真诚愿望，他负责与像隐士亚伯克隆比这样的独居者进行沟通。令人遗憾的是，埃伯洛克对隐士那些晦涩难懂的文字缺乏真正的洞察力，这使得他一直对在镇子边境之外悄然滋生的缝合怪噩梦一无所知，直到为时已晚。"}},faq={{q="艾尔罗·埃伯洛克公爵是谁？",a="艾尔罗·埃伯洛克公爵是夜色镇的镇长，也是夜色镇委员会的负责人。他在市政厅办公，负责监督暮色森林剩余人类居民的防御、民政事务以及生存问题。",al={"谁是艾尔罗","夜色镇镇长","艾尔罗·埃伯洛克背景故事"}},{q="他和指挥官阿尔泰娅·埃伯洛克是什么关系？",a="夜色镇守夜人坚定的领导者指挥官阿尔泰娅·埃伯洛克是艾尔罗公爵的至亲。他负责治理夜色镇的民政和外交事务，而她则指挥着积极保卫该定居点的民兵。",al={"阿尔泰娅·埃伯洛克关系","阿尔泰娅是艾尔罗的女儿吗"}},{q="为什么埃伯洛克公爵拒绝向湖畔镇派兵？",a="当所罗门镇长请求援助以对抗赤脊山的黑石兽人时，埃伯洛克公爵被迫拒绝。夜色镇正面临亡灵和怪物的严峻威胁，抽走镇上的卫兵会导致定居点在民兵赶到森林边界之前就被彻底踏平。",al={"为什么不援助赤脊山","前往夜色镇的信使","所罗门镇长与艾尔罗·埃伯洛克"}},{q="在哪里可以找到艾尔罗·埃伯洛克公爵？",a="他位于夜色镇市政厅内，该建筑坐落于暮色森林东部的夜色镇中心。",al={"艾尔罗·埃伯洛克位置","埃伯洛克镇长在哪里"}},{q="为什么暴风城不派兵援助埃伯洛克公爵？",a="瓦里安·乌瑞恩国王失踪后，暴风城陷入了内部政治斗争。由于王国的资源紧张，贵族议会基本上放弃了南部地区，迫使像埃伯洛克公爵这样的当地领导人不得不组织自己的防御力量。",al={"为什么暴风城不帮助暮色森林","暴风城的忽视"}},{q="埃伯洛克公爵与亚伯克隆比有什么牵连？",a="埃伯洛克公爵协助处理与隐士亚伯克隆比的沟通，帮助翻译那些奇怪的笔记。",al={"艾尔罗与亚伯克隆比的笔记","翻译亚伯克隆比的笔记"}}},fx={["0007fc63"]={q="艾尔罗·埃伯洛克公爵效忠于哪一方？",a="艾尔罗·埃伯洛克公爵忠于大联盟，担任夜色镇镇长并领导镇议会。尽管他宣誓效忠于暴风城王国，但相比更广泛地区的求援，他必须优先确保自己那些惊恐不安的居民能够生存下去。",al={"埃伯洛克所属阵营","艾尔罗·埃伯洛克效力于谁","埃伯洛克是联盟成员吗"}},["48b49947"]={q="艾尔罗·埃伯洛克公爵想要什么？",a="埃伯洛克镇长最想做的，是阻止饱受困扰的夜色镇被步步逼近的黑暗吞噬。王室已将他们抛弃，他唯一关心的是保护自己的人民，并确保当地守夜人始终有人值守，抵御周围的恐怖威胁。",al={"艾尔罗公爵想要什么","埃伯洛克的目标","艾尔罗·埃伯洛克的目的"}},["26db90ba"]={q="艾尔罗·埃伯洛克公爵为什么在夜色镇？",a="埃伯洛克公爵在市政厅主持夜色镇的事务，因为他是夜色镇议会的首领。作为暮色森林最后一处幸存文明据点的领袖，他在镇中心统筹当地防务与政务。",al={"埃伯洛克为什么在暮色森林","埃伯洛克为什么在夜色镇","艾尔罗·埃伯洛克为何在此"}}},fp="19,289,19.500.0,18.576.0,29.465.1,27.208.0,48.218.0,59.294.0,39.106.0,57.276.0,54.125.1"}
P.entries["npc:lord-grayson-shadowbreaker"] = {n="格雷森·沙东布瑞克公爵",s="格雷森·沙东布瑞克公爵是一位驻扎在暴风城Cathedral of Light的白银之手骑士团资深圣骑士指挥官。作为联盟最杰出的圣骑士之一，他负责训练初出茅庐的圣光勇士，并监督资深圣骑士获得神圣战马所需经历的神圣而艰巨的试炼。",h="格雷森·沙东布瑞克公爵是一位驻扎在暴风城Cathedral of...",kw={"cathedral of light","战马","格雷森","grimand elmore","圣骑士","通灵学院","沙东布瑞克","白银之手"},ang={["class:Paladin"]="格雷森是你在联盟中最高级的精神导师之一，他指引你对抗洛丹伦的天灾军团，并主持召唤真正的战马所需严苛的试炼。",["faction:Alliance"]="作为一名坚忍的白银之手老兵，格雷森公爵帮助加强了暴风城的防御，并支持对被争夺的北方王国的远征援助。"},sec={{t="白银之手大师",b="格雷森·沙东布瑞克公爵是联盟最主要的保卫者之一，他在暴风城稳固着白银之手骑士团的势力。作为一名白银之手的老兵，格雷森不仅教导新兵武艺，更会考验他们的精神信念。当有潜力的骑士展现出成熟的技艺时，格雷森会派遣他们前往北方的西瘟疫之地前线，协助寒风营地的阿什拉姆·瓦罗菲斯特指挥官。"},{t="神圣战马的试炼",b="对于寻求神圣战马的圣骑士，沙东布瑞克公爵要求他们做出深刻的牺牲并保持毋庸置疑的美德。他的试炼不仅需要谦卑的慈善行为——例如通过高阶牧师洛汉帮助铁炉堡的贫民——还需要前往恐惧谷驱魔，以及在厄运之槌净化古老灵魂的危险旅程。试炼的终点位于通灵学院的黑暗深处，受试者必须面对死亡骑士Darkreaver，并借圣光之力将一匹邪恶的战马从奴役中救赎出来。"}},faq={{q="我在哪里可以找到格雷森·沙东布瑞克公爵？",a="格雷森·沙东布瑞克公爵居住在暴风城Cathedral Square的Cathedral of Light内。他站在大厅里监督着白银之手骑士团的圣骑士们。",al={"格雷森·沙东布瑞克在哪里","沙东布瑞克的位置","格雷森公爵在哪里"}},{q="格雷森公爵在圣骑士中担任什么职务？",a="他是联盟的一位高级圣骑士训练师。除了指引年轻骑士前往洛丹伦对抗天灾军团的前线战斗外，他还负责主持打造神圣马铠和获得圣骑士战马所需的神圣仪式任务线。",al={"格雷森做什么","格雷森·沙东布瑞克的职责","为什么要拜访格雷森公爵"}},{q="格雷森公爵失去了一只眼睛吗？",a="当今的记载中没有任何关于格雷森是否失去了一只眼睛的说法，更不用说他是如何失去的了。人们只知道他是一位白银之手的老兵，也是联盟最杰出的圣骑士之一。",al={"格雷森是怎么失去眼睛的","为什么格雷森少了一只眼睛","格雷森的眼罩"}},{q="他与被遗忘者有什么联系？",a="目前所知没有任何联系。格雷森是白银之手的一名圣骑士，他派遣手下的骑士前往洛丹伦对抗天灾军团，当今的记载中没有任何记录将他或他的家族与被遗忘者联系在一起。",al={"格雷森的姐妹","格雷森有亡灵亲人吗"}},{q="为什么格雷森要派遣圣骑士去找Grimand Elmore？",a="多年前，Grimand Elmore曾为格雷森自己的战马打造过马铠。由于神圣战马需要兼顾体能与精神和谐、完美无瑕的工艺，格雷森会将所有合格的受试者派遣到Grimand那里去打造他们的奥金马铠。",al={"格雷森与grimand elmore","谁制作圣骑士马铠","奥金马铠任务"}}},fx={["70324968"]={q="格雷森·沙东布瑞克公爵是谁？",a="格雷森·沙东布瑞克公爵是暴风城和联盟最杰出的圣骑士之一。他是白银之手骑士团身经百战的老兵，在这个神圣组织中担任高级导师，训练并引导有前途的骑士学习圣光之道。",al={"格雷森·沙东布瑞克是谁","格雷森公爵是谁","格雷森·沙东布瑞克简介"}},["2db8c97e"]={q="格雷森·沙东布瑞克公爵效忠于哪一方？",a="格雷森坚定地支持大联盟、暴风城王国和白银之手骑士团。他全心奉献于圣光，并致力于保护生者免受天灾军团和其他黑暗势力的威胁。",al={"格雷森·沙东布瑞克所属阵营","格雷森效力于谁","格雷森是联盟成员吗"}},["88e74201"]={q="格雷森·沙东布瑞克公爵想要什么？",a="格雷森希望培养新一代圣洁的战士，驱散吞噬艾泽拉斯的黑暗。他通过艰苦的精神与武技试炼考验圣骑士，派他们前往东西瘟疫之地对抗天灾军团，并证明他们有资格获得一匹受祝福的战马。",al={"格雷森·沙东布瑞克的目标","格雷森想要什么","格雷森的动机"}},a5a2c568={q="格雷森·沙东布瑞克公爵为什么在圣光大教堂？",a="他驻守在暴风城的圣光大教堂，负责监督城中圣骑士的成长。在这座信仰的中心堡垒，他统筹对抗天灾军团的任务，并指导高级勇士完成召唤神圣战马所需的艰苦试炼。",al={"格雷森为什么在暴风城","格雷森为什么在这里","格雷森与圣光大教堂"}},c41cec02={q="格雷森·沙东布瑞克公爵与哪些人有关联？",a="格雷森与铁炉堡的高阶牧师洛汉、铁匠格里曼德·艾尔莫尔，以及在北方与天灾军团作战的指挥官（如阿什拉姆·瓦罗菲斯特）密切合作。",al={"格雷森·沙东布瑞克的盟友","格雷森认识谁","格雷森的侍从"}}},fp="26,321,25.451.0,30.494.1,44.193.0,41.263.0,29.175.0,39.187.0,49.261.0"}
P.entries["npc:lord-jorach-ravenholdt"] = {n="乔拉齐·拉文霍德公爵",s="乔拉齐·拉文霍德公爵是拉文霍德的主人，这是一个潜行者和刺客组成的精英公会，在奥特兰克山脉的一处隐蔽庄园中运作。他指挥着该联盟的秘密行动，在训练有前途的特工的同时，与辛迪加的区域土匪进行着激烈的战争。",h="乔拉齐·拉文霍德公爵是拉文霍德的主人，这是一个潜行者和刺客组成的精英公会，在奥特兰克山脉的一处隐蔽庄园中运作。他指挥着该联盟的秘密行动，在训练有前途的特工的同时，与辛迪加的区域土匪进行着激烈的战争。",kw={"奥特兰克","刺客联盟","碧蓝钥匙","乔拉齐","拉文霍德","潜行者","辛迪加","克希雷姆"},ang={["class:Rogue"]="拉文霍德公爵是艾泽拉斯潜行者大师们的卓越赞助人，为那些赢得他信任的人提供精英训练、毒药和享有盛誉的合同。"},sec={{t="刺客联盟的主人",b="乔拉齐·拉文霍德公爵在奥特兰克和希尔斯布莱德之间的悬崖峭壁中隐藏的庄园里，主持着刺客联盟。作为一名血统神秘的贵族，他向亡命之徒、扒手和刺客敞开大门，无论其阵营如何，只要他们展现出非凡的技能并尊重他的权威。在他的指挥下，该联盟既是盗贼大师的兄弟会，也是从事暗杀和间谍活动的独立组织。拉文霍德对辛迪加——这群堕落为亡命之徒的奥特兰克落魄贵族——怀有强烈的仇恨，并经常指挥其下属和来访的自由职业者破坏他们的营地并掠夺他们的资产。"},{t="阴影中的秘密",b="虽然表面上忙于当地的冲突，但拉文霍德公爵指挥着艾泽拉斯各地的深远行动。证明了自己忠诚的潜行者会被招募去执行复杂的跨大陆任务，以取回受保护的神器。其中包括找回一个神秘的密封的蓝袋子，它被从他那里偷走并被运送到了艾萨拉的熊怪手中，这需要大法师克希雷姆的奥术解码，以及从沉没的神庙中夺取的碧蓝钥匙。拉文霍德还协调开发致命的新化合物，派遣他的侦察兵从整个王国的远古恐怖生物身上收集致命的毒液。"}},faq={{q="乔拉齐·拉文霍德公爵是谁？",a="他是刺客联盟的贵族领袖，这是一个以希尔斯布莱德丘陵上方山脉中的拉文霍德庄园为总部的潜行者秘密社团。他训练潜行大师，并协调隐秘的暗杀和情报收集工作。",al={"乔拉齐是谁","拉文霍德领袖","乔拉齐背景故事"}},{q="为什么拉文霍德憎恨辛迪加？",a="拉文霍德的庄园直接坐落于辛迪加所争夺的领土内，辛迪加是一个由前奥特兰克贵族转变而成的残忍亡命之徒网络。他视他们粗暴的土匪行为为高地上的毒瘤，并利用他公会的刺客积极肃清他们的据点。",al={"为什么辛迪加是敌人","拉文霍德与辛迪加","辛迪加恩怨"}},{q="拉文霍德公爵隶属于联盟还是部落？",a="拉文霍德严格作为一个独立组织运作。乔拉齐公爵接受联盟和部落的潜行者进入他的庄园，只在乎专业能力、潜行纪律和绝对的谨慎，而不是种族政治。",al={"拉文霍德是联盟吗","乔拉齐是部落吗","拉文霍德阵营"}},{q="乔拉齐寻找的密封的蓝袋子里装的是什么？",a="袋子里的内容仍然是一个严守的秘密。当碧蓝钥匙被呈上并最终解锁这个附魔小包时，乔拉齐公爵沐浴在一种怪异的金光中，他惊愕地盯着里面，然后迅速将其收了起来。",al={"密封的蓝袋子内容","蓝袋子之谜","乔拉齐得到了什么"}}},fp="22,302,31.670.0,22.600.1,30.264.0,39.273.0,57.249.0,49.237.1"}
P.entries["npc:lord-maxwell-tyrosus"] = {n="玛克斯韦尔·泰罗索斯男爵",s="玛克斯韦尔·泰罗索斯男爵是银色黎明的最高指挥官，驻扎在东瘟疫之地的银色黎明前哨站——圣光之愿礼拜堂。作为第三次战争中白银之手的资深圣骑士，他领导着联盟对抗天灾军团的远征，并策划了对斯坦索姆等被瘟疫侵蚀的据点的打击。",h="玛克斯韦尔·泰罗索斯男爵是银色黎明的最高指挥官，驻扎在东瘟疫之地的银色黎明前哨站——圣光之愿礼拜堂。作为第三次战争中白银之手的资深圣骑士，他领导着联盟对抗天灾军团的远征，并策划了对斯坦索姆等被瘟疫侵蚀的据点的打击。",kw={"银色黎明","圣光之愿礼拜堂","圣骑士","天灾军团","白银之手","斯坦索姆","泰罗索斯"},ang={["class:Paladin"]="泰罗索斯代表了白银之手不屈的精神，在乌瑟尔去世以及该组织的分裂派系发生悲剧性的堕落后，他依然坚守着同情、团结和纪律的美德。",["faction:Alliance"]="尽管泰罗索斯生为洛丹伦的贵族，也是联盟的英雄，但他现在将自己的力量投入到了一个独立的组织中，欢迎任何愿意与天灾军团作战的人。",["faction:Horde"]="与壁炉谷和血色修道院的狂热分子不同，泰罗索斯长期以来一直支持与非人类种族合作，确保部落的战士和萨满祭司在圣光之愿礼拜堂内能被平等对待。"},sec={{t="洛丹伦的宿将",b="在灾难性的第三次战争中，玛克斯韦尔·泰罗索斯曾与光明使者乌瑟尔并肩作战，当天灾军团席卷王国时，他负责守卫安多哈尔的出口。洛丹伦陷落后，他加入了银色黎明。这是一个欢迎任何愿意对抗天灾军团的人士加入的组织，这与血色十字军只接纳人类的狂热作风形成了鲜明对比。"},{t="黎明指挥官",b="泰罗索斯现在领导着银色黎明，并负责监督圣光之愿礼拜堂的防御工作。他从礼拜堂内的指挥所出发，统筹整个瘟疫之地的广泛军事行动，包括由尼古拉斯·兹韦伦霍夫公爵领导的针对斯坦索姆废墟内瑞文戴尔男爵的战术突袭。"}},faq={{q="谁是玛克斯韦尔·泰罗索斯男爵？",a="玛克斯韦尔·泰罗索斯男爵是一位资深的人类圣骑士，也是银色黎明的最高领导人。他在第三次战争中曾追随光明使者乌瑟尔作战，如今他指挥着圣光之愿礼拜堂的防御，并领导着该组织净化瘟疫之地的战役。",al={"玛克斯韦尔·泰罗索斯是谁","泰罗索斯背景故事","银色黎明领袖","银色黎明首领"}},{q="为什么泰罗索斯离开了血色十字军？",a="没有记录显示泰罗索斯曾加入过血色十字军。他领导的是银色黎明，这个组织接纳任何愿意对抗天灾军团的种族，而十字军的狂热分子则不信任任何非人类且信仰不纯粹的人。",al={"泰罗索斯为何离开血色十字军","泰罗索斯与血色十字军","泰罗索斯是血色十字军吗"}},{q="在哪里可以找到玛克斯韦尔·泰罗索斯？",a="他位于圣光之愿礼拜堂的圣所内，这是银色黎明位于东瘟疫之地最东端的坚固据点。",al={"泰罗索斯位置","玛克斯韦尔·泰罗索斯在哪里","泰罗索斯地图位置"}},{q="泰罗索斯在对斯坦索姆的战争中扮演什么角色？",a="泰罗索斯与尼古拉斯·兹韦伦霍夫公爵共同协调广泛的军事战略，指派身经百战的冒险者和突击队攻入陷落的城市斯坦索姆，并消灭巫妖王在该地区的指挥官——瑞文戴尔男爵。",al={"泰罗索斯与斯坦索姆","泰罗索斯与瑞文戴尔男爵"}},{q="泰罗索斯会接见任何人吗？",a="泰罗索斯很少接见外来者，他多年来一直深居于作战会议中，指挥着前线的战斗。冒险者通常需要获得银色黎明的深度信任，或者提供关键情报才能引起他的注意。",al={"我能与泰罗索斯交谈吗","泰罗索斯的接见"}}},fp="20,330,22.366.0,21.302.0,28.271.0,42.215.0,35.161.0,53.230.0,43.245.0"}
P.entries["npc:lord-pythas"] = {n="皮萨斯",s="皮萨斯曾经是一名暗夜精灵战士，是哀嚎洞穴中四位堕落的尖牙德鲁伊领袖之一。他原本是德鲁伊纳拉雷克斯的私人护卫之一，后来沦为了地下绿洲中滋生梦魇的受害者。如今，他挥舞着武力与扭曲的毒蛇魔法，对抗任何试图接近他沉睡主人的人。",h="皮萨斯曾经是一名暗夜精灵战士，是哀嚎洞穴中四位堕落的尖牙德鲁伊领袖之一。他原本是德鲁伊纳拉雷克斯的私人护卫之一，后来沦为了地下绿洲中滋生梦魇的受害者。如今，他挥舞着武力与扭曲的毒蛇魔法，对抗任何试图接近他沉睡主人的人。",kw={"尖牙德鲁伊","皮萨斯宝石","尖牙领袖","皮萨斯","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="皮萨斯代表了一位前途无量的追随者的悲惨命运，他出于虔诚而拥抱自然魔法，却最终让翡翠梦境的腐化将他的教义扭曲成了毒蛇般的异端。",["class:Warrior"]="在被腐化成毒蛇教徒之前，皮萨斯是一名纪律严明的暗夜精灵战士和私人护卫——这冷酷地提醒着人们，仅靠武力无法抵御精神上的疯狂。",["race:NightElf"]="看着像皮萨斯这样受人尊敬的守护者陷入黑暗的疯狂，对于任何试图恢复卡利姆多那片伤痕累累的土地平衡的暗夜精灵来说，都是一种苦涩的悲哀。"},sec={{t="卫士的陨落",b="在堕落之前，皮萨斯是一名经验丰富的暗夜精灵战士。当远征队冒险进入干旱的贫瘠之地时，他曾在德鲁伊纳拉雷克斯的私人护卫队中服役。除了军事训练外，他还钻研德鲁伊之道，以服务于纳拉雷克斯恢复这片干旱土地生机的梦想。然而，身体的纪律和尚武的勇气在潜伏于地下裂隙深处的险恶腐化面前，无法提供任何庇护。"},{t="致命哨兵",b="当纳拉雷克斯与翡翠梦境的连接被黑暗梦魇劫持时，皮萨斯的精神和其他追随者一样屈服了。他放弃了曾经的忠诚，成为了尖牙德鲁伊的领袖之一。不同于其他偏好狡诈施法或野兽形态的毒蛇领主，皮萨斯将致命的战斗技巧与自然魔法完美融合。他现在徘徊在洞穴蜿蜒的隧道中，决心捍卫梦魇对洞穴之泉的扭曲控制。"}},faq={{q="皮萨斯是谁？",a="皮萨斯原本是一名暗夜精灵战士，曾担任纳拉雷克斯的私人护卫，并学习了德鲁伊教义以协助他的主人在贫瘠之地的工作。",al={"皮萨斯身份","皮萨斯背景故事"}},{q="他为何背叛纳拉雷克斯？",a="皮萨斯并非自愿背叛纳拉雷克斯。当纳拉雷克斯试图利用翡翠梦境来治愈贫瘠之地时，梦魇攫取了大德鲁伊的思想。这种腐化的梦境渗入了追随者的思想中，剥夺了皮萨斯的理智，并将他改造成了一位毒蛇领主。",al={"皮萨斯为何邪恶","皮萨斯如何疯狂","他为何成为尖牙德鲁伊"}},{q="皮萨斯与其他尖牙领袖有何不同？",a="与其他纯粹依赖自然魔法和野兽形态的领袖不同，皮萨斯在成为德鲁伊之前就是一名经验丰富的战士。他将武术战斗技能与德鲁伊魔法相结合，使他成为了洞穴中最强悍的防御者之一。",al={"皮萨斯战斗风格","皮萨斯与其他领袖对比"}},{q="冒险者为什么要击败他？",a="皮萨斯携带着完成任务“尖牙领袖”所需的四颗附魔宝石之一。该任务由雷霆崖的德鲁伊Nara Wildmane发布，她需要所有四位尖牙领袖的宝石，以将贫瘠之地从扭曲的梦境中解放出来。",al={"尖牙领袖任务","皮萨斯宝石"}},{q="在哪里可以找到皮萨斯？",a="皮萨斯潜伏在哀嚎洞穴的深处，周围环绕着堕落的野兽和尖牙教派的同伙。",al={"皮萨斯位置","皮萨斯在哪里"}},{q="他的宝石会怎样？",a="在他被击败后，可以从他的遗骸中找回皮萨斯宝石。冒险者将其与另外三位毒蛇领主的宝石一起带给雷霆崖的Nara Wildmane，以证明尖牙德鲁伊的领导层已被瓦解。",al={"皮萨斯宝石用途","什么是皮萨斯宝石"}}},fx={be91010a={q="皮萨斯效忠于哪一方？",a="皮萨斯效力于尖牙德鲁伊。过去，他曾是纳拉雷克斯忠诚的守护者和追随者；后来噩梦控制了他的心智，扭曲了他的忠诚。如今，他完全站在这个叛变教派一边，挥舞刀刃并施展自然魔法守护噩梦，而非保护他曾发誓守护的主人。",al={"皮萨斯所属阵营","皮萨斯是联盟成员吗","皮萨斯效力于谁"}},a058df7c={q="皮萨斯想要什么？",a="纳拉雷克斯沉睡时遭噩梦侵染，皮萨斯因此陷入疯狂，决意守护哀嚎洞穴，不让任何人前来净化它。失去理智的他只想消灭威胁噩梦控制力的入侵者，将自己的武技和德鲁伊之力尽数用于守护这片被腐化的领地。",al={"皮萨斯的目标","皮萨斯想做什么","皮萨斯的动机"}},d8d94386={q="皮萨斯为什么在哀嚎洞穴？",a="皮萨斯最初进入洞穴，是纳拉雷克斯为恢复贫瘠之地而行动时的贴身护卫之一。纳拉雷克斯的冥想陷入无法摆脱的噩梦后，皮萨斯与其他弟子一同屈服于腐化，留在洞穴深处，成为尖牙德鲁伊的一名堕落守卫。",al={"皮萨斯为什么在哀嚎洞穴","皮萨斯身处此地的原因","皮萨斯如何来到这里"}},d87430fd={q="皮萨斯与哪些人有关联？",a="陷入疯狂之前，皮萨斯曾是德鲁伊纳拉雷克斯的贴身护卫之一。他前往地下泉水处保护纳拉雷克斯，同时学习德鲁伊之道；然而，无处不在的腐化摧毁了他的心智，使他与其他扭曲的尖牙首领沆瀣一气。",al={"皮萨斯与纳拉雷克斯","皮萨斯的人际关系","皮萨斯认识谁"}},eb0bbb13={q="皮萨斯为何令人畏惧？",a="皮萨斯被视为尖牙首领中最强悍的一位。许多追随者只依赖自然法术，而皮萨斯在学习德鲁伊之道前就是一名经验丰富的战士。他兼具致命的近战本领、强悍的体魄和黑暗的德鲁伊魔法，对任何探险队而言都极其危险。",al={"皮萨斯危险吗","皮萨斯为何难以对付","皮萨斯的实力"}}},fp="11,360,16.457.0,19.492.0,19.163.0,32.288.0,56.259.0,38.253.0,31.132.0,24.228.0"}
P.entries["npc:lord-serpentis"] = {n="瑟芬迪斯",s="瑟芬迪斯是一位堕落的暗夜精灵德鲁伊，也是哀嚎洞穴中那些离经叛道的尖牙德鲁伊的四位首领之一。他曾是纳拉雷克斯教团中一位极具力量和威望的德鲁伊，但当纳拉雷克斯的梦境在地底深泉中化为噩梦时，他也随之陷入了疯狂。现在，他在洞穴深处协助指挥那个崇拜毒蛇的教派，而堕落的纳拉雷克斯正沉睡在那里。",h="瑟芬迪斯是一位堕落的暗夜精灵德鲁伊，也是哀嚎洞穴中那些离经叛道的尖牙德鲁伊的四位首领之一。他曾是纳拉雷克斯教团中一位极具力量和威望的德鲁伊，但当纳拉雷克斯的梦境在地底深泉中化为噩梦时，他也随之陷入了疯狂。现在，他在洞穴深...",kw={"尖牙德鲁伊","瑟芬迪斯宝石","尖牙德鲁伊的首领","瑟芬迪斯","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="瑟芬迪斯代表了潜藏在翡翠梦境中的悲剧性危险，展示了当高尚的愿景变成噩梦时，即使是极其强大的德鲁伊也可能走向扭曲。",["race:NightElf"]="对暗夜精灵而言，瑟芬迪斯和他的追随者是一场痛苦的耻辱——这些曾享有盛誉的卡多雷学者抛弃了对自然的的神圣职责，沦为了可怕的毒蛇领主。",["race:Tauren"]="牛头人将瑟芬迪斯的堕落视为对大地母亲平衡的亵渎，认为这以非自然的疯狂威胁着贫瘠之地脆弱的生态系统。"},sec={{t="从高贵的德鲁伊到毒蛇之王",b="在黑暗笼罩洞穴之泉前，瑟芬迪斯是一位极具力量和威望的德鲁伊，隶属于纳拉雷克斯领导的高贵教团，他们曾希望利用洞穴之泉和翡翠梦境来治愈贫瘠之地。然而，当纳拉雷克斯的愿景变成了一场腐蚀性的噩梦时，瑟芬迪斯与其他德鲁伊一样，心智也随之陷入了疯狂。"},{t="尖牙之王",b="瑟芬迪斯和他的同僚们完全屈服于从纳拉雷克斯扭曲的梦境中散发出的腐蚀力量，成为了尖牙德鲁伊。他们背弃了传统的塞纳里奥平衡和古老的图腾动物，现在试图重塑贫瘠之地以符合他们扭曲的梦境，而非治愈它。瑟芬迪斯与安娜科德拉、考布莱恩和皮萨斯一起，作为四位首领之一统治着这个教派。"},{t="最后的阻碍",b="瑟芬迪斯盘踞在蜿蜒洞穴的深处，他是该离经叛道教派的四位首领之一，每一位首领都携带一颗梦境宝石。那些试图唤醒被困大师或收复绿洲之水的人，必须击倒瑟芬迪斯并夺取他携带的宝石，以此打破毒蛇对这座迷宫的控制。"}},faq={{q="谁是瑟芬迪斯？",a="瑟芬迪斯是哀嚎洞穴深处的尖牙德鲁伊的四位首领之一。他曾是纳拉雷克斯教团中一位极具力量和威望的暗夜精灵德鲁伊，后来和他的同僚们一起被纳拉雷克斯的噩梦所腐蚀。",al={"谁是瑟芬迪斯","瑟芬迪斯背景故事","瑟芬迪斯背景"}},{q="瑟芬迪斯为什么会堕落？",a="当纳拉雷克斯试图通过翡翠梦境治愈贫瘠之地的尝试变成一场噩梦时，腐蚀力量蔓延到了跟随他的德鲁伊身上，导致瑟芬迪斯的心智陷入疯狂并开始崇拜毒蛇。",al={"瑟芬迪斯为何堕落","瑟芬迪斯的腐蚀","瑟芬迪斯为何变邪恶"}},{q="他与纳拉雷克斯是什么关系？",a="瑟芬迪斯曾是跟随纳拉雷克斯进入洞穴的高贵德鲁伊之一。他没有协助大师恢复，反而成为了尖牙德鲁伊的首领，他们现在试图重塑贫瘠之地以符合自己扭曲的梦境。",al={"瑟芬迪斯与纳拉雷克斯","瑟芬迪斯与纳拉雷克斯的关系","纳拉雷克斯的学徒"}},{q="玩家为什么要杀掉他？",a="瑟芬迪斯是尖牙德鲁伊的四位首领之一。消灭他是打破该教派对哀嚎洞穴控制的关键，这能确保玩家获得任务“尖牙德鲁伊的首领”所需的宝石，并为唤醒纳拉雷克斯扫清道路。",al={"为什么要杀瑟芬迪斯","尖牙德鲁伊的首领瑟芬迪斯","瑟芬迪斯宝石"}},{q="什么是尖牙德鲁伊？",a="他们是跟随纳拉雷克斯进入哀嚎洞穴的一群离经叛道的暗夜精灵德鲁伊。在翡翠梦魇的腐蚀下，他们在瑟芬迪斯和其他尖牙领主的指挥下放弃了传统的德鲁伊形态，转而采用毒蛇的外貌、毒液和行为。",al={"尖牙德鲁伊背景故事","什么是尖牙德鲁伊","尖牙德鲁伊"}}},fx={["1f07cf4d"]={q="瑟芬迪斯效忠于哪一方？",a="瑟芬迪斯是尖牙德鲁伊的首领。他受到导师纳拉雷克斯体内噩梦的腐化，背弃了塞纳里奥议会和暗夜精灵的理想，对所有进入洞穴的人都充满敌意。",al={"瑟芬迪斯所属阵营","瑟芬迪斯效力于谁","瑟芬迪斯的忠诚对象"}},e8a94e96={q="瑟芬迪斯想要什么？",a="他曾是纳拉雷克斯弟子中声望卓著、力量强大的德鲁伊，后来心智被噩梦扭曲，陷入疯狂。如今神志错乱的他，妄图与扭曲的追随者一同统治洞穴，自称蛇王。",al={"瑟芬迪斯的目标","瑟芬迪斯想要什么","瑟芬迪斯的动机"}},["33635f36"]={q="瑟芬迪斯为什么在哀嚎洞穴？",a="瑟芬迪斯最初来到哀嚎洞穴时，是纳拉雷克斯的一名德鲁伊，帮助导师汲取地下泉水的力量，让贫瘠之地恢复生机。纳拉雷克斯失去对梦境的控制、噩梦腐化爆发后，瑟芬迪斯也成了精神折磨的受害者，留在洞穴中，成为尖牙德鲁伊的统治者。",al={"瑟芬迪斯为什么在这里","瑟芬迪斯为什么在哀嚎洞穴","瑟芬迪斯身处此地的原因"}}},fp="14,426,32.350.0,18.412.0,18.316.1,22.250.0,28.208.0,36.242.0,32.234.0,31.285.0"}
P.entries["npc:lord-shalzaru"] = {n="沙尔扎鲁",s="领主沙尔扎鲁是盘踞在菲拉斯海岸外恐怖之岛上的恨沼纳迦的暴君。他以绝对的残忍统治着他的蛇形追随者，并监督着在那些被淹没的精灵废墟中的大规模挖掘工作。他最近发现了一件奇怪的古老遗物，引起了外界调查者的注意，他们渴望从他手中夺走这件宝物。",h="领主沙尔扎鲁是盘踞在菲拉斯海岸外恐怖之岛上的恨沼纳迦的暴君。他以绝对的残忍统治着他的蛇形追随者，并监督着在那些被淹没的精灵废墟中的大规模挖掘工作。他最近发现了一件奇怪的古老遗物，引起了外界调查者的注意，他们渴望从他手中夺...",kw={"菲拉斯","恨沼","恐怖之岛","沙尔扎鲁","神秘遗物","纳迦"},ang={["faction:Alliance"]="夺取沙尔扎鲁的遗物并消灭这位恨沼纳迦军阀，有助于保护菲拉斯荒野海岸上遥远的联盟哨站。",["faction:Horde"]="部落的侦察兵密切关注着菲拉斯的沿海威胁，击杀这位纳迦领主消除了莫沙彻营地利益范围内的一个不可预知的危险。",["race:NightElf"]="恨沼纳迦亵渎了古代卡利姆多的远古废墟；从沙尔扎鲁手中回收遗物，可以防止上层精灵的黑暗遗产增强他蛇形同类的力量。"},sec={{t="恨沼之主",b="领主沙尔扎鲁指挥着恨沼纳迦，指引他们在菲拉斯南海岸的行动。在恐怖之岛的一个洞穴深处，他建立了自己的地下巢穴，并通过残酷和无情的权威来强制实行他的统治。在他的指挥下，恨沼纳迦搜寻着古代卡利姆多的远古废墟，寻找在大分裂中遗留下的被遗忘的宝藏和强大的遗物。"},{t="神秘遗物",b="在恐怖之岛主要废墟南侧的挖掘过程中，沙尔扎鲁亲自发现了一件奇怪的古老遗物。这件神器的用途和力量仍然是个谜，但被这样一位强大的纳迦军阀所掌控，构成了一个明显的威胁。大陆上的行动人员正在寻找勇敢的勇士，深入蛇穴，终结沙尔扎鲁的指挥权，并在恨沼纳迦将其用于更邪恶的目的之前，夺回这件奇怪的遗物。"}},faq={{q="领主沙尔扎鲁是谁？",a="领主沙尔扎鲁是恨沼纳迦残忍的皇室领袖。他统领着位于菲拉斯海岸外的恐怖之岛上的纳迦军队和挖掘工作。",al={"领主沙尔扎鲁背景","沙尔扎鲁","沙尔扎鲁是谁"}},{q="在哪里可以找到领主沙尔扎鲁？",a="他的巢穴位于恐怖之岛上的主要精灵废墟以南的一个洞穴中，该岛位于菲拉斯西南海岸外。",al={"沙尔扎鲁位置","领主沙尔扎鲁在哪里","恐怖之岛洞穴"}},{q="什么是恨沼纳迦？",a="恨沼纳迦是占据菲拉斯海岸线和岛屿的一个充满敌意的纳迦部族，在沙尔扎鲁的指挥下，他们以搜寻古代废墟和恐吓沿海水域而闻名。",al={"恨沼纳迦","恨沼部族"}},{q="领主沙尔扎鲁拥有什么遗物？",a="在最近一次于恐怖之岛进行的挖掘中，沙尔扎鲁发现了一件起源和力量均未知的神秘古老遗物，这促使大陆上的阵营派遣冒险者去夺取它。",al={"沙尔扎鲁的遗物","菲拉斯神秘遗物"}},{q="为什么要击败领主沙尔扎鲁？",a="消灭沙尔扎鲁将瓦解恨沼纳迦在恐怖之岛的领导层，并使冒险者能在纳迦利用这件神秘遗物之前将其回收。",al={"对抗领主沙尔扎鲁","击杀领主沙尔扎鲁"}},{q="恨沼纳迦在菲拉斯挖掘什么？",a="恨沼纳迦挖掘着在大分裂中破碎的暗夜精灵定居点，寻找隐藏在土壤和波浪下的强大魔法遗物和上层精灵的历史残余。",al={"恨沼挖掘","为什么纳迦在菲拉斯"}}},fp="13,392,23.394.0,20.439.0,21.159.0,33.135.0,22.183.0,38.189.0,35.182.0,46.194.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="博学者诺拉·暴雨图腾",s="博学者诺拉·暴雨图腾是一位驻守在莫高雷北部、赤色石南侧的牛头人长者。他负责看管神圣的墓地，并请求冒险者驱逐在此骚扰的刺鬃野猪人。",h="博学者诺拉·暴雨图腾是一位驻守在莫高雷北部、赤色石南侧的牛头人长者。他负责看管神圣的墓地，并请求冒险者驱逐在此骚扰的刺鬃野猪人。",kw={"博学者诺拉·暴雨图腾","莫高雷","暴雨图腾","赤色石","神圣墓地"},ang={["class:Shaman"]="暴雨图腾对赤色石躁动亡魂的监视与萨满职责息息相关，旨在确保先祖之灵能获得应有的安宁与敬重。",["race:Tauren"]="帮助暴雨图腾保卫赤色石是对先祖的尊崇，也是在维护你部族的埋葬传统。"},sec={{t="赤色石的守望者",b="博学者诺拉·暴雨图腾驻守在莫高雷赤色石的神圣峭壁旁，肩负着部族的精神职责。他请求冒险者将刺鬃入侵者从墓地驱逐出去，以此让先祖的安息之地恢复宁静。"},{t="先祖之地的捍卫者",b="除了考验年轻的英雄，博学者诺拉·暴雨图腾还守护着赤色石的神圣墓地。当刺鬃野猪人入侵者打扰了已故牛头人酋长与萨满的安息之所时，暴雨图腾便会招募过往的旅人，以恢复这些地方的尊严，并平息躁动不安的亡魂。"}},faq={{q="我在哪里可以找到博学者诺拉·暴雨图腾？",a="博学者诺拉·暴雨图腾驻守在莫高雷北部，位于赤色石以南，通往先祖峭壁的小路上。",al={"暴雨图腾位置","博学者诺拉·暴雨图腾在哪里","寻找莫高雷的暴雨图腾"}},{q="为什么暴雨图腾需要帮助来守护墓地？",a="他请求冒险者将刺鬃入侵者从赤色石赶走，因为这些野猪人正在亵渎神圣的牛头人墓地。",al={"暴雨图腾神圣墓地","为什么要帮助暴雨图腾","赤色石墓地"}},{q="为什么暴雨图腾需要在赤色石寻求帮助？",a="赤色石是神圣的牛头人墓地，但刺鬃野猪人入侵者正在破坏这里。暴雨图腾指派有能力的冒险者去整治这些被亵渎的先祖之地。",al={"赤色石问题","为什么要做神圣墓地任务"}}},fx={["88640b34"]={q="博学者诺拉·暴雨图腾想要什么？",a="她照料着赤色石的祖先墓地，并请求冒险者赶走那些侵扰墓地的刺背入侵者。",al={"诺拉·暴雨图腾想要什么","诺拉·暴雨图腾的目标","诺拉·暴雨图腾在请求什么"}},["4ada6d87"]={q="博学者诺拉·暴雨图腾是谁？",a="博学者诺拉·暴雨图腾服务于牛头人族群，守护祖先的传统，并确保逝者得到神圣的安葬。",al={"诺拉·暴雨图腾是谁","博学者诺拉·暴雨图腾信息","诺拉·暴雨图腾简介"}},["29f679b7"]={q="博学者诺拉·暴雨图腾效忠于哪一方？",a="博学者诺拉·暴雨图腾完全忠于莫高雷的牛头人部族，以及由大酋长凯恩·血蹄领导的部落。他是受人尊敬的文化长者，会帮助任何尊重其族群神圣仪式与祖先的部落冒险者。",al={"暴雨图腾所属阵营","暴雨图腾是部落成员吗","暴雨图腾的忠诚对象"}},["6a12fd3c"]={q="博学者诺拉·暴雨图腾为什么在这里？",a="暴雨图腾在赤色石以南守望，因为那里是牛头人部族神圣的祖先墓地。他驻守附近，守护这片圣土，引导前来寻求祖先赐福的朝圣者，并对付那些惊扰红色石崖中安息灵魂的威胁。",al={"暴雨图腾为什么在赤色石","暴雨图腾身处此地的原因","博学者诺拉·暴雨图腾为什么在莫高雷"}}},fp="20,207,20.255.0,29.302.0,38.141.0,53.133.0,42.213.0"}
P.entries["npc:lorgus-jett"] = {n="洛古斯·杰特",s="洛古斯·杰特是暮光之锤教派的一名人类成员，在黑暗深渊的被淹没的走廊中活动。他在Moonshrine Ruins徘徊，作为教派服务于上古之神的无情指挥官。部落领袖将他列为首要目标，以扰乱教派在灰谷沿岸日益增长的影响力。",h="洛古斯·杰特是暮光之锤教派的一名人类成员，在黑暗深渊的被淹没的走廊中活动。他在Moonshrine Ruins徘徊，作为教派服务于上古之神的无情指挥官。部落领袖将他列为首要目标，以扰乱教派在灰谷沿岸日益增长的影响力。",kw={"侍奉上古之神","黑暗深渊","洛古斯·杰特","moonshrine ruins","暮光之锤"},ang={["class:Shaman"]="杰特挥舞元素并非出于和谐或敬畏，而是通过暮光之锤教授的腐化、暴力的手段。",["faction:Horde"]="击杀洛古斯·杰特是为了响应一项紧急请求，旨在铲除在灰谷海岸下滋生的暮光之锤领导层。",["race:Human"]="看到一名人类在卡利姆多的西部地区为宇宙恐怖势力效力，令人不寒而栗，这提醒着我们暮光之锤的腐化已经蔓延到了何种地步。"},sec={{t="废墟中的亵渎者",b="虽然在黑暗深渊下工作的许多暮光之锤成员出身于兽人或牛头人血统，但洛古斯·杰特作为人类，在古老的暗夜精灵废墟深处显得格外突出。杰特在Moonshrine Ruins上层到鱼人亵渎者格里哈斯特所在的洞穴隧道之间的区域游荡，负责协调教派的黑暗仪式和暴力野心。"}},faq={{q="洛古斯·杰特是谁？",a="洛古斯·杰特是暮光之锤教派的一名人类特工，驻扎在黑暗深渊内。他负责监督Moonshrine Ruins内的教派活动，并侍奉上古之神。",al={"洛古斯·杰特背景故事","洛古斯是谁","洛古斯·杰特背景"}},{q="洛古斯·杰特在黑暗深渊的什么位置？",a="洛古斯·杰特在Moonshrine Ruins内有变动的巡逻区域。他可能出现在最早的一批暮光教徒附近，也可能出现在格里哈斯特祭坛后方那些被淹没的通道中。",al={"洛古斯·杰特位置","洛古斯·杰特在哪里","寻找洛古斯·杰特"}},{q="为什么部落想要洛古斯·杰特死？",a="部落通过任务“侍奉上古之神”寻求将他铲除。他在灰谷的存在威胁到了区域的稳定，代表了一个致力于释放古老、毁灭世界实体的阴险联盟。",al={"为什么要杀洛古斯","侍奉上古之神任务"}},{q="为什么人类会使用萨满力量？",a="暮光之锤直接与混乱的元素力量和上古之神交流，而非传统的先祖之灵，这使得人类等非传统种族也能掌握元素毁灭之力。",al={"洛古斯·杰特的魔法","人类萨满洛古斯"}},{q="洛古斯·杰特与格里哈斯特有什么联系？",a="两人都居住在黑暗深渊的Moonshrine Ruins中，同样侍奉着沉睡在海底的黑暗力量，杰特经常在格里哈斯特的祭坛之外的走廊巡逻。",al={"洛古斯与格里哈斯特","与格里哈斯特的联系"}}},fx={["647bfdae"]={q="洛古斯·杰特站在哪一边？",a="洛古斯·杰特效忠于暮光之锤——一个致力于古神、意图毁灭世界的教派。尽管他是人类，却已背弃同族，投身于聚集在灰谷遗忘深处的黑暗仪式主持者与元素势力。",al={"洛古斯·杰特的阵营","洛古斯·杰特效忠于谁","洛古斯·杰特属于哪个阵营"}},ba0235c4={q="洛古斯·杰特为什么在黑暗深渊？",a="他与其他教徒一同潜伏在地下的Moonshrine Ruins，执行暮光之锤的意志。在这座古老的暗夜精灵神殿深处，教徒们照料着黑暗恐怖之物，并崇拜在水下涌动的远古力量。",al={"洛古斯·杰特为什么在黑暗深渊","洛古斯·杰特在黑暗深渊的目的","洛古斯·杰特为什么在这里"}}},fp="11,350,22.373.0,19.179.0,52.199.0,41.223.0,40.200.0,45.198.0"}
P.entries["npc:loslor-rudge"] = {n="罗斯洛·鲁治",s="罗斯洛·鲁治是一位进取的矮人工程学供应商，驻扎在丹莫罗的钢架补给站。他为白雪覆盖的山脊上的工匠们提供机械零件、工具和弹药，并与海格纳·重枪这样的枪匠保持着关键的联络。",h="罗斯洛·鲁治是一位进取的矮人工程学供应商，驻扎在丹莫罗的钢架补给站。他为白雪覆盖的山脊上的工匠们提供机械零件、工具和弹药，并与海格纳·重枪这样的枪匠保持着关键的联络。",kw={"弹药","丹莫罗","工程学","灰色洞穴","海格纳·重枪","罗斯洛·鲁治","钢架补给站"},ang={["profession:Engineering"]="罗斯洛储备着关键的早期制造补给品——如助熔剂、爆盐炸药、管子和修补工具包——这使得他在补给站的商铺成为了任何路过丹莫罗的工程学新手方便的补给点。",["race:Dwarf"]="和许多丹莫罗的匠人一样，罗斯洛的生计依赖于分散的矮人营地之间可靠的驮运路线，这也表明了即使是温迪戈这样的当地掠食者也能扰乱山区的贸易。"},sec={{t="雪中的供应商",b="罗斯洛·鲁治在距离卡拉诺斯不远的钢架补给站开展业务，始终储备着充足的工程学必需品——从铜质调节器和青铜管，到爆盐炸药和扳手，应有尽有。丹莫罗严酷的天气和庞大的修补作业意味着人们对实用零件的需求源源不断，罗斯洛以能为当地的机械师提供补给而自豪。然而，前哨站之间的荒野危机四伏；当一名试图抄近路经过灰色洞穴的信使被温迪戈赶走后，一批本应送往他尊贵客户——枪匠海格纳·重枪手中的重要弹药就被遗弃在了雪地里。"}},faq={{q="罗斯洛·鲁治是谁？",a="罗斯洛·鲁治是一位矮人工程学供应商，他在丹莫罗的钢架补给站经营着自己的店铺。他向该地区的冒险者和工匠出售修补工具、零件和弹药。",al={"罗斯洛·鲁治","鲁治是谁","钢架补给站工程师"}},{q="罗斯洛需要什么样的帮助？",a="他最近派了一名信使去给枪匠海格纳·重枪运送一批弹药。信使在经过灰色洞穴时抄了近路，结果遇上了野生的温迪戈，由于惊慌逃窜，把装弹药的板条箱丢在了雪地里。罗斯洛需要有人在失去这位尊贵的客户之前找回这批货物。",al={"重枪的弹药任务","鲁治想要什么","鲁治的信使"}},{q="钢架补给站位于何处？",a="钢架补给站是一个繁忙的矮人集结地和机械车间，位于卡拉诺斯以东，通往洛克莫丹的主干道旁。",al={"钢架补给站在哪里","钢架位置"}},{q="海格纳·重枪是谁？",a="海格纳·重枪是一位驻扎在丹莫罗营地的矮人枪匠，他依靠罗斯洛·鲁治提供新鲜的弹药和机械组件供应。",al={"海格纳是谁","重枪"}}},fx={["774accc1"]={q="罗斯洛·鲁治站在哪一边？",a="罗斯洛·鲁治是铁炉堡矮人社群和联盟的忠实成员。他驻扎在钢架补给站，经营的生意直接支持着丹莫罗各地的矮人射手、工匠和附近聚居点。",al={"罗斯洛·鲁治的阵营","罗斯洛·鲁治是联盟成员吗","罗斯洛·鲁治效忠于谁"}},["1a06e65e"]={q="罗斯洛·鲁治为什么在钢架补给站？",a="罗斯洛在钢架补给站经营工程用品生意，也是一名商人。补给站是铁炉堡外繁忙的矮人机械、维修和工业中心，非常适合他向当地枪匠出售修补匠零件、火药和制造弹药。",al={"罗斯洛·鲁治为什么在这里","罗斯洛·鲁治在钢架补给站的职责","罗斯洛为什么在补给站"}}},fp="12,278,22.653.0,20.204.0,40.304.0,28.141.0,25.162.0"}
P.entries["npc:lotwil-veriatus"] = {n="鲁特维尔·沃拉图斯",s="鲁特维尔·沃拉图斯是一位古怪的侏儒学者，正在Badlands尘土飞扬的荒野中进行危险的元素实验。他与讽刺成性的学徒卢希恩·枪穗以及一个名为Servo的机械侍从驻扎在卡加斯东部，致力于将奥术理论、炼金术和工程学融合成一门统一的学科。",h="鲁特维尔·沃拉图斯是一位古怪的侏儒学者，正在Badlands尘土飞扬的荒野中进行危险的元素实验。他与讽刺成性的学徒卢希恩·枪穗以及一个名为Servo的机械侍从驻扎在卡加斯东部，致力于将奥术理论、炼金术和工程学融合成一门统...",kw={"badlands","元素","fam'retor","卡加斯","鲁特维尔","卢希恩","servo","沃拉图斯"},ang={["profession:Engineering"]="工程师们会认出鲁特维尔将机械陀螺仪和齿轮整合到奥术约束场中的野心，以及工程学中经典的突然、暴力故障的陷阱。",["race:Gnome"]="鲁特维尔是侏儒智力抱负达到鲁莽极端的典型例子，他不顾灾难性的风险，试图在工程学和奥术之间架起桥梁。"},sec={{t="混沌统一场",b="鲁特维尔最初来自丹莫罗的卡拉诺斯，他设想为他的“奥术、炼金与工程科学启蒙大会”建立一所宏伟的大学。他认为这三门学科不应孤立地实践，而应和谐统一。为了实现这个梦想，他选择了恶劣的Badlands作为实验室，以研究当地的岩石元素，并制造能够驾驭元素力量的束缚枷锁。虽然他是一位有成就的研究者——过去曾研究过元素机器并击败过黑铁构造体——但他专注的眼光往往让他忽视了实地考察中的爆炸性危险。"},{t="元素枷锁",b="鲁特维尔在Badlands的宏伟抱负集中在测试他的元素束缚枷锁上。通过指派冒险者收集岩石元素之核、冷却剂和陀螺仪原子，他准备了一个复杂的仪式，旨在征服一个元素仆从。然而，当束缚装置最终被激活时，不稳定的魔法、反复无常的工程学和不稳定的炼金试剂的汇聚导致了灾难性的后果，召唤出一个名为Fam'retor的、高大愤怒的元素怪物，并反过来攻击它的制造者。"}},faq={{q="谁是鲁特维尔·沃拉图斯？",a="鲁特维尔·沃拉图斯是一位侏儒智者，居住在Badlands卡加斯东部的一个孤立营地。他是奥术、炼金与工程科学启蒙大会的创始成员，寻求将这三个领域融合为一个单一的学术学科。",al={"鲁特维尔是谁","鲁特维尔·沃拉图斯背景故事","badlands的侏儒"}},{q="为什么鲁特维尔在Badlands？",a="鲁特维尔来到Badlands是为了研究该地区密集的野生岩石元素。这片开阔的沙漠既提供了原始的元素材料，又有足够的空间进行不稳定的束缚实验，而不会危及主要人口中心。",al={"为什么鲁特维尔在badlands","鲁特维尔的badlands营地","鲁特维尔在做什么"}},{q="谁是卢希恩·枪穗？",a="卢希恩·枪穗是鲁特维尔饱受折磨的侏儒助手。卢希恩对主人的古怪言论感到非常愤世嫉俗且疲惫不堪，他负责管理后勤、维修机械仆从Servo，并经常警告旁观者鲁特维尔那危险的粗心大意。",al={"卢希恩·枪穗","鲁特维尔的助手","鲁特维尔的学徒"}},{q="鲁特维尔完成他的实验后会发生什么？",a="鲁特维尔试图使用他定制的元素束缚枷锁来奴役一个元素构造体。这种混合技术失败得一塌糊涂，召唤出一个巨大的、愤怒的岩石元素Fam'retor，必须在它摧毁他的营地之前将其消灭。",al={"鲁特维尔的实验失败","元素束缚枷锁","fam'retor"}}},fp="15,338,24.619.0,22.526.1,23.268.0,34.248.0,27.269.0,49.259.1"}
P.entries["npc:lucius"] = {n="卢修斯",s="卢修斯是一名出现在赤脊山湖畔镇码头附近的矮人特工。他作为暴风城军情七处（SI:7）的秘密外勤联络员，协助特工们进行专业的侦察和交易技能训练。",h="卢修斯是一名出现在赤脊山湖畔镇码头附近的矮人特工。他作为暴风城军情七处（SI:7）的秘密外勤联络员，协助特工们进行专业的侦察和交易技能训练。",kw={"码头","矮人","湖畔镇","开锁","卢修斯","赤脊山","潜行者","军情七处"},ang={["class:Rogue"]="对于从暴风城被派往外地的潜行者来说，卢修斯是精进开锁和侦察技能的重要联络人和导师。",["race:Dwarf"]="卢修斯提醒人们，矮人的天赋不仅仅局限于熔炉和前线，在暴风城的秘密行动中也有一席之地。"},sec={{t="山中的眼线",b="虽然卢修斯在湖畔镇的码头上表现得漫不经心，但他实际上是直接隶属于暴风城情报机构军情七处的秘密特工。他在码头的岗位上监视着贸易、异常往来以及侵入赤脊山的区域威胁。从暴风城派往东部的特工们会前往此处，与他协调秘密任务并磨炼实际的外勤艺术，例如开锁，以确保王国的隐秘触角能延伸至艾尔文森林之外。"}},faq={{q="卢修斯是谁？",a="卢修斯是一位驻扎在湖畔镇的矮人特工，他为暴风城王国的军情七处（情报部门）效力。",al={"卢修斯身份","码头上的矮人是谁","卢修斯npc"}},{q="卢修斯在湖畔镇做什么？",a="他担任秘密特工的外勤联络员，提供当地的盗贼技能和开锁指导，同时密切关注赤脊山的区域动向。",al={"卢修斯在这里做什么","卢修斯的目的","为什么卢修斯在码头上"}},{q="哪些任务涉及卢修斯？",a="卢修斯是军情七处任务“赤脊山之约”的联络人，并派遣年轻的潜行者前往奥瑟尔伐木场开启宝箱，以获取他们的偷窃技能认证书。",al={"卢修斯任务","赤脊山之约任务","奥瑟尔伐木场"}}},fp="6,167,21.357.0,14.92.0,33.134.0,28.162.0"}
P.entries["npc:lyria-du-lac"] = {n="里瑞亚·杜拉克",s="里瑞亚·杜拉克是一位驻扎在艾尔文森林闪金镇的人类战士训练师。她待在村庄铁匠铺后方，专门训练初出茅庐的战士，指导年轻的战士掌握姿态和武器运用。",h="里瑞亚·杜拉克是一位驻扎在艾尔文森林闪金镇的人类战士训练师。她待在村庄铁匠铺后方，专门训练初出茅庐的战士，指导年轻的战士掌握姿态和武器运用。",kw={"战士的训练","铁匠","艾尔文森林","闪金镇","里瑞亚·杜拉克","战士训练师"},ang={["class:Warrior"]="对于刚从北郡修道院出来的新手战士而言，里瑞亚·杜拉克是你在艾尔文森林遇到的第一位主要训练师，她能帮你磨练姿态掌握和近战战术。",["faction:Alliance"]="里瑞亚驻扎在闪金镇的铁匠铺后方，确保当地的新兵有能力保卫暴风城的核心地区，抵御迪菲亚兄弟会的强盗和豺狼人劫掠者。"},sec={{t="闪金镇战士训练师",b="当闪金镇的Lion's Pride Inn里挤满了旅客，而铁匠忙着打造当地贸易商品时，里瑞亚·杜拉克总是待在铁匠铺后的训练场。她精通武术训练，通过指导从北郡修道院出来的新手战士为联盟服务。她评估他们的战备水平，并传授他们专业的战斗技巧，确保那些为暴风城拿起盾牌与利刃的人们能够抵御艾尔文森林不断逼近的威胁。"}},faq={{q="我在哪里可以找到里瑞亚·杜拉克？",a="里瑞亚·杜拉克站在闪金镇铁匠铺的后方，位于艾尔文森林里Lion's Pride Inn的正西方。",al={"里瑞亚·杜拉克位置","里瑞亚在哪里","闪金镇战士训练师"}},{q="里瑞亚·杜拉克提供什么服务？",a="她是一位战士训练师。她向新手战士传授基础的战斗动作、姿态要领以及随着技能提升所需的战斗纪律。",al={"里瑞亚有什么功能","里瑞亚·杜拉克职责","里瑞亚教什么"}},{q="有哪些任务与里瑞亚·杜拉克有关？",a="里瑞亚会给予成长中的战士“战士的训练”这一任务，让他们前往位于暴风城Old Town的Pig and Whistle Tavern，寻找老兵哈里·伯加德。",al={"里瑞亚·杜拉克任务","闪金镇战士任务"}}},fp="12,126,28.275.0,30.102.0,39.107.0,33.159.0"}
P.entries["npc:ma-stonefield"] = {n="斯通菲尔德妈妈",s="斯通菲尔德妈妈是一位住在艾尔文森林西部斯通菲尔德农场的人类女家长。她和波尼斯·斯通菲尔德姑妈一起站在家庭宅基地外，在邻里的敌对竞争和害虫困扰中，处理着农村农场生活的日常艰辛。",h="斯通菲尔德妈妈是一位住在艾尔文森林西部斯通菲尔德农场的人类女家长。她和波尼斯·斯通菲尔德姑妈一起站在家庭宅基地外，在邻里的敌对竞争和害虫困扰中，处理着农村农场生活的日常艰辛。",kw={"波尼斯·斯通菲尔德","艾尔文森林","斯通菲尔德妈妈","公主","公主必须死","斯通菲尔德农场"},ang={["faction:Alliance"]="对于在艾尔文森林探索的联盟冒险者来说，帮助像斯通菲尔德妈妈这样勤劳的农场主有助于维护暴风城的农业根基。"},sec={{t="农场麻烦",b="斯通菲尔德妈妈站在艾尔文森林西南部她家的小屋旁，与“波尼斯·斯通菲尔德姑妈”一起守护着农场。邻近的麦克鲁尔农场和附近的南瓜地之间鲜有宁静的日子。当地的野猪不断威胁着农作物，而其中最大的祸害莫过于“公主”，这头巨大的获奖母猪因为践踏田地和吞食来之不易的收成而臭名昭著。"}},faq={{q="斯通菲尔德妈妈是谁？",a="斯通菲尔德妈妈是斯通菲尔德家族的长辈之一，与波尼斯·斯通菲尔德姑妈等亲戚一起住在艾尔文森林西南部的农场里。",al={"斯通菲尔德妈妈是谁","斯通菲尔德妈妈","斯通菲尔德母亲"}},{q="在哪里可以找到斯通菲尔德妈妈？",a="她就站在艾尔文森林闪金镇西部的斯通菲尔德农场主屋前。",al={"斯通菲尔德妈妈位置","斯通菲尔德妈妈在哪里","斯通菲尔德农场坐标"}},{q="斯通菲尔德妈妈需要解决什么问题？",a="斯通菲尔德妈妈寻找冒险者来除掉“公主”，这是一头巨大的获奖母猪，它经常在周围的田地里横冲直撞，吞食当地的农作物。",al={"斯通菲尔德妈妈任务","公主母猪任务","公主必须死任务发放者"}}},fp="13,167,18.396.0,21.146.0,31.112.0,44.135.0"}
P.entries["npc:mad-magus-tirth"] = {n="大法师提尔斯",s="大法师提尔斯是一位古怪的人类法师，居住在千针石林的沙漠赛道盐碱地上。他因在当地饲养鸡群和折磨他被变形术变成鸡的学徒而闻名，同时他也是一位学识渊博的奥术学者，但他却把宝贵的书籍都浪费在赛车赌注上了。",h="大法师提尔斯是一位古怪的人类法师，居住在千针石林的沙漠赛道盐碱地上。他因在当地饲养鸡群和折磨他被变形术变成鸡的学徒而闻名，同时他也是一位学识渊博的奥术学者，但他却把宝贵的书籍都浪费在赛车赌注上了。",kw={"安科纳鸡","大法师提尔斯","沙漠赛道","勇敢的","勇敢的约翰逊","能量仪祭","闪光平原","千针石林","提尔斯"},ang={["class:Mage"]="对于寻求加深对奥术力量理解的法师来说，提尔斯是一个重要的人物，因为他撰写了重要的论著《能量仪祭》。"},sec={{t="尘土中的法师",b="虽然大多数像他这样水平的法师都在达拉然或暴风城的图书馆里潜心研究，但大法师提尔斯却在闪光平原的机油味和轰鸣声中安了家。被竞速火箭车包围的提尔斯向过路人兜售鸡、喝酒、赌博，并且早就诅咒了他那倒霉的学徒“勇敢的”约翰逊，将其变成了一只家禽。尽管举止古怪，提尔斯确实拥有真正的奥术造诣，他曾撰写过有关魔法力量的深奥文献，但在赛道上因鲁莽的赌注而输掉了这些著作。"},{t="仪式与债务",b="提尔斯的学术遗产包括《能量仪祭》，这是一本修行法师们梦寐以求的奥术手册。不幸的是，对于那些有抱负的施法者来说，提尔斯已经不再拥有这本杰作了。由于在沙漠赛道上欠下了累累赌债，这位法师将这本书卖给了血色十字军的一名特工以抵消他的损失，迫使学徒和求知者必须深入敌对领地去寻找这本书。"}},faq={{q="为什么大法师提尔斯会待在沙漠里？",a="提尔斯住在闪光平原的沙漠赛道旁，被这里的奇观和赌博所吸引。他没有在大城市里过学术生活，而是终日观看侏儒和地精的赛车，卖鸡，并沉溺于自己的嗜好中。",al={"为什么提尔斯在这里","大法师提尔斯闪光平原","提尔斯位置"}},{q="他身边的鸡是谁？",a="在赛道上徘徊的那只鸡是“勇敢的”约翰逊，即大法师提尔斯的学徒。提尔斯对约翰逊施加了一个诅咒，把他变成了一只鸡，他甚至已经记不起为什么要这么做了，但他确信这对那个忘恩负义的小家伙来说是应得的报应。",al={"谁是勇敢的","勇敢的约翰逊","提尔斯鸡学徒"}},{q="《能量仪祭》是一本什么样的书？",a="《能量仪祭》是一本由大法师提尔斯撰写的关于奥术能量的高级论著。对于想要提升技艺的法师来说，这是一本必不可少的书籍，尽管提尔斯为了偿还他日益增加的赛车赌债而放弃了它。",al={"能量仪祭","提尔斯的书","法师任务书"}},{q="为什么他的书很难获得？",a="提尔斯已经没有《能量仪祭》的副本了。寻找这本书的法师必须根据他如何失去这本书的叙述去追寻线索。",al={"谁有能量仪祭","提尔斯的债务","血色十字军书"}}},fx={["8056ee12"]={q="大法师提尔斯是谁？",a="大法师提尔斯是一名古怪的人类施法者，住在闪光平原上的沙漠赛道。显然，他精通秘奥学识，还曾撰写著名的魔法典籍《能量仪祭》；如今，他却把时间花在兜售安科纳鸡、喝酒和赌赛上。",al={"大法师提尔斯是谁","提尔斯是谁","大法师提尔斯的背景"}},f085518f={q="大法师提尔斯站在哪一边？",a="大法师提尔斯始终严守中立。他在闪光平原的盐碱地上与地精和侏儒工程师为伴谋生，乐于向联盟和部落的旅人出售货物并提供魔法建议，却不参与双方更大规模的战争。",al={"大法师提尔斯属于联盟还是部落","提尔斯的阵营","大法师提尔斯是中立的吗"}},["3482f0bf"]={q="大法师提尔斯想要什么？",a="除了向赛场观众出售安科纳鸡、赚些钱糊口，提尔斯最想要的就是一杯新鲜的麦酒，以及下一场比赛的可靠消息。他曾想快速弄到钱来偿还高额赌债，结果把自己的学术研究都卖掉了。",al={"提尔斯想要什么","大法师提尔斯的动机","提尔斯为什么卖鸡"}}},fp="11,290,20.521.0,17.418.1,37.236.0,31.235.0,34.214.0,36.128.0"}
P.entries["npc:madame-eva"] = {n="伊瓦夫人",s="伊瓦夫人是一位受人尊敬的占卜师和族长，居住在暮色森林那片阴暗树林中的夜色镇。她精通古老的神秘占卜术和牌阵，常常是镇上第一个感知到树林中出现异常波动的人。旅人们经常向她寻求帮助，以解开那些阴森的谜团，或是获取能够抵御不断逼近的黑暗的超自然护身符。",h="伊瓦夫人是一位受人尊敬的占卜师和族长，居住在暮色森林那片阴暗树林中的夜色镇。她精通古老的神秘占卜术和牌阵，常常是镇上第一个感知到树林中出现异常波动的人。旅人们经常向她寻求帮助，以解开那些阴森的谜团，或是获取能够抵御不断逼...",kw={"艾莉莎·伊瓦","牌阵","夜色镇","暮色森林","占卜师","幽灵的发丝","伊瓦夫人","斯塔文"},ang={["class:Priest"]="虽然圣光能给生者带来慰藉，但牧师们会发现伊瓦对牌阵和灵魂残余的依赖，是教会传统礼仪的一种奇特且世俗的对应物。",["faction:Alliance"]="对于那些踏入暮色森林压抑阴影中的联盟勇士来说，伊瓦夫人是一位不可或缺的向导，她的预感能穿透树林中致命的混乱。",["profession:Tailoring"]="裁缝们会欣赏伊瓦对奇异编织材料的知识，特别是她能够利用直接从该地区幽灵身上获取的幽灵丝线进行创作的能力。"},sec={{t="夜色镇的占卜师",b="伊瓦夫人安静地居住在夜色镇的阴影之中，她修习的牌阵和古老的民间仪式在暴风城的大教堂看来是十分可疑的。在这个被凶残野兽、亡灵和更可怕的恐怖笼罩的被遗弃之地，她那诡异的洞察力受到了绝望的镇民和来访冒险者的容忍与追捧。"},{t="血脉与预言的羁绊",b="除了作为一名神秘学的解读人，伊瓦夫人对她的家庭倾注了深厚的感情，她是艾莉莎·伊瓦和年幼的洛甘的祖母。当她的牌阵揭示出威胁她孙女的黑暗预兆时，伊瓦毫不犹豫地招募过路的流浪者去搜寻这片树林，在历史重演之前揭开那些被埋藏已久的悲剧。"},{t="编织抵御黑夜的保护",b="伊瓦的知识不仅仅局限于读牌，还包括仪式制作和结界防卫。从利用幽灵的发丝纺织出幽灵的发丝，到制作惩罚图腾这样离奇的民间圣物，她对掌控着暮色森林那些躁动不安的灵魂的奇特、暮光逻辑的理解，几乎超过了镇上的任何人。"}},faq={{q="伊瓦夫人是谁？",a="伊瓦夫人是一位居住在夜色镇的老年人类占卜师和预言家。她通过练习牌阵和古老的民间手艺，来洞察潜伏在暮色森林中那些看不见的危险。",al={"伊瓦夫人","伊瓦是谁","夜色镇占卜师"}},{q="伊瓦夫人在斯塔文的谜团中扮演了什么角色？",a="伊瓦夫人通过牌阵读出了围绕在她孙女艾莉莎身边的迫在眉睫的超自然危险。她的占卜引导冒险者调查被遗忘的文件和线索，最终揭开了斯塔文·密斯曼托那阴森的历史。",al={"伊瓦 斯塔文","斯塔文传说 伊瓦","为什么伊瓦关心斯塔文"}},{q="伊瓦夫人是女巫还是法师？",a="伊瓦主要是一位预言家和古老神秘艺术的实践者，例如牌阵、灵魂丝线编织和民间塑像。她的魔法更接近于传统的占卜和神秘学知识，而不是达拉然的结构化奥术或圣光。",al={"伊瓦是女巫吗","伊瓦魔法类型","伊瓦使用什么魔法"}},{q="在夜色镇，谁与伊瓦夫人有亲属关系？",a="她是艾莉莎·伊瓦和洛甘·伊瓦的祖母。镇上的守夜人中也有一位守夜人伊瓦，据信她与伊瓦夫人有亲属关系。",al={"伊瓦家庭","伊瓦夫人的孙辈","艾莉莎·伊瓦的祖母"}},{q="幽灵的发丝有什么用途？",a="伊瓦夫人利用躁动灵魂的头发纺织出幽灵的发丝。正如她所言，这种丝线有上千种用途，从束缚邪恶的灵魂到将生命缝合进无生命的物体中，她会为那些带给她所需的幽灵头发的人制作这种丝线。",al={"幽灵的发丝","伊瓦丝线任务"}},{q="为什么伊瓦夫人要制作惩罚图腾？",a="伊瓦夫人制作惩罚图腾作为一种黑暗的感应塑像。通过将特定的生物材料绑定在图腾上，它能将诅咒和伤害反向施加给那些恐吓森林的邪恶野兽。",al={"惩罚图腾","伊瓦图腾"}}},fx={b3bc0c21={q="伊瓦夫人站在哪一边？",a="伊瓦夫人坚定地站在夜色镇居民和联盟一边。虽然她涉猎纸牌占卜和晦奥的“古老技艺”，但她仍忠于处境艰难的邻居和家人，并用占卜与仪式守护城镇，抵御潜伏在暮色森林中的黑暗祸患。",al={"伊瓦夫人的忠诚对象","伊瓦夫人效忠于谁","伊瓦夫人是联盟成员吗"}},d6f73346={q="伊瓦夫人想要什么？",a="伊瓦夫人想保护自己的社群和亲族，免受萦绕暮色森林的黑暗势力侵害。她运用纸牌占卜预见隐患，例如斯塔文·密斯特曼托尔之谜背后潜伏的厄运，并指引旅人收集仪式材料，以驱邪护佑家人。",al={"伊瓦夫人想做什么","伊瓦夫人的目标","伊瓦夫人为什么需要帮助"}},["6bf59259"]={q="伊瓦夫人为什么在夜色镇？",a="夜色镇是伊瓦夫人的祖居。她住在自己的小屋里，作为孙辈艾莉莎·伊娃和洛根·伊娃的家长，为那些在阴森森林中艰难求生、心怀恐惧的人们提供指引、占卜和神秘援助。",al={"伊瓦夫人为什么住在暮色森林","伊瓦夫人为什么在夜色镇","伊瓦夫人的家"}}},fp="10,372,31.351.0,26.353.0,36.317.0,18.177.0,52.237.0,32.252.0,42.149.0,35.250.0,50.201.0"}
P.entries["npc:magatha-grimtotem"] = {n="玛加萨·野性图腾",s="玛加萨·野性图腾是野性图腾部族的女族长，也是雷霆崖的长者导师。她是一位令人生畏的萨满祭司，同时也是一名政治阴谋家。她居住在长者高地，不断挑战凯恩·血蹄对牛头人部族的愿景。",h="玛加萨·野性图腾是野性图腾部族的女族长，也是雷霆崖的长者导师。她是一位令人生畏的萨满祭司，同时也是一名政治阴谋家。她居住在长者高地，不断挑战凯恩·血蹄对牛头人部族的愿景。",kw={"阿瑞卡拉","血蹄","凯恩","长者导师","长者高地","野性图腾","玛加萨","怒焰","雷霆崖","扎玛"},ang={["class:Shaman"]="玛加萨无疑是卡利姆多最强大的萨满祭司之一，她以极少数在世牛头人能企及的威严统御着原始元素。",["faction:Horde"]="虽然玛加萨在对抗区域性威胁时提供了宝贵的援助和建议，但她对自己部族坚定的忠诚以及对其他种族的公开蔑视，使她成为了一个不可信赖的盟友。",["race:Tauren"]="每个牛头人都知道野性图腾部族那黑暗的名声，这使得玛加萨在长者高地的存在，成为了一个令人不安的提醒，昭示着威胁着他们联合部族的意识形态分歧。",["race:Undead"]="被遗忘者的旅行者会发现，这位长者导师给予了他们出奇热情的接待，她经常在预见之池与皇家药剂师学会进行商议。"},sec={{t="长者高地的女族长",b="玛加萨通过一场包办婚姻，以及随后她配偶那场突如其来的致命攀登事故，确立了对野性图腾部族的绝对统治。她在长者高地通过她的私人随从和保镖进行运作，作为她这个隐世部族无可争议的政治和精神领袖。与凯恩·血蹄不同，玛加萨宣扬牛头人的统治地位，视其他凡人种族为卡利姆多的入侵者，认为他们应当被铲除或驱逐。"},{t="奇怪的联盟",b="尽管她公开蔑视非牛头人种族，玛加萨却是最早主张接纳被遗忘者加入部落的人之一。她声称牛头人可以教导亡灵保持精神平衡，并引导他们找回人性。然而在实践中，玛加萨直接与雷霆崖下的皇家药剂师学会合作，向药剂师扎玛等人物咨询实用炼金术和奥术遗物研究。"},{t="政治权谋",b="在睿智顾问的伪装下，玛加萨积极削弱凯恩的权威，同时测试潜在威胁的防御。她派遣冒险者深入险境——从探测怒焰裂谷的石鄂怪军队，到猎杀复仇之灵阿瑞卡拉。她指派的每一项任务，要么是为了巩固野性图腾的筹码，要么是为了迎接她能彻底取代血蹄王朝的那一天做准备。"}},faq={{q="玛加萨·野性图腾是谁？",a="玛加萨是野性图腾部族的长者导师和女族长。她自幼就是一位天赋异禀的萨满祭司，在配偶死于攀登事故后，她全面接管了自己的氏族。她居住在雷霆崖的长者高地，是凯恩·血蹄的主要政治对手。",al={"玛加萨背景故事","谁是长者导师","雷霆崖长者导师"}},{q="玛加萨为什么要支持被遗忘者？",a="表面上，玛加萨认为牛头人的传统和萨满教义的理解可以引导被遗忘者回归人性。然而，许多人怀疑她与皇家药剂师学会的友谊，实际上是出于对秘传炼金术秘密的渴望，以及在凯恩忠诚的核心圈之外寻找政治盟友的意图。",al={"玛加萨与亡灵","为什么玛加萨支持被遗忘者","玛加萨与药剂师扎玛"}},{q="玛加萨与凯恩·血蹄的关系如何？",a="玛加萨认为凯恩软弱、天真，不适合领导团结的牛头人。虽然凯恩主张在部落内共存，并在整个卡利姆多实现和平，但玛加萨认为野性图腾部族应该通过武力夺回祖先的土地，并铲除外来的入侵者。",al={"玛加萨与凯恩","玛加萨讨厌凯恩吗","凯恩与玛加萨"}},{q="怒焰裂谷的任务是什么？",a="玛加萨派遣了一位名叫莫尔的使者前往奥格瑞玛下方的怒焰裂谷，与当地的石鄂怪进行谈判。然而石鄂怪杀死了莫尔，促使玛加萨派遣部落冒险者进入洞穴找回莫尔的背包，并屠杀石鄂怪作为报复。",al={"玛加萨怒焰裂谷任务","为什么玛加萨派遣莫尔","玛加萨丢失的背包"}},{q="阿瑞卡拉是谁？",a="阿瑞卡拉是一个复仇心切的风蛇之灵，据说它寻求对牛头人进行报复。玛加萨声称阿瑞卡拉直接寻求对凯恩·血蹄的复仇，并派遣有能力的勇士使用附魔龙舌兰来召唤并击杀这头野兽。",al={"复仇之蛇","阿瑞卡拉任务","玛加萨与阿瑞卡拉"}},{q="在哪里可以找到玛加萨·野性图腾？",a="玛加萨居住在雷霆崖长者高地顶部的大型主帐篷内，由她的仆人拉哈罗和两名冷漠的野性图腾卫兵伺候。",al={"玛加萨位置","玛加萨在哪里","玛加萨长者高地"}}},fx={ebac2d3c={q="玛加萨·野性图腾站在哪一边？",a="玛加萨·野性图腾首先效忠于自己和野性图腾部族。尽管她在雷霆崖的长者高地占有受人尊敬的一席之地，名义上也属于部落，但她的效忠纯粹是利益交换。她公开反对大酋长凯恩·血蹄对族人的愿景，更倾向于让牛头人以无情手段称霸，而非追求和平；她还谋求私下结盟，尤其是与被遗忘者结盟，以扩大自身部族的势力范围。",al={"玛加萨的效忠对象","玛加萨效忠于谁","玛加萨是否忠于部落"}},b26ae613={q="玛加萨·野性图腾想要什么？",a="玛加萨认为只有自己才有资格领导牛头人。她企图从凯恩·血蹄手中夺取权力，将所有弱小种族赶出卡利姆多，并收复族人的祖地。为了积蓄实现目标所需的力量，她不断搜集古代遗物、试探潜在敌人，并经营一些凯恩和其他长老绝不会认可的关系。",al={"玛加萨的目标","玛加萨在谋划什么","玛加萨的动机"}},["0cc6173c"]={q="玛加萨·野性图腾为什么在这里？",a="作为野性图腾部族的年长女巫和族长，玛加萨居于长者高地，在统一的牛头人部族中代表她那强悍的部族。她从高处为旅人提供建议、辅佐城中事务，并密切关注凯恩·血蹄的统治，确保自己的部族在雷霆崖的治理中保有重要话语权。",al={"玛加萨为什么在雷霆崖","玛加萨为什么在这里"}},["4e6ef5c4"]={q="玛加萨·野性图腾与谁有联系？",a="玛加萨统领着野性图腾部族的强悍战士，身边总有私人卫兵和仆从护卫。部族之外，她还与被遗忘者保持着异常密切且积极的合作关系，与扎玛药剂师等皇家药剂师学会成员共事；她也与卡利姆多各地的先知和特工保持私下联系，这些人并不属于凯恩的核心圈子。",al={"玛加萨的盟友","玛加萨与谁来往","玛加萨的人脉"}},["92d0808b"]={q="玛加萨·野性图腾为何声名显赫或令人畏惧？",a="玛加萨自幼便天赋异禀，拥有强大的萨满力量，并用一生将这份力量化为对野性图腾部族的绝对权威。雷霆崖的许多人都畏惧她无情的野心，私下传言她为了夺取部族领导权而安排了自己的婚事。她不惜使用黑暗的疗法、插手复仇之灵之事，并公然违抗凯恩，因此成为莫高雷最令人望而生畏的人物之一。",al={"玛加萨为何令人畏惧","玛加萨是否强大","玛加萨的声望"}}},fp="17,243,27.449.0,18.431.0,22.412.1,25.284.0,38.301.0,53.256.0,39.270.0,15.251.0,37.140.0"}
P.entries["npc:magga"] = {n="玛卡尔",s="玛卡尔是一位居住在杜隆塔尔试炼谷的兽人居民。她驻扎在大兽穴附近，对于刚开始在山谷中踏上旅程的新晋部落冒险者来说，她是迎接他们的熟悉面孔。",h="玛卡尔是一位居住在杜隆塔尔试炼谷的兽人居民。她驻扎在大兽穴附近，对于刚开始在山谷中踏上旅程的新晋部落冒险者来说，她是迎接他们的熟悉面孔。",kw={"杜隆塔尔","部落","旅店老板格罗斯克","玛卡尔","兽人","试炼谷","欢迎"},ang={["faction:Horde"]="对于初来乍到、环境严酷的试炼谷的新兵而言，玛卡尔为他们提供了通往杜隆塔尔的安心欢迎。"},sec={{t="试炼谷的迎宾者",b="试炼谷是年轻兽人和暗矛巨魔初次体验这个世界的地方。玛卡尔位于大兽穴附近，负责迎接来到山谷的新人。虽然她在山谷中忙碌的训练师和新兵之间保持低调，但她有助于将这个小营地团结在一起。"}},faq={{q="玛卡尔是谁？",a="玛卡尔是一位驻扎在杜隆塔尔试炼谷的兽人平民。她站在大兽穴附近，欢迎新的部落旅行者。",al={"玛卡尔 杜隆塔尔","玛卡尔 试炼谷","玛卡尔是谁"}},{q="玛卡尔和旅店老板格罗斯克有什么联系？",a="没有任何关于他们之间特殊联系的记录。玛卡尔待在试炼谷，而旅店老板格罗斯克则经营着剃刀岭的旅店，为旅客提供食物、饮料以及绑定炉石的地方。",al={"玛卡尔和格罗斯克","玛卡尔 旅店老板"}},{q="玛卡尔提供任务吗？",a="玛卡尔负责“欢迎！”差事：持有试炼谷礼品券的冒险者会将它交给她，她会送出一只小宠物作为礼物，欢迎他们来到艾泽拉斯。",al={"玛卡尔 任务","欢迎任务"}}},fx={["7d8c5102"]={q="玛卡尔站在哪一边？",a="玛卡尔是部落的忠诚成员，与同胞兽人一同居住在试炼谷。她欢迎来到谷中的新人，并自豪地支持在萨尔领导下的族人以及杜隆塔尔的防卫。",al={"玛卡尔的阵营","玛卡尔是部落成员吗","玛卡尔的效忠对象"}}},fp="5,201,40.272.0,13.124.0,46.199.0,28.174.0"}
P.entries["npc:maggran-earthbinder"] = {n="马格兰",s="马格兰是一位饱经风霜的牛头人老兵，被大酋长凯恩·血蹄任命为烈日石居部落营地的指挥官。他毕生历经残酷的战争磨砺，如今负责保卫石爪山脉的崎岖山谷，抵御贪婪的野兽和充满攻击性的鹰身人部族。尽管身经百战的他已感到疲惫，但他依然是这座定居点坚定的守护者。",h="马格兰是一位饱经风霜的牛头人老兵，被大酋长凯恩·血蹄任命为烈日石居部落营地的指挥官。他毕生历经残酷的战争磨砺，如今负责保卫石爪山脉的崎岖山谷，抵御贪婪的野兽和充满攻击性的鹰身人部族。尽管身经百战的他已感到疲惫，但他依然是...",kw={"贝塞雷斯","血怒鹰身人","凯恩·血蹄","大地缚者","鹰身人","马格兰","石爪山脉","烈日石居"},ang={["faction:Horde"]="对于在石爪山脉崎岖道路上行进的旅行者来说，马格兰是协调当地部落巡逻队并确保补给路线不受野兽和鹰身人侵扰的主要负责人。",["race:Tauren"]="马格兰体现了战争对舒哈鲁精神造成的沉重代价，提醒着人们冲突是如何让即使是最脚踏实地的“大地母亲”的孩子们也变得冷酷坚硬。"},sec={{t="老兵的避风港",b="马格兰是大酋长凯恩·血蹄亲自派往石爪山脉的。作为无数次冲突和血腥战役的老兵，马格兰承认，岁月和暴力已经磨硬了他的心，抹去了他族人原本天生的温和。烈日石居既是他在稳健指挥下的哨所，也是一个让他可以休憩的地方，温暖的风和山间的阳光或许能抚慰他那饱经战火摧残的心灵。"},{t="悬崖间的威胁",b="即便是在石爪山脉，马格兰也难寻片刻安宁。作为烈日石居的监督者，他统筹防御力量，抵御盘踞在山峰上的血怒鹰身人，并派遣战士反击遍布峭壁的掠食者。他曾侥幸从巨型蜘蛛贝塞雷斯的伏击中逃脱，因此对周围致命的荒野绝无幻想，并经常招募旅行者在危险的野兽淹没哨所前将其消灭。"}},faq={{q="马格兰是谁？",a="马格兰是位于石爪山脉烈日石居的牛头人指挥官。他身经百战，被凯恩·血蹄派驻于此，负责看守定居点，确保补给路线和边界的安全。",al={"马格兰","马格兰是谁","烈日石居的领袖"}},{q="马格兰为何被派往烈日石居？",a="凯恩·血蹄任命他负责烈日石居，部分是因为他丰富的军事领导经验，部分也是为了让他休养生息。马格兰的身心已在毕生的战斗中严重受损，而寂静的山间阳光能带给他一定程度的治愈。",al={"马格兰为什么在这里","马格兰的背景","凯恩与马格兰"}},{q="马格兰要求冒险者处理哪些威胁？",a="马格兰指挥防御力量对抗盘踞在群山中的凶残的血怒鹰身人，并派遣战士去消灭巨型蜘蛛母兽贝塞雷斯，这只恐怖的掠食者曾让他在早年的旅途中险些丧命。",al={"马格兰的任务","马格兰想要什么","石爪山脉的鹰身人"}},{q="马格兰和贝塞雷斯之间发生了什么？",a="马格兰曾被巨型蜘蛛贝塞雷斯咬伤。尽管他成功击退了它并保住性命逃脱，但他还是会派遣有能力的冒险者去杀死这只野兽，以免其他人成为它的猎物。",al={"马格兰与贝塞雷斯","蜘蛛任务马格兰","恐蛛症传说"}},{q="马格兰在雷霆崖担任什么职务吗？",a="马格兰直接听命于雷霆崖的大酋长凯恩·血蹄。虽然他驻守在烈日石居的前线，但他的职权和命令都直接源自首都。",al={"马格兰与雷霆崖","马格兰与凯恩"}},{q="马格兰对联盟玩家友好吗？",a="不友好。马格兰是一位坚定的部落领袖，对于误入烈日石居的任何联盟冒险者，他都保持完全敌对的态度。",al={"联盟可以和马格兰说话吗","马格兰敌对"}}},fp="19,387,17.455.0,20.472.0,27.247.0,41.256.0,55.228.0,44.210.0,42.201.0,52.133.0"}
P.entries["npc:magis-sparkmantle"] = {n="玛济斯·石衣",s="玛济斯·石衣是一位驻扎在卡拉诺斯雷酒酿制厂内的侏儒法师训练师。他为从寒脊山谷冒险进入丹莫罗腹地的初出茅庐的施法者们提供指导和训练。",h="玛济斯·石衣是一位驻扎在卡拉诺斯雷酒酿制厂内的侏儒法师训练师。他为从寒脊山谷冒险进入丹莫罗腹地的初出茅庐的施法者们提供指导和训练。",kw={"丹莫罗","侏儒法师","卡拉诺斯","法师训练师","玛济斯","玛济斯·石衣","石衣","雷酒酿制厂"},ang={["class:Mage"]="对于穿越丹莫罗的联盟法师来说，石衣是法术训练和获取更广泛奥术网络推荐的重要本地联络人。",["race:Gnome"]="从诺莫瑞根流亡的侏儒经常依赖像石衣这样的导师，以确保他们在矮人中生活时，学术和奥术传统依然能够繁荣发展。"},sec={{t="酿制厂里的施法者",b="当矮人们聚集在雷酒酿制厂畅饮烈酒时，玛济斯·石衣在卡拉诺斯的木桶与酒桶间提供着奥术的指引。侏儒法师经常与他们在丹莫罗的矮人盟友紧密结合，而石衣作为关键导师，致力于帮助准备扩展其奥术理论与实践理解的新手法师。"},{t="指引年轻的奥术师",b="除了指导新手法师学习基础咒语外，玛济斯还确保有潜力的学生能与更广阔的魔法圈子取得联系。当法师们不再满足于早期的本地教学或需要专业的指导时，石衣会引导他们前往更远的地方，将他们引荐给像彬克这样的从业者，或派往联盟主要枢纽的导师那里。"}},faq={{q="玛济斯·石衣是谁？",a="玛济斯·石衣是一位居住在丹莫罗卡拉诺斯的侏儒法师训练师。他负责向新手法师教授奥术基础知识。",al={"玛济斯·石衣","玛济斯是谁","卡拉诺斯法师训练师"}},{q="在哪里可以找到玛济斯·石衣？",a="他位于雷酒酿制厂内，那是卡拉诺斯镇主要的旅店和聚会厅。",al={"玛济斯位置","玛济斯在哪里","找到石衣"}},{q="为什么一位侏儒法师训练师会待在矮人的酿制厂里？",a="诺莫瑞根陷落后，许多侏儒在丹莫罗的矮人表亲中定居下来。雷酒酿制厂是卡拉诺斯的中心枢纽，这使它成为了指导游历施法者的理想据点。",al={"为什么在酿制厂","在酿制厂的侏儒","为什么是雷酒酿制厂"}},{q="玛济斯·石衣提供任务吗？",a="随着法师们的成长，玛济斯会将他们引荐给其他奥术导师，包括派他们去找彬克交谈，或向人类领地的导师报告。",al={"石衣的任务","玛济斯的任务"}}},fx={["1189c3a2"]={q="玛济斯·石衣站在哪一边？",a="玛济斯·石衣坚定地支持诺莫瑞根和联盟。和许多逃离家园城市灾难、被迫流亡的侏儒一样，他与铁炉堡的矮人共同生活和工作，将自己的奥术知识贡献给联盟的守卫者。",al={"玛济斯·石衣的阵营","玛济斯是联盟成员吗","石衣效忠于谁"}},e3e37731={q="玛济斯·石衣想要什么？",a="玛济斯致力于教导初出茅庐的法师掌握奥术。住在酿酒厂期间，他为初级施法者做好前行准备，教授他们基础魔法，然后指引他们去找詹妮亚·坎农等暴风城的资深大师。",al={"玛济斯想要什么","玛济斯·石衣的目标","玛济斯为何训练法师"}},["318a77dd"]={q="玛济斯·石衣与谁有联系？",a="作为联盟法师网络的一员，玛济斯与各地的同行训练师保持联系，包括矮人领地的彬克以及暴风城 Mage Quarter 的詹妮亚·坎农，确保有潜力的学徒能够得到更深入的指导。",al={"玛济斯·石衣的盟友","石衣与谁有联系","石衣的人脉"}}},fp="17,224,31.369.0,25.350.0,25.132.0,37.107.0,60.222.0,40.173.0"}
P.entries["npc:magistrate-henry-maleb"] = {n="赫尼·马雷布镇长",s="赫尼·马雷布镇长负责南海镇的市政管理。南海镇是联盟在希尔斯布莱德丘陵地区主要的沿海据点。为了在不断的威胁中维持秩序，他将大部分精力投入到了追捕那些针对城镇领导层的辛迪加阴谋分子上。",h="赫尼·马雷布镇长负责南海镇的市政管理。南海镇是联盟在希尔斯布莱德丘陵地区主要的沿海据点。为了在不断的威胁中维持秩序，他将大部分精力投入到了追捕那些针对城镇领导层的辛迪加阴谋分子上。",kw={"奥特兰克","刺客","赫尼·马雷布","希尔斯布莱德","马雷布镇长","南海镇","辛迪加"},ang={["class:Rogue"]="潜行者会发现马雷布非常关注潜行和暗杀艺术，他依赖目光敏锐的特工来智胜辛迪加隐藏的杀手。",["faction:Alliance"]="对于抵达希尔斯布莱德的联盟勇士来说，马雷布镇长代表了这个无法无天的边境地区合法的市政权威，他会为清除破坏城镇稳定的辛迪加暴徒提供赏金。"},sec={{t="南海镇秩序的守护者",b="赫尼·马雷布镇长在南海镇的市政厅办公，负责处理这个洛丹伦仅存的几处真正的联盟定居点之一的民事治理。该镇不断受到来自北方和西方的被遗忘者的围攻，同时凶残的强盗也在丘陵地带四处游荡。在上一任镇长被离奇暗杀后，马雷布接任了现在的职位，他将那起事件直接归咎于辛迪加。为了避免重蹈覆辙，他积极协调调查工作，以铲除隐藏的刺客，瓦解辛迪加的补给网络，并揪出那些在奥特兰克废墟中幕后操纵的流亡贵族。"},{t="贵族背叛之网",b="马雷布对辛迪加的调查揭示了一场激烈的地区冲突。那些潜入南海镇外果园的刺客并非普通的强盗，而是收受了没落奥特兰克贵族雇佣的杀手。马雷布指派值得信赖的联盟侦察兵拦截他们的加密计划并消灭他们的首领，不遗余力地在辛迪加的阴谋彻底瘫痪城镇防御之前打破他们的控制。"}},faq={{q="赫尼·马雷布镇长是谁？",a="他是希尔斯布莱德丘陵地区南海镇的首席市政官，负责维持民事秩序并保护这个沿海的联盟避风港免受内部威胁。",al={"赫尼·马雷布","南海镇镇长","谁是马雷布"}},{q="为什么马雷布要调查辛迪加？",a="马雷布是在南海镇上一任镇长被暗杀后继任的。他的调查指向了由奥特兰克没落贵族派遣的辛迪加雇佣刺客，他积极委托联盟冒险者来预防针对他本人的另一次暗杀企图。",al={"为什么针对辛迪加","马雷布 辛迪加","南海镇刺客"}},{q="在哪里可以找到马雷布镇长？",a="他位于希尔斯布莱德丘陵南部地区的南海镇市政厅内。",al={"马雷布位置","赫尼·马雷布在哪里","寻找马雷布镇长"}},{q="马雷布在希尔斯布莱德面临哪些威胁？",a="除了来自北方和西方的被遗忘者扩张所带来的长期威胁外，马雷布还特别受到阴险的辛迪加杀手的威胁，他们潜伏在城镇周边，密谋推翻南海镇的治理。",al={"南海镇威胁","马雷布的敌人"}}},fx={["078ca783"]={q="赫尼·马雷布镇长站在哪一边？",a="赫尼·马雷布镇长全心效忠于联盟。作为南海镇的民事执政官，他为当地镇民服务，并听命于联盟当局，努力团结希尔斯布莱德地区仅存的自由人类，保护他们免受周边敌人的侵害。",al={"马雷布的阵营","马雷布属于联盟还是部落","赫尼·马雷布是联盟成员吗"}},b9806b6f={q="赫尼·马雷布镇长想要什么？",a="马雷布想要保护南海镇免遭毁灭，并终结辛迪加的掠夺行径。前任遭暗杀后，他接任镇长一职，决心查明阴谋者的身份、追踪那些行踪诡秘的刺客，并惩罚策划针对该镇阴谋的奥特兰克贵族。",al={"赫尼·马雷布的目标","马雷布需要什么","马雷布镇长的目标"}},a611609c={q="赫尼·马雷布镇长为什么在南海镇？",a="镇上的前任领袖遇刺后，马雷布最近被任命为南海镇的执政官。他在 Southshore Town Hall 主持事务，治理聚落、统筹镇上的防卫，并协调联盟对潜伏在希尔斯布莱德丘陵各处威胁的调查。",al={"马雷布为什么在南海镇","马雷布在南海镇的原因","马雷布镇长的市政厅"}}},fp="22,313,30.640.0,24.434.1,30.175.0,41.278.0,36.121.0,42.222.0"}
P.entries["npc:magistrate-sevren"] = {n="执政官塞弗伦",s="执政官塞弗伦是主管提瑞斯法林地布瑞尔定居点的首席行政官员。他站在市政厅内，负责组织被遗忘者的早期防御工作，并指挥前来报道的勇士稳定幽暗城周边的领土。",h="执政官塞弗伦是主管提瑞斯法林地布瑞尔定居点的首席行政官员。他站在市政厅内，负责组织被遗忘者的早期防御工作，并指挥前来报道的勇士稳定幽暗城周边的领土。",kw={"阿加曼德","布瑞尔","被遗忘者","执政官","塞弗伦","提瑞斯法","市政厅","幽暗城"},ang={["faction:Horde"]="抵达提瑞斯法的部落盟友会发现塞弗伦正在协调提瑞斯法林地的前线平定工作，对抗土匪、天灾余孽和反叛势力。",["race:Undead"]="对于离开丧钟镇的新生被遗忘者来说，执政官塞弗伦代表了Sylvanas疆域的民事面貌，为你提供保卫家园的首批重要任务。"},sec={{t="布瑞尔的城镇执政官",b="执政官塞弗伦在布瑞尔的市政厅内办公，负责统筹幽暗城以北地区的民政管理和战略部署。当新的被遗忘者来到提瑞斯法林地时，塞弗伦会评估当地的危机，并派遣冒险者去恢复秩序、加固受损的基础设施，并镇压潜伏在周边丘陵中的持续威胁。"},{t="守卫墓地",b="塞弗伦的主要关注点集中在提瑞斯法死者的保存与恢复上。当地的盗墓贼、腐皮豺狼人以及流亡的亡灵扰乱了墓地，威胁到了Sylvanas Windrunner日益壮大的统治。塞弗伦确保像阿加曼德家族墓穴这样的祖先陵墓被收回，并防止逃兵或不合作的势力在该地区颠覆被遗忘者的权威。"}},faq={{q="执政官塞弗伦是谁？",a="执政官塞弗伦是布瑞尔的行政首长，驻扎在市政厅内。他作为被遗忘者领土管理的监督者，为从丧钟镇赶来支援这片新成立王国的冒险者们派发任务。",al={"执政官塞弗伦","塞弗伦是谁","布瑞尔执政官"}},{q="在哪里可以找到执政官塞弗伦？",a="他在提瑞斯法林地布瑞尔中心的市政厅内。",al={"塞弗伦的位置","执政官塞弗伦在哪里","找到塞弗伦"}},{q="执政官塞弗伦处理哪些威胁？",a="塞弗伦致力于解决提瑞斯法林地面临的当地威胁，包括盗掘坟墓的腐皮豺狼人、亵渎当地地下墓穴的天灾余孽，以及拒绝向Sylvanas女王效忠的流亡亡灵。",al={"塞弗伦的任务","塞弗伦想要什么","布瑞尔的问题"}},{q="执政官塞弗伦效忠于谁？",a="他效忠于被遗忘者，并代表Sylvanas Windrunner和幽暗城治理布瑞尔。",al={"塞弗伦的阵营","塞弗伦效忠于谁"}},{q="为什么塞弗伦派遣冒险者去家族墓穴？",a="属于旧阿加曼德王朝的墓穴被亡灵和拾荒者威胁所占领。塞弗伦要求冒险者收复这些祖先的安息之地，以防止敌人利用它们。",al={"阿加曼德墓穴","塞弗伦的墓穴任务"}},{q="塞弗伦与幽暗城的领导层有联系吗？",a="是的。作为当地的执政官，他经常与幽暗城的特工和官员联络，派遣信使并在冒险者证明了在布瑞尔的能力后，指引他们前往首都。",al={"塞弗伦和幽暗城","塞弗伦的角色"}}},fx={["54ff886a"]={q="执政官塞弗伦想要什么？",a="作为布瑞尔的最高民政长官，塞弗伦想要为被遗忘者巩固提瑞斯法林地。他协调行动，清剿残余的天灾军团，镇压亵渎被遗忘者安息之地的盗墓者，并确保通往王国腹地的指挥和补给线路畅通。",al={"执政官塞弗伦的目标","塞弗伦的动机","塞弗伦想要什么"}},["2465c638"]={q="执政官塞弗伦为什么在布瑞尔？",a="塞弗伦在布瑞尔的市政厅主持事务，负责管理当地政务和法律，位置就在幽暗城城门外。他是主要的地方行政长官，负责指派新近苏醒和前来投奔的被遗忘者，为保护和整顿王国效力。",al={"塞弗伦为什么在布瑞尔","执政官塞弗伦的市政厅","塞弗伦所在位置的目的"}}},fp="17,260,24.369.0,19.396.0,25.236.0,37.78.0,46.220.0,39.102.0,53.204.0,50.212.0"}
P.entries["npc:magistrate-solomon"] = {n="所罗门镇长",s="所罗门镇长是湖畔镇的最高行政长官，在市政厅负责处理当地事务。由于受到黑石兽人和凶残的豺狼人部落的围攻，他终日都在焦急地恳求暴风城提供军事援助，但暴风城对此却漠不关心，无暇顾及。",h="所罗门镇长是湖畔镇的最高行政长官，在市政厅负责处理当地事务。由于受到黑石兽人和凶残的豺狼人部落的围攻，他终日都在焦急地恳求暴风城提供军事援助，但暴风城对此却漠不关心，无暇顾及。",kw={"黑石","伯瓦尔","湖畔镇","所罗门镇长","马瑞斯","普瑞斯托","赤脊山","所罗门","市政厅"},ang={["faction:Alliance"]="所罗门在政治上的孤立无援揭示了暴风城联盟内部的严重裂痕，表明了边远省份是如何完全依赖于自由冒险者来生存的。",["race:Dwarf"]="矮人访客可能会在所罗门的历史中发现一段悲剧性的联系，因为铁炉堡为响应他的求救信号所做的努力，最终导致了茉艾拉·铜须公主在伏击中被俘。",["race:Human"]="对于人类旅行者来说，与所罗门交谈可以揭示王国在艾尔文森林内陆边界之外的严峻局势。"},sec={{t="围困之中的城镇",b="所罗门镇长治理湖畔镇期间，正值其近代史上最黑暗的时刻。这座宁静的湖畔定居点四面受敌：赤脊山豺狼人和暗皮豺狼人在周围的山丘中徘徊，而黑石兽人则组成有组织的战团从北方不断来袭。所罗门与治安官马瑞斯并肩工作，以维持社会秩序并组织防御，但湖畔镇的当地卫兵和民兵已到了崩溃的边缘。"},{t="充耳不闻的呼吁",b="为了获得增援，所罗门心急如焚，派遣信使奔赴王国各地——请求西部荒野、夜色镇以及暴风城首府提供援助。然而他的请求只换来了苦涩的失望。西部荒野在迪菲亚潜行者的魔爪下苦苦挣扎，暮色森林被自身的恐怖阴影所笼罩，而暴风城则拒绝向东部边境部署军队，这使得湖畔镇只能完全依靠自己。"},{t="宫廷的拒绝",b="当黑石兽人与黑龙军团结盟的证据出现时，所罗门直接将这一警告转发给了伯瓦尔·弗塔根公爵。尽管威胁巨大，皇家顾问女伯爵卡特拉娜·普瑞斯托却将所罗门的恳求斥为无稽之谈。受限于她的建议以及暴风城捉襟见肘的兵力，伯瓦尔拒绝派遣暴风城军队，仅授权所罗门可以招募独立的雇佣兵。"}},faq={{q="所罗门镇长是谁？",a="所罗门镇长是湖畔镇的民事领袖，也是湖畔镇法庭的首席法官。他在市政厅办公，负责监督当地行政事务，并组织全镇进行防御，以抵御入侵的豺狼人和兽人。",al={"所罗门镇长背景故事","所罗门是谁","湖畔镇领袖"}},{q="为什么暴风城不能派兵支援他？",a="暴风城的军队在多个动荡地区捉襟见肘。当所罗门请求援助时，伯瓦尔·弗塔根公爵深受皇家顾问女伯爵卡特拉娜·普瑞斯托的影响，她质疑所罗门的报告，并极力阻挠向赤脊山派遣王国正规军。",al={"为什么没有暴风城军队","为什么暴风城不援助湖畔镇","伯瓦尔援助赤脊山"}},{q="铁炉堡尝试过提供援助吗？",a="是的。在所罗门的请求下，国王麦格尼·铜须派遣了一支由茉艾拉·铜须公主率领的救援队。然而，这支远征队在燃烧平原遭到了伏击并被俘虏，未能抵达赤脊山。",al={"湖畔镇的矮人增援","铁炉堡援助赤脊山","茉艾拉·铜须湖畔镇"}},{q="是什么威胁困扰着湖畔镇？",a="湖畔镇同时面临着来自赤脊山豺狼人和暗皮豺狼人的压力，它们在山丘和道路上横行霸道；此外，还有从石堡要塞和燃烧平原向南突袭的黑石兽人。",al={"是什么在攻击湖畔镇","赤脊山敌人","为什么所罗门很担心"}},{q="谁与所罗门一起防守城镇？",a="所罗门主要与治安官马瑞斯协调工作，后者负责指挥当地的城镇卫兵。由于正规援军始终未到，这两位官员不得不招募并授权过往的冒险者来击退入侵的威胁。",al={"湖畔镇保卫者","治安官马瑞斯和所罗门"}},{q="为什么所罗门要向夜色镇和西部荒野派遣信使？",a="所罗门知道暴风城的宫廷已经陷入停滞，因此试图与邻近的联盟定居点达成互助协议。不幸的是，西部荒野正受困于迪菲亚潜行者，而夜色镇则被亡灵和野兽淹没，双方都无法分出哪怕一名守卫来支援。",al={"前往夜色镇的信使","前往西部荒野的信使","所罗门寻求其他城镇援助"}}},fx={["85afa026"]={q="所罗门镇长站在哪一边？",a="所罗门忠于暴风王国和联盟。作为湖畔镇的民政长官，他听命于暴风城的王廷，并向伯瓦尔·弗塔根公爵请求军事支援，以保护他的人民。",al={"所罗门镇长的阵营","所罗门效忠于谁","所罗门的效忠对象"}},c7aa651d={q="所罗门镇长想要什么？",a="所罗门迫切希望获得军事援助和资源，以保卫湖畔镇免遭迫在眉睫的毁灭。侵略性十足的豺狼人群和步步逼近的黑石兽人将镇子围困其中，他希望得到暴风城和附近聚落的援军，或是愿意主动出击对抗敌人的能干冒险者。",al={"所罗门的目标","所罗门需要什么","所罗门镇长的动机"}},dc9ff3b9={q="所罗门镇长为什么在湖畔镇？",a="所罗门在湖畔镇的市政厅主持事务，因为他既是镇长，也是湖畔镇法庭的法官。尽管危险日益加剧，他仍坚守岗位，处理当地事务并组织赤脊山的防卫。",al={"所罗门为什么在赤脊山","所罗门在湖畔镇的职责","所罗门镇长的工作"}}},fp="18,263,18.445.0,20.447.0,19.458.1,26.249.0,44.300.1,31.224.1,37.213.0,42.241.0,57.292.0"}
P.entries["npc:magni-bronzebeard"] = {n="Magni Bronzebeard",s="Magni Bronzebeard是铁炉堡的领主，铜须氏族的族长，以及卡兹莫丹的统治者。作为第二次战争的一名老兵指挥官，他带领着自己的山脉王国历经悲痛与政治紧张局势，同时在艾泽拉斯各地大力支持矮人的考古事业。",h="Magni Bronzebeard是铁炉堡的领主，铜须氏族的族长，以及卡兹莫丹的统治者。作为第二次战争的一名老兵指挥官，他带领着自己的山脉王国历经悲痛与政治紧张局势，同时在艾泽拉斯各地大力支持矮人的考古事业。",kw={"brann","铜须","探险者协会","铁炉堡","卡兹莫丹","magni","moira","muradin"},ang={["faction:Alliance"]="作为与洛丹伦和暴风城并肩的联盟的坚定创始人，Magni为联盟提供了军事力量、工程技术和坚定的忠诚。",["profession:Blacksmithing"]="大熔炉在Magni城市的中心燃烧，在国王统治下工作的铁匠被认为是联盟中最优秀的铁匠之一。",["race:Dwarf"]="Magni是你无可争议的君主和卡兹莫丹的保护者，带领铜须氏族度过外部的战争和对你们种族古代遗产的内部探索。",["race:Gnome"]="Magni国王向诺莫瑞根的幸存者提供了避难所，并与大工匠Mekkatorque保持着密切的友谊和技术联盟。"},sec={{t="山脉领主",b="作为三兄弟中的长兄，Magni在成长过程中深知自己肩负着山脉之下沉重的使命。当部落在第二次战争期间入侵时，他将铁炉堡守在坚不可摧的大门后，并在围攻结束后现身，承诺让卡兹莫丹加入洛丹伦联盟。在随后的和平岁月里，Magni在诺莫瑞根陷落后迎接了他的侏儒盟友进入城市，让大工匠Gelbin Mekkatorque和他的难民在山中获得了庇护。为了团结四分五裂的南部和北部王国，Magni恳求Mekkatorque设计了一个史无前例的地下奇迹：矿道地铁，直接连接了铁炉堡和暴风城。"},{t="失去的兄弟",b="在Magni的王者威严之下隐藏着深沉的个人悲剧。第三次战争期间，有消息从诺森德传来，说他挚爱的弟弟Muradin在阿尔萨斯·米奈希尔王子的远征中丧生。Magni沉浸在悲痛之中，但他和最小的弟弟Brann仍然坚定地履行着对矮人人民的职责，国王在承受着那份哀伤的同时，依然明智地统治着国家。"},{t="挖掘历史",b="在Magni的法令下，矮人社会已将很大一部分重心从传统的商业采矿转向了发掘古代历史。在地下深处发现奇特的泰坦遗物后，Magni与他幸存的弟弟Brann Bronzebeard共同创立了探险者协会。如今，矮人的挖掘点遍布各个大陆，从丹莫罗到卡利姆多，致力于揭开矮人传说起源的奥秘。然而，国内的和平依然脆弱：Magni的女儿，Moira公主，已经失踪，据信是被可恶的黑铁氏族绑架了。"}},faq={{q="谁是Magni Bronzebeard？",a="Magni Bronzebeard是卡兹莫丹之王，铁炉堡的族长，以及铜须氏族的首领。他在铁炉堡的High Seat统治着这个山脉王国，是联盟的中坚支柱之一。",al={"铁炉堡之王","矮人国王","magni是谁"}},{q="是谁锻造了灰烬使者？",a="铁炉堡的记录中没有任何关于这把武器锻造过程的记载。灰烬使者被人们铭记为白银之手大领主亚历山德罗斯·莫格莱尼的佩剑，记录中没有任何证据表明其制作与Magni国王有关。",al={"magni制造了灰烬使者吗","灰烬使者的创造者","谁制造了灰烬使者"}},{q="Magni的兄弟们发生了什么事？",a="Magni是三兄弟中的长兄。他的弟弟Muradin曾担任联盟驻洛丹伦的大使，据报在诺森德被阿尔萨斯王子杀害。他最小的弟弟Brann是一位著名的探险家，他领导着探险者协会，足迹遍布世界各地。",al={"muradin和brann","magni的兄弟","muradin bronzebeard的命运"}},{q="Moira公主在哪里？",a="Magni唯一的孩子，Moira Bronzebeard公主，已经从铁炉堡失踪。山中的官方报告称，她被敌对的黑铁矮人绑架，目前被囚禁在黑石山的深处。",al={"magni的女儿","moira在哪里","moira bronzebeard发生了什么"}},{q="为什么侏儒住在铁炉堡？",a="在石腭怪入侵和诺莫瑞根遭到可怕的辐射污染后，Magni国王向大工匠Gelbin Mekkatorque和侏儒幸存者敞开了铁炉堡的大门。Magni将城市的一整个街区划拨给他们，现在被称为Tinker Town。",al={"tinker town","为什么侏儒在矮人城市","铁炉堡的侏儒难民"}},{q="什么是探险者协会？",a="探险者协会是由Magni国王和他的弟弟Brann创立的一个考古组织。在发现古代泰坦遗迹后，Magni指导矮人工业致力于发掘他们种族起源的真相，并派遣勘探队前往艾泽拉斯各地。",al={"探险者公会","矮人考古学家","为什么矮人在挖掘"}}},fp="17,261,20.683.0,14.398.0,19.585.0,25.222.0,26.212.0,34.283.0,24.239.0,35.242.0,30.267.0"}
P.entries["npc:magus-rimtori"] = {n="大法师雷姆托里",s="大法师雷姆托里是一位叛逆的血精灵女法师，在艾萨拉的古老废墟中领导着一支探险队。她以残酷的欺诈手段而闻名，曾操纵部落护送她穿越卡利姆多，随后便屠杀了她的兽人护卫。",h="大法师雷姆托里是一位叛逆的血精灵女法师，在艾萨拉的古老废墟中领导着一支探险队。她以残酷的欺诈手段而闻名，曾操纵部落护送她穿越卡利姆多，随后便屠杀了她的兽人护卫。",kw={"艾萨拉","贝尔格罗姆","血精灵","霍克海姆","金贾尔","大法师雷姆托里","雷姆托里","萨拉斯营地"},ang={["class:Mage"]="雷姆托里展示了萨拉斯法师为了绝望地追求奥术力量会走多远，甚至不惜搜寻卡利姆多的废墟和恶魔遗物。",["faction:Horde"]="雷姆托里操纵了贝尔格罗姆并屠杀了负责护送她的兽人卫队，这使得除掉她成为了寻求为阵亡同胞复仇的部落勇士的首要任务。"},sec={{t="致命的骗局",b="大法师雷姆托里带领一支高等血精灵探险队横跨大海，来到了艾萨拉的古老海岸。为了确保她的队伍在卡利姆多的险境中幸存下来，她操纵了兽人贝尔格罗姆，通过魅惑和利用他，迫使他同意提供一支武装护卫队。当士兵们将她安全送达目的地后，雷姆托里露出了真面目，转而攻击她的保护者，并屠杀了整个驻军。她在萨拉斯营地建立了据点，随后在精英保镖的陪同下深入沿海荒野，搜寻被遗忘的魔法神器。"},{t="废墟的秘密",b="雷姆托里探险队的真实动机仍笼罩在秘密之中，但她冷酷无情的手段为她招来了无数敌人。除了背叛部落，她还背叛了当地雇佣兵，包括地精测量员金贾尔，据他所称，雷姆托里痴迷于发掘一枚古老的符文。在营地里留下的恶魔召唤典籍等遗物的包围下，雷姆托里对力量的追求招致了被她冷酷背叛的部落的猛烈报复。"}},faq={{q="部落为什么要除掉雷姆托里？",a="雷姆托里魅惑并操纵了兽人贝尔格罗姆，让他为她的探险队提供横跨卡利姆多的军事护卫。当他们安全抵达艾萨拉后，她背叛并屠杀了贝尔格罗姆指挥下的每一名兽人士兵。",al={"为什么要杀雷姆托里","贝尔格罗姆雷姆托里剧情","雷姆托里对部落做了什么"}},{q="大法师雷姆托里在哪里？",a="虽然她的探险队建立了萨拉斯营地，但雷姆托里本人经常在艾萨拉的荒野中游荡，在私人血精灵保镖的陪同下搜寻古老的遗物。",al={"雷姆托里位置","大法师雷姆托里在哪里","雷姆托里艾萨拉位置"}},{q="雷姆托里在艾萨拉寻找什么？",a="根据地精金贾尔（曾受雇于她后被她背叛）的说法，雷姆托里疯狂地搜寻着一枚神秘的古老符文，以及其他强大的遗物，例如一本卡多雷召唤典籍。",al={"雷姆托里想要什么","雷姆托里在艾萨拉的目的","雷姆托里符文"}},{q="大法师霍克海姆是谁？",a="大法师霍克海姆是一位血精灵军官，受大法师雷姆托里之托，在她调查周边废墟时指挥并监管萨拉斯营地。",al={"霍克海姆","萨拉斯营地领导者","大法师霍克海姆雷姆托里"}}},fp="13,241,18.585.0,20.485.1,37.236.0,33.191.0,42.198.0,25.163.0"}
P.entries["npc:mai-ah"] = {n="迈安",s="迈安是一位丛林巨魔魔法导师，驻扎在杜隆塔尔试炼谷那片被烈日炙烤的盆地中。她为来到这片红色峡谷磨练奥术技艺的暗矛巨魔新手法师提供指导。对于踏上巫师之路的年轻巨魔来说，她会提供早期的引导，并传授魔法的基础艺术。",h="迈安是一位丛林巨魔魔法导师，驻扎在杜隆塔尔试炼谷那片被烈日炙烤的盆地中。她为来到这片红色峡谷磨练奥术技艺的暗矛巨魔新手法师提供指导。对于踏上巫师之路的年轻巨魔来说，她会提供早期的引导，并传授魔法的基础艺术。",kw={"暗矛","杜隆塔尔","魔法导师","迈安","巨魔","试炼谷"},ang={["class:Mage"]="对于暗矛施法者来说，迈安代表着他们魔法旅程的起点，她传授他们在杜隆塔尔烈日下编织火焰、冰霜和奥术能量所需的纪律。",["race:Troll"]="迈安在试炼谷为暗矛青年提供文化导师服务，这种艺术在他们的兽人盟友中极少被研习。"},sec={{t="大兽穴的奥术导师",b="虽然兽人大多偏爱元素之力的原始召唤或战士的物理统治，但暗矛巨魔却对奥术研究有着罕见的天赋。迈安驻守在试炼谷，为前来履行成人礼的年轻巨魔法师提供指导。她会接待带着符文羊皮纸的候选人，并将他们体内混乱的原始力量引导为严谨的咒语，确保他们学会如何在杜隆塔尔的险境中生存下来。"}},faq={{q="迈安是谁？",a="迈安是一位驻扎在杜隆塔尔试炼谷的暗矛巨魔魔法导师。在年轻的巨魔施法者前往部落的广阔土地之前，她为他们提供最初的指导、训练和基础法术。",al={"迈安是谁","迈安背景故事","巨魔魔法导师"}},{q="为什么兽人新手区会有巨魔魔法导师？",a="在暗矛巨魔逃离他们正在沉没的家园岛屿，并与萨尔的兽人一起在杜隆塔尔定居后，年轻的暗矛巨魔会与兽人青年一起经历成年试炼。由于兽人文化因过去的恶魔腐化而大体上排斥奥术魔法，因此像迈安这样的巨魔法师便承担起了引导同族的责任。",al={"为什么这里有巨魔法师","试炼谷巨魔导师","杜隆塔尔巨魔法师"}},{q="她在训练新手法师中扮演什么角色？",a="迈安欢迎携带书面指导（如Glyphic Parchment）的新手法师。她开启他们的正式训练，传授施法基础，以便他们能保卫试炼谷免受当地野兽和流氓火刃氏族渗透者的侵害。",al={"迈安的作用","glyphic parchment 迈安","迈安任务"}}},fx={["4a36b72a"]={q="迈安站在哪一边？",a="迈安忠于暗矛部族和部落。她驻扎在试炼谷，在大酋长萨尔的新政权下工作，致力于培养部落未来的施法者，并将自己的奥术知识用于增强年轻巨魔及盟友法师的实力。",al={"迈安的效忠对象","迈安效忠于谁","迈安是部落成员吗"}},["648de549"]={q="迈安想要什么？",a="迈安想要训练有志者掌握奥术基础。她希望指导年轻学徒学习入门法术和符文，确保他们具备在杜隆塔尔生存并为部落效力所需的纪律与魔力。",al={"迈安需要什么","迈安的目标","迈安为什么教导法术"}}},fp="6,368,24.501.0,14.245.0,58.314.0,46.263.0"}
P.entries["npc:major-mattingly"] = {n="玛丁雷少校",s="玛丁雷少校是一位驻守在英雄谷宏伟城门处的暴风城军队经验丰富的军官。他在马库斯·乔纳森将军麾下服役，协助保卫首都的主要入口，并指导有能力的工匠如何保护英雄免受龙类威胁。",h="玛丁雷少校是一位驻守在英雄谷宏伟城门处的暴风城军队经验丰富的军官。他在马库斯·乔纳森将军麾下服役，协助保卫首都的主要入口，并指导有能力的工匠如何保护英雄免受龙类威胁。",kw={"龙鳞披风","马库斯·乔纳森","玛丁雷少校","玛丁雷","暴风城军队","英雄谷"},ang={["class:Warrior"]="作为一名在城门处挥舞长剑、纪律严明的老兵，玛丁雷代表了暴风城军队步兵军官们坚定的决心。",["faction:Alliance"]="对于寻求挑战奥妮克希亚等巨龙的联盟勇士来说，玛丁雷少校提供了制作龙鳞防御披风所需的关键指导。"},sec={{t="首都大门的哨兵",b="玛丁雷少校在英雄谷站岗，是直接负责暴风城主要陆路防务的高级军官之一。作为一名饱经风霜的老兵，他的脸上刻满了历经艰辛所留下的印记。他在马库斯·乔纳森将军麾下与城市的常备卫戍部队并肩作战。除了负责监督城门巡逻和往来旅客的日常职责外，玛丁雷还拥有关于龙类致命习性的专业战术知识。经验丰富的冒险者公认他是学习制作必要防护龙鳞装备的关键联系人，这些装备对于挑战本区域最致命的巢穴至关重要。"}},faq={{q="玛丁雷少校在哪里？",a="玛丁雷少校驻守在暴风城的英雄谷入口附近，与城门内的卫戍部队士兵一起站岗。",al={"玛丁雷位置","玛丁雷少校在哪里","寻找玛丁雷少校"}},{q="玛丁雷少校在暴风城的军衔和职责是什么？",a="他是暴风城军队中马库斯·乔纳森将军麾下的一名军官。他协助监督城门的防御，并为冒险者提供军事指导。",al={"玛丁雷是谁","玛丁雷的工作","玛丁雷做什么"}},{q="制皮师为什么要找玛丁雷少校？",a="玛丁雷拥有关于如何处理黑龙皮并制作鳞片披风的说明，指导那些希望保护盟友免受龙焰伤害的熟练工匠。",al={"奥妮克希亚鳞片披风玛丁雷","玛丁雷任务","旅程才刚刚开始玛丁雷"}},{q="玛丁雷少校是否参与了任何更广泛的冲突？",a="他是暴风王国的久经沙场的老兵，在瓦里安·乌瑞恩国王失踪且王国面临持续威胁时，他致力于保卫王国。",al={"玛丁雷背景","玛丁雷背景故事"}}},fp="15,117,29.421.0,35.117.0,53.160.0,47.144.0,53.191.0"}
P.entries["npc:major-samuelson"] = {n="萨缪尔森少校",s="萨缪尔森少校是暴风城卫队的一名高级军官，驻扎在Stormwind Keep的王座大厅内。作为一名经验丰富的军事指挥官，他负责监管重要的人事事务，并曾指导过法尔林·奥里涅尔中尉等初级军官。",h="萨缪尔森少校是暴风城卫队的一名高级军官，驻扎在Stormwind Keep的王座大厅内。作为一名经验丰富的军事指挥官，他负责监管重要的人事事务，并曾指导过法尔林·奥里涅尔中尉等初级军官。",kw={"法尔林·奥里涅尔","萨缪尔森少校","重新分配","萨缪尔森","南海镇","暴风城卫队","stormwind keep"},ang={["faction:Alliance"]="萨缪尔森少校在皇家王座大厅内任职，代表着暴风城军队的行政骨干，指挥着在希尔斯布莱德等争议领土上的人员调动。"},sec={{t="暴风城卫队的支柱",b="萨缪尔森少校站在Stormwind Keep的皇家法庭前，代表着暴风城卫队的领导层。他负责监督整个王国的军官任命和行政军事命令。值得注意的是，他曾指导过法尔林·奥里涅尔中尉，后者是一名驻扎在希尔斯布莱德丘陵南海镇远北地区的军官。当初级指挥官感到不堪重负或寻求从遥远的边境驻地调离时，他们的请求和官方报告会直接传送到首都萨缪尔森少校的办公桌上。"}},faq={{q="萨缪尔森少校是谁？",a="萨缪尔森少校是暴风城卫队的一名军官，驻扎在Stormwind Keep的王座大厅内。他担任行政指挥官，处理军官部署和人事问题。",al={"萨缪尔森","萨缪尔森少校身份","要塞里的少校是谁"}},{q="在哪里可以找到萨缪尔森少校？",a="他位于暴风城的Stormwind Keep内，站在安度因·乌瑞恩国王和伯瓦尔·弗塔根公爵身旁的王座大厅里。",al={"萨缪尔森位置","萨缪尔森少校在哪里","寻找萨缪尔森"}},{q="他和南海镇有什么联系？",a="萨缪尔森少校曾担任法尔林·奥里涅尔中尉的导师，后者是驻扎在希尔斯布莱德丘陵南海镇的一名军官。奥里涅尔通过萨缪尔森寻求从压力巨大的北方驻地调职。",al={"萨缪尔森南海镇","法尔林·奥里涅尔中尉导师","萨缪尔森希尔斯布莱德"}},{q="为什么冒险者要寻找他？",a="从希尔斯布莱德北方前线赶来的冒险者携带法尔林·奥里涅尔中尉的正式调职请求，前往Stormwind Keep寻找萨缪尔森少校。",al={"暴风城任务提交","重新分配任务","为什么找萨缪尔森谈话"}}},fp="15,182,29.419.0,23.176.0,35.145.0,37.184.0,32.161.0"}
P.entries["npc:makaba-flathoof"] = {n="玛卡巴·扁蹄",s="玛卡巴·扁蹄是一位牛头人幸存者，来自石爪山脉的阿帕拉耶营地。在亲眼目睹家园和族人惨遭恐怖图腾氏族的屠戮后，他寻求部落勇士的帮助，以向袭击者复仇并确保家人的安全。",h="玛卡巴·扁蹄是一位牛头人幸存者，来自石爪山脉的阿帕拉耶营地。在亲眼目睹家园和族人惨遭恐怖图腾氏族的屠戮后，他寻求部落勇士的帮助，以向袭击者复仇并确保家人的安全。",kw={"阿帕拉耶营地","扁蹄","恐怖图腾","格鲁迪格·黑云","卡雅","玛卡巴","石爪"},ang={["faction:Horde"]="玛卡巴的求援请求让部落勇士们可以通过惩罚那些屠杀和平营地的凶手，来证明他们对牛头人盟友的忠诚。",["race:Tauren"]="对于牛头人英雄来说，玛卡巴的困境突显了恐怖图腾的卑劣背叛，提醒着人们并非所有的族人都尊崇和平与统一之道。"},sec={{t="阿帕拉耶营地的悲剧",b="玛卡巴·扁蹄代表了牛头人内部冲突所造成的惨痛代价。他的家园——石爪山脉的阿帕拉耶营地，遭到了恐怖图腾氏族的残忍突袭。当许多牛头人在凯恩·血蹄的领导下追求和平与统一时，背信弃义的恐怖图腾却不断播撒仇恨与暴力的种子，导致像玛卡巴这样的幸存者流离失所，悲痛欲绝。"},{t="复仇的请求",b="由于无法独自收复陷落的定居点，玛卡巴呼吁部落的旅行者发起反击。他指示人们对那些占领了他家园的恐怖图腾叛徒进行猛烈报复，要求为惨遭屠杀的族人伸张正义。他最急切的担忧是负责此事的督军格鲁迪格·黑云；他认为自己的女儿卡雅在袭击中失踪了。"}},faq={{q="玛卡巴·扁蹄是谁？",a="玛卡巴·扁蹄是一位来自石爪山脉阿帕拉耶营地的牛头人难民。他的村庄被恐怖图腾氏族攻占并洗劫，这促使他向部落冒险者寻求帮助。",al={"玛卡巴","玛卡巴·扁蹄是谁","玛卡巴·扁蹄背景故事"}},{q="玛卡巴来自哪里？",a="玛卡巴来自阿帕拉耶营地，这是位于石爪山脉的一个小型牛头人定居点，曾遭到恐怖图腾的袭击并被摧毁。",al={"玛卡巴出身","玛卡巴来自哪里","阿帕拉耶营地 玛卡巴"}},{q="是谁袭击了玛卡巴的村庄？",a="阿帕拉耶营地遭到了恐怖图腾氏族的洗劫。这是一个具有侵略性且背信弃义的牛头人派系，在当地由格鲁迪格·黑云等人领导。",al={"谁袭击了阿帕拉耶营地","玛卡巴的敌人","谁洗劫了阿帕拉耶"}},{q="玛卡巴希望部落冒险者做什么？",a="玛卡巴寻求为他陷落的家园复仇，请求有能力的战士铲除阿帕拉耶营地的恐怖图腾势力，并消灭他们的首领格鲁迪格·黑云。",al={"玛卡巴的任务","玛卡巴请求什么","玛卡巴的任务目标"}},{q="卡雅和玛卡巴是什么关系？",a="卡雅·扁蹄是玛卡巴的女儿。她在阿帕拉耶营地遇袭期间失踪，她的家人认为她在袭击中遭遇了不测。",al={"卡雅·扁蹄","卡雅是谁","玛卡巴的亲戚卡雅"}},{q="玛卡巴和迪姆·扁蹄有亲戚关系吗？",a="玛卡巴和迪姆都姓扁蹄，但两人之间是否存在家庭关系尚未得到证实。",al={"迪姆·扁蹄","玛卡巴和迪姆","扁蹄家族"}}},fx={["586aa360"]={q="玛卡巴·扁蹄效忠哪一方？",a="玛卡巴·扁蹄是部落和牛头人的忠诚成员。家园遭受暴力袭击后，他逃离了那里，只向部落的旅人和勇士寻求援助，以保护族人并反击袭击者。",al={"玛卡巴·扁蹄的阵营","玛卡巴属于部落吗","玛卡巴效忠谁"}},["6e0e5223"]={q="玛卡巴·扁蹄为何在这里？",a="家乡阿帕拉耶营地遭遇惨剧后，玛卡巴在石爪山避难。暴徒将他赶出了定居点，如今他留在这里寻求援助，为死去的族人复仇，并确保凯亚等幸存者的安全。",al={"玛卡巴·扁蹄为何在这里","玛卡巴为何在石爪山","玛卡巴·扁蹄的目的"}}},fp="15,291,23.401.0,20.357.1,23.189.0,27.144.0,30.141.0,46.163.0,22.136.0,34.97.0"}
P.entries["npc:malfurion-stormrage"] = {n="玛法里奥·怒风",s="玛法里奥·怒风是第一位凡人德鲁伊，也是与高阶女祭司泰兰德·语风共同领导暗夜精灵的尊崇领袖。他因在上古之战和第三次战争中击败燃烧军团而闻名，被尊称为“珊多”，即尊贵的导师。目前，他陷入了翡翠梦境中昏迷不醒的沉睡，使得卡多雷失去了他清醒时的指引。",h="玛法里奥·怒风是第一位凡人德鲁伊，也是与高阶女祭司泰兰德·语风共同领导暗夜精灵的尊崇领袖。他因在上古之战和第三次战争中击败燃烧军团而闻名，被尊称为“珊多”，即尊贵的导师。目前，他陷入了翡翠梦境中昏迷不醒的沉睡，使得卡多雷...",kw={"大德鲁伊","塞纳留斯","翡翠梦境","玛法里奥","海加尔","伊利丹","珊多","怒风","泰兰德"},ang={["class:Druid"]="每一位德鲁伊都将他们的教义追溯到玛法里奥，他直接师从于塞纳留斯。他在翡翠梦境中的缺席给塞纳里奥议会蒙上了一层沉重的阴影。",["class:Priest"]="玛法里奥是高阶女祭司泰兰德·语风的挚爱伴侣，将艾露恩的精神信仰与对自然的神圣守护结合在了一起。",["race:NightElf"]="玛法里奥被尊为你们人民的古老守护者和救世主，尽管他持续的沉睡使得统治权完全留给了泰兰德和大德鲁伊范达尔·鹿盔。"},sec={{t="第一位德鲁伊",b="一万年前，在大分裂摧毁古老的卡利姆多之前，玛法里奥师从半神塞纳留斯。当艾萨拉女王和她的上层精灵沉迷于永恒之井的奥术能量并进行危险的探索时，玛法里奥转向了原始的自然力量，成为了艾泽拉斯第一位凡人德鲁伊。当艾萨拉鲁莽的法术刺穿了帷幕，将萨格拉斯和燃烧军团召唤到艾泽拉斯，点燃了灾难性的上古之战时，玛法里奥对上层精灵的怀疑被证明是悲剧性地正确。"},{t="卡利姆多的救世主",b="玛法里奥与塞纳留斯、泰兰德·语风以及他的双胞胎兄弟伊利丹一起，领导了抵抗军，阻止了恶魔的猛攻并关闭了永恒之井上方的传送门。世界破碎后，玛法里奥让德鲁伊们进入翡翠梦境，以重建和保护艾泽拉斯的生命织锦。一万年后，泰兰德将他从漫长的林地巢穴沉睡中唤醒，以在第三次战争中对抗阿克蒙德，他在海加尔山集结了森林之魂，再次粉碎了燃烧军团。"},{t="迷失在梦境中",b="第三次战争后，玛法里奥回到了月光林地进行沉睡，以便与翡翠梦境沟通并补充消耗的力量。然而，他的灵魂未能回到他的肉体，使他陷入了一种不自然的昏迷状态。在达纳苏斯，大德鲁伊范达尔·鹿盔承担了塞纳里奥议会的临时领导职责，而泰兰德和姐妹会正焦急地等待着她们伟大的珊多醒来的迹象。"}},faq={{q="玛法里奥·怒风现在在哪里？",a="玛法里奥的肉体正在月光林地的林地巢穴中沉睡，而他的意识仍困在翡翠梦境的精神领域深处。他无法作为活跃的NPC在达纳苏斯被找到，因为他的身体处于昏迷状态，大多数冒险者无法接触到他。",al={"玛法里奥在哪里","去哪里找玛法里奥","玛法里奥的位置","玛法里奥在游戏中吗"}},{q="为什么玛法里奥在沉睡？",a="德鲁伊经常在翡翠梦境中冬眠，以与自然交流、维持世界的动植物并恢复他们的精神力量。在海加尔山击败阿克蒙德并承受了巨大的魔法压力后，玛法里奥进入了梦境进行恢复，但一种不自然的萎靡将他的灵魂与身体隔绝了。",al={"为什么玛法里奥在沉睡","他为什么昏迷不醒","玛法里奥发生了什么"}},{q="玛法里奥沉睡时，谁在统治暗夜精灵？",a="高阶女祭司泰兰德·语风在达纳苏斯的Temple of the Moon统治着卡多雷民族，领导着哨兵部队和The Sisterhood of Elune。与此同时，塞纳里奥议会和德鲁伊事务由大德鲁伊范达尔·鹿盔监管。",al={"谁领导暗夜精灵","谁是暗夜精灵的领袖","暗夜精灵统治者"}},{q="“珊多”是什么意思？",a="在达纳苏斯语中，“珊多”翻译为“尊贵的导师”。这是一个为大师级德鲁伊保留的最高敬称，最著名的是玛法里奥·怒风，他在塞纳留斯的教导下，首次将德鲁伊教义带给了凡人种族。",al={"珊多的含义","什么是珊多","珊多"}},{q="谁是玛法里奥的兄弟？",a="玛法里奥的双胞胎兄弟是伊利丹·怒风。尽管他们在苏拉玛度过了共同的童年，但伊利丹对奥术魔法的痴迷和对恶魔力量的鲁莽追求在上古之战期间在他们之间造成了深刻的裂痕，导致玛法里奥将他囚禁了数千年。",al={"玛法里奥的兄弟","伊利丹和玛法里奥的关系","怒风兄弟"}},{q="玛法里奥在海加尔山之战中做了什么？",a="在第三次战争的高潮时刻，玛法里奥在世界之树诺达希尔吹响了塞纳留斯之角，召唤出成千上万的古老森林之魂（小精灵）。这些灵魂蜂拥而至包围了恶魔领主阿克蒙德并引爆，摧毁了恶魔并焚毁了世界之树，从而拯救了卡利姆多。",al={"玛法里奥海加尔山","海加尔山之战玛法里奥","玛法里奥如何击败阿克蒙德"}}},fx={["65d9a7b2"]={q="玛法里奥·怒风是谁？",a="玛法里奥·怒风是艾泽拉斯最早的凡人德鲁伊，也是暗夜精灵至高无上的大德鲁伊。一万年前，他曾师从半神塞纳留斯，并在对抗艾萨拉女王与燃烧军团的上古之战中，带领族人历经浩劫。他与挚爱、高阶女祭司泰兰德·语风一同领导卡多雷数千年，既是族人的精神导师，也是自然界最强大的守护者。",al={"玛法里奥是谁","furion 是谁","玛法里奥·怒风的背景"}},af86ea6f={q="玛法里奥·怒风效忠哪一方？",a="玛法里奥首要效忠的是自己的族人卡多雷，以及致力于维护艾泽拉斯自然秩序的塞纳里奥议会。随着暗夜精灵近期缔结盟约，他的族人已与大联盟结盟；但玛法里奥的忠诚超越了琐碎的政治纷争——他一生的职责是守护自然平衡，并保护翡翠梦境免遭腐化。",al={"玛法里奥的阵营","玛法里奥是联盟成员吗","玛法里奥属于什么阵营"}},["1592db0d"]={q="玛法里奥·怒风想要什么？",a="玛法里奥最看重的是保护艾泽拉斯脆弱的自然平衡，并使翡翠梦境免受黑暗势力侵袭。一万年来，他为治愈满目疮痍的大地、击退恶魔入侵付出了巨大牺牲。他的一生都与守护荒野、照料世界之树，以及引导暗夜精灵走上与自然和谐共处的道路紧密相连。",al={"玛法里奥的目标","玛法里奥的目标是什么","玛法里奥的目的"}}},fp="19,403,15.549.0,18.530.0,17.461.0,39.270.0,24.330.0,49.248.0,25.229.0,27.276.0,51.294.0"}
P.entries["npc:mangletooth"] = {n="碎牙",s="碎牙是一只被关押在陶拉祖营地的剃刀鬃毛野猪人，正被部落囚禁。在面对处决之际，他用关于自己竞争对手的情报以及阿迦玛甘的古老传说，与愿意听他差遣的冒险者进行交易。",h="碎牙是一只被关押在陶拉祖营地的剃刀鬃毛野猪人，正被部落囚禁。在面对处决之际，他用关于自己竞争对手的情报以及阿迦玛甘的古老传说，与愿意听他差遣的冒险者进行交易。",kw={"阿迦玛甘","贫瘠之地","血岩碎片","刺鬃","陶拉祖营地","碎牙","野猪人","剃刀鬃毛"},ang={["faction:Horde"]="陶拉祖营地的守卫将碎牙关在笼子里严加看管，但部落愿意利用这名俘虏心中的苦涩怨恨来摧毁遍布贫瘠之地的野猪人要塞。",["race:Tauren"]="牛头人猎手为了争夺平原领地而不断与野猪人发生冲突，这使得碎牙愿意背叛同类的特质成为了一个有价值的，尽管有些令人不安的军事资产。"},sec={{t="枷锁中的人质",b="碎牙是一只被陶拉祖营地的牛头人猎手和兽人哨兵关在笼子里的剃刀鬃毛野猪人，等待着被处决。与其束手待毙，他试图操纵看守和路过的部落冒险者去击败他部族的敌人，希望能以此展现自己的价值或换取获救的机会。"},{t="内部的背叛",b="碎牙最初打算通过引导部落的力量去对付敌对的刺鬃部族，以此来赢得他所在部族的感激。然而，他很快意识到，他的剃刀鬃毛同僚——纳克、库兹和洛克兽人克星——已经彻底抛弃他自生自灭了。这只被俘的野猪人对他们的背叛感到愤怒，转而向自己的族人复仇，指使冒险者去处决他曾经的盟友。"},{t="血岩碎片的力量",b="碎牙对本族的宗教历史非常了解，他知道贫瘠之地遍布的巨大荆棘源于上古之战时期阿迦玛甘洒下的鲜血。通过从被击败的刺鬃野猪人身上收集红色的结晶状血岩碎片，碎牙可以引导这位陨落野猪之神残留的神圣力量，为那些帮助他的人提供强大的远古祝福。"}},faq={{q="碎牙是谁？",a="碎牙是一只被关押在陶拉祖营地笼子里的剃刀鬃毛野猪人。他正面临部落的处决，并与冒险者进行交易，用指引和远古恩惠换取对方帮他铲除对手。",al={"碎牙","碎牙是谁","被关在陶拉祖的野猪人"}},{q="碎牙为什么会被关在笼子里？",a="他在南贫瘠之地部落与野猪人的冲突中被俘。陶拉祖营地的牛头人和兽人将他关押起来，等待对其执行处决。",al={"碎牙为什么会被俘","为什么在笼子里","为什么是陶拉祖的囚犯"}},{q="为什么碎牙让你去攻击其他的剃刀鬃毛野猪人？",a="碎牙意识到他的部族成员——纳克、库兹和洛克兽人克星——宁愿让他死也不愿来营救。他被他们的背叛激怒了，出于纯粹的怨恨，他委派过路人去处决他们。",al={"为什么要攻击剃刀鬃毛","内部的背叛传说","为什么要杀纳克和库兹"}},{q="什么是血岩碎片？",a="血岩碎片是结晶矿物，形成于上古之战中野猪半神阿迦玛甘陨落时，其鲜血浸透大地的地点。刺鬃野猪人经常携带着这些碎片。",al={"血岩碎片","血岩碎片传说","阿迦玛甘之血"}},{q="在碎牙那里可以用血岩碎片做什么？",a="如果你为碎牙提供血岩碎片，他会引导阿迦玛甘的神圣力量将其转化为临时的祝福，赋予你更强的力量、敏捷、韧性、精神或速度。",al={"血岩碎片增益","血岩碎片上交","碎牙给什么奖励"}},{q="碎牙说阿迦玛甘死在哪里？",a="碎牙叙述道，阿迦玛甘在上古之战的战斗中陨落。他洒下的鲜血催生了巨大的荆棘之柱，而他巨大的头骨则深藏在南边的一座洞穴中，作为圣物供奉。",al={"阿迦玛甘传说","阿迦玛甘死在哪里","野猪之神头骨"}}},fx={d88e6e26={q="碎牙效忠哪一方？",a="碎牙只为自己效力。尽管他出身于剃刀沼泽野猪人，却并不真心效忠囚禁他的部落；当他发现族人已经抛弃自己后，也不再对自己的部族抱有忠诚。他与部落冒险者合作，只是为了活下去并反击敌人的绝望交易。",al={"碎牙效忠哪一方","碎牙忠于谁","碎牙属于部落吗"}},["7791b01e"]={q="碎牙想要什么？",a="面临在陶拉祖营地被处决的命运时，碎牙最初只想活下去，并证明自己的部族凌驾于刺背野猪人之上，希望族人能来救他。当他发现剃刀沼泽的首领 Nak、Kuz 和 Lok Orcbane 已经抛弃自己后，他转而渴望复仇，并收集血岩碎片中的神圣力量。",al={"碎牙想要什么","碎牙的目标","碎牙想做什么"}},["1234667b"]={q="碎牙与谁有关联？",a="碎牙属于南贫瘠之地的剃刀沼泽野猪人。他的命运与部族对手 Nak、Kuz 和 Lok Orcbane 纠缠在一起，他们的背叛激起了他的怒火。他也崇敬古老的野猪之神阿迦玛甘；阿迦玛甘四散的精华让碎牙能够为那些带来这位陨落之神血液遗物的人赐福。",al={"碎牙的人际关系","碎牙认识谁","碎牙的部族"}}},fp="11,237,19.339.0,20.389.1,25.399.0,19.213.0,29.171.0,64.201.1,22.209.0,49.182.0,42.201.0"}
P.entries["npc:mankrik"] = {n="曼科里克",s="曼科里克是一位沉浸在悲痛中的兽人战士，驻扎在贫瘠之地的十字路口。在一次残酷的野猪人伏击中，他与妻子奥格拉失散，此后他便致力于为妻子复仇，发誓要除掉他所能找到的每一只荆棘野兽。",h="曼科里克是一位沉浸在悲痛中的兽人战士，驻扎在贫瘠之地的十字路口。在一次残酷的野猪人伏击中，他与妻子奥格拉失散，此后他便致力于为妻子复仇，发誓要除掉他所能找到的每一只荆棘野兽。",kw={"贫瘠之地","十字路口","黄金之路","曼科里克","奥格拉","野猪人","索克"},ang={["faction:Horde"]="对于到达十字路口的旅人来说，曼科里克的遭遇是对贫瘠之地各地凶残的野猪人部族所构成的严峻威胁的一个鲜明写照。",["race:Orc"]="曼科里克体现了在卡利姆多荒野边疆定居所付出的惨痛代价，在这里，家庭和荣誉时刻都在经受着残酷的原生威胁的考验。"},sec={{t="尘土中的伏击",b="当曼科里克和他的妻子奥格拉穿越贫瘠之地的灌木丛时，在一个小型牛头人定居点遭遇了一场遭遇战，他们被成群的野猪人淹没了。在混乱和疯狂的战斗中，两人失散，曼科里克眼睁睁看着奥格拉消失在獠牙和荆棘武器的浪潮之中。他被愤怒冲昏了头脑，不顾一切地战斗，直到被打昏在地。他之所以能活下来，只是因为一名路过的牛头人德鲁伊在黄金之路上发现了失血过多的他，并包扎了他的伤口。"},{t="复仇的火焰",b="在十字路口康复期间，曼科里克发现自己被悲痛和吞噬一切的嗜血欲望所麻痹。尽管索克等当地领导人警告说，盲目的仇恨蒙蔽了他的判断力，并拒绝组织官方的战争派系，但曼科里克拒绝离去。由于对奥格拉命运的未卜感到痛苦，他招募了任何愿意帮忙的部落旅人，在贫瘠之地搜寻他失踪妻子的踪迹，并屠杀所有挡在路上的野猪人。"}},faq={{q="谁是曼科里克？",a="曼科里克是一位居住在贫瘠之地十字路口的兽人战士。他幸存于一场残酷的野猪人伏击，那次伏击使他与妻子失散，也使他陷入了愤怒，发誓要为她复仇。",al={"曼科里克背景故事","曼科里克是谁","曼科里克故事"}},{q="曼科里克的妻子发生了什么事？",a="在一次牛头人定居点的冲突中，曼科里克和奥格拉被大量的野猪人冲散。曼科里克在混乱中被打倒，而奥格拉则在战斗中失踪了。",al={"曼科里克的妻子","曼科里克的妻子在哪里","奥格拉发生了什么","奥格拉的命运"}},{q="曼科里克是如何在战斗中幸存下来的？",a="在被成群的野猪人打昏后，曼科里克被一名路过的牛头人德鲁伊在黄金之路上发现，该德鲁伊处理了他严重的伤口并将他带到了安全的地方。",al={"曼科里克如何幸存","谁救了曼科里克"}},{q="为什么索克拒绝帮助曼科里克？",a="十字路口的领导者索克认为，曼科里克强烈的愤怒和复仇欲望完全蒙蔽了他的判断力，使他无法理智地行事。",al={"索克为何不帮忙","索克与曼科里克"}}},fx={["63979fed"]={q="曼科里克效忠哪一方？",a="曼科里克效忠部落。他以贫瘠之地的十字路口为据点，依靠部落旅人与冒险者协助他进行绝望的搜寻，并反击威胁这片土地的野猪人。",al={"曼科里克的阵营","曼科里克属于部落吗","曼科里克属于联盟还是部落"}},["20b8339c"]={q="曼科里克想要什么？",a="曼科里克想查明失踪妻子 Olgra 的下落，并尽可能多地杀死野猪人。一次伏击让他与妻子失散，此后他便深陷悲痛与愤怒，满心只想向那些长着鬃刺的劫掠者复仇。",al={"曼科里克在寻找什么","曼科里克的目标","曼科里克需要什么"}},["5eb75604"]={q="曼科里克为何在十字路口？",a="一次野猪人袭击令曼科里克身受重伤，一名路过的牛头人德鲁伊沿着黄金之路将他拖到安全处。曼科里克如今仍留在十字路口，因为伤势未愈，加上心中挥之不去的不确定，让他无法离开最后见到妻子的地方附近。",al={"曼科里克为何在十字路口","曼科里克留在此处的原因","曼科里克为何在贫瘠之地"}},d34d6f35={q="曼科里克与谁有关联？",a="曼科里克与妻子 Olgra 之间维系着爱与悲痛；在被野猪人冲散之前，他们曾并肩作战。他也欠那位在黄金之路上为他疗伤的游历牛头人德鲁伊一条命。",al={"曼科里克的人际关系","曼科里克与谁有关联","曼科里克的家人"}}},fp="7,244,18.488.0,21.432.0,15.194.0,32.198.0,35.186.0,38.175.0"}
P.entries["npc:marcus-redpath"] = {n="Marcus Redpath",s="治安官Marcus Redpath是负责保卫希尔斯布莱德丘陵中联盟城镇南海镇的最高军事长官。他负责组织巡逻队和悬赏任务，以抵御周围的食人魔、鱼人和纳迦。他的领导对于维持洛丹伦在海岸上的最后一个南部堡垒至关重要。",h="治安官Marcus Redpath是负责保卫希尔斯布莱德丘陵中联盟城镇南海镇的最高军事长官。他负责组织巡逻队和悬赏任务，以抵御周围的食人魔、鱼人和纳迦。他的领导对于维持洛丹伦在海岸上的最后一个南部堡垒至关重要。",kw={"碎颅","希尔斯布莱德","marcus redpath","治安官","南海镇"},ang={["faction:Alliance"]="治安官Redpath为联盟勇士提供至关重要的任务，以确保希尔斯布莱德免受食人魔和沿海危险的侵害。",["race:Human"]="Redpath坚守着人类在洛丹伦的最后立足点之一，在王国四分五裂之际，维持着南海镇的存续。"},sec={{t="南海镇的哨兵",b="Marcus Redpath是南海镇的治安官，这是位于希尔斯布莱德丘陵南海岸的联盟港口。南海镇经历了洛丹伦首都的陷落和毁灭性的天灾入侵，而Redpath现在挺身而出，领导着该镇的防御工作，守护着港口饱受苦难的幸存者。"},{t="守卫海岸",b="在第三次战争之后，南海镇几乎孤立无援，独自面对来自四面八方的敌对势力。治安官Redpath负责协调希尔斯布莱德丘陵各地的防御行动，招募经验丰富的冒险者击退从奥特兰克潜入的碎颅食人魔，并扫荡海岸线上危险的纳迦和鱼人营地。随着被遗忘者占据了北部，而塔伦米尔附近又经过了重兵设防，Redpath的警惕成为了防止该地区联盟势力彻底崩溃的少数屏障之一。"}},faq={{q="Marcus Redpath是谁？",a="Marcus Redpath是希尔斯布莱德丘陵中南海镇的治安官和军事指挥官。他负责监督当地针对周围荒野威胁和敌对邻居的防御工作。",al={"marcus redpath背景故事","南海镇的治安官是谁","marcus redpath信息"}},{q="他在第二次战争中扮演了什么角色？",a="没有任何关于第二次战争的记录提到Redpath在其中的参与情况。他如今以南海镇治安官的身份为人所知，负责保卫该镇，抵御希尔斯布莱德丘陵的食人魔、鱼人和纳迦。",al={"第二次战争 marcus","marcus redpath见过洛萨吗"}},{q="他主要对抗哪些威胁？",a="Redpath组织军事力量对抗侵扰南海镇的当地掠食者和入侵者。他发布针对奥特兰克山麓的碎颅食人魔部落、沿海鱼人和袭击纳迦的悬赏和任务。",al={"marcus redpath任务","redpath想要猎杀什么"}},{q="他和达隆郡的Redpath家族有关联吗？",a="虽然他与因东瘟疫之地的达隆郡的Joseph Redpath上尉而闻名的Redpath姓氏相同，但除了他们在洛丹伦王国的共同背景外，并没有正式建立起直接的亲属关系。",al={"redpath家族","marcus和joseph redpath有亲戚关系吗","redpath亲属"}},{q="在哪里可以找到Marcus Redpath？",a="治安官Redpath驻扎在南海镇中心，这是一处位于希尔斯布莱德丘陵南海岸的联盟避风港。",al={"marcus redpath在哪里","marcus redpath位置"}}},fx={["0aeeadbf"]={q="Marcus Redpath 效忠哪一方？",a="治安官 Marcus Redpath 效忠联盟，以及聚集在南海镇旗帜下的洛丹伦幸存者。作为南海镇的治安官，他坚定地与人类守军并肩作战，抵御丘陵地带各处的敌对威胁，守住希尔斯布莱德防线。",al={"marcus redpath 的阵营","marcus redpath 属于什么阵营","redpath 效忠谁"}},["43107ef7"]={q="Marcus Redpath 想要什么？",a="Redpath 想保护南海镇及其周边地区，使其免遭步步逼近的危险。他积极指挥士兵与冒险者清除当地威胁，驱逐北部山脉的碎脊食人魔部族，并剿灭侵扰海岸的鱼人和纳迦。",al={"marcus redpath 的目标","redpath 需要什么","marcus redpath 的目的"}},["402d4dad"]={q="Marcus Redpath 为何在这里？",a="Marcus Redpath 是南海镇的治安官。第三次战争中洛丹伦沦陷后，南海镇成为联盟在该地区最后的据点之一，他负责组织防御并维持当地秩序。",al={"marcus redpath 为何在南海镇","redpath 留在南海镇的原因","redpath 在这里做什么"}}},fp="14,308,24.295.0,17.550.0,22.182.0,40.182.0,39.227.0,45.222.0,34.134.0"}
P.entries["npc:mardant-strongoak"] = {n="玛丹特·硬木",s="玛丹特·硬木是一位暗夜精灵德鲁伊训练师，居住在位于泰达希尔中心的奥达希尔。他引导新晋德鲁伊与自然之灵交流，并向他们介绍翡翠梦境的奥秘。",h="玛丹特·硬木是一位暗夜精灵德鲁伊训练师，居住在位于泰达希尔中心的奥达希尔。他引导新晋德鲁伊与自然之灵交流，并向他们介绍翡翠梦境的奥秘。",kw={"奥达希尔","德鲁伊","翡翠梦境","玛丹特","幽影谷","硬木","泰达希尔","训练师"},ang={["class:Druid"]="对于年轻的暗夜精灵德鲁伊来说，玛丹特·硬木是连接世俗生活与塞纳里奥议会神圣职责的第一座桥梁。",["race:NightElf"]="玛丹特驻扎在奥达希尔的核心，他是卡多雷致力于与泰达希尔蓬勃发展的生态系统保持和谐的典范。"},sec={{t="野性导师",b="在奥达希尔的枝叶间，感受到野性召唤的年轻暗夜精灵会向玛丹特·硬木寻求指引。他的主要任务是教导初学者如何开启对自然之灵的感知，解读它们的低语，并引导恢复性的魔法。对于那些迈出成为野性守护者第一步的人来说，他往往是第一位向他们揭示翡翠梦境那宏大复杂性和古老危险的导师。"}},faq={{q="玛丹特·硬木是谁？",a="玛丹特·硬木是一位驻扎在奥达希尔内幽影谷的暗夜精灵德鲁伊训练师。他指导泰达希尔上新觉醒的德鲁伊学习交流和施法的基本技艺。",al={"玛丹特·硬木背景故事","玛丹特是谁","奥达希尔的玛丹特"}},{q="他教导新德鲁伊什么？",a="他教导初学者如何解读野性之灵的信息，施放如月火术和治疗法术等基础法术，并理解翡翠梦境的本质。",al={"玛丹特教导什么","玛丹特的能力","幽影谷德鲁伊训练师"}},{q="我在哪里可以找到玛丹特·硬木？",a="他位于幽影谷的奥达希尔内部或附近，这是泰达希尔上暗夜精灵冒险者的起始山谷。",al={"玛丹特位置","玛丹特·硬木在哪里"}},{q="什么是绿色符记？",a="绿色符记是赠予幽影谷新晋暗夜精灵德鲁伊的指导信物，指引他们寻找玛丹特·硬木进行初步训练。",al={"绿色符记任务","给玛丹特的符记"}}},fx={ff8559f4={q="玛丹特·硬木想要什么？",a="玛丹特希望年轻的暗夜精灵学徒加深与自然的联系。他致力于引导新德鲁伊度过最初的试炼，帮助他们解读灵魂的低语，并应对翡翠梦境深邃的奥秘与危险。",al={"玛丹特想要什么","玛丹特·硬木的目标","玛丹特的目标是什么"}},b78651d9={q="玛丹特·硬木为什么在这里？",a="玛丹特驻守在奥达希尔中空的枝干间，担任新觉醒德鲁伊的导师，陪伴他们在泰达希尔迈出最初的步伐。他留在幽影谷照看新手，教导他们运用与生俱来的力量，并指引他们前往林间空地各处帮助有需要的人。",al={"玛丹特为什么在奥达希尔","玛丹特·硬木为什么在这里","玛丹特·硬木在此地的原因"}},dec3bef7={q="玛丹特·硬木与谁有关联？",a="玛丹特与塞纳里奥议会以及奥达希尔的其他教师关系密切，例如艾露恩的女祭司和守护圣所的哨兵。他们共同引导并培养暗夜精灵年轻的守卫者。",al={"玛丹特·硬木的盟友","玛丹特与谁有关联","玛丹特的人脉关系"}},a3bbc1b2={q="玛丹特·硬木效忠哪一方？",a="玛丹特·硬木忠于暗夜精灵、联盟，以及塞纳里奥议会的神圣信条。他坚定地驻守在幽影谷，守护初生的世界之树，并确保卡多雷德鲁伊的传统在这动荡时期得以延续。",al={"玛丹特·硬木的阵营","玛丹特效忠谁","玛丹特是联盟成员吗"}}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marek-ironheart"] = {n="马雷克·铁心",s="马雷克·铁心是一位驻守在洛克莫丹东南部的旅行者营地的矮人老猎人。他致力于守护荒野传统，在接纳四方游历的旅者和神射手进入营地受尊崇的猎人行列之前，会对他们进行考验。",h="马雷克·铁心是一位驻守在洛克莫丹东南部的旅行者营地的矮人老猎人。他致力于守护荒野传统，在接纳四方游历的旅者和神射手进入营地受尊崇的猎人行列之前，会对他们进行考验。",kw={"鳄鱼狩猎","旅行者营地","猎人","狩猎","铁心","洛克莫丹","马雷克·铁心"},ang={["class:Hunter"]="对于游侠和野兽追踪者来说，马雷克·铁心代表了旅行者营地的粗犷传统，他挑战猎人们去证明他们在面对当地野生动物时的精准度和追踪技巧。",["race:Dwarf"]="马雷克体现了许多卡兹莫丹矮人所珍视的户外运动文化，他选择了山脉中宁静的守望，而非铁炉堡嘈杂的熔炉之火。"},sec={{t="狩猎大师",b="旅行者营地坐落在俯瞰湖泊的风景优美的山脊上，是矮人国度中最优秀的射手和追踪者的前哨站。马雷克·铁心正是这种边境精神的化身。他不为头衔或言辞所动，要求任何想要获得营地尊重的人，必须在面对洛克莫丹各地徘徊的野兽时展现出实战能力，证明自己拥有作为一名真正的荒野追踪者所必须具备的耐心和勇气。"}},faq={{q="马雷克·铁心是谁？",a="马雷克·铁心是居住在洛克莫丹旅行者营地的一名矮人猎人。他会考验那些希望获得营地追踪者和户外运动者群体认可的访客。",al={"马雷克·铁心","马雷克是谁"}},{q="我在哪里可以找到马雷克·铁心？",a="他位于旅行者营地，坐落在洛克莫丹东南岸的山丘之中。",al={"马雷克·铁心位置","马雷克在哪里"}},{q="马雷克提供什么样的任务？",a="马雷克指引猎人们去追踪并猎杀洛克湖周围的各种当地野生动物，通过对抗危险的鳄鱼来考验他们的生存技能。",al={"马雷克·铁心任务","马雷克任务"}},{q="马雷克与其他已知的矮人有亲缘关系吗？",a="由于共享一个显赫的矮人姓氏，他可能与考古学家阿达曼特·铁心和伊米·铁心有亲戚关系，尽管马雷克将一生都奉献给了狩猎，而不是挖掘遗物。",al={"铁心家族","马雷克亲属"}}},fx={ac3880c9={q="马雷克·铁心属于哪一方？",a="马雷克支持联盟和铁炉堡的矮人氏族。他在洛克莫丹东南荒野的旅行者营地活动，欢迎其他联盟旅人通过掌握周边荒野来证明自己的实力。",al={"马雷克·铁心的阵营","马雷克·铁心与联盟","马雷克·铁心是联盟成员吗"}},["2928b65a"]={q="马雷克·铁心想要什么？",a="马雷克在洛克莫丹的旅行者营地活动，邀请猎人去猎杀湖边的鳄鱼。",al={"马雷克想要什么","马雷克·铁心的目标","为什么要找马雷克·铁心"}},ddec60fb={q="马雷克·铁心为什么在旅行者营地？",a="马雷克以旅行者营地为家，在洛克莫丹未经驯服的山丘上考验并训练林地猎手。他从这处偏远哨站守望当地野生动物，并指导希望在高地荒野磨炼野外技能的猎人。",al={"马雷克为什么在洛克莫丹","马雷克·铁心在旅行者营地的职责","马雷克为什么在这里"}}},fp="15,264,18.444.0,23.177.0,33.104.0,36.144.0,44.176.0"}
P.entries["npc:marisa-du-paige"] = {n="玛里莎·杜派格",s="玛里莎·杜派格是一位稀有的人类潜行者施法者，潜伏在西部荒野西南部死亡矿井入口外的洞穴网络中。她与月溪镇下方的亡命之徒同流合污，在守卫隧道的劳工和强盗中施展奥术魔法。",h="玛里莎·杜派格是一位稀有的人类潜行者施法者，潜伏在西部荒野西南部死亡矿井入口外的洞穴网络中。她与月溪镇下方的亡命之徒同流合污，在守卫隧道的劳工和强盗中施展奥术魔法。",kw={"死亡矿井","人类","法师","玛里莎·杜派格","月溪镇","稀有","西部荒野"},ang={["class:Mage"]="玛里莎·杜派格提醒人们，王国的奥术训练并不局限于肯瑞托的高塔或暴风城的巫师圣所；叛逆的施法者很容易将自己的才能出卖给犯罪网络。",["faction:Alliance"]="在月溪镇下方隧道中侦察的联盟冒险者必须对杜派格保持警惕，因为在一群扒手中出现一个意想不到的施法者，可能会迅速让一场小规模冲突演变为致命的战斗。"},sec={{t="隧道中的奥术天赋",b="在月溪镇下方通往死亡矿井的蜿蜒洞穴深处，大多数守卫都是粗鲁的扒手、叛变的矿工和暴徒。玛里莎·杜派格作为一名熟练的人类法师，在他们之中显得格格不入。虽然王国的大多数施法者都在暴风城Mage Quarter的指定大厅中受训，或者为肯瑞托效力，但杜派格却选择与躲藏在西部荒野地下的亡命之徒和强盗为伍。"}},faq={{q="玛里莎·杜派格是谁？",a="玛里莎·杜派格是一位潜伏在通往死亡矿井外围洞穴系统中的稀有人类法师。与巡逻这些通道的普通小偷和劳工不同，她施展奥术法术来保卫这个地下网络。",al={"玛里莎·杜派格","玛里莎是谁","死亡矿井洞穴中的稀有怪"}},{q="在哪里可以找到她？",a="她偶尔会出现在西部荒野月溪镇下方的公共洞穴系统中，即死亡矿井副本传送门入口外的隧道里。",al={"玛里莎·杜派格的位置","玛里莎·杜派格在哪里","玛里莎刷新"}},{q="为什么会有人类法师躲在死亡矿井的洞穴里？",a="并非每一位奥术修行者都忠于暴风城的高塔。逃兵、叛逆者和心怀不满的平民纷纷投靠了西部荒野的亡命之徒事业，为他们在月溪镇下方的防御工事贡献了钢铁和魔法。",al={"她为什么在这里","玛里莎背景故事","玛里莎·杜派格阵营"}}},fp="15,191,28.333.0,23.200.0,23.164.0,50.217.0"}
P.entries["npc:marleth-barleybrew"] = {n="马莱斯·麦酒",s="马莱斯·麦酒是一位雄心勃勃的矮人酿酒师，驻扎在烈酒村。她对雷酒家族在当地啤酒市场的统治地位感到沮丧，不断地策划如何证明她家族酿造的酒比卡拉诺斯的著名雷霆麦酒更胜一筹。",h="马莱斯·麦酒是一位雄心勃勃的矮人酿酒师，驻扎在烈酒村。她对雷酒家族在当地啤酒市场的统治地位感到沮丧，不断地策划如何证明她家族酿造的酒比卡拉诺斯的著名雷霆麦酒更胜一筹。",kw={"苦涩的竞争","烈酒村","矮人酿酒师","卡拉诺斯","马莱斯·麦酒","雷霆麦酒","雷酒"},ang={["race:Dwarf"]="对矮人来说，酿酒是一门与家族声望息息相关的艺术，这使得马莱斯与雷酒家族的宿怨成了一个关乎激烈家族荣誉的问题。"},sec={{t="酿酒竞争",b="在丹莫罗，人们对待酒精就像对待钢铁一样严肃，麦酒家族和雷酒家族之间的竞争早已成为了传奇。马莱斯·麦酒对拉格纳·雷酒和他的族人在卡拉诺斯的雷酒酿制厂所维持的近乎垄断的地位感到不满。她确信自己的手艺同样醇厚，因此想方设法地将麦酒家族的酒桶送到酒馆顾客手中。她没有选择公开冲突，而是采取了小规模的诡计，招募路过的旅行者偷偷将卡拉诺斯珍贵的麦酒桶换成她自己的产品。"}},faq={{q="马莱斯·麦酒是谁？",a="马莱斯是一位居住在丹莫罗西部烈酒村的矮人酿酒大师。她代表了麦酒家族，并积极致力于挑战雷酒家族在当地饮酒市场上的垄断地位。",al={"马莱斯是谁","马莱斯背景故事","马莱斯·麦酒"}},{q="我在哪里可以找到马莱斯·麦酒？",a="她位于烈酒村，该村坐落在丹莫罗西部，靠近涌冰湖。",al={"马莱斯位置","马莱斯在哪里","寻找马莱斯"}},{q="为什么马莱斯想要更换雷酒的啤酒？",a="马莱斯认为她家族酿造的麦酒和雷霆麦酒一样好，甚至更好。由于雷酒家族在卡拉诺斯的贸易中占据主导地位，她雇佣冒险者秘密地用麦酒家族的存货替换酒馆的酒桶，这样饮酒者就能品尝到她的产品，同时冒险者还能带回一份雷霆麦酒供她分析。",al={"为什么要换啤酒","苦涩的竞争任务原因","为什么要憎恨雷酒家族"}},{q="麦酒家族还有哪些成员？",a="她的大家族包括其他知名的酿酒师和商人，如Malgin、Rejold、Wellart和Yorus Barleybrew，他们都致力于传统的矮人酿酒工艺。",al={"麦酒家族","马莱斯的亲戚"}}},fx={c401045b={q="马莱斯·麦酒属于哪一方？",a="马莱斯是自豪的铁炉堡矮人，忠于联盟，不过她日常最关注的完全是生意。她属于麦酒酿造家族，并竭力捍卫家族的酿酒技艺，抵御当地竞争对手。",al={"马莱斯·麦酒的效忠对象","马莱斯·麦酒为谁效力","马莱斯的阵营"}},["716c9dd7"]={q="马莱斯·麦酒为什么在烈酒村？",a="烈酒村是丹莫罗雪山中的一处地区酿酒哨站。马莱斯在此酿造自家的啤酒，并谋划如何打入被雷酒家族垄断的大型市场。",al={"马莱斯为什么在这里","马莱斯·麦酒与烈酒村","马莱斯·麦酒为什么在丹莫罗"}}},fp="18,255,19.559.0,26.223.0,36.101.0,49.325.0,51.174.0"}
P.entries["npc:marryk-nurribit"] = {n="玛瑞克·斯托纳尔",s="玛瑞克·斯托纳尔是驻扎在寒脊山谷安威玛尔的侏儒法师训练师。比起严谨的教学，他似乎更喜欢当地的麦酒，他会在引导初出茅庐的侏儒奥术师学习技艺的同时，频频向他们讨要零钱去买酒喝。",h="玛瑞克·斯托纳尔是驻扎在寒脊山谷安威玛尔的侏儒法师训练师。比起严谨的教学，他似乎更喜欢当地的麦酒，他会在引导初出茅庐的侏儒奥术师学习技艺的同时，频频向他们讨要零钱去买酒喝。",kw={"安威玛尔","啤酒","寒脊","侏儒","法师","玛瑞克","斯托纳尔","训练师"},ang={["class:Mage"]="对于在寒脊山谷开启冒险旅程的侏儒法师新手来说，玛瑞克是第一位为你提供基础法术和《雕文备忘录》的导师。",["race:Gnome"]="在丹莫罗避难的难民们都知道玛瑞克，他是一个已经太过于适应矮人酒馆好客氛围的侏儒学者。"},sec={{t="奥术学习与麦酒",b="玛瑞克·斯托纳尔躲在安威玛尔温暖的炉火旁，为初次接触魔法的年轻侏儒们提供奥术指导。尽管他在奥术领域知识渊博，但他的态度却非常随意——比起传授复杂的理论知识，他似乎更热衷于抱着一罐矮人麦酒，并从新学员身上搜刮零花钱。尽管有这些嗜好，玛瑞克对寒脊山谷之外的危险仍有着清醒的认识，他经常警告有抱负的施法者们，小心诺莫瑞根陷落后遗留下的辐射和穴居人带来的威胁。"}},faq={{q="玛瑞克·斯托纳尔是谁？",a="玛瑞克·斯托纳尔是一位驻扎在丹莫罗寒脊山谷安威玛尔内的侏儒法师训练师。他负责向新到达的侏儒法师传授奥术魔法的基础知识。",al={"玛瑞克·斯托纳尔","玛瑞克是谁","安威玛尔法师训练师"}},{q="为什么玛瑞克总要钱买啤酒？",a="众所周知，玛瑞克喜欢当地烈酒胜过保持严格的职业操守。他经常缠着学生要零钱，好去酒馆满足他的饮酒嗜好。",al={"玛瑞克酗酒","玛瑞克啤酒","为什么他要硬币"}},{q="玛瑞克关于诺莫瑞根说了什么？",a="尽管他对训练的态度很随意，但玛瑞克意识到了真正的危险，并反复告诫新手法师们不要低估诺莫瑞根辐射废墟中潜藏的危机。",al={"玛瑞克诺莫瑞根","诺莫瑞根警告"}}},fx={["42f80152"]={q="玛瑞克·斯托纳尔属于哪一方？",a="玛瑞克忠于诺莫瑞根流亡者，并坚定地支持联盟。他与收留自己的矮人一同在丹莫罗避难，为初入寒脊山谷的侏儒传授奥术知识。",al={"玛瑞克·斯托纳尔的阵营","玛瑞克为谁效力","玛瑞克的效忠对象"}},["241b0acf"]={q="玛瑞克·斯托纳尔为什么在安威玛尔？",a="诺莫瑞根不幸沦陷于穴居人侵袭和有毒的辐射之后，玛瑞克和幸存的族人逃往丹莫罗。如今他留在寒脊山谷的安威玛尔，名义上的职责是教导初级侏儒法师奥术。",al={"玛瑞克为什么在这里","玛瑞克·斯托纳尔与安威玛尔","玛瑞克在丹莫罗的职责"}}},fp="15,261,22.589.0,23.175.0,47.191.0,38.197.0"}
P.entries["npc:marshal-dughan"] = {n="治安官杜汉",s="治安官杜汉是驻扎在闪金镇的暴风城军队分遣队的指挥官。他的任务是保卫艾尔文森林的核心区域，但他发现面对日益增多的狗头人、豺狼人和强盗的侵袭，当地驻军捉襟见肘。为了保障这座十字路口城镇及周边农场的安全，他非常依赖独立的冒险者。",h="治安官杜汉是驻扎在闪金镇的暴风城军队分遣队的指挥官。他的任务是保卫艾尔文森林的核心区域，但他发现面对日益增多的狗头人、豺狼人和强盗的侵袭，当地驻军捉襟见肘。为了保障这座十字路口城镇及周边农场的安全，他非常依赖独立的冒险者...",kw={"艾尔文森林","法戈第矿洞","闪金镇","霍格","玉石矿洞","治安官杜汉","暴风城军队","西泉要塞"},ang={["class:Warrior"]="对于战士类角色来说，杜汉体现了暴风城步兵在面对不可能战胜的困难时，依然坚守阵地的标准纪律和后勤压力。",["faction:Alliance"]="治安官杜汉代表了联盟在艾尔文森林的前线行政权力，为新到达的招募人员提供代表暴风城的最初军事任务。"},sec={{t="十字路口指挥官",b="治安官杜汉显眼地驻扎在闪金镇的Lion's Pride Inn外，肩负着在暴风城军事资源被调往他处的情况下维护艾尔文森林安全的重担。周围的林地正在不断恶化：害虫充斥着矿洞，豺狼人在河岸边集结，而劫匪在国王大道上骚扰过往的旅客。由于他直接指挥的步兵太少，杜汉通过指派新兵去增援前哨站并侦察争议地区来协调当地的防御。"},{t="各边境的威胁",b="杜汉目前最关心的就是法戈第矿洞和玉石矿洞内泛滥的狗头人，它们威胁着闪金镇至关重要的矿产产量。在西边，由臭名昭著的霍格领导的河爪豺狼人对西泉要塞施加了巨大的压力。在东边，杜汉被迫处理卫兵托马斯发来的报告，内容是关于凶残的鱼人在河边屠杀巡逻队。由于兵力有限，要同时应对这些相互重叠的危机，使得治安官不得不时刻需要能干的雇佣兵。"}},faq={{q="治安官杜汉是谁？",a="治安官杜汉是驻扎在闪金镇的一名暴风城军队军官。他负责艾尔文森林中部的军事安全，协调针对盗贼、豺狼人和狗头人等当地威胁的防御工作。",al={"杜汉","治安官杜汉背景故事","闪金镇治安官"}},{q="为什么杜汉不派更多的卫兵去帮助西泉要塞或东部地区？",a="暴风城军队兵力分散，导致杜汉手下的卫兵勉强只能维持闪金镇当地的治安。因为他没有足够的现役人手来驻守每一个偏远的农场和边境哨所，所以他依靠到访的冒险者来侦察热点地区、递送公文并清除区域内的危险。",al={"为什么没有卫兵","闪金镇驻军实力","杜汉的部队"}},{q="杜汉如何看待艾尔文森林的鱼人威胁？",a="起初，杜汉驳回了雷米“两次”关于鱼人是对该地区严重威胁的警告。直到卫兵托马斯发来了惨痛的报告，证实了卫兵罗尔夫·哈特福德和马拉凯·斯通在东部水道遇害，他才意识到真正的危险。",al={"杜汉与鱼人","雷米“两次”与鱼人"}},{q="杜汉如何处理当地的犯罪和吵闹的平民？",a="保持闪金镇及周边地区的和平是杜汉的职责，尽管据他自己所说，在没有艾尔文森林各地涌现的所有新麻烦的情况下维持秩序已经够难的了。他大部分精力都放在了北方的狗头人以及西方的豺狼人和盗贼身上。",al={"杜汉与犯罪","闪金镇法律","暴风城监狱威胁"}},{q="为什么杜汉担心这些矿洞？",a="法戈第矿洞和玉石矿洞是暴风城黄金和矿石的重要来源。狗头人已经占领了这两个地下建筑，驱逐了矿工，并威胁要将其隧道直接扩展到艾尔文森林的定居点之下。",al={"法戈第矿洞与杜汉","玉石矿洞与杜汉","狗头人泛滥"}},{q="治安官杜汉会与西部荒野协调吗？",a="是的。一旦冒险者证明了自己的能力，治安官杜汉就会指引他们前往西部荒野，向哨兵岭的格里安·斯托曼报告，那里的人民民兵正迫切需要老兵的帮助，以对抗迪菲亚潜行者。",al={"杜汉与格里安","向西部荒野报告","杜汉与哨兵岭"}}},fp="14,260,27.399.0,23.343.0,22.143.0,75.260.0,53.208.1,55.213.0,40.179.0,45.208.0"}
P.entries["npc:marshal-marris"] = {n="治安官马瑞斯",s="治安官马瑞斯是湖畔镇负责指挥镇卫队的饱受困扰的军官。他驻扎在城镇的桥边，协调防务以抵御从赤脊山高地上压境而来的大规模Blackrock兽人入侵。由于暴风城的军队缺席，他只能依靠来访的冒险者来遏制部落的推进。",h="治安官马瑞斯是湖畔镇负责指挥镇卫队的饱受困扰的军官。他驻扎在城镇的桥边，协调防务以抵御从赤脊山高地上压境而来的大规模Blackrock兽人入侵。由于暴风城的军队缺席，他只能依靠来访的冒险者来遏制部落的推进。",kw={"blackrock","大桥","湖畔镇","马瑞斯","治安官马瑞斯","赤脊山","石堡","tharil'zun"},ang={["class:Warrior"]="马瑞斯推崇直接的军事纪律，他会派遣能干的前线战士深入石堡的虎穴，与经验丰富的Blackrock老兵进行肉搏。",["faction:Alliance"]="治安官马瑞斯体现了Alliance农村领地的困境，他们因暴风城的政治瘫痪而处于脆弱的境地，被迫独自为生存而战。",["race:Human"]="对于王国的人类来说，马瑞斯代表了坚忍、饱受困扰的边境守卫，他们坚守防线，抵御Old Horde的残余势力。"},sec={{t="被围困的城镇",b="湖畔镇正处于崩溃的边缘，夹在西面的豺狼人和东面Blackrock氏族恐怖的军事力量之间。治安官马瑞斯负责监督城镇主桥上的防线，但他的资源已耗尽，士兵们也捉襟见肘。由于暴风城王国迟迟不派皇家援军，马瑞斯肩负着沉重的负担，必须防止这个城镇被蛮力所淹没。"},{t="粉碎Blackrock先锋",b="马瑞斯意识到仅靠防御无法拯救赤脊山，于是策划了针对兽人营地的果断进攻。他指挥雇佣兵剿灭Blackrock战士，铲除他们的暗影施法者，并最终追捕躲藏在石堡要塞废墟中的威胁性指挥官Tharil'zun。他的命令旨在打破兽人的指挥体系，以免一场全面突袭彻底摧毁湖畔镇。"}},faq={{q="治安官马瑞斯是谁？",a="治安官马瑞斯是负责保卫湖畔镇的最高军事指挥官。你可以在城镇大桥的西端找到他，他正站在那里守卫，试图让定居点免受敌对入侵。",al={"马瑞斯","治安官马瑞斯背景故事","湖畔镇大桥的卫兵是谁"}},{q="为什么治安官马瑞斯要雇佣外来的冒险者？",a="暴风城王国未能向赤脊山派遣足够的驻军支援，导致湖畔镇当地的卫队在人数上完全处于劣势。面对豺狼人战团和已扎根的Blackrock兽人入侵，马瑞斯被迫招募雇佣兵英雄来执行关键的打击任务。",al={"为什么马瑞斯需要帮助","为什么没有暴风城军队"}},{q="治安官马瑞斯正在对抗哪些威胁？",a="虽然豺狼人蹂躏着郊区，但马瑞斯主要关注的是占领了石堡要塞的Blackrock兽人。这些由Tharil'zun指挥并得到暗影魔法支持的兽人，对湖畔镇乃至整个王国构成了迫在眉睫的生存威胁。",al={"马瑞斯的敌人","谁在攻击湖畔镇"}},{q="治安官马瑞斯与Nathanos Marris有亲戚关系吗？",a="他们拥有Lordaeron和暴风城人类王国中常见的姓氏，但没有官方记录证实赤脊山的治安官马瑞斯与来自北方的著名游侠Nathanos Marris之间存在直接的亲属关系。",al={"马瑞斯和nathanos有关系吗","马瑞斯的家族"}},{q="马瑞斯击败Blackrock氏族的计划是什么？",a="马瑞斯实行消耗战和斩首行动。他指挥战斗人员剿灭Blackrock步兵，从他们的暗影施法者身上收集魔法组件，并攻入石堡要塞以处决他们的首领Tharil'zun。",al={"马瑞斯的计划","如何击败blackrock兽人"}},{q="治安官马瑞斯在哪里？",a="马瑞斯驻扎在赤脊山的湖畔镇，他位于城镇中心附近的大桥上，位置显眼。",al={"马瑞斯的位置","治安官马瑞斯在哪里"}}},fx={["4fad023e"]={q="治安官马瑞斯属于哪一方？",a="治安官马瑞斯是暴风王国和联盟的忠诚军官。他驻守在湖畔镇前线，代表当地军事当局，竭力保护赤脊山及其居民免受逼近的敌人侵袭。",al={"治安官马瑞斯的阵营","马瑞斯为谁效力","马瑞斯效忠联盟还是暴风城"}},["4230d686"]={q="治安官马瑞斯为什么在湖畔镇？",a="治安官马瑞斯驻扎在湖畔镇附近的桥边，负责协调防御，抵挡从山中涌出的黑石兽人。暴风城的官方增援十分有限，他便留守赤脊山，召集愿意进攻敌方据点的能干冒险者。",al={"治安官马瑞斯为什么在赤脊山","马瑞斯为什么在这里","治安官马瑞斯驻扎此地的原因"}}},fp="14,354,18.453.0,31.438.0,22.223.0,53.302.0,48.263.0,45.228.0,51.229.0,34.128.0"}
P.entries["npc:marshal-maxwell"] = {n="麦克斯韦尔元帅",s="麦克斯韦尔元帅是驻扎在燃烧平原摩根的岗哨的暴风城军队的一名高级军官。他的任务是守卫赤脊山上方的联盟最北端的防御山脊，以抵御黑石氏族和黑铁矮人。他指挥侦察任务进入下方充满敌意的岩壁。他还在协调工作以探明其被俘的战友，雷吉纳德·温德索尔元帅的下落方面发挥着关键作用。",h="麦克斯韦尔元帅是驻扎在燃烧平原摩根的岗哨的暴风城军队的一名高级军官。他的任务是守卫赤脊山上方的联盟最北端的防御山脊，以抵御黑石氏族和黑铁矮人。他指挥侦察任务进入下方充满敌意的岩壁。他还在协调工作以探明其被俘的战友，雷吉纳...",kw={"黑石深渊","燃烧平原","达基萨斯将军","麦克斯韦尔元帅","麦克斯韦尔","摩根的岗哨","雷吉纳德·温德索尔","暴风城军队"},ang={["class:Warrior"]="麦克斯韦尔体现了暴风城前线军队的纪律，他屹立在火山灰中，协调着深入敌后的突击行动。",["faction:Alliance"]="对于勇闯燃烧平原灼热高温的联盟勇士们来说，麦克斯韦尔元帅代表了暴风城的权威，也是针对黑石山战役的先锋。"},sec={{t="荒原上的孤寂哨所",b="摩根的岗哨是位于燃烧平原南缘的一处危险前哨站，俯瞰着一片充斥着灰烬、龙人和黑石兽人的荒地。麦克斯韦尔元帅指挥着驻扎在此的暴风城军事分遣队，为勇闯烈焰岩壁的旅行者提供了一处难得的友方据点。在这座岩石堡垒中，他监督防御演习，以将山中的敌对势力控制住，防止他们向南席卷进入赤脊山和艾尔文森林。"},{t="揭开山中的真相",b="除了日常的防御，麦克斯韦尔还担任针对黑石塔和黑石深渊腹地的行动的主要外勤联络官。当有传言称被俘的雷吉纳德·温德索尔元帅可能仍被关押在黑铁矮人的地下城中时，是麦克斯韦尔接收情报、筛选报告并指挥值得信赖的勇士们进行营救。他的岗哨构成了连接前线侦察与暴风城内不断酝酿的政治动荡之间的关键桥梁。"}},faq={{q="麦克斯韦尔元帅是谁？",a="麦克斯韦尔元帅是驻扎在燃烧平原摩根的岗哨的暴风城军队的一名指挥官。他领导着当地的联盟军队，监视着黑石兽人、黑龙和黑铁矮人。",al={"麦克斯韦尔元帅背景故事","麦克斯韦尔是谁"}},{q="为什么麦克斯韦尔元帅驻扎在摩根的岗哨？",a="摩根的岗哨是联盟毗邻燃烧平原的前线营地。麦克斯韦尔被派驻在此，以确保通往赤脊山的山路安全，并监测从黑石山涌出的威胁。",al={"为什么麦克斯韦尔在燃烧平原","摩根的岗哨指挥官"}},{q="麦克斯韦尔与温德索尔元帅有什么联系？",a="麦克斯韦尔是协助搜寻雷吉纳德·温德索尔元帅的关键指挥官，后者被俘虏并拖入了黑石深渊。麦克斯韦尔帮助协调营救工作，并将有关温德索尔的重要情报传回暴风城。",al={"麦克斯韦尔和温德索尔","遗弃的希望任务剧情"}},{q="麦克斯韦尔元帅会协助组织对黑石塔的打击吗？",a="会。麦克斯韦尔指挥经验丰富的联盟勇士们瓦解黑石氏族的高层，并发布针对达基萨斯将军及其占据黑石塔高地的部队的指令。",al={"麦克斯韦尔与达基萨斯","麦克斯韦尔的任务"}}},fp="15,446,28.475.0,36.518.1,23.216.0,51.231.0,48.243.0,67.205.0"}
P.entries["npc:marshal-mcbride"] = {n="治安官玛克布莱德",s="治安官道格拉斯·玛克布莱德是驻守在北郡修道院的暴风城卫队指挥官。他肩负着保卫北郡山谷的重任，指挥着刚抵达的新兵对抗威胁当地农场和矿场的狗头人侵扰。对于刚开始为暴风城王国效力的新手来说，他是主要的军事负责人。",h="治安官道格拉斯·玛克布莱德是驻守在北郡修道院的暴风城卫队指挥官。他肩负着保卫北郡山谷的重任，指挥着刚抵达的新兵对抗威胁当地农场和矿场的狗头人侵扰。对于刚开始为暴风城王国效力的新手来说，他是主要的军事负责人。",kw={"道格拉斯·玛克布莱德","回音山矿洞","艾尔文森林","狗头人","治安官玛克布莱德","北郡","北郡修道院"},ang={["class:Warrior"]="玛克布莱德积极寻找强壮的战士为王国效力，依靠前线战士来清理回音山矿洞中的隧道。",["faction:Alliance"]="玛克布莱德代表了人类腹地大联盟的起始前线，指引新兵投身于王权的麾下。",["race:Human"]="对于在北郡开始冒险的人类来说，治安官玛克布莱德是他们接触到的第一个代表暴风城皇室权威的人。"},sec={{t="北郡指挥官",b="治安官道格拉斯·玛克布莱德驻守在北郡修道院外，代表着暴风城军队在这个宁静山谷中的直接权威。虽然修道院本身是一处信仰与知识的圣地，但王国各地日益加剧的动荡使得原本就捉襟见肘的驻军更加吃紧。玛克布莱德必须仅靠少数誓言守卫和一批批在修道院大师指导下寻求训练的新兵，来维持治安并确保山谷的粮食与资源供应。"},{t="狗头人的入侵",b="玛克布莱德最头疼的问题是当地害虫的突然暴动。狗头人曾经只是些无足轻重的麻烦，如今却已侵占了周围的树林，并夺取了当地重要的经济命脉——回音山矿洞。由于缺乏清理这些害虫所需的正规军，玛克布莱德只能统领圣骑士、战士和其他新手去击退这些打洞的害虫，并在山谷彻底陷入瘫痪前查明侵扰的规模。"}},faq={{q="谁是治安官玛克布莱德？",a="治安官道格拉斯·玛克布莱德是一名暴风城军队的军官，担任北郡修道院的驻军指挥官。他负责保卫北郡山谷，并指挥新兵入伍。",al={"治安官玛克布莱德","玛克布莱德是谁","北郡指挥官"}},{q="为什么玛克布莱德要派新兵去对抗狗头人？",a="狗头人已经侵扰了北郡周围的森林，并控制了回音山矿洞。由于暴风城的军力吃紧，玛克布莱德不得不依靠刚抵达的冒险者来清除这些害虫，确保该地区的安全。",al={"为什么要消灭狗头人","狗头人问题","回音山矿洞问题"}},{q="玛克布莱德接下来会派新兵去哪里？",a="一旦新兵展现出处理北郡山谷威胁的能力，玛克布莱德就会指引他们沿南边的路前往闪金镇，去协助治安官杜汉。",al={"离开玛克布莱德后去哪","北郡之后","下一个城镇"}},{q="回音山矿洞是什么地方？",a="回音山矿洞是一个位于北郡山谷北缘、矿产丰富的洞穴。最近它被钻洞的狗头人占领，促使玛克布莱德下令进行多次行动将其收复。",al={"回音山矿洞","北郡的矿洞"}},{q="玛克布莱德指挥修道院本身吗？",a="不。北郡修道院由圣光的神圣教团和牧师们管理。玛克布莱德负责监管驻军，任务是保卫修道院和周围的山谷。",al={"玛克布莱德管理北郡修道院吗","谁在管理修道院"}},{q="玛克布莱德是否担心狗头人之外的威胁？",a="虽然狗头人是眼前最直接的麻烦，但玛克布莱德也在警惕更深层的动荡。土匪和暴徒徘徊在山谷边缘，预示着艾尔文森林各地正在酝酿着更广泛的动乱。",al={"北郡的迪菲亚","北郡安全吗"}}},fp="15,169,23.400.0,20.352.0,23.134.0,45.195.0,38.138.0,24.163.0,38.166.0,50.143.0"}
P.entries["npc:martie-jainrose"] = {n="玛蒂·詹罗斯",s="玛蒂·詹罗斯是湖畔镇当地的草药师，她在赤脊山的止水湖岸边照料着自己的花园。除了为饱受困扰的镇子培育草药和花卉外，她还要对付践踏她花圃的野兽，并且对卫兵帕克怀着一份默默的爱慕。",h="玛蒂·詹罗斯是湖畔镇当地的草药师，她在赤脊山的止水湖岸边照料着自己的花园。除了为饱受困扰的镇子培育草药和花卉外，她还要对付践踏她花圃的野兽，并且对卫兵帕克怀着一份默默的爱慕。",kw={"大肚皮","水仙花","卫兵帕克","草药师","湖畔镇","玛蒂·詹罗斯","赤脊山"},ang={["faction:Alliance"]="玛蒂在湖畔镇的坚持体现了赤脊山人民的坚韧，即便暴风城几乎对该镇不闻不问，他们依然努力维持着平凡的日常生活。",["profession:Herbalism"]="对于路过赤脊山的草药师来说，玛蒂展现了一种亲切的同伴之情，尽管受到野猪和入侵敌人的残酷破坏，她依然悉心照料着脆弱的花卉。"},sec={{t="湖畔花园",b="玛蒂·詹罗斯居住在湖畔镇，勤勤恳恳地担任着该定居点的常驻草药师。即使黑石兽人、豺狼人和当地的强盗威胁着这一地区，玛蒂依然专注于为镇子供应新鲜草药和花卉。她日常的劳作经常受到当地野生动物的干扰——最著名的是那头巨大的野猪大肚皮，它经常蹂躏她珍贵的花圃。除了草药事业外，玛蒂似乎对卫兵帕克情有独钟，然而帕克正在追求达希，而达希称玛蒂是一个嫉妒的竞争对手。"}},faq={{q="玛蒂·詹罗斯是谁？",a="玛蒂·詹罗斯是一位住在赤脊山湖畔镇的人类草药师。她在止水湖旁照料着一座花园，培育花卉并为当地居民准备草药。",al={"玛蒂·詹罗斯","玛蒂是谁","湖畔镇草药师"}},{q="玛蒂在当地野生动物方面遇到了什么麻烦？",a="一头巨大且极其顽固的野猪“大肚皮”经常袭击她的花园，在玛蒂采摘之前就践踏了她娇嫩的植株并吃掉了她的草药。",al={"玛蒂的野猪问题","大肚皮花园","谁在破坏她的花园"}},{q="玛蒂在湖畔镇喜欢谁？",a="玛蒂似乎对卫兵帕克很有好感。然而帕克正在追求达希，当他给达希送去一束玛蒂种的水仙花时，他要求玛蒂不要告诉达希花是谁送的。",al={"玛蒂的暗恋对象","玛蒂与卫兵帕克","传递水仙花的浪漫"}}},fx={["4d2b4277"]={q="玛蒂·詹罗斯效忠哪一方？",a="玛蒂是联盟的忠诚居民，安居在湖畔镇。她虽不在前线作战，也不携带武器，却以草药师的身份支持城镇及其守卫者。",al={"玛蒂·詹罗斯的阵营","玛蒂是联盟成员吗"}},e745a8a7={q="玛蒂·詹罗斯想要什么？",a="玛蒂想要平静地打理花园，不受打扰地钻研草药技艺。眼下最让她头疼的是一头名叫 Bellygrub 的巨型野猪，它总是践踏她珍视的庄稼。她很乐意欢迎任何愿意赶走这头野兽的旅人。",al={"玛蒂·詹罗斯的目标","玛蒂需要什么"}},["6d429f48"]={q="玛蒂·詹罗斯为什么在湖畔镇？",a="湖畔镇是玛蒂的家。她在止水湖宁静的湖岸边种植草药、打理花园，以此谋生，尽管赤脊山周边的麻烦日益加剧。",al={"玛蒂为什么在赤脊山","玛蒂·詹罗斯为什么在这里"}}},fp="15,293,20.545.0,23.202.0,54.182.0,35.199.0"}
P.entries["npc:marukai"] = {n="玛鲁凯",s="玛鲁凯是一位驻扎在灰谷西北部多雾海岸的佐拉姆加前哨站的暗矛丛林巨魔。她致力于为部落守住这个偏远的滩头堡，并负责协调清除威胁前哨站的侵入性愤怒之尾纳迦。",h="玛鲁凯是一位驻扎在灰谷西北部多雾海岸的佐拉姆加前哨站的暗矛丛林巨魔。她致力于为部落守住这个偏远的滩头堡，并负责协调清除威胁前哨站的侵入性愤怒之尾纳迦。",kw={"灰谷","暗矛","丛林巨魔","玛鲁凯","纳迦","愤怒之尾","佐拉姆海岸","佐拉姆加前哨站"},ang={["faction:Horde"]="玛鲁凯坐镇部落在暗夜精灵领地中最危险的沿海营地之一，依靠盟友勇士来阻止当地的纳迦攻占他们的阵地。",["race:Troll"]="远离森金村温暖的回响，玛鲁凯代表了暗矛部族的韧性，他们在卡利姆多各地为部落开辟了坚固的立足点。"},sec={{t="守住海岸",b="佐拉姆加前哨站孤立地坐落在佐拉姆海岸的北缘，四周环绕着古代遗迹、敌对的暗夜精灵领地以及波涛汹涌的大海。随着愤怒之尾纳迦成群结队地从水域和古老的精灵遗迹中涌出，试图占领海岸线，玛鲁凯努力使营地免于被淹没。她指挥部落勇士将这些蛇人赶回潮汐之中并收集他们的头颅，以确保该前哨站仍然是一个稳固的沿海据点。"}},faq={{q="玛鲁凯是谁？",a="玛鲁凯是一位丛林巨魔任务发布者，负责保卫佐拉姆加前哨站，这是部落位于灰谷西北海岸的一处孤立沿海营地。",al={"玛鲁凯背景故事","玛鲁凯是谁","玛鲁凯npc"}},{q="玛鲁凯为什么要与纳迦作战？",a="愤怒之尾纳迦已经侵扰了附近的佐拉姆海岸和周围的遗迹。为了保卫前哨站的边界并确保部落在海岸上的生存，玛鲁凯雇佣冒险者通过直接猎杀来削减它们的数量。",al={"为什么要杀纳迦","玛鲁凯纳迦任务","佐拉姆海岸纳迦"}},{q="玛鲁凯在哪里？",a="她在佐拉姆加前哨站与她的族人站在一起，该哨站位于灰谷西北部的佐拉姆海岸入口处，就在黑暗深渊水下遗迹的南面。",al={"玛鲁凯在哪里","玛鲁凯位置","寻找玛鲁凯"}}},fx={["53dc13db"]={q="玛鲁凯效忠哪一方？",a="玛鲁凯效忠部落。她驻守在灰谷海岸的佐拉姆加前哨站，守护部落的利益，并依靠部落旅人抵御当地的危险，保卫这处定居点。",al={"玛鲁凯的阵营","玛鲁凯是部落成员吗","玛鲁凯效忠谁"}},["1bf5ddde"]={q="玛鲁凯为什么在佐拉姆加前哨站？",a="玛鲁凯驻扎在佐拉姆加前哨站，负责守卫部落在佐拉姆海岸的据点。凶猛的怒尾纳迦重返海滩，威胁营地边界，她因此协调各方力量巩固外围防线，确保前哨站安全。",al={"玛鲁凯为什么在灰谷","玛鲁凯的职责","玛鲁凯为何来到这里"}}},fp="7,259,18.471.0,15.146.0,33.230.0,25.190.0"}
P.entries["npc:master-apothecary-faranell"] = {n="大药剂师法拉尼尔",s="大药剂师法拉尼尔是皇家药剂师学会的领袖，驻扎在幽暗城的药剂师区深处。生前他曾是一位受人尊敬的达拉然学者，而在死后，他指挥被遗忘者研制一种足以彻底消灭天灾军团与生者的毁灭性的“新瘟疫”。",h="大药剂师法拉尼尔是皇家药剂师学会的领袖，驻扎在幽暗城的药剂师区深处。生前他曾是一位受人尊敬的达拉然学者，而在死后，他指挥被遗忘者研制一种足以彻底消灭天灾军团与生者的毁灭性的“新瘟疫”。",kw={"憎恶","apothecarium","枯萎","法拉尼尔","大药剂师法拉尼尔","新瘟疫","伦弗瑞","皇家药剂师学会","希尔瓦娜斯","幽暗城"},ang={["faction:Horde"]="尽管兽人、巨魔和牛头人盟友可能会对药剂师区里的绿色软泥和关在笼子里的实验品感到不安，但法拉尼尔的研究作为对抗天灾军团这一共同威胁的重要作战手段，受到了各方的容忍。",["profession:Herbalism"]="法拉尼尔的实验桶消耗了无尽的珍稀植物、苔藓和真菌提取物，这是将植物学研究武器化以进行毁灭破坏的阴暗展示。",["race:Undead"]="对于被遗忘者而言，法拉尼尔代表了生物主权的前沿，他在黑暗中辛勤工作，确保他们的人民拥有足以粉碎巫妖王的武器。"},sec={{t="死后扭曲的思想",b="在第三次战争之前，法拉尼尔是一位德高望重的炼金术师，曾与达拉然的博学法师们一同研究了数十年。他生前致力于寻找治愈疾病、缓解伤痛和改善凡人健康的药剂。当“天灾瘟疫”夺去他的生命，使他复生为拥有自由意志的被遗忘者后，他曾经的科学好奇心便扭曲为了残忍。他保留了百科全书般的智识，却将治愈药膏换成了灾难性的试剂，并迅速成为希尔瓦娜斯·风行者女王在洛丹伦沦陷的首都深处最倚重的研究员之一。"},{t="药剂师区的大师",b="法拉尼尔在药剂师区有害的实验室里运作，统筹皇家药剂师学会的各项广泛研究。他监督着笨重憎恶的制造，并指挥驻扎在洛丹伦及其他地区的下属药剂师。由各地研究员收集的每一批奇怪的毒液、污秽的血液和被诅咒的植物，最终都会经过他的大桶进行蒸馏与提纯。"},{t="研制新瘟疫",b="法拉尼尔唯一的执念就是实现黑暗女王的指令：研制出“新瘟疫”。为了酿造出足以摧毁阿尔萨斯和他那盲目的天灾军团的传染病，法拉尼尔统筹了大量的试剂搜集工作。他派遣冒险者去焚木村找回他已故同事贝拉德药剂师的研究笔记，从剃刀沼泽的深处巢穴中获取蝙蝠粪便，并用血色修道院狂热者的器官来测试酸性胶状物的效果。"}},faq={{q="大药剂师法拉尼尔是谁？",a="法拉尼尔是皇家药剂师学会的领袖，这是一个在幽暗城为希尔瓦娜斯·风行者女士服务的炼金术组织。他监督所有关于毒素、缝合憎恶以及“新瘟疫”开发的研究。",al={"法拉尼尔是谁","法拉尼尔背景故事","药剂师领袖"}},{q="在哪里可以找到法拉尼尔？",a="他居住在药剂师区，那是位于幽暗城西侧的炼金区，周围环绕着沸腾的大锅、测试笼和他的药剂师下属。",al={"法拉尼尔位置","大药剂师法拉尼尔在哪","寻找法拉尼尔"}},{q="法拉尼尔死前的背景是什么？",a="生前，法拉尼尔是一位著名的炼金术师和医生，曾与达拉然的法师们一同研究。在死于瘟疫并将其好奇心扭曲为致命毒素之前，他曾花费毕生精力发明治疗疾病的药物。",al={"法拉尼尔历史","法拉尼尔在达拉然吗","法拉尼尔生前"}},{q="皇家药剂师学会试图制造什么？",a="在希尔瓦娜斯女王的指示下，该学会正在制造一种“新瘟疫”。他们的目标是制造一种足以摧毁天灾军团并向巫妖王复仇的强力武器，同时保护被遗忘者免受凡人敌人的侵害。",al={"什么是新瘟疫","药剂师在制造什么","药剂师目标"}},{q="为什么法拉尼尔要派遣冒险者去焚木村？",a="他寻找他前同事贝拉德药剂师的研究日志，贝拉德在焚木村因发疯而屈服于狼人诅咒。贝拉德的现场笔记中包含了提炼他们的瘟疫实验所必需的关键毒剂数据。",al={"死亡配方任务法拉尼尔","为什么去焚木村","贝拉德药剂师的日志"}},{q="为什么他需要来自剃刀沼泽和血色修道院的试剂？",a="法拉尼尔需要测试相互对立的挥发性化合物是如何相互作用的。他将从剃刀沼泽野猪人巢穴收集的粪便，与新鲜获取的血色十字军狂热者的心脏结合起来，以测试酸性胶状物和生物污染的效果。",al={"法拉尼尔剃刀沼泽粪便","狂热者的心脏","血色修道院心脏"}}},fx={["90cc21c1"]={q="大药剂师法拉尼尔效忠哪一方？",a="法拉尼尔全心效忠希尔瓦娜斯·风行者女王和被遗忘者。作为皇家药剂师协会的大药剂师，他的研究完全服务于黑暗女王的野心，并调遣炼金师消灭敌人、确保亡灵国度存续，不计道德代价。",al={"法拉尼尔的忠诚对象","法拉尼尔效忠谁","法拉尼尔效忠希尔瓦娜斯吗"}},b168fd3d={q="大药剂师法拉尼尔为什么在幽暗城？",a="法拉尼尔主管幽暗城的炼金区。这里是一座规模庞大的实验室，遍布沸腾的大锅和有毒烟雾；他在此领导皇家药剂师协会的研究，测试危险的药剂，并协调为被遗忘者合成强力的新型瘟疫和憎恶。",al={"法拉尼尔为什么在这里","法拉尼尔与炼金区","法拉尼尔为什么在幽暗城"}},["79d7ca05"]={q="大药剂师法拉尼尔隶属于谁？",a="法拉尼尔直接效忠希尔瓦娜斯女王，并领导皇家药剂师协会，指挥下属研究员，例如银松森林的药剂师伦弗利尔和希尔斯布莱德丘陵的药剂师林度恩。他也与其他研究员保持联系，汇集前同僚药剂师贝拉德等人的研究成果。",al={"法拉尼尔的关系","谁与法拉尼尔共事","法拉尼尔的盟友"}},d3e005f3={q="大药剂师法拉尼尔为何令人畏惧？",a="法拉尼尔曾是达拉然一位声誉良好的学者，成为亡灵后，他的才智变成了深不见底的残酷。他臭名昭著，是被遗忘者最致命的毒药和瘟疫背后的黑暗策划者；他毫无悔意地用活人和死人测试骇人的新药剂。",al={"法拉尼尔为何出名","法拉尼尔的名声","法拉尼尔危险吗"}}},fp="26,293,24.557.0,30.456.0,23.496.1,34.230.0,28.184.0,46.234.0,54.242.0,55.235.0,72.238.0"}
P.entries["npc:master-apothecary-lydon"] = {n="药剂师林度恩",s="药剂师林度恩是一位驻扎在塔伦米尔的皇家药剂师学会的病态研究员。他长期抑郁且感到极度无聊，只有在提炼致命药剂和观察活物受苦时才会感到快乐。他带头研究强力的新型毒素，旨在为被遗忘者稳固希尔斯布莱德，并推进Sylvanas Windrunner的The New Plague。",h="药剂师林度恩是一位驻扎在塔伦米尔的皇家药剂师学会的病态研究员。他长期抑郁且感到极度无聊，只有在提炼致命药剂和观察活物受苦时才会感到快乐。他带头研究强力的新型毒素，旨在为被遗忘者稳固希尔斯布莱德，并推进Sylvanas...",kw={"药剂师","苦痛药剂","法拉尼尔","希尔斯布莱德","林度恩","皇家药剂师学会","塔伦米尔","乌比"},ang={["faction:Alliance"]="对南海镇的人类来说，林度恩是一个可怕的怪物，他酿造致命疾病，并肆意在被俘的希尔斯布莱德农夫和野生动物身上进行测试。",["profession:Herbalism"]="林度恩的工作室里堆满了试剂、坩埚和腐烂的植物，展示了药剂师学会是如何将传统的采集技艺武器化的。",["race:Undead"]="林度恩体现了皇家药剂师学会的唯一使命：开发The New Plague，为被遗忘者确保未来并铲除生者。"},sec={{t="塔伦米尔的隐士",b="药剂师林度恩驻扎在塔伦米尔一座改建成实验室的教堂内，他代表了皇家药剂师学会那冷酷且精于算计的信条。他深受一种深沉、倦怠的忧郁症折磨，对希尔斯布莱德丘陵盛开的鲜花和清新的空气感到厌恶。唯一能让他摆脱永恒阴霾的消遣是死亡技艺。当无人看管时，他会通过不断毒杀、解剖并复活他那不幸的宠物青蛙乌比来打发时间，等待新的试剂送达。"},{t="苦痛药剂",b="与幽暗城的大药剂师法拉尼尔协同工作，林度恩在希尔斯布莱德各地进行了大量的实地实验。他的工作从受难药剂升级到了剧毒的苦痛药剂。为了验证它们的效力，林度恩派遣冒险者在当地的目标身上测试这些药剂，目标范围从无辜的野生动物和家畜，到被俘虏的人类农夫。他将完全忠诚于黑暗女王，渴望着终有一天他们完成的The New Plague能够净化这个活人的世界。"},{t="洛阿之毒",b="除了标准的药剂外，林度恩的求知欲还延伸到了深奥的毒药上。当神秘的毒液瓶出现在该地区时，他会咨询像加德林大师这样的巨魔神秘学家来追踪它们的来源。这项调查揭示了一条直接指向辛特兰蜘蛛女神沙德拉的线索。一旦获得，这种原始毒液就会直接运往幽暗城的Apothecarium，以进一步推进被遗忘者的瘟疫计划。"}},faq={{q="药剂师林度恩是谁？",a="他是皇家药剂师学会的一名炼金术师，在希尔斯布莱德丘陵的塔伦米尔开展工作。他代表Sylvanas Windrunner女士负责监督各种实验性瘟疫和毒素的开发。",al={"林度恩是谁","林度恩 塔伦米尔","药剂师林度恩背景故事"}},{q="为什么林度恩如此抑郁？",a="林度恩深受深沉的忧郁症折磨，并觉得希尔斯布莱德的自然美景和清新空气令人反感。唯一能让他振奋精神的就是残酷的实验、活物的苦难，以及炼金防腐液的气味。",al={"他为什么悲伤","林度恩抑郁症","为什么林度恩阴郁"}},{q="乌比是谁？",a="乌比是林度恩养在工作室里的一只青蛙，他嘲讽地将其称为自己的助手。实际上，他是通过不断毒杀、杀死并复活这只无助的两栖动物来排遣他极度的无聊。",al={"林度恩的青蛙","那只青蛙是谁","乌比背景故事"}},{q="什么是苦痛药剂？",a="这是一种强效的实验性毒药，林度恩用泥头花酿制而成，并用大药剂师法拉尼尔的腐败胶体进行提炼，再用强效巨魔之血药剂、刺鳍鳞片和撕裂的鱼鳍眼进行激活。随后，他将这种毒药混入从丹加洛克的矮人那里偷来的一桶烈酒中，并在希尔斯布莱德的被俘农夫身上进行测试。",al={"苦痛药剂任务","什么是苦痛药剂","林度恩的药剂"}},{q="林度恩是如何成为被遗忘者的？",a="没有记录说明林度恩本人是如何死亡或复生的。像其他被遗忘者一样，他在Sylvanas Windrunner的领导下摆脱了巫妖王的控制，现在他将自己的亡灵生命奉献给了黑暗女王和她的The New Plague。",al={"林度恩的过去","林度恩曾经是人类吗","林度恩 第三次战争"}},{q="林度恩向幽暗城运送什么？",a="在发现辛特兰的古代毒液容器并协调促成巨魔蜘蛛神沙德拉的倒台后，林度恩收集了她浓缩的神圣毒液，并将其直接运送给大药剂师法拉尼尔，以支持学会的瘟疫研究。",al={"林度恩 幽暗城 毒液","沙德拉毒液任务"}}},fx={["4ad88718"]={q="药剂师林度恩效忠哪一方？",a="药剂师林度恩坚定效忠希尔瓦娜斯女王、被遗忘者和部落。他是皇家药剂师协会的高级研究员，直接接受幽暗城大药剂师法拉尼尔的指导。他调制的一切药剂，都服务于希尔瓦娜斯为亡灵巩固疆土的宏图。",al={"林度恩的阵营","林度恩效忠谁","林度恩是被遗忘者吗"}},["64f2c0db"]={q="药剂师林度恩想要什么？",a="林度恩一心为黑暗女王研制并完善新瘟疫。他在各地搜寻强效毒素、掠食者的血液和致命毒液，以改良自己的药剂，包括受难药剂和痛苦药剂，意图给生者带来苦难与死亡。",al={"林度恩想做什么","林度恩的目标","林度恩为什么要毒药"}},["26e1a5a5"]={q="药剂师林度恩为什么在塔伦米尔？",a="林度恩驻扎在塔伦米尔的药剂实验室，收集当地原料，并在靠近敌境的地方测试致命的炼金配方。希尔斯布莱德丘陵为针对当地野生动物、敌对的矮人袭击者以及不远处人类城镇南海镇的实验提供了理想场所。",al={"林度恩为什么在希尔斯布莱德","林度恩在塔伦米尔的职责","药剂师林度恩为什么在这里"}},["19c08bcd"]={q="药剂师林度恩隶属于谁？",a="林度恩直接听命于大药剂师法拉尼尔和皇家药剂师协会。他与艾泽拉斯各地的同僚合作，帮助雷霆崖的药剂师扎玛调制毒剂，以应对部落在石爪山脉遇到的麻烦，并与驻扎在洛丹伦各地的其他被遗忘者药剂师协调研究。",al={"林度恩的关系","谁与林度恩共事","林度恩的盟友"}}},fp="16,354,26.508.0,20.517.1,16.465.1,24.213.0,26.245.0,12.207.0,28.337.1,30.208.0,38.260.1"}
P.entries["npc:master-gadrin"] = {n="加德林大师",s="加德林大师是一位年迈的丛林巨魔，也是暗矛部族一位德高望重的巫医，目前居住在森金村。他曾与叛变的巫医扎拉赞一起训练过部族的牧师和法师，如今他负责协调各种力量，以帮助流离失所的族人，并打破笼罩在他们被掠夺的家园——回音群岛上的黑暗诅咒。",h="加德林大师是一位年迈的丛林巨魔，也是暗矛部族一位德高望重的巫医，目前居住在森金村。他曾与叛变的巫医扎拉赞一起训练过部族的牧师和法师，如今他负责协调各种力量，以帮助流离失所的族人，并打破笼罩在他们被掠夺的家园——回音群岛上...",kw={"暗矛","杜隆塔尔","回音群岛","加德林","加德林大师","明希纳","森金村","沃金","巫医","扎拉赞"},ang={["class:Mage"]="第三次战争后，加德林开创性地指导暗矛巨魔学习奥术，证明了巨魔魔法可以远远超出原始仪式巫术的范畴。",["class:Priest"]="作为指导暗矛牧师与灵魂和洛阿神灵沟通的长者，加德林体现了丛林巨魔的暗影和信仰传统。",["faction:Horde"]="加德林大师是沃金最信任的顾问之一，他时刻注视着杜隆塔尔的海岸，并在黑暗邪教威胁杜隆塔尔这个新兴国家时向剃刀岭发出警告。",["race:Troll"]="对于暗矛巨魔来说，加德林大师是你与祖居地和森金传统之间的活生生的联系。他塑造了你们部族数代人的精神领导层，并对回音群岛的悲剧怀有一种慈父般的哀伤。"},sec={{t="暗矛的导师",b="早在暗矛部族抵达卡利姆多之前，加德林大师就已在南海的故土担任部族巫医，指导过数代暗矛巨魔的神秘训练。"},{t="扎拉赞的背叛",b="当暗矛部族与部落一同在回音群岛定居时，加德林与年轻的巫医扎拉赞共同领导了部族牧师和法师的神秘训练。可悲的是，扎拉赞沉迷于他试图掌握的黑暗巫毒力量，最终陷入了疯狂。这位叛变的修行者奴役了族人的心智，并将沃金和未受腐化的暗矛族人赶到了杜隆塔尔的内陆。现在，驻扎在森金村的加德林背负着看着昔日同伴变成暴君怪物的私人悲痛，不知疲倦地工作，希望能让死去的族人安息，并终结扎拉赞的统治。"},{t="古老知识的守护者",b="除了回音群岛的危机外，加德林还是部落中最伟大的巨魔灵学和洛阿神灵知识权威之一。学者、萨满，甚至皇家药剂师学会都会寻求他在奥术和炼金术奥秘方面的见解。当火刃氏族等奇怪威胁侵扰杜隆塔尔，或者远方的研究人员需要古老的仪式——例如破译祖尔法拉克中召唤蜘蛛洛阿沙德拉的古代石板——时，正是加德林拥有制作必要束缚法术的知识。"}},faq={{q="加德林大师是谁？",a="加德林大师是一位巫医，也是暗矛巨魔的一位年长精神领袖。他位于杜隆塔尔海岸的森金村，是沃金酋长的高级顾问。",al={"加德林大师背景","加德林是谁","加德林npc"}},{q="加德林与扎拉赞有什么过往？",a="在回音群岛，加德林和年轻的巫医扎拉赞曾共同领导暗矛部族牧师和法师的神秘训练，但后来加德林惊恐地看着扎拉赞堕入黑暗魔法、陷入疯狂，并将暗矛族人赶出了他们的岛屿家园。",al={"加德林与扎拉赞","加德林如何认识扎拉赞","扎拉赞导师"}},{q="为什么加德林要留在森金村？",a="当扎拉赞的诅咒将暗矛族人赶出回音群岛时，幸存者们在杜隆塔尔南海岸建立了森金村作为避难所。加德林留在村子里是为了安抚难民、追踪当地的威胁，并指挥对扎拉赞势力的打击。",al={"为什么加德林在这里","加德林在森金村做什么"}},{q="明希纳是谁？",a="明希纳是加德林大师的兄弟。他在回音群岛的动乱中丧生，他那不安的灵魂开始在梦中呼唤加德林。加德林请求值得信任的冒险者找回他兄弟的头骨，以便他的灵魂能够最终获得安宁。",al={"明希纳兄弟","明希纳头骨任务背景","明希纳是谁"}},{q="加德林是否协助对抗火刃氏族邪教？",a="是的。在收到祖雷萨关于火刃氏族渗透进试炼谷的消息后，加德林便开始监视该邪教在森金村附近的活动。看到这对杜隆塔尔构成了更广泛的威胁，他将新兵派往北方，向剃刀岭的奥戈尼尔·魂痕报告。",al={"火刃氏族杜隆塔尔加德林","奥戈尼尔·魂痕加德林"}},{q="加德林对洛阿神灵沙德拉了解多少？",a="加德林是一位精通古代巨魔神学的专家。当被遗忘者药剂师林度恩寻求一种辛特兰枯木巨魔使用的强力毒液时，加德林将其认定为蜘蛛洛阿沙德拉的恩赐，并指引冒险者前往祖尔法拉克阅读刻有她真名的石板，他需要用这些名字来写出一道召唤咒语。",al={"沙德拉蜘蛛洛阿加德林","加德林蜘蛛之神"}}},fx={["48c543c3"]={q="加德林大师效忠哪一方？",a="加德林大师效忠暗矛部族和部落。在萨尔从海巫手中救下他的族人后，他从暗矛群岛远道而来，成为一位德高望重的长老、神秘学导师，也是酋长沃金信赖的顾问。",al={"加德林的阵营","加德林是部落成员吗","加德林效忠谁"}},d3faca51={q="加德林大师想要什么？",a="加德林大师希望杀死背叛族人的巫医扎拉赞，并解放回音群岛。他想让受诅咒的族人摆脱扎拉赞的精神控制，取回已故兄弟明希纳的颅骨，让灵魂得以安息，并保护森金村免受杜隆塔尔各处新兴威胁的侵扰。",al={"加德林想要什么","加德林的目标","加德林大师的动机"}}},fp="13,354,23.211.0,24.606.0,22.522.0,21.190.0,39.259.0,41.267.0,16.245.0,45.268.0,43.327.0"}
P.entries["npc:master-vornal"] = {n="沃纳尔大师",s="沃纳尔大师是一位上了年纪的暗矛巨魔，居住在杜隆塔尔南海岸的森金村。尽管年事已高，而且对炼金药剂有着渊博的知识，但他固执地拒绝收任何学徒。",h="沃纳尔大师是一位上了年纪的暗矛巨魔，居住在杜隆塔尔南海岸的森金村。尽管年事已高，而且对炼金药剂有着渊博的知识，但他固执地拒绝收任何学徒。",kw={"烈性之魂","暗矛","杜隆塔尔","沃纳尔大师","森金村","巨魔","沃纳尔"},ang={["profession:Herbalism"]="那些精通原始植物的人会认同沃纳尔对稀有催化剂和溶剂所需的苛刻天然试剂的敏锐眼光。",["race:Troll"]="对于暗矛巨魔来说，沃纳尔大师代表了那些在部族逃离岛屿家园后，帮助建立了森金村的固执的长者工匠。"},sec={{t="森金村顽固的酿酒师",b="沃纳尔大师是森金村的常客，以他为暗矛巨魔同胞酿造强效药水和烈酒而闻名。虽然岁月不饶人，但他依然极其独立，固执地拒绝教导任何学徒，宁愿亲手调制他的疗愈药剂和不稳定的混合物。"},{t="烈性之魂",b="沃纳尔偶尔会派遣年轻的冒险者从周边地区收集严苛或稀奇的原料，例如制造溶剂和混合物所需的强力材料。虽然他乐于奖赏那些帮助他的人，但他却严守自己的配方和精确方法，将他的手艺视为一项独自进行的追求。"}},faq={{q="沃纳尔大师是谁？",a="沃纳尔大师是一位居住在森金村的年迈暗矛丛林巨魔。他为部落酿造强效的烈酒和药水，但坚持独自工作，不收学徒。",al={"沃纳尔大师","沃纳尔","森金村沃纳尔大师","沃纳尔是谁"}},{q="我能在哪里找到沃纳尔大师？",a="他待在森金村的棚屋之间，位于杜隆塔尔南海岸，回音群岛以北。",al={"沃纳尔位置","沃纳尔大师在哪里","找到沃纳尔大师"}},{q="为什么沃纳尔大师拒绝收学徒？",a="沃纳尔说，还从来没有哪个巨魔或兽人有足够的资格。尽管他的视力在衰退，并且越来越依赖炼金术，但他宁愿独自工作，也不愿教导不合格的人。",al={"沃纳尔学徒","为什么没有学徒","沃纳尔的学生"}},{q="他为冒险者提供什么样的任务？",a="沃纳尔派遣旅行者去该地区各地收集他制造溶剂混合物所需的原始成分，他依靠旅行者获取材料，同时将酿造过程严格保密。",al={"沃纳尔大师的任务","烈性之魂","沃纳尔任务"}}},fx={e0bd334a={q="沃纳尔大师效忠哪一方？",a="沃纳尔大师效忠暗矛部族和部落。他在森金村安家，以自己的技艺和经验帮助守护这座年轻的定居点，使其免受周边险境侵扰。",al={"沃纳尔的忠诚对象","沃纳尔大师效忠谁","沃纳尔大师的阵营"}},["27223be8"]={q="沃纳尔大师为什么在森金村？",a="沃纳尔大师住在杜隆塔尔海岸，帮助族人在流亡之地开创新生活。他在森金村的家中从事自己的行当，并安排旅人收集他所需的强效原料。",al={"沃纳尔大师为什么在这里","沃纳尔为什么在森金村","沃纳尔在杜隆塔尔的职责"}},faf3afd9={q="沃纳尔大师想要什么？",a="沃纳尔大师虽已年迈，却更愿意独自工作，不肯让学徒成为自己的负担。因此，他会请有本事的冒险者替他跑腿，在杜隆塔尔各处收集稀有的蒸馏液和溶剂。",al={"沃纳尔想要什么","沃纳尔大师的目标","沃纳尔在找什么"}}},fp="13,247,30.334.0,16.319.0,21.176.0,31.134.0,50.182.0,37.181.0"}
P.entries["npc:mastok-wrilehiss"] = {n="马斯托克·维尔西斯",s="马斯托克·维尔西斯是一名驻扎在灰谷东部碎木岗哨的兽人军官。作为部落在这一争议森林区域的重要防御协调员，他指挥侦察兵和勇士保卫周边边境，并应对腐蚀性的元素威胁。在暗夜精灵不断的敌意下，他的存在对于维持部落那摇摇欲坠的立足点至关重要。",h="马斯托克·维尔西斯是一名驻扎在灰谷东部碎木岗哨的兽人军官。作为部落在这一争议森林区域的重要防御协调员，他指挥侦察兵和勇士保卫周边边境，并应对腐蚀性的元素威胁。在暗夜精灵不断的敌意下，他的存在对于维持部落那摇摇欲坠的立足点...",kw={"灰谷","大地之环","马斯托克","兽人","碎木","石爪","维尔西斯"},ang={["class:Shaman"]="马斯托克对森林中受腐蚀元素生物的担忧，通常会指引冒险者前往佐拉姆海岸寻求大地之环的指导。",["faction:Alliance"]="马斯托克·维尔西斯代表了兽人在灰谷的根深蒂固的军事存在，守卫着碎木岗哨这一坚固定居点，抵御暗夜精灵哨兵的进攻。",["faction:Horde"]="对于那些为了维持在灰谷前线立足点而奋战的部落勇士来说，马斯托克是一位关键的指挥官，可以引导你完成该地区的关键任务。"},sec={{t="远古森林中的壁垒",b="碎木岗哨坐落在灰谷高耸树冠的阴影深处，完全被敌对的暗夜精灵领地所包围。马斯托克·维尔西斯是该岗哨的核心守卫之一，负责监视补给路线和森林动态。这个位置非常危险；任何软弱的迹象都会招致哨兵的迅速打击，在她们眼中，这个定居点是一种掠夺性的入侵。"},{t="协调前线",b="在监狱里的有利位置上，马斯托克积极指派路过的冒险者执行关键的战略任务。他密切注视着通往石爪山脉等邻近领地的边境，并派遣侦察兵前往佐拉姆海岸，向大地之环的耶努萨克雷等萨满祭司咨询。他的职责连接了军事防御与监测那些困扰当地元素生物的奇异腐蚀力量。"}},faq={{q="马斯托克·维尔西斯是谁？",a="马斯托克·维尔西斯是一名驻扎在灰谷碎木岗哨的精英兽人。他担任军官和任务发布者，负责守卫该前哨站以抵御暗夜精灵的入侵，并调查附近的区域性威胁。",al={"马斯托克是谁","马斯托克·维尔西斯的作用","这个兽人是谁"}},{q="马斯托克·维尔西斯在哪里？",a="他位于碎木岗哨内，这是一个位于灰谷中东部，沿着主森林道路建立的坚固部落前哨站。",al={"马斯托克位置","马斯托克·维尔西斯在哪里","马斯托克地图"}},{q="马斯托克会给冒险者分配什么任务？",a="马斯托克指派部落冒险者执行战略任务，包括调查森林中受腐蚀的元素威胁、保卫通往石爪山脉的关口，以及派遣使者前往大地之环的耶努萨克雷处。",al={"马斯托克任务","马斯托克发布的任务"}},{q="为什么碎木岗哨一直处于高压之下？",a="该前哨站是部落在灰谷的一个核心伐木枢纽和据点。当地的暗夜精灵认为兽人的存在及其伐木行为严重亵渎了这片神圣的土地，因此导致了连绵不断的冲突。",al={"为什么暗夜精灵要攻击碎木岗哨","碎木岗哨冲突"}},{q="为什么马斯托克要派旅行者去找耶努萨克雷？",a="包括佐拉姆海岸的耶努萨克雷在内的大地之环萨满祭司，致力于研究并治愈困扰灰谷的元素不稳定现象。马斯托克将前线战士与他们的专业灵性知识联系起来，以处理受污染的水元素和奇异的扰动。",al={"为什么联系大地之环","马斯托克和耶努萨克雷"}},{q="马斯托克·维尔西斯对联盟玩家敌对吗？",a="是的。马斯托克是部落的忠诚成员，也是碎木岗哨的精英守卫，这意味着如果联盟玩家靠近该营地，他会立即发动攻击。",al={"联盟能和马斯托克交谈吗","马斯托克可以被击杀吗"}}},fx={["414a3ea9"]={q="马斯托克·维尔西斯为什么在灰谷？",a="马斯托克·维尔西斯驻扎在碎木岗哨，帮助守住部落在灰谷这片争夺激烈的森林中的据点。作为战歌部队中经验丰富的守卫者，他负责监督当地防务、追查影响周边荒野的异动，并招募有能力的旅人应对腐化元素的威胁和邻近暗夜精灵的敌意。",al={"马斯托克为什么在这里","马斯托克·维尔西斯与碎木岗哨","马斯托克为什么在碎木岗哨"}}},fp="16,381,30.377.0,22.436.0,24.219.0,36.129.0,45.216.0,49.238.0,49.251.0,48.172.0"}
P.entries["npc:mathias-shaw"] = {n="Mathias Shaw",s="马迪亚斯·肖尔大师是暴风城王国的秘密情报机构——军情七处的领袖。他在Old Town的阴影中运作，指挥间谍和侦察兵，以保护王国免受内部阴谋和外部恐怖的侵袭。",h="马迪亚斯·肖尔大师是暴风城王国的秘密情报机构——军情七处的领袖。他在Old Town的阴影中运作，指挥间谍和侦察兵，以保护王国免受内部阴谋和外部恐怖的侵袭。",kw={"刺客","凋零者","kearnen","mathias shaw","old town","军情七处","间谍大师","暴风城","范克里夫"},ang={["class:Rogue"]="马迪亚斯·肖尔代表了人类潜行者技艺的最高水平。联盟潜行者经常被派往他那里接受高级战术任务和特殊毒药的训练。",["faction:Alliance"]="作为王国的间谍大师，肖尔是防范颠覆活动的第一道防线，为伯瓦尔·弗塔根公爵和年幼的国王安度因收集重要的军事情报。",["race:Human"]="肖尔针对迪菲亚潜行者的战争，反映了暴风城王国在重建后内部更广泛、更苦涩的分裂。"},sec={{t="军情七处大师",b="马迪亚斯·肖尔是暴风城首席间谍大师兼刺客。从隐藏在Old Town兵营后的军情七处秘密总部出发，肖尔协调着一张覆盖东部王国及更远地区的秘密网络。他务实、精于算计，并且对乌瑞恩家族忠心耿耿。他的信条是：暴风城的安全不仅取决于闪亮的盔甲和宫廷卫队，更取决于无形的匕首和被窃取的密函。"},{t="范克里夫之影",b="肖尔与反叛组织迪菲亚潜行者的领袖艾德温·范克里夫有着一段非常私人的过往。两人曾是童年玩伴，肖尔曾亲自传授范克里夫潜行与刺杀的艺术，并曾希望这位天赋异禀的石匠能将才华用于为王国效力。然而，当石匠工会在暴风城重建后被驱逐时，范克里夫将这些致命的课程转向了王室。如今，肖尔指挥着旨在瓦解他这位老友在西部荒野发动的叛乱的监视与渗透行动。"},{t="王国各地的耳目",b="尽管国内的叛乱让西部荒野和艾尔文森林陷入动荡，肖尔的注意力却始终被外部的致命未知威胁所牵引。当有关被遗忘者在东瘟疫之地进行诡异行动的报告传到他耳中时，他派遣了五名最优秀的特工前去调查。只有一人活着回来，在睡梦中死去前，他还在惊恐地喃喃自语着“纳萨诺斯”和“凋零者”。肖尔依赖值得信赖的独立勇士前往那些他的侦察兵消失的地方，试图刺破聚集在王国边境的阴霾。"}},faq={{q="马迪亚斯·肖尔是谁？",a="马迪亚斯·肖尔是军情七处的领袖，这是暴风城的情报机构兼刺客行会。他在Old Town办公，在王座的授权下协调王国的间谍活动和秘密防御。",al={"谁是肖尔","军情七处领袖","马迪亚斯·肖尔背景故事","暴风城间谍大师"}},{q="马迪亚斯·肖尔在哪里？",a="他在暴风城的Old Town区，位于军事兵营后方的军情七处总部内。",al={"肖尔位置","马迪亚斯·肖尔在哪里","寻找马迪亚斯·肖尔"}},{q="他与艾德温·范克里夫有什么关系？",a="那段故事是西部荒野的秘密之一。肖尔为格里安·斯托曼准备了一份报告，其中记录了军情七处所知的关于石匠工会的一切。那些追随迪菲亚潜行者直至终局的人，将会了解到这两人的关系有多么紧密。",al={"肖尔与范克里夫","范克里夫的朋友","马迪亚斯与艾德温"}},{q="军情七处代表什么？",a="军情七处是暴风城最重要的情报组织，专门从事监视、侦察、间谍活动和秘密暗杀，以保护王国和联盟的利益。",al={"什么是军情七处","军情七处含义","暴风城情报机构"}},{q="为什么马迪亚斯·肖尔关注西部荒野？",a="西部荒野是迪菲亚潜行者的大本营。肖尔在该地区派驻了活跃的特工，以监视叛军活动并破坏他们针对暴风城的阴谋。",al={"肖尔西部荒野","军情七处西部荒野","klaven's tower"}},{q="肖尔派往瘟疫之地的特工发生了什么？",a="肖尔派遣了五名特工去侦察东瘟疫之地可疑的被遗忘者动向。有四人再也没回来，唯一的幸存者在几天后死于睡梦之中，死前还在喃喃自语着“纳萨诺斯”和“凋零者”。",al={"肖尔瘟疫之地任务","肖尔的五名侦察兵","玛瑞斯农场侦察兵"}}},fp="12,190,14.348.0,18.407.1,24.422.0,20.176.0,32.112.0,41.234.0,25.187.0,43.166.0,57.217.0"}
P.entries["npc:mathredis-firestar"] = {n="玛瑟迪斯·火芒",s="玛瑟迪斯·火芒是一位古怪的血精灵法师，居住在燃烧平原的烈焰峰。他利用已故导师的奥术研究成果制作强大的附魔，即次级奥术，并借此通过吸收绑定过程中释放的残留能量来缓解他对魔法的成瘾。",h="玛瑟迪斯·火芒是一位古怪的血精灵法师，居住在燃烧平原的烈焰峰。他利用已故导师的奥术研究成果制作强大的附魔，即次级奥术，并借此通过吸收绑定过程中释放的残留能量来缓解他对魔法的成瘾。",kw={"奥术","燃烧平原","追梦者","火芒","烈焰峰","圣契","玛瑟迪斯","泰尔米斯"},ang={["class:Mage"]="法师们会认出玛瑟迪斯的奥术合成是一种绝望而又极不稳定的方法，旨在从物品绑定的过程中汲取原始的魔法养分。"},sec={{t="导师的遗产与魔法成瘾",b="玛瑟迪斯·火芒从他的导师泰尔米斯·追梦者那里学会了制作奥术——即浓缩的奥术强化宝珠——的技术。泰尔米斯在试图从辛德拉手中夺取魔法秘密时，在古老的厄运之槌遗迹中惨遭不幸。虽然这些魔法绑定是由泰尔米斯发明的，但玛瑟迪斯尚不具备制作最高级奥术的大师级技艺，因此他专注于次级奥术。对玛瑟迪斯来说，这项工作远不止是学术研究：就像太阳之井陷落后所有的血精灵一样，他饱受奥术饥渴的折磨。将材料绑定到古老的圣契上会释放出狂暴的魔法能量，玛瑟迪斯正是通过吸收这些能量来维持自身。"},{t="奥术的技艺",b="冒险者如果能带给玛瑟迪斯合适的圣契——例如专注圣契、防护圣契、贪婪圣契、坚韧圣契或体质圣契——并提供稀有试剂，他就会很乐意传授他的技艺。这个过程将不稳定的魔法试剂直接绑定到书籍上，将其精华浓缩成可以永久附魔在头部或腿部护甲上的奥术。只要冒险者提供组件，玛瑟迪斯既能得到报酬，又能获得他迫切渴望的周围奥术能量的滋养。"}},faq={{q="玛瑟迪斯·火芒是谁？",a="玛瑟迪斯·火芒是一位驻扎在燃烧平原烈焰峰中立前哨站的血精灵法师。他是一位奥术师，能够锻造用于护甲附魔的次级奥术。",al={"玛瑟迪斯背景故事","玛瑟迪斯·火芒是谁","火芒 血精灵"}},{q="玛瑟迪斯为什么要制作奥术？",a="在太阳之井被摧毁后，血精灵们遭受了严重的魔法戒断反应。玛瑟迪斯通过吸收在制作和绑定奥术过程中释放出的原始残留魔法能量，来缓解他的种族性成瘾。",al={"为什么要制作奥术","玛瑟迪斯的动机","为什么要使用圣契"}},{q="泰尔米斯·追梦者是谁？",a="泰尔米斯·追梦者是玛瑟迪斯已故的导师，也是奥术的原始发明者。泰尔米斯曾冒险进入厄运之槌的废墟，试图从辛德拉那里获取知识，但在他完全传授自己的专业知识之前，他就在那里被杀害了。",al={"泰尔米斯","玛瑟迪斯的导师","他的导师是谁"}},{q="玛瑟迪斯能制作哪些奥术？",a="玛瑟迪斯可以锻造体质、防护、专注、坚韧和贪婪的次级奥术。最强大的奥术只有他的导师泰尔米斯知晓，对于玛瑟迪斯来说依然遥不可及。",al={"哪些奥术","次级奥术","圣契列表"}}},fp="18,330,37.709.0,22.497.0,26.181.0,35.233.0,28.245.0,42.200.0"}
P.entries["npc:mathrengyl-bearwalker"] = {n="玛斯雷·驭熊者",s="玛斯雷·驭熊者是一位德鲁伊训练师大师，也是塞纳里奥议会中受人尊敬的长者，居住在达纳苏斯的塞纳里奥区。他曾担任大德鲁伊范达尔·鹿盔的直接助手，引导年轻的联盟德鲁伊进行精神试炼、变形仪式，并履行他们在卡利姆多的职责。",h="玛斯雷·驭熊者是一位德鲁伊训练师大师，也是塞纳里奥议会中受人尊敬的长者，居住在达纳苏斯的塞纳里奥区。他曾担任大德鲁伊范达尔·鹿盔的直接助手，引导年轻的联盟德鲁伊进行精神试炼、变形仪式，并履行他们在卡利姆多的职责。",kw={"水栖形态","熊形态","驭熊者","塞纳里奥议会","塞纳里奥区","达纳苏斯","利爪德鲁伊","德鲁伊训练师","范达尔·鹿盔","玛斯雷·驭熊者","晨露草","泰达希尔"},ang={["class:Druid"]="对于联盟德鲁伊来说，玛斯雷是一位至关重要的导师，他连接了达纳苏斯和月光林地，解锁了熊形态、水栖形态以及针对致命毒药的草药疗法的秘密。",["faction:Alliance"]="玛斯雷代表了塞纳里奥议会在达纳苏斯稳健、传统的领导地位，与范达尔·鹿盔咄咄逼人的姿态形成了温和的对比。",["race:NightElf"]="作为卡多雷德鲁伊教派的典范，玛斯雷在第三次战争之后和泰达希尔的发展过程中，体现了对自然和平衡的奉献。"},sec={{t="塞纳里奥区的导师",b="玛斯雷·驭熊者端坐在达纳苏斯葱郁的塞纳里奥区中，是泰达希尔最受人尊敬且行事稳健的德鲁伊之一。他是初出茅庐的联盟德鲁伊的主要向导，监督他们与月光林地的沟通，并测试他们是否准备好掌握原始的动物形态。玛斯雷在年轻时曾经历过与伟大的熊灵那种强烈而令人困惑的沟通，因此他深知这些仪式的分量，他会亲自命令初学者在神圣的枭兽月爪面前证明自己的精神，然后才能引导他们踏上利爪德鲁伊的道路。"},{t="效力于大德鲁伊",b="玛斯雷长期担任范达尔·鹿盔的副手，管理塞纳里奥议会的日常事务，并负责为大德鲁伊的宏伟事业进行招募工作。当范达尔要求大量晨露草时，玛斯雷组织冒险者收集了这些草药，尽管他私下里对这种奇异植物所散发出的非自然气息感到不安。他还负责协调联盟对来自月光林地的召唤作出的响应，在范达尔将目光投向卡利姆多南部时，处理塞纳里奥议会微妙的政治事务。"},{t="更广阔的视角",b="虽然鹿盔以其傲慢自大和对其他种族的蔑视而闻名，但玛斯雷往往展现出更具反思精神和开明的思想。当坠落的德鲁伊穆格里斯·深河（在西瘟疫之地对抗天灾军团时牺牲）的遗物被送到达纳苏斯时，玛斯雷发现调查者是一位牛头人，这令他深受触动。在思考塞纳里奥议会的共同使命时，他静静地沉思道，牛头人也许并没有像大德鲁伊所坚持的那样，偏离塞纳留斯的教导太远。"}},faq={{q="玛斯雷·驭熊者是谁？",a="玛斯雷·驭熊者是一位经验丰富的暗夜精灵德鲁伊训练师，驻扎在达纳苏斯的塞纳里奥区。作为泰达希尔最稳健的贤者之一，他指导初学者学习变形、清除毒素，并履行塞纳里奥议会的职责。",al={"玛斯雷是谁","玛斯雷的角色","驭熊者"}},{q="他与范达尔·鹿盔的关系如何？",a="玛斯雷曾担任大德鲁伊范达尔·鹿盔的直接助手和副手。尽管顺从地处理范达尔的要求——包括收集晨露草和指派任务——但玛斯雷对范达尔的一些苛刻观点和古怪计划持有微妙的怀疑。",al={"范达尔的助手","鹿盔和玛斯雷"}},{q="玛斯雷帮助德鲁伊学习哪些形态？",a="玛斯雷在年轻的德鲁伊完成前往月光林地的精神朝圣后给予指导，监督他们与月爪的沟通以获得熊形态，并在黑海岸和西部荒野完成最终试炼以掌握水栖形态。",al={"达纳苏斯熊形态任务","达纳苏斯水栖形态任务","玛斯雷德鲁伊形态"}},{q="玛斯雷为什么要收集晨露草？",a="他协助大德鲁伊范达尔·鹿盔在泰达希尔进行持续的植物学研究，收集冒险者种植的晨露草。即便如此，玛斯雷也承认，每当他靠近这种植物时，都会感到深深的不安。",al={"晨露草任务","为何在达纳苏斯收集晨露草"}},{q="玛斯雷如何看待牛头人德鲁伊？",a="与对牛头人德鲁伊持公开怀疑态度的范达尔·鹿盔不同，玛斯雷的思想更为深刻。在审阅了一位在西瘟疫之地对抗天灾军团时牺牲的牛头人德鲁伊的事迹后，他承认牛头人可能比范达尔所承认的更接近塞纳留斯的教导。",al={"牛头人德鲁伊","玛斯雷与牛头人"}},{q="他如何处理噩梦碎片？",a="当冒险者将受污染的噩梦碎片带给菲拉·古风时，她会将他们引荐给玛斯雷，玛斯雷会带着极大的警觉检查它，感知到那威胁着翡翠梦境的蔓延的腐蚀。",al={"噩梦碎片与玛斯雷","噩梦任务"}}},fx={d00fa4f6={q="玛斯雷·驭熊者效忠于哪一方？",a="玛斯雷忠于塞纳里奥议会和达纳苏斯的暗夜精灵。作为一名驻扎在塞纳里奥区的重要猛爪德鲁伊，他既为卡多雷，也为更广泛的德鲁伊组织效力，努力维护卡利姆多的自然平衡。",al={"玛斯雷的阵营","玛斯雷为谁效力","玛斯雷属于联盟吗"}},["88f66b3d"]={q="玛斯雷·驭熊者为何在达纳苏斯？",a="玛斯雷居住在塞纳里奥区，指导年轻的暗夜精灵德鲁伊，教导他们履行神圣职责。身处泰达希尔的卡多雷社会核心地带，他帮助新晋德鲁伊学习动物形态、与荒野之灵建立联系，并应对威胁这片土地的自然灾害。",al={"玛斯雷为何在这里","玛斯雷在达纳苏斯的原因","是什么让玛斯雷来到达纳苏斯"}}},fp="21,314,30.623.0,24.546.0,21.521.0,29.262.0,47.285.0,45.226.0,40.234.0,45.289.0,41.199.0"}
P.entries["npc:maur-grimtotem"] = {n="玛尔·恐怖图腾",s="玛尔·恐怖图腾是长者老妪玛加萨·野性图腾派遣至怒焰裂谷深处的使者。他被派往奥格瑞玛地下的洞穴，试图与盘踞在那里的穴居人进行外交谈判，但这注定是一场灾难，他最终惨死在穴居人手中。如今，只有他的遗骸和个人背包留在那黑暗中，作为那次愚蠢任务的见证。",h="玛尔·恐怖图腾是长者老妪玛加萨·野性图腾派遣至怒焰裂谷深处的使者。他被派往奥格瑞玛地下的洞穴，试图与盘踞在那里的穴居人进行外交谈判，但这注定是一场灾难，他最终惨死在穴居人手中。如今，只有他的遗骸和个人背包留在那黑暗中，作...",kw={"恐怖图腾","玛加萨","玛尔","奥格弗林特","奥格瑞玛","怒焰","背包","穴居人"},ang={["faction:Horde"]="在奥格瑞玛的正下方拥有一个致命的地下洞穴已经够糟糕了；派遣单独的使者去与穴居人谈判，对部落的安全来说完全是一场灾难。",["race:Tauren"]="恐怖图腾氏族与雷霆崖的其他部落关系紧张，而玛尔在穴居人隧道中那次离奇且致命的差事，只会加深人们对玛加萨真实意图的怀疑。"},sec={{t="注定失败的外交",b="虽然部落中的大多数人认为穴居人是毫无理智、野蛮粗鲁、不值一谈的野兽，但长者老妪玛加萨·野性图腾却不这么想——或者至少她是这么宣称的。她派遣玛尔·恐怖图腾深入奥格瑞玛地下的怒焰裂谷蜿蜒洞穴，试图与这些地底生物进行和平接触。不出所料，外交失败了。玛尔很快被杀，他的尸体被丢弃在洞穴中，在穴居人首领奥格弗林特的监视下。"},{t="长者老妪的意图",b="玛尔死后，玛加萨寻找冒险者不仅仅是为了替他报仇，更是为了找回他带入深处的个人背包。玛尔是真的相信能与穴居人实现和平，还是仅仅是这位恐怖图腾女族长阴暗计划中一个可消耗的棋子，对于那些找回他遗物的人来说，这依然是个悬而未决的问题。"}},faq={{q="玛尔·恐怖图腾是谁？",a="玛尔是一名属于恐怖图腾氏族的牛头人。他听从玛加萨·野性图腾的命令，作为使者深入奥格瑞玛地下的怒焰裂谷洞穴与穴居人接触，最终在那里被杀。",al={"玛尔是谁","玛尔·恐怖图腾背景故事","玛尔在做什么"}},{q="他为什么要试图与穴居人谈判？",a="长者老妪玛加萨声称她派他是为了寻求和平并测试这些地底敌人的实力。鉴于穴居人野蛮的天性，许多人怀疑玛加萨有不可告人的动机，或者仅仅是利用玛尔来探查怒焰裂谷的深处。",al={"为什么要与穴居人和平共处","穴居人外交","为什么要与穴居人对话"}},{q="是谁杀了玛尔·恐怖图腾？",a="玛尔被居住在怒焰裂谷的穴居人部落杀害。他的尸体被怒焰穴居人的首领奥格弗林特严密看守着。",al={"玛尔是怎么死的","谁杀了他","玛尔之死"}},{q="他的遗体和遗物怎么样了？",a="玛尔的尸体被遗弃在怒焰裂谷，就在奥格弗林特附近。拉哈罗在雷霆崖委托冒险者找回玛尔丢失的背包，并将其带回长者高地交给他，以便转交给玛加萨·野性图腾。",al={"玛尔的尸体","丢失的背包","玛尔的背包"}}},fx={c7d44e51={q="玛尔·恐怖图腾曾效忠于哪一方？",a="玛尔直接听命于长老族母玛加萨·野性图腾，为恐怖图腾氏族的利益效力。恐怖图腾虽然因勉强栖身于雷霆崖的长者高地而被算作部落的一员，但玛尔效忠的对象和执行的秘密任务都只属于他的氏族。",al={"玛尔·恐怖图腾的阵营","玛尔·恐怖图腾为谁效力","玛尔·恐怖图腾属于联盟还是部落"}},["565aa8ac"]={q="玛尔·恐怖图腾想要什么？",a="玛尔试图与盘踞在奥格瑞玛地下深处裂隙中的穴居人结盟，或达成和平协议。遵照玛加萨·野性图腾的指示，他深入怒焰裂谷，希望与这些生物谈判，却不知道它们野蛮暴戾的天性让任何外交谅解都不可能实现。",al={"玛尔·恐怖图腾在做什么","玛尔·恐怖图腾的任务","玛尔·恐怖图腾的目标"}},bfc0472b={q="玛尔·恐怖图腾与谁有关联？",a="玛尔是玛加萨·野性图腾派出的使者。她是恐怖图腾氏族的族长，目前居住在雷霆崖的长者高地。玛尔在奥格瑞玛地下执行她的私人计划，使这项任务与部落的常规领导事务分开。",al={"谁派遣了玛尔·恐怖图腾","玛尔·恐怖图腾的关系","玛尔·恐怖图腾与玛加萨"}}},fp="14,352,18.458.0,27.345.1,23.209.0,40.232.0,26.149.0,41.208.0"}
P.entries["npc:maur-raincaller"] = {n="茂尔·祈雨",s="茂尔·祈雨是一位居住在莫高雷血蹄村的牛头人。他与平原的自然与精神生命息息相关，协助村中的长者，并关注着影响兽群和野生动物的地方事务。",h="茂尔·祈雨是一位居住在莫高雷血蹄村的牛头人。他与平原的自然与精神生命息息相关，协助村中的长者，并关注着影响兽群和野生动物的地方事务。",kw={"血蹄村","茂尔·祈雨","玛兹拉纳其","莫高雷","平原陆行鸟","牛头人"},ang={["class:Hunter"]="茂尔提供了一项早期的狩猎测试，派遣你前往开阔的平原猎杀狼、美洲狮、平原陆行鸟和迅猛龙，以收集他治疗玛兹拉纳其毒咬所需的材料。",["race:Tauren"]="对于刚从纳拉其营地走出来的年轻牛头人来说，茂尔提供了一个保护你们族人祖居地免受游荡掠食者和破坏性野兽骚扰的机会。"},sec={{t="血蹄村的一名居民",b="茂尔·祈雨位于石牛湖畔的血蹄村中心附近，通过处理区域生态和与野兽相关的问题为社区服务。像许多肩负祈雨者职责的人一样，他非常关注莫高雷肥沃平原上元素与野生动物的平衡。在被可怕的平原陆行鸟玛兹拉纳其咬伤并感染后，茂尔求助于能干的年轻旅行者，请求他们收集他制作药膏所需的动物部位。"}},faq={{q="茂尔·祈雨是谁？",a="茂尔·祈雨是一位居住在莫高雷翠绿草原血蹄村的牛头人。他是一名当地的任务发布者，负责派遣冒险者去管理周边地区不受管束的野生动物。",al={"茂尔·祈雨的作用","茂尔是谁","茂尔·祈雨背景故事"}},{q="我在哪里可以找到茂尔·祈雨？",a="He can be found standing outdoors among the tepees and hearth fires of Bloodhoof Village, situated just south of Thunder Bluff along the eastern bank of Lake Stonebull.",al={"茂尔·祈雨位置","茂尔在哪里","茂尔坐标"}},{q="茂尔在处理什么麻烦？",a="茂尔被他祖父故事中提到的可怕陆行鸟玛兹拉纳其咬伤，伤口已经感染。他请求冒险者带回莫高雷的狼、美洲狮、平原陆行鸟和迅猛龙的部位，以便他制作治疗药膏。",al={"茂尔·祈雨任务","玛兹拉纳其的问题","茂尔想要什么"}}},fx={fd24c378={q="茂尔·祈雨效忠于哪一方？",a="茂尔·祈雨是忠诚的血蹄氏族牛头人，也是部落的一员。他住在血蹄村，坚定地效忠于大酋长凯恩·血蹄，并致力于守护莫高雷的平原。",al={"茂尔·祈雨的阵营","茂尔·祈雨属于部落吗","茂尔为谁效力"}},["231da345"]={q="茂尔·祈雨为何在血蹄村？",a="茂尔住在血蹄村，这里是血蹄氏族在莫高雷平原上的家园。可怕的长蹄怪马兹拉纳切咬伤了他，伤口随后感染，因此他留在村中，请旅人带来制作药剂所需的野兽部件。",al={"茂尔为何在血蹄村","茂尔·祈雨在莫高雷的目的","茂尔在这里做什么"}}},fp="15,241,31.493.0,23.204.0,33.168.0,34.243.0"}
P.entries["npc:maurin-bonesplitter"] = {n="玛乌林·碎骨",s="玛乌林·碎骨是一名驻扎在凄凉之地幽灵岗哨的被遗忘者学者和施法者。他受科尔丹指派去监视恶魔邪教活动，并利用自己对古代知识的深刻理解来瓦解火刃氏族。玛乌林对这些邪教徒嗤之以鼻，认为他们是被黑暗实体玩弄于股掌之间却浑然不知的蠢货。",h="玛乌林·碎骨是一名驻扎在凄凉之地幽灵岗哨的被遗忘者学者和施法者。他受科尔丹指派去监视恶魔邪教活动，并利用自己对古代知识的深刻理解来瓦解火刃氏族。玛乌林对这些邪教徒嗤之以鼻，认为他们是被黑暗实体玩弄于股掌之间却浑然不知的蠢...",kw={"火刃氏族","腐化者","凄凉之地","被遗忘者","幽灵岗哨","科尔丹","玛乌林·碎骨"},ang={["class:Mage"]="访问幽灵岗哨的法师们可以领会玛乌林那经过深思熟虑的知识型方法，利用专门的反制手段来瓦解黑暗仪式。",["class:Warlock"]="术士们会认同玛乌林对恶魔契约的敏锐理解，尽管他的鄙夷也尖锐地提醒着人们，侍奉强大的恶魔所带来的危险。",["faction:Horde"]="玛乌林代表幽暗城为部落的西部哨岗提供专业支持，他带来了黑暗学术知识，协助牛头人盟友对抗恶魔腐蚀。",["race:Undead"]="玛乌林证明了被遗忘者的力量不仅依赖于纯粹的死灵法术，同样也依赖于狡诈的奥术研究和对敌人弱点的利用。"},sec={{t="弃儿之中的学者",b="虽然幽灵岗哨主要是凄凉之地贫瘠荒原上的牛头人和部落据点，但玛乌林·碎骨作为其中为数不多的亡灵居民而显得与众不同。玛乌林并非粗野的士兵，而是一位博学的施法者，掌握着禁忌历史和神秘力量的大量知识。他的奥术天赋和敏锐智力引起了科尔丹的注意，后者将他派往该地区，以观察日益增长的恶魔威胁并协调针对性的打击行动。"},{t="对火刃氏族的蔑视",b="玛乌林将他大部分的恶意都指向了盘踞在凄凉之地的火刃氏族邪教。他对他们鲁莽的野心感到极其厌恶，嘲笑这些邪教徒无法理解他们所借用的力量只会让他们沦为恶魔主子的奴隶。通过探知法术和仪式知识，玛乌林招募部落冒险者去系统地破坏该邪教的召唤仪式，并摧毁他们在荒芜大地上的行动。"}},faq={{q="玛乌林·碎骨是谁？",a="玛乌林·碎骨是一位居住在凄凉之地幽灵岗哨的被遗忘者术士和学者。他受科尔丹委任，利用自己对古代知识和黑暗魔法的了解来铲除在该地区活动的火刃氏族邪教。",al={"玛乌林·碎骨背景故事","玛乌林是谁","凄凉之地的玛乌林"}},{q="为什么亡灵会待在牛头人的哨岗？",a="幽灵岗哨是部落在凄凉之地的关键定居点。科尔丹之所以派驻玛乌林在那里，正是因为该哨岗提供了一个理想的立足点，可以观察并打击那些侵扰周边荒野的火刃氏族邪教徒。",al={"为什么玛乌林在幽灵岗哨","凄凉之地的亡灵"}},{q="玛乌林对火刃氏族有什么看法？",a="玛乌林对火刃氏族怀有极深的蔑视。他认为他们是可悲且无知的棋子，妄想自己掌握着真正的力量，却完全没有意识到他们只不过是恶魔主子的傀儡。",al={"玛乌林与火刃氏族","玛乌林为什么痛恨火刃氏族"}},{q="是谁派玛乌林·碎骨前往凄凉之地的？",a="玛乌林在凄凉之地的职责是由科尔丹任命的。科尔丹认可玛乌林对邪教行为和古代知识的广泛了解，因此指派他主动阻挠并最终将火刃氏族从该地区铲除。",al={"谁派了玛乌林","玛乌林与科尔丹","玛乌林的上司"}},{q="玛乌林会交给冒险者什么样的任务？",a="玛乌林要求冒险者调查火刃氏族，并收集仇恨之怒暗影猎手的头皮和纳迦神谕水晶。他利用这些试剂来破解探知结界，并定位该邪教背后的恶魔领主。",al={"玛乌林的任务","玛乌林想要什么"}},{q="玛乌林是隶属于塞纳里奥议会还是部落？",a="玛乌林是被遗忘者的忠诚成员，并为部落服务。他严格在幽灵岗哨的部落营地中行动，协助部落勇士清除荒原上的邪教活动。",al={"玛乌林是部落吗","玛乌林所属阵营"}}},fp="19,361,24.495.0,30.459.0,27.231.0,42.252.0,46.222.0,41.236.0,48.214.0,59.199.0"}
P.entries["npc:maxan-anvol"] = {n="马克萨恩·安沃尔",s="马克萨恩·安沃尔是一位矮人牧师训练师，驻扎在卡拉诺斯的雷酒酿制厂内。他笃信圣光，在丹莫罗严寒的气候中，指引初出茅庐的矮人牧师修习如何引导神圣的力量。他会考验年轻的侍僧，确保他们有资格穿上教会的长袍。",h="马克萨恩·安沃尔是一位矮人牧师训练师，驻扎在卡拉诺斯的雷酒酿制厂内。他笃信圣光，在丹莫罗严寒的气候中，指引初出茅庐的矮人牧师修习如何引导神圣的力量。他会考验年轻的侍僧，确保他们有资格穿上教会的长袍。",kw={"绝望祷言","丹莫罗","圣光之衣","圣光","卡拉诺斯","马克萨恩·安沃尔","牧师训练师","雷酒酿制厂"},ang={["class:Priest"]="马克萨恩是你早年在丹莫罗的向导，为你提供基础的神圣纪律，教授“绝望祷言”等种族祈祷，并授予你第一套正式的教会长袍。",["faction:Alliance"]="马克萨恩照料着保护丹莫罗免受石腭怪、冰霜巨魔和荒野野兽侵扰的联盟登山者和斥候，确保他们的身心时刻准备就绪。",["race:Dwarf"]="马克萨恩体现了铁炉堡务实的虔诚，他将矮人的信仰锚定在人们真正聚集的地方：就在卡拉诺斯的麦芽酒桶旁。"},sec={{t="酒吧里的牧师",b="虽然在雷酒酿制厂里看到一位受过圣职的圣光牧师可能显得有些奇怪，但这非常符合矮人的文化。卡拉诺斯是连接寒脊山谷和铁炉堡的主要枢纽，当地旅店是旅行者、登山者和侍僧们自然聚集的地方。马克萨恩在供应黑啤酒的同时，也照料着这个小镇的精神福祉，为每一位进门的客人提供祈祷和建议。"},{t="考验信仰",b="马克萨恩·安沃尔负责在新手牧师踏入广阔世界之前对他们进行考核。他会让见习者向丹莫罗的伤员施展基础的治疗祈祷，以证明他们已经掌握了这项能力。那些证明了自己的虔诚和实践能力的学徒会被授予他们第一套正式的牧师法袍，从而标志着他们在圣光教会中获得了正式认可的地位。"}},faq={{q="我在哪里可以找到马克萨恩·安沃尔？",a="马克萨恩·安沃尔位于卡拉诺斯镇的雷酒酿制厂内，这里是该镇主要的旅店和聚集地，坐落在丹莫罗中央的雪堆之中。",al={"马克萨恩·安沃尔位置","马克萨恩在哪里","卡拉诺斯牧师训练师"}},{q="马克萨恩·安沃尔教什么？",a="他是一位牧师训练师，指导新手和中级牧师学习圣光愈合、暗影控制和神圣保护的法术。他还指导矮人牧师学习像“绝望祷言”这样的种族特有祈祷。",al={"他教授什么","马克萨恩·安沃尔法术"}},{q="为什么一位圣光牧师会待在酿酒厂里？",a="在矮人社会中，生活、交流和庆祝活动都围绕着酿酒和酒馆展开。雷酒酿制厂实际上是卡拉诺斯的公共论坛、市政厅和旅行者休息站。马克萨恩待在人们需要精神慰藉的地方，这样他就能接触到平民、卫兵和过往的旅人。",al={"为什么在酿酒厂","酒吧里的牧师"}},{q="马克萨恩·安沃尔提供特殊的任务吗？",a="是的。他会用“圣光的眷顾”和“圣光之衣”等试炼来考验有抱负的牧师，派遣他们去治疗雪地里受伤的登山者。成功完成这些任务的学徒将获得他们正式的侍僧长袍。",al={"马克萨恩任务","圣光之衣"}},{q="他对非牧师玩家说什么？",a="他告诫其他冒险者永远不要背弃圣光，提醒他们神圣的恩典很可能就是他们在战斗中保住性命的关键。",al={"马克萨恩对话","马克萨恩语录"}},{q="侏儒可以向马克萨恩·安沃尔学习吗？",a="可以。侏儒也可以成为牧师，马克萨恩欢迎任何已经向圣光宣誓的联盟成员。",al={"侏儒可以找他吗","侏儒牧师训练师"}}},fx={["32034ea0"]={q="马克萨恩·安沃尔是谁？",a="马克萨恩·安沃尔是驻扎在卡拉诺斯的一名矮人圣光牧师。他在丹莫罗担任新晋信徒的导师，考验年轻侍僧的纪律和与圣光的沟通能力，然后才授予他们符合教会身份的祭服。",al={"马克萨恩是谁","马克萨恩·安沃尔的背景","卡拉诺斯的牧师训练师"}},["310c3ecc"]={q="马克萨恩·安沃尔效忠于哪一方？",a="他忠诚地支持铁炉堡王国、圣光和大联盟。他致力于守护丹莫罗当地居民，并培养新牧师，让他们在联盟各地维护信仰。",al={"马克萨恩的阵营","马克萨恩属于联盟吗","马克萨恩·安沃尔效忠于谁"}},["1141108e"]={q="马克萨恩·安沃尔想要什么？",a="马克萨恩希望弘扬对圣光的虔诚，确保新手牧师为世间的考验做好充分准备。他会考验有志学徒，确认他们配得上神圣的祭袍，并提醒所有路人永远不要放弃圣光的恩典。",al={"马克萨恩·安沃尔的目标","马克萨恩想要什么","马克萨恩·安沃尔的动机"}}},fp="11,322,19.445.0,20.399.0,29.164.0,28.218.0,49.282.0,41.243.0,32.178.0,34.120.0"}
P.entries["npc:maybell-maclure"] = {n="梅贝尔·马科伦",s="梅贝尔·马科伦是一位生活在艾尔文森林马科伦农场的年轻女子。尽管她的家族与邻近的斯通菲尔德家族之间有着长期的深仇大恨，她却暗中爱上了托米·乔·斯通菲尔德。",h="梅贝尔·马科伦是一位生活在艾尔文森林马科伦农场的年轻女子。尽管她的家族与邻近的斯通菲尔德家族之间有着长期的深仇大恨，她却暗中爱上了托米·乔·斯通菲尔德。",kw={"恋人","马科伦","梅贝尔","斯通菲尔德","托米·乔","农场"},ang={["faction:Alliance"]="对于途经艾尔文森林的联盟冒险者来说，梅贝尔的恋情提醒着人们，即便是在王国的腹地，个人烦恼和古老的怨恨依然存在。"},sec={{t="农场中的苦命鸳鸯",b="马科伦农场的生活充满了无尽的劳作，以及对邻近斯通菲尔德家族挥之不去的宿怨。夹在中间的是梅贝尔·马科伦，她深深地爱上了敌对农场的年轻继承人托米·乔·斯通菲尔德。由于警惕的亲属和古老的家族仇恨，他们被迫分离，梅贝尔渴望找到任何机会与托米·乔交流，以避开她亲人的窥探。"},{t="真爱药剂",b="由于无法公开跨越两个农场之间的界限，梅贝尔只能依靠热心的旅行者以及米莱德·斯通菲尔德的指引。在闪金镇的炼金术师威廉·匹斯特的帮助下，一种隐形水被调制了出来。喝下这种违禁药水后，梅贝尔就能在不被发现的情况下溜出马科伦家，在河岸边与托米·乔享受宝贵的相聚时光。"}},faq={{q="为什么梅贝尔和托米·乔不能见面？",a="马科伦和斯通菲尔德家族多年来一直怀有深仇大恨。由于两个家族都禁止双方往来，梅贝尔和托米·乔必须将他们的恋情严加保密，否则将面临家人的愤怒。",al={"家族恩怨起因","马科伦与斯通菲尔德的世仇","他们为什么不能在一起"}},{q="是什么阻碍了梅贝尔离开农场？",a="由于与斯通菲尔德家族的世仇，她的家人对她看得非常紧。她需要帮助找到一种既能见到托米·乔又不引起家人注意的方法。",al={"梅贝尔如何溜出来","艾尔文森林隐形水","她如何与托米见面"}},{q="梅贝尔在哪里与托米·乔见面？",a="托米·乔在马科伦农场和斯通菲尔德农场交界处的河岸边等待，那里避开了两个农场的直接视线。",al={"会面地点","他们在哪里见面","托米·乔在哪里"}},{q="谁在帮助梅贝尔的恋情？",a="米莱德·斯通菲尔德对这对恋人的困境表示同情，并指引热心的冒险者去找闪金镇的炼金术师威廉·匹斯特，他为他们秘密的约会提供了手段。",al={"谁在帮助梅贝尔","斯通菲尔德家族的帮助者"}}},fp="15,191,29.299.0,26.285.1,47.179.0,48.146.1,34.136.0,35.172.1"}
P.entries["npc:mebok-mizzyrix"] = {n="麦伯克·米希瑞克斯",s="麦伯克·米希瑞克斯是一位富有进取心的地精企业家，居住在棘齿城港口镇。他总是热衷于将奇异的荒野试剂转化为利润，因此经常雇佣路过的冒险者从贫瘠之地及更远的地方收集珍稀的动植物。他最著名的项目是用迅猛龙角调制一种能够增加智力的商业饮料。",h="麦伯克·米希瑞克斯是一位富有进取心的地精企业家，居住在棘齿城港口镇。他总是热衷于将奇异的荒野试剂转化为利润，因此经常雇佣路过的冒险者从贫瘠之地及更远的地方收集珍稀的动植物。他最著名的项目是用迅猛龙角调制一种能够增加智力的...",kw={"贫瘠之地","蓝叶块茎","麦伯克","米希瑞克斯","迅猛龙角","棘齿城","智慧饮料","热砂港"},ang={["faction:Alliance"]="从藏宝海湾乘船抵达中立的棘齿城，让联盟探险者无需担心敌对守卫即可接取麦伯克的任务。",["faction:Horde"]="部落旅行者在穿越贫瘠之地途经棘齿城时，可以轻松获得清理附近危险野兽的任务，从而赚取金币。",["profession:Cooking"]="鉴于麦伯克坚持酿造磨碎的迅猛龙角，追求美味的冒险者会认为他的烹饪和饮料配方充其量是有问题的。",["profession:Herbalism"]="麦伯克对蓝叶块茎等奇特标本的痴迷，展示了采集卡利姆多独特植物群落更野性、更商业化的一面。"},sec={{t="一位进取心的炼金术师",b="麦伯克·米希瑞克斯在繁忙的中立港口棘齿城经营，体现了热砂港那种不懈追逐机遇的经典精神。虽然棘齿城迎接着各色水手、海盗和商人，但麦伯克的敏锐目光却聚焦在卡利姆多的荒野上。与其挖掘普通的矿石或交易平凡的布匹，他更倾向于寻找那些他认为可以提炼成高利润药剂和商品的珍稀生物奇珍。"},{t="对智慧饮料的追求",b="麦伯克的主要商业项目是一种专有的“智慧饮料”，旨在人工提升消费者的智力。他坚信当地迅猛龙天生的狡黠和凶猛源于它们口鼻上的角，因此委托猎人们在贫瘠之地各地收集完整的迅猛龙角。对他来说，只要付钱的顾客相信这种药水有效，道德和口感都要为原始的市场潜力让路。"},{t="异国情调的试剂与植物",b="除了迅猛龙衍生的药剂外，麦伯克对其他奇异标本的需求也源源不断。从收集不稳定的深苔蜘蛛卵，到委托他人深入剃刀沼泽的荆棘丛中找回罕见的蓝叶块茎，他的追求总是将无畏的雇佣兵推向危险的境地。只要一种生物具有奇特的属性，麦伯克就确信有一种方法可以将其装瓶出售。"}},faq={{q="麦伯克·米希瑞克斯是谁？",a="麦伯克·米希瑞克斯是一位地精商人和炼金术策划者，位于贫瘠之地的中立港口城市棘齿城。他与冒险者签订契约，收集奇异的野生动物和植物部位，以支持他的商业项目。",al={"麦伯克是谁","麦伯克·米希瑞克斯背景故事","棘齿城地精麦伯克"}},{q="什么是智慧饮料？",a="智慧饮料是麦伯克·米希瑞克斯希望酿造并销售的实验性智力提升补药。他相信磨碎贫瘠之地迅猛龙的角，可以将它们的敏锐本能和狡黠传给饮用者。",al={"智慧饮料","智慧饮料任务","迅猛龙角药水"}},{q="在哪里可以找到麦伯克·米希瑞克斯？",a="他站在贫瘠之地东海岸的港口城市棘齿城的建筑物之间，部落和联盟的旅行者都可以前往。",al={"麦伯克位置","麦伯克在哪里","寻找麦伯克·米希瑞克斯"}},{q="为什么麦伯克想要迅猛龙角？",a="麦伯克推测，徘徊在贫瘠之地的迅猛龙那狡黠的智慧就集中在它们的角里。他计划将其粉碎，作为他智力增强饮料的主要活性成分。",al={"为什么需要迅猛龙角","迅猛龙角的用途","麦伯克如何处理迅猛龙角"}},{q="为什么麦伯克派人去剃刀沼泽？",a="他招募冒险者深入剃刀沼泽，利用受过训练的嗅探者挖掘蓝叶块茎，寻找这种因其有价值和不寻常的植物特性而闻名的稀有植物。",al={"为什么要去剃刀沼泽","麦伯克的剃刀沼泽任务","剃刀沼泽的蓝叶块茎"}},{q="麦伯克为部落还是联盟工作？",a="麦伯克是中立棘齿城热砂港的一名独立成员。他只忠于金币，乐于与任何阵营的成员进行交易和签订契约。",al={"麦伯克属于部落吗","麦伯克属于联盟吗","麦伯克阵营"}}},fx={["55f078f0"]={q="麦伯克·米希瑞克斯想要什么？",a="麦伯克热衷于调制稀奇古怪的新炼金药剂，尤其是他试验中的“聪明饮料”。为了完善这些古怪配方，他派冒险者搜遍贫瘠之地及其危险的深处，寻找各种奇特材料，从完整的迅猛龙角到稀有的根茎样本和蜘蛛卵。",al={"麦伯克想要什么","麦伯克需要什么","麦伯克·米希瑞克斯的目标"}},c521482b={q="麦伯克·米希瑞克斯为何在棘齿城？",a="棘齿城是雄心勃勃的地精首选的港口城镇，他们可以在此轻松获取卡利姆多的野生资源。麦伯克以这里为据点，能轻易雇用来自任意阵营、刚刚抵达的佣兵，让他们深入危险的草原，采集他实验所需的野生样本。",al={"麦伯克为何在这里","麦伯克为何在棘齿城","麦伯克·米希瑞克斯与贫瘠之地"}}},fp="14,360,25.445.0,26.443.0,25.422.0,22.219.0,22.218.0,34.159.0,33.217.0,45.176.0,46.165.0"}
P.entries["npc:melithar-staghelm"] = {n="麦利萨尔·鹿盔",s="麦利萨尔·鹿盔是一位暗夜精灵，驻扎在泰达希尔的初始林地——幽影谷中，位于奥达希尔外。他会协助年轻的暗夜精灵冒险者开启最初的训练，派遣他们去调查是什么原因让森林女神塔琳德拉回到了林地。虽然他与大德鲁伊范达尔·鹿盔拥有显赫的“鹿盔”这一姓氏，但他与这位德鲁伊领袖的确切关系尚未得到证实。",h="麦利萨尔·鹿盔是一位暗夜精灵，驻扎在泰达希尔的初始林地——幽影谷中，位于奥达希尔外。他会协助年轻的暗夜精灵冒险者开启最初的训练，派遣他们去调查是什么原因让森林女神塔琳德拉回到了林地。虽然他与大德鲁伊范达尔·鹿盔拥有显赫的...",kw={"奥达希尔","麦利萨尔","幽影谷","鹿盔","泰达希尔","训练师"},ang={["race:NightElf"]="对于在幽影谷开启旅程的暗夜精灵来说，麦利萨尔是他们离开奥达希尔庇护所后最先见到的人之一。"},sec={{t="奥达希尔的向导",b="麦利萨尔站在奥达希尔巨枝入口的正外侧，是暗夜精灵踏入世界后的早期联络人之一。作为一名倾听森林之灵低语的德鲁伊，他得知神秘的林地守护者塔琳德拉在离开多年后回到了幽影谷。麦利萨尔察觉到有些不对劲，于是派遣新手前往奥达希尔西南方寻找这位森林女神，并了解她来到林地的缘由。"},{t="鹿盔之名",b="拥有“鹿盔”这一姓氏不可避免地会引人注目，因为在大德鲁伊范达尔·鹿盔于玛法里奥·怒风消失在翡翠梦境后，便一直领导着位于达纳苏斯的塞纳里奥议会。然而，麦利萨尔并未对外夸耀过伟大的血统，也没有主动谈起过自己的家世。无论是大德鲁伊那尊贵家族的远亲，还是仅仅碰巧拥有同一个古老的卡多雷姓氏，麦利萨尔都安于在奥达希尔的根部履行着卑微的职责。"}},faq={{q="谁是麦利萨尔·鹿盔？",a="麦利萨尔·鹿盔是一位暗夜精灵任务发放者，驻扎在幽影谷中奥达希尔巨枝外的坡道上。他帮助新到来的暗夜精灵冒险者适应环境，并派遣他们去寻找森林女神塔琳德拉。",al={"麦利萨尔","谁是麦利萨尔","麦利萨尔 幽影谷"}},{q="麦利萨尔与大德鲁伊范达尔·鹿盔有亲戚关系吗？",a="他们的确切亲缘关系尚不得而知。尽管他们都姓鹿盔，但麦利萨尔从未提及自己与大德鲁伊范达尔·鹿盔或其已故的儿子瓦斯坦有任何亲属关系。目前尚不清楚他是远亲，还是仅仅共享了一个常见的卡多雷姓氏。",al={"范达尔亲戚","范达尔兄弟","鹿盔家族"}},{q="麦利萨尔对新晋冒险者扮演了什么角色？",a="麦利萨尔通过森林之灵的低语得知，林地守护者塔琳德拉在离开多年后回到了幽影谷。他派遣新手前往奥达希尔西南方寻找她，并了解她来到林地的缘由。",al={"麦利萨尔任务","麦利萨尔的作用"}},{q="我在哪里可以找到麦利萨尔·鹿盔？",a="他站在泰达希尔幽影谷中心，奥达希尔入口外的木制坡道上。",al={"麦利萨尔位置","麦利萨尔在哪里","寻找麦利萨尔·鹿盔"}}},fx={de95e555={q="麦利萨尔·鹿盔属于哪一方？",a="麦利萨尔与达纳苏斯的暗夜精灵和联盟并肩。他驻守在奥达希尔外的幽影谷，协助年轻的暗夜精灵守卫者和新兵迈出守护世界之树的第一步。",al={"麦利萨尔的阵营","麦利萨尔效忠于谁","麦利萨尔的归属"}},["67f605fc"]={q="麦利萨尔·鹿盔想要什么？",a="麦利萨尔致力于守护幽影谷，并清除泰达希尔上日益滋长的威胁。森林之灵传来的消息令他忧心：树妖塔琳德拉离开多年后又回到了林间空地。他请求新来的冒险者前去寻找她，查明发生了什么事。",al={"麦利萨尔的目标","麦利萨尔在做什么","麦利萨尔的职责"}},f95cde78={q="麦利萨尔·鹿盔为什么在这里？",a="麦利萨尔驻守在幽影谷、奥达希尔外不远处，负责守望树枝并指引初出茅庐的暗夜精灵冒险者。他为新晋守卫者提供早期指引，派他们遏制当地的腐化，维护泰达希尔圣洁的育苗地的和谐。",al={"麦利萨尔为什么在幽影谷","麦利萨尔在此处的原因"}}},fp="17,410,20.482.0,17.508.0,25.225.0,50.260.0,49.262.0,35.115.0"}
P.entries["npc:melor-stonehoof"] = {n="梅洛·石蹄",s="梅洛·石蹄是一位驻守在雷霆崖猎人高地上的资深牛头人猎手。作为狩猎之道的导师，他通过派遣部落的猎人们去追捕贫瘠之地和千针石林中最危险的捕食野兽，来考验他们的追踪技巧和勇气。",h="梅洛·石蹄是一位驻守在雷霆崖猎人高地上的资深牛头人猎手。作为狩猎之道的导师，他通过派遣部落的猎人们去追捕贫瘠之地和千针石林中最危险的捕食野兽，来考验他们的追踪技巧和勇气。",kw={"死沼","霜喉","猎人高地","狩猎之道","梅洛","塞格拉·黑刺","钢鬃","石蹄","雷霆崖"},ang={["class:Hunter"]="梅洛是部落猎人们最典型的任务发布者之一，他指引你完成体现神圣狩猎之道的追踪仪式。",["faction:Horde"]="梅洛确保整个部落的战士和追踪者都变得坚韧，能够应对那些威胁着从莫高雷到千针石林各个定居点的野生猛兽。",["race:Tauren"]="梅洛驻守在猎人高地之上，展现了你们族人对狩猎的深切敬畏，这既是对力量的考验，也是与大地母亲保持平衡的一种行为。"},sec={{t="荒野导师",b="梅洛·石蹄栖身于微风吹拂的猎人高地上，用老练的目光注视着下方的平原。狩猎之道对牛头人来说是神圣的，它与生存、精神平衡以及对大自然最强大的捕食者的尊重紧密相连。梅洛确保那些以部落之名执弓带刃的人能够理解这种平衡，并指引有前途的猎人通过挑战传奇野兽来磨练他们的技艺。"},{t="狩猎试炼",b="梅洛挑战猎人们去寻找那些恐吓荒野的传奇且难以捉摸的野兽。他指引追踪者们穿过贫瘠之地的平原，从协助十字路口的猎手塞格拉·黑刺到追捕千针石林中狡猾而凶残的鬣狗——钢鬃。通过这些试炼，猎人们证明了他们能够智胜并击败卡利姆多中部最致命的生物。"},{t="遥远之地的怪物",b="对于那些技艺已超越贫瘠之地的猎人，梅洛会为他们指明前往远方的道路。他嘱托经验丰富的猎人去猎杀拥有恐怖力量的野兽，包括潜伏在尘泥沼泽湿地中的古老鳄鱼——死沼，以及奥特兰克山脉中野蛮的雪怪——霜喉。每一次狩猎都是为了考验追踪者是否真正掌握了狩猎之道。"}},faq={{q="我在哪里可以找到梅洛·石蹄？",a="梅洛·石蹄位于雷霆崖的猎人高地上。猎人高地是牛头人主城主高地南侧的一座台地，可以通过绳桥到达。",al={"梅洛·石蹄位置","梅洛在哪里","梅洛·石蹄坐标"}},{q="梅洛·石蹄提供哪些任务？",a="梅洛提供了一系列针对中等级冒险者的狩猎挑战。其中包括指引玩家前往贫瘠之地寻找塞格拉·黑刺，猎杀凶猛的鬣狗钢鬃，以及追踪更远处的强大野兽，例如尘泥沼泽的鳄鱼死沼和奥特兰克山脉的雪怪霜喉。",al={"梅洛任务","梅洛做什么","梅洛·石蹄任务线"}},{q="梅洛为什么要派猎人去追捕钢鬃？",a="钢鬃是一只臭名昭著、狡猾凶残，在千针石林四处游荡的鬣狗。梅洛派遣有能力的猎人去追踪并击杀他，以此作为对荒野中技能、耐力和勇气的考验。",al={"为什么要杀钢鬃","钢鬃任务背景"}},{q="死沼是什么？",a="死沼是一只异常巨大且具有攻击性的鳄鱼，潜伏在尘泥沼泽的泥沼中。梅洛挑战猎人们去击杀它，作为一项展现能力的仪式。",al={"死沼是谁","死沼背景","死沼野兽"}},{q="我必须是猎人职业才能接受他的任务吗？",a="不必。虽然他的试炼代表了狩猎之道的哲学，并且对猎人职业而言很有代入感，但梅洛会将他的狩猎契约提供给任何为部落而战的有能力的冒险者。",al={"梅洛任务猎人限定吗","其他职业可以做梅洛任务吗"}},{q="塞格拉·黑刺是谁，为什么梅洛会让你去找她？",a="塞格拉·黑刺是一位驻扎在贫瘠之地十字路口的兽人猎手。梅洛将有前途的猎人引荐给她，这样他们就可以协助平定平原上桀骜不驯的野兽，并向另一位荒野老兵学习。",al={"梅洛与塞格拉的关系","塞格拉·黑刺任务"}}},fx={c4d46d44={q="梅洛·石蹄是谁？",a="梅洛·石蹄是一位备受尊敬的牛头人猎人，驻守在雷霆崖的猎人高地。他恪守狩猎传统，致力于维护平衡，指引有前途的追踪者行遍卡利姆多，让他们与这片土地上最凶猛的掠食者较量，考验他们的力量与机敏。",al={"梅洛·石蹄是谁","梅洛·石蹄的背景","梅洛是谁"}},d59647ad={q="梅洛·石蹄属于哪一方？",a="梅洛忠于牛头人部族和部落。他从雷霆崖高处为自己的族人效力，指导部落猎人，并协调各方力量，对付威胁贫瘠之地及更远处的旅人和定居点的凶猛野兽。",al={"梅洛·石蹄的阵营","梅洛是部落成员吗","梅洛·石蹄的忠诚对象"}},["2962cc83"]={q="梅洛·石蹄想要什么？",a="梅洛希望教导猎人古老的潜行、追踪和尊重猎物之道。他希望技艺精湛的追踪者通过狩猎钢牙、死水绿洲的死水鳄和冰爪熊等恶名昭彰的野兽证明自己，并与塞格拉·黑棘这样的盟友合作，考验他们的本领。",al={"梅洛·石蹄的目标","梅洛想要什么","梅洛·石蹄的职责"}},["6e964c49"]={q="梅洛·石蹄为什么在雷霆崖？",a="梅洛居住在猎人高地，这里是牛头人神射手、陷阱师和追踪者自然聚集的地方。凭借这里的视野，他能留意前来的猎人、给予指点，并派遣经受考验的战士进入荒野，守护这片土地。",al={"梅洛为什么在猎人高地","梅洛为什么在雷霆崖","梅洛·石蹄在此处的目的"}}},fp="15,283,21.435.0,18.388.0,29.374.0,33.167.0,39.333.0,44.185.0,17.157.0,52.189.0,60.225.0"}
P.entries["npc:menara-voidrender"] = {n="梅纳拉·沃伦德",s="梅纳拉·沃伦德是一位人类术士，居住在哥布林港口棘齿城。她为来自联盟和部落、心怀抱负的黑暗艺术修行者提供指导，传授她深厚的恶魔契约法器和奥术技艺知识。她身处卡利姆多的偏僻位置，使她远离了正统权威的监视。",h="梅纳拉·沃伦德是一位人类术士，居住在哥布林港口棘齿城。她为来自联盟和部落、心怀抱负的黑暗艺术修行者提供指导，传授她深厚的恶魔契约法器和奥术技艺知识。她身处卡利姆多的偏僻位置，使她远离了正统权威的监视。",kw={"贫瘠之地","血袍","恶魔学","梅纳拉","奥拉希尔","棘齿城","塔贝萨","沃伦德","术士"},ang={["class:Warlock"]="梅纳拉是卡利姆多的一位重要导师，教导两个阵营的修行者如何锻造他们的标志性附魔长袍，并将恶魔束缚到法球中。",["profession:Tailoring"]="梅纳拉将高级裁缝材料与邪能试剂相结合，编织出能够引导恶魔力量的耐用、法术编织的法衣。",["race:Human"]="远离暴风城的地下墓穴，梅纳拉代表了那些抛弃王国忠诚，在中立领土上不受阻碍地追求黑暗艺术的人类术士。"},sec={{t="棘齿城的避难所",b="当东部王国的大多数术士在潮湿的地下室或主城下的隐秘屠宰场修行时，梅纳拉·沃伦德选择了贫瘠之地的中立哥布林港口——棘齿城。由于远离了肯瑞托、暴风城卫兵或奥格瑞玛监督官的视线，她可以自由地在众目睽睽之下追求她的神秘学研究。她愿意与任何有能力的学徒打交道，无论阵营如何，这使她成为了黑暗艺术修行者之间一个罕见的共同点。"},{t="契约女巫",b="梅纳拉在资深施法者中因制造禁锢和驾驭恶魔灵魂的法球而闻名。她擅长处理复杂的试剂，引导学徒完成高难度的仪式，以锻造附魔服饰和束缚法器。她的专业名声远传至铁炉堡和幽暗城，促使艾泽拉斯各地的资深术士将他们最有前途的学生送过海洋，以寻求她的指点。"},{t="与尘泥沼泽的联系",b="梅纳拉的远方熟人中包括隐士法师塔贝萨，她独自居住在尘泥沼泽的深处。虽然塔贝萨追求的是奥术，而梅纳拉钻研的是邪能契约和恶魔学，但这两位女性有着一段久远的历史。当像奥拉希尔之球这样强大的圣物需要修复或相关专业知识时，她们共同的过去便成为了连接卡利姆多荒野的一座意想不到的桥梁。"}},faq={{q="梅纳拉·沃伦德是谁？",a="梅纳拉·沃伦德是一位人类术士，驻扎在贫瘠之地的中立港口小镇棘齿城。她担任进阶术士的导师和工匠，引导他们完成制作仪式和恶魔契约魔法。",al={"谁是梅纳拉","梅纳拉·沃伦德背景故事","棘齿城的术士是谁"}},{q="为什么一位人类术士会住在贫瘠之地？",a="棘齿城提供了中立的环境，远离了主要政府的监视。通过以哥布林经营的港口为基地，梅纳拉可以在不受圣骑士、法师或城市卫兵干涉的情况下，修行禁忌法术并指导来自联盟和部落的学生。",al={"为什么梅纳拉在棘齿城","为什么她在贫瘠之地","为什么是棘齿城术士"}},{q="梅纳拉擅长什么样的魔法？",a="梅纳拉擅长恶魔学、黑暗织物附魔以及打造旨在困住恶魔实体的容器。她特别以制造和修复束缚恶魔的法球（例如奥拉希尔之球）而闻名。",al={"梅纳拉教什么","梅纳拉·沃伦德的力量","梅纳拉擅长什么"}},{q="梅纳拉与塔贝萨有什么联系？",a="梅纳拉和隐居的法师塔贝萨有着过去的一段渊源。尽管塔贝萨隐居在尘泥沼泽并修习传统巫术，但寻求关于奥拉希尔之球知识的术士们发现，这两位女性都很了解彼此的才华。",al={"梅纳拉和塔贝萨","她怎么认识塔贝萨","塔贝萨的联系"}},{q="梅纳拉偏向联盟还是部落？",a="梅纳拉在棘齿城保持中立。她向任何证明自己有能力、且雄心勃勃到足以驾驭邪能的术士提供指导和制作任务，欢迎联盟和部落的修行者。",al={"梅纳拉是联盟还是部落","梅纳拉阵营","梅纳拉为谁工作"}},{q="她帮助制造哪些主要法器？",a="梅纳拉指导学徒编织魔化金线血袍（一件注入了恶魔力量的服装），并协助高级修行者回收和组装奥拉希尔之球的组件。",al={"梅纳拉的任务","她制造什么","魔化金线血袍梅纳拉"}}},fx={["63c53201"]={q="梅纳拉·沃伦德想要什么？",a="梅纳拉寻求教导那些展现出足够天赋与雄心、主动前来拜访的术士学徒。她专注于制作并完善专用的黑暗神器，例如束缚宝珠和附魔长袍，并依靠有能力的施法者收集完成这些物品所需的稀有而危险的材料。",al={"梅纳拉·沃伦德的目标","梅纳拉想要什么","梅纳拉·沃伦德的职责"}}},fp="17,347,19.503.0,19.441.0,17.416.1,25.230.0,45.276.0,45.232.0,39.275.0,44.214.0,42.202.0"}
P.entries["npc:merissa-stilwell"] = {n="梅里萨·斯蒂维尔",s="梅里萨·斯蒂维尔是一位居住在艾尔文森林北郡修道院的年轻人类城镇居民。她站在修道院附近，微笑着迎接并在北郡山谷受训的新手提供帮助。",h="梅里萨·斯蒂维尔是一位居住在艾尔文森林北郡修道院的年轻人类城镇居民。她站在修道院附近，微笑着迎接并在北郡山谷受训的新手提供帮助。",kw={"艾尔文","梅里萨","北郡","斯蒂维尔"},ang={["faction:Alliance"]="对于那些即将离开北郡封闭修道院的联盟新兵来说，梅里萨代表了在迪菲亚兄弟会的威胁接踵而至之前，艾尔文森林那份温暖的好客之情。"},sec={{t="北郡的迎宾面孔",b="梅里萨·斯蒂维尔站在北郡修道院，迎接来到北郡山谷的新兵。对于漫游至此的新手，她会提供简单的待客之道以及休息和定位方面的实用建议。她与王国中著名的工匠和家园守护者——例如铁匠乔丹·斯迪威尔和西部荒野的保卫者达芙妮·斯迪威尔——有着相同的姓氏，但在王国日益紧张的局势下，她依然保持着宁静的平民面貌。"}},faq={{q="梅里萨·斯蒂维尔是谁？",a="梅里萨是一位生活在艾尔文森林北郡修道院的友善人类居民，她为抵达那里的旅者提供建议和热情的欢迎。",al={"梅里萨·斯蒂维尔","梅里萨是谁","北郡的斯蒂维尔女孩"}},{q="我在哪里可以找到梅里萨·斯蒂维尔？",a="她位于艾尔文森林北郡山谷的北郡修道院。",al={"梅里萨·斯蒂维尔位置","梅里萨在哪里","寻找梅里萨"}},{q="梅里萨与王国里的其他斯蒂维尔家族成员有关系吗？",a="虽然她与铁匠乔丹·斯迪威尔和西部荒野的达芙妮·斯迪威尔等知名人物有着相同的姓氏，但她安静地生活在北郡修道院，负责迎接旅者，而不是与迪菲亚兄弟会作战或锻造刀剑。",al={"斯蒂维尔家族","达芙妮·斯迪威尔亲属","乔丹·斯迪威尔亲属"}},{q="梅里萨·斯蒂维尔提供任务吗？",a="不提供。她没有给旅者安排任何任务；她只是迎接那些路过北郡的新人。",al={"梅里萨的任务","梅里萨·斯蒂维尔任务"}}},fp="16,178,30.433.0,24.149.0,34.93.0,57.206.0,39.103.0"}
